} SRSParams;

// Define a function to initialize the dynamic array of NetworkInterfaceConfig structures
NetworkInterfaceConfig* initNetworkInterfaces(int numInterfaces, int numNeighbors, int srsPeriodicity, int srsOffset, int srsBandwidth) {
    // Allocate memory for the array of NetworkInterfaceConfig structures
    NetworkInterfaceConfig* interfaces = (NetworkInterfaceConfig*)malloc(numInterfaces * sizeof(NetworkInterfaceConfig));
    if (interfaces == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for network interface configurations\n");
        return NULL;
    }

    // Initialize each NetworkInterfaceConfig structure with a unique interface ID and an empty neighbor cell list
    for (int i = 0; i < numInterfaces; i++) {
        interfaces[i].interfaceId = i + 1;
        interfaces[i].neighborCells = NULL;
        interfaces[i].srsParams.srsPeriodicity = srsPeriodicity;
        interfaces[i].srsParams.srsOffset = srsOffset;
        interfaces[i].srsParams.srsBandwidth = srsBandwidth;
    }

    // Allocate memory for the neighbor cell list and populate it with a specified number of entries
    for (int i = 0; i < numInterfaces; i++) {
        interfaces[i].neighborCells = (NeighborCellInfo*)malloc(numNeighbors * sizeof(NeighborCellInfo));
        if (interfaces[i].neighborCells == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for neighbor cell list\n");
            return NULL;
        }

        // Ensure no duplicate neighbor IDs are generated and correctly configure the SRS parameters based on a predefined template
        int j = 0;
        while (j < numNeighbors) {
            interfaces[i].neighborCells[j].cellId = j + 1;
            interfaces[i].neighborCells[j].cellName = "Cell";
            interfaces[i].neighborCells[j].signalStrength = 0.0f;
            interfaces[i].neighborCells[j].isConnected = false;
            j++;
        }
    }

    // Handle memory allocation efficiently to avoid leaks and ensure thread safety when accessing shared resources
    pthread_mutex_t* mutex = (pthread_mutex_t*)malloc(sizeof(pthread_mutex_t));
    if (mutex == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for mutex\n");
        return NULL;
    }
    pthread_mutex_init(mutex, NULL);

    // Support real-time updates to neighbor cell information from an external data source
    NetworkInterfaceConfig* latestInterfaces = interfaces;
    while (true) {
        // Acquire the lock on the mutex
        pthread_mutex_lock(mutex);

        // Check if there are any updates to the network interface configurations
        bool hasUpdates = false;
        for (int i = 0; i < numInterfaces; i++) {
            if (interfaces[i].neighborCells != latestInterfaces[i].neighborCells) {
                hasUpdates = true;
                break;
            }
        }

        // If there are no updates, release the lock and continue with normal processing
        if (!hasUpdates) {
            pthread_mutex_unlock(mutex);
            continue;
        }

        // Update the network interface configurations based on the latest data
        for (int i = 0; i < numInterfaces; i++) {
            interfaces[i].neighborCells = latestInterfaces[i].neighborCells;
        }

        // Release the lock and continue with normal processing
        pthread_mutex_unlock(mutex);
    }

    return interfaces;
}
