// Define constants for command line options and delimiter
#define OPT_MANPAGE 'm'
#define OPT_CONFIG 'c'
#define OPT_OUTPUT 'o'
#define OPT_DELIMITER 'd'
#define OPT_LOG_PATH 'l'
#define OPT_MAX_LOG_SIZE 1024 * 1024 * 10 // 10 MB
#define DELIM_NEWLINE '\n'

// Define structure for thread-safe logging
typedef struct {
    int fd;
    char* path;
} LogFile;

// Function to handle signal for clean exit
void sigint_handler(int signum) {
    printf("Exiting...\n");
    exit(signum);
}

// Function to initialize logging file
void init_logfile(LogFile* logfile, char* path) {
    logfile->path = path;
    logfile->fd = open(path, O_CREAT | O_RDWR | O_APPEND, 0644);
}

// Function to write to logging file
void log_message(LogFile* logfile, char* message) {
    if (logfile != NULL && logfile->fd >= 0) {
        write(logfile->fd, message, strlen(message));
    }
}

// Function to close logging file
void close_logfile(LogFile* logfile) {
    if (logfile != NULL && logfile->fd >= 0) {
        close(logfile->fd);
    }
}

// Function to read input file line by line and count lines
int count_lines(char* filename, char delimiter) {
    int fd = open(filename, O_RDONLY);
    if (fd < 0) {
        perror("Error opening input file");
        return -1;
    }

    // Initialize variables for counting lines and reading file
    size_t line_count = 0;
    char buffer[BUFSIZ];
    ssize_t bytes_read;

    // Read file line by line and increment line count
    while ((bytes_read = read(fd, buffer, BUFSIZ)) > 0) {
        for (int i = 0; i < bytes_read; i++) {
            if (buffer[i] == delimiter) {
                line_count++;
            }
        }
    }

    // Clean up and return line count
    close(fd);
    return line_count;
}

// Function to parse command line arguments and handle options
void parse_args(int argc, char** argv) {
    // Define variables for parsing command line arguments
    int opt;
    char* output_file = NULL;
    char* config_file = NULL;
    char delimiter = DELIM_NEWLINE;
    LogFile logfile = { -1 };

    // Parse command line arguments and handle options
    while ((opt = getopt(argc, argv, "m:c:d:o:l:")) != -1) {
        switch (opt) {
            case OPT_MANPAGE:
                printf("Usage: %s [-m] [-c <config file>] [-d <delimiter>] [-o <output file>] [-l <log file>]\n", argv[0]);
                exit(EXIT_SUCCESS);
            case OPT_CONFIG:
                config_file = optarg;
                break;
            case OPT_DELIMITER:
                delimiter = (char)strtol(optarg, NULL, 10);
                break;
            case OPT_OUTPUT:
                output_file = optarg;
                break;
            case OPT_LOG_PATH:
                init_logfile(&logfile, optarg);
                break;
        }
    }

    // Handle input file
    if (optind < argc) {
        char* filename = argv[optind];

        // Count lines in input file
        int line_count = count_lines(filename, delimiter);

        // Write output to log file and stdout
        log_message(&logfile, "Processed ");
        log_message(&logfile, filename);
        log_message(&logfile, " with ");
        log_message(&logfile, line_count);
        log_message(&logfile, " lines");
        printf("Processed %s with %d lines\n", filename, line_count);

        // Close log file if necessary
        if (output_file != NULL) {
            close_logfile(&logfile);
        }
    } else {
        // Print usage information if no input file is specified
        printf("Usage: %s [-m] [-c <config file>] [-d <delimiter>] [-o <output file>] [-l <log file>]\n", argv[0]);
    }
}

// Main function to execute program
int main(int argc, char** argv) {
    // Register signal handler for clean exit
    signal(SIGINT, sigint_handler);

    // Parse command line arguments and handle options
    parse_args(argc, argv);

    return 0;
}
