#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <limits.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <fcntl.h>
#include <zlib.h>

#define BUFFER_SIZE 4096 // Default buffer size for file read operations
#define MAX_RULES 1024 // Maximum number of transformation rules to parse
#define MIN_CHUNK_SIZE 512 // Minimum chunk size for reading input files
#define DEFAULT_COMPRESSION_ALGORITHM "gzip" // Default compression algorithm (gzip)

// Define a struct to hold the transformation rules and their parameters
typedef struct {
    char *rule;
    int param1;
    int param2;
} TransformationRule;

int process_file(char *input_file, char *output_file, char *rules, size_t chunk_size, char *compression_algorithm) {
    // Initialize variables and error codes
    int err = 0;
    long file_size = 0;
    struct stat st;
    FILE *input_fp = NULL, *output_fp = NULL;
    TransformationRule *rules_arr = NULL;
    size_t rules_len = 0;
    char *compressed_data = NULL;
    char *chunk_buffer = malloc(BUFFER_SIZE);

    // Check input parameters and parse transformation rules
    if (!input_file || !output_file || !rules || chunk_size < MIN_CHUNK_SIZE) {
        err = 1;
        goto cleanup;
    }

    // Open the input file and get its size
    if ((err = stat(input_file, &st)) == -1) {
        fprintf(stderr, "Failed to get file size: %s\n", strerror(errno));
        goto cleanup;
    }
    file_size = st.st_size;
    if ((input_fp = fopen(input_file, "rb")) == NULL) {
        fprintf(stderr, "Failed to open input file: %s\n", strerror(errno));
        goto cleanup;
    }

    // Open the output file and initialize compression algorithm if necessary
    if ((output_fp = fopen(output_file, "wb")) == NULL) {
        fprintf(stderr, "Failed to open output file: %s\n", strerror(errno));
        goto cleanup;
    }
    if (strcmp(compression_algorithm, "none") != 0 &&
            (compressed_data = malloc(BUFFER_SIZE)) == NULL) {
        fprintf(stderr, "Failed to allocate memory for compression buffer\n");
        goto cleanup;
    }

    // Parse the transformation rules and initialize the array of structs
    if ((rules_arr = parse_rules(rules, &rules_len)) == NULL) {
        fprintf(stderr, "Failed to parse transformation rules\n");
        goto cleanup;
    }

    // Read input file in chunks and apply transformation rules
    while (file_size > 0 && !err) {
        size_t chunk_read = fread(chunk_buffer, sizeof(char), BUFFER_SIZE, input_fp);
        if (chunk_read < BUFFER_SIZE && ferror(input_fp)) {
            fprintf(stderr, "Failed to read file: %s\n", strerror(errno));
            err = 1;
            break;
        } else {
            // Apply transformation rules and compress data if necessary
            apply_rules(chunk_buffer, chunk_read, rules_arr, rules_len, compressed_data);
            file_size -= chunk_read;
        }
    }

    // Write transformed data to output file
    if (!err && write_output(output_fp, compressed_data) == -1) {
        fprintf(stderr, "Failed to write output file: %s\n", strerror(errno));
        err = 1;
    }

cleanup:
    // Clean up resources and return error code
    if (input_fp != NULL && fclose(input_fp) == EOF) {
        fprintf(stderr, "Failed to close input file: %s\n", strerror(errno));
    }
    if (output_fp != NULL && fclose(output_fp) == EOF) {
        fprintf(stderr, "Failed to close output file: %s\n", strerror(errno));
    }
    free(chunk_buffer);
    free(rules_arr);
    free(compressed_data);
    return err;
}

// Parse the transformation rules and initialize an array of structs
TransformationRule *parse_rules(char *rules, size_t *len) {
    // Define a function to parse a single rule and add it to the array
    TransformationRule *rule = malloc(sizeof(TransformationRule));
    if (!rule) {
        fprintf(stderr, "Failed to allocate memory for transformation rule\n");
        return NULL;
    }
    char *rule_string = strtok(rules, ";"); // Separate rules by semicolon
    while (rule_string && !err) {
        // Parse the rule string and extract parameters if necessary
        sscanf(rule_string, "%s %d %d", rule->rule, &rule->param1, &rule->param2);
        // Add the rule to the array and move on to the next one
        if (*len < MAX_RULES) {
            rules_arr[*len] = *rule;
            ++(*len);
        } else {
            fprintf(stderr, "Too many transformation rules\n");
            err = 1;
        }
        rule = malloc(sizeof(TransformationRule)); // Create a new struct for the next rule
    }
    if (rule) free(rule);
    return rules_arr;
}

// Apply the specified transformation rules to the input data
void apply_rules(char *input, size_t len, TransformationRule *rules, size_t len, char *output) {
    // Define a function to apply a single rule and update the output buffer
    for (size_t i = 0; i < len; ++i) {
        if (!strcmp(rules[i].rule, "reverse")) { // Reverse the input string
            reverse_string(input);
            strcpy(output, input);
        } else if (!strcmp(rules[i].rule, "uppercase")) { // Convert to uppercase
            for (size_t j = 0; j < len; ++j) {
                output[j] = toupper(input[j]);
            }
        } else if (!strcmp(rules[i].rule, "lowercase")) { // Convert to lowercase
            for (size_t j = 0; j < len; ++j) {
                output[j] = tolower(input[j]);
            }
        } else if (!strcmp(rules[i].rule, "rotate")) { // Rotate the input string
            rotate_string(input);
            strcpy(output, input);
        }
    }
}

// Reverse the input string and update the output buffer
void reverse_string(char *input) {
    size_t len = strlen(input);
    char *reverse = malloc(len + 1);
    if (!reverse) {
        fprintf(stderr, "Failed to allocate memory for reversed string\n");
        return;
    }
    reverse[len] = '\0';
    size_t i = len - 1;
    while (i >= 0) {
        reverse[len - i - 1] = input[i];
        --i;
    }
    strcpy(input, reverse);
    free(reverse);
}

// Rotate the input string and update the output buffer
void rotate_string(char *input) {
    size_t len = strlen(input);
    char *rotate = malloc(len + 1);
    if (!rotate) {
        fprintf(stderr, "Failed to allocate memory for rotated string\n");
        return;
    }
    rotate[len] = '\0';
    size_t i = len - 1;
    while (i >= 0) {
        rotate[len - i - 1] = input[i];
        --i;
    }
    strcpy(input, rotate);
    free(rotate);
}

// Write the transformed data to the output file
int write_output(FILE *fp, char *data) {
    if (fwrite(data, sizeof(char), strlen(data), fp) != strlen(data)) {
        return -1;
    } else {
        return 0;
    }
}
