        line->num_fields = num_fields;
    }
    fclose(file);

    // Iterate over lines and calculate averages for each hostname
    int i, j;
    struct hostname *hostname;
    double average;
    for (i = 0; i < num_lines; ++i) {
        line = &lines[i];
        for (j = 0; j < line->num_fields; ++j) {
            if (strcmp(line->fields[j], "hostname") == 0) {
                hostname = find_hostname(line->fields[j+1]);
                if (!hostname) {
                    printf("Invalid hostname: %s\n", line->fields[j+1]);
                    return 1;
                }
            } else if (strcmp(line->fields[j], "average") == 0) {
                average = calculate_average(line, j);
                if (isnan(average)) {
                    printf("Error calculating average: %s\n", line->fields[j+1]);
                    return 1;
                }
            }
        }
        // Handle memory leaks and performance optimizations
    }

    // Clean up resources and exit
    for (i = 0; i < num_lines; ++i) {
        line = &lines[i];
        free(line->fields);
    }
    free(lines);
    return 0;
}

// Parse configuration file and initialize hostnames array
struct config parse_config(char *filename) {
    struct config config;
    // Open file for reading
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("fopen");
        return NULL;
    }

    // Read hostnames and filtering criteria from file
    char buffer[MAX_LINE_LEN];
    while (fgets(buffer, MAX_LINE_LEN, file)) {
        if (!parse_line(buffer, &config)) {
            printf("Error parsing configuration: %s\n", buffer);
            return NULL;
        }
    }
    fclose(file);
    return config;
}

// Parse a single line of the configuration file and update config struct
int parse_line(char *buffer, struct config *config) {
    // Tokenize input and parse fields
    char **fields = malloc(sizeof(char *) * MAX_NUM_FIELDS);
    int num_fields = tokenize(buffer, &fields);
    if (num_fields < 0) {
        free(fields);
        return -1;
    }

    // Process filtering criteria
    for (int i = 0; i < num_fields; ++i) {
        if (strcmp(fields[i], "hostname") == 0) {
            config->hostnames[config->num_hostnames++] = malloc(sizeof(struct hostname));
            config->hostnames[config->num_hostnames-1]->hostname = fields[i+1];
        } else if (strcmp(fields[i], "average") == 0) {
            config->filtering_criteria[i] = atof(fields[i+1]);
        }
    }
    free(fields);
    return num_fields;
}

// Find hostname in configuration and initialize DNS resolution library
struct hostname *find_hostname(char *hostname) {
    for (int i = 0; i < config.num_hostnames; ++i) {
        if (strcmp(config.hostnames[i]->hostname, hostname) == 0) {
            return config.hostnames[i];
        }
    }
    return NULL;
}

// Calculate average of last two numeric fields in a line
double calculate_average(struct line *line, int field_index) {
    double sum = 0;
    for (int i = field_index - 1; i < field_index + 2; ++i) {
        if (!isdigit(line->fields[i][0])) {
            return NAN;
        }
        sum += atof(line->fields[i]);
    }
    return sum / 3;
}

// Tokenize input and parse fields
int tokenize(char *buffer, char ***fields) {
    int num_fields = 0;
    char **tokens = malloc(sizeof(char *) * MAX_NUM_FIELDS);
    while (*buffer != '\0') {
        if (strlen(*buffer) > 0) {
            tokens[num_fields++] = strdup(*buffer);
        }
        ++buffer;
    }
    *fields = malloc(sizeof(char *) * num_fields);
    memcpy(*fields, tokens, sizeof(char *) * num_fields);
    free(tokens);
    return num_fields;
}
