// Function to read a list of integers from standard input, validate them for positive values, and store them in a dynamically allocated array
void read_integers(Integer** integers, int* count) {
    // Initialize the dynamic array with an initial size of 8 elements
    *integers = (Integer*)malloc(INITIAL_ARRAY_SIZE * sizeof(Integer));
    *count = INITIAL_ARRAY_SIZE;

    // Read input from standard input until end-of-file is reached
