            // Handle invalid input by ignoring the current line and continuing with the next one
            continue;
        }

        // Check if the dynamic array needs to be resized
        if (*count >= *integers_count) {
            // Reallocate memory for the dynamic array with an additional 8 elements
            *integers = (Integer*)realloc(*integers, (*integers_count + 8) * sizeof(Integer));
            *count += 8;
        }

        // Store the validated integer in the dynamic array
        (*integers)[*count - 1].value = value;
        (*integers)[*count - 1].is_valid = true;
    }
}

// Function to find and print the largest integer in the array, handling the case where the array is empty
void print_largest_integer(Integer** integers, int count) {
