        // Handle the case where the array is empty by printing an error message
        printf("The array is empty\n");
        return;
    }

    // Initialize the largest integer to the first element of the dynamic array
    int largest = (*integers)[0].value;

    // Iterate over the remaining elements of the dynamic array and find the largest value
    for (int i = 1; i < count; ++i) {
        if ((*integers)[i].value > largest) {
            largest = (*integers)[i].value;
        }
    }

    // Print the largest integer in the array
    printf("The largest integer is %d\n", largest);
}

// Main function to demonstrate the use of the read_integers and print_largest_integer functions
int main() {
    Integer* integers = NULL;
    int count = 0;

    // Read a list of integers from standard input, validate them for positive values, and store them in a dynamically allocated array
    read_integers(&integers, &count);

    // Find and print the largest integer in the array
    print_largest_integer(integers, count);

    // Free the memory allocated for the dynamic array
    free(integers);

    return 0;
}
