#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <openssl/aes.h>
#include <openssl/chacha.h>
#include <openssl/poly1305.h>
#include <openssl/gcm.h>

// Define the different cipher modes supported by the service
enum CipherMode { AES_128_CBC, AES_256_GCM, ChaCha20_Poly1305 };

// Define the key types that can be used for encryption/decryption
enum KeyType { Symmetric, Asymmetric };

// Define the authentication requirements that can be applied to the cipher
enum AuthRequirements { None, Authentication };

// Structure to hold the configuration options for the service
struct ConfigOptions {
  // The mode of encryption/decryption to use (e.g. AES-128-CBC)
  enum CipherMode mode;

  // The key type to be used (symmetric or asymmetric)
  enum KeyType keyType;

  // The authentication requirements to apply to the cipher
  enum AuthRequirements authRequirements;
};

// Structure to hold the key information for encryption/decryption
struct Key {
  // The actual key data (e.g. AES key, RSA private key)
  unsigned char *data;

  // The length of the key in bytes
  size_t len;
};

// Function to encrypt a message using the given cipher and key
int encrypt(const unsigned char *message, const struct Key *key, enum CipherMode mode, size_t *encryptedLen) {
  // Check if the input parameters are valid
  if (!message || !key || !encryptedLen) {
    return -1;
  }

  // Allocate memory for the encrypted message
  unsigned char *encrypted = malloc(strlen((const char *)message) + 1);
  if (!encrypted) {
    return -2;
  }

  // Initialize the cipher and set it to the appropriate mode
  EVP_CIPHER_CTX *ctx;
  switch (mode) {
    case AES_128_CBC:
      ctx = EVP_CIPHER_CTX_new();
      if (!ctx) {
        return -3;
      }
      if (EVP_EncryptInit_ex(ctx, EVP_aes_128_cbc(), NULL, key->data, NULL)) {
        return -4;
      }
      break;
    case AES_256_GCM:
      ctx = EVP_CIPHER_CTX_new();
      if (!ctx) {
        return -3;
      }
      if (EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key->data, NULL)) {
        return -4;
      }
      break;
    case ChaCha20_Poly1305:
      ctx = EVP_CIPHER_CTX_new();
      if (!ctx) {
        return -3;
      }
      if (EVP_EncryptInit_ex(ctx, EVP_chacha20_poly1305(), NULL, key->data, NULL)) {
        return -4;
      }
      break;
  }

  // Set the input and output buffers for the encryption operation
  unsigned char *in = (unsigned char *)message;
  int inLen = strlen((const char *)message);
  unsigned char *out = encrypted;
  int outLen = strlen((const char *)encrypted);

  // Perform the encryption operation
  if (!EVP_EncryptUpdate(ctx, out, &outLen, in, inLen)) {
    return -5;
  }

  // Set the output length to be the same as the input length
  *encryptedLen = inLen;

  // Free the cipher context and return
  EVP_CIPHER_CTX_free(ctx);
  return 0;
}

// Function to decrypt a message using the given cipher and key
int decrypt(const unsigned char *encrypted, const struct Key *key, enum CipherMode mode, size_t *decryptedLen) {
  // Check if the input parameters are valid
  if (!encrypted || !key || !decryptedLen) {
    return -1;
  }

  // Allocate memory for the decrypted message
  unsigned char *decrypted = malloc(strlen((const char *)encrypted) + 1);
  if (!decrypted) {
    return -2;
  }

  // Initialize the cipher and set it to the appropriate mode
  EVP_CIPHER_CTX *ctx;
  switch (mode) {
    case AES_128_CBC:
      ctx = EVP_CIPHER_CTX_new();
      if (!ctx) {
        return -3;
      }
      if (EVP_DecryptInit_ex(ctx, EVP_aes_128_cbc(), NULL, key->data, NULL)) {
        return -4;
      }
      break;
    case AES_256_GCM:
      ctx = EVP_CIPHER_CTX_new();
      if (!ctx) {
        return -3;
      }
      if (EVP_DecryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key->data, NULL)) {
        return -4;
      }
      break;
    case ChaCha20_Poly1305:
      ctx = EVP_CIPHER_CTX_new();
      if (!ctx) {
        return -3;
      }
      if (EVP_DecryptInit_ex(ctx, EVP_chacha20_poly1305(), NULL, key->data, NULL)) {
        return -4;
      }
      break;
  }

  // Set the input and output buffers for the decryption operation
  unsigned char *in = (unsigned char *)encrypted;
  int inLen = strlen((const char *)encrypted);
  unsigned char *out = decrypted;
  int outLen = strlen((const char *)decrypted);

  // Perform the decryption operation
  if (!EVP_DecryptUpdate(ctx, out, &outLen, in, inLen)) {
    return -5;
  }

  // Set the output length to be the same as the input length
  *decryptedLen = inLen;

  // Free the cipher context and return
  EVP_CIPHER_CTX_free(ctx);
  return 0;
}

// Function to generate a new symmetric key for encryption/decryption
struct Key generateKey(enum CipherMode mode) {
  // Allocate memory for the key data
  unsigned char *keyData = malloc(mode == AES_128 ? 16 : (mode == AES_256 ? 32 : 32));
  if (!keyData) {
    return NULL;
  }

  // Initialize the key data with random values
  RAND_bytes(keyData, mode == AES_128 ? 16 : (mode == AES_256 ? 32 : 32));

  // Return the new key structure
  struct Key key;
  key.data = keyData;
  return key;
}

// Function to free a symmetric key for encryption/decryption
void freeKey(struct Key *key) {
  if (key != NULL && key->data != NULL) {
    OPENSSL_free(key->data);
  }
}
