        return new PokemonDetails();
    }

    private static String getPrimaryWeakness(String pokemonType) {
        // Determine the primary weakness of the Pokemon based on its type
        // and the predefined mapping of types and their associated weaknesses.
        if (typeWeaknesses.containsKey(pokemonType)) {
            return typeWeaknesses.get(pokemonType);
        } else {
            return "";
        }
    }

    private static List<String> getSecondaryWeaknesses(String pokemonType) {
        // Determine the secondary weaknesses of the Pokemon based on its type
        // and the predefined mapping of types and their associated weaknesses.
        if (typeResistances.containsKey(pokemonType)) {
            return typeResistances.get(pokemonType);
        } else {
