        return NULL;
    }

    // decrypt input string using key and configuration
    char* decrypted_string = decryptString(input->input_string, key, config);
    if (!decrypted_string) {
        printf("Failed to decrypt input string\n");
        free(key);
        free(config);
        return NULL;
    }

    // prepare output data structure
    OutputData* output = (OutputData*)malloc(sizeof(OutputData));
    if (!output) {
        printf("Failed to allocate memory for output\n");
        free(key);
        free(config);
        return NULL;
    }
    output->thread_id = input->thread_id;
    output->output_string = decrypted_string;

    // release resources
    free(key);
    free(config);

    return (void*)output;
}

int main() {
    pthread_t threads[NUM_THREADS];
    InputData* input_data[NUM_THREADS];
    OutputData* output_data[NUM_THREADS];
    int i;

    // initialize input data for each thread
    for (i = 0; i < NUM_THREADS; i++) {
        input_data[i] = (InputData*)malloc(sizeof(InputData));
        if (!input_data[i]) {
            printf("Failed to allocate memory for input data\n");
            return -1;
        }
        input_data[i]->thread_id = i;
        input_data[i]->input_string = "hello world"; // replace with actual input string
    }

    // create threads for encryption and decryption
    for (i = 0; i < NUM_THREADS / 2; i++) {
        pthread_create(&threads[i], NULL, encrypt, input_data[i]);
        pthread_create(&threads[i + NUM_THREADS/2], NULL, decrypt, input_data[i + NUM_THREADS/2]);
    }

    // wait for threads to finish and retrieve output data
    for (i = 0; i < NUM_THREADS / 2; i++) {
        pthread_join(threads[i], (void**)&output_data[i]);
        pthread_join(threads[i + NUM_THREADS/2], (void**)&output_data[i + NUM_THREADS/2]);
    }

    // print output data
    for (i = 0; i < NUM_THREADS; i++) {
        printf("Thread %d: %s\n", output_data[i]->thread_id, output_data[i]->output_string);
        free(output_data[i]);
    }

    return 0;
}
