#include <boost/asio.hpp>
#include <boost/bind.hpp>
#include <boost/thread.hpp>
#include <iostream>
#include <vector>
#include <string>
#include <random>
#include <fstream>
#include <sstream>
#include <cstdlib>

using namespace boost::asio;
using namespace std;

class SandeshClient {
public:
    SandeshClient(const string& server_ip, const string& server_port) : io_service(), resolver(io_service), socket(io_service), deadline(io_service), timer(io_service), num_requests(0), packet_loss_percentage(0), request_volume(10000), test_duration(60) {
        // Initialize the random number engine and distribution for packet loss simulation
        rng = make_unique<mt19937>(random_device()());
        uniform_int_distribution<int> dist(0, 100);

        // Set the default values for the variables
        this->server_ip = server_ip;
        this->server_port = server_port;
        this->packet_loss_percentage = 0;
        this->request_volume = 10000;
        this->test_duration = 60;
    }

    void run() {
        // Start the timer for the test duration
        deadline.expires_from_now(chrono::seconds(test_duration));
        deadline.async_wait(bind(&SandeshClient::handle_timeout, this, placeholders::error));

        // Start the thread pool for handling requests
        io_service.run();
    }

private:
    void handle_timeout(const boost::system::error_code& error) {
        if (error) {
            cerr << "Timer error: " << error.message() << endl;
            return;
        }

        // Print the results at the end of the test period
        cout << "Total requests: " << num_requests << endl;
        cout << "Successful requests: " << successful_requests << endl;
        cout << "Failed requests: " << failed_requests << endl;
        cout << "Average response time: " << average_response_time << " ms" << endl;

        // Stop the io_service and thread pool
        io_service.stop();
    }

    void handle_request(const boost::system::error_code& error, size_t bytes_transferred) {
        if (error) {
            cerr << "Request error: " << error.message() << endl;
            return;
        }

        // Increment the number of requests and successful/failed requests counters
        num_requests++;
        if (error.value() == 0) {
            successful_requests++;
            average_response_time += chrono::duration<double>(chrono::high_resolution_clock::now() - start_time).count();
        } else {
            failed_requests++;
        }

        // Simulate network latency and packet loss for the next request
        double r = dist(*rng);
        if (r <= packet_loss_percentage) {
            socket.close();
        } else {
            start_time = chrono::high_resolution_clock::now();
            resolver.async_resolve(server_ip, server_port, bind(&SandeshClient::handle_resolve, this, placeholders::error, placeholders::iterator));
        }
    }

    void handle_resolve(const boost::system::error_code& error, ip::tcp::resolver::iterator endpoint_iterator) {
        if (error) {
            cerr << "Resolve error: " << error.message() << endl;
            return;
        }

        // Create the socket and establish a connection to the server
        socket = io_service.socket(ip::tcp::v4(), ip::tcp::socket::non_blocking);
        socket.async_connect(*endpoint_iterator, bind(&SandeshClient::handle_connect, this, placeholders::error));
    }

    void handle_connect(const boost::system::error_code& error) {
        if (error) {
            cerr << "Connect error: " << error.message() << endl;
            return;
        }

        // Send a GET request to the server
        string request = "GET / HTTP/1.0\r\nHost: www.example.com\r\nConnection: close\r\n\r\n";
        socket.async_send(buffer(request), bind(&SandeshClient::handle_send, this, placeholders::error));
    }

    void handle_send(const boost::system::error_code& error) {
        if (error) {
            cerr << "Send error: " << error.message() << endl;
            return;
        }

        // Receive the response from the server
        socket.async_receive(buffer(response), bind(&SandeshClient::handle_receive, this, placeholders::error));
    }

    void handle_receive(const boost::system::error_code& error) {
        if (error && error != boost::asio::error::eof) {
            cerr << "Receive error: " << error.message() << endl;
            return;
        }

        // Print the response from the server
        cout << "Response: " << response << endl;

        // Close the socket and schedule the next request
        socket.close();
        start_time = chrono::high_resolution_clock::now();
        resolver.async_resolve(server_ip, server_port, bind(&SandeshClient::handle_resolve, this, placeholders::error, placeholders::iterator));
    }

private:
    io_service io_service;
    ip::tcp::resolver resolver;
    ip::tcp::socket socket;
    deadline_timer deadline;
    steady_clock::time_point start_time;
    string server_ip;
    string server_port;
    int num_requests = 0;
    int successful_requests = 0;
    int failed_requests = 0;
    double average_response_time = 0;
    unique_ptr<mt19937> rng;
    uniform_int_distribution<int> dist;
    int packet_loss_percentage;
    int request_volume;
    int test_duration;
    string response;
};

int main(int argc, char* argv[]) {
    if (argc < 4) {
        cerr << "Usage: " << argv[0] << " <server IP> <server port> <packet loss percentage>" << endl;
        return 1;
    }

    string server_ip = argv[1];
    string server_port = argv[2];
    int packet_loss_percentage = stoi(argv[3]);

    // Create the client object and start the requests
    cout << "Starting client with " << server_ip << ":" << server_port << " and " << packet_loss_percentage << "% packet loss" << endl;
    try {
        auto client = make_unique<SandeshClient>(server_ip, server_port);
        client->set_packet_loss_percentage(packet_loss_percentage);
        client->start();
    } catch (exception& e) {
        cerr << "Error creating client: " << e.what() << endl;
    }

    return 0;
}']

