namespace Logging {
    class Logger {
    public:
        Logger();
        ~Logger();

        // Setup logging system
        void init(std::string log_file, int max_size, int max_files);

        // Log different levels of messages
        void debug(std::string message);
        void info(std::string message);
        void warning(std::string message);
        void error(std::string message);
        void critical(std::string message);

    private:
        std::ofstream log_file;
        std::mutex mtx;
        int max_size;
        int max_files;
        std::vector<std::string> log_messages;

        // Thread-safe log writing function
        void write(std::string message);
    };
}

// Constructor for the Logger class
Logging::Logger::Logger() {}

// Destructor for the Logger class
Logging::Logger::~Logger() {}

void Logging::Logger::init(std::string log_file, int max_size, int max_files) {
    // Setup logging system
    this->log_file = std::ofstream(log_file);
    this->max_size = max_size;
    this->max_files = max_files;
}

void Logging::Logger::write(std::string message) {
    // Write log message to file
    std::lock_guard<std::mutex> lock(mtx);
    log_file << message << std::endl;
}

// Log different levels of messages
void Logging::Logger::debug(std::string message) { write("DEBUG: " + message); }
void Logging::Logger::info(std::string message) { write("INFO: " + message); }
void Logging::Logger::warning(std::string message) { write("WARNING: " + message); }
void Logging::Logger::error(std::string message) { write("ERROR: " + message); }
void Logging::Logger::critical(std::string message) { write("CRITICAL: " + message); }
```
