    {
        var parser = new XmlParser(filePath);
        var config = await parser.ParseAsync();

        foreach (var obj in config.GameObjects)
        {
            _gameObjects.Add(new GameObject(obj.Name, obj.Position));
        }

        foreach (var level in config.Levels)
        {
