function validateUpdate(update) {
  const updateFields = Object.keys(update);
  return updateFields.every((f) => whitelist.includes(f));
}

// Define a function to create a new version of a resource
function createNewVersion(resource, update) {
  const updatedResource = { ...resource };
  updateFields.forEach((f) => updatedResource[f] = update[f]);
  return updatedResource;
}

// Define a function to handle concurrent updates and resolve conflicts
function handleConcurrentUpdates(existingResource, update) {
  // Check if the update is for a different version than the existing resource
  if (update.version !== existingResource.version) {
    throw new Error("Conflict: Update is for an older version of the resource");
  }

  // Create a new version of the resource with the updated fields
  const updatedResource = createNewVersion(existingResource, update);

  // Log the conflict and provide feedback to the client
  logConflict(updatedResource.id, updatedResource.version, existingResource.version);

  // Return the updated resource with the new version number
  return { ...updatedResource, version: updatedResource.version + 1 };
}

