import java.util.concurrent.Executors;

public class StringProcessing {
    private static final int MAX_CONCURRENT_THREADS = 10;

    public void processStrings(String filePath) throws IOException {
        // Create an executor service to manage concurrent threads
        ExecutorService executor = Executors.newFixedThreadPool(MAX_CONCURRENT_THREADS);

        try (BufferedReader reader = new BufferedReader(new FileReader(filePath, StandardCharsets.UTF_8))) {
            List<String> stringList = new ArrayList<>();

            String line;
            while ((line = reader.readLine()) != null) {
                stringList.add(line);
            }

            // Create a list of tasks to process the strings in parallel
            List<ProcessStringTask> taskList = new ArrayList<>();
            for (int i = 0; i < stringList.size(); i++) {
                String currentString = stringList.get(i);
                ProcessStringTask task = new ProcessStringTask(currentString);
                taskList.add(task);
            }

            // Submit the tasks to the executor service and wait for them to complete
            executor.invokeAll(taskList);
        } catch (IOException e) {
            // Handle any errors that occur during processing
        } finally {
            executor.shutdown();
        }
    }
}

