<?php
function userAccountManagement($_REQUEST) {
  // Prepare the database connection and schema
  $db = new PDO('mysql:host=localhost;dbname=mydatabase', 'username', 'password');
  $db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

  // Validate the input data
  if (!isset($_REQUEST['name']) || empty($_REQUEST['name'])) {
    return jsonResponse('error', 'Missing name');
  }
  if (!isset($_REQUEST['email']) || !filter_var($_REQUEST['email'], FILTER_VALIDATE_EMAIL)) {
    return jsonResponse('error', 'Invalid email address');
  }
  if (!isset($_REQUEST['password'])) {
    return jsonResponse('error', 'Missing password');
  }

  // Handle sub-actions (update, delete, import)
  if (isset($_REQUEST['sub_action'])) {
    $subAction = $_REQUEST['sub_action'];
    if ($subAction === 'update') {
      // Update user profile
      $stmt = $db->prepare('UPDATE users SET name=:name, email=:email, password=:password WHERE id=:id');
      $stmt->bindParam(':name', $_REQUEST['name']);
      $stmt->bindParam(':email', $_REQUEST['email']);
      $stmt->bindParam(':password', $_REQUEST['password']);
      $stmt->bindParam(':id', $_REQUEST['id']);
      $stmt->execute();
    } elseif ($subAction === 'delete') {
      // Delete user account
      $stmt = $db->prepare('DELETE FROM users WHERE id=:id');
      $stmt->bindParam(':id', $_REQUEST['id']);
      $stmt->execute();
    } elseif ($subAction === 'import') {
      // Import bulk user data
      if (!isset($_REQUEST['import_file']) || empty($_REQUEST['import_file'])) {
        return jsonResponse('error', 'Missing import file');
      }
      $importFile = $_REQUEST['import_file'];

      // Read the import file and validate each entry
      $lines = file($importFile);
      foreach ($lines as $line) {
        $entry = explode(',', $line);
        if (count($entry) !== 3) {
          return jsonResponse('error', 'Invalid import format');
        }

        // Validate the entry against the same rules as individual user creation
        if (!isset($entry[0]) || empty($entry[0])) {
          return jsonResponse('error', 'Missing name');
        }
        if (!isset($entry[1]) || !filter_var($entry[1], FILTER_VALIDATE_EMAIL)) {
          return jsonResponse('error', 'Invalid email address');
        }
        if (!isset($entry[2])) {
          return jsonResponse('error', 'Missing password');
        }

        // Handle concurrent updates to user data
        $stmt = $db->prepare('INSERT INTO users (name, email, password) VALUES (:name, :email, :password) ON DUPLICATE KEY UPDATE name=:name, email=:email, password=:password');
        $stmt->bindParam(':name', $entry[0]);
        $stmt->bindParam(':email', $entry[1]);
        $stmt->bindParam(':password', $entry[2]);
        $stmt->execute();
      }
    } else {
      return jsonResponse('error', 'Invalid sub-action');
    }
  } elseif (isset($_REQUEST['id'])) {
    // Update or delete a specific user account
    if ($_REQUEST['id'] === 'new') {
      // Create a new user account
      $stmt = $db->prepare('INSERT INTO users (name, email, password) VALUES (:name, :email, :password)');
      $stmt->bindParam(':name', $_REQUEST['name']);
      $stmt->bindParam(':email', $_REQUEST['email']);
      $stmt->bindParam(':password', $_REQUEST['password']);
      $stmt->execute();
    } else {
      // Update or delete an existing user account
      $stmt = $db->prepare('SELECT * FROM users WHERE id=:id');
      $stmt->bindParam(':id', $_REQUEST['id']);
      $stmt->execute();

      if ($stmt->rowCount() === 0) {
        return jsonResponse('error', 'User not found');
      }

      $user = $stmt->fetch(PDO::FETCH_ASSOC);
      if ($user['name'] !== $_REQUEST['name']) {
        // Update the user's name
        $stmt = $db->prepare('UPDATE users SET name=:name WHERE id=:id');
        $stmt->bindParam(':name', $_REQUEST['name']);
        $stmt->bindParam(':id', $_REQUEST['id']);
        $stmt->execute();
      }

      if ($user['email'] !== $_REQUEST['email']) {
        // Update the user's email address
        $stmt = $db->prepare('UPDATE users SET email=:email WHERE id=:id');
        $stmt->bindParam(':email', $_REQUEST['email']);
        $stmt->bindParam(':id', $_REQUEST['id']);
        $stmt->execute();
      }

      if ($user['password'] !== $_REQUEST['password']) {
        // Update the user's password
        $stmt = $db->prepare('UPDATE users SET password=:password WHERE id=:id');
        $stmt->bindParam(':password', $_REQUEST['password']);
        $stmt->bindParam(':id', $_REQUEST['id']);
        $stmt->execute();
      }

      if ($_REQUEST['sub_action'] === 'delete') {
        // Delete the user's account
        $stmt = $db->prepare('DELETE FROM users WHERE id=:id');
        $stmt->bindParam(':id', $_REQUEST['id']);
        $stmt->execute();
      }
    }
  } else {
    return jsonResponse('error', 'Missing ID or sub-action');
  }

  // Log all actions and return a JSON response
  $log = "User account management: ";
  if (isset($_REQUEST['id'])) {
    $log .= "ID=" . $_REQUEST['id'] . ", ";
  }
  if (isset($_REQUEST['name'])) {
    $log .= "Name=" . $_REQUEST['name'] . ", ";
  }
  if (isset($_REQUEST['email'])) {
    $log .= "Email=" . $_REQUEST['email'] . ", ";
  }
  if (isset($_REQUEST['password'])) {
    $log .= "Password=********, ";
  }
  if (isset($_REQUEST['sub_action'])) {
    $log .= "Sub-action=" . $_REQUEST['sub_action'] . ". ";
  }
  file_put_contents('user_accounts.txt', $log . PHP_EOL, FILE_APPEND);
  return jsonResponse(['success' => true]);
}

function jsonResponse($data) {
  header('Content-Type: application/json');
  echo json_encode($data);
  exit;
}
