    public class UserService : IUserService
    {
        private readonly ILogger<UserService> _logger;
        private readonly IConfiguration _configuration;
        private readonly IIdentityService _identityService;
        private readonly IEmailService _emailService;

        public UserService(ILogger<UserService> logger, IConfiguration configuration, IIdentityService identityService, IEmailService emailService)
        {
            _logger = logger;
            _configuration = configuration;
            _identityService = identityService;
            _emailService = emailService;
        }

        public async Task<User> CreateAsync(string username, string password, string emailAddress)
        {
            // Perform input validation to ensure the user's username and password are secure.
            if (string.IsNullOrEmpty(username))
            {
                throw new ArgumentException("Username cannot be empty.");
            }
            if (string.IsNullOrEmpty(password))
            {
                throw new ArgumentException("Password cannot be empty.");
            }
            if (!_configuration["AllowedEmailDomains"].Split(",").Contains(emailAddress.Substring(emailAddress.IndexOf("@") + 1)))
            {
                throw new ArgumentException("Email domain is not allowed.");
            }

            // Create a new user and set their password.
            var user = new User
            {
                Username = username,
                EmailAddress = emailAddress,
                PasswordHash = _identityService.GeneratePasswordHash(password)
            };

            // Perform external email verification if necessary.
            if (_configuration["EnableEmailVerification"] == "true")
            {
                var verifyEmailResponse = await _emailService.VerifyEmailAsync(user.EmailAddress);
                if (verifyEmailResponse.IsSuccessStatusCode)
                {
                    user.IsEmailVerified = true;
                }
                else
                {
                    throw new Exception("External email verification failed.");
                }
            }

            // Perform additional validation and configuration.
            if (_configuration["EnableTwoFactorAuthentication"] == "true")
            {
                user.TwoFactorAuth = true;
            }
            if (_configuration["AllowedIpAddresses"].Split(",").Contains(HttpContext.Connection.RemoteIpAddress))
            {
                user.IsIpAddressAllowed = true;
            }

            // Create the user in the database and return them.
            _identityService.CreateUserAsync(user);
            return user;
        }

        public async Task<User> AuthenticateAsync(string username, string password)
        {
            // Perform input validation to ensure the user's username and password are secure.
            if (string.IsNullOrEmpty(username))
            {
                throw new ArgumentException("Username cannot be empty.");
            }
            if (string.IsNullOrEmpty(password))
            {
                throw new ArgumentException("Password cannot be empty.");
            }

            // Look up the user in the database and check their password hash.
            var user = _identityService.GetUserAsync(username);
            if (user == null || !_identityService.VerifyPasswordHash(password, user.PasswordHash))
            {
                throw new Exception("Invalid username or password.");
            }

            // Check if the user's account is locked out and if so, how long they need to wait before trying again.
            var lockoutTime = _identityService.GetLockoutTimeAsync(user);
            if (lockoutTime != null)
            {
                throw new Exception($"User account is locked out for {lockoutTime.Value} minutes.");
            }

            // Check if the user's email address has been verified and if not, send them an email verification link.
            if (!user.IsEmailVerified)
            {
                var verifyEmailResponse = await _emailService.SendVerifyEmailAsync(user.EmailAddress);
                if (verifyEmailResponse.IsSuccessStatusCode)
                {
                    user.IsEmailVerified = true;
                }
                else
                {
                    throw new Exception("Failed to send verify email.");
                }
            }

            // Return the authenticated user.
            return user;
        }
    }
}
