async function runTest(label, f, module) {
  const startTime = Date.now();

  try {
    // Dynamically load the module using the require function
    const mod = require(module);

    // Initialize the module asynchronously if it has an async initialize method
    if (mod.hasOwnProperty('initialize') && typeof mod.initialize === 'function') {
      await mod.initialize();
    }

    // Execute the test function f asynchronously, passing in a promise that resolves after the test completes successfully or rejects if it encounters an error
    const result = await f(mod);

    // Log detailed information to the console in JSON format
    console.log({
      module: label,
      test: label,
      startTime: startTime,
      endTime: Date.now(),
      outcome: 'pass'
    });

    return result;
  } catch (err) {
    // Log detailed information to the console in JSON format
    console.log({
      module: label,
      test: label,
      startTime: startTime,
      endTime: Date.now(),
      outcome: 'fail'
    });

    throw err;
  } finally {
    // Reset the mocking library blueslip to ensure no side effects between consecutive tests
    blueslip.reset();
  }
}
```
This function takes three arguments: `label` (a string representing the name of the test), `f` (a function that implements the test), and `module` (the module to be tested). It first dynamically loads the module using the `require` function, initializes it asynchronously if it has an async initialize method, executes the test function `f` asynchronously, and logs detailed information to the console in JSON format. If an error occurs during execution, the function will log the detailed information to the console in JSON format and rethrow the error. Finally, the function resets the mocking library blueslip to ensure no side effects between consecutive tests."]

