class DataStreamManager {
  constructor() {
    this.data = [];
    this.paused = false;
    this.stopped = false;
    this.distributedMonitoringSystem = null;
  }

  start() {
    if (this.paused) {
      this.resume();
    } else {
      this.startInterval();
    }
  }

  pause() {
    this.paused = true;
    clearInterval(this.interval);
  }

  resume() {
    this.paused = false;
    this.startInterval();
  }

  stop() {
    this.stopped = true;
    clearInterval(this.interval);
    if (this.distributedMonitoringSystem) {
      this.distributedMonitoringSystem.notifyEvent('data-stream-stopped');
    }
  }

  startInterval() {
    const delay = getRandomIntInclusive(100, 500);
    this.interval = setInterval(() => {
      if (this.stopped) return;
      const data = generateData();
      this.data.push(data);
      if (this.distributedMonitoringSystem) {
        this.distributedMonitoringSystem.notifyEvent('data-stream-event', data);
      }
    }, delay);
  }

  getData() {
    return this.data;
  }
}
