function loadFiles(files) {
  // Load files asynchronously using Promises
  const promises = files.map(file => fetch(file).then(res => res.text()));

  // Wait for all promises to resolve
  Promise.all(promises).then(results => {
    results.forEach((result, index) => {
      // Extract file extension from MIME type
      const extension = result.type.split('/')[1];

      // Replace file extension with new one based on content type
      files[index] = `${files[index].replace(/\.[^.]+$/, '')}.${extension}`;
    });

    // Load and execute files in the correct order
    const dependencies = {};
    files.forEach(file => {
      fetch(file).then(res => res.text()).then(code => {
        try {
          eval(code);
        } catch (error) {
          console.log(`Error loading file ${file}:`, error);
        }
      });
    });
  });
}
