import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import org.apache.kafka.clients.consumer.ConsumerRecord;
import org.apache.kafka.clients.consumer.ConsumerRecords;
import org.apache.kafka.common.serialization.StringDeserializer;
import org.eclipse.paho.client.mqttv3.MqttClient;
import org.eclipse.paho.client.mqttv3.MqttException;
import org.eclipse.paho.client.mqttv3.MqttMessage;

public class DistributedDataProcessingPipeline {
    private static final String KAFKA_BOOTSTRAP_SERVERS = "localhost:9092";
    private static final String KAFKA_TOPIC = "my-topic";
    private static final String HTTP_URL = "http://example.com/data";
    private static final String MQTT_BROKER_URI = "tcp://localhost:1883";
    private static final String MQTT_TOPIC = "my-topic";

    public static void main(String[] args) {
        ExecutorService executorService = Executors.newFixedThreadPool(2);
        ScheduledExecutorService scheduledExecutorService = Executors.newSingleThreadScheduledExecutor();

        KafkaConsumer kafkaConsumer = new KafkaConsumer<>(KAFKA_BOOTSTRAP_SERVERS, KAFKA_TOPIC, StringDeserializer.class);
        HttpClient httpClient = new HttpClient(HTTP_URL);
        MqttClient mqttClient = new MqttClient(MQTT_BROKER_URI, MQTT_TOPIC);

        scheduledExecutorService.scheduleAtFixedRate(() -> {
            ConsumerRecords<String, String> kafkaRecords = kafkaConsumer.poll();
            if (kafkaRecords.isEmpty()) {
                return;
            }
            executorService.submit(() -> processKafkaRecords(kafkaRecords));
        }, 0, 1, TimeUnit.SECONDS);

        scheduledExecutorService.scheduleAtFixedRate(() -> {
            String mqttMessage = mqttClient.receive();
            if (mqttMessage == null) {
                return;
            }
            executorService.submit(() -> processMqttMessage(mqttMessage));
        }, 0, 1, TimeUnit.SECONDS);
    }

    private static void processKafkaRecords(ConsumerRecords<String, String> kafkaRecords) {
        for (ConsumerRecord<String, String> record : kafkaRecords) {
            String message = record.value();
            // Process Kafka message
            System.out.println("Processing Kafka message: " + message);
            httpClient.send(message);
            mqttClient.publish(message);
        }
    }

    private static void processMqttMessage(String mqttMessage) {
