```rust
// http_client.rs
use std::time::Duration;

use async_trait::async_trait;
use reqwest::{Request, Response, Url};
use url::Url;

#[async_trait]
pub trait HTTPClient {
    type Error: Debug + Display;

    fn new(configuration: Configuration) -> Self;

    async fn send(&mut self, request: Request) -> Result<Response, Self::Error>;
}

pub struct HTTPClientImpl {
    client: reqwest::Client,
    configuration: Configuration,
}

impl HTTPClient for HTTPClientImpl {
    type Error = reqwest::Error;

    fn new(configuration: Configuration) -> Self {
        let mut builder = reqwest::Client::builder();

        if let Some(timeout) = configuration.timeout {
            builder = builder.timeout(Duration::from_secs(timeout));
        }

        if let Some(ca_certificate) = configuration.ca_certificate {
            builder = builder.add_root_certificate(ca_certificate);
        }

        if let Some(proxy) = configuration.proxy {
            builder = builder.proxy(reqwest::Proxy::all(proxy)?);
        }

        Self {
            client: builder.build()?,
            configuration,
        }
    }

    async fn send(&mut self, request: Request) -> Result<Response, Self::Error> {
        let response = match self.configuration.ca_certificate {
            Some(ca_certificate) => {
                reqwest::Client::new()
                    .execute(request)
                    .await?
                    .text()
                    .await?
            }
            None => self.client.execute(request).await?.text().await?,
        };

        Ok(response)
    }
}
```

