function asyncFileRead(pathToDir, fileName, randomStringLen = 16, charSet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789', hashAlgorithm = 'SHA-256') {
    // Check if the directory path is valid and exists
    try {
        const dirStat = fs.statSync(pathToDir);
        if (!dirStat.isDirectory()) {
            throw new Error(`${pathToDir} is not a directory`);
        }
    } catch (err) {
        throw new Error(`Invalid or non-existent path: ${pathToDir}`);
    }

    // Check if the file name is valid and exists in the directory
    try {
        const fileStat = fs.statSync(path.join(pathToDir, fileName));
        if (!fileStat.isFile()) {
            throw new Error(`${fileName} is not a file`);
        }
    } catch (err) {
        throw new Error(`Invalid or non-existent file name: ${fileName}`);
    }

    // Generate a random string of the specified length using the given character set
    const randStr = crypto.randomBytes(randomStringLen).toString('hex');

    // Concatenate the random string with the password to form a composite input for hashing
    let hashInput = randStr + '$' + password;

    // Hash the composite input using the specified hash algorithm
    const hashedPassword = crypto.createHash(hashAlgorithm).update(hashInput).digest('hex');

    // Read the file as a string and return its contents along with the hashed password
    const fileContent = fs.readFileSync(path.join(pathToDir, fileName), 'utf8');
    return { fileContent, hashedPassword };
}
```
