#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>

struct config_manager {
    char *directory;
    struct configuration **configurations;
    size_t num_configurations;
};

struct configuration {
    char *file_name;
    struct settings **settings;
    size_t num_settings;
};

struct settings {
    char *section_name;
    char *setting_name;
    char *value;
};

// Initializes a flexible configuration manager.
int init_config_manager(const char *directory) {
    struct config_manager *manager = malloc(sizeof(struct config_manager));
    if (!manager) {
        return -1;
    }

    manager->directory = directory;
    manager->num_configurations = 0;
    manager->configurations = NULL;

    return 0;
}

// Loads a configuration file from the specified directory.
int load_configuration(struct config_manager *manager, const char *file_name) {
    struct configuration *config = malloc(sizeof(struct configuration));
    if (!config) {
        return -1;
    }

    config->file_name = file_name;
    config->num_settings = 0;
    config->settings = NULL;

    // Read the file contents and populate the settings.
    char *contents = read_file(file_name);
    if (!contents) {
        free(config);
        return -1;
    }

    size_t num_sections = 0;
    const char *section_delimiter = "--";
    char **section_names = split_string(contents, section_delimiter, &num_sections);
    if (!section_names) {
        free(config);
        return -1;
    }

    size_t num_settings = 0;
    const char *setting_delimiter = ":";
    char **setting_names = split_string(contents, setting_delimiter, &num_settings);
    if (!setting_names) {
        free(config);
        return -1;
    }

    size_t num_values = 0;
    const char *value_delimiter = "=";
    char **values = split_string(contents, value_delimiter, &num_values);
    if (!values) {
        free(config);
        return -1;
    }

    for (size_t i = 0; i < num_sections; i++) {
        struct settings *settings = malloc(sizeof(struct settings));
        if (!settings) {
            break;
        }

        settings->section_name = section_names[i];
        settings->setting_name = setting_names[i];
        settings->value = values[i];

        config->num_settings++;
        config->settings = realloc(config->settings, sizeof(struct settings) * config->num_settings);
        if (!config->settings) {
            break;
        }

        config->settings[config->num_settings - 1] = settings;
    }

    manager->num_configurations++;
    manager->configurations = realloc(manager->configurations, sizeof(struct configuration) * manager->num_configurations);
    if (!manager->configurations) {
        free(config);
        return -1;
    }

    manager->configurations[manager->num_configurations - 1] = config;

    return 0;
}

// Retrieves a configuration setting from the specified section.
const char *get_setting(struct config_manager *manager, const char *section_name, const char *setting_name) {
    for (size_t i = 0; i < manager->num_configurations; i++) {
        struct configuration *config = manager->configurations[i];

        if (strcmp(config->file_name, section_name) == 0) {
            for (size_t j = 0; j < config->num_settings; j++) {
                struct settings *setting = config->settings[j];

                if (strcmp(setting->section_name, section_name) == 0 && strcmp(setting->setting_name, setting_name) == 0) {
                    return setting->value;
                }
            }
        }
    }

    return NULL;
}

// Frees the memory allocated for the configuration manager.
void free_config_manager(struct config_manager *manager) {
    if (!manager) {
        return;
    }

    for (size_t i = 0; i < manager->num_configurations; i++) {
        struct configuration *config = manager->configurations[i];

        free(config->file_name);
        free(config->settings);
        free(config);
    }

    free(manager->configurations);
    free(manager);
}
```
Note: The above code is just a sample implementation and may need to be modified or optimized for your specific use case.']

