#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <libxml/tree.h>
#include <libxml/xpath.h>

typedef struct {
    char* name;
    char* namespace;
} Element;

char** processString(const char* input, int sizeLimit, xmlXPathFunc func) {
    // Create an XML document object from the given string
    xmlDocPtr doc = xmlReadMemory(input, strlen(input), NULL, NULL, 0);
    if (doc == NULL) {
        return NULL;
    }

    // Create an XPath context for evaluating expressions
    xmlXPathContextPtr ctx = xmlXPathNewContext(doc);
    if (ctx == NULL) {
        xmlFreeDoc(doc);
        return NULL;
    }

    // Initialize a list to store the matched elements' text content
    Element** list = malloc(sizeof(Element*) * sizeLimit);
    int count = 0;

    // Traverse the XML document starting from the root node
    xmlNodePtr node = xmlDocGetRootElement(doc);
    while (node != NULL && count < sizeLimit) {
        // Evaluate the XPath expression for the current node
        xmlXPathObjectPtr result = xmlXPathEvalExpression(ctx, func);
        if (result == NULL || !xmlXPathNodeSetIsEmpty(result->nodesetval)) {
            Element* element = malloc(sizeof(Element));
            element->name = xmlGetProp(node, BAD_CAST "name");
            element->namespace = xmlGetProp(node, BAD_CAST "namespace");
            list[count++] = element;
        }
        node = node->next;
    }

    // Free the XML document and XPath context
    xmlFreeDoc(doc);
    xmlXPathFreeContext(ctx);

    // Return the matched elements' text content as a dynamically allocated array
    if (count > 0) {
        char** output = malloc(sizeof(char*) * count);
        for (int i = 0; i < count; i++) {
            output[i] = list[i]->name;
            if (list[i]->namespace != NULL) {
                strcat(output[i], " ");
                strcat(output[i], list[i]->namespace);
            }
        }
        free(list);
        return output;
    } else {
        free(list);
        return NULL;
    }
}
