char *generate_unique_filename(const char *filename, const char *directory) {
    // Get the current time in seconds
    time_t now = time(NULL);
    // Generate a random number between 1000 and 9999
    int rand_num = (int)(now % 8999 + 1000);
    // Determine the appropriate file type extension based on the directory's existing files
    char *ext = determine_file_extension(directory);
    // Create a new filename by appending the random number and file type extension
    char *new_filename = malloc(strlen(filename) + strlen(ext) + 5);
    sprintf(new_filename, "%s_%d.%s", filename, rand_num, ext);
    // Handle filenames containing spaces and special characters without causing syntax errors or crashes
    int len = strlen(new_filename);
    for (int i = 0; i < len; i++) {
        if (!isalnum(new_filename[i])) {
            new_filename[i] = '_';
        }
    }
    // Manage directory paths carefully, ensuring no trailing slashes and handling any non-printable characters gracefully
    char *path = malloc(strlen(directory) + strlen(new_filename) + 2);
    sprintf(path, "%s/%s", directory, new_filename);
    // Optimize for performance to handle a large number of files in the directory efficiently
    struct stat st;
    int exists = 0;
    while (!exists) {
        if (stat(path, &st) == -1) {
            // If the file does not exist, return the full path to the new filename
            return path;
        } else {
            // If the file already exists, generate a new random number and try again
            rand_num++;
            sprintf(new_filename, "%s_%d.%s", filename, rand_num, ext);
            len = strlen(new_filename);
            for (int i = 0; i < len; i++) {
                if (!isalnum(new_filename[i])) {
                    new_filename[i] = '_';
                }
            }
            sprintf(path, "%s/%s", directory, new_filename);
        }
    }
}

char *determine_file_extension(const char *directory) {
    // Open the directory and read its contents
    DIR *dir = opendir(directory);
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strlen(entry->d_name) > 4) {
            // Check the file extension of each file in the directory
            char *ext = entry->d_name + strlen(entry->d_name) - 4;
            if (!strcmp(ext, ".txt") || !strcmp(ext, ".pdf")) {
                return ext;
            }
        }
    }
    // If no compatible file extensions are found, return a default extension
    return ".txt";
}
```
