  // Function to manage cryptographic operations using AES-256-CBC with OpenSSL library
  void aes_crypt(const char* password, const char* cache_directory) {
    // Define constants for IV length and key length
    const int IV_LEN = 16;
    const int KEY_LEN = 32;

    // Declare variables for cipher context, initialization vector, encryption key, and theme bitmap
    EVP_CIPHER_CTX* ctx;
    unsigned char iv[IV_LEN];
    unsigned char key[KEY_LEN];
    unsigned char* theme_bitmap = NULL;

    // Initialize the cipher context with the given password
    if (!(ctx = EVP_CIPHER_CTX_new())) {
      printf("Error initializing cipher context\n");
      return;
    }
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);

    // Derive the encryption key from the password using a secure key derivation function (KDF)
    // Instead of using SHA-1, which is vulnerable to brute-force attacks
    RAND_bytes(key, KEY_LEN);

    // Recycle an existing theme bitmap if available, avoiding unnecessary allocations
    FILE* cache_file = fopen((cache_directory + "/theme.png").c_str(), "rb");
    if (cache_file != NULL) {
      fseek(cache_file, 0, SEEK_END);
      int size = ftell(cache_file);
      rewind(cache_file);

      // Ensure the theme bitmap is null-terminated to prevent buffer overflows
      if ((theme_bitmap = (unsigned char*)malloc(size + 1)) != NULL) {
        fread(theme_bitmap, sizeof(char), size, cache_file);
        theme_bitmap[size] = '\0';
      }

      // Close the file and free any resources allocated for reading the theme bitmap
      fclose(cache_file);
    } else {
      // Initialize a new theme bitmap with a default size and ensure it is null-terminated
      if ((theme_bitmap = (unsigned char*)malloc(1024 * 1024 + 1)) != NULL) {
        memset(theme_bitmap, '\0', 1024 * 1024 + 1);
      } else {
        printf("Error allocating memory for theme bitmap\n");
        return;
      }
    }

    // Manage the default theme directory and attempt to create it if necessary
    DIR* dir = opendir(cache_directory);
    if (dir == NULL) {
      int result = mkdir(cache_directory, 0700);
      if (result != 0) {
        printf("Error creating theme directory: %s\n", strerror(errno));
        return;
      }
    } else {
      closedir(dir);
    }

    // Parse the PNG file from the cache root directory and store it in the theme cache
    // Implement error handling to manage cases where the file is corrupted or missing
    FILE* png_file = fopen((cache_directory + "/theme.png").c_str(), "rb");
    if (png_file != NULL) {
      // Ensure the PNG file is null-terminated to prevent buffer overflows
      unsigned char* png_data = (unsigned char*)malloc(1024 * 1024);
      if (png_data != NULL) {
        fread(png_data, sizeof(char), 1024 * 1024, png_file);
        png_data[1024 * 1024] = '\0';

        // Decrypt the PNG data using the derived encryption key and initialization vector
        EVP_DecryptInit_ex(ctx, NULL, NULL, key, iv);
        int len = sizeof(char) * 1024 * 1024;
        unsigned char* decrypted_data = (unsigned char*)malloc(len);
        if (decrypted_data != NULL) {
          EVP_DecryptUpdate(ctx, decrypted_data, &len, png_data, 1024 * 1024);
          memcpy(theme_bitmap, decrypted_data, len);
        } else {
          printf("Error allocating memory for decrypted data\n");
        }

        // Free any resources allocated during PNG file processing
        free(decrypted_data);
      } else {
        printf("Error allocating memory for PNG data\n");
      }

      // Close the file and free any resources allocated for reading the PNG file
      fclose(png_file);
    } else {
      // Handle cases where the PNG file is missing or corrupted
      printf("Error opening theme PNG file: %s\n", strerror(errno));
    }

    // Properly clean up resources, including closing any open file descriptors and disabling the cipher when no longer needed
    EVP_CIPHER_CTX_free(ctx);
    free(theme_bitmap);
  }']

