    private const string AllowedDirectories = @"C:\inetpub\wwwroot"; // Add more directories as needed

    public static async Task<Process> StartSite(string directoryPath, string siteName)
    {
        if (!Directory.Exists(directoryPath))
        {
            return null;
        }

        var webConfigPath = Path.Combine(directoryPath, "web.config");
        if (!File.Exists(webConfigPath))
        {
            return null;
        }

        if (!AllowedDirectories.Split(';').Any(d => d.Equals(directoryPath, StringComparison.OrdinalIgnoreCase)))
        {
            throw new UnauthorizedAccessException("The specified directory is not allowed.");
        }

        var processes = Process.GetProcessesByName(siteName);
        if (processes.Any())
        {
            return null;
        }

        try
        {
            using (var process = new Process())
            {
                process.StartInfo.FileName = Path.Combine(directoryPath, "dotnet.exe");
                process.StartInfo.Arguments = $"{siteName}.dll";
                process.Start();
                return process;
            }
        }
        catch (Exception e)
        {
            // Log error and release resources if necessary
            Console.WriteLine(e);
            return null;
        }
    }
}
