int verifyConfiguration(Configuration *config) {
  // Check if the password is valid and not empty or NULL
  if (config->password == NULL || strlen(config->password) == 0) {
    return INVALID_PASSWORD;
  }

  // Ensure the connection settings object has a valid title and endpoint configured
  if (config->connectionSettings == NULL || config->connectionSettings->title == NULL || config->connectionSettings->endpoint == NULL) {
    return INVALID_CONNECTION_SETTINGS;
  }

  // Confirm the callback handler is properly initialized and not NULL
  if (config->callbackHandler == NULL) {
    return INVALID_CALLBACK_HANDLER;
  }

  // Attempt to decrypt the provided Base64-encoded message using Triple DES encryption with a specified key and initialization vector (IV)
  char *decryptedMessage = triple_des_decrypt(config->message, config->password);
  if (decryptedMessage == NULL) {
    return DECRYPTION_FAILED;
  }

  // Handle potential errors during decryption and memory allocation for the decrypted message
  int errorCode = handleDecryptionErrors(decryptedMessage);
  if (errorCode != SUCCESS) {
    return errorCode;
  }

  // Ensure the integrity of the decrypted data before returning it
  char *integrityError = ensureIntegrity(decryptedMessage);
  if (integrityError != NULL) {
    free(decryptedMessage);
    return INTEGRITY_ERROR;
  }

  return SUCCESS;
}
