using System;
using System.Data;
using System.Data.Common;
using System.Threading;
using System.Threading.Tasks;

public static class DatabaseHelper
{
    private const int MAX_RETRIES = 3;
    private const int TIMEOUT = 5000; // in milliseconds

    public static async Task<DataTableReader> QueryDatabaseAsync(byte[] input)
    {
        string queryString = Encoding.ASCII.GetString(input);

        DataTable table = new DataTable();
        using (var connection = new SqlConnection("Server=myserver;Database=mydatabase;User Id=myusername;Password=mypassword"))
        {
            try
            {
                await connection.OpenAsync();
                var command = new SqlCommand(queryString, connection);
                var reader = command.ExecuteReader();
                table.Load(reader);
            }
            catch (SqlException ex)
            {
                if (ex.Number == 10060) // retry connection error
                {
                    await RetryQueryAsync(input, MAX_RETRIES - 1);
                }
                else if (ex.Number == 258 /* Unknown database */)
                {
                    throw new DatabaseException("Database not found");
                }
                else
                {
                    throw ex;
                }
            }
        }

        return table.CreateDataReader();
    }

    private static async Task RetryQueryAsync(byte[] input, int retries)
    {
        if (retries <= 0)
        {
            throw new DatabaseException("Failed to query database");
        }

        await Task.Delay(TIMEOUT);
        return await QueryDatabaseAsync(input);
    }
}
