    {
        $this->oauth = new OAuth2($clientId, $clientSecret);
    }

    public function authenticateUser(string $username, string $password): TokenResponse
    {
        try
        {
            $tokenResponse = $this->oauth->grantAccessToken('authorization_code', ['username' => $username, 'password' => $password]);
            if (!$tokenResponse->hasError())
            {
                // store access token in session variable
                $_SESSION['access_token'] = $tokenResponse->getAccessToken();
            }
        }
        catch (OAuthException $ex)
        {
            throw new AuthenticationException("Authentication failed", 0, $ex);
        }
    }
}
