    char* ip;
};

int perform_dns_lookup(const char* hostname, struct dns_query_result* result)
{
    int ret = 0;
    struct addrinfo hints, *res;

    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_DGRAM;

    ret = getaddrinfo(hostname, NULL, &hints, &res);
    if (ret != 0)
    {
        fprintf(stderr, "Error: %s\n", gai_strerror(ret));
        return ret;
    }

    // perform DNS lookup for each address
    struct addrinfo* p = res;
    while (p != NULL && ret == 0)
    {
        if (perform_dns_lookup_for_address(p->ai_addr, result))
        {
            ret = 1;
            break;
        }
        p = p->ai_next;
    }

    freeaddrinfo(res);
    return ret;
}

int perform_dns_lookup_for_address(struct sockaddr* addr, struct dns_query_result* result)
{
    int ret = 0;
    struct sockaddr_in* saddr = (struct sockaddr_in*)addr;
    char buffer[DNS_MAX_QUERIES * sizeof(struct in_addr)];

    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0)
    {
        fprintf(stderr, "Error: %s\n", strerror(errno));
        return ret;
    }

    // perform DNS lookup for each address
    struct in_addr* p = (struct in_addr*)buffer;
    while (p != NULL && ret == 0)
    {
        if (perform_dns_lookup_for_address_helper(sockfd, saddr->sin_addr.s_addr, result))
        {
            ret = 1;
            break;
        }
        p++;
    }

    close(sockfd);
    return ret;
}

int perform_dns_lookup_for_address_helper(int sockfd, uint32_t address, struct dns_query_result* result)
{
    int ret = 0;
    char buffer[sizeof(struct in_addr)];
    struct in_addr* p = (struct in_addr*)buffer;

    // send DNS request
    ssize_t sent = sendto(sockfd, "GET / HTTP/1.1\r\nHost: google.com\r\nAccept: */*\r\n\r\n", strlen("GET / HTTP/1.1\r\nHost: google.com\r\nAccept: */*\r\n\r\n"), 0, (struct sockaddr*)saddr, sizeof(struct sockaddr_in));
    if (sent < 0)
    {
        fprintf(stderr, "Error: %s\n", strerror(errno));
        return ret;
    }

    // receive DNS response
    ssize_t received = recvfrom(sockfd, buffer, sizeof(buffer), 0, NULL, NULL);
    if (received < 0)
    {
        fprintf(stderr, "Error: %s\n", strerror(errno));
        return ret;
    }

    // parse DNS response
    p = (struct in_addr*)buffer;
    for (int i = 0; i < received / sizeof(struct in_addr); i++)
    {
        if (p->s_addr == address)
        {
            result->ip = strdup(inet_ntoa(*p));
            ret = 1;
            break;
        }
        p++;
    }

    return ret;
}
```
Note: This code is for illustration purposes only and may not be suitable for production environments. It should be tested and validated to ensure that it meets your specific requirements before use.']

