using System;
using System.Security.Cryptography;
using System.IO;
using System.Text;

namespace AesCbcEncryption
{
    public class EncryptionManager
    {
        // Config file path for storing keys and IVs
        private static readonly string _configFilePath = "keys.cfg";

        // Keys and IVs for current session
        private byte[] _key;
        private byte[] _iv;

        // Initializes the encryption manager with a randomly generated key and IV
        public EncryptionManager()
        {
            _key = GenerateRandomKey();
            _iv = GenerateRandomIv();
        }

        // Generates a random 32-byte encryption key
        private byte[] GenerateRandomKey()
        {
            var rng = new RNGCryptoServiceProvider();
            var bytes = new byte[32];
            rng.GetBytes(bytes);
            return bytes;
        }

        // Generates a random 16-byte initialization vector (IV)
        private byte[] GenerateRandomIv()
        {
            var rng = new RNGCryptoServiceProvider();
            var bytes = new byte[16];
            rng.GetBytes(bytes);
            return bytes;
        }

        // Loads pre-configured keys and IVs from a specified configuration file path
        public void LoadKeysAndIvsFromConfigFile()
        {
            var config = new ConfigurationManager();
            _key = Convert.FromBase64String(config["key"]);
            _iv = Convert.FromBase64String(config["iv"]);
        }

        // Saves the current session's keys and IVs to a specified configuration file path
        public void SaveKeysAndIvsToConfigFile()
        {
            var config = new ConfigurationManager();
            config["key"] = Convert.ToBase64String(_key);
            config["iv"] = Convert.ToBase64String(_iv);
        }

        // Encrypts a given string using AES-CBC with the current session's key and IV
        public string Encrypt(string plaintext)
        {
            var ciphertext = String.Empty;

            using (var aes = new AesCryptoServiceProvider())
            {
                // Set the encryption key and IV
                aes.Key = _key;
                aes.IV = _iv;

                // Encrypt the plaintext
                var cipherBytes = aes.Encrypt(Encoding.UTF8.GetBytes(plaintext));

                // Convert the encrypted bytes to a string
                ciphertext = BitConverter.ToString(cipherBytes).Replace("-", "");
            }

            return ciphertext;
        }

        // Decrypts a given string using AES-CBC with the current session's key and IV
        public string Decrypt(string ciphertext)
        {
            var plaintext = String.Empty;

            using (var aes = new AesCryptoServiceProvider())
            {
                // Set the decryption key and IV
                aes.Key = _key;
                aes.IV = _iv;

                // Decrypt the ciphertext
                var plainBytes = aes.Decrypt(Convert.FromBase64String(ciphertext));

                // Convert the decrypted bytes to a string
                plaintext = Encoding.UTF8.GetString(plainBytes);
            }

            return plaintext;
        }
    }
}
