use tokio::runtime::Runtime;
use tokio::sync::mpsc;
use std::time::Duration;
use std::thread;

fn main() {
    let mut rt = Runtime::new().unwrap();
    let (tx, rx) = mpsc::channel(10);

    // spawn a thread to process messages from the channel
    thread::spawn(move || {
        while let Some(message) = rx.recv().await {
            match message {
                Message::CriticalError(error) => {
                    // construct log message using `snprintf` and `va_start/va_end`
                    let mut buf = [0; 1024];
                    let len = snprintf(buf.as_mut_ptr(), buf.len(), "%s", error);
                    if len > 0 {
                        // send log message to remote logging service via HTTP POST request
                        rt.block_on(send_log_request(&buf[..len]));
                    }
                },
                Message::Warning(warning) => {
                    println!("WARNING: {}", warning);
                },
                Message::Info(info) => {
                    println!("INFO: {}", info);
                },
            }
        }
    });

    // handle command-line arguments and dispatch messages to the channel
    for arg in std::env::args().skip(1) {
        match arg.parse() {
            Ok(Message::CriticalError(error)) => tx.send(Message::CriticalError(error)).await,
            Ok(Message::Warning(warning)) => tx.send(Message::Warning(warning)).await,
            Ok(Message::Info(info)) => tx.send(Message::Info(info)).await,
            Err(e) => println!("Invalid message: {}", e),
        }
    }
}

fn send_log_request(buf: &[u8]) -> impl Future<Output = ()> {
    // construct HTTP POST request using `hyper` library
    let client = hyper::Client::new();
    let url = "http://example.com/log";
    let mut req = Request::post(url);
    req.set_body(Body::from(buf));
    async move {
        match client.request(req).await {
            Ok(res) => {
                if res.status() == 200 {
                    println!("Log message sent");
                } else {
                    println!("Failed to send log message: {}", res);
                }
            },
            Err(e) => println!("Error sending log request: {}", e),
        }
    }
}

enum Message {
    CriticalError(String),
    Warning(String),
    Info(String),
}

fn snprintf(buf: *mut c_char, len: usize, fmt: &str) -> isize {
    // construct log message using `fmt::format`
    let message = format!("{}: {}", "CriticalError", error);
    if message.len() > len - 1 {
        return -1;
    }
    unsafe { std::ptr::copy_nonoverlapping(message.as_bytes().as_ptr(), buf, message.len()) };
    message.len() as isize + 1
}
```
