const CONFIG_DIR: &str = "CONFIG_DIR";
const CONFIG_PATH: &str = "CONFIG_PATH";

fn get_config_dir() -> PathBuf {
    let home_dirs = env::home_dir().unwrap();
    let default_base_path = PathBuf::from("/etc");

    let base_path = if let Some(home) = home_dirs {
        PathBuf::from(&home).join("config")
    } else {
        default_base_path.clone()
    };

    let config_dir = base_path.join(CONFIG_DIR);
    fs::create_dir_all(&config_dir).unwrap();

    if !config_dir.is_dir() {
        println!("Invalid configuration directory path, using default path");
        default_base_path
    } else {
        config_dir
    }
}

fn get_config_path() -> PathBuf {
    let mut config_path = env::var(CONFIG_PATH);

    if config_path.is_err() || !PathBuf::from(&config_path.unwrap()).exists() {
        let config_dir = get_config_dir();
        env::set_var(CONFIG_PATH, &config_dir);
        config_dir
    } else {
        PathBuf::from(&config_path.unwrap())
    }
}

fn create_config_dir() -> PathBuf {
    let config_dir = get_config_dir();
    fs::create_dir_all(&config_dir).unwrap();
