namespace NetworkRandomNumberGenerator {
  class NetworkInterfaceConfig {
    int interfaceId;
    std::vector<NeighborCellInfo> neighborCellList;
    SoundingReferenceSignalParams srsParams;

   public:
    // Constructor to populate neighbor cell list and configure SRS parameters
    NetworkInterfaceConfig(int numNeighbors, int interfaceId) {
      this->interfaceId = interfaceId;
      for (int i = 0; i < numNeighbors; i++) {
        NeighborCellInfo newCell;
        // Populate neighbor cell list with unique IDs and configure SRS parameters
        newCell.neighborId = i + 1;
        newCell.signalStrength = getRandomSignalStrength();
        srsParams.srsBandwidth = getRandomSRSParam(0, 2);
        srsParams.srsSubcarrierSpacing = getRandomSRSParam(0, 3);
        neighborCellList.push_back(newCell);
      }
    }

    // Destructor to free memory
    ~NetworkInterfaceConfig() {
      neighborCellList.clear();
    }

    // Function to get a random signal strength value
    int getRandomSignalStrength() {
      std::mt19937 rng(std::random_device()());
      std::uniform_int_distribution<int> distribution(0, 25);
      return distribution(rng);
    }

    // Function to get a random SRS parameter value
    int getRandomSRSParam(int min, int max) {
      std::mt19937 rng(std::random_device()());
      std::uniform_int_distribution<int> distribution(min, max);
      return distribution(rng);
    }
  };
