  void* RX_PDU;
  float SNR[20];
  float RSSI[20];
} NFAPI_RXINFO_PDU_T;

// Define helper function to calculate mean and standard deviation
void meanAndStdDev(float *array, int size, float *mean, float *stddev) {
  // Calculate the sum of all elements in the array
  float sum = 0.0f;
  for (int i = 0; i < size; ++i) {
    sum += array[i];
  }

  // Calculate the mean
  *mean = sum / size;

  // Calculate the variance
  float var = 0.0f;
  for (int i = 0; i < size; ++i) {
    var += pow((array[i] - *mean), 2);
  }
  var /= (size - 1);

  // Calculate the standard deviation
  *stddev = sqrt(var);
}

// Define function to process dynamically sized list of floating-point numbers read from standard input
void processList(float* input, int size) {
  // Create an array to store the mean and standard deviation values
  float mean[2] = {0.0f, 0.0f};

  // Create a list of NFAPI_RXINFO_PDU_T structures
  NFAPI_RXINFO_PDU_T* rxinfoList = malloc(size * sizeof(NFAPI_RXINFO_PDU_T));

  // Populate the list with values from the input array
  for (int i = 0; i < size; ++i) {
    rxinfoList[i].UE_ID = i + 1;
    rxinfoList[i].RX_PDU = NULL;
    memcpy(rxinfoList[i].SNR, input + (2 * i), sizeof(float));
    memcpy(rxinfoList[i].RSSI, input + (2 * i + 1), sizeof(float));
  }

  // Calculate the mean and standard deviation values for each UE
  for (int i = 0; i < size; ++i) {
    float tempMean = 0.0f;
    float tempStdDev = 0.0f;
    meanAndStdDev(rxinfoList[i].SNR, 20, &tempMean, &tempStdDev);
    rxinfoList[i].mean = tempMean;
    rxinfoList[i].stddev = tempStdDev;
  }

  // Print the mean and standard deviation values for each UE
  for (int i = 0; i < size; ++i) {
    printf("UE %d: Mean=%.2f, StdDev=%.2f\n", rxinfoList[i].UE_ID, rxinfoList[i].mean, rxinfoList[i].stddev);
  }

  // Free the memory allocated for the list of NFAPI_RXINFO_PDU_T structures
  free(rxinfoList);
}

int main() {
