  float* input = NULL;

  // Read the number of elements in the input array from standard input
  scanf("%d", &size);

  // Allocate memory for the input array
  input = malloc(2 * size * sizeof(float));

  // Read the input array from standard input
  for (int i = 0; i < size; ++i) {
    scanf("%f %f", &input[2 * i], &input[2 * i + 1]);
  }

  // Process the input array and calculate the mean and standard deviation values for each UE
