    char* ue_id;
    struct event* events;
} SessionState;

// Linked list of network events
struct event {
    int type;
    int timestamp;
    struct event* next;
};

// Function to initialize and manage an array of network session states
void initSessions(int num_sessions) {
    // Allocate memory for the session state array
    SessionState* sessions = (SessionState*) malloc(num_sessions * sizeof(SessionState));

    // Initialize each session state with a unique ID and UE identifier
    for (int i = 0; i < num_sessions; i++) {
        sessions[i].id = i + 1;
        char* ue_id = (char*) malloc(sizeof(char) * 20);
        sprintf(ue_id, "UE-%d", i + 1);
        sessions[i].ue_id = ue_id;
    }

    // Initialize the linked list of events for each session
    for (int i = 0; i < num_sessions; i++) {
        struct event* head = NULL;
        struct event* tail = NULL;
        while (head != NULL || tail != NULL) {
            if (tail == NULL) {
                tail = malloc(sizeof(struct event));
                tail->type = 0;
                tail->timestamp = 0;
                head = tail;
            } else {
                struct event* temp = malloc(sizeof(struct event));
                temp->type = 0;
                temp->timestamp = 0;
                tail->next = temp;
                tail = temp;
            }
        }
        sessions[i].events = head;
    }
}

// Function to allocate memory for a new network session
void addSession(int id, char* ue_id) {
    // Allocate memory for the new session state
    SessionState* new_session = (SessionState*) malloc(sizeof(SessionState));
    new_session->id = id;
    new_session->ue_id = ue_id;

    // Initialize the linked list of events for the new session
    struct event* head = NULL;
    struct event* tail = NULL;
    while (head != NULL || tail != NULL) {
        if (tail == NULL) {
            tail = malloc(sizeof(struct event));
            tail->type = 0;
            tail->timestamp = 0;
            head = tail;
        } else {
            struct event* temp = malloc(sizeof(struct event));
            temp->type = 0;
            temp->timestamp = 0;
            tail->next = temp;
            tail = temp;
        }
    }
    new_session->events = head;

    // Add the new session to the array of sessions
    int num_sessions = 10; // Replace with actual number of sessions
    SessionState* sessions = (SessionState*) malloc(num_sessions * sizeof(SessionState));
    for (int i = 0; i < num_sessions; i++) {
        if (sessions[i].id == 0) {
            sessions[i] = new_session;
            break;
        }
    }
}

// Function to deallocate memory for a network session
void removeSession(int id) {
    // Find the session with the given ID in the array of sessions
    int num_sessions = 10; // Replace with actual number of sessions
    SessionState* sessions = (SessionState*) malloc(num_sessions * sizeof(SessionState));
    for (int i = 0; i < num_sessions; i++) {
        if (sessions[i].id == id) {
            free(sessions[i].ue_id);
            struct event* head = sessions[i].events;
            while (head != NULL) {
                struct event* temp = head->next;
                free(head);
                head = temp;
            }
            break;
        }
    }
}

// Function to handle network events for a given session
void handleEvent(int id, int type, int timestamp) {
    // Find the session with the given ID in the array of sessions
    int num_sessions = 10; // Replace with actual number of sessions
    SessionState* sessions = (SessionState*) malloc(num_sessions * sizeof(SessionState));
    for (int i = 0; i < num_sessions; i++) {
        if (sessions[i].id == id) {
            struct event* new_event = malloc(sizeof(struct event));
            new_event->type = type;
            new_event->timestamp = timestamp;
            new_event->next = sessions[i].events;
            sessions[i].events = new_event;
            break;
        }
    }
}
