// Define the function to execute a given command in the background using the fork and wait system calls
fn executeBackgroundCommand(command: &str) -> i32 {
    // Fork a new process to execute the given command
    let pid = unsafe { fork() };
    if pid == -1 {
        return -1; // Return error code on failure to fork a new process
    } else if pid == 0 {
        // In the child process, execute the given command and exit with the status code
        let status = std::process::Command::new("sh")
            .arg("-c")
            .arg(command)
            .spawn()
            .unwrap()
            .wait()
            .unwrap();
        unsafe { _exit(status.code().unwrap_or(-1)); }
    } else {
        // In the parent process, wait for the child process to finish and return its status code
        let mut status = -1;
        while status == -1 {
            match unsafe { waitpid(pid, &mut status as *mut i32, 0) } {
                Ok(_) => break, // Break out of the loop on successful completion of the child process
                Err(_) => std::thread::sleep(std::time::Duration::from_secs(1)), // Sleep for one second and try again if there is an error
            }
        }
        return status; // Return the status code from the child process
    }
}

