using namespace std;
using namespace boost::asio;
using namespace boost::json;

class NetworkManager {
public:
    NetworkManager(const string& ipAddress, const unsigned short port) : io_service(), socket(io_service), resolver(io_service), interfaceTable() {
        // Initialize the network interface table
        interfaceTable = make_shared<InterfaceTable>();

        // Set up the socket for connecting to the API service
        socket.connect(ipAddress, port);

        // Set up the timer for sending GET requests to validate network health
        timer = io_service.make_unique<steady_timer>(io_service);
        timer->expires_from_now(chrono::seconds(10));
        timer->async_wait([this](const error_code& ec) {
            if (!ec) {
                // Send a GET request to the API service to validate network health
                string request = "GET /network/health HTTP/1.1\r\nHost: api.example.com\r\n\r\n";
                write(request);
            }
        });
    }

    void addNetworkInterface(const NetworkInterfaceConfig& config) {
        // Check if the interface ID is already in use
        if (interfaceTable->find(config.interfaceId)) {
            throw runtime_error("Duplicate network interface ID");
        }

        // Add the new interface to the interface table
        interfaceTable->add(config);

        // Send a POST request to the API service with the new interface configuration
        string request = "POST /network/interfaces HTTP/1.1\r\nHost: api.example.com\r\nContent-Type: application/json\r\n";
