        // Check if the interface ID is already in use
        if (!interfaceTable->find(config.interfaceId)) {
            throw runtime_error("Invalid network interface ID");
        }

        // Remove the interface from the interface table
        interfaceTable->remove(config);

        // Send a DELETE request to the API service with the removed interface configuration
        string request = "DELETE /network/interfaces HTTP/1.1\r\nHost: api.example.com\r\nContent-Type: application/json\r\n";
        write(request);
    }

    void updateSRSParameters(const NetworkInterfaceConfig& config, const SRSParameters& srsParams) {
        // Check if the interface ID is already in use
        if (!interfaceTable->find(config.interfaceId)) {
            throw runtime_error("Invalid network interface ID");
        }

        // Update the SRS parameters for the interface
        interfaceTable->get(config.interfaceId).srsParams = srsParams;

        // Send a PUT request to the API service with the updated SRS parameters
        string request = "PUT /network/interfaces/srs HTTP/1.1\r\nHost: api.example.com\r\nContent-Type: application/json\r\n";
        write(request);
    }

    void updateNeighborCellInfo(const NetworkInterfaceConfig& config, const vector<NeighborCellInfo>& neighborInfos) {
        // Check if the interface ID is already in use
        if (!interfaceTable->find(config.interfaceId)) {
            throw runtime_error("Invalid network interface ID");
        }

        // Update the neighbor cell information for the interface
        interfaceTable->get(config.interfaceId).neighborInfos = neighborInfos;

        // Send a PUT request to the API service with the updated neighbor cell information
        string request = "PUT /network/interfaces/neighbors HTTP/1.1\r\nHost: api.example.com\r\nContent-Type: application/json\r\n";
        write(request);
    }

private:
