// Memory pool allocator
struct mempool {
    struct node *head; // Pointer to the head of the list
    size_t size;       // Size of each element in the pool
    size_t n;          // Number of elements in the pool
};

// Node structure for the memory pool
struct node {
    void *data;   // Data pointer
    struct node *next; // Pointer to the next node
};

// Initialize a memory pool with a given number of elements and size
void mempool_init(struct mempool *pool, size_t n, size_t size) {
    pool->size = size;
    pool->n = n;
    pool->head = NULL;
}

// Allocate an element from the memory pool
void* mempool_alloc(struct mempool *pool) {
    if (pool->head == NULL) {
        return NULL;
    }

    void *data = pool->head->data;
    struct node *next = pool->head->next;
    free(pool->head);
    pool->head = next;

    return data;
}

// Free an element back to the memory pool
void mempool_free(struct mempool *pool, void *data) {
    struct node *node = malloc(sizeof(struct node));
    node->data = data;
    node->next = pool->head;
    pool->head = node;
}

// C function for allocating and initializing an array of NFAPI_CRC_INDICATION_PDU_T structures
