// HTTP client module for interacting with the remote API endpoint
pub mod http_client {
    use reqwest::blocking::Client;

    pub fn configure(timeout: u64) -> Client {
        let mut builder = Client::builder();

        // Set the timeout to the specified value
        builder.timeout(Duration::from_secs(timeout));

        // Build and return the HTTP client
        builder.build().unwrap()
    }
}
```
