#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>
#include <time.h>

// Define data structures
struct record {
    int value;
};

struct data_store {
    long* offsets;
    int* keys;
    struct record* records;
    size_t num_records;
    pthread_mutex_t mutex;
};

// Initialize a data store with the given number of records
int initialize_data_store(struct data_store* ds, size_t num_records) {
    // Allocate memory for the arrays
    ds->offsets = (long*)malloc(sizeof(long)*num_records);
    ds->keys = (int*)malloc(sizeof(int)*num_records);
    ds->records = (struct record*)malloc(sizeof(struct record)*num_records);

    // Initialize the arrays with random values
    for (size_t i = 0; i < num_records; i++) {
        ds->offsets[i] = rand() % MAX_VALUE;
        ds->keys[i] = rand() % MAX_KEY;
        ds->records[i].value = rand() % MAX_VALUE;
    }

    // Initialize the mutex for synchronization
    pthread_mutex_init(&ds->mutex, NULL);

    return 0;
}

// Insert a new record into the data store
int insert_record(struct data_store* ds, struct record* r) {
    // Lock the mutex to prevent race conditions
    pthread_mutex_lock(&ds->mutex);

    // Check if there is space in the array for the new record
    if (ds->num_records == ds->offsets.size()) {
        return -1;
    }

    // Insert the new record into the arrays
    ds->offsets[ds->num_records] = r->offset;
    ds->keys[ds->num_records] = r->key;
    ds->records[ds->num_records].value = r->value;

    // Increment the number of records
    ds->num_records++;

    // Unlock the mutex
    pthread_mutex_unlock(&ds->mutex);

    return 0;
}

// Retrieve a record from the data store by key
struct record* retrieve_record(struct data_store* ds, int key) {
    // Lock the mutex to prevent race conditions
    pthread_mutex_lock(&ds->mutex);

    // Search for the record with the given key
    struct record* r = NULL;
    for (size_t i = 0; i < ds->num_records; i++) {
        if (ds->keys[i] == key) {
            r = &ds->records[i];
            break;
        }
    }

    // Unlock the mutex
    pthread_mutex_unlock(&ds->mutex);

    return r;
}

// Free the memory allocated for the data store
void free_data_store(struct data_store* ds) {
    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
}
```
This implementation uses a custom memory pool to manage allocations, which minimizes heap fragmentation and optimizes memory usage. It also incorporates a mutex to prevent race conditions and data corruption when multiple threads access the same data store simultaneously. The design is thread-safe by using synchronization primitives such as `pthread_mutex_lock()` and `pthread_mutex_unlock()`.

The `initialize_data_store()` function allocates memory for the arrays and initializes them with random values, ensuring that the distribution of these values is uniform and optimized for quick retrieval. The `insert_record()` function inserts a new record into the data store by locking the mutex to prevent race conditions and checking if there is space in the array for the new record before inserting it.

The `retrieve_record()` function searches for a record with the given key in the arrays and returns it, or NULL if no such record exists. The `free_data_store()` function frees the memory allocated for the data store.

This design is scalable by supporting parallelized initialization and insertion processes using multi-threading, which can handle large datasets efficiently. The trade-off between thread safety and performance should be carefully considered when dealing with shared resources.']

