#include <stdlib.h>
#include <stdio.h>
#include <stdbool.h>

typedef struct {
    long offset;
    int key;
} Record;

void manageMemory(long offsetSize, int keySize, int recordSize) {
    // Allocate memory for the arrays
    long *offsetArray = malloc(sizeof(long) * offsetSize);
    int *keyArray = malloc(sizeof(int) * keySize);
    Record *recordArray = malloc(sizeof(Record) * recordSize);

    // Check if allocation was successful
    if (offsetArray == NULL || keyArray == NULL || recordArray == NULL) {
        printf("Memory allocation failed. Exiting...");
        exit(1);
    }

    // Populate the 'key' field of each 'record' structure with unique values from the 'int' array, ensuring no duplicates within the same structure
    for (int i = 0; i < recordSize; i++) {
        int key = rand() % keySize;
        while (findKey(keyArray, keySize, key)) {
            // Key is already in use. Generate a new random number
            key = rand() % keySize;
        }
        recordArray[i].key = key;
    }

    // Set the 'offset' field of each 'record' structure to a random value within a specified range, avoiding zero to prevent indexing errors
    srand(time(NULL));
    for (int i = 0; i < recordSize; i++) {
        long offset = rand() % (offsetSize - 1) + 1;
        while (findOffset(offsetArray, offsetSize, offset)) {
            // Offset is already in use. Generate a new random number
            offset = rand() % (offsetSize - 1) + 1;
        }
        recordArray[i].offset = offset;
    }

    // Free memory for the arrays when they are no longer needed
    free(offsetArray);
    free(keyArray);
    free(recordArray);
}

bool findKey(int *keyArray, int keySize, int key) {
    for (int i = 0; i < keySize; i++) {
        if (keyArray[i] == key) {
            return true;
        }
    }
    return false;
}

bool findOffset(long *offsetArray, int offsetSize, long offset) {
    for (int i = 0; i < offsetSize; i++) {
        if (offsetArray[i] == offset) {
            return true;
        }
    }
    return false;
}

void resetRandomNumberGenerator(long seed) {
    srand(seed);
}

int main() {
    long offsetSize = 1000000; // Change this to a smaller value for testing
    int keySize = 500000; // Change this to a smaller value for testing
    int recordSize = 500000; // Change this to a smaller value for testing
    manageMemory(offsetSize, keySize, recordSize);
    return 0;
}']

['  #include <stdio.h>
  #include <stdlib.h>
  #include <string.h>
  #include <sys/types.h>
  #include <sys/stat.h>
  #include <fcntl.h>
  #include <unistd.h>
  #include <openssl/conf.h>
  #include <openssl/evp.h>
  #include <openssl/err.h>

  int encryptFile(const char* inputPath, const char* outputPath) {
      // Check if the input file exists and is readable
      struct stat st;
      if (stat(inputPath, &st) == -1) {
          perror("stat");
          return EXIT_FAILURE;
      }

      // Check if we have enough disk space to encrypt the file
      off_t inputSize = st.st_size;
      struct statvfs svf;
      if (statvfs(outputPath, &svf) == -1) {
          perror("statvfs");
          return EXIT_FAILURE;
      }

      // Calculate the size of the output file based on the input file and add a buffer for encryption overhead
      off_t outputSize = inputSize + (inputSize / 10);
      if (svf.f_bavail < outputSize) {
          fprintf(stderr, "Insufficient disk space to encrypt file\n");
          return EXIT_FAILURE;
      }

      // Open the input and output files in binary mode
      int inputFd = open(inputPath, O_RDONLY);
      if (inputFd == -1) {
          perror("open");
          return EXIT_FAILURE;
      }

      int outputFd = open(outputPath, O_WRONLY | O_CREAT, 0644);
      if (outputFd == -1) {
          perror("open");
          close(inputFd);
          return EXIT_FAILURE;
      }

      // Initialize the EVP context for AES-256-CBC encryption
      EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
      if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, NULL, NULL)) {
          perror("EVP_EncryptInit_ex");
          close(inputFd);
          close(outputFd);
          return EXIT_FAILURE;
      }

      // Allocate memory for the input and output buffers
      size_t bufferSize = 4096;
      unsigned char *inputBuffer = malloc(bufferSize);
      if (!inputBuffer) {
          perror("malloc");
          close(inputFd);
          close(outputFd);
          EVP_CIPHER_CTX_free(ctx);
          return EXIT_FAILURE;
      }

      unsigned char *outputBuffer = malloc(bufferSize + 16);
      if (!outputBuffer) {
          perror("malloc");
          free(inputBuffer);
          close(inputFd);
          close(outputFd);
          EVP_CIPHER_CTX_free(ctx);
          return EXIT_FAILURE;
      }

      // Read the input file in chunks and encrypt it to the output file
      int bytesRead, totalBytesRead = 0;
      while ((bytesRead = read(inputFd, inputBuffer, bufferSize)) > 0) {
          totalBytesRead += bytesRead;

          // Update the EVP context with the new chunk of data
          if (!EVP_EncryptUpdate(ctx, outputBuffer, &bytesRead, inputBuffer, bytesRead)) {
              perror("EVP_EncryptUpdate");
              close(inputFd);
              close(outputFd);
              free(inputBuffer);
              free(outputBuffer);
              EVP_CIPHER_CTX_free(ctx);
              return EXIT_FAILURE;
          }

          // Write the encrypted chunk to the output file
          if (write(outputFd, outputBuffer, bytesRead) != bytesRead) {
              perror("write");
              close(inputFd);
              close(outputFd);
              free(inputBuffer);
              free(outputBuffer);
              EVP_CIPHER_CTX_free(ctx);
              return EXIT_FAILURE;
          }
      }

      // Finalize the encryption and write any remaining data to the output file
      int bytesWritten = 0;
      if (!EVP_EncryptFinal_ex(ctx, outputBuffer + bytesWritten, &bytesWritten)) {
          perror("EVP_EncryptFinal_ex");
          close(inputFd);
          close(outputFd);
          free(inputBuffer);
          free(outputBuffer);
          EVP_CIPHER_CTX_free(ctx);
          return EXIT_FAILURE;
      }

      if (write(outputFd, outputBuffer, bytesWritten) != bytesWritten) {
          perror("write");
          close(inputFd);
          close(outputFd);
          free(inputBuffer);
          free(outputBuffer);
          EVP_CIPHER_CTX_free(ctx);
          return EXIT_FAILURE;
      }

      // Clean up resources and return success
      close(inputFd);
      close(outputFd);
      free(inputBuffer);
      free(outputBuffer);
      EVP_CIPHER_CTX_free(ctx);
      return EXIT_SUCCESS;
  }']

