    // Initialize Log4j, NLog, and SLF4J logging frameworks
    log4j_init();
    nlog_init();
    slf4j_init();
}

void deinit_logging() {
    // Deinitialize Log4j, NLog, and SLF4J logging frameworks
    log4j_deinit();
    nlog_deinit();
    slf4j_deinit();
}

