    // Initialize temperature readings, time zones, and timestamps arrays
    srand(time(NULL)); // Seed random number generator with current time
    for (int i = 0; i < NUM_READINGS; ++i) {
        temperatures[i] = rand() % 100; // Generate a random temperature reading between 0 and 99
