        strcpy(tz, "America/New_York"); // Initialize time zone string to "America/New_York"
        time_zones[i] = tz;
        timestamps[i] = (unsigned long) time(NULL); // Get current timestamp in seconds since epoch
    }
}

void deinit_temp_readings(float *temperatures, char **time_zones, unsigned long *timestamps) {
