    while (num_calls < NUM_CALLS) {
        update_temperatures(temperatures); // Update temperature readings using weather API
        num_calls++;
        sleep(api_call_interval); // Wait for the specified interval before making the next API call
    }
}

void configure_logging() {
    // Configure logging output preferences based on configuration file
    FILE *log_file = fopen("log.txt", "w"); // Open log file in write mode
    if (log_file == NULL) {
        printf("Error opening log file\n");
        return;
    }
    char *config_file = "logging_config.json"; // Configuration file for logging output preferences
    struct log_entry *entries = read_config(config_file); // Read configuration file and get array of 'log_entry' structures
    if (entries == NULL) {
        printf("Error reading logging configuration\n");
        fclose(log_file);
        return;
    }
    for (int i = 0; i < NUM_ENTRIES; ++i) {
        switch (entries[i].log_level) {
            case DEBUG:
                log4j_debug(entries[i].time_zone, "Temperature: %.2f°C", entries[i].temperature); // Log debug message to file
                break;
            case INFO:
                nlog_info(entries[i].time_zone, "Temperature: %.2f°C", entries[i].temperature); // Log info message to console
                slf4j_info("{} Temperature: {}°C", entries[i].time_zone, entries[i].temperature); // Log info message to network
                break;
            case WARN:
                log4j_warn(entries[i].time_zone, "Temperature: %.2f°C (potential danger)", entries[i].temperature); // Log warn message to file
                nlog_warn(entries[i].time_zone, "Temperature: {}°C (potential danger)", entries[i].temperature); // Log warn message to console
                slf4j_warn("{} Temperature: {}°C (potential danger)", entries[i].time_zone, entries[i].temperature); // Log warn message to network
                break;
            case ERROR:
                log4j_error(entries[i].time_zone, "Temperature: %.2f°C (critical error)", entries[i].temperature); // Log error message to file
                nlog_error(entries[i].time_zone, "Temperature: {}°C (critical error)", entries[i].temperature); // Log error message to console
                slf4j_error("{} Temperature: {}°C (critical error)", entries[i].time_zone, entries[i].temperature); // Log error message to network
                break;
        }
    }
    free(entries); // Free memory for 'log_entry' structures
    fclose(log_file); // Close log file
}

int main() {
    float temperatures[NUM_READINGS]; // Array of temperature readings
    char *time_zones[NUM_READINGS]; // Array of time zones for each reading
    unsigned long timestamps[NUM_READINGS]; // Array of timestamps for each reading
    init_temp_readings(temperatures, time_zones, timestamps); // Initialize temperature readings and arrays
    update_temp_readings(temperatures, time_zones, timestamps); // Update temperature readings with real-time data from weather API
    deinit_temp_readings(temperatures, time_zones, timestamps); // Deallocate memory for temperature readings and arrays
    configure_logging(); // Configure logging output preferences based on configuration file
    return 0;
}
