    for (size_t i = 0; i < offsetSize; i++) {
        offsetArray[i].offset = rand() % MAX_RAND_VALUE + MIN_RAND_VALUE;
    }

    // Populate the key array with unique values from the offset array
    for (size_t i = 0; i < keySize; i++) {
        int offset = offsetArray[i].offset;
        bool isUnique = true;
        while (!isUnique) {
            // Generate a random index within the offset array range
            size_t j = rand() % (offsetSize - 1);

            // Check if the generated value is unique
            int compareValue = offsetArray[j].offset;
            if (compareValue != offset) {
                keyArray[i] = compareValue;
                isUnique = true;
            }
        }
    }
}

// Function to validate an offset value
bool validateOffset(Record* record) {
    return record->offset >= MIN_RAND_VALUE && record->offset <= MAX_RAND_VALUE;
}

// Function to validate a key value
bool validateKey(int* key) {
    return *key >= 0;
}

// Function to set the random offset values for each record structure
void setOffsetValues(Record* offsetArray, size_t offsetSize) {
    // Reset the random number generator before populating the 'offset' fields
    srand((unsigned) time(NULL));

    // Set the 'offset' field of each record structure to a random value within the specified range
    for (size_t i = 0; i < offsetSize; i++) {
        offsetArray[i].offset = rand() % MAX_RAND_VALUE + MIN_RAND_VALUE;
    }
}

// Function to handle memory allocation errors and provide error messages
void handleError(char* message) {
    printf("%s\n", message);
}

// Function to reset the random number generator before populating the 'offset' fields
void resetRandGen() {
    srand((unsigned) time(NULL));
}

// Thread-safe function to populate the arrays with data
void populateArraysThreadSafe(Record* offsetArray, int* keyArray, size_t offsetSize, size_t keySize) {
    // Use a mutex to synchronize access to the 'offset' and 'key' arrays
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Allocate memory for the offset array
    offsetArray = (Record*) malloc(offsetSize * RECORD_STRUCT_SIZE);
    if (!offsetArray) {
        handleError("Error: Failed to allocate memory for offset array\n");
        return;
    }

    // Allocate memory for the key array
    keyArray = (int*) malloc(keySize * sizeof(int));
    if (!keyArray) {
        handleError("Error: Failed to allocate memory for key array\n");
        free(offsetArray);
        return;
    }

    // Initialize and validate the offset array
    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < offsetSize; i++) {
        offsetArray[i].offset = -1;
        if (!validateOffset(&offsetArray[i])) {
            handleError("Error: Invalid offset value\n");
            pthread_mutex_unlock(&mutex);
            return;
        }
    }
    pthread_mutex_unlock(&mutex);

    // Initialize and validate the key array
    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < keySize; i++) {
        keyArray[i] = -1;
        if (!validateKey(&keyArray[i])) {
            handleError("Error: Invalid key value\n");
            pthread_mutex_unlock(&mutex);
            return;
        }
    }
    pthread_mutex_unlock(&mutex);

    // Populate the offset array with random values
    srand((unsigned) time(NULL));
    for (size_t i = 0; i < offsetSize; i++) {
        offsetArray[i].offset = rand() % MAX_RAND_VALUE + MIN_RAND_VALUE;
    }

    // Populate the key array with unique values from the offset array
    for (size_t i = 0; i < keySize; i++) {
        int offset = offsetArray[i].offset;
        bool isUnique = true;
        while (!isUnique) {
            // Generate a random index within the offset array range
            size_t j = rand() % (offsetSize - 1);

            // Check if the generated value is unique
            int compareValue = offsetArray[j].offset;
            if (compareValue != offset) {
                keyArray[i] = compareValue;
                isUnique = true;
            }
        }
    }
}

// Function to handle memory allocation errors and provide error messages
