    printf("%s\n", message);
}

// Graph traversal function
void traverseGraph(int** graph, int numVertices, int startVertex) {
    // Mark all the vertices as not visited
    bool* visited = (bool*) malloc(numVertices * sizeof(bool));
    for (int i = 0; i < numVertices; i++) {
        visited[i] = false;
    }

    // Create a queue for BFS
    int* queue = (int*) malloc(sizeof(int) * numVertices);
    int front = -1, rear = -1;

    // Mark the starting vertex as visited and enqueue it
    visited[startVertex] = true;
    queue[++rear] = startVertex;

    while (front <= rear) {
        // Dequeue a vertex from queue
        int vertex = queue[++front];

        // Print the dequeued vertex
        printf("%d ", vertex);

        // Get all adjacent vertices of the dequeued vertex
        for (int i = 0; i < numVertices; i++) {
            if (graph[vertex][i] == 1 && !visited[i]) {
                visited[i] = true;
                queue[++rear] = i;
            }
        }
    }
}

// Function to handle memory allocation errors and provide error messages for graphs
void handleErrorGraph(char* message) {
    printf("%s\n", message);
}

