// Structure to hold configuration for a single network interface
typedef struct NetworkInterfaceConfig {
    int interfaceId;
    NeighborCellInfo* neighborCellList;
    SoundingReferenceSignalParams srsParams;
} NetworkInterfaceConfig;

// Structure to hold information about a neighboring cell
typedef struct NeighborCellInfo {
    int neighborId;
    long lastModifiedTime; // Timestamp indicating when this entry was last updated
} NeighborCellInfo;

// Structure to hold configuration for Sounding Reference Signal parameters
typedef struct SoundingReferenceSignalParams {
    int srsConfigIndex;
    int bandwidth;
    int frequency;
} SoundingReferenceSignalParams;

// Global variable to hold the number of neighbor cells in the list
int numNeighborCells = 0;

// Global variable to hold the maximum number of neighbor cells that can be stored in the list
int maxNumNeighborCells = 100;

// Global variable to hold the current size of the neighbor cell list
int currentSize = 0;

// Lock used to protect access to the global variables and the neighbor cell list
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize a dynamic array of NetworkInterfaceConfig structures
void initializeNetworkInterfaces(int numInterfaces) {
    // Lock the mutex to prevent race conditions during access to global variables
    pthread_mutex_lock(&lock);

    // Allocate memory for the network interface list and set its size
    NetworkInterfaceConfig* networkInterfaces = malloc(sizeof(NetworkInterfaceConfig) * numInterfaces);
    currentSize = 0;

    // Unlock the mutex to allow other threads access to the global variables and the neighbor cell list
    pthread_mutex_unlock(&lock);
}

// Function to populate a dynamic array of NetworkInterfaceConfig structures with information about neighboring cells
void populateNetworkInterfaces(int numNeighborCells, int interfaceId) {
    // Lock the mutex to prevent race conditions during access to global variables
    pthread_mutex_lock(&lock);

    // Check if there is enough memory allocated for the new neighbor cells
    if (numNeighborCells + currentSize > maxNumNeighborCells) {
        printf("Error: Not enough memory allocated for %d neighbor cells\n", numNeighborCells);
        return;
    }

    // Allocate memory for the new neighbor cells and initialize their structures
    NeighborCellInfo* neighborCells = malloc(sizeof(NeighborCellInfo) * numNeighborCells);
    SoundingReferenceSignalParams* srsParams = malloc(sizeof(SoundingReferenceSignalParams) * numNeighborCells);

    // Loop through the new neighbor cells and populate their structures
    for (int i = 0; i < numNeighborCells; ++i) {
        neighborCells[i].neighborId = interfaceId + i;
        srsParams[i].srsConfigIndex = i % 2 == 0 ? 1 : 2;
        srsParams[i].bandwidth = i % 3 == 0 ? 1500 : 500;
        srsParams[i].frequency = i % 4 == 0 ? 1920 : 2160;
    }

    // Add the new neighbor cells to the list and update the current size
    NetworkInterfaceConfig* interface = &networkInterfaces[currentSize];
    interface->interfaceId = interfaceId;
    interface->neighborCellList = neighborCells;
    interface->srsParams = srsParams;
    currentSize += numNeighborCells;

    // Unlock the mutex to allow other threads access to the global variables and the neighbor cell list
    pthread_mutex_unlock(&lock);
}

// Function to update a dynamic array of NetworkInterfaceConfig structures with information about changes in the network configuration
void updateNetworkInterfaces(int numUpdatedNeighborCells, int interfaceId) {
    // Lock the mutex to prevent race conditions during access to global variables
    pthread_mutex_lock(&lock);

    // Check if there are any updated neighbor cells that need to be added or removed from the list
    int numUpdatedNeighbors = 0;
    for (int i = 0; i < numUpdatedNeighborCells; ++i) {
        if (neighborCellList[interfaceId + i].lastModifiedTime != currentTime) {
            numUpdatedNeighbors++;
        }
    }

    // Check if there are any neighbor cells that need to be removed from the list
    int numRemovedNeighbors = 0;
    for (int i = 0; i < currentSize; ++i) {
        if (networkInterfaces[i].interfaceId != interfaceId + i) {
            numRemovedNeighbors++;
        }
    }

    // Allocate memory for the updated neighbor cells and initialize their structures
    NeighborCellInfo* updatedNeighborCells = malloc(sizeof(NeighborCellInfo) * numUpdatedNeighbors);
    SoundingReferenceSignalParams* updatedSrsParams = malloc(sizeof(SoundingReferenceSignalParams) * numUpdatedNeighbors);

    // Loop through the updated neighbor cells and populate their structures
    for (int i = 0; i < numUpdatedNeighborCells; ++i) {
        int index = interfaceId + i;
        if (neighborCellList[index].lastModifiedTime != currentTime) {
            updatedNeighborCells[numRemovedNeighbors].neighborId = index;
            updatedSrsParams[numRemovedNeighbors++].srsConfigIndex = i % 2 == 0 ? 1 : 2;
            updatedSrsParams[numRemovedNeighbors++].bandwidth = i % 3 == 0 ? 1500 : 500;
            updatedSrsParams[numRemovedNeighbors++].frequency = i % 4 == 0 ? 1920 : 2160;
        }
    }

    // Remove the removed neighbor cells from the list and update the current size
    for (int i = numRemovedNeighbors - 1; i >= 0; --i) {
        networkInterfaces[numRemovedNeighbors].interfaceId = interfaceId + i;
        free(networkInterfaces[numRemovedNeighbors].neighborCellList);
        free(networkInterfaces[numRemovedNeighbors].srsParams);
        currentSize--;
    }

    // Add the updated neighbor cells to the list and update the current size
    for (int i = 0; i < numUpdatedNeighborCells; ++i) {
        int index = interfaceId + i;
        if (neighborCellList[index].lastModifiedTime != currentTime) {
            NetworkInterfaceConfig* interface = &networkInterfaces[currentSize];
            interface->interfaceId = interfaceId;
            interface->neighborCellList = updatedNeighborCells;
            interface->srsParams = updatedSrsParams;
            currentSize++;
        }
    }

    // Unlock the mutex to allow other threads access to the global variables and the neighbor cell list
    pthread_mutex_unlock(&lock);
}
