    perror("fopen");
    return;
  }

  // Write the serialized data to the file
  for (int i = 0; i < N; ++i) {
    int bytesWritten = fwrite(&pduList[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, fp);
    if (bytesWritten != sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
      perror("fwrite");
      break;
    }
  }

  // Close the file and release the memory for the list of structures
  fclose(fp);
  free(pduList);
}
