import threading
from collections import defaultdict
from typing import Dict, List, Optional

class ResourceManager:
    def __init__(self):
        self._lock = threading.Lock()
        self._resources: Dict[str, Dict[str, any]] = defaultdict(dict)

    def add_resource(self, resource_id: str, status: str, metadata: Dict[str, any]) -> None:
        with self._lock:
            if resource_id in self._resources:
                raise ValueError(f"Resource ID '{resource_id}' already exists")
            self._resources[resource_id] = {
                "status": status,
                "metadata": metadata,
            }

    def get_resource(self, resource_id: str) -> Optional[Dict[str, any]]:
        with self._lock:
            return self._resources.get(resource_id, None)

    def update_resource(self, resource_id: str, status: str, metadata: Dict[str, any]) -> None:
        with self._lock:
            if resource_id not in self._resources:
                raise ValueError(f"Resource ID '{resource_id}' does not exist")
            self._resources[resource_id]["status"] = status
            self._resources[resource_id]["metadata"].update(metadata)

    def remove_resource(self, resource_id: str) -> None:
        with self._lock:
            if resource_id not in self._resources:
                raise ValueError(f"Resource ID '{resource_id}' does not exist")
            del self._resources[resource_id]

    def list_resources(self) -> List[Dict[str, any]]:
        with self._lock:
            return list(self._resources.values())

    def _validate_metadata(self, metadata: Dict[str, any]) -> None:
        """Validates the integrity of the metadata by checking for duplicate keys."""
        if len(set(metadata.keys())) != len(metadata):
            raise ValueError("Duplicate keys in metadata")
