    new_profile->id = id;
    new_profile->username = strdup(username);
    new_profile->email = strdup(email);
    return new_profile;
}

// Function to add a profile to the dynamic array of user profiles
UserProfile** addProfile(long id, char* username, char* email) {
    // Increment the size of the dynamic array by 1
    int old_size = sizeof(profiles) / sizeof(UserProfile*);
    int new_size = old_size + 1;
    profiles = (UserProfile**)realloc(profiles, new_size * sizeof(UserProfile*));

    // Create a new profile with the given ID, username, and email address
    UserProfile* new_profile = createProfile(id, username, email);

    // Add the new profile to the dynamic array
    profiles[old_size] = new_profile;

    return profiles;
}

// Function to check for uniqueness of usernames
int isUniqueUsername(char* username) {
    // Iterate over all user profiles and check if any have the same username
    for (int i = 0; i < sizeof(profiles) / sizeof(UserProfile*); i++) {
        UserProfile* profile = profiles[i];
        if (strcasecmp(profile->username, username) == 0) {
            return 0;
        }
    }

    // If we reach this point, the username is unique
    return 1;
}

// Function to check for validity of user IDs
int isValidUserId(long id) {
    // Check if the user ID is within the bounds of the data type
    if (id > INT_MAX || id < INT_MIN) {
        return 0;
    }

    // If we reach this point, the user ID is valid
    return 1;
}

// Function to validate the integrity of the data post-initialization
void validateData() {
    // Iterate over all user profiles and check for uniqueness of usernames
    for (int i = 0; i < sizeof(profiles) / sizeof(UserProfile*); i++) {
        UserProfile* profile = profiles[i];
        if (!isUniqueUsername(profile->username)) {
            printf("Duplicate username: %s\n", profile->username);
        }
    }
}

// Function to identify and print the longest string among stored user inputs
void findLongestString() {
    // Initialize the longest string to an empty string
    char* longest_string = "";

    // Iterate over all user profiles and compare the length of each username
    for (int i = 0; i < sizeof(profiles) / sizeof(UserProfile*); i++) {
        UserProfile* profile = profiles[i];
        if (strlen(profile->username) > strlen(longest_string)) {
            longest_string = profile->username;
        }
    }

    // Print the longest string
    printf("Longest string: %s\n", longest_string);
}

// Function to handle concurrent access from multiple threads and ensure thread safety
void manageThreads() {
    // Create a mutex for synchronizing access to the dynamic array of user profiles
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Iterate over all user inputs and handle them concurrently using threads
    while (1) {
        // Get the next line from stdin
