// Define function to dynamically manage list of NFAPI_CRC_INDICATION_PDU_T structures
void nfapi_crc_indication_list_manage(NFAPI_CRC_INDICATION_LIST *list, uint32_t rnti) {
    // Acquire lock for list modification
    pthread_mutex_lock(&list->mutex);

    // Check if RNTI is already in the list
    bool found = false;
    for (size_t i = 0; i < list->count; i++) {
        if (list->data[i].rnti == rnti) {
            found = true;
            break;
        }
    }

    // If RNTI is not in the list, add it
    if (!found) {
        NFAPI_CRC_INDICATION_PDU_T *newEntry = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
