// Define a linked list to store the MAC_PDU structures
struct mac_pdu_list {
    struct mac_pdu *head;
    struct mac_pdu *tail;
    int size;
    pthread_mutex_t lock; // Mutex to protect access to the list
};

// Initialize the linked list with an empty head and tail
struct mac_pdu_list* initialize_mac_pdu_list() {
    struct mac_pdu_list *list = malloc(sizeof(struct mac_pdu_list));
    if (!list) {
        printf("Error: Could not allocate memory for the MAC PDU list\n");
        return NULL;
    }
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Add a new MAC_PDU structure to the linked list
void add_mac_pdu(struct mac_pdu_list *list, struct mac_pdu *pdu) {
    pthread_mutex_lock(&list->lock);
    // Check if the list is empty
    if (list->head == NULL) {
        list->head = pdu;
        list->tail = pdu;
    } else {
        list->tail->next = pdu;
        list->tail = pdu;
    }
    list->size++;
    pthread_mutex_unlock(&list->lock);
}

// Remove a MAC_PDU structure from the linked list
void remove_mac_pdu(struct mac_pdu_list *list, struct mac_pdu *pdu) {
    pthread_mutex_lock(&list->lock);
    // Check if the list is empty
    if (list->head == NULL) {
        printf("Error: Could not remove MAC PDU from the list\n");
        return;
    }
    struct mac_pdu *current = list->head;
    while (current != NULL && current != pdu) {
        current = current->next;
    }
    if (current == NULL) {
        printf("Error: Could not find MAC PDU in the list\n");
        return;
    }
    // Remove the node from the linked list
    if (current == list->head) {
        list->head = current->next;
    } else {
        struct mac_pdu *previous = current->previous;
        previous->next = current->next;
        if (list->tail == current) {
            list->tail = previous;
        }
    }
    // Free the memory allocated for the node
    free(current);
    list->size--;
    pthread_mutex_unlock(&list->lock);
}

// Print all the MAC_PDU structures in the linked list
void print_mac_pdu_list(struct mac_pdu_list *list) {
    pthread_mutex_lock(&list->lock);
    struct mac_pdu *current = list->head;
    while (current != NULL) {
        printf("MAC PDU: %d\n", current->header.seq_num);
        printf("\tHeader: %d\n", current->header.seq_num);
        printf("\tPayload: %s\n", current->macsdu.data);
        printf("\tTimestamp: %lld\n", current->timestamp);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

// Serialize the linked list to a binary format for efficient storage and retrieval
void serialize_mac_pdu_list(struct mac_pdu_list *list, char *buffer) {
    pthread_mutex_lock(&list->lock);
    struct mac_pdu *current = list->head;
    int offset = 0;
    while (current != NULL) {
        // Serialize the MAC header
        memcpy(buffer + offset, &current->header.seq_num, sizeof(int));
        offset += sizeof(int);
        // Serialize the MAC payload
        memcpy(buffer + offset, current->macsdu.data, strlen(current->macsdu.data) + 1);
        offset += strlen(current->macsdu.data) + 1;
        // Serialize the timestamp
        memcpy(buffer + offset, &current->timestamp, sizeof(long long));
        offset += sizeof(long long);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

// Deserialize the linked list from a binary format
void deserialize_mac_pdu_list(struct mac_pdu_list *list, char *buffer) {
    pthread_mutex_lock(&list->lock);
    struct mac_pdu *current = list->head;
    int offset = 0;
    while (offset < strlen(buffer)) {
        // Deserialize the MAC header
        memcpy(&current->header.seq_num, buffer + offset, sizeof(int));
        offset += sizeof(int);
        // Deserialize the MAC payload
        memcpy(current->macsdu.data, buffer + offset, strlen(buffer) - offset);
        current->macsdu.data[strlen(buffer) - offset] = '\0';
        offset += strlen(buffer) - offset;
        // Deserialize the timestamp
        memcpy(&current->timestamp, buffer + offset, sizeof(long long));
        offset += sizeof(long long);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}
