// Define data structures for connection management
struct connection {
    int id;
    struct sockaddr_in addr;
};

struct record {
    int value;
};

int main(int argc, char **argv) {
    // Parse input parameters
    if (argc < 4) {
        printf("Usage: %s <port> <num_connections> <seed>\n", argv[0]);
        return 1;
    }

    int port = atoi(argv[1]);
    int num_connections = atoi(argv[2]);
    int seed = atoi(argv[3]);

    // Initialize arrays for offsets, keys, and records
    long *offsets = (long *)malloc(num_connections * sizeof(long));
    int *keys = (int *)malloc(num_connections * sizeof(int));
    struct record **records = (struct record **)malloc(num_connections * sizeof(struct record *));

    // Initialize connection pool and health-check mechanism
    struct connection connections[10000];
    int num_active_connections = 0;
    int num_passive_connections = 0;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cv = PTHREAD_COND_INITIALIZER;

    // Loop until all connections are established and active
    while (num_active_connections < num_connections) {
        // Establish connection to remote server using Java's NIO channels
        int sock = socket(AF_INET, SOCK_STREAM, 0);
        struct sockaddr_in addr;
        memset(&addr, 0, sizeof(struct sockaddr_in));
        addr.sin_family = AF_INET;
        addr.sin_port = htons(port);
        addr.sin_addr.s_addr = INADDR_ANY;

        if (connect(sock, (struct sockaddr *)&addr, sizeof(struct sockaddr_in)) < 0) {
            perror("connect");
            return 1;
        }

        // Allocate memory for record and populate with random integer value
        struct record *record = malloc(sizeof(struct record));
        record->value = rand_r(&seed) % 100 + 1;

        // Add connection to connection pool and increment active connections
        int id = num_active_connections++;
        connections[id].id = id;
        connections[id].addr = addr;
        records[id] = record;

        // Transition connection from passive to active state
        pthread_mutex_lock(&mutex);
        num_passive_connections--;
        num_active_connections++;
        pthread_cond_signal(&cv);
        pthread_mutex_unlock(&mutex);
    }

    // Loop until all connections are terminated and resources are released
    while (num_active_connections > 0) {
        // Handle connection events in separate thread to minimize overhead
        pthread_t thread;
        if (pthread_create(&thread, NULL, handle_connection_events, &connections[0]) != 0) {
            perror("pthread_create");
            return 1;
        }

        // Transition connection from active to passive state
        pthread_mutex_lock(&mutex);
        num_active_connections--;
        num_passive_connections++;
        pthread_cond_signal(&cv);
        pthread_mutex_unlock(&mutex);
    }

    // Release memory for offsets, keys, and records
    free(offsets);
    free(keys);
    for (int i = 0; i < num_connections; i++) {
        struct record *record = records[i];
        if (record != NULL) {
            free(record);
        }
    }
    free(records);

    return 0;
}

// Handle connection events in separate thread to minimize overhead
void *handle_connection_events(void *arg) {
    struct connection connections[10000];
    int num_active_connections = 0;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cv = PTHREAD_COND_INITIALIZER;

    // Loop until all connections are terminated and resources are released
    while (num_active_connections > 0) {
        // Wait for connection event to occur
        pthread_mutex_lock(&mutex);
        while (num_active_connections == 0) {
            pthread_cond_wait(&cv, &mutex);
        }
        num_active_connections--;
        pthread_mutex_unlock(&mutex);

        // Handle connection event
        int id = connections[num_active_connections].id;
        struct sockaddr_in addr = connections[num_active_connections].addr;
        int record = records[id]->value;
        printf("Connection %d: Record value is %d\n", id, record);
    }

    return NULL;
}
