typedef struct {
    int rnti;
    int crc_indication_rel8_tag;
    int additional_int_field;
} RX_UE_INFORMATION_TAG;

// Function to process a list of integers from standard input, storing them in a dynamically allocated array and managing a linked list of custom structures
void process_integer_list(int *input_array, int input_size) {
    // Determine the initial size of the linked list based on the first integer read from standard input
    int initial_linked_list_size = 1;
    while (initial_linked_list_size < input_size) {
        initial_linked_list_size *= 2;
    }

    // Allocate memory for the linked list and initialize it with the default values
    RX_UE_INFORMATION_TAG *rx_ue_information = malloc(sizeof(RX_UE_INFORMATION_TAG) * initial_linked_list_size);
    memset(rx_ue_information, 0, sizeof(RX_UE_INFORMATION_TAG) * initial_linked_list_size);

    // Loop through each integer in the input array and add it to the linked list
    for (int i = 0; i < input_size; i++) {
        if (i >= initial_linked_list_size) {
            // If the number of integers exceeds the initial allocated size of the linked list, reallocate and migrate data in powers of two
            int new_linked_list_size = initial_linked_list_size * 2;
            RX_UE_INFORMATION_TAG *new_rx_ue_information = realloc(rx_ue_information, sizeof(RX_UE_INFORMATION_TAG) * new_linked_list_size);
            if (new_rx_ue_information == NULL) {
                // If the reallocation fails, free the existing memory and exit the function
                free(rx_ue_information);
                return;
            }
            rx_ue_information = new_rx_ue_information;
            initial_linked_list_size *= 2;
        }

        // Set the RX UE information for the current integer and update the CRCFLAG value based on the additional integer field
        int crcflag = input_array[i] & rx_ue_information[i].additional_int_field;
        rx_ue_information[i].rnti = input_array[i];
        rx_ue_information[i].crc_indication_rel8_tag = crcflag ? 1 : 0;
    }

    // Free the memory allocated for the input array and return the linked list
    free(input_array);
    return rx_ue_information;
}

int main() {
    int input_size = 5;
    int *input_array = malloc(sizeof(int) * input_size);
    for (int i = 0; i < input_size; i++) {
        input_array[i] = i + 1;
    }
    RX_UE_INFORMATION_TAG *rx_ue_information = process_integer_list(input_array, input_size);
    for (int i = 0; i < input_size; i++) {
        printf("RNTI: %d, CRCFLAG: %d\n", rx_ue_information[i].rnti, rx_ue_information[i].crc_indication_rel8_tag);
    }
    free(rx_ue_information);
    return 0;
}
