#define MAX_NEIGHBOR_CELLS 100 // maximum number of neighbor cells per interface
#define MAX_RETRIES 3          // maximum number of initialization retries

typedef struct {
    int interfaceId;
    NeighborCellInfo *neighborCells[MAX_NEIGHBOR_CELLS];
    SoundingReferenceSignalParams srsParams;
} NetworkInterfaceConfig;

static void initializeNetworkConfig(NetworkInterfaceConfig **config) {
    // allocate memory for the network interface config array
    *config = (NetworkInterfaceConfig *)malloc(sizeof(NetworkInterfaceConfig) * MAX_NEIGHBOR_CELLS);
    if (*config == NULL) {
        perror("Error allocating memory for network interface config");
        return;
    }

    // initialize the SRS parameters using a predefined template
    for (int i = 0; i < MAX_NEIGHBOR_CELLS; i++) {
        (*config)[i].srsParams.srsEnabled = true;
        (*config)[i].srsParams.srsDuration = 200;
        (*config)[i].srsParams.srsPeriodicity = 500;
    }

    // fetch the maximum number of neighbor cells from the system configuration
    int maxNeighborCells = getMaximumNumberOfNeighborCells();

    // retrieve the SRS parameters from an external data source (e.g., a configuration file or database)
    for (int i = 0; i < MAX_NEIGHBOR_CELLS && i < maxNeighborCells; i++) {
        (*config)[i].srsParams = retrieveSRSParameters(i);
        if ((*config)[i].srsParams.srsEnabled == false) {
            break;
        }
    }

    // ensure no duplicate neighbor IDs within each interface config
    for (int i = 0; i < MAX_NEIGHBOR_CELLS && i < maxNeighborCells; i++) {
        for (int j = i + 1; j < MAX_NEIGHBOR_CELLS && j < maxNeighborCells; j++) {
            if ((*config)[i].neighborCells[j] != NULL) {
                fprintf(stderr, "Duplicate neighbor ID found in interface config %d\n", i);
                freeNetworkInterfaceConfig(*config);
                *config = NULL;
                return;
            }
        }
    }
