#include <stdio.h>

// Configuration structure for initialization parameters
struct Config {
    int max_records;   // Maximum number of records to store
    size_t record_size; // Size of each record in bytes
};

// Record structure for storing offset, key, and value
struct Record {
    long offset;   // Offset within the data buffer
    int key;      // Key for indexing the record
    int value;    // Value associated with the key
};

// Data structure for managing the array of records
struct RecordManager {
    struct Config config;     // Configuration parameters for the manager
    struct Record* records;  // Array of records
    size_t num_records;      // Number of records currently stored
    pthread_mutex_t mutex;   // Mutex for thread-safe access to the manager
};

// Initialize a record manager with a given configuration
void init_record_manager(struct RecordManager* rm, struct Config config) {
    // Allocate memory for the records array
    size_t record_size = sizeof(struct Record);
    rm->records = (struct Record*) malloc(config.max_records * record_size);
    if (!rm->records) {
        printf("Error: Failed to allocate memory for record manager\n");
        exit(1);
    }

    // Initialize the configuration parameters
    rm->config = config;

    // Set the number of records to zero
    rm->num_records = 0;
}

// Add a new record to the manager
void add_record(struct RecordManager* rm, struct Record record) {
    pthread_mutex_lock(&rm->mutex);

    // Check if there is space in the records array for the new record
    if (rm->num_records >= rm->config.max_records) {
        printf("Error: No space left in record manager\n");
        pthread_mutex_unlock(&rm->mutex);
        return;
    }

    // Copy the new record into the records array
    rm->records[rm->num_records] = record;

    // Increment the number of records
    rm->num_records++;

    pthread_mutex_unlock(&rm->mutex);
}

// Retrieve a record from the manager using its key
struct Record* get_record(struct RecordManager* rm, int key) {
    struct Record* result = NULL;
    pthread_mutex_lock(&rm->mutex);

    // Search for the record with the given key
    for (int i = 0; i < rm->num_records; i++) {
        if (rm->records[i].key == key) {
            result = &rm->records[i];
            break;
        }
    }

    pthread_mutex_unlock(&rm->mutex);

    return result;
}

// Update a record in the manager using its key
void update_record(struct RecordManager* rm, struct Record record) {
    pthread_mutex_lock(&rm->mutex);

    // Search for the record with the given key
    for (int i = 0; i < rm->num_records; i++) {
        if (rm->records[i].key == record.key) {
            // Update the record in place
            rm->records[i] = record;
            break;
        }
    }

    pthread_mutex_unlock(&rm->mutex);
}

// Remove a record from the manager using its key
void remove_record(struct RecordManager* rm, int key) {
    pthread_mutex_lock(&rm->mutex);

    // Search for the record with the given key
    for (int i = 0; i < rm->num_records; i++) {
        if (rm->records[i].key == key) {
            // Shift all records after the found record back by one index
            memmove(&rm->records[i], &rm->records[i + 1], (rm->num_records - i - 1) * sizeof(struct Record));
            rm->num_records--;
            break;
        }
    }

    pthread_mutex_unlock(&rm->mutex);
}

// Clean up the record manager and free its resources
void cleanup_record_manager(struct RecordManager* rm) {
    // Free the records array
    if (rm->records) {
        free(rm->records);
        rm->records = NULL;
    }
}

// Function for managing memory for an array of 'record' structures
void manage_memory(struct RecordManager* rm, struct Config config) {
    // Initialize the record manager with the given configuration
    init_record_manager(rm, config);

    // Add some records to the manager
    add_record(rm, (struct Record) { .offset = 0, .key = 1, .value = 1 });
    add_record(rm, (struct Record) { .offset = 1, .key = 2, .value = 2 });
    add_record(rm, (struct Record) { .offset = 2, .key = 3, .value = 3 });

    // Retrieve a record from the manager using its key
    struct Record* record = get_record(rm, 1);

    // Update a record in the manager using its key
    update_record(rm, (struct Record) { .offset = 0, .key = 1, .value = 4 });

    // Remove a record from the manager using its key
    remove_record(rm, 2);

    // Clean up the record manager and free its resources
    cleanup_record_manager(rm);
}']

