typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void processInputAndAnalyzeArray(int* array, int size) {
    // Determine and print the largest integer in the array using a helper function
    int largest = findLargest(array, size);
    printf("The largest element in the array is %d\n", largest);

    // Populate a list of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* pduList = malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < size; i++) {
        // Generate a random RNTI value within the range of [1, 2^31 - 1]
        int rnti = rand() % (1 << 31);
        // Set CRCFLAG to either 0 or 1 randomly
        pduList[i].CRCFLAG = (rand() % 2) ? 0 : 1;
        pduList[i].RX_UE_INFORMATION_TAG = i + 1;
        pduList[i].RNTI = rnti;
    }

    // Measure and print the time taken to process the input integers, including finding the largest value and populating the structures
    clock_t startTime = clock();
    for (int i = 0; i < size; i++) {
        int currentValue = array[i];
        if (currentValue > largest) {
            largest = currentValue;
        }
    }
    clock_t endTime = clock();
    double timeTaken = (double)(endTime - startTime) / CLOCKS_PER_SEC;
    printf("Time taken to process the input integers is %f seconds\n", timeTaken);

    // Implement a Union-Find data structure to identify and count the number of disjoint pairs of elements within the original array
    // Optimize for both time and space efficiency
    int* parent = malloc(size * sizeof(int));
    int* rank = malloc(size * sizeof(int));
    for (int i = 0; i < size; i++) {
        parent[i] = i;
        rank[i] = 0;
    }
    int disjointPairsCount = 0;
    for (int i = 0; i < size - 1; i++) {
        int root1 = findRoot(parent, rank, array[i]);
        int root2 = findRoot(parent, rank, array[i + 1]);
        if (root1 != root2) {
            disjointPairsCount++;
            unionRoots(parent, rank, root1, root2);
        }
    }
    free(parent);
    free(rank);

    // Print the number of disjoint pairs of elements in the array
    printf("The number of disjoint pairs of elements in the array is %d\n", disjointPairsCount);

    // Sort the array in ascending order and print the sorted array
    qsort(array, size, sizeof(int), compareInts);
    for (int i = 0; i < size; i++) {
        printf("%d ", array[i]);
    }
    printf("\n");
}

// Helper function to find the largest integer in an array using a helper function
int findLargest(int* array, int size) {
    int largest = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    return largest;
}

// Helper function to find the root of a node in a Union-Find data structure
int findRoot(int* parent, int* rank, int node) {
    if (parent[node] == node) {
        return node;
    } else {
        int root = findRoot(parent, rank, parent[node]);
        parent[node] = root;
        return root;
    }
}

// Helper function to union two nodes in a Union-Find data structure
void unionRoots(int* parent, int* rank, int root1, int root2) {
    if (rank[root1] > rank[root2]) {
        parent[root2] = root1;
    } else if (rank[root1] < rank[root2]) {
        parent[root1] = root2;
    } else {
        parent[root2] = root1;
        rank[root1]++;
    }
}

// Helper function to compare two integers for sorting in ascending order
int compareInts(const void* a, const void* b) {
    int x = *(const int*)a;
    int y = *(const int*)b;
    if (x < y) {
        return -1;
    } else if (x > y) {
        return 1;
    } else {
        return 0;
    }
}
