// Structure to represent a user profile
typedef struct {
    int id;
    char* username;
    char* profile_picture_url;
    int num_posts;
} Profile;

// Structure to represent a cache entry
typedef struct {
    int id;
    Profile profile;
} CacheEntry;

// Cache parameters
#define CACHE_SIZE 10000
#define CACHE_HIT_RATE 0.8
#define MEMORY_LIMIT 500 * 1024 * 1024 // 500 MB

// Global variables
CacheEntry* cache;
int num_profiles = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

/*
 * Insert a new profile into the cache.
 */
void insert(int id, Profile profile) {
    CacheEntry* entry = malloc(sizeof(CacheEntry));
    entry->id = id;
    entry->profile = profile;

    // Add to cache
    pthread_mutex_lock(&mutex);
    cache[num_profiles++] = entry;
    if (num_profiles > CACHE_SIZE) {
        int old_size = num_profiles - CACHE_SIZE;
        for (int i = 0; i < old_size; i++) {
            CacheEntry* entry = cache[i];
            free(entry->profile.username);
            free(entry->profile.profile_picture_url);
            free(entry);
        }
    }
    pthread_mutex_unlock(&mutex);
}

/*
 * Retrieve a profile from the cache by ID.
 */
Profile retrieve(int id) {
    Profile profile;
    memset(&profile, 0, sizeof(profile));

    // Check cache
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_profiles; i++) {
        CacheEntry* entry = cache[i];
        if (entry->id == id) {
            profile = entry->profile;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);

    // Fetch from external API if not found in cache
    if (profile.username == NULL) {
        // Perform external API call to fetch user data
        profile = fetch_user_data(id);

        // Add to cache if successful
        insert(id, profile);
    }

    return profile;
}

/*
 * Delete a profile from the cache by ID.
 */
void delete(int id) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_profiles; i++) {
        CacheEntry* entry = cache[i];
        if (entry->id == id) {
            free(entry->profile.username);
            free(entry->profile.profile_picture_url);
            free(entry);
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

/*
 * Fetch user data from an external API.
 */
Profile fetch_user_data(int id) {
    Profile profile = {};
    // Perform external API call to fetch user data
    if (successful) {
        profile.id = id;
        profile.username = strdup("johndoe");
        profile.profile_picture_url = strdup("https://example.com/profile-pics/1234567890.jpg");
    } else {
        // Fallback mechanism: return cached data if available
        Profile fallback = retrieve(id);
        if (fallback.username != NULL) {
            profile = fallback;
        } else {
            // Return an empty profile if no data is available
            profile.username = strdup("");
            profile.profile_picture_url = strdup("");
        }
    }
    return profile;
}

/*
 * Main function to manage user profiles and fetch external data.
 */
int main() {
    // Initialize cache with default size
    cache = malloc(CACHE_SIZE * sizeof(CacheEntry));
    memset(cache, 0, CACHE_SIZE * sizeof(CacheEntry));

    // Insert initial profiles into the cache
    Profile profile1 = {};
    profile1.id = 1;
    profile1.username = strdup("johndoe");
    profile1.profile_picture_url = strdup("https://example.com/profile-pics/1234567890.jpg");
    insert(profile1.id, profile1);

    Profile profile2 = {};
    profile2.id = 2;
    profile2.username = strdup("janedoe");
    profile2.profile_picture_url = strdup("https://example.com/profile-pics/9876543210.jpg");
    insert(profile2.id, profile2);

    // Thread-safe access to the cache and external API
    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        int thread_id = i + 1;
        pthread_create(&threads[i], NULL, &thread_function, (void*)thread_id);
    }

    // Wait for threads to finish
    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}

/*
 * Thread function to manage user profiles and fetch external data.
 */
void* thread_function(void* arg) {
    int thread_id = (int)arg;
    while (1) {
        // Fetch a random profile from the cache
        int id = rand() % num_profiles + 1;
        Profile profile = retrieve(id);

        // Perform external API call to fetch user data
        if (!successful) {
            // Fallback mechanism: return cached data if available
            Profile fallback = retrieve(id);
            if (fallback.username != NULL) {
                profile = fallback;
            } else {
                // Return an empty profile if no data is available
                profile.username = strdup("");
                profile.profile_picture_url = strdup("");
            }
        }

        // Update the cache with new data
        insert(id, profile);
    }
}
