} NetworkInterfaceConfig;

// Custom memory pool for allocating and managing network interface configurations
struct MemoryPool {
    size_t size;
    void *pool;
};

// Global counter for tracking the number of initialized interfaces
static int32_t interfaceCount = 0;

// Mutex for synchronizing access to shared resources like the memory pool and global counters
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize a network interface configuration
NetworkInterfaceConfig *initialize_network_interface(const char *interfaceId, const NeighborCellInfo *neighbors, uint8_t srsPower) {
    // Lock the mutex to ensure thread safety when accessing shared resources
    pthread_mutex_lock(&mutex);

    // Check if the interface has already been initialized and return a pointer to it if so
    for (int32_t i = 0; i < interfaceCount; i++) {
        NetworkInterfaceConfig *config = &(interfaceConfigs[i]);
        if (!strcmp(config->interfaceId, interfaceId)) {
            pthread_mutex_unlock(&mutex);
            return config;
        }
    }

    // Allocate a new network interface configuration and populate it with the specified values
    NetworkInterfaceConfig *newConfig = malloc(sizeof(NetworkInterfaceConfig));
    strcpy(newConfig->interfaceId, interfaceId);
    newConfig->neighborCount = neighbors ? MAX_NEIGHBOR_CELLS : 0;
    if (neighbors) {
        for (int32_t i = 0; i < newConfig->neighborCount; i++) {
            memcpy(&(newConfig->neighbors[i]), &(neighbors[i]), sizeof(NeighborCellInfo));
        }
    }
    newConfig->srsPower = srsPower;

    // Add the new network interface configuration to the array of initialized interfaces
    interfaceConfigs[interfaceCount++] = newConfig;

    // Unlock the mutex and return a pointer to the newly created network interface configuration
    pthread_mutex_unlock(&mutex);
    return newConfig;
}

// Function to allocate memory for a custom memory pool
static void *customMemoryPoolAlloc(size_t size) {
    // Lock the mutex to ensure thread safety when accessing shared resources
    pthread_mutex_lock(&mutex);

    // Search through the array of available memory pools for one that can fit the requested size
    for (int32_t i = 0; i < poolCount; i++) {
        struct MemoryPool *pool = &(pools[i]);
        if (size <= pool->size) {
            // If a matching memory pool is found, allocate memory from it and return the pointer
            void *mem = malloc(size);
            pthread_mutex_unlock(&mutex);
            return mem;
        }
    }

    // If no matching memory pool is found, create a new one and add it to the array of available pools
    struct MemoryPool *newPool = malloc(sizeof(struct MemoryPool));
    newPool->size = size;
    newPool->pool = malloc(size);
    pools[poolCount++] = newPool;

    // Allocate memory from the new pool and return the pointer
    void *mem = malloc(size);
    pthread_mutex_unlock(&mutex);
    return mem;
}

// Function to deallocate memory for a custom memory pool
static void customMemoryPoolFree(void *ptr) {
    // Lock the mutex to ensure thread safety when accessing shared resources
    pthread_mutex_lock(&mutex);

    // Search through the array of available memory pools for the one that contains the specified pointer
    for (int32_t i = 0; i < poolCount; i++) {
        struct MemoryPool *pool = &(pools[i]);
        if (ptr >= pool->pool && ptr < (char *)pool->pool + pool->size) {
            // If the pointer is found, free it from the pool and return
            free(ptr);
            pthread_mutex_unlock(&mutex);
            return;
        }
    }

    // If the pointer is not found in any of the available pools, free it using the standard library's free function
    free(ptr);
    pthread_mutex_unlock(&mutex);
}
