#define MAX_RETRY 3
#define MIN_CONN_TIMEOUT 1000 // in milliseconds
#define MAX_CONN_TIMEOUT 60000 // in milliseconds
#define CONN_BACKOFF_FACTOR 2 // exponential backoff factor for connection retries

// structure to hold record data
struct record {
    int value;
    long timestamp;
};

// function to establish a reliable connection to a remote service
int connectToService(char* host, char* port) {
    struct addrinfo hints, *res;
    int sockfd = 0, retval = -1;
    unsigned int conn_timeout = MIN_CONN_TIMEOUT; // in milliseconds
    struct record *records[3];
    size_t num_records = 3;
    char error_message[256] = {0};

    // get address info for the remote service
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;
    if ((retval = getaddrinfo(host, port, &hints, &res)) != 0) {
        printf("Failed to resolve address for host '%s' and port '%s': %s\n", host, port, gai_strerror(retval));
        goto cleanup;
    }

    // try establishing a connection up to MAX_RETRY times
    for (int i = 0; i < MAX_RETRY; ++i) {
        // create socket and set non-blocking flag
        sockfd = socket(res->ai_family, res->ai_socktype, res->ai_protocol);
        if (sockfd == -1) {
            printf("Failed to create socket: %s\n", strerror(errno));
            continue;
        }

        // set non-blocking flag on the socket
        if (fcntl(sockfd, F_SETFL, O_NONBLOCK) == -1) {
            printf("Failed to set non-blocking flag on socket: %s\n", strerror(errno));
            close(sockfd);
            continue;
        }

        // establish connection to remote service
        if (connect(sockfd, res->ai_addr, res->ai_addrlen) != 0) {
            printf("Failed to connect to remote service: %s\n", strerror(errno));
            close(sockfd);
            continue;
        }

        // successfully established connection, break out of loop
        break;
    }

    if (retval == -1) {
        printf("Failed to establish connection after %d attempts\n", MAX_RETRY);
        goto cleanup;
    }

    // initialize arrays for record data and populate with random values within specified range
    records[0] = malloc(sizeof(struct record));
    records[1] = malloc(sizeof(struct record));
    records[2] = malloc(sizeof(struct record));
    for (size_t i = 0; i < num_records; ++i) {
        records[i]->value = rand() % INT_MAX + 1; // generate random integer value within specified range
        records[i]->timestamp = time(NULL); // get current timestamp
    }

    // send record data to remote service over established connection
    for (size_t i = 0; i < num_records; ++i) {
        char buffer[1024];
        sprintf(buffer, "%d:%ld", records[i]->value, records[i]->timestamp);
        if (write(sockfd, buffer, strlen(buffer)) == -1) {
            printf("Failed to write record data to remote service: %s\n", strerror(errno));
            goto cleanup;
        }
    }

cleanup:
    // close socket and free memory allocated for record data
    if (sockfd != -1) {
        close(sockfd);
    }
    if (records[0] != NULL) {
        free(records[0]);
    }
    if (records[1] != NULL) {
        free(records[1]);
    }
    if (records[2] != NULL) {
        free(records[2]);
    }

    return retval;
}
