    if (!ra) {
        fprintf(stderr, "Error: unable to allocate memory for the record array\n");
        return NULL;
    }

    ra->capacity = capacity;
    ra->size = 0;
    ra->records = (Record *)malloc(sizeof(Record) * capacity);
    if (!ra->records) {
        fprintf(stderr, "Error: unable to allocate memory for the record array\n");
        return NULL;
    }

    return ra;
}

// Function to free a record array and its contents
