}

// Function to allocate a new memory pool
MemoryPool *allocate_memory_pool(size_t size) {
    MemoryPool *mp = (MemoryPool *)malloc(sizeof(MemoryPool));
    if (!mp) {
        fprintf(stderr, "Error: unable to allocate memory for the memory pool\n");
        return NULL;
    }

    mp->size = size;
    mp->capacity = size;
    mp->memory_pool = (void **)malloc(sizeof(void *) * size);
    if (!mp->memory_pool) {
