// Function to populate a record array with unique keys from an integer array
bool populate_record_array(RecordArray *ra, int *key_array, size_t key_count) {
    if (!ra || !key_array || key_count == 0) {
        fprintf(stderr, "Error: invalid arguments for populating record array\n");
