    }

    // Initialize the hash set to keep track of unique keys
    HashSet *unique_keys = (HashSet *)malloc(sizeof(HashSet));
    if (!unique_keys) {
        fprintf(stderr, "Error: unable to allocate memory for the hash set\n");
        return false;
