    }

    // Free the hash set
    free(unique_keys);

    return true;
}

// Function to validate the integrity of a record array
bool validate_record_array(RecordArray *ra) {
    if (!ra) {
        fprintf(stderr, "Error: invalid arguments for validating record array\n");
        return false;
    }

    // Loop through the records and check that all keys are unique
    for (size_t i = 0; i < ra->size; i++) {
        Record *rec = &ra->records[i];
        if (hashset_contains(ra->memory_pool, rec->key)) {
            fprintf(stderr, "Error: key %d is not unique\n", rec->key);
            return false;
        }
    }

    return true;
}

// Function to generate random 'offset' values for new 'record' structures when the memory pool is exhausted
bool generate_new_offsets(RecordArray *ra, int seed) {
    if (!ra) {
        fprintf(stderr, "Error: invalid arguments for generating new offsets\n");
        return false;
    }

    // Initialize the random number generator with the provided seed
    srand(seed);

    // Loop through the record array and generate random 'offset' values for any empty slots
    for (size_t i = 0; i < ra->capacity; i++) {
        if (ra->records[i].offset == -1) {
            int offset = rand() % 100;
            Record *rec = &ra->records[i];
            rec->offset = offset;
        }
    }

    return true;
}
