void *sensor_data_retriever(void *args) {
    // Initialize the data retrieval function with the specified parameters
    int (*data_retrieval_func)(struct sensor_data *);
    data_retrieval_func = args;

    // Define a variable to store the number of retries
    int num_retries = 0;

