    while (num_retries < MAX_RETRIES) {
        struct sensor_data *sensor_data = data_retrieval_func(NULL);
        if (sensor_data != NULL) {
            break;
        } else {
            num_retries++;
            sleep(1); // Sleep for 1 second between retries
        }
    }

    // If the data retrieval failed MAX_RETRIES times, log an error
    if (num_retries == MAX_RETRIES) {
        fprintf(stderr, "Data retrieval failed %d times. Exiting...\n", num_retries);
        exit(EXIT_FAILURE);
    }

    // Log the number of sensor readings retrieved successfully
    printf("Retrieved %lu sensor readings.\n", sizeof(sensor_data->temperatures) / sizeof(*sensor_data->temperatures));

    // Free the memory allocated for the sensor data
    free(sensor_data);
}

