  pthread_mutex_init(&queue->mutex, NULL);
}

// Function to add a new transaction log entry to the queue
void enQueue(struct TransactionLogEntry *entry) {
  QueueData *queue = &queue;

  // Lock the mutex for thread-safe access to the queue
  pthread_mutex_lock(&queue->mutex);

  // Check if the array is full
  if (queue->size == queue->index) {
    // Double the size of the array
    queue->logs = realloc(queue->logs, 2 * sizeof(struct TransactionLogEntry));

    // Update the size of the array
    queue->size = 2 * queue->size;
  }

  // Add the new transaction log entry to the end of the array
  memcpy(&queue->logs[queue->index], entry, sizeof(struct TransactionLogEntry));

  // Increment the index of the next available slot in the array
  queue->index++;

  // Unlock the mutex for thread-safe access to the queue
  pthread_mutex_unlock(&queue->mutex);
}

// Function to remove a transaction log entry from the queue
void deQueue(struct TransactionLogEntry *entry) {
  QueueData *queue = &queue;

  // Lock the mutex for thread-safe access to the queue
  pthread_mutex_lock(&queue->mutex);

  // Check if there are any transaction log entries in the queue
  if (queue->index > 0) {
    // Get the first transaction log entry from the array
    memcpy(entry, &queue->logs[0], sizeof(struct TransactionLogEntry));

    // Remove the first transaction log entry from the array
    memmove(&queue->logs[0], &queue->logs[1], (queue->index - 1) * sizeof(struct TransactionLogEntry));

    // Decrement the index of the next available slot in the array
    queue->index--;
  } else {
    // There are no transaction log entries in the queue, return NULL
    entry = NULL;
  }

  // Unlock the mutex for thread-safe access to the queue
  pthread_mutex_unlock(&queue->mutex);
}

