      printf("Error: Timestamp outside valid range\n");
    }
  } else {
    // The transaction ID is outside the valid range, log an error message
    printf("Error: Transaction ID outside valid range\n");
  }
}

// Function to handle a failed transaction
void handleFailedTransaction(struct TransactionLogEntry *entry) {
  // Check if there are any retries remaining for the transaction
  if (entry->retries > 0) {
    // Reattempt the transaction within the retry period
    entry->retries--;

    // Update the status of the transaction in the queue
    entry->status = true;
  } else {
    // No retries remaining, log an error message
    printf("Error: Failed transaction with no retries remaining\n");
  }
}

// Function to clean up the queue data structure
void cleanupQueue(QueueData *queue) {
  // Lock the mutex for thread-safe access to the queue
  pthread_mutex_lock(&queue->mutex);

  // Free the memory used by the array
  free(queue->logs);

  // Reset the size of the array and the index of the next available slot in the array
