// C Header File
#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <math.h>

#define MAX_OFFSET 10000
#define MIN_OFFSET -10000
#define MAX_KEY 1000
#define MIN_KEY 0
#define MAX_VALUE 100.0
#define MIN_VALUE -100.0

// Data Structures
struct entry {
    long offset;
    int key;
    double value;
};

typedef struct entry entry_t;

entry_t* allocate_data(size_t size) {
    // Allocate memory for the data structures
    entry_t* entries = malloc(sizeof(entry_t) * size);
    if (entries == NULL) {
        printf("Error: Failed to allocate memory for entries.\n");
        return NULL;
    }

    // Initialize the entries with random values within specified ranges
    srand(time(NULL));
    for (int i = 0; i < size; ++i) {
        entries[i].offset = MIN_OFFSET + rand() % (MAX_OFFSET - MIN_OFFSET + 1);
        entries[i].key = MIN_KEY + rand() % (MAX_KEY - MIN_KEY + 1);
        entries[i].value = MIN_VALUE + ((double)rand()) / RAND_MAX * (MAX_VALUE - MIN_VALUE);
    }

    // Validate the integrity of the allocated memory
    for (int i = 0; i < size; ++i) {
        if (!is_entry_valid(&entries[i])) {
            printf("Error: Entry %d is not valid.\n", i);
            return NULL;
        }
    }

    // Return the allocated memory
    return entries;
}

void deallocate_data(entry_t* entries, size_t size) {
    free(entries);
}

bool is_entry_valid(const entry_t* entry) {
    // Validate the offset and key values
    if (entry->offset < MIN_OFFSET || entry->offset > MAX_OFFSET) {
        return false;
    }
    if (entry->key < MIN_KEY || entry->key > MAX_KEY) {
        return false;
    }

    // Validate the value range
    if (entry->value < MIN_VALUE || entry->value > MAX_VALUE) {
        return false;
    }

    return true;
}
