// Function to allocate and initialize the memory block
int allocateAndInitializeMemory(size_t numRecords, size_t rangeMin, size_t rangeMax, unsigned seed) {
    // Calculate the total size of the memory block required
    size_t totalSize = sizeof(struct Record) * numRecords;

    // Allocate memory for all components in a single block
    struct Record* records = (struct Record*)malloc(totalSize);

    // Check for memory allocation failure and return error code if necessary
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    // Initialize each record's integer value with a random value within the specified range
    srand(seed);
    for (size_t i = 0; i < numRecords; ++i) {
        records[i].value = rand() % (rangeMax - rangeMin + 1) + rangeMin;
    }

    // Generate a randomly populated string for each character field
    for (size_t i = 0; i < numRecords; ++i) {
        size_t len = rand() % 20 + 1;
        for (size_t j = 0; j < len; ++j) {
            records[i].buffer[j] = 'a' + rand() % 26;
        }
    }

    return 0;
}

// Function to free the memory allocated by allocateAndInitializeMemory
void freeMemory(struct Record* records, size_t numRecords) {
    // Check if the input parameters are valid
    if (!records || !numRecords) {
        fprintf(stderr, "Invalid input parameters\n");
        return;
    }

    // Free the memory allocated for the records
    free(records);
}

int main() {
    const size_t numRecords = 1000;
    const size_t rangeMin = 0;
    const size_t rangeMax = 100;
    unsigned seed = time(NULL);

    // Allocate and initialize the memory block
    int status = allocateAndInitializeMemory(numRecords, rangeMin, rangeMax, seed);
    if (status != 0) {
        fprintf(stderr, "Error: Failed to allocate and initialize memory\n");
        return -1;
    }

    // Use the allocated memory as needed
    struct Record* records = ...; // Initialize with the returned pointer from allocateAndInitializeMemory

    // Free the memory when done
    freeMemory(records, numRecords);

    return 0;
}
