// Function to initialize arrays with random values within specified ranges
void initArrays(Entry *entries, long *offsets, int *keys) {
    // Set seed for generating random numbers
    srand(time(NULL));

    // Initialize arrays with random values within specified ranges
    for (int i = 0; i < NUM_ENTRIES; i++) {
        entries[i].offset = rand() % MAX_OFFSET;
        entries[i].key = rand() % MAX_KEY;
        entries[i].value = (double)rand() / RAND_MAX;

        offsets[i] = rand() % MAX_OFFSET;
        keys[i] = rand() % MAX_KEY;
    }
}

// Function to manage memory allocation for three distinct data structures: an array of 'long' offset values, an array of 'int' keys, and an array of 'entry' structures. Each 'entry' structure should contain a 'long' offset, an 'int' key, and a 'double' value.
void memoryAllocation(Entry *entries, long *offsets, int *keys) {
    // Initialize arrays with random values within specified ranges
    initArrays(entries, offsets, keys);

    // Allocate memory for entries array
    entries = malloc(NUM_ENTRIES * sizeof(Entry));
    if (entries == NULL) {
        printf("Failed to allocate memory for entries array\n");
        return;
    }

    // Allocate memory for offsets array
    offsets = malloc(NUM_ENTRIES * sizeof(long));
    if (offsets == NULL) {
        printf("Failed to allocate memory for offsets array\n");
        free(entries);
        return;
    }

    // Allocate memory for keys array
    keys = malloc(NUM_ENTRIES * sizeof(int));
    if (keys == NULL) {
        printf("Failed to allocate memory for keys array\n");
        free(entries);
        free(offsets);
        return;
    }

    // Initialize entries with random values within specified ranges
    initArrays(entries, offsets, keys);

    // Deallocate memory for entries array
    free(entries);

    // Deallocate memory for offsets array
    free(offsets);

    // Deallocate memory for keys array
    free(keys);
}

int main() {
    // Define constants for maximum offset, key, and number of entries
    const int MAX_OFFSET = 100;
    const int MAX_KEY = 500;
    const int NUM_ENTRIES = 1000;

    // Declare variables to hold memory for arrays of offsets, keys, and entries
    long *offsets = NULL;
    int *keys = NULL;
    Entry *entries = NULL;

    // Call function to manage memory allocation for three distinct data structures
    memoryAllocation(entries, offsets, keys);

    return 0;
}

