    int rssi; // Received signal strength indicator (RSSI)
    int cellId; // Cell ID of the neighboring cell
};

// Structure to store configuration for Sounding Reference Signal (SRS) parameters
struct SoundingReferenceSignalParams {
    bool srs_enabled; // Flag indicating whether SRS is enabled
    int srs_period; // Period in milliseconds for SRS transmission
    int srs_bandwidth; // Bandwidth for SRS transmission
};

// Function to initialize a dynamic array of NetworkInterfaceConfig structures
void initNetworkInterfaceConfig(struct NetworkInterfaceConfig **configArray, int numInterfaces) {
    *configArray = malloc(numInterfaces * sizeof(struct NetworkInterfaceConfig));
    if (*configArray == NULL) {
        perror("Error allocating memory for network interface config array");
        exit(EXIT_FAILURE);
    }

    // Initialize each NetworkInterfaceConfig structure in the array
    for (int i = 0; i < numInterfaces; i++) {
        struct NetworkInterfaceConfig *config = &(*configArray)[i];
        config->interfaceId = i + 1;
        config->neighbors = malloc(10 * sizeof(struct NeighborCellInfo)); // Allocate enough memory for 10 neighboring cells
        if (config->neighbors == NULL) {
            perror("Error allocating memory for neighbor cell list");
            exit(EXIT_FAILURE);
        }
        config->srsParams.srs_enabled = false; // Default SRS parameters
        config->srsParams.srs_period = 0;
        config->srsParams.srs_bandwidth = 0;
    }
}

// Function to fetch real-time configuration updates for a network interface and its neighbors
void updateNetworkInterfaceConfig(struct NetworkInterfaceConfig *config) {
    // Fetch real-time configuration updates from the external network management service asynchronously
    pthread_t thread;
    pthread_create(&thread, NULL, fetchConfigUpdates, (void *)config);
}

// Thread function to fetch real-time configuration updates for a network interface and its neighbors
void *fetchConfigUpdates(void *arg) {
    struct NetworkInterfaceConfig *config = (struct NetworkInterfaceConfig *)arg;
    // Fetch current neighbor cell list from the external network management service
    int numNeighbors = fetchCurrentNeighborCellList(config->interfaceId, &config->neighbors);
    if (numNeighbors < 0) {
        perror("Error fetching current neighbor cell list");
        exit(EXIT_FAILURE);
    } else if (numNeighbors > 10) {
        // Limit the number of neighbors to 10 for memory and performance reasons
        numNeighbors = 10;
    }

    // Fetch current SRS parameters from the external network management service
    struct SoundingReferenceSignalParams srsParams = fetchCurrentSRSParameters(config->interfaceId);
    if (srsParams.srs_enabled) {
        config->srsParams.srs_period = srsParams.srs_period;
        config->srsParams.srs_bandwidth = srsParams.srs_bandwidth;
    } else {
        // Disable SRS if the service does not support it
        config->srsParams.srs_enabled = false;
    }
}

// Function to handle memory allocation efficiently for the NetworkInterfaceConfig structures
void *mallocNetworkInterfaceConfig(int numInterfaces) {
    struct NetworkInterfaceConfig **configArray = malloc(numInterfaces * sizeof(struct NetworkInterfaceConfig));
    if (configArray == NULL) {
        perror("Error allocating memory for network interface config array");
        exit(EXIT_FAILURE);
    }

    // Initialize each NetworkInterfaceConfig structure in the array
    for (int i = 0; i < numInterfaces; i++) {
        struct NetworkInterfaceConfig *config = &(*configArray)[i];
        config->interfaceId = i + 1;
        config->neighbors = malloc(10 * sizeof(struct NeighborCellInfo)); // Allocate enough memory for 10 neighboring cells
        if (config->neighbors == NULL) {
            perror("Error allocating memory for neighbor cell list");
