        }
        config->srsParams.srs_enabled = false; // Default SRS parameters
        config->srsParams.srs_period = 0;
        config->srsParams.srs_bandwidth = 0;
    }
}

// Function to handle concurrent modifications to the NetworkInterfaceConfig data structures safely
void *lockNetworkInterfaceConfig(struct NetworkInterfaceConfig **configArray, int numInterfaces) {
    pthread_mutex_t *mutexArray = malloc(numInterfaces * sizeof(pthread_mutex_t));
    if (mutexArray == NULL) {
        perror("Error allocating memory for mutex array");
        exit(EXIT_FAILURE);
    }

    // Initialize each mutex in the array
    for (int i = 0; i < numInterfaces; i++) {
        struct NetworkInterfaceConfig *config = &(*configArray)[i];
        pthread_mutex_init(&mutexArray[i], NULL);
        config->lock = &mutexArray[i]; // Assign the mutex to each NetworkInterfaceConfig structure
    }
}

// Function to handle memory allocation efficiently for the NeighborCellInfo structures
