        struct NeighborCellInfo *neighborCell = &(*neighborCellArray)[i];
        neighborCell->cellId = i + 1; // Assign a unique cell ID to each structure
        neighborCell->signalStrength = fetchSignalStrength(config->interfaceId, neighborCell->cellId);
    }
}

// Function to handle logging of error messages for the NetworkInterfaceConfig structures
