typedef struct Connection {
    long id;
    char *src_ip;
    char *dst_ip;
    short src_port;
    short dst_port;
} Connection;

Connection *connections; // Pointer to array of connections
int num_connections = 0; // Number of connections in the array

void init_connection(Connection *conn) {
    conn->id = 0;
    conn->src_ip = NULL;
    conn->dst_ip = NULL;
    conn->src_port = 0;
    conn->dst_port = 0;
}

void add_connection(Connection *conn) {
    if (num_connections >= connections) {
        // Reallocate memory for the connection array
        connections = realloc(connections, (num_connections + 1) * sizeof(Connection));
    }
    init_connection(&connections[num_connections]);
    memcpy(&connections[num_connections], conn, sizeof(Connection));
    num_connections++;
}

void remove_connection(long id) {
    for (int i = 0; i < num_connections; i++) {
        if (connections[i].id == id) {
            // Shift all connections after the removed connection down by one
            memmove(&connections[i], &connections[i + 1], (num_connections - i - 1) * sizeof(Connection));
            num_connections--;
            break;
        }
    }
}

int get_connection_index(long id) {
    for (int i = 0; i < num_connections; i++) {
        if (connections[i].id == id) {
            return i;
        }
    }
    return -1; // Connection not found
}

void update_connection(long id, Connection *conn) {
    int index = get_connection_index(id);
    if (index < 0) {
        printf("Connection with ID %ld not found\n", id);
        return;
    }
    memcpy(&connections[index], conn, sizeof(Connection));
}

void print_connections() {
    for (int i = 0; i < num_connections; i++) {
        printf("Connection %d: ID=%ld, Src IP=%s, Dst IP=%s, Src Port=%d, Dst Port=%d\n", i + 1, connections[i].id, connections[i].src_ip, connections[i].dst_ip, connections[i].src_port, connections[i].dst_port);
    }
}

void reset_hash() {
    // Reset the hash function to ensure reproducibility
}

int main() {
    int num_inputs = 0;
    printf("Enter the number of network connections: ");
    scanf("%d", &num_inputs);
    connections = malloc(num_inputs * sizeof(Connection));
    if (!connections) {
        fprintf(stderr, "Error: Could not allocate memory for connections\n");
        return 1;
    }
    reset_hash(); // Reset the hash function before assigning connection IDs
    for (int i = 0; i < num_inputs; i++) {
        Connection conn;
        init_connection(&conn);
        printf("Enter connection %d:\n", i + 1);
        printf("\tSource IP address: ");
        scanf("%s", conn.src_ip);
        printf("\tDestination IP address: ");
        scanf("%s", conn.dst_ip);
        printf("\tSource port number: ");
        scanf("%hd", &conn.src_port);
        printf("\tDestination port number: ");
        scanf("%hd", &conn.dst_port);
        add_connection(&conn);
    }
    // Check for duplicate connections
    for (int i = 0; i < num_connections - 1; i++) {
        for (int j = i + 1; j < num_connections; j++) {
            if (strcmp(connections[i].src_ip, connections[j].src_ip) == 0 &&
                    strcmp(connections[i].dst_ip, connections[j].dst_ip) == 0 &&
                    connections[i].src_port == connections[j].src_port &&
                    connections[i].dst_port == connections[j].dst_port) {
                fprintf(stderr, "Error: Duplicate connection found\n");
            }
        }
    }
    // Assign unique connection IDs to each connection
    for (int i = 0; i < num_connections; i++) {
        connections[i].id = get_next_connection_id();
    }
    printf("Connections:\n");
    print_connections();
    // Free memory used by the connection array
    free(connections);
    return 0;
}

long get_next_connection_id() {
    long id = rand();
    while (get_connection_index(id) >= 0) {
        // If there is a collision, try again with a different ID
        id = rand();
    }
    return id;
}
