// Function to generate a list of NFAPI_CRC_INDICATION_PDU_T structures with random RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG values, with dynamic cooldown logic to prevent concurrent attacks
int generateNfarPduList(std::vector<NFAPI_CRC_INDICATION_PDU>& pduList) {
    // Initialize a random seed based on current time
    srand(time(NULL));

    // Create an empty list of PDUs
    pduList.clear();

    // Loop until the desired number of PDUs is reached, or the cooldown period has elapsed
    while (pduList.size() < N && getCooldownRemainingSeconds() > 0) {
        // Generate a new PDU with random RX_UE_INFORMATION_TAG and RNTI values
        NFAPI_CRC_INDICATION_PDU pdu;
        pdu.rxUeInformationTag = rand();
        pdu.rnti = rand();

        // Set the CRCFLAG to a random value with 50% probability of being set
        if (rand() % 2 == 0) {
            pdu.crcIndicationRel8Tag.crcFlag = true;
        } else {
            pdu.crcIndicationRel8Tag.crcFlag = false;
        }

        // Add the PDU to the list
        pduList.push_back(pdu);
    }

    return pduList.size();
}

// Function to compute the remaining cooldown period in seconds, taking into account concurrent calls to generateNfarPduList
double getCooldownRemainingSeconds() {
    // Compute the current time
    time_t now = time(NULL);

    // Get the last time a PDU was added to the list
    time_t lastAdded = pduList.empty() ? 0 : pduList.back().rxUeInformationTag;

    // Compute the difference between the current time and the last time a PDU was added
    double diff = difftime(now, lastAdded);

    // If the cooldown period has elapsed, reset it to 0
    if (diff >= COOLDOWN_PERIOD) {
        return 0;
    } else {
        // Otherwise, return the remaining cooldown period
        return COOLDOWN_PERIOD - diff;
    }
}
