// Define the structure for LTE_NAS_Message
typedef struct {
    NAS_PDU *nas_pdu;
    size_t nas_pdu_size;
} LTE_NAS_Message_Type;

// Define the global variables
static LTE_NAS_Message_Type *messages = NULL;
static size_t num_messages = 0;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize the array of messages
int init_messages() {
    // Allocate memory for the array of messages
    messages = (LTE_NAS_Message_Type *) malloc(MAX_MESSAGES * sizeof(LTE_NAS_Message_Type));
    if (!messages) {
        return -1;
    }

    // Initialize each message structure
    for (int i = 0; i < MAX_MESSAGES; i++) {
        messages[i].nas_pdu = NULL;
        messages[i].nas_pdu_size = 0;
    }

    return 0;
}

// Function to add a new message to the array
int add_message(NAS_PDU *nas_pdu, size_t nas_pdu_size) {
    // Check if the memory limit has been exceeded
    if (num_messages >= MEMORY_LIMIT / MESSAGE_SIZE) {
        return -1;
    }

    // Acquire the mutex to prevent concurrent modifications to the array
    pthread_mutex_lock(&mutex);

    // Check if there is enough space in the buffer for the new message
    if (num_messages >= MAX_MESSAGES) {
        // Resize the buffer to fit more messages
        int new_size = MAX_MESSAGES * 2;
        LTE_NAS_Message_Type *new_buffer = (LTE_NAS_Message_Type *) realloc(messages, new_size * sizeof(LTE_NAS_Message_Type));
        if (!new_buffer) {
            // Reallocation failed, release the mutex and return an error code
            pthread_mutex_unlock(&mutex);
            return -1;
        } else {
            messages = new_buffer;
            MAX_MESSAGES = new_size;
        }
    }

    // Add the new message to the buffer
    messages[num_messages].nas_pdu = nas_pdu;
    messages[num_messages].nas_pdu_size = nas_pdu_size;
    num_messages++;

    // Release the mutex and return success
    pthread_mutex_unlock(&mutex);
    return 0;
}

// Function to retrieve a message from the array by its index
int get_message(int index, NAS_PDU **nas_pdu, size_t *nas_pdu_size) {
    // Check if the index is valid
    if (index >= num_messages || index < 0) {
        return -1;
    }

    // Acquire the mutex to prevent concurrent modifications to the array
    pthread_mutex_lock(&mutex);

    // Return the message at the specified index
    *nas_pdu = messages[index].nas_pdu;
    *nas_pdu_size = messages[index].nas_pdu_size;

    // Release the mutex and return success
    pthread_mutex_unlock(&mutex);
    return 0;
}

// Function to release all resources used by the array of messages
void cleanup_messages() {
    // Acquire the mutex to prevent concurrent modifications to the array
    pthread_mutex_lock(&mutex);

    // Free the memory allocated for the array of messages
    free(messages);
    messages = NULL;
    num_messages = 0;

    // Release the mutex and return success
    pthread_mutex_unlock(&mutex);
}
