#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_MESSAGES 1024 // maximum number of messages that can be allocated at once
#define MESSAGE_SIZE sizeof(LTE_NAS_Message_Type) // size of each message in bytes

typedef struct {
    char *pdu;
    size_t size;
} LTE_NAS_Message_Type;

typedef struct {
    pthread_mutex_t lock;
    int message_count;
    int max_messages;
    LTE_NAS_Message_Type *messages;
} MessageQueue;

void init_message_queue(MessageQueue *queue) {
    queue->lock = PTHREAD_MUTEX_INITIALIZER;
    queue->message_count = 0;
    queue->max_messages = MAX_MESSAGES;
    queue->messages = malloc(sizeof(LTE_NAS_Message_Type) * queue->max_messages);
}

void deinit_message_queue(MessageQueue *queue) {
    free(queue->messages);
    pthread_mutex_destroy(&queue->lock);
}

int add_message(MessageQueue *queue, char *pdu, size_t size) {
    if (queue->message_count >= queue->max_messages) {
        return -1; // maximum number of messages exceeded
    }

    pthread_mutex_lock(&queue->lock);

    int i = queue->message_count++;
    LTE_NAS_Message_Type *message = &queue->messages[i];
    message->pdu = malloc(size);
    memcpy(message->pdu, pdu, size);
    message->size = size;

    pthread_mutex_unlock(&queue->lock);

    return 0; // success
}

int remove_message(MessageQueue *queue) {
    if (queue->message_count == 0) {
        return -1; // no messages available to be removed
    }

    pthread_mutex_lock(&queue->lock);

    int i = queue->message_count--;
    LTE_NAS_Message_Type *message = &queue->messages[i];
    free(message->pdu);

    pthread_mutex_unlock(&queue->lock);

    return 0; // success
}

void clear_message_queue(MessageQueue *queue) {
    if (queue->message_count == 0) {
        return;
    }

    pthread_mutex_lock(&queue->lock);

    for (int i = 0; i < queue->message_count; i++) {
        LTE_NAS_Message_Type *message = &queue->messages[i];
        free(message->pdu);
    }
    queue->message_count = 0;

    pthread_mutex_unlock(&queue->lock);
}
```
