// Structures for NetworkInterfaceConfig and NeighborCellInfo
struct NetworkInterfaceConfig {
    int interfaceId;
    struct NeighborCellInfo *neighborCells;
    int numNeighbors;
    SRSParameters srsParams;
};

struct NeighborCellInfo {
    int neighborId;
    float signalStrength;
    float channelQuality;
};

struct SRSParameters {
    int srsType;
    int srsResourceSet;
    int srsBandwidth;
};

// Dynamic array of NetworkInterfaceConfig structures
struct NetworkInterfaceConfig *networkInterfaces = NULL;
size_t numNetworkInterfaces = 0;

// Function to initialize a dynamic array of NetworkInterfaceConfig structures
void initNetworkInterfaces(int numEntries, int srsType, int srsResourceSet, int srsBandwidth) {
    // Allocate memory for the dynamic array
    networkInterfaces = (struct NetworkInterfaceConfig *)malloc(numEntries * sizeof(struct NetworkInterfaceConfig));
    if (!networkInterfaces) {
        fprintf(stderr, "Failed to allocate memory for network interfaces\n");
        return;
    }

    // Initialize the SRS parameters in each NetworkInterfaceConfig structure
    for (int i = 0; i < numEntries; ++i) {
        networkInterfaces[i].srsParams.srsType = srsType;
        networkInterfaces[i].srsParams.srsResourceSet = srsResourceSet;
        networkInterfaces[i].srsParams.srsBandwidth = srsBandwidth;
    }

    // Initialize the neighbor cell list in each NetworkInterfaceConfig structure
    for (int i = 0; i < numEntries; ++i) {
        int neighborId = 0;
        float signalStrength = 0.0f;
        float channelQuality = 0.0f;

        // Generate a unique neighbor ID and populate the neighbor cell list
        do {
            neighborId = rand() % numEntries;
        } while (networkInterfaces[i].neighborCells[neighborId].neighborId != -1);

        networkInterfaces[i].neighborCells[neighborId].neighborId = neighborId;
        networkInterfaces[i].neighborCells[neighborId].signalStrength = signalStrength;
        networkInterfaces[i].neighborCells[neighborId].channelQuality = channelQuality;
    }

    numNetworkInterfaces = numEntries;
}

// Function to update the neighbor cell list in a NetworkInterfaceConfig structure
void updateNeighborCellList(int interfaceId, int neighborId, float signalStrength, float channelQuality) {
    // Check if the interface ID is valid and the neighbor ID is not already present
    if (interfaceId < 0 || interfaceId >= numNetworkInterfaces || networkInterfaces[interfaceId].neighborCells[neighborId].neighborId != -1) {
        return;
    }

    // Update the neighbor cell list in the NetworkInterfaceConfig structure
    networkInterfaces[interfaceId].neighborCells[neighborId].neighborId = neighborId;
    networkInterfaces[interfaceId].neighborCells[neighborId].signalStrength = signalStrength;
    networkInterfaces[interfaceId].neighborCells[neighborId].channelQuality = channelQuality;
}

// Function to get the number of neighbor cells in a NetworkInterfaceConfig structure
int getNumNeighbors(int interfaceId) {
    // Check if the interface ID is valid and return 0 if not
    if (interfaceId < 0 || interfaceId >= numNetworkInterfaces) {
        return 0;
    }

    return networkInterfaces[interfaceId].numNeighbors;
}

// Function to get the neighbor cell ID and signal strength in a NetworkInterfaceConfig structure
void getNeighborCell(int interfaceId, int neighborIndex, int *neighborId, float *signalStrength) {
    // Check if the interface ID is valid and the neighbor index is within range
    if (interfaceId < 0 || interfaceId >= numNetworkInterfaces || neighborIndex < 0 || neighborIndex >= networkInterfaces[interfaceId].numNeighbors) {
        *neighborId = -1;
        *signalStrength = 0.0f;
        return;
    }

    // Get the neighbor cell ID and signal strength from the NetworkInterfaceConfig structure
    *neighborId = networkInterfaces[interfaceId].neighborCells[neighborIndex].neighborId;
    *signalStrength = networkInterfaces[interfaceId].neighborCells[neighborIndex].signalStrength;
}
```
In this implementation, a dynamic array of `NetworkInterfaceConfig` structures is used to store the configuration for each network interface. Each `NetworkInterfaceConfig` structure contains a list of `NeighborCellInfo` structures, which are used to store information about the neighboring cells. The SRS parameters are stored in a separate structure.

The `initNetworkInterfaces()` function takes as input the number of entries in the dynamic array, the type of SRS resource set, and the bandwidth of the SRS signal. It then allocates memory for the dynamic array and initializes the SRS parameters in each `NetworkInterfaceConfig` structure. It also populates the neighbor cell list in each `NetworkInterfaceConfig` structure with a specified number of entries, ensuring no duplicate neighbor IDs and correctly configuring the SRS parameters based on a predefined template.

The `updateNeighborCellList()` function takes as input an interface ID, a neighbor ID, and the signal strength and channel quality of the neighboring cell. It updates the corresponding entry in the neighbor cell list with the new signal strength and channel quality.

The `getNumNeighbors()` function returns the number of neighbor cells for a given interface ID. It returns 0 if the interface ID is invalid.

The `getNeighborCell()` function takes as input an interface ID, a neighbor index, and pointers to store the neighbor cell ID and signal strength. It returns the specified neighbor cell information if the interface ID and neighbor index are valid, or -1 and 0.0f otherwise.

Memory allocation is handled efficiently by using a single block of memory for the dynamic array of `NetworkInterfaceConfig` structures. This helps to prevent leaks and ensures thread safety when accessing shared resources. The `NetworkInterfaceConfig` structures are also designed to minimize memory usage, as only the number of neighbor cells for each interface needs to be stored.

The `initNetworkInterfaces()` function is called at program startup to initialize the dynamic array with the default configuration. It can also be used to update the configuration at runtime by passing a different number of entries and/or SRS parameters. The `updateNeighborCellList()` function can be used to update the neighbor cell list for a given interface ID, while the `getNumNeighbors()` and `getNeighborCell()` functions are used to retrieve information about the neighboring cells.']

