    boost::asio::http::request<boost::asio::streambuf> req;
    req.set(boost::beast::http::field::user_agent, "SandeshClient/1.0");
    req.set(boost::beast::http::field::host, url);
    req.method(boost::beast::http::verb::get);

    // Send the GET request to the server and read the response
    boost::asio::write(client->socket(), req);
    boost::beast::http::response<boost::beast::http::string_body> res;
    boost::asio::read(client->socket(), boost::asio::dynamic_buffer(res));

    // Check the response status and print out the payload if valid
    if (res.result() == boost::beast::http::status::ok) {
      std::cout << "Response received: " << res.body() << std::endl;
    } else {
      std::cerr << "Error sending GET request: " << res.reason() << std::endl;
    }
  }

 private:
  // Boost ASIO service object for creating sockets
  boost::asio::io_service& io_service_;
};

