// Function to initialize a dynamic array of NetworkInterfaceConfig structures using a custom C function
void InitializeNetworkInterfaces(const std::string& interface_table_path, const std::string& sandesh_server) {
  // Create a Sandesh client object for sending GET requests to the server
  auto sc = std::make_shared<SandeshClient>(boost::asio::io_service());

  // Initialize a custom InterfaceTable class with a test double function for FindVmUuidFromMetadataIp
  auto it = std::make_shared<InterfaceTable>();
  it->FindVmUuidFromMetadataIp = [](const std::string& ip) { return "test-vm-uuid"; };

  // Create a dynamic array of NetworkInterfaceConfig structures for storing network interface configuration data
  auto nics = new NetworkInterfaceConfig*[10];
  int nic_count = 0;

  // Send GET requests to the server for each interface and create a NetworkInterfaceConfig structure for each response
  std::string path = "/" + sandesh_server + "/get-interfaces";
  sc->Get(path, [&](const boost::system::error_code& ec) {
    if (!ec) {
      // Parse the JSON payload from the GET response and create a NetworkInterfaceConfig structure for each interface
      std::string json = sc->response().body();
      auto root = cpptoml::parse(json);
      auto interfaces = cpptoml::get_table_array(root, "interfaces");
      for (auto& i : interfaces) {
        auto interface_id = cpptoml::get<std::string>(i, "interface-id");
        std::cout << "Initializing network interface with ID: " << interface_id << std::endl;
        nics[nic_count] = new NetworkInterfaceConfig(interface_id);
        nic_count++;
      }
    } else {
      std::cerr << "Error sending GET request to server: " << ec.message() << std::endl;
    }
  });
}

int main() {
  InitializeNetworkInterfaces("interface-table.conf", "sandesh-server");
  return 0;
}
