// Structure to hold the parameters for the cryptographic service
typedef struct {
    int mode; // ECB, EDE, EDE3, CFB
    int reversible; // 0 for irreversible, 1 for reversible
    int padding; // customizable padding scheme
} crypt_params_t;

// Function to initialize the cryptographic service with default parameters
void init_crypt(crypt_params_t *params) {
    params->mode = ECB;
    params->reversible = 1;
    params->padding = NO_PADDING;
}

// Function to configure the cryptographic service with user-specified parameters
void config_crypt(crypt_params_t *params, int mode, int reversible, int padding) {
    params->mode = mode;
    params->reversible = reversible;
    params->padding = padding;
}

// Function to encrypt data using the cryptographic service
void encrypt(crypt_params_t *params, const unsigned char *plaintext, int plaintext_len, unsigned char *ciphertext) {
    EVP_CIPHER_CTX *ctx = NULL;
    const EVP_CIPHER *cipher = NULL;
    int ciphertext_len = 0;
    int len = 0;
    unsigned char iv[8] = {0};

    // Initialize the cryptographic service with the specified parameters
    ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        fprintf(stderr, "Error: Failed to initialize the cryptographic service\n");
        return;
    }
    cipher = EVP_des_cbc();
    if (cipher == NULL) {
        fprintf(stderr, "Error: Failed to get the DES cipher\n");
        return;
    }
    if (!EVP_CipherInit_ex(ctx, cipher, NULL, NULL, iv, params->reversible)) {
        ERR_print_errors_fp(stderr);
        return;
    }
    if (!EVP_CIPHER_CTX_set_padding(ctx, params->padding)) {
        fprintf(stderr, "Error: Failed to set the padding scheme\n");
        return;
    }

    // Encrypt the plaintext data
    len = 0;
    while (plaintext_len > 0) {
        int chunksize = (plaintext_len >= DES_BLOCK_SIZE) ? DES_BLOCK_SIZE : plaintext_len;
        if (!EVP_CipherUpdate(ctx, ciphertext + len, &chunksize, plaintext, chunksize)) {
            ERR_print_errors_fp(stderr);
            return;
        }
        len += chunksize;
        plaintext_len -= chunksize;
    }
    if (!EVP_CipherFinal_ex(ctx, ciphertext + len, &ciphertext_len)) {
        ERR_print_errors_fp(stderr);
        return;
    }

    // Clean up
    EVP_CIPHER_CTX_free(ctx);
}

// Function to decrypt data using the cryptographic service
void decrypt(crypt_params_t *params, const unsigned char *ciphertext, int ciphertext_len, unsigned char *plaintext) {
    EVP_CIPHER_CTX *ctx = NULL;
    const EVP_CIPHER *cipher = NULL;
    int plaintext_len = 0;
    int len = 0;
    unsigned char iv[8] = {0};

    // Initialize the cryptographic service with the specified parameters
    ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        fprintf(stderr, "Error: Failed to initialize the cryptographic service\n");
        return;
    }
    cipher = EVP_des_cbc();
    if (cipher == NULL) {
        fprintf(stderr, "Error: Failed to get the DES cipher\n");
        return;
    }
    if (!EVP_CipherInit_ex(ctx, cipher, NULL, NULL, iv, params->reversible)) {
        ERR_print_errors_fp(stderr);
        return;
    }
    if (!EVP_CIPHER_CTX_set_padding(ctx, params->padding)) {
        fprintf(stderr, "Error: Failed to set the padding scheme\n");
        return;
    }

    // Decrypt the ciphertext data
    len = 0;
    while (ciphertext_len > 0) {
        int chunksize = (ciphertext_len >= DES_BLOCK_SIZE) ? DES_BLOCK_SIZE : ciphertext_len;
        if (!EVP_CipherUpdate(ctx, plaintext + len, &chunksize, ciphertext, chunksize)) {
            ERR_print_errors_fp(stderr);
            return;
        }
        len += chunksize;
        ciphertext_len -= chunksize;
    }
    if (!EVP_CipherFinal_ex(ctx, plaintext + len, &plaintext_len)) {
        ERR_print_errors_fp(stderr);
        return;
    }

    // Clean up
    EVP_CIPHER_CTX_free(ctx);
}']

