#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define custom Union-Find data structure
struct UF {
  int parent; // Parent node of the current node
  int rank; // Rank of the current node
};

// Function to find the representative node of a group
int find(int x, struct UF* uf) {
  if (uf[x].parent != x) {
    uf[x].parent = find(uf[x].parent, uf);
  }
  return uf[x].parent;
}

// Function to union two nodes
void union(int x, int y, struct UF* uf) {
  int root_x = find(x, uf);
  int root_y = find(y, uf);
  if (root_x != root_y) {
    if (uf[root_x].rank > uf[root_y].rank) {
      uf[root_y].parent = root_x;
    } else if (uf[root_x].rank < uf[root_y].rank) {
      uf[root_x].parent = root_y;
    } else {
      uf[root_x].parent = root_y;
      uf[root_y].rank++;
    }
  }
}

// Function to check if two nodes are disjoint
int is_disjoint(int x, int y, struct UF* uf) {
  return find(x, uf) != find(y, uf);
}

// Function to count the number of disjoint pairs in an array
int count_disjoint_pairs(int* arr, int n, struct UF* uf) {
  int count = 0;
  for (int i = 0; i < n - 1; i++) {
    for (int j = i + 1; j < n; j++) {
      if (is_disjoint(arr[i], arr[j], uf)) {
        count++;
      }
    }
  }
  return count;
}

// Function to find the size of the largest connected component in an array
int find_largest_cc(int* arr, int n, struct UF* uf) {
  int max = -1;
  for (int i = 0; i < n - 1; i++) {
    for (int j = i + 1; j < n; j++) {
      if (!is_disjoint(arr[i], arr[j], uf)) {
        union(arr[i], arr[j], uf);
        max = max < uf[find(arr[i], uf)].rank ? uf[find(arr[i], uf)].rank : max;
      }
    }
  }
  return max;
}

// Function to log the number of milliseconds taken to perform a check for each pair and the total processing time
void log_processing_time(int* arr, int n, struct UF* uf) {
  clock_t start = clock();
  count_disjoint_pairs(arr, n, uf);
  find_largest_cc(arr, n, uf);
  clock_t end = clock();
  double elapsed = (double)(end - start) / CLOCKS_PER_SEC;
  printf("Processing time: %.3lf ms\n", elapsed * 1000);
}

int main() {
  int n = 10000000; // Size of the array
  int* arr = (int*)malloc(n * sizeof(int)); // Array to store NFAPI_CRC_INDICATION_PDU_T structures
  struct UF* uf = (struct UF*)malloc(n * sizeof(struct UF)); // Custom Union-Find data structure

  // Initialize the array and Union-Find data structure
  for (int i = 0; i < n; i++) {
    arr[i] = i;
    uf[i].parent = i;
    uf[i].rank = 1;
  }

  // Test the function with different batch sizes
  int batch_sizes[] = {1000, 5000, 10000, 20000};
  for (int i = 0; i < sizeof(batch_sizes) / sizeof(int); i++) {
    int batch_size = batch_sizes[i];
    // Fill the array with random values and perform checks
    srand(time(NULL));
    for (int j = 0; j < n; j += batch_size) {
      for (int k = 0; k < batch_size; k++) {
        arr[j + k] = rand() % n;
      }
      log_processing_time(arr, batch_size, uf);
    }
  }
  return 0;
}
