    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to read configuration settings from XML file
void readConfig(const char* filename) {
    // Open the XML file and validate its contents
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error opening XML file!\n");
        exit(1);
    }

    int tileSize;
    int worldDimensions[2];
    float cameraSpeed;

    while (!feof(fp)) {
        char line[1024];
        fgets(line, sizeof(line), fp);

        if (strncmp(line, "<tileSize>", 10) == 0) {
            sscanf(line + 10, "%d", &tileSize);
        } else if (strncmp(line, "<worldDimensions>", 17) == 0) {
            sscanf(line + 17, "%d %d", &worldDimensions[0], &worldDimensions[1]);
        } else if (strncmp(line, "<cameraSpeed>", 13) == 0) {
            sscanf(line + 13, "%f", &cameraSpeed);
        }
    }

    // Close the XML file and validate its contents
    fclose(fp);
    if (tileSize <= 0 || worldDimensions[0] <= 0 || worldDimensions[1] <= 0 || cameraSpeed <= 0) {
        printf("Invalid configuration settings!\n");
        exit(1);
    }
}

// Function to find and print the largest integer in an array
void findLargestInteger(int* arr, int size) {
    int largest = INT_MIN;
    for (int i = 0; i < size; i++) {
        if (arr[i] > largest) {
            largest = arr[i];
        }
    }
    printf("Largest integer: %d\n", largest);
}

// Function to populate a list of NFAPI_CRC_INDICATION_PDU_T structures
void populateNFAPI_CRC_INDICATION_PDU_T(int* arr, int size) {
    // Allocate memory for the list of structures
    NFAPI_CRC_INDICATION_PDU_T *list = malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list == NULL) {
        printf("Error allocating memory for list!\n");
        exit(1);
    }

    // Initialize the structures with the input data and calculate CRCFLAG
    int index = 0;
    for (int i = 0; i < size; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = arr[i];
        pdu.RNTI = i + 1;
        pdu.CRC_INDICATION_REL8_TAG = i % 2 == 0 ? 1 : 0;
        pdu.CRCFLAG = rand() % 2 == 0 ? 1 : 0;
        list[index++] = pdu;
    }
}

// Function to find and print the disjoint pairs of elements in an array
void findDisjointPairs(int* arr, int size) {
    // Initialize the Union-Find data structure
    int *parent = malloc(size * sizeof(int));
    if (parent == NULL) {
        printf("Error allocating memory for Union-Find data structure!\n");
        exit(1);
    }
    for (int i = 0; i < size; i++) {
        parent[i] = i;
    }

    // Find and print the disjoint pairs of elements in the array
    int count = 0;
    for (int i = 0; i < size - 1; i++) {
        int j = i + 1;
        while (j < size && arr[i] != arr[j]) {
            int p1 = findRoot(parent, i);
            int p2 = findRoot(parent, j);
            if (p1 != p2) {
                parent[p1] = p2;
                count++;
            }
            j++;
        }
    }
    printf("Number of disjoint pairs: %d\n", count);
}

// Helper function to find the root element of a Union-Find data structure
int findRoot(int *parent, int index) {
    while (parent[index] != index) {
        parent[index] = parent[parent[index]];
        index = parent[index];
    }
    return index;
}

// Function to measure and print the time taken to process the input integers
void processInput(int* arr, int size) {
    clock_t start = clock();

    // Read configuration settings from XML file
    readConfig("config.xml");

    // Find and print the largest integer in the array
    findLargestInteger(arr, size);

    // Populate a list of NFAPI_CRC_INDICATION_PDU_T structures
    populateNFAPI_CRC_INDICATION_PDU_T(arr, size);

    // Find and print the disjoint pairs of elements in the array
    findDisjointPairs(arr, size);

    clock_t end = clock();
    double time_spent = (double)(end - start) / CLOCKS_PER_SEC;
    printf("Time taken to process input: %f seconds\n", time_spent);
}
