class EventManager {
private:
	std::vector<Event> events;
	std::unordered_map<int, int> eventMap; // maps event ID to its index in the events vector
	int nextID = 0;

public:
	// adds a new event to the collection
	void addEvent(const Event& event) {
		events.push_back(event);
		eventMap[event.id] = events.size() - 1;
	}

	// retrieves an event by its ID
	Event getEvent(int id) const {
		if (eventMap.find(id) != eventMap.end()) {
			return events[eventMap.at(id)];
		} else {
			throw std::runtime_error("Event not found");
		}
	}

	// lists all events within a specified time range
	std::vector<Event> getEvents(const TimeRange& range) const {
		std::vector<Event> result;
		for (const auto& event : events) {
			if (range.contains(event.timestamp)) {
				result.push_back(event);
			}
		}
		return result;
	}

private:
	// compresses an event message
	std::string compressMessage(const std::string& message) const {
		if (message.size() > 1024) { // compression threshold
			return lzma_compress(message);
		} else {
			return message;
		}
	}

	// decompresses an event message
	std::string decompressMessage(const std::string& message) const {
		if (message.size() > 1024) { // compression threshold
			return lzma_decompress(message);
		} else {
			return message;
		}
	}
};

