#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>
#include <errno.h>

// Structure for storing neighbor cell information
typedef struct NeighborCellInfo {
    int id; // Unique ID of the neighbor cell
    char *cell_id; // Cell ID of the neighbor cell
} NeighborCellInfo;

// Structure for storing SRS parameters
typedef struct SrsParams {
    int srs_en; // Enable/disable SRS transmission
    int srs_bandwidth; // Bandwidth for SRS transmission
    int srs_cyclic_shift; // Cyclic shift for SRS transmission
} SrsParams;

// Structure for storing network interface configuration
typedef struct NetworkInterfaceConfig {
    int interfaceId; // Unique ID of the network interface
    NeighborCellInfo *neighborCells; // List of neighbor cells
    SrsParams srsParams; // SRS parameters
} NetworkInterfaceConfig;

// Custom allocator for managing memory usage
void* custom_alloc(size_t size) {
    void *ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory\n");
        exit(1);
    }
    return ptr;
}

// Custom deallocator for managing memory usage
void custom_free(void *ptr) {
    free(ptr);
}

// Thread-safe function for initializing a dynamic array of NetworkInterfaceConfig structures
NetworkInterfaceConfig* init_network_interface_configs(int num_interfaces, int num_neighbor_cells, int srs_en, int srs_bandwidth, int srs_cyclic_shift) {
    // Allocate memory for the dynamic array of NetworkInterfaceConfig structures
    NetworkInterfaceConfig **configs = custom_alloc(sizeof(NetworkInterfaceConfig *) * num_interfaces);
    memset(configs, 0, sizeof(NetworkInterfaceConfig *) * num_interfaces);

    // Initialize each NetworkInterfaceConfig structure in the array
    for (int i = 0; i < num_interfaces; i++) {
        configs[i] = custom_alloc(sizeof(NetworkInterfaceConfig));
        memset(configs[i], 0, sizeof(NetworkInterfaceConfig));
        configs[i]->interfaceId = i + 1; // Start at 1 for unique IDs
        configs[i]->neighborCells = custom_alloc(sizeof(NeighborCellInfo) * num_neighbor_cells);
        memset(configs[i]->neighborCells, 0, sizeof(NeighborCellInfo) * num_neighbor_cells);
        configs[i]->srsParams.srs_en = srs_en;
        configs[i]->srsParams.srs_bandwidth = srs_bandwidth;
        configs[i]->srsParams.srs_cyclic_shift = srs_cyclic_shift;
    }

    // Initialize the neighbor cell list in each NetworkInterfaceConfig structure
    for (int i = 0; i < num_interfaces; i++) {
        for (int j = 0; j < num_neighbor_cells; j++) {
            configs[i]->neighborCells[j].id = j + 1; // Start at 1 for unique IDs
            configs[i]->neighborCells[j].cell_id = "Cell ID";
        }
    }

    return configs;
}

// Thread-safe function for serializing a NetworkInterfaceConfig structure to a string
char* serialize_network_interface_config(NetworkInterfaceConfig *config) {
    // Allocate memory for the serialized string
    char *serialized = custom_alloc(sizeof(char) * 1024);
    memset(serialized, 0, sizeof(char) * 1024);

    // Serialize the NetworkInterfaceConfig structure to a JSON-like format
    sprintf(serialized, "{\"interfaceId\":%d,\"neighborCells\":[", config->interfaceId);
    for (int i = 0; i < num_neighbor_cells; i++) {
        if (i != 0) {
            strcat(serialized, ",");
        }
        sprintf(serialized + strlen(serialized), "{\"id\":%d,\"cellId\":\"%s\"}", config->neighborCells[i].id, config->neighborCells[i].cell_id);
    }
    strcat(serialized, "],\"srsParams\":{\"srsEn\":%d,\"srsBandwidth\":%d,\"srsCyclicShift\":%d}}", srs_en, srs_bandwidth, srs_cyclic_shift);

    return serialized;
}

// Thread-safe function for deserializing a NetworkInterfaceConfig structure from a string
NetworkInterfaceConfig* deserialize_network_interface_config(char *serialized) {
    // Parse the JSON-like format of the serialized string
    NetworkInterfaceConfig *config = custom_alloc(sizeof(NetworkInterfaceConfig));
    memset(config, 0, sizeof(NetworkInterfaceConfig));
    config->interfaceId = atoi(strtok(serialized, ","));
    config->neighborCells = custom_alloc(sizeof(NeighborCellInfo) * num_neighbor_cells);
    memset(config->neighborCells, 0, sizeof(NeighborCellInfo) * num_neighbor_cells);
    for (int i = 0; i < num_neighbor_cells; i++) {
        config->neighborCells[i].id = atoi(strtok(NULL, ","));
        config->neighborCells[i].cell_id = strdup(strtok(NULL, "}"));
    }
    config->srsParams.srs_en = atoi(strtok(NULL, ","));
    config->srsParams.srs_bandwidth = atoi(strtok(NULL, ","));
    config->srsParams.srs_cyclic_shift = atoi(strtok(NULL, "}"));

    return config;
}

// Thread-safe function for freeing the memory of a NetworkInterfaceConfig structure
void free_network_interface_config(NetworkInterfaceConfig *config) {
    // Free the memory allocated for each field of the NetworkInterfaceConfig structure
    if (config->neighborCells != NULL) {
        free(config->neighborCells);
    }
    if (config->srsParams.srs_en != NULL) {
        free(config->srsParams.srs_en);
    }
    if (config->srsParams.srs_bandwidth != NULL) {
        free(config->srsParams.srs_bandwidth);
    }
    if (config->srsParams.srs_cyclic_shift != NULL) {
        free(config->srsParams.srs_cyclic_shift);
    }
}']

