['```
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <unistd.h>
#include <semaphore.h>

// Memory pool parameters
#define POOL_SIZE 1024 * 1024 * 16 // 16 MB
#define BLOCK_SIZE sizeof(long) * 2 + sizeof(int)

// Hash table parameters
#define HASH_TABLE_SIZE 1024
#define HASH_BUCKETS (HASH_TABLE_SIZE / sizeof(long))

// Record structure
typedef struct {
    long offset;
    int key;
} record_t;

// Memory pool management
pthread_mutex_t memory_pool_lock = PTHREAD_MUTEX_INITIALIZER;
sem_t memory_pool_sem;
long* memory_pool = NULL;
size_t memory_pool_used = 0;
size_t memory_pool_size = 0;

// Hash table management
pthread_mutex_t hash_table_lock = PTHREAD_MUTEX_INITIALIZER;
long* hash_table[HASH_BUCKETS];

// Random number generator
unsigned int seed = 1234567890;

// Function to manage memory and data for a dynamic record store, supporting concurrent access from multiple threads
void manage_record_store(int num_records) {
    // Initialize the memory pool
    init_memory_pool();

    // Initialize the hash table
    init_hash_table();

    // Populate the records
    for (int i = 0; i < num_records; i++) {
        record_t* new_record = malloc(sizeof(record_t));
        if (!new_record) {
            perror("Failed to allocate memory for record");
            exit(1);
        }
        new_record->offset = get_random_offset();
        new_record->key = get_unique_key();
        insert_record(new_record);
    }
}

// Initialize the memory pool
void init_memory_pool() {
    // Allocate the memory pool and initialize the semaphore
    memory_pool = (long*)malloc(POOL_SIZE);
    if (!memory_pool) {
        perror("Failed to allocate memory for memory pool");
        exit(1);
    }
    memory_pool_size = POOL_SIZE;
    sem_init(&memory_pool_sem, 0, 1);
}

// Insert a record into the memory pool
void insert_record(record_t* new_record) {
    pthread_mutex_lock(&memory_pool_lock);
    if (memory_pool_used >= memory_pool_size - BLOCK_SIZE) {
        // Memory pool is full, expand it by 50%
        size_t new_size = memory_pool_size * 1.5;
        long* new_pool = realloc(memory_pool, new_size);
        if (!new_pool) {
            perror("Failed to expand memory pool");
            exit(1);
        }
        memory_pool = new_pool;
        memory_pool_size = new_size;
    }
    // Write the record to the next available slot in the memory pool
    long* record_ptr = &memory_pool[memory_pool_used / sizeof(long)];
    *record_ptr++ = new_record->offset;
    *record_ptr++ = new_record->key;
    // Update the used memory counter and release the lock
    memory_pool_used += BLOCK_SIZE;
    pthread_mutex_unlock(&memory_pool_lock);
}

// Get a random offset within the specified range
long get_random_offset() {
    long min = 1, max = POOL_SIZE - BLOCK_SIZE;
    return (long)(min + ((max - min + 1) * rand_r(&seed)) / RAND_MAX);
}

// Get a unique key for the new record
int get_unique_key() {
    int key = 0;
    do {
        // Generate a random key and check for uniqueness
        key = (int)(10000 + rand_r(&seed) % 90000);
        pthread_mutex_lock(&hash_table_lock);
        if (find_key(key)) {
            // Key is not unique, generate a new one
            key = 0;
        } else {
            // Insert the new key into the hash table
            insert_key(key);
        }
        pthread_mutex_unlock(&hash_table_lock);
    } while (key == 0);
    return key;
}

// Find a key in the hash table
int find_key(int key) {
    for (int i = 0; i < HASH_BUCKETS; i++) {
        if (hash_table[i] != NULL && *hash_table[i] == key) {
            return 1;
        }
    }
    return 0;
}

// Insert a key into the hash table
void insert_key(int key) {
    int index = key % HASH_BUCKETS;
    if (hash_table[index] == NULL) {
        // Create a new bucket for the key
        long* new_bucket = malloc(sizeof(long));
        hash_table[index] = new_bucket;
    } else {
        // Append the key to the existing bucket
        long* last_key = hash_table[index];
        while (*last_key != 0) {
            if (*last_key == key) {
                return;
            }
            last_key++;
        }
    }
    *hash_table[index]++ = key;
}

// Initialize the hash table
void init_hash_table() {
    for (int i = 0; i < HASH_BUCKETS; i++) {
        hash_table[i] = NULL;
    }
}

// Clean up the memory pool and hash table
void cleanup() {
    sem_destroy(&memory_pool_sem);
    free(memory_pool);
    for (int i = 0; i < HASH_BUCKETS; i++) {
        if (hash_table[i] != NULL) {
            free(hash_table[i]);
        }
    }
}
```

This solution is based on the idea of using a memory pool to store the records, and a hash table to keep track of the unique keys. The `manage_record_store` function is responsible for initializing the memory pool, initializing the hash table, populating the records, and cleaning up the memory when it's done.

The memory pool is implemented as an array of long integers, where each integer represents a record in the database. The `init_memory_pool` function allocates memory for the array and initializes the semaphore used to synchronize access to the memory pool. The `insert_record` function writes a new record to the next available slot in the memory pool, and updates the used memory counter.

The hash table is implemented as an array of pointers, where each pointer points to a bucket that contains keys for the records in the database. The `init_hash_table` function initializes all buckets to NULL, and the `insert_key` function creates a new bucket or appends a key to an existing one. The `find_key` function searches for a key in all buckets and returns 1 if it finds the key, otherwise it returns 0.

The `get_random_offset` function generates a random offset within the specified range, and the `get_unique_key` function generates a unique key by first generating a random key and then checking for its uniqueness in the hash table. If the generated key is not unique, it generates a new one until a unique key is found.

Finally, the `cleanup` function destroys the semaphore used to synchronize access to the memory pool and frees all allocated memory.']

['Here is a sample C++ program that integrates with an existing monitoring pipeline to monitor a distributed service's health under load-testing conditions, using the Boost library to create a Sandesh client capable of sending a series of GET requests to a service endpoint while adhering to operational constraints such as limiting the number of simultaneous requests to 100.
```cpp
#include <iostream>
#include <boost/asio.hpp>
#include <boost/bind.hpp>
#include <boost/function.hpp>
#include <string>
#include <vector>

using namespace boost::asio;
using namespace std;

// InterfaceTable class test double with overridden FindVmUuidFromMetadataIp function
class InterfaceTableTestDouble {
public:
    virtual string FindVmUuidFromMetadataIp(string metadata_ip) {
        // Artificial delay between 50ms and 200ms for each request
        this_thread::sleep_for(chrono::milliseconds(random() % 150));
        return "vm-uuid";
    }
};

// Sandesh client class with built-in logging functionality
class SandeshClient {
public:
    // Constructor
    SandeshClient(string url, int max_requests) : url_(url), max_requests_(max_requests) {}

    // Send GET request to service endpoint and return response
    string GetRequest(string vm_uuid) {
        // Prepare HTTP headers for the GET request
        http::request<http::string_body> req;
        req.set("Host", url_.host);
        req.set("Accept-Encoding", "gzip");

        // Send GET request and wait for response
        auto res = http::request<http::string_body>(req).get();

        // Check if response is successful
        string status_code;
        if (res->status_code() == 200) {
            status_code = "Success";
        } else {
            status_code = "Timeout";
        }

        // Log request information and return response
        cout << "Request: " << url_.path << ", Metadata IP: " << vm_uuid << endl;
        cout << "Status Code: " << res->status_code() << endl;
        cout << "Response Body: " << res->body().string() << endl;

        return status_code;
    }

private:
    // URL of the service endpoint
    http::url url_;

    // Maximum number of simultaneous requests
    int max_requests_;
};

// Main function
int main(int argc, char* argv[]) {
    // Set up Sandesh client with maximum number of simultaneous requests
    SandeshClient sandesh_client("http://example.com/service", 100);

    // Create test double for InterfaceTable class
    InterfaceTableTestDouble interface_table;

    // Initialize vector to store request status codes
    vector<string> status_codes;

    // Send GET requests to service endpoint while adhering to operational constraints and logging detailed information
    for (int i = 0; i < 1000; i++) {
        string vm_uuid = interface_table.FindVmUuidFromMetadataIp("127.0.0.1");
        string status_code = sandesh_client.GetRequest(vm_uuid);
        status_codes.push_back(status_code);
    }

    // Print request statistics and metrics
    cout << "Total number of requests: " << status_codes.size() << endl;
    cout << "Number of successful responses: " << count(status_codes.begin(), status_codes.end(), "Success") << endl;
    cout << "Number of timeouts: " << count(status_codes.begin(), status_codes.end(), "Timeout") << endl;
    cout << "Average response time (ms): " << accumulate(status_codes.begin(), status_codes.end(), 0, [](int sum, string status_code) { return sum + status_code == "Success" ? 1 : 0; }) / status_codes.size() << endl;

    // Export metrics in Prometheus format for easy integration into an existing monitoring ecosystem
    cout << "# HELP sandesh_requests_total The total number of Sandesh requests." << endl;
    cout << "# TYPE sandesh_requests_total counter" << endl;
    cout << "sandesh_requests_total " << status_codes.size() << endl;
    cout << "# HELP sandesh_successful_responses_total The total number of successful Sandesh responses." << endl;
    cout << "# TYPE sandesh_successful_responses_total counter" << endl;
    cout << "sandesh_successful_responses_total " << count(status_codes.begin(), status_codes.end(), "Success") << endl;
    cout << "# HELP sandesh_timeouts_total The total number of Sandesh timeouts." << endl;
    cout << "# TYPE sandesh_timeouts_total counter" << endl;
    cout << "sandesh_timeouts_total " << count(status_codes.begin(), status_codes.end(), "Timeout") << endl;

    return 0;
}
```
Note that this is just a sample program and should be tailored to the specific requirements of the service being monitored and the monitoring pipeline in use.']

