        // Reallocate the array with more space for elements
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(crc_array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (MAX_CRC_ARRAY_SIZE + 1));
        if (new_array == NULL) {
            // Handle memory allocation failure gracefully
            pthread_mutex_unlock(&crc_mutex);
            return;
        }
        crc_array = new_array;
    }

    // Generate a random CRCFLAG value for the new element
    uint8_t CRCFLAG = rand() % 256;

    // Add the new element to the array
    crc_array->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    crc_array->RNTI = RNTI;
    crc_array->CRCFLAG = CRCFLAG;
    crc_array->count++;

    // Unlock the mutex and return
    pthread_mutex_unlock(&crc_mutex);
}

