    // Search for the element in the array with the given RX_UE_INFORMATION_TAG and RNTI
    for (int i = 0; i < crc_array->count; i++) {
        if (crc_array[i].RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG && crc_array[i].RNTI == RNTI) {
            // Return the element if found
            pthread_mutex_unlock(&crc_mutex);
            return &crc_array[i];
        }
