#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <stdbool.h>
#include <time.h>

// Structure definition
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Custom memory pool for efficient allocation and deallocation of structures
struct MemoryPool {
    struct MemoryPool *next;
};

// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
void createAndPopulateList(int numElements, int minRNTIValue, int maxRNTIValue) {
    // Initialize memory pool
    struct MemoryPool *memoryPool = NULL;
    struct MemoryPool **lastMemoryBlock = &memoryPool;

    // Validate RNTI values before population
    for (int i = 0; i < numElements; i++) {
        int rntiValue = rand() % (maxRNTIValue - minRNTIValue + 1) + minRNTIValue;
        if (rntiValue > maxRNTIValue || rntiValue < minRNTIValue) {
            continue;
        }
    }

    // Populate list of NFAPI_CRC_INDICATION_PDU_T structures
    for (int i = 0; i < numElements; i++) {
        int rntiValue = rand() % (maxRNTIValue - minRNTIValue + 1) + minRNTIValue;
        NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pdu->RX_UE_INFORMATION_TAG = i;
        pdu->RNTI = rntiValue;
        pdu->CRC_INDICATION_REL8_TAG = rand() % 2;
        // Add structure to memory pool
        struct MemoryPool *newMemoryBlock = malloc(sizeof(struct MemoryPool));
        newMemoryBlock->next = NULL;
        lastMemoryBlock->next = newMemoryBlock;
        lastMemoryBlock = newMemoryBlock;
    }
}

// Function to free memory allocated by createAndPopulateList function
void freeList(struct MemoryPool *memoryPool) {
    while (memoryPool != NULL) {
        struct MemoryPool *nextMemoryBlock = memoryPool->next;
        free(memoryPool);
        memoryPool = nextMemoryBlock;
    }
}
