Connection* connection_pool = (Connection*)malloc(MAX_CONNECTIONS * sizeof(Connection));
Record* records = (Record*)malloc(MAX_RECORDS * RECORD_SIZE);
sem_t semaphore;
pthread_mutex_t mutex;
pthread_cond_t cond;
