bool shutdown = false;
int connection_count = 0;

void initialize_pool() {
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        Connection *c = &connection_pool[i];
        c->socket = -1;
        c->last_active = time(NULL);
        c->active = false;
    }
}

void establish_new_connection() {
    int socket = socket(AF_INET, SOCK_STREAM, 0);
    if (socket < 0) {
        perror("Error creating socket");
        exit(1);
    }
    struct sockaddr_in serv_addr;
    memset(&serv_addr, '0', sizeof(struct sockaddr_in));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(80); // replace with server port number
    if (inet_pton(AF_INET, "127.0.0.1", &serv_addr.sin_addr) <= 0) {
        perror("Error initializing socket address");
        exit(1);
    }
    if (connect(socket, (struct sockaddr*)&serv_addr, sizeof(struct sockaddr)) < 0) {
        perror("Error connecting to server");
        close(socket);
        return;
    }
    Connection *c = get_available_connection();
    if (!c) {
        fprintf(stderr, "Connection pool exhausted\n");
        close(socket);
        return;
    }
    c->socket = socket;
    c->last_active = time(NULL);
    c->active = true;
}

Connection* get_available_connection() {
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        Connection *c = &connection_pool[i];
        if (c->socket >= 0 && c->active) return c;
    }
    return NULL;
}

void close_connection(Connection *c) {
    if (c->socket >= 0) {
        shutdown(c->socket, SHUT_RDWR);
        close(c->socket);
    }
    c->socket = -1;
    c->active = false;
}

void check_connections() {
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        Connection *c = &connection_pool[i];
        if (c->socket >= 0) {
            if (!c->active) close_connection(c);
            else {
                time_t current_time = time(NULL);
                if (difftime(current_time, c->last_active) > CONNECTION_TIMEOUT) {
                    fprintf(stderr, "Connection timed out\n");
                    close_connection(c);
                }
            }
        }
    }
}

void monitor_pool() {
    while (!shutdown) {
        check_connections();
        establish_new_connection();
        sleep(CONNECTION_TIMEOUT / 2); // backoff strategy
    }
}

int main(int argc, char *argv[]) {
    initialize_pool();
    populate_records(records, MAX_RECORDS);
    sem_init(&semaphore, 0, 1);
    pthread_mutex_init(&mutex, NULL);
    pthread_cond_init(&cond, NULL);
    pthread_t monitor;
    pthread_create(&monitor, NULL, &monitor_pool, NULL);
    while (true) {
        sem_wait(&semaphore);
        if (connection_available) {
            Connection *c = get_available_connection();
            if (!c) {
                fprintf(stderr, "Connection pool exhausted\n");
                continue;
            }
            int record = get_random_record();
            c->last_active = time(NULL);
            c->active = true;
            sem_post(&semaphore);
            // process the record using the connection
        } else {
            sem_post(&semaphore);
            fprintf(stderr, "Connection pool exhausted\n");
            break;
        }
    }
    pthread_join(monitor, NULL);
    return 0;
}

int get_random_record() {
    int record = -1;
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (records[i].active) {
            record = i;
            break;
        }
    }
    return record;
}
