#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

// Custom NetworkPacket structure
struct NetworkPacket {
    int id;
    unsigned long timestamp;
    char* sourceIP;
    char* destinationIP;
    size_t payloadSize;
};

// Queue node structure
struct Node {
    struct NetworkPacket packet;
    struct Node* next;
};

// Queue data structure
struct Queue {
    struct Node* head;
    struct Node* tail;
    pthread_mutex_t mutex;
    int size;
};

// Initialize queue with given capacity
struct Queue* initializeQueue(int capacity) {
    struct Queue* queue = (struct Queue*)malloc(sizeof(struct Queue));
    if (!queue) return NULL;
    queue->head = NULL;
    queue->tail = NULL;
    queue->mutex = PTHREAD_MUTEX_INITIALIZER;
    queue->size = 0;
    return queue;
}

// Enqueue packet with given priority
bool enqueue(struct Queue* queue, struct NetworkPacket* packet, int priority) {
    if (!queue || !packet) return false;

    // Lock mutex before modifying queue
    pthread_mutex_lock(&queue->mutex);

    // Check for duplicate packet ID
    struct Node* node = queue->head;
    while (node != NULL) {
        if (node->packet.id == packet->id) {
            pthread_mutex_unlock(&queue->mutex);
            return false;
        }
        node = node->next;
    }

    // Create new node with given priority
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    if (!newNode) {
        pthread_mutex_unlock(&queue->mutex);
        return false;
    }
    newNode->packet = *packet;
    newNode->next = NULL;

    // Update head and tail pointers
    if (queue->head == NULL) {
        queue->head = newNode;
        queue->tail = newNode;
    } else {
        queue->tail->next = newNode;
        queue->tail = newNode;
    }
    queue->size++;

    // Unlock mutex and return success
    pthread_mutex_unlock(&queue->mutex);
    return true;
}

// Dequeue packet with given priority
bool dequeue(struct Queue* queue, struct NetworkPacket** packet, int priority) {
    if (!queue || !packet) return false;

    // Lock mutex before modifying queue
    pthread_mutex_lock(&queue->mutex);

    // Check for empty queue
    if (queue->head == NULL) {
        *packet = NULL;
        pthread_mutex_unlock(&queue->mutex);
        return false;
    }

    // Find node with given priority
    struct Node* node = queue->head;
    while (node != NULL && node->packet.priority > priority) {
        node = node->next;
    }

    // Check for invalid priority or empty queue
    if (node == NULL || node->packet.priority <= priority) {
        *packet = NULL;
        pthread_mutex_unlock(&queue->mutex);
        return false;
    }

    // Remove node from queue and update head and tail pointers
    if (node == queue->head) {
        struct Node* nextNode = node->next;
        free(node);
        queue->head = nextNode;
        if (queue->tail == node) {
            queue->tail = NULL;
        }
    } else if (node == queue->tail) {
        struct Node* prevNode = node->prev;
        free(node);
        queue->tail = prevNode;
        prevNode->next = NULL;
    } else {
        struct Node* nextNode = node->next;
        struct Node* prevNode = node->prev;
        prevNode->next = nextNode;
        nextNode->prev = prevNode;
        free(node);
    }
    queue->size--;

    // Set output packet and unlock mutex
    *packet = &node->packet;
    pthread_mutex_unlock(&queue->mutex);
    return true;
}

// Destroy queue and free all memory
void destroyQueue(struct Queue* queue) {
    if (!queue) return;

    // Lock mutex before modifying queue
    pthread_mutex_lock(&queue->mutex);

    // Free all nodes in queue
    struct Node* node = queue->head;
    while (node != NULL) {
        struct Node* nextNode = node->next;
        free(node);
        node = nextNode;
    }

    // Unlock mutex and free queue structure
    pthread_mutex_unlock(&queue->mutex);
    free(queue);
}
