// Structures for representing nodes and values
typedef struct Node {
    int key;
    struct Value* values;
} Node;

typedef struct Value {
    long offset;
    struct Node* node;
} Value;

// Data structure to represent the list of nodes
struct List {
    Node** nodes;
    size_t size;
};

// Lock-free data structure for thread-safe operations
struct LockFreeList {
    Node** nodes;
    size_t size;
    pthread_mutex_t* mutex;
};

// Function to initialize the list with a given number of nodes
void init_list(struct List* list, size_t num_nodes) {
    list->nodes = (Node**)malloc(num_nodes * sizeof(Node*));
    for (size_t i = 0; i < num_nodes; i++) {
        list->nodes[i] = NULL;
    }
    list->size = num_nodes;
}

// Function to add a node with a given integer key to the list
void add_node(struct List* list, int key) {
    // Check if key is already present in the list
    for (size_t i = 0; i < list->size; i++) {
        if (list->nodes[i] != NULL && list->nodes[i]->key == key) {
            return;
        }
    }
    // Add new node to the end of the list
    list->nodes[list->size++] = malloc(sizeof(Node));
    Node* new_node = list->nodes[list->size - 1];
    new_node->key = key;
    new_node->values = NULL;
}

// Function to insert a value with a given offset into the linked list of a node
void insert_value(struct List* list, int key, long offset) {
    // Find the node with the given key in the list
    for (size_t i = 0; i < list->size; i++) {
        if (list->nodes[i] != NULL && list->nodes[i]->key == key) {
            Node* node = list->nodes[i];
            // Add new value to the end of the linked list
            Value* new_value = malloc(sizeof(Value));
            new_value->offset = offset;
            new_value->node = node;
            new_value->next = NULL;
            if (node->values != NULL) {
                Value* last_value = node->values;
                while (last_value->next != NULL) {
                    last_value = last_value->next;
                }
                last_value->next = new_value;
            } else {
                node->values = new_value;
            }
            return;
        }
    }
}

// Function to free the memory allocated for the list and its nodes
void free_list(struct List* list) {
    for (size_t i = 0; i < list->size; i++) {
        if (list->nodes[i] != NULL) {
            free(list->nodes[i]);
        }
    }
    free(list);
}

