        if (list->nodes[i] != NULL && list->nodes[i]->key == key) {
            Node* node = list->nodes[i];
            // Add new value to the end of the linked list
            Value* new_value = malloc(sizeof(Value));
            new_value->offset = offset;
            new_value->node = node;
            new_value->next = NULL;
            if (node->values != NULL) {
                Value* last_value = node->values;
                while (last_value->next != NULL) {
                    last_value = last_value->next;
                }
                last_value->next = new_value;
            } else {
                node->values = new_value;
            }
            return;
        }
    }
}

