    for (int i = 0; i < 5; i++) {
        int key = rand() % 100;
        add_node(list, key);
    }

    // Insert values with offsets into the linked lists of these nodes
    for (int i = 0; i < 5; i++) {
        int key = rand() % 100;
        long offset = rand();
        lock_free_insert_value(list, key, offset);
    }

    // Free the memory allocated for the list and its nodes
    free_list(list);

    return 0;
}
