        /// Parses an XML document using XPath and returns the first element that matches a given name along with its namespace.
        /// Supports both qualified and unqualified names for element matching, allowing users to specify whether they want to match only by tag name or consider namespace as well.
        /// Returns a list of all elements that match the specified name and namespace pair, if any. If no elements are found, returns an empty list. If multiple elements are found, returns all matching elements.
        /// Handles cases where the XML document is malformed or contains invalid namespaces gracefully, without crashing, but logs appropriate warnings. Integrates with an existing logging framework for consistent error reporting.
        /// Ensures the function can handle large XML documents efficiently, balancing memory usage and parsing speed. You may need to explore different XML parsing libraries (e.g., System.Xml.Linq, System.Xml, third-party libraries) and choose the one that best meets your performance and scalability needs.
        /// The function should integrate with an existing XML validation service to ensure that the document structure adheres to predefined schemas. This integration may require handling potential network latency and ensuring robust error handling for service failures.
        /// Consider the impact of external dependencies on the parsing process. If the XML source is fetched from an external API, implement retry logic and timeouts to handle network failures gracefully.
        /// Optimize the function for concurrent access in a multi-threaded environment, ensuring thread safety and avoiding race conditions.
        /// Document your code thoroughly, including assumptions about the input format and any external services used. This will aid future maintenance and allow other developers to understand the rationale behind certain design choices.
        /// Profile the function under different load conditions to identify bottlenecks and optimize performance. Consider caching frequently accessed elements or parts of the XML tree to improve lookup times.
        /// Ensure that the function can be easily tested and integrated into an existing codebase. Provide unit tests and integration tests to cover various edge cases and ensure reliability.
        /// </summary>
        public static List<XElement> GetElementsByName(string xml, string name, bool includeNamespace = false)
        {
            // 1. Parse the XML document using XPath
            var doc = XDocument.Parse(xml);

            // 2. Define an XPath query to find elements by name and namespace (if applicable)
            string xpathQuery = $"//{{{includeNamespace ? "*" : ""}}{name}}}";

            // 3. Use the XPath query to select all matching elements in the document
            var elements = doc.XPathSelectElements(xpathQuery).ToList();

            // 4. Handle cases where no matching elements are found
            if (elements.Count == 0)
            {
                return new List<XElement>();
            }

            // 5. Handle cases where multiple matching elements are found
            else if (elements.Count > 1)
            {
                return elements;
            }

            // 6. Return the first matching element, along with its namespace (if applicable)
            var element = elements[0];
            var namespaceUri = includeNamespace ? element.GetNamespaceOfPrefix(element.Name.Prefix.Value) : null;
            return new List<XElement> { new XElement(element.Name, element.Attributes(), element.Elements()) { Name = name, Namespace = namespaceUri } };
        }
    }
}
