// Structures to store frame metadata
typedef struct NFAPI_L2_RX_FRAME {
    uint32_t L2_RX_FRAME_TAG;
    uint32_t L3_RX_FRAME_TAG;
    uint64_t timestamp;
} NFAPI_L2_RX_FRAME;

// Function to manage dynamic list of frames
void manage_frames(NFAPI_L2_RX_FRAME *frames, int frame_count) {
    // Allocate memory for the frames if necessary
    if (frame_count > 0 && frames == NULL) {
        frames = malloc(sizeof(NFAPI_L2_RX_FRAME) * MAX_FRAMES);
    }

    // Handle potential frame duplication by comparing timestamps
    for (int i = 0; i < frame_count - 1; i++) {
        if (frames[i].timestamp == frames[i + 1].timestamp) {
            // Skip the duplicate frame and adjust the frame count accordingly
            memmove(&frames[i], &frames[i + 1], (frame_count - i - 1) * FRAME_SIZE);
            frame_count--;
        }
    }

    // Log performance metrics for each frame
    for (int i = 0; i < frame_count; i++) {
        printf("Frame %d: L2_RX_FRAME_TAG=%u, L3_RX_FRAME_TAG=%u, timestamp=%lu\n", i + 1, frames[i].L2_RX_FRAME_TAG, frames[i].L3_RX_FRAME_TAG, frames[i].timestamp);
