}

struct NFAPI_CRC_INDICATION_PDU_T *nfapi_pop_crc_indication_pdu(void) {
  pthread_mutex_lock(&nfapi_crc_indication_pdu_list_lock);
  if (nfapi_crc_indication_pdu_list_size <= 0) {
    printf("No CRC indications available, returning NULL\n");
    return NULL;
  } else {
    struct NFAPI_CRC_INDICATION_PDU_T *pdu = nfapi_crc_indication_pdu_list[--nfapi_crc_indication_pdu_list_size];
    return pdu;
  }
  pthread_mutex_unlock(&nfapi_crc_indication_pdu_list_lock);
}

void nfapi_clear_crc_indication_pdu_list(void) {
  pthread_mutex_lock(&nfapi_crc_indication_pdu_list_lock);
  for (int i = 0; i < nfapi_crc_indication_pdu_list_size; ++i) {
    struct NFAPI_CRC_INDICATION_PDU_T *pdu = nfapi_crc_indication_pdu_list[i];
    nfapi_free_crc_indication_pdu(pdu);
  }
  nfapi_crc_indication_pdu_list_size = 0;
  pthread_mutex_unlock(&nfapi_crc_indication_pdu_list_lock);
}
