typedef struct {
    float value;
    char* string;
    struct geometric_shape shape;
} custom_object;

int allocate_memory(custom_object** list, size_t num_elements) {
    if (num_elements <= 0 || num_elements > MAX_MEMORY_LIMIT) {
        return -1;
    }
    *list = malloc(sizeof(custom_object) * num_elements);
    if (*list == NULL) {
        fprintf(stderr, "Error: Insufficient memory for allocation\n");
        return -1;
    }
    memset(*list, 0, sizeof(custom_object) * num_elements);
    return 0;
}

int populate_list(custom_object** list, size_t num_elements, char* strings[], size_t string_lengths[]) {
    int i;
    for (i = 0; i < num_elements; i++) {
        (*list)[i].string = malloc(sizeof(char) * string_lengths[i]);
        if ((*list)[i].string == NULL) {
            fprintf(stderr, "Error: Insufficient memory for string allocation\n");
            return -1;
        }
        memcpy((*list)[i].string, strings[i], sizeof(char) * string_lengths[i]);
        (*list)[i].shape = (struct geometric_shape){};
    }
    return 0;
}

int initialize_shape(custom_object** list, size_t num_elements, struct geometric_shape* shape) {
    int i;
    for (i = 0; i < num_elements; i++) {
        (*list)[i].shape = *shape;
    }
    return 0;
}

int validate_data(custom_object** list, size_t num_elements) {
    int i;
    for (i = 1; i < num_elements; i++) {
        if ((*list)[i].string == (*list)[i-1].string) {
            fprintf(stderr, "Error: Duplicate string value found\n");
            return -1;
        }
    }
    return 0;
}

int free_memory(custom_object** list, size_t num_elements) {
    int i;
    for (i = 0; i < num_elements; i++) {
        free((*list)[i].string);
    }
    free(*list);
    *list = NULL;
    return 0;
}
