#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <assert.h>
#include <stdint.h>

// Define the record structure
typedef struct {
    int key;
    long value;
} Record;

// Define the collection of records
typedef struct {
    size_t capacity; // Current capacity of the array
    size_t size; // Current number of elements in the array
    Record* records; // Array of records
} RecordCollection;

// Function to allocate memory for a new record
Record* allocRecord(int key, long value) {
    Record* newRecord = malloc(sizeof(Record));
    assert(newRecord != NULL);
    newRecord->key = key;
    newRecord->value = value;
    return newRecord;
}

// Function to add a record to the collection
void addRecord(RecordCollection* collection, int key, long value) {
    // Check if the array needs to be resized
    if (collection->size == collection->capacity) {
        // Double the capacity of the array
        collection->capacity *= 2;
        // Reallocate memory for the new records
        Record* newRecords = realloc(collection->records, collection->capacity * sizeof(Record));
        assert(newRecords != NULL);
        collection->records = newRecords;
    }
    // Add the new record to the array
    collection->records[collection->size].key = key;
    collection->records[collection->size].value = value;
    collection->size++;
}

// Function to retrieve a record from the collection by key
Record* getRecord(RecordCollection* collection, int key) {
    // Iterate through the records until the desired key is found
    for (int i = 0; i < collection->size; i++) {
        if (collection->records[i].key == key) {
            return &collection->records[i];
        }
    }
    // If the key was not found, return NULL
    return NULL;
}

// Function to delete a record from the collection by key
void deleteRecord(RecordCollection* collection, int key) {
    // Iterate through the records until the desired key is found
    for (int i = 0; i < collection->size; i++) {
        if (collection->records[i].key == key) {
            // If the key was found, move all subsequent records one position back in the array
            for (int j = i + 1; j < collection->size; j++) {
                collection->records[j - 1] = collection->records[j];
            }
            // Decrement the size of the collection
            collection->size--;
            break;
        }
    }
}

// Function to free the memory used by the collection
void freeCollection(RecordCollection* collection) {
    free(collection->records);
}

int main() {
    // Test the functions
    RecordCollection* collection = malloc(sizeof(RecordCollection));
    assert(collection != NULL);
    collection->capacity = 10;
    collection->size = 0;
    collection->records = malloc(10 * sizeof(Record));
    assert(collection->records != NULL);
    addRecord(collection, 1, 2);
    addRecord(collection, 2, 4);
    addRecord(collection, 3, 6);
    Record* record = getRecord(collection, 2);
    printf("Value of record with key 2: %ld\n", record->value);
    deleteRecord(collection, 2);
    freeCollection(collection);
    return 0;
}
```
This code defines a `Record` structure to store the key and value of each record, and a `RecordCollection` structure to store an array of `Record` structures. The `addRecord` function allocates memory for a new record and adds it to the collection, while the `getRecord` function searches for a record with a given key and returns its address if found, or NULL otherwise. The `deleteRecord` function removes a record from the collection by moving all subsequent records one position back in the array and decrementing the size of the collection. Finally, the `freeCollection` function frees the memory used by the collection.

The code also includes a test program that demonstrates how to use the functions to manage a dynamic collection of record structures. It creates a new collection with an initial capacity of 10 records and adds three records to it using the `addRecord` function, then retrieves the value of the second record using the `getRecord` function and prints it to the console. Finally, it removes the second record from the collection using the `deleteRecord` function and frees the memory used by the collection using the `freeCollection` function.']

