void init_network_interface(LTE_TRANSPORT_CHANNEL_CONFIGS *configs) {
    // Initialize memory allocation failures structures
    LTE_TRANSPORT_CHANNEL_ALLOC_FAILURES alloc_failed;
    memset(&alloc_failed, 0, sizeof(LTE_TRANSPORT_CHANNEL_ALLOC_FAILURES));
    LTE_TRANSPORT_CHANNEL_CONFIG_ALLOC_FAILURES config_alloc_failed;
