    memset(&config_modulation_adjusted, 0, sizeof(LTE_TRANSPORT_CHANNEL_CONFIG_MODULATION_ADJUSTMENTS));

    // Initialize mutex for thread-safe access to LTE transport channels configuration array
    pthread_mutex_t configs_mutex = PTHREAD_MUTEX_INITIALIZER;

    // Iterate over each LTE transport channel configuration
    for (size_t i = 0; i < configs->configs_count; i++) {
        // Acquire mutex to access LTE transport channels configuration array safely
        pthread_mutex_lock(&configs_mutex);

        // Initialize memory allocation failures structures for the current configuration
        alloc_failed.alloc_failed_channels = NULL;
        alloc_failed.alloc_failed_count = 0;
        config_alloc_failed.alloc_failed_configs = NULL;
