        if (channels == NULL) {
            alloc_failed.alloc_failed_count++;
            // Release mutex to release thread-safe access to LTE transport channels configuration array safely
            pthread_mutex_unlock(&configs_mutex);
            continue;
        } else {
            memset(channels, 0, channel_count * sizeof(LTE_TRANSPORT_CHANNEL));
        }

        // Iterate over each LTE transport channel in the current configuration
        for (size_t j = 0; j < channel_count; j++) {
            // Initialize memory allocation failures structures for the current channel
            alloc_failed.alloc_failed_channels = NULL;
            alloc_failed.alloc_failed_count = 0;
            config_alloc_failed.alloc_failed_configs = NULL;
            config_alloc_failed.alloc_failed_count = 0;

            // Initialize real-time modulation adjustments structures for the current channel
            modulation_adjusted.modulation_adjusted_channels = NULL;
            modulation_adjusted.modulation_adjusted_count = 0;
            config_modulation_adjusted.modulation_adjusted_configs = NULL;
            config_modulation_adjusted.modulation_adjusted_count = 0;

            // Initialize LTE transport channel parameters for the current channel
            channels[j].channel_id = i * channel_count + j;
            channels[j].tx_power = 16; // Default power level of 16 dBm
            channels[j].modulation = "QPSK"; // Default modulation is QPSK

            // Check if real-time modulation adjustments are required for the current channel
            if (configs->configs[i].adjust_tx_power) {
