                channels[j].tx_power = configs->configs[i].tx_power;
            }

            if (configs->configs[i].adjust_modulation) {
                // Update modulation scheme of the current channel based on real-time modulation adjustments
                channels[j].modulation = configs->configs[i].modulation;
            }
        }

        // Check if any memory allocation failures occurred during initialization and configuration of LTE transport channels
        if (alloc_failed.alloc_failed_count > 0) {
