### 3.3.4.4 List Implementation with Linked Lists (Singly)

The linked list implementation of a list uses pointers to link nodes together. Each node in the list contains a data field and a pointer to the next node in the list. The last node points to NULL, indicating the end of the list. This implementation has a time complexity of O(n) for insertion, deletion, and traversal.
```cpp
#include <stdlib.h>
#include <stdio.h>

// Structure to represent each node in the linked list
struct Node {
    int data;
    struct Node* next;
};

// Function to create a new node with given data
struct Node* newNode(int data) {
    struct Node* node = (struct Node*)malloc(sizeof(struct Node));
    node->data = data;
    node->next = NULL;
    return node;
}

// Function to insert a new node at the beginning of the list
void push(struct Node** head_ref, int new_data) {
    // Allocate memory for new node
    struct Node* new_node = newNode(new_data);

    // Make next of new node as head and move the head to point to it
    new_node->next = (*head_ref);
    (*head_ref) = new_node;
}

// Function to delete a node from the beginning of the list
void pop(struct Node** head_ref) {
    // If linked list is empty, return NULL.
    if (*head_ref == NULL)
        return;

    // Store previous heaad
    struct Node* temp = *head_ref;

    // Move the head to point to the next node
    *head_ref = (temp->next);

    // Free the memory of dequeued node
    free(temp);
}

// Function to get the front element of the list
int peek(struct Node* head) {
    return (head->data);
}

// Function to insert an element at a given position
void insert(struct Node** head_ref, int data, int idx) {
    // If linked list is empty, then create a new node with data and make it as head.
    if (*head_ref == NULL) {
        push(head_ref, data);
        return;
    }

    // Initialize current pointer with head
    struct Node* cur = *head_ref;

    // If index is greater than 0 then traverse till the index-1 postion in the linked list.
    int i;
    for (i = 0; i < idx - 1; ++i) {
        // If we reach at the end of the linked list, then return NULL
        if (cur->next == NULL)
            return;

        cur = cur->next;
    }

    // Create a new node with given data and link it with current node.
    struct Node* new_node = newNode(data);
    new_node->next = cur->next;
    cur->next = new_node;
}

// Function to delete an element from the linked list at a given position
void remove(struct Node** head_ref, int idx) {
    // If linked list is empty or index is out of bounds
    if (*head_ref == NULL || idx < 0)
        return;

    // Initialize current pointer with head
    struct Node* cur = *head_ref;

    // If index is greater than 0 then traverse till the index-1 postion in the linked list.
    int i;
    for (i = 0; i < idx - 1; ++i) {
        // If we reach at the end of the linked list, then return NULL
        if (cur->next == NULL)
            return;

        cur = cur->next;
    }

    // Delete the required node and remove in the linked list.
    struct Node* delNode = cur->next;
    cur->next = delNode->next;

    free(delNode);
}

// Function to print the elements of linked list
void printList(struct Node* head) {
    // If linked list is empty, then return NULL.
    if (head == NULL)
        printf("Linked List is Empty");

    // Iterate through the Linked list and print its data members.
    while (head != NULL) {
        printf("%d ", head->data);
        head = head->next;
    }
}
```
### 3.3.4.5 List Implementation with Doulbly Links

The linked list implementation of a list uses pointers to link nodes together. Each node in the list contains two references: one pointing to the next node in the list, and another pointing to the previous node in the list. This implementation has a time complexity of O(1) for insertion, deletion, and traversal.
```cpp
#include <stdlib.h>
#include <stdio.h>

// Structure to represent each node in the linked list
struct Node {
    int data;
    struct Node* next;
    struct Node* prev;
};

// Function to create a new node with given data
struct Node* newNode(int data) {
    struct Node* node = (struct Node*)malloc(sizeof(struct Node));
    node->data = data;
    node->next = NULL;
    node->prev = NULL;
    return node;
}

// Function to insert a new node at the beginning of the list
void push(struct Node** head_ref, int new_data) {
    // Allocate memory for new node
    struct Node* new_node = newNode(new_data);

    // Make next and prev pointers of new node as NULL
    new_node->prev = NULL;
    new_node->next = (*head_ref);

    // If linked list is not empty, then change the next and prev pointers of previous head.
    if ((*head_ref) != NULL) {
        (*head_ref)->prev = new_node;
    }

    // Move the head to point to the new node.
    (*head_ref) = new_node;
}

// Function to remove a node from the beginning of the list
void pop(struct Node** head_ref) {
    // If linked list is empty, return NULL.
    if (*head_ref == NULL)
        return;

    // Store the next pointer of head (for deletion later)
    struct Node* temp = *head_ref;

    // Change the head pointer to point to the next node
    *head_ref = (*head_ref)->next;

    // If the stored next pointer is not NULL, then change its prev pointer.
    if (*head_ref != NULL) {
        (*head_ref)->prev = NULL;
    }

    // Free the memory of deleted node.
    free(temp);
}

// Function to get the front element of the list
int peek(struct Node* head) {
    return (head->data);
}

// Function to insert an element at a given position
void insert(struct Node** head_ref, int data, int idx) {
    // If linked list is empty or index is out of bounds
    if (*head_ref == NULL || idx < 0)
        return;

    // Create new node with the given data.
    struct Node* new_node = newNode(data);

    // Get the position where we need to insert our data. If index is 0 then insert at the beginning of linked list.
    if (idx == 0) {
        new_node->next = (*head_ref);
        new_node->prev = NULL;
        (*head_ref)->prev = new_node;
        (*head_ref) = new_node;
    } else {
        struct Node* temp = *head_ref;
        int i;
        for (i = 0; i < idx - 1; ++i) {
            if (temp->next == NULL) {
                break;
            }
            temp = temp->next;
        }
        new_node->prev = temp;
        new_node->next = temp->next;
        temp->next = new_node;
        if (new_node->next != NULL) {
            new_node->next->prev = new_node;
        }
    }
}

// Function to delete an element from the linked list at a given position
void remove(struct Node** head_ref, int idx) {
    // If linked list is empty or index is out of bounds
    if (*head_ref == NULL || idx < 0)
        return;

    // Get the position where we need to insert our data. If index is 0 then insert at the beginning of linked list.
    struct Node* temp = *head_ref;
    int i;
    for (i = 0; i < idx - 1; ++i) {
        if (temp->next == NULL) {
            break;
        }
        temp = temp->next;
    }
    struct Node* delNode = temp->next;
    temp->next = delNode->next;
    if (delNode->next != NULL) {
        delNode->next->prev = temp;
    }
    free(delNode);
}

// Function to print the elements of linked list
void printList(struct Node* head) {
    // If linked list is empty, then return NULL.
    if (head == NULL)
        printf("Linked List is Empty");

    // Iterate through the Linked list and print its data members.
    while (head != NULL) {
        printf("%d ", head->data);
        head = head->next;
    }
}
```
### 3.3.5 Hash Table Implementation

A hash table is a data structure that uses a hash function to map keys to values in such a way that it can perform lookups, insertions, and deletions efficiently. It works by creating an array of buckets and assigning each key a unique index for the bucket where its value is stored. Each slot in the bucket is called a "cell" and contains a key-value pair. When we add a new element to the hash table, we first compute its hash code using our hash function and use that to determine which cell in the array will contain its value.

```java
public class MyHashMap {
    // Number of buckets in the hash map.
    private int numBuckets;

    // An array of cells, each containing a key-value pair.
    private Cell[] cells;

    public MyHashMap() {
        this(16);
    }

    public MyHashMap(int numBuckets) {
        this.numBuckets = numBuckets;
        cells = new Cell[numBuckets];
    }

    // Adds a key-value pair to the hash table.
    public void put(String key, Object value) {
        int index = getIndex(key);
        Cell cell = cells[index];

        // If there's already a value for this key, update it.
        if (cell != null && cell.getKey().equals(key)) {
            cell.setValue(value);
        } else {
            // Create a new cell and add it to the array.
            cells[index] = new Cell(key, value);
        }
    }

    // Gets the value for a given key. Returns null if no such value exists.
    public Object get(String key) {
        int index = getIndex(key);
        return cells[index] != null ? cells[index].getValue() : null;
    }

    // Removes a key-value pair from the hash table. Returns true if successful, false otherwise.
    public boolean remove(String key) {
        int index = getIndex(key);
        Cell cell = cells[index];

        if (cell != null && cell.getKey().equals(key)) {
            // Set the value of the cell to null.
            cell.setValue(null);
            return true;
        }

        return false;
    }

    // Gets the number of key-value pairs in the hash table.
    public int size() {
        int count = 0;

        for (int i = 0; i < cells.length; i++) {
            if (cells[i] != null) {
                count++;
            }
        }

        return count;
    }

    // Gets the index for a given key in the hash table.
    private int getIndex(String key) {
        return Math.abs(key.hashCode()) % numBuckets;
    }
}
```
### 3.3.6 Queue Implementation

A queue is a data structure that follows the principle of **first-in, first-out (FIFO)**. It means that when we insert an element into the queue, it gets added to the end of the queue and when we retrieve an element from the queue, the one at the beginning of the queue gets removed first.

```java
public class Queue {
    // Array to store the elements of the queue.
    private Object[] queue;

    // Index of the front of the queue (the first element).
    private int front = 0;

    // Index of the rear of the queue (the last element).
    private int rear = -1;

    public Queue() {
        this(5);
    }

    public Queue(int capacity) {
        // Allocate memory for the array.
        queue = new Object[capacity];
    }

    // Adds an element to the rear of the queue.
    public void enqueue(Object value) {
        if (isFull()) {
            // Grow the array if the queue is full.
            grow();
        }

        // Increment the index of the rear of the queue.
        rear++;

        // Store the element in the array.
        queue[rear] = value;
    }

    // Removes an element from the front of the queue and returns it.
    public Object dequeue() {
        if (isEmpty()) {
            return null;
        }

        // Store the element at the front of the queue.
        Object value = queue[front];

        // Increment the index of the front of the queue.
        front++;

        // If the front of the queue is equal to the rear of the queue, make them both -1.
        if (front > rear) {
            front = -1;
            rear = -1;
        }

        return value;
    }

    // Returns the size of the queue.
    public int size() {
        return rear - front + 1;
    }

    // Returns whether the queue is empty or not.
    public boolean isEmpty() {
        return front == -1;
    }

    // Grows the array if the queue is full.
    private void grow() {
        // Create a new array that is twice the size of the current array.
        Object[] newQueue = new Object[queue.length * 2];

        // Copy the elements from the old array to the new array.
        for (int i = front; i <= rear; i++) {
            newQueue[i - front] = queue[i];
        }

        // Set the queue to the new array.
        queue = newQueue;

        // Update the indices of the front and rear of the queue.
        front = 0;
        rear = rear - front + 1;
    }
}
```
### 3.3.7 Stack Implementation

A stack is a data structure that follows the principle of **last-in, first-out (LIFO)**. It means that when we insert an element into the stack, it gets added to the top of the stack and when we retrieve an element from the stack, the one at the top of the stack gets removed first.

```java
public class Stack {
    // Array to store the elements of the stack.
    private Object[] stack;

    // Index of the top of the stack (the last element).
    private int top = -1;

    public Stack() {
        this(5);
    }

    public Stack(int capacity) {
        // Allocate memory for the array.
        stack = new Object[capacity];
    }

    // Adds an element to the top of the stack.
    public void push(Object value) {
        if (isFull()) {
            // Grow the array if the stack is full.
            grow();
        }

        // Increment the index of the top of the stack.
        top++;

        // Store the element in the array.
        stack[top] = value;
    }

    // Removes an element from the top of the stack and returns it.
    public Object pop() {
        if (isEmpty()) {
            return null;
        }

        // Store the element at the top of the stack.
        Object value = stack[top];

        // Decrement the index of the top of the stack.
        top--;

        // If the top of the stack is equal to -1, make it -1.
        if (top < 0) {
            top = -1;
        }

        return value;
    }

    // Returns the size of the stack.
    public int size() {
        return top + 1;
    }

    // Returns whether the stack is empty or not.
    public boolean isEmpty() {
        return top == -1;
    }

    // Grows the array if the stack is full.
    private void grow() {
        // Create a new array that is twice the size of the current array.
        Object[] newStack = new Object[stack.length * 2];

        // Copy the elements from the old array to the new array.
        for (int i = top; i >= 0; i--) {
            newStack[i] = stack[i];
        }

        // Set the stack to the new array.
        stack = newStack;

        // Update the index of the top of the stack.
        top = top + newStack.length - 1;
    }
}
```']

