int node_pool_idx = 0;

// Define a linked list head to store the root node of the list
node_t *list_head = NULL;

// Define a lock for concurrent access and modification by multiple threads
pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

// Define a counter for tracking the total number of nodes added to the list
