// Function to initialize the linked list and allocate memory from the pool
void init_list(int num_nodes) {
    pthread_mutex_lock(&list_lock);
    // Allocate memory for the nodes from the pool
    for (int i = 0; i < num_nodes; ++i) {
        node_t *node = node_pool[node_pool_idx++];
        if (node == NULL) {
            printf("Memory pool exhausted\n");
            break;
        }
        // Initialize the data and next pointer of each node
        node->data.rx_ue_information_tag = 0;
        node->data.rnti = 0;
        node->data.crc_indication_rel8_tag = 0;
        node->next = NULL;
        // Add the node to the linked list
        if (list_head == NULL) {
            list_head = node;
        } else {
            node_t *last_node = list_head;
            while (last_node->next != NULL) {
                last_node = last_node->next;
            }
            last_node->next = node;
        }
    }
    pthread_mutex_unlock(&list_lock);
}

// Function to add a new node with a unique integer key and insert values with offsets into the linked lists of these nodes
void add_node(int key, int offset) {
    pthread_mutex_lock(&list_lock);
    // Allocate memory for the new node from the pool
    node_t *node = node_pool[node_pool_idx++];
    if (node == NULL) {
        printf("Memory pool exhausted\n");
        pthread_mutex_unlock(&list_lock);
        return;
    }
    // Initialize the data and next pointer of the new node
    node->data.rx_ue_information_tag = key;
    node->data.rnti = key + offset;
    node->data.crc_indication_rel8_tag = key * offset;
    node->next = NULL;
    // Add the new node to the linked list
    if (list_head == NULL) {
        list_head = node;
    } else {
        node_t *last_node = list_head;
        while (last_node->next != NULL) {
            last_node = last_node->next;
        }
        last_node->next = node;
    }
    pthread_mutex_unlock(&list_lock);
}

// Function to traverse the linked list and print the details of all nodes and their associated values
void traverse_list() {
