// Function to create a new LTE UE Context
int CreateLTEUEContext(int UEID, unsigned long long S_TMSI, void* MMEContext) {
    // Lock the list of LTE UE Contexts to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Check if the context already exists in the list
    for (int i = 0; i < MAX_CONTEXT_COUNT; i++) {
        if (LTEUEContextList[i].UEID == UEID) {
            pthread_mutex_unlock(&mutex);
            return -1; // Context already exists, cannot create new context
        }
    }

    // Find the first empty slot in the list and initialize it with the new context
    for (int i = 0; i < MAX_CONTEXT_COUNT; i++) {
        if (LTEUEContextList[i].UEID == -1) {
            LTEUEContextList[i].UEID = UEID;
            LTEUEContextList[i].S_TMSI = S_TMSI;
            LTEUEContextList[i].MMEContext = MMEContext;
            break;
        }
    }

    // Unlock the list of LTE UE Contexts
    pthread_mutex_unlock(&mutex);

    return 0; // Successfully created new context
}

