```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_LIST_SIZE 10000
#define MIN_FREQUENCY_THRESHOLD 5
#define DEFAULT_CRCFLAG false

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    uint32_t rnti;
    bool crcflag;
} nfapi_crc_indication_pdu_t;

struct nfapi_crc_indication_list {
    nfapi_crc_indication_pdu_t* pdu;
    size_t count;
    bool full;
};

struct nfapi_crc_indication_list* nfapi_create_crc_indication_list() {
    struct nfapi_crc_indication_list* list = malloc(sizeof(struct nfapi_crc_indication_list));
    if (!list) {
        fprintf(stderr, "Failed to allocate memory for CRC indication list\n");
        return NULL;
    }

    list->pdu = calloc(MAX_LIST_SIZE, sizeof(nfapi_crc_indication_pdu_t));
    if (!list->pdu) {
        fprintf(stderr, "Failed to allocate memory for CRC indication PDUs\n");
        free(list);
        return NULL;
    }

    list->count = 0;
    list->full = false;

    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void nfapi_free_crc_indication_list(struct nfapi_crc_indication_list* list) {
    if (list) {
        pthread_mutex_destroy(&list->lock);
        free(list->pdu);
        free(list);
    }
}

bool nfapi_add_crc_indication_pdu(struct nfapi_crc_indication_list* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!list || !pdu) {
        return false;
    }

    pthread_mutex_lock(&list->lock);
    if (list->full) {
        fprintf(stderr, "CRC indication list is full\n");
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    if (list->count >= MAX_LIST_SIZE) {
        fprintf(stderr, "CRC indication list size exceeded limit of %d entries\n", MAX_LIST_SIZE);
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    uint32_t rnti = nfapi_get_rnti(pdu);
    bool exists = false;
    for (size_t i = 0; i < list->count; ++i) {
        if (list->pdu[i].rnti == rnti) {
            exists = true;
            break;
        }
    }

    if (!exists) {
        memcpy(&list->pdu[list->count++], pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        list->full = (list->count == MAX_LIST_SIZE);
        pthread_mutex_unlock(&list->lock);
        return true;
    } else {
        fprintf(stderr, "CRC indication for RNTI %u already exists\n", rnti);
        pthread_mutex_unlock(&list->lock);
        return false;
    }
}

void nfapi_remove_crc_indication_pdu(struct nfapi_crc_indication_list* list, uint32_t rnti) {
    if (!list) {
        return;
    }

    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        if (list->pdu[i].rnti == rnti) {
            memmove(&list->pdu[i], &list->pdu[i + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (list->count - i));
            --list->count;
            break;
        }
    }

    list->full = false;
    pthread_mutex_unlock(&list->lock);
}

void nfapi_update_crcflag(struct nfapi_crc_indication_list* list, uint32_t rnti) {
    if (!list) {
        return;
    }

    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        if (list->pdu[i].rnti == rnti) {
            list->pdu[i].crcflag = DEFAULT_CRCFLAG;
            break;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void nfapi_export_crc_indication_list(struct nfapi_crc_indication_list* list, FILE* fp) {
    if (!list || !fp) {
        return;
    }

    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &list->pdu[i];
        fprintf(fp, "%u %u %u\n", nfapi_get_rnti(pdu), nfapi_get_tpc(pdu), nfapi_get_crc_indication_status(pdu));
    }

    pthread_mutex_unlock(&list->lock);
}

void nfapi_import_crc_indication_list(struct nfapi_crc_indication_list* list, FILE* fp) {
    if (!list || !fp) {
        return;
    }

    pthread_mutex_lock(&list->lock);
    while (true) {
        int rnti = 0, tpc = 0, status = 0;
        int n = fscanf(fp, "%u %u %u", &rnti, &tpc, &status);
        if (n == EOF) {
            break;
        } else if (n != 3) {
            continue;
        }

        NFAPI_CRC_INDICATION_PDU_T* pdu = nfapi_create_crc_indication_pdu(rnti, tpc);
        if (!pdu) {
            continue;
        }

        nfapi_set_crc_indication_status(pdu, status);
        if (!nfapi_add_crc_indication_pdu(list, pdu)) {
            fprintf(stderr, "Error adding CRC indication PDU to list\n");
            nfapi_destroy_crc_indication_pdu(pdu);
        }
    }

    pthread_mutex_unlock(&list->lock);
}

int main() {
    struct nfapi_crc_indication_list* list = nfapi_create_crc_indication_list();
    if (!list) {
        return 1;
    }

    FILE* fp = fopen("data.txt", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file\n");
        nfapi_free_crc_indication_list(list);
        return 1;
    }

    nfapi_import_crc_indication_list(list, fp);
    fclose(fp);

    nfapi_update_crcflag(list, 12345);

    fp = fopen("output.txt", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file\n");
        nfapi_free_crc_indication_list(list);
        return 1;
    }

    nfapi_export_crc_indication_list(list, fp);
    fclose(fp);

    nfapi_free_crc_indication_list(list);
    return 0;
}
```

Note that this example uses a `FILE*` to read and write the data, but you can also use any other method of reading and writing the data. Additionally, note that in order to import the list, you need to have the PDUs already created using the `nfapi_create_crc_indication_pdu()` function.

Also note that this example uses a mutex to protect the list from concurrent access, but if you are not using multithreading or do not want to use a mutex, you can remove it and the locking code around the `nfapi_add_crc_indication_pdu()`, `nfapi_remove_crc_indication_pdu()`, `nfapi_update_crcflag()` and `nfapi_export_crc_indication_list()` functions.

### Using NFAPI in your application

Once you have built the library, you can use it in your own applications by including the header file and linking to the library. For example:

```c
#include <nfapi/oai_integration.h>

int main() {
  // Your code here
}
```

You can also use the `nfapi/open-air-interface` submodule, which contains the OpenAirInterface (OAI) integration. This includes a set of APIs for working with OAI structures and functions for sending and receiving messages. For example:

```c
#include <nfapi/oai_integration/interface.h>

int main() {
  // Your code here
}
```

Note that this submodule is not included in the standard NFAPI build, so you will need to include it explicitly when building your application.

### Using the CMake build system

The NFAPI source code includes a `CMakeLists.txt` file for generating build files using the [CMake](https://cmake.org/) build system. This allows you to generate build files for different platforms and compilers, and to build NFAPI with support for additional features such as OpenAirInterface (OAI) integration.

To use the CMake build system, first install CMake on your platform. Then, run `cmake` from the top-level directory of the NFAPI source code to generate build files for your platform and compiler:
```bash
mkdir build && cd build
cmake ..
```
This will create a `build` directory containing build files for your platform and compiler. You can then build NFAPI by running `make`:
```bash
make
```
Once the build is complete, you can test it using the provided test scripts or use it in your own applications.
