// Function to manage and populate a list of NFAPI_CRC_INDICATION_PDUs
void manageNFAPICrcIndications(int *ints, int size) {
  // Initialize linked list for NFAPI_CRC_INDICATION_PDUs
  NFAPI_CRC_INDICATION_LIST_T *list = (NFAPI_CRC_INDICATION_LIST_T *)malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
  list->head = NULL;
  list->tail = NULL;

