  NFAPI_CRC_INDICATION_PDU_T *nfaci = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * initCapacity);
  list->head = nfaci;

