struct SessionState {
    int session_id;
    std::string ue_identifier;
    std::vector<std::string> associated_events;
};

void initialize_and_populate_array(std::vector<SessionState>& sessions) {
    // Initialize array with predefined number of elements
    for (int i = 0; i < 10; ++i) {
        SessionState session;
        session.session_id = i + 1;
        session.ue_identifier = "UE_" + std::to_string(i);
        sessions.push_back(session);
    }

    // Populate array with random data
    for (int i = 0; i < 10; ++i) {
        SessionState session = sessions[i];
        session.associated_events.push_back("Event_" + std::to_string(rand() % 10));
        sessions[i] = session;
    }
}

void serialize_sessions(const std::vector<SessionState>& sessions, const std::string& filename) {
    std::ofstream file;
    file.open(filename);
    for (const SessionState& session : sessions) {
        file << session.session_id << "," << session.ue_identifier << "," << session.associated_events.size() << "\n";
        for (const std::string& event : session.associated_events) {
            file << event << "\n";
        }
    }
}

int main() {
    // Initialize and populate array of SessionState structures
    std::vector<SessionState> sessions;
    initialize_and_populate_array(sessions);

    // Serialize sessions to file
    serialize_sessions(sessions, "sessions.bin");
}
