// Define structure for storing records
typedef struct {
    int value;
} record_t;

// Function to dynamically allocate memory for offsets array
long *allocate_offsets(int max_size) {
    // Initialize offsets array with multiples of 5
    long *offsets = malloc(max_size * sizeof(long));
    if (offsets == NULL) {
        printf("Memory allocation failed!\n");
        exit(EXIT_FAILURE);
    }

    // Initialize offsets array with multiples of 5, ensuring no two adjacent values differ by less than 100
    int i = 0;
    while (i < max_size) {
        if (offsets[i] == 0) {
            offsets[i] = 5 * (i + 1);
        } else {
            offsets[i] += 5;
        }
        i++;
    }

    return offsets;
}

// Function to dynamically allocate memory for keys array
int *allocate_keys(int max_size) {
    // Initialize keys array with unique integers between 4 and 8 characters long
    int *keys = malloc(max_size * sizeof(int));
    if (keys == NULL) {
        printf("Memory allocation failed!\n");
        exit(EXIT_FAILURE);
    }

    // Generate unique integers between 4 and 8 characters long, using a weighted distribution based on the frequency of each key found in a provided text file
    FILE *file = fopen("input.txt", "r");
    if (file == NULL) {
        printf("Error opening input file!\n");
        exit(EXIT_FAILURE);
    }

    int i = 0;
    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        // Validate each key to ensure it contains only alphanumeric characters and falls within a specific length range
        for (int j = 0; j < strlen(line); j++) {
            if (!isalnum(line[j])) {
                printf("Error: Key contains non-alphanumeric character!\n");
                exit(EXIT_FAILURE);
            }
        }
        if (strlen(line) < 4 || strlen(line) > 8) {
            printf("Error: Key length is not within the specified range of 4 to 8 characters!\n");
            exit(EXIT_FAILURE);
        }
        keys[i] = atoi(line);
        i++;
    }
    fclose(file);

    // Handle potential errors gracefully, such as retrying failed operations and logging errors
    if (i < max_size) {
        printf("Error: Insufficient input data!\n");
        exit(EXIT_FAILURE);
    } else if (i > max_size) {
        int new_max_size = i / 100;
        int *new_keys = realloc(keys, new_max_size * sizeof(int));
        if (new_keys == NULL) {
            printf("Error: Reallocation failed!\n");
            exit(EXIT_FAILURE);
        }
        keys = new_keys;
    }

    return keys;
}

// Function to populate records array with weighted distribution based on frequency of each key found in a provided text file
