#define ARRAY_INITIAL_SIZE 1024 // Initial size of the array
#define ARRAY_GROWTH_FACTOR 2 // Factor by which to grow the array
#define FILENAME "array_state.dat" // Name of the file where state is saved
#define MAX_FILENAME_LEN 64 // Maximum length of the filename
#define MIN_ARRAY_SIZE 1024 // Minimum size of the array after resizing

typedef struct {
    long offset;
    int key;
    float data;
} element_t;

// Function to grow or shrink the array based on user-defined growth criteria
void resize_array(element_t **arr, size_t *size) {
    // Calculate the new size of the array based on the growth factor and current size
    size_t new_size = (*size) * ARRAY_GROWTH_FACTOR;
    if (new_size < MIN_ARRAY_SIZE) {
        new_size = MIN_ARRAY_SIZE;
    }

    // Create a new array with the new size
    element_t *new_arr = (element_t *)malloc(sizeof(element_t) * new_size);
    if (!new_arr) {
        perror("Failed to allocate memory for the new array");
        exit(EXIT_FAILURE);
    }

    // Copy elements from the old array to the new one
    memcpy(new_arr, *arr, sizeof(element_t) * (*size));

    // Free the old array and replace it with the new one
    free(*arr);
    *arr = new_arr;
    *size = new_size;
}

// Function to save the state of the array to a file
void save_array(element_t **arr, size_t size) {
    // Create a filename for the state file
    char filename[MAX_FILENAME_LEN];
    sprintf(filename, "%s_%ld", FILENAME, (long int)*arr);

    // Open the file in append mode and write the array to it
    int fd = open(filename, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd == -1) {
        perror("Failed to open state file for writing");
        exit(EXIT_FAILURE);
    }

    // Write the array to the file
    size_t written = write(fd, *arr, sizeof(element_t) * size);
    if (written != sizeof(element_t) * size) {
        perror("Failed to write state to file");
        exit(EXIT_FAILURE);
    }

    // Close the file
    close(fd);
}

// Function to load the array from a file into memory
void load_array(element_t **arr, size_t *size) {
    // Create a filename for the state file
    char filename[MAX_FILENAME_LEN];
    sprintf(filename, "%s_%ld", FILENAME, (long int)*arr);

    // Open the file in read-only mode and read the array from it
    int fd = open(filename, O_RDONLY, 0644);
    if (fd == -1) {
        perror("Failed to open state file for reading");
        exit(EXIT_FAILURE);
    }

    // Read the array from the file
    size_t read = read(fd, *arr, sizeof(element_t) * (*size));
    if (read != sizeof(element_t) * (*size)) {
        perror("Failed to read state from file");
        exit(EXIT_FAILURE);
    }

    // Close the file
    close(fd);
}

// Function to periodically free unused memory within the array
void garbage_collect(element_t **arr, size_t *size) {
    // Calculate the number of elements that can be freed
    size_t num_freed = 0;
    for (int i = 0; i < (*size); i++) {
        if (!(*arr)[i].data) {
            num_freed++;
        }
    }

    // Free the unused elements and update the size of the array
    if (num_freed > 0) {
        size_t new_size = (*size) - num_freed;
        element_t *new_arr = (element_t *)realloc(*arr, sizeof(element_t) * new_size);
        if (!new_arr) {
            perror("Failed to reallocate memory for the array");
            exit(EXIT_FAILURE);
        }
        *arr = new_arr;
        *size = new_size;
    }
}

// Main function that manages dynamic memory allocation for an array of structures
void manage_array(element_t **arr, size_t *size) {
    // Initialize the array with the initial size
    if (*arr == NULL) {
        *arr = (element_t *)malloc(sizeof(element_t) * ARRAY_INITIAL_SIZE);
        if (!(*arr)) {
            perror("Failed to allocate memory for the array");
            exit(EXIT_FAILURE);
        }
    }

    // Perform garbage collection periodically
    garbage_collect(arr, size);

    // Check if the array needs to be resized based on user-defined growth criteria
    if (*size >= ARRAY_GROWTH_FACTOR) {
        resize_array(arr, size);
    }

    // Save the state of the array to a file at regular intervals
    save_array(arr, *size);

    // Load the array from a file into memory if needed
    load_array(arr, size);
}

int main() {
    element_t *arr = NULL;
    size_t size = 0;

    manage_array(&arr, &size);

    return 0;
}
