    log_entries = (CellularEventLogEntry*)malloc(sizeof(CellularEventLogEntry) * log_capacity);
}

// Function to add a new entry to the log
void add_entry(char* event_type, char* status_message) {
    // Check if the dynamic array needs to be resized
    if (log_count == log_capacity) {
        log_capacity *= 2;
        CellularEventLogEntry* new_entries = (CellularEventLogEntry*)realloc(log_entries, sizeof(CellularEventLogEntry) * log_capacity);
        if (new_entries == NULL) {
            // Handle memory allocation failure gracefully
            return;
        }
        log_entries = new_entries;
    }

    // Add the new entry to the log
    log_entries[log_count].timestamp = time(NULL);
    strncpy(log_entries[log_count].event_type, event_type, 32);
    strncpy(log_entries[log_count].status_message, status_message, 256);
    log_count++;
}

