        log_entries[i].load5 = load5;
        log_entries[i].load15 = load15;
        log_entries[i].total_memory = total_memory;
        log_entries[i].free_memory = free_memory;
        log_entries[i].used_memory = used_memory;
        log_entries[i].cpu_usage = cpu_usage;
    }
}

// Function to flush the log entries to disk or a remote server at appropriate intervals
