    }

    // Initialize the structures with valid data
    for (size_t i = 0; i < numElements; i++) {
        list[i].rxUeInformationTag = RX_UE_INFORMATION_TAG_INIT;
        list[i].rnti = 0;
        list[i].crcIndicationRel8Tag = CRC_INDICATION_REL8_TAG_INIT;
    }

    return list;
}

// Function to resolve a given hostname to an IP address using DNS resolution
int resolveHostname(const char* hostname, char** ipAddress) {
    // Initialize the DNS resolver library
    res_init();

    // Get the DNS server information from /etc/resolv.conf
    const struct __res_state *state = _res;

    // Resolve the given hostname to an IP address asynchronously
    int status = res_query(state, hostname, C_IN, T_A, (dns_sdl_func_t)NULL, NULL, ipAddress, NULL);
    if (status != 0) {
        *ipAddress = NULL;
        return status;
    }

    // Return the resolved IP address
    return 0;
}

// Function to allocate memory for a list of NFAPI_CRC_INDICATION_PDU_T structures and resolve hostnames to IP addresses
NFAPI_CRC_INDICATION_PDU_T* allocAndResolveMemory(size_t numElements, const char** hostnames) {
    // Allocate memory for the list of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* list = allocateMemory(numElements);
    if (list == NULL) {
        return NULL;
    }

    // Resolve hostnames to IP addresses asynchronously
    for (size_t i = 0; i < numElements; i++) {
        char* ipAddress = NULL;
        int status = resolveHostname(hostnames[i], &ipAddress);
        if (status != 0) {
            free(list);
            return NULL;
        }
        list[i].rnti = atoi(ipAddress);
    }

    return list;
}

// Main function to demonstrate the use of the above functions
int main() {
    // Initialize the DNS resolver library
    res_init();

    // Define a list of hostnames to resolve
    const char* hostnames[] = {"google.com", "facebook.com", "microsoft.com"};

    // Allocate memory for the list of NFAPI_CRC_INDICATION_PDU_T structures and resolve hostnames to IP addresses
    NFAPI_CRC_INDICATION_PDU_T* list = allocAndResolveMemory(3, hostnames);
    if (list == NULL) {
        printf("Failed to allocate memory for the list of NFAPI_CRC_INDICATION_PDU_T structures and resolve hostnames to IP addresses\n");
        return 1;
    }

    // Print the resolved IP addresses
    for (size_t i = 0; i < 3; i++) {
        printf("Resolved IP address for %s: %u.%u.%u.%u\n", hostnames[i], list[i].rnti >> 24, (list[i].rnti >> 16) & 0xFF, (list[i].rnti >> 8) & 0xFF, list[i].rnti & 0xFF);
    }

    // Clean up memory allocation
    free(list);

    return 0;
}
