// Define the random number generator seed
unsigned int seed = time(NULL);

// Define the memory allocation function for the dataset
void* alloc_dataset(int num_records) {
    // Allocate memory for the dataset and initialize it to NULL pointers
    Record **dataset = malloc(num_records * sizeof(Record));
    if (!dataset) {
        fprintf(stderr, "Error: Failed to allocate memory for dataset\n");
        return NULL;
    }
    memset(dataset, 0, num_records * sizeof(Record));

    // Initialize the random number generator seed
    srand(seed);

    // Populate the dataset with unique keys and offsets
    for (int i = 0; i < num_records; i++) {
        dataset[i] = malloc(sizeof(Record));
        if (!dataset[i]) {
            fprintf(stderr, "Error: Failed to allocate memory for record %d\n", i);
            free_dataset(dataset, i);
            return NULL;
        }
        dataset[i]->key = rand() % (MAX_RECORDS - 1) + 1; // Generate a random key between 1 and MAX_RECORDS - 1
        dataset[i]->offset = rand() % DATASET_SIZE; // Generate a random offset between 0 and DATASET_SIZE - 1
    }

    return dataset;
}

// Define the function to find the largest integer in the dataset
int find_largest(Record **dataset, int num_records) {
    int largest = INT_MIN; // Initialize the largest integer to the smallest possible value
    for (int i = 0; i < num_records; i++) {
        if (dataset[i]->key > largest) {
            largest = dataset[i]->key;
        }
    }
    return largest;
}

// Define the function to free the dataset memory
void free_dataset(Record **dataset, int num_records) {
    for (int i = 0; i < num_records; i++) {
        if (dataset[i]) {
            free(dataset[i]);
        }
    }
    free(dataset);
}

// Define the function to print the largest integer in the dataset
void print_largest(Record **dataset, int num_records) {
    printf("Largest integer: %d\n", find_largest(dataset, num_records));
}

// Define the main function to handle user input and execute the functions
int main() {
    // Initialize the dataset and print the largest integer
    Record **dataset = alloc_dataset(DATASET_SIZE);
    if (dataset) {
        print_largest(dataset, DATASET_SIZE);
        free_dataset(dataset, DATASET_SIZE);
    } else {
        fprintf(stderr, "Error: Failed to allocate memory for dataset\n");
    }

    return 0;
}
