int execute_background_command(const char *command) {
    pid_t child_pid = fork();
    if (child_pid == 0) { // Child process
        execl("/bin/sh", "sh", "-c", command, (char *)NULL);
        return -1;
    } else if (child_pid > 0) { // Parent process
