typedef struct MediaStreamConfig {
    int streamId;
    MediaSourceInfo* mediaSources;
    AudioQuality audioQuality;
} MediaStreamConfig;

MediaStreamConfig* initialize_media_stream(int numMediaSources, AudioQualityOverride overrides) {
    // Validate input parameters
    if (numMediaSources < 0 || overrides.bitrateKbps < 0 || overrides.sampleRateHz < 0 || overrides.codecType < 0 || overrides.channelCount < 0) {
        printf("Invalid input parameters\n");
        return NULL;
    }

    // Create a custom memory pool for efficient memory management
    MemoryPool* mempool = create_memory_pool(MEMORY_POOL_SIZE);
    if (mempool == NULL) {
        printf("Failed to create memory pool\n");
        return NULL;
    }

    // Initialize a hash table for efficient lookups of media source IDs
    HashTable* mediaSourceIdMap = initialize_hash_table(MEDIA_SOURCE_ID_MAP_SIZE);
    if (mediaSourceIdMap == NULL) {
        printf("Failed to create media source ID map\n");
        destroy_memory_pool(mempool);
        return NULL;
    }

    // Initialize the audio quality settings based on predefined template and overrides
    AudioQuality audioQuality = get_default_audio_quality();
    if (overrides.bitrateKbps > 0) {
        audioQuality.bitrateKbps = overrides.bitrateKbps;
    }
    if (overrides.sampleRateHz > 0) {
        audioQuality.sampleRateHz = overrides.sampleRateHz;
    }
    if (overrides.codecType >= 0) {
        audioQuality.codecType = overrides.codecType;
    }
    if (overrides.channelCount > 0) {
        audioQuality.channelCount = overrides.channelCount;
    }

    // Populate the media source list with unique media sources, checking for duplicates
    int numMediaSourcesAdded = 0;
    MediaSourceInfo* mediaSources = malloc(sizeof(MediaSourceInfo) * numMediaSources);
    if (mediaSources == NULL) {
        printf("Failed to allocate memory for media sources\n");
        destroy_hash_table(mediaSourceIdMap);
        destroy_memory_pool(mempool);
        return NULL;
    }
    for (int i = 0; i < numMediaSources; i++) {
        MediaSourceInfo* source = &mediaSources[i];
        // Generate a unique media source ID based on the input parameters
        char idBuffer[128];
        sprintf(idBuffer, "%d-%d-%d", overrides.bitrateKbps, overrides.sampleRateHz, overrides.codecType);
        int idLength = strlen(idBuffer);
        // Check if the media source ID already exists in the map
        if (lookup_hash_table(mediaSourceIdMap, idBuffer) != NULL) {
            continue;
        }
        // Add the new media source to the list
        source->id = strdup(idBuffer);
        source->bitrateKbps = overrides.bitrateKbps;
        source->sampleRateHz = overrides.sampleRateHz;
        source->codecType = overrides.codecType;
        source->channelCount = overrides.channelCount;
        // Add the media source ID to the map
        insert_hash_table(mediaSourceIdMap, idBuffer);
        numMediaSourcesAdded++;
    }

    // Configure thread safety for accessing shared resources
    pthread_mutex_t* lock = malloc(sizeof(pthread_mutex_t));
    if (lock == NULL) {
        printf("Failed to allocate memory for mutex\n");
        free(mediaSources);
        destroy_hash_table(mediaSourceIdMap);
        destroy_memory_pool(mempool);
        return NULL;
    }
    pthread_mutex_init(lock, NULL);

    // Create a memory pool for efficient memory management
    MemoryPool* mempool = create_memory_pool(MEMORY_POOL_SIZE);
    if (mempool == NULL) {
        printf("Failed to create memory pool\n");
        free(lock);
        free(mediaSources);
        destroy_hash_table(mediaSourceIdMap);
        return NULL;
    }

    // Create a logging mechanism for debugging purposes
    LoggingMechanism* logger = malloc(sizeof(LoggingMechanism));
    if (logger == NULL) {
        printf("Failed to allocate memory for logging mechanism\n");
        free(lock);
        destroy_memory_pool(mempool);
        free(mediaSources);
        return NULL;
    }
    logger->logFile = fopen("/var/log/media_stream.log", "a+");
    if (logger->logFile == NULL) {
        printf("Failed to open log file\n");
        free(lock);
        free(mempool);
        free(mediaSources);
        return NULL;
    }

    // Create a configuration for the media stream
    MediaStreamConfig* config = malloc(sizeof(MediaStreamConfig));
    if (config == NULL) {
        printf("Failed to allocate memory for media stream config\n");
        free(lock);
        destroy_memory_pool(mempool);
        free(mediaSources);
        fclose(logger->logFile);
        return NULL;
    }
    config->audioQuality = audioQuality;
    config->mediaSources = mediaSources;
    config->numMediaSources = numMediaSourcesAdded;
    config->lock = lock;
    config->logger = logger;

    // Return the configuration for the media stream
    return config;
}

void destroy_media_stream(MediaStreamConfig* config) {
    if (config == NULL) {
        return;
    }
    // Destroy the logging mechanism
    fclose(config->logger->logFile);
    free(config->logger);
    // Destroy the memory pool
    destroy_memory_pool(config->mempool);
    // Destroy the hash table for media source IDs
    destroy_hash_table(config->mediaSourceIdMap);
    // Free the media sources
    free(config->mediaSources);
    // Free the lock
    free(config->lock);
    // Free the configuration
    free(config);
}

MediaStreamConfig* get_default_media_stream_config() {
