    if (config == NULL) {
        return NULL;
    }
    config->audioQuality = get_default_audio_quality();
    config->mediaSources = NULL;
    config->numMediaSources = 0;
    config->lock = malloc(sizeof(pthread_mutex_t));
    if (config->lock == NULL) {
        free(config);
        return NULL;
    }
