// Define struct for LOG_EVENT_RECORD
typedef struct LogEventRecord {
    int eventId;
    char* eventType;
    int timestamp;
} LogEventRecord;

// Custom binary search tree (BST) data structure to store and efficiently query records by timestamp
typedef struct BstNode {
    int key; // timestamp
    LogEventRecord value;
    struct BstNode* left;
    struct BstNode* right;
} BstNode;

// Calculate average event duration by extracting timestamps and computing the difference between consecutive events of the same type
void calculateAverageEventDuration(LogEventRecord* records, int numRecords) {
    // Initialize variables to keep track of average event duration and number of events
    double avgEventDuration = 0;
    int numEvents = 0;

    // Iterate through the records and calculate the difference between consecutive events of the same type
    for (int i = 1; i < numRecords; i++) {
        if (strcmp(records[i].eventType, records[i - 1].eventType) == 0) {
            int diff = records[i].timestamp - records[i - 1].timestamp;
            avgEventDuration += diff;
            numEvents++;
        }
    }

    // Print the average event duration
    printf("Average event duration: %f\n", avgEventDuration / numEvents);
}

// Populate a list of LOG_EVENT_RECORD structures, where each structure contains a unique event ID and an associated event type
void populateLogEventRecords(LogEventRecord* records, int numRecords) {
    // Initialize variables to keep track of the next available event ID and the current event type
    int nextEventId = 0;
    char* currentEventType = NULL;

    // Iterate through the records and populate the list of LOG_EVENT_RECORD structures
    for (int i = 0; i < numRecords; i++) {
        if (strcmp(records[i].eventType, currentEventType) != 0) {
            // Increment the next available event ID and update the current event type
            nextEventId++;
            currentEventType = records[i].eventType;
        }
        records[i].eventId = nextEventId;
    }
}

// Measure and print the time taken to process the input records, including calculating the average event duration and populating the structures
void measureProcessingTime(LogEventRecord* records, int numRecords) {
    // Initialize variables to keep track of the start and end times for processing the records
    struct timespec start;
    struct timespec end;

    // Start the timer before processing the records
    clock_gettime(CLOCK_MONOTONIC, &start);

    // Process the records as usual
    calculateAverageEventDuration(records, numRecords);
    populateLogEventRecords(records, numRecords);

    // End the timer and print the elapsed time in seconds
    clock_gettime(CLOCK_MONOTONIC, &end);
    double elapsedTime = (end.tv_sec - start.tv_sec) + ((double)(end.tv_nsec - start.tv_nsec)) / 1000000000;
    printf("Processing time: %f seconds\n", elapsedTime);
}

// Implement a custom binary search tree (BST) data structure to store and efficiently query the records by timestamp
void insertIntoBst(BstNode* root, LogEventRecord record) {
    // Check if the root node is NULL
    if (root == NULL) {
        // Create a new node with the given record as its value
        BstNode* newNode = malloc(sizeof(BstNode));
        newNode->key = record.timestamp;
        newNode->value = record;
        newNode->left = NULL;
        newNode->right = NULL;
        return;
    }

    // Check if the given record is less than or equal to the root node's value
    if (record.timestamp <= root->key) {
        insertIntoBst(root->left, record);
    } else {
        insertIntoBst(root->right, record);
    }
}

void deleteFromBst(BstNode* root, int timestamp) {
    // Check if the root node is NULL or the given timestamp is less than the root node's value
    if (root == NULL || timestamp < root->key) {
        return;
    }

    // Check if the given timestamp is equal to the root node's value
    if (timestamp == root->key) {
        free(root);
        return;
    }

    // Delete from the left subtree
    deleteFromBst(root->left, timestamp);

    // Delete from the right subtree
    deleteFromBst(root->right, timestamp);
}

void searchInBst(BstNode* root, int timestamp) {
    // Check if the root node is NULL or the given timestamp is less than the root node's value
    if (root == NULL || timestamp < root->key) {
        return;
    }

    // Check if the given timestamp is equal to the root node's value
    if (timestamp == root->key) {
        printf("Found record with timestamp %d\n", timestamp);
        return;
    }

    // Search in the left subtree
    searchInBst(root->left, timestamp);

    // Search in the right subtree
    searchInBst(root->right, timestamp);
}

// Handle edge cases such as missing timestamps, invalid numeric identifiers, and duplicate event types
void inputValidation(LogEventRecord* records, int numRecords) {
    // Check if any of the given records have a missing or invalid timestamp
    for (int i = 0; i < numRecords; i++) {
        if (records[i].timestamp <= 0) {
            printf("Error: Record %d has an invalid timestamp\n", i);
            return;
        }
    }

    // Check if any of the given records have a duplicate event type
    for (int i = 0; i < numRecords - 1; i++) {
        if (strcmp(records[i].eventType, records[i + 1].eventType) == 0) {
            printf("Error: Record %d has a duplicate event type\n", i);
            return;
        }
    }
}

// Sort the given array of LOG_EVENT_RECORD structures by their timestamps in descending order
void sortByTimestamp(LogEventRecord* records, int numRecords) {
    // Use a custom sorting function to compare two LOG_EVENT_RECORD structures based on their timestamps
    qsort(records, numRecords, sizeof(LogEventRecord), (int(*)(const void*, const void*))compareByTimestamp);
}

// Compare two LOG_EVENT_RECORD structures based on their timestamps in descending order
int compareByTimestamp(const LogEventRecord* record1, const LogEventRecord* record2) {
    return (record1->timestamp > record2->timestamp ? -1 : (record1->timestamp < record2->timestamp ? 1 : 0));
}
