void addEntryAtRuntime(NetworkInterfaceConfig *array, size_t numEntries) {
    // Check if the requested size is within the maximum allowed size
    if (numEntries > MAX_ARRAY_SIZE - gCurrentArraySize) {
        printf("Requested number of entries exceeds remaining space in array\n");
        return;
