    newEntry->interfaceId = gCurrentArraySize + 1;
    newEntry->numNeighbors = 0;
    newEntry->neighborInfos = NULL;
    memset(newEntry->srsParams, 0, sizeof(newEntry->srsParams));

    // Add the new entry to the array
    array[gCurrentArraySize++] = *newEntry;

    // Release the mutex to allow other threads to access the shared resources
    pthread_mutex_unlock(&gMutex);
