int fetchSessionStatusUpdates(char* requestUrl) {
    // Fetch real-time session status updates for each data subscription using the API
    int statusCode = 200;
    char* responseBody = NULL;
    CURL* curl = curl_easy_init();
    curl_easy_setopt(curl, CURLOPT_URL, requestUrl);
    curl_easy_perform(curl, &responseBody);

