// Jitter backoff for retrying the API call with backoff and jitter
void jitterBackoff(int min, int max, char* responseBody) {
    // Calculate the jittered backoff time using the formula from the paper "The Science of Backoff" by David R. Gross
    int base = (max - min) * pow(1 - (float)responseBody[0] / 255, 4);
    int random = (int)(base * rand() / (RAND_MAX + 1.0));
    int backoffTime = min + (random % (max - min));
