        // Configure the client with the SSL/TLS settings and custom headers
        let mut client = self.configure_client()?;
        let mut request = Request::new(Method::GET, Uri::from_static(url));
        request.headers_mut().insert(HeaderName::from_static("x-requested-with"), "Rust");
        request.headers_mut().insert(HeaderName::from_static("content-type"), "application/json; charset=utf-8");

        // Send the request and retrieve the response body as a byte vector
        let response = client.lock().await.request(request).await?;
        let mut body = response.into_body();
        let mut buffer = Vec::new();
        while let Some(chunk) = body.next().await {
            let chunk = chunk?;
            buffer.extend(&*chunk);
        }

        // Return the response body as a byte vector
        Ok(buffer)
    }
}
