// Define a struct to represent a record
typedef struct {
    long offset;
    int key;
    double timestamp;
} Record;

// Define a linked list node to store records
typedef struct ListNode {
    Record *record;
    struct ListNode *next;
} ListNode;

// Define a data structure to store the records and their offsets
typedef struct {
    int num_records;
    int max_num_records;
    ListNode *head;
    ListNode *tail;
} DynamicRecordStruct;

// Function to initialize the dynamic record struct with random integer values within a specified range
int initDynamicRecordStruct(DynamicRecordStruct *ds, int min_value, int max_value) {
    // Check if the input parameters are valid
    if (ds == NULL || min_value >= max_value) {
        return -1;
    }

    // Initialize the number of records and the maximum number of records
    ds->num_records = 0;
    ds->max_num_records = max_value - min_value + 1;

    // Allocate memory for the linked list nodes
    ListNode *node = malloc(sizeof(ListNode) * ds->max_num_records);
    if (node == NULL) {
        return -2;
    }

    // Initialize the head and tail pointers
    ds->head = node;
    ds->tail = node;

    // Generate random integer values for the records
    int i, j;
    for (i = 0; i < ds->max_num_records; ++i) {
        Record *record = &node[i].record;
        record->offset = min_value + rand() % (max_value - min_value);
        record->key = rand() % INT_MAX;
        record->timestamp = 0.0;
    }

    // Ensure thread-safety by using a mutex to protect the data structure
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    ds->mutex = &mutex;

    return 0;
}

// Function to insert a record into the dynamic record struct
int insertRecord(DynamicRecordStruct *ds, long offset, int key, double timestamp) {
    // Check if the input parameters are valid
    if (ds == NULL || offset < 0 || key < 0 || timestamp < 0.0) {
        return -1;
    }

    // Acquire the mutex to prevent race conditions
    pthread_mutex_lock(ds->mutex);

    // Check if the data structure is full
    if (ds->num_records == ds->max_num_records) {
        return -2;
    }

    // Allocate memory for a new record
    ListNode *node = malloc(sizeof(ListNode));
    if (node == NULL) {
        pthread_mutex_unlock(ds->mutex);
        return -3;
    }

    // Fill the new record with the input parameters
    Record *record = &node->record;
    record->offset = offset;
    record->key = key;
    record->timestamp = timestamp;

    // Add the new record to the linked list
    node->next = ds->tail->next;
    ds->tail->next = node;
    ds->tail = node;

    // Update the number of records and release the mutex
    ++ds->num_records;
    pthread_mutex_unlock(ds->mutex);

    return 0;
}

// Function to retrieve a record from the dynamic record struct
int getRecord(DynamicRecordStruct *ds, long offset, int key, double *timestamp) {
    // Check if the input parameters are valid
    if (ds == NULL || offset < 0 || key < 0 || timestamp == NULL) {
        return -1;
    }

    // Acquire the mutex to prevent race conditions
    pthread_mutex_lock(ds->mutex);

    // Search for the record in the linked list
    ListNode *node = ds->head;
    while (node != NULL) {
        if (node->record.offset == offset && node->record.key == key) {
            *timestamp = node->record.timestamp;
            pthread_mutex_unlock(ds->mutex);
            return 0;
        }
        node = node->next;
    }

    // Return -2 if the record is not found
    pthread_mutex_unlock(ds->mutex);
    return -2;
}

// Function to remove a record from the dynamic record struct
int removeRecord(DynamicRecordStruct *ds, long offset, int key) {
    // Check if the input parameters are valid
    if (ds == NULL || offset < 0 || key < 0) {
        return -1;
    }

    // Acquire the mutex to prevent race conditions
    pthread_mutex_lock(ds->mutex);

    // Search for the record in the linked list and remove it if found
    ListNode *prev = NULL, *node = ds->head;
    while (node != NULL) {
        if (node->record.offset == offset && node->record.key == key) {
            if (prev == NULL) {
                ds->head = node->next;
            } else {
                prev->next = node->next;
            }
            free(node);
            --ds->num_records;
            pthread_mutex_unlock(ds->mutex);
            return 0;
        }
        prev = node;
        node = node->next;
    }

    // Return -2 if the record is not found
    pthread_mutex_unlock(ds->mutex);
    return -2;
}

// Function to clear the dynamic record struct and release all memory
void clearDynamicRecordStruct(DynamicRecordStruct *ds) {
    // Acquire the mutex to prevent race conditions
    pthread_mutex_lock(ds->mutex);

    // Release all memory associated with the linked list nodes
    ListNode *node = ds->head;
    while (node != NULL) {
        ListNode *next = node->next;
        free(node);
        node = next;
    }

    // Reset the number of records and release the mutex
    ds->num_records = 0;
    pthread_mutex_unlock(ds->mutex);
}
```
