} CellStatsEntry;

// Maximum number of cells supported by the system
#define MAX_CELLS 1024

// Array to store L1 statistics for each cell
static CellStatsEntry *cell_stats = NULL;

// Mutex to protect concurrent access to the cell stats array
static pthread_mutex_t cell_stats_mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_l1_stats(int num_cells) {
    // Allocate memory for the cell statistics array
    cell_stats = malloc(num_cells * sizeof(CellStatsEntry));

    if (cell_stats == NULL) {
        printf("Failed to allocate memory for L1 statistics\n");
        return;
    }

    // Initialize each entry in the array with a default value
    for (int i = 0; i < num_cells; ++i) {
        cell_stats[i].cell_id = -1;
        memset(&cell_stats[i].stats, 0, sizeof(NFAPI_L1_STATS_T));
    }
}

void populate_l1_stats(int cell_id, NFAPI_L1_STATS_T *stats) {
    // Acquire the mutex to protect concurrent access to the cell stats array
    pthread_mutex_lock(&cell_stats_mutex);

    // Check if the cell ID is valid and if there is enough space in the array
    if (cell_id < 0 || cell_id >= MAX_CELLS || cell_stats[cell_id].cell_id != -1) {
        pthread_mutex_unlock(&cell_stats_mutex);
        return;
    }

    // Copy the L1 statistics for the given cell ID
    memcpy(&cell_stats[cell_id].stats, stats, sizeof(NFAPI_L1_STATS_T));

    // Release the mutex and update the cell ID in the entry
    pthread_mutex_unlock(&cell_stats_mutex);
    cell_stats[cell_id].cell_id = cell_id;
}

NFAPI_L1_STATS_T *get_l1_stats(int cell_id) {
    // Acquire the mutex to protect concurrent access to the cell stats array
    pthread_mutex_lock(&cell_stats_mutex);

    // Check if the cell ID is valid and if there is a corresponding entry in the array
    if (cell_id < 0 || cell_id >= MAX_CELLS || cell_stats[cell_id].cell_id == -1) {
        pthread_mutex_unlock(&cell_stats_mutex);
        return NULL;
    }

    // Return a pointer to the L1 statistics for the given cell ID
    NFAPI_L1_STATS_T *stats = &cell_stats[cell_id].stats;

    // Release the mutex and return the pointer
    pthread_mutex_unlock(&cell_stats_mutex);
    return stats;
}
