    NeighborCellInfo *neighborCells;
    SRSParameters srsParams;
} NetworkInterfaceConfig;

// Structure to represent a single neighbor cell
typedef struct NeighborCellInfo {
    uint32_t neighborId;
    int earfcn;
    int psc;
    int bandwidth;
} NeighborCellInfo;

// Structure to represent SRS parameters
typedef struct SRSParameters {
    int srsBandwidth;
    int srsSubcarrierSpacing;
    int srsNumberOfSymbols;
    int srsTimeDuration;
} SRSParameters;

// Enum to represent the different cryptographic ciphers available
typedef enum CryptoCipher {
    NULL_CRYPTO = 0,
    DES_ECB = 1,
    DES_EDE = 2,
    DES_EDE3 = 3,
    CFB_MODE = 4
} CryptoCipher;

// Function to initialize a dynamic array of NetworkInterfaceConfig structures
NetworkInterfaceConfig *initNetworkInterfaces(int numInterfaces) {
    // Allocate memory for the dynamic array
    NetworkInterfaceConfig **interfaces = malloc(sizeof(NetworkInterfaceConfig *) * numInterfaces);
    if (!interfaces) {
        printf("Error: unable to allocate memory for network interfaces\n");
        return NULL;
    }

    // Initialize each interface in the dynamic array
    for (int i = 0; i < numInterfaces; i++) {
        NetworkInterfaceConfig *interface = malloc(sizeof(NetworkInterfaceConfig));
        if (!interface) {
            printf("Error: unable to allocate memory for network interface %d\n", i);
            return NULL;
        }

        // Initialize the interface ID and number of neighbor cells
        interface->interfaceId = i + 1;
        interface->numNeighborCells = 0;

        // Allocate memory for the neighbor cell list
        interface->neighborCells = malloc(sizeof(NeighborCellInfo) * interface->numNeighborCells);
        if (!interface->neighborCells) {
            printf("Error: unable to allocate memory for neighbor cells in network interface %d\n", i);
            return NULL;
        }

        // Initialize the SRS parameters
        interface->srsParams.srsBandwidth = 0;
        interface->srsParams.srsSubcarrierSpacing = 0;
        interface->srsParams.srsNumberOfSymbols = 0;
        interface->srsParams.srsTimeDuration = 0;

        // Add the interface to the dynamic array
        interfaces[i] = interface;
    }

    return interfaces;
}

// Function to add a new neighbor cell to an existing network interface
int addNeighborCell(NetworkInterfaceConfig *interface, int neighborId, int earfcn, int psc, int bandwidth) {
    // Check if the neighbor ID is already in use
    for (int i = 0; i < interface->numNeighborCells; i++) {
        if (interface->neighborCells[i].neighborId == neighborId) {
            return -1;
        }
    }

    // Allocate memory for the new neighbor cell
    NeighborCellInfo *newNeighborCell = malloc(sizeof(NeighborCellInfo));
    if (!newNeighborCell) {
        printf("Error: unable to allocate memory for new neighbor cell\n");
        return -1;
    }

    // Initialize the new neighbor cell
    newNeighborCell->neighborId = neighborId;
    newNeighborCell->earfcn = earfcn;
    newNeighborCell->psc = psc;
    newNeighborCell->bandwidth = bandwidth;

    // Add the new neighbor cell to the list of neighbor cells
    interface->neighborCells[interface->numNeighborCells++] = newNeighborCell;

    return 0;
}

// Function to set SRS parameters for an existing network interface
void setSRSParameters(NetworkInterfaceConfig *interface, int srsBandwidth, int srsSubcarrierSpacing, int srsNumberOfSymbols, int srsTimeDuration) {
    interface->srsParams.srsBandwidth = srsBandwidth;
    interface->srsParams.srsSubcarrierSpacing = srsSubcarrierSpacing;
    interface->srsParams.srsNumberOfSymbols = srsNumberOfSymbols;
    interface->srsParams.srsTimeDuration = srsTimeDuration;
}

// Function to get the SRS parameters for an existing network interface
SRSParameters *getSRSParameters(NetworkInterfaceConfig *interface) {
    return &interface->srsParams;
}

// Function to set the cryptographic cipher for an existing network interface
void setCipher(NetworkInterfaceConfig *interface, CryptoCipher cipher) {
    interface->cipher = cipher;
}

// Function to get the cryptographic cipher for an existing network interface
CryptoCipher getCipher(NetworkInterfaceConfig *interface) {
    return interface->cipher;
}

// Function to encrypt data using the chosen cryptographic cipher
void *encryptData(void *data, int length, NetworkInterfaceConfig *interface) {
    // Check if the cipher is null
    if (interface->cipher == NULL_CRYPTO) {
        return data;
    }

    // Get the appropriate encrypt function for the chosen cipher
    void (*encryptFunc)(void *, int, CryptoCipher);
    switch (interface->cipher) {
        case AES128:
            encryptFunc = aes128Encrypt;
            break;
        case AES256:
            encryptFunc = aes256Encrypt;
            break;
        default:
            return data;
    }

    // Encrypt the data using the chosen cipher
    encryptFunc(data, length, interface->cipher);

    return data;
}

// Function to decrypt data using the chosen cryptographic cipher
void *decryptData(void *data, int length, NetworkInterfaceConfig *interface) {
    // Check if the cipher is null
    if (interface->cipher == NULL_CRYPTO) {
        return data;
    }

    // Get the appropriate decrypt function for the chosen cipher
    void (*decryptFunc)(void *, int, CryptoCipher);
    switch (interface->cipher) {
        case AES128:
            decryptFunc = aes128Decrypt;
            break;
        case AES256:
            decryptFunc = aes256Decrypt;
            break;
        default:
            return data;
    }

    // Decrypt the data using the chosen cipher
    decryptFunc(data, length, interface->cipher);

    return data;
}

// Function to set up a new network interface with the desired parameters
NetworkInterfaceConfig *setupNewInterface(int interfaceId, int neighborId, int earfcn, int psc, int bandwidth) {
    // Allocate memory for the new interface
    NetworkInterfaceConfig *interface = malloc(sizeof(NetworkInterfaceConfig));
    if (!interface) {
        printf("Error: unable to allocate memory for network interface %d\n", interfaceId);
        return NULL;
    }

    // Initialize the interface ID and number of neighbor cells
    interface->interfaceId = interfaceId;
    interface->numNeighborCells = 0;

    // Allocate memory for the neighbor cell list
    interface->neighborCells = malloc(sizeof(NeighborCellInfo) * interface->numNeighborCells);
    if (!interface->neighborCells) {
        printf("Error: unable to allocate memory for neighbor cells in network interface %d\n", interfaceId);
        return NULL;
    }

    // Initialize the SRS parameters
    interface->srsParams.srsBandwidth = 0;
    interface->srsParams.srsSubcarrierSpacing = 0;
    interface->srsParams.srsNumberOfSymbols = 0;
    interface->srsParams.srsTimeDuration = 0;

    // Set the cryptographic cipher to null
    interface->cipher = NULL_CRYPTO;

    // Add the new neighbor cell to the list of neighbor cells
    addNeighborCell(interface, neighborId, earfcn, psc, bandwidth);

    return interface;
}

// Function to get a list of all network interfaces
NetworkInterfaceConfig **getAllInterfaces() {
    // Check if any network interfaces have been initialized
    if (!interfaces) {
        printf("Error: no network interfaces have been initialized\n");
        return NULL;
    }

    // Return the list of all network interfaces
    return interfaces;
}

// Function to get a specific network interface by its ID
NetworkInterfaceConfig *getInterfaceById(int id) {
    // Check if any network interfaces have been initialized
    if (!interfaces) {
        printf("Error: no network interfaces have been initialized\n");
        return NULL;
    }

    // Find the interface with the specified ID
    for (int i = 0; i < numInterfaces; i++) {
        if (interfaces[i]->interfaceId == id) {
            return interfaces[i];
        }
    }

    printf("Error: network interface %d does not exist\n", id);
    return NULL;
}

// Function to destroy a specific network interface by its ID
void destroyInterfaceById(int id) {
    // Check if any network interfaces have been initialized
    if (!interfaces) {
        printf("Error: no network interfaces have been initialized\n");
        return;
    }

    // Find the interface with the specified ID and remove it from the list of interfaces
    for (int i = 0; i < numInterfaces; i++) {
        if (interfaces[i]->interfaceId == id) {
            free(interfaces[i]);
            memmove(&interfaces[i], &interfaces[i+1], sizeof(NetworkInterfaceConfig *) * (numInterfaces - i));
            numInterfaces--;
            return;
        }
    }

    printf("Error: network interface %d does not exist\n", id);
}

// Function to destroy all network interfaces
void destroyAllInterfaces() {
    // Check if any network interfaces have been initialized
    if (!interfaces) {
        printf("Error: no network interfaces have been initialized\n");
        return;
    }

    // Destroy each interface in the list
    for (int i = 0; i < numInterfaces; i++) {
        free(interfaces[i]);
    }

    // Reset the number of interfaces to zero
    numInterfaces = 0;
}']

