} log_entry;

// Function to generate a random log entry
static void generate_random_log_entry(log_entry *entry) {
    entry->log_level = rand() % 8; // random value between 0 and 7
    char *time_zone = malloc(16);
    snprintf(time_zone, 16, "UTC%d", (rand() % 24) + 1); // random time zone between UTC1 and UTC24
    entry->time_zone = time_zone;
    entry->temperature = rand() % 100 - 50.0; // random temperature value between -50 and +50 degrees Celsius
}

// Function to update the log entries with new data
void update_log_entries(int num_entries) {
    // Allocate an array of log entries
    log_entry *entries = malloc(num_entries * sizeof(log_entry));
    if (entries == NULL) {
        fprintf(stderr, "Failed to allocate memory for log entries: %s\n", strerror(errno));
        return;
    }

    // Initialize each entry with a random value
    for (int i = 0; i < num_entries; i++) {
        generate_random_log_entry(&entries[i]);
    }

    // Write the log entries to disk
