    FILE *file = fopen(LOG_FILE_NAME, "rb");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for reading: %s\n", strerror(errno));
        return;
    }

    // Allocate an array of log entries
    log_entry *entries = malloc(MAX_LOG_ENTRIES * sizeof(log_entry));
    if (entries == NULL) {
        fprintf(stderr, "Failed to allocate memory for log entries: %s\n", strerror(errno));
        free(file);
        return;
    }

    // Read the log entries from disk
    int num_read = fread(entries, sizeof(log_entry), MAX_LOG_ENTRIES, file);
    if (num_read == 0) {
        fprintf(stderr, "Failed to read any log entries: %s\n", strerror(errno));
        free(file);
        return;
    }

    // Print the log entries
    for (int i = 0; i < num_read; i++) {
        printf("Log entry %d:\n", i);
        printf("  Log level: %d\n", entries[i].log_level);
        printf("  Time zone: %s\n", entries[i].time_zone);
        printf("  Temperature: %.2f\n", entries[i].temperature);
    }

    // Free the log entries array and close the file
    free(entries);
    fclose(file);
}

// Function to fetch real-time temperature updates from an external weather API
void fetch_weather_updates() {
    // Open a connection to the external weather API
    CURL *curl = curl_easy_init();
    if (curl == NULL) {
        fprintf(stderr, "Failed to initialize cURL: %s\n", strerror(errno));
        return;
    }

    // Set the URL for the weather API endpoint
    char *url = "https://api.openweathermap.org/data/2.5/weather?q=London,UK";

    // Set the HTTP headers for the request
    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Accept: application/json");
    headers = curl_slist_append(headers, "X-Api-Key: YOUR_API_KEY");

    // Set the options for the request
    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

    // Perform the request and check for errors
    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "Failed to perform cURL request: %s\n", curl_easy_strerror(res));
        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
        return;
    }

    // Read the response from the API
    char *response = malloc(1024);
    size_t response_len = 1024;
    res = curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_len);
    if (res != CURLE_OK) {
        fprintf(stderr, "Failed to read cURL response: %s\n", curl_easy_strerror(res));
        free(response);
        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
        return;
    }

    // Parse the response from JSON to a C struct
    cJSON *root = cJSON_Parse(response);
    if (root == NULL) {
        fprintf(stderr, "Failed to parse JSON: %s\n", cJSON_GetErrorPtr());
        free(response);
        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
        return;
    }

    // Extract the temperature from the API response
    double temperature = root->temperature->value;
    printf("Current temperature: %.2f\n", temperature);

    // Clean up resources
    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);
}

// Function to print the log entries and fetch real-time weather updates concurrently
void print_log_entries_and_fetch_weather() {
    // Print the log entries
    read_log_entries();

    // Fetch real-time weather updates in a separate thread
    pthread_t thread;
    pthread_create(&thread, NULL, fetch_weather_updates, NULL);
}

