// Function to efficiently extract and manage a contiguous sequence of states from a given finite state automaton (FSA)
void extract_sequence(int* states, int num_states, FSA fsa, int start_state, int end_state) {
    // Initialize the list of extracted states
    List<Integer> extracted_states = new List<Integer>();

    // Iterate over the states in the given range
    for (int i = start_state; i <= end_state; i++) {
        // Get the next state in the sequence
        int next_state = fsa.get_next_state(i);

        // Add the next state to the list of extracted states if it is not already present
        if (!extracted_states.contains(next_state)) {
            extracted_states.add(next_state);
        }
    }

    // Update the pointers within the FSA to point to the first and last states in the sequence
    fsa.set_first_state(start_state);
    fsa.set_last_state(end_state);

    // Return the list of extracted states
    return extracted_states;
}

