// Define a struct for the collection of UEs and their associated RACH information
typedef struct {
    NFAPI_UE_ID ue_id;
    NFAPI_RACH_INFO_T *rach_info;
} NFAPI_MESSAGE_T;

// Define a hashtable to store the UEs and their associated RACH information
static HTABLE_T *ue_table = NULL;

// Define a function for adding a new UE to the collection
void add_new_ue(NFAPI_UE_ID ue_id, NFAPI_RACH_INFO_T *rach_info) {
    // Check if the UE already exists in the table
    bool found = false;
    for (int i = 0; i < ue_table->num_entries; i++) {
        if (ue_table->entries[i].ue_id == ue_id) {
            found = true;
            break;
        }
    }

    // If the UE is not found, add a new entry to the table
    if (!found) {
        NFAPI_MESSAGE_T *new_entry = malloc(sizeof(NFAPI_MESSAGE_T));
        new_entry->ue_id = ue_id;
        new_entry->rach_info = rach_info;

        // Add the new entry to the end of the table
        ue_table->entries[ue_table->num_entries++] = *new_entry;
    } else {
        // Update the existing entry with the new RACH information
        NFAPI_MESSAGE_T *existing_entry = &(ue_table->entries[i]);
        existing_entry->rach_info = rach_info;
    }
}

// Define a function for updating an existing UE's RACH information
void update_ue_rach_info(NFAPI_UE_ID ue_id, NFAPI_RACH_INFO_T *new_rach_info) {
    // Check if the UE exists in the table
    bool found = false;
    for (int i = 0; i < ue_table->num_entries; i++) {
        if (ue_table->entries[i].ue_id == ue_id) {
            found = true;
            break;
        }
    }

    // If the UE is found, update its RACH information
    if (found) {
        NFAPI_MESSAGE_T *existing_entry = &(ue_table->entries[i]);
        existing_entry->rach_info = new_rach_info;
    } else {
        // If the UE is not found, add a new entry to the table with the updated RACH information
        NFAPI_MESSAGE_T *new_entry = malloc(sizeof(NFAPI_MESSAGE_T));
        new_entry->ue_id = ue_id;
        new_entry->rach_info = new_rach_info;

        // Add the new entry to the end of the table
        ue_table->entries[ue_table->num_entries++] = *new_entry;
    }
}

// Define a function for querying the latest RACH sequence for a given UE ID
NFAPI_RACH_INFO_T *query_latest_rach_info(NFAPI_UE_ID ue_id) {
    // Check if the UE exists in the table
    bool found = false;
    for (int i = 0; i < ue_table->num_entries; i++) {
        if (ue_table->entries[i].ue_id == ue_id) {
            found = true;
            break;
        }
    }

    // If the UE is not found, return NULL
    if (!found) {
        return NULL;
    }

    // Return the latest RACH information for the UE
    NFAPI_MESSAGE_T *existing_entry = &(ue_table->entries[i]);
    return existing_entry->rach_info;
}

