            found = true;
            break;
        }
    }

    // If the UE is not found, add a new entry to the table with the updated RACH information
    if (!found) {
        NFAPI_MESSAGE_T *new_entry = malloc(sizeof(NFAPI_MESSAGE_T));
        new_entry->ue_id = ue_id;
        new_entry->rach_info = new_rach_info;

        // Add the new entry to the end of the table
        ue_table->entries[ue_table->num_entries++] = *new_entry;
    } else {
        // Update the existing entry with the new RACH information
        NFAPI_MESSAGE_T *existing_entry = &(ue_table->entries[i]);
        existing_entry->rach_info = new_rach_info;
    }
}

// Define a function for managing memory efficiently and minimizing latency during updates
void manage_memory() {
    // Check if the table needs to be resized
    if (ue_table->num_entries >= ue_table->max_size) {
        NFAPI_MESSAGE_T *new_table = malloc(sizeof(NFAPI_MESSAGE_T) * 2 * ue_table->max_size);
        memcpy(new_table, ue_table->entries, sizeof(NFAPI_MESSAGE_T) * ue_table->num_entries);
        free(ue_table->entries);
        ue_table->entries = new_table;
        ue_table->max_size *= 2;
    }
}

// Define a function for handling concurrent access to the collection of UEs and ensuring thread-safe operations
void handle_concurrent_access() {
    // Use a lock to ensure that only one thread can access the table at a time
    pthread_mutex_lock(&ue_table->lock);
    // Perform the operation on the table
    add_new_ue(NFAPI_UE_ID, NFAPI_RACH_INFO_T *);
    // Release the lock
    pthread_mutex_unlock(&ue_table->lock);
}
