    // rate-limit the creation of new CRC_INDICATION_REL8_TAG instances per second
    if (list->length >= MAX_CRC_INDICATIONS) {
        printf("Rate limit exceeded: %d CRC_INDICATION_REL8_TAG instances created in the last second\n", list->length - MAX_CRC_INDICATIONS);
        return;
    }

    // handle potential failures during memory allocation gracefully
    try {
        NFAPI_CRC_INDICATION_PDU_T *newPdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!newPdu) {
            printf("Error: failed to allocate memory for new CRC_INDICATION_REL8_TAG instance\n");
            return;
        }
        list->length++;
    } catch (const std::bad_alloc &e) {
        printf("Error: failed to allocate memory for new CRC_INDICATION_REL8_TAG instance: %s\n", e.what());
        return;
    }
}
```
