Here is an example of a modular encryption service in C that supports multiple cipher modes (AES-128-CBC, AES-256-GCM, ChaCha20-Poly1305) and allows seamless integration with both symmetric and asymmetric encryption keys:
```
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/aes.h>
#include <openssl/evp.h>
#include <openssl/chacha20poly1305.h>
#include <openssl/rand.h>
#include <openssl/ecdh.h>
#include <openssl/bn.h>
#include <openssl/sha.h>

// Define the supported cipher modes
enum CipherMode {
    CIPHER_MODE_AES_128_CBC,
    CIPHER_MODE_AES_256_GCM,
    CIPHER_MODE_CHACHA20_POLY1305
};

// Define the supported encryption keys
enum EncryptionKey {
    ENCRYPTION_KEY_SYMMETRIC,
    ENCRYPTION_KEY_ASYMMETRIC
};

// Struct to store the encryption parameters
struct EncryptionParams {
    enum CipherMode mode;
    enum EncryptionKey keyType;
    unsigned char *key;
    size_t keySize;
    unsigned char *iv;
    size_t ivSize;
    unsigned char *aad;
    size_t aadSize;
};

// Function to generate an initialization vector (IV) for encryption
void generateIV(unsigned char *iv, size_t ivSize) {
    RAND_bytes(iv, ivSize);
}

// Function to encrypt data using the specified cipher mode and key
int encryptData(struct EncryptionParams *params, unsigned char *data, size_t dataSize, unsigned char *encryptedData) {
    // Check if the encryption parameters are valid
    if (params == NULL || params->key == NULL || params->keySize == 0 || data == NULL || dataSize == 0 || encryptedData == NULL) {
        return -1;
    }

    // Initialize the encryption context
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        return -2;
    }

    // Set the cipher mode and key size
    switch (params->mode) {
        case CIPHER_MODE_AES_128_CBC:
            EVP_EncryptInit_ex(ctx, EVP_aes_128_cbc(), NULL, params->key, params->iv);
            break;
        case CIPHER_MODE_AES_256_GCM:
            EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, params->key, params->iv);
            break;
        case CIPHER_MODE_CHACHA20_POLY1305:
            EVP_EncryptInit_ex(ctx, EVP_chacha20poly1305(), NULL, params->key, params->iv);
            break;
    }

    // Encrypt the data
    int encryptedDataSize = 0;
    if (EVP_EncryptUpdate(ctx, encryptedData, &encryptedDataSize, data, dataSize) <= 0) {
        return -3;
    }

    // Finalize the encryption
    if (EVP_EncryptFinal_ex(ctx, encryptedData + encryptedDataSize, &encryptedDataSize) <= 0) {
        return -4;
    }

    // Clean up the encryption context
    EVP_CIPHER_CTX_free(ctx);

    return encryptedDataSize;
}

// Function to decrypt data using the specified cipher mode and key
int decryptData(struct EncryptionParams *params, unsigned char *encryptedData, size_t encryptedDataSize, unsigned char *data) {
    // Check if the encryption parameters are valid
    if (params == NULL || params->key == NULL || params->keySize == 0 || encryptedData == NULL || encryptedDataSize == 0 || data == NULL) {
        return -1;
    }

    // Initialize the decryption context
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        return -2;
    }

    // Set the cipher mode and key size
    switch (params->mode) {
        case CIPHER_MODE_AES_128_CBC:
            EVP_DecryptInit_ex(ctx, EVP_aes_128_cbc(), NULL, params->key, params->iv);
            break;
        case CIPHER_MODE_AES_256_GCM:
            EVP_DecryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, params->key, params->iv);
            break;
        case CIPHER_MODE_CHACHA20_POLY1305:
            EVP_DecryptInit_ex(ctx, EVP_chacha20poly1305(), NULL, params->key, params->iv);
            break;
    }

    // Decrypt the data
    int decryptedDataSize = 0;
    if (EVP_DecryptUpdate(ctx, data, &decryptedDataSize, encryptedData, encryptedDataSize) <= 0) {
        return -3;
    }

    // Finalize the decryption
    if (EVP_DecryptFinal_ex(ctx, data + decryptedDataSize, &decryptedDataSize) <= 0) {
        return -4;
    }

    // Clean up the decryption context
    EVP_CIPHER_CTX_free(ctx);

    return decryptedDataSize;
}

// Function to generate a shared secret key between two parties using Diffie-Hellman key exchange
void generateSharedSecretKey(struct EncryptionParams *params, unsigned char *secretKey) {
    // Check if the encryption parameters are valid
    if (params == NULL || params->keyType != ENCRYPTION_KEY_ASYMMETRIC || secretKey == NULL) {
        return;
    }

    // Generate a Diffie-Hellman key pair
    EVP_PKEY *pkey = EVP_PKEY_new();
    if (pkey == NULL) {
        return;
    }

    EVP_PKEY_CTX *ctx = EVP_PKEY_CTX_new(params->key, NULL);
    if (ctx == NULL) {
        EVP_PKEY_free(pkey);
        return;
    }

    if (EVP_PKEY_keygen_init(ctx) <= 0 || EVP_PKEY_keygen(ctx, pkey) <= 0) {
        EVP_PKEY_CTX_free(ctx);
        EVP_PKEY_free(pkey);
        return;
    }

    // Get the shared secret key
    size_t keyLen = EVP_PKEY_size(pkey);
    if (secretKey == NULL || keyLen > sizeof(unsigned char) * 1024) {
        EVP_PKEY_CTX_free(ctx);
        EVP_PKEY_free(pkey);
        return;
    }

    // Derive the shared secret key using Diffie-Hellman key exchange
    if (EVP_PKEY_derive(ctx, secretKey, &keyLen) <= 0) {
        EVP_PKEY_CTX_free(ctx);
        EVP_PKEY_free(pkey);
        return;
    }

    // Clean up the Diffie-Hellman key exchange context
    EVP_PKEY_CTX_free(ctx);
    EVP_PKEY_free(pkey);
}

// Function to generate a random nonce
void generateNonce(unsigned char *nonce) {
    // Check if the nonce is valid
    if (nonce == NULL) {
        return;
    }

    // Generate a random nonce using OpenSSL's RAND_bytes function
    int result = RAND_bytes(nonce, sizeof(unsigned char) * 1024);
    if (result <= 0) {
        return;
    }
}

// Function to generate an HMAC using SHA-256
void generateHMAC(struct EncryptionParams *params, unsigned char *data, size_t dataLen, unsigned char *hmac) {
    // Check if the encryption parameters are valid and the HMAC is not null
    if (params == NULL || hmac == NULL) {
        return;
    }

    // Generate an HMAC using SHA-256
    unsigned int hmacLen = 0;
    HMAC(EVP_sha256(), params->hmacKey, sizeof(unsigned char) * 1024, data, dataLen, hmac, &hmacLen);
}
```

