// Function to initialize and populate two arrays: one for 'long' offset values and another for 'int' keys, along with an array of 'record' structures containing a single 'int' value.
void init_arrays(size_t max_size, size_t limit, int min_value, int max_value) {
    // Allocate memory dynamically for the arrays
    long *offsets = (long *)malloc(max_size * sizeof(long));
    int *keys = (int *)malloc(max_size * sizeof(int));
    struct Record *records = (struct Record *)malloc(max_size * sizeof(struct Record));

    // Check for allocation failures and log errors
    if (offsets == NULL || keys == NULL || records == NULL) {
        printf("Memory allocation failure\n");
        return;
    }

    // Initialize the arrays with random values within the given range
    srand(time(NULL));
    for (size_t i = 0; i < max_size; i++) {
        offsets[i] = rand() % (max_value - min_value + 1) + min_value;
        keys[i] = rand() % (max_value - min_value + 1) + min_value;
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
