    FILE *fp = fopen(log_file, "a");
    if (!fp) {
        // Handle file opening failure gracefully
        printf("File opening failed!\n");
        return;
    }

    // Write the PDU information to the log file
    fprintf(fp, "PDU %d: RX_UE_INFORMATION_TAG = %hu, RNTI = %hu, CRCFLAG = %d\n", pdu->rx_ue_information_tag, pdu->rnti, pdu->crc_indication_rel8_tag);

    // Close the log file
    fclose(fp);
}

// Define a function to create and initialize an array of PDUs based on a given number of structures
NFAPI_CRC_INDICATION_PDU* init_pdus(size_t num_pdus) {
