    int crcFlag;
} crcIndicationPdu_t;

// Define the function for generating a list of CRC indication PDUs
NFAPI_ERROR_CODE createAndPopulateNfapiPduList(const char *hostname, const char *serviceName, int maxRetries, int backoffFactor, int maxPduCount, crcIndicationPdu_t **pduList) {
    // Initialize the error code to indicate no errors
    NFAPI_ERROR_CODE err = NFAPI_OK;

    // Validate the input parameters
    if (hostname == NULL || serviceName == NULL || maxRetries < 0 || backoffFactor <= 0 || maxPduCount <= 0 || pduList == NULL) {
        return NFAPI_ERR_INVALID_PARAMETERS;
    }

    // Initialize the DNS lookup variables
    int dnsLookupRetries = 0;
    struct addrinfo *addrInfo = NULL;
    struct addrinfo hints = {};
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_protocol = IPPROTO_TCP;

    // Initialize the buffer for storing the IP address
    char ipBuffer[IP_BUFFER_SIZE] = {};

    // Loop until we have successfully resolved the hostname or reached the maximum number of retries
    while (dnsLookupRetries < maxRetries) {
        // Perform the DNS lookup
        int res = getaddrinfo(hostname, serviceName, &hints, &addrInfo);
        if (res == 0 && addrInfo != NULL) {
            break;
        } else {
            printf("DNS lookup failed with error code %d\n", errno);
            freeaddrinfo(addrInfo);
            addrInfo = NULL;
            // Exponentially backoff for the next retry
            sleep((1 << (dnsLookupRetries - 1)) * backoffFactor);
            dnsLookupRetries++;
        }
    }

    // Check if we have successfully resolved the hostname
    if (addrInfo == NULL) {
        printf("Failed to resolve %s:%s after %d retries\n", hostname, serviceName, maxRetries);
        return NFAPI_ERR_DNS_LOOKUP;
    }

    // Allocate memory for the PDU list and initialize it
    *pduList = malloc(sizeof(crcIndicationPdu_t) * maxPduCount);
    if (*pduList == NULL) {
        printf("Failed to allocate memory for PDU list\n");
        freeaddrinfo(addrInfo);
        return NFAPI_ERR_MEMORY;
    }

    // Loop over the list of PDUs and populate them with random data
    int pduIndex = 0;
    while (pduIndex < maxPduCount) {
        // Generate a random RX_UE_INFORMATION_TAG
        uint32_t rxUeInformationTag = rand();

        // Generate a random RNTI
        uint16_t rnti = (rand() & 0xFFFF);

        // Generate a random CRC_INDICATION_REL8_TAG
        uint8_t crcIndicationRel8Tag = rand();

        // Generate a random CRCFLAG
        int crcFlag = rand() % 2;

        // Populate the PDU with the random data
        (*pduList)[pduIndex].crcIndicationPdu.rxUeInformationTag = rxUeInformationTag;
        (*pduList)[pduIndex].crcIndicationPdu.rnti = rnti;
        (*pduList)[pduIndex].crcIndicationPdu.crcIndicationRel8Tag = crcIndicationRel8Tag;
        (*pduList)[pduIndex].crcFlag = crcFlag;

        // Increment the PDU index
        pduIndex++;
    }

    // Free the addrInfo structure
    freeaddrinfo(addrInfo);

    // Return the list of PDUs
    return NFAPI_OK;
}
