['//C code for a dynamic list of network event logs
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#define EVENT_LOG_SIZE 1024 //size of the event log buffer
#define EVENT_LOG_NAME "event_log" //name of the event log file
#define MEMORY_ALLOCATION_FAILURE -1 //error code for memory allocation failure
struct network_event_log {
    time_t timestamp; //timestamp of the event
    int type; //type of the event (e.g., connect, disconnect)
    char *source_ip; //source IP address of the event
    char *description; //detailed description of the event
};
//function to allocate memory for a new network event log
struct network_event_log* create_network_event_log(time_t timestamp, int type, char *source_ip, char *description) {
    struct network_event_log *new_event = (struct network_event_log *)malloc(sizeof(struct network_event_log));
    if (!new_event) {
        fprintf(stderr, "Memory allocation failure: %s\n", strerror(MEMORY_ALLOCATION_FAILURE));
        return NULL;
    }
    new_event->timestamp = timestamp;
    new_event->type = type;
    new_event->source_ip = source_ip;
    new_event->description = description;
    return new_event;
}
//function to add a network event log to the list
int add_network_event(struct network_event_log *new_event) {
    struct network_event_log **event_list; //dynamic array of network event logs
    int current_size = 0; //current size of the event list
    if (!new_event) {
        return -1;
    }
    event_list = (struct network_event_log **)malloc(sizeof(struct network_event_log *) * EVENT_LOG_SIZE);
    if (!event_list) {
        fprintf(stderr, "Memory allocation failure: %s\n", strerror(MEMORY_ALLOCATION_FAILURE));
        return -1;
    }
    //check if the event list needs to be resized
    if (current_size == EVENT_LOG_SIZE) {
        struct network_event_log **new_list = (struct network_event_log **)realloc(event_list, sizeof(struct network_event_log *) * (EVENT_LOG_SIZE + EVENT_LOG_SIZE));
        if (!new_list) {
            fprintf(stderr, "Memory allocation failure: %s\n", strerror(MEMORY_ALLOCATION_FAILURE));
            return -1;
        }
        event_list = new_list;
    }
    //add the new event to the list
    event_list[current_size] = new_event;
    current_size++;
    return 0;
}
//function to truncate the event log file at the start of each logging session
int truncate_event_log() {
    FILE *log_file; //pointer to the event log file
    int bytes_written = 0; //number of bytes written to the file
    char *buffer = (char *)malloc(EVENT_LOG_SIZE);
    if (!buffer) {
        fprintf(stderr, "Memory allocation failure: %s\n", strerror(MEMORY_ALLOCATION_FAILURE));
        return -1;
    }
    //open the event log file for writing in truncate mode (w+)
    log_file = fopen(EVENT_LOG_NAME, "w+");
    if (!log_file) {
        fprintf(stderr, "File opening failure: %s\n", strerror(errno));
        free(buffer);
        return -1;
    }
    //truncate the file to remove any existing data
    bytes_written = ftruncate(fileno(log_file), 0);
    if (bytes_written == -1) {
        fprintf(stderr, "File truncation failure: %s\n", strerror(errno));
        free(buffer);
        return -1;
    }
    //close the file and free the buffer
    fclose(log_file);
    free(buffer);
    return 0;
}
//function to record a network event in the log file
int record_network_event(struct network_event_log *event) {
    FILE *log_file; //pointer to the event log file
    int bytes_written = 0; //number of bytes written to the file
    char *buffer = (char *)malloc(EVENT_LOG_SIZE);
    if (!buffer) {
        fprintf(stderr, "Memory allocation failure: %s\n", strerror(MEMORY_ALLOCATION_FAILURE));
        return -1;
    }
    //open the event log file for appending (a+)
    log_file = fopen(EVENT_LOG_NAME, "a+");
    if (!log_file) {
        fprintf(stderr, "File opening failure: %s\n", strerror(errno));
        free(buffer);
        return -1;
    }
    //write the event to the file
    bytes_written = fprintf(log_file, "%ld %d %s %s\n", event->timestamp, event->type, event->source_ip, event->description);
    if (bytes_written < 0) {
        fprintf(stderr, "File write failure: %s\n", strerror(errno));
        free(buffer);
        return -1;
    }
    //close the file and free the buffer
    fclose(log_file);
    free(buffer);
    return 0;
}
int main() {
    struct network_event_log *event = (struct network_event_log *)malloc(sizeof(struct network_event_log));
    if (!event) {
        fprintf(stderr, "Memory allocation failure: %s\n", strerror(MEMORY_ALLOCATION_FAILURE));
        return -1;
    }
    event->timestamp = time(NULL); //current timestamp
    event->type = 1; //network connection event type
    char *source_ip = "192.168.0.1"; //source IP address of the network connection
    strcpy(event->source_ip, source_ip);
    char *description = "User connected to Wi-Fi network"; //description of the network event
    strcpy(event->description, description);
    add_network_event(event); //add the new event to the list
    truncate_event_log(); //truncate the log file at the start of each logging session
    record_network_event(event); //record the network event in the log file
    free(event); //free the memory allocated for the event
    return 0;
}']

