    while (*str != '\0') {
        hash ^= *(unsigned char*)str++;
        hash *= 16777619;
    }
    return hash;
}

// Struct for metadata associated with each record
struct metadata {
    bool allocated; // Whether the memory is currently in use
    int value; // The integer value stored in the record
};

// Struct for extended metadata associated with each record
struct extended_metadata {
    bool dirty; // Whether the record has been modified since last write
    int status; // Status of the allocation (e.g., whether it's a free block)
    void* next; // Pointer to the next available memory block
};

// Struct for each record in the hash table
struct record {
    unsigned long offset; // Offset into the array of 'long' values
    int key; // Key associated with this record (e.g., a string)
    struct metadata* metadata; // Pointer to the metadata for this record
    struct extended_metadata* extended_metadata; // Pointer to the extended metadata for this record
};

// Global variable for tracking the number of allocated records
int num_allocated = 0;

// Global variable for tracking the number of free records
int num_free = 0;

// Linked list structure for managing free memory blocks
struct free_block {
    void* block; // Pointer to the free memory block
    struct free_block* next; // Pointer to the next available free block
};

// Lock for synchronizing access to the hash table and free lists
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Initialize a new record in the hash table with a random integer value
void initRecord(struct record* record) {
    // Generate a random integer value within the specified range
    record->value = (int)(rand() % (MAX_INT_VALUE - MIN_INT_VALUE + 1)) + MIN_INT_VALUE;

    // Allocate memory for the metadata and extended metadata structures
    record->metadata = malloc(METADATA_SIZE);
    record->extended_metadata = malloc(EXTENDED_METADATA_SIZE);

    // Initialize the metadata and extended metadata structures
    record->metadata->allocated = false;
    record->metadata->value = record->value;
    record->extended_metadata->dirty = false;
    record->extended_metadata->status = 0;
    record->extended_metadata->next = NULL;
}

// Free a record and its associated metadata and extended metadata structures
void freeRecord(struct record* record) {
    // Mark the record as free
    record->metadata->allocated = false;

    // Add the record to the list of free records
    num_free++;

    // Remove the record from the hash table
    int index = customHashFunction(&record->key) % HASH_TABLE_SIZE;
    struct record* previous = NULL;
    while (table[index] != record) {
        previous = table[index];
        index++;
        if (index >= HASH_TABLE_SIZE) {
            index = 0;
        }
    }
    if (previous == NULL) {
        table[index] = table[index]->next;
    } else {
        previous->next = record->next;
    }
}

// Allocate memory for a new record and initialize its metadata and extended metadata structures
struct record* allocateRecord(int key, unsigned long offset) {
    // Check if the hash table needs to be resized
    if (num_allocated >= HASH_TABLE_SIZE * LOAD_FACTOR) {
        resizeHashTable();
    }

    // Lock the hash table and free lists to prevent concurrent access
    pthread_mutex_lock(&lock);

    // Search for an available record in the hash table
    struct record* current = table[customHashFunction(key) % HASH_TABLE_SIZE];
    while (current != NULL && current->metadata->allocated == true) {
        if (current->key == key) {
            pthread_mutex_unlock(&lock);
            return current; // Return the existing record
        }
        current = current->next;
    }

    // Allocate memory for a new record and initialize its metadata and extended metadata structures
    struct record* new_record = malloc(sizeof(struct record));
    new_record->offset = offset;
    new_record->key = key;
    initRecord(new_record);

    // Add the record to the hash table
    num_allocated++;
    current = table[customHashFunction(key) % HASH_TABLE_SIZE];
    new_record->next = current;
    table[customHashFunction(key) % HASH_TABLE_SIZE] = new_record;

    // Add the record to the list of allocated records
    num_free--;

    pthread_mutex_unlock(&lock);

    return new_record; // Return the newly allocated record
}

// Resize the hash table by doubling its size
void resizeHashTable() {
    int new_size = HASH_TABLE_SIZE * 2;
    struct record** new_table = malloc(sizeof(struct record*) * new_size);
    for (int i = 0; i < new_size; i++) {
        new_table[i] = NULL;
    }

    // Lock the hash table and free lists to prevent concurrent access
    pthread_mutex_lock(&lock);

    // Copy all records from the old table to the new table
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        struct record* current = table[i];
        while (current != NULL) {
            int index = customHashFunction(current->key) % new_size;
            current->next = new_table[index];
            new_table[index] = current;
            current = current->next;
        }
    }

    // Free the old table and update the hash table size
    free(table);
    table = new_table;
    HASH_TABLE_SIZE *= 2;

    pthread_mutex_unlock(&lock);
}

// Free all records in the hash table and reset the hash table size
void clearHashTable() {
    // Lock the hash table and free lists to prevent concurrent access
    pthread_mutex_lock(&lock);

    // Free all records in the hash table
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        struct record* current = table[i];
        while (current != NULL) {
            freeRecord(current);
            current = current->next;
        }
    }

    // Free the hash table and reset the hash table size
    free(table);
    HASH_TABLE_SIZE = INITIAL_HASH_TABLE_SIZE;

    pthread_mutex_unlock(&lock);
}

// Main function to test the hash table implementation
int main() {
    // Initialize the hash table with an initial size
    int INITIAL_HASH_TABLE_SIZE = 16;
    struct record** table = malloc(sizeof(struct record*) * INITIAL_HASH_TABLE_SIZE);
    for (int i = 0; i < INITIAL_HASH_TABLE_SIZE; i++) {
        table[i] = NULL;
    }

    // Insert records into the hash table and perform operations on them
    struct record* r1 = allocateRecord(1, 0);
    struct record* r2 = allocateRecord(2, 1);
    struct record* r3 = allocateRecord(3, 2);
    freeRecord(r1);
    freeRecord(r3);
    resizeHashTable();

    // Clear the hash table and free all memory allocated for records and metadata structures
    clearHashTable();
}
```

This implementation uses a hash table to store the records, with each bucket in the hash table containing a linked list of records with the same hash value. The hash table is resized when it reaches a certain load factor, which ensures that the hash table does not become too large and slows down the program. The `allocateRecord` function allocates memory for a new record and initializes its metadata structures, while the `freeRecord` function frees the memory allocated for a record and removes it from the hash table.

This implementation also uses a mutex lock to prevent concurrent access to the hash table and free lists during operations on them. This ensures that multiple threads accessing the hash table do not interfere with each other's operations, which improves the performance of the program."]

