void updateNetworkInterfaceConfig(int interfaceId, List<NeighborCellInfo> neighborCells, SRSConfig srsConfig) {
    // Acquire lock on the interface list
    pthread_mutex_lock(&interfaceLock);

    // Update the configuration settings for the specified network interface
    int index = 0;
    while (index < interfaceCount && interfaceList[index].interfaceId != interfaceId) {
        index++;
    }
    if (index < interfaceCount) {
        interfaceList[index].neighborCells = neighborCells;
        interfaceList[index].srsConfig = srsConfig;
    }

    // Release lock on the interface list
    pthread_mutex_unlock(&interfaceLock);
}

