#include <math.h>

typedef struct LTE_ENB_RRC_PDU_T {
    int UE_ID;
    int RRC_connection_state;
    PDU_DATA_TAG PDU_data_tag;
    float* input_numbers; // Array of floating-point numbers read from standard input
} LTE_ENB_RRC_PDU_T;

LTE_ENB_RRC_PDU_T* allocate_LTE_ENB_RRC_PDU(int UE_ID, int RRC_connection_state, float* input_numbers) {
    LTE_ENB_RRC_PDU_T* pdu = (LTE_ENB_RRC_PDU_T*) malloc(sizeof(LTE_ENB_RRC_PDU_T));
    if (!pdu) {
        fprintf(stderr, "Error: Unable to allocate memory for LTE_ENB_RRC_PDU\n");
        return NULL;
    }

    pdu->UE_ID = UE_ID;
    pdu->RRC_connection_state = RRC_connection_state;
    pdu->input_numbers = input_numbers;
    return pdu;
}

void free_LTE_ENB_RRC_PDU(LTE_ENB_RRC_PDU_T* pdu) {
    if (pdu) {
        free(pdu->input_numbers);
        free(pdu);
    }
}

int main() {
    // Get the number of input numbers from standard input
    int num_inputs;
    printf("Enter the number of floating-point numbers: ");
    scanf("%d", &num_inputs);

    // Allocate memory for the input numbers and read them from standard input
    float* inputs = (float*) malloc(sizeof(float) * num_inputs);
    if (!inputs) {
        fprintf(stderr, "Error: Unable to allocate memory for input numbers\n");
        return 1;
    }

    for (int i = 0; i < num_inputs; i++) {
        printf("Enter floating-point number %d: ", i + 1);
        scanf("%f", &inputs[i]);
    }

    // Calculate the mean and standard deviation of the input numbers
    float sum = 0.0, mean, std_dev;
    for (int i = 0; i < num_inputs; i++) {
        sum += inputs[i];
    }
    mean = sum / num_inputs;

    sum = 0.0;
    for (int i = 0; i < num_inputs; i++) {
        float diff = inputs[i] - mean;
        sum += diff * diff;
    }
    std_dev = sqrt(sum / num_inputs);

    // Create and populate a list of LTE_ENB_RRC_PDU structures with the input numbers
    int num_pdu = num_inputs / 32;
    if (num_inputs % 32 != 0) {
        num_pdu++;
    }

    LTE_ENB_RRC_PDU_T* pdu_list = (LTE_ENB_RRC_PDU_T*) malloc(sizeof(LTE_ENB_RRC_PDU_T) * num_pdu);
    if (!pdu_list) {
        fprintf(stderr, "Error: Unable to allocate memory for LTE_ENB_RRC_PDU list\n");
        return 1;
    }

    int pdu_index = 0;
    for (int i = 0; i < num_inputs; i += 32) {
        int remaining_inputs = num_inputs - i;
        if (remaining_inputs > 32) {
            remaining_inputs = 32;
        }

        LTE_ENB_RRC_PDU_T* pdu = allocate_LTE_ENB_RRC_PDU(i, 1, inputs + i);
        if (!pdu) {
            fprintf(stderr, "Error: Unable to allocate memory for LTE_ENB_RRC_PDU\n");
            return 1;
        }

        pdu->input_numbers = (float*) malloc(sizeof(float) * remaining_inputs);
        if (!pdu->input_numbers) {
            fprintf(stderr, "Error: Unable to allocate memory for input numbers\n");
            return 1;
        }

        memcpy(pdu->input_numbers, inputs + i, sizeof(float) * remaining_inputs);
        pdu_list[pdu_index++] = *pdu;
    }

    // Print the mean and standard deviation of the input numbers
    printf("Mean: %f\n", mean);
    printf("Standard Deviation: %f\n", std_dev);

    // Print the list of LTE_ENB_RRC_PDU structures with the input numbers
    for (int i = 0; i < num_pdu; i++) {
        printf("UE ID: %d, RRC Connection State: %d\n", pdu_list[i].UE_ID, pdu_list[i].RRC_connection_state);
        printf("PDU Data Tag: %d\n", pdu_list[i].PDU_data_tag.payload_size);
        for (int j = 0; j < 32; j++) {
            printf("%f ", pdu_list[i].input_numbers[j]);
        }
        putchar('\n');
    }

    // Free the memory allocated for the input numbers and the list of LTE_ENB_RRC_PDU structures
    free(inputs);
    for (int i = 0; i < num_pdu; i++) {
        free_LTE_ENB_RRC_PDU(&pdu_list[i]);
    }
    free(pdu_list);

    return 0;
}
