void init_session_states(int num_sessions) {
    // Allocate memory for the array of sessions states
    session_states = (session_state_t **)malloc(num_sessions * sizeof(session_state_t *));
    if (!session_states) {
        perror("Memory allocation failed");
        exit(1);
    }

    // Initialize each session state with a valid session ID, UE identifier, and timestamp
    for (int i = 0; i < num_sessions; i++) {
        session_states[i] = (session_state_t *)malloc(sizeof(session_state_t));
        if (!session_states[i]) {
            perror("Memory allocation failed");
            exit(1);
        }
        session_states[i]->session_id = i;
        session_states[i]->ue_identifier = (char *)malloc(strlen("UE000000") + 1);
