void serialize(session_state_t *states, int num_states) {
    // Allocate memory for the serialized data
    unsigned char *serialized_data = (unsigned char *)malloc(num_states * sizeof(session_state_t));
    if (!serialized_data) {
        perror("Memory allocation failed");
        exit(1);
    }

    // Serialize each session state into the serialized data
    for (int i = 0; i < num_states; i++) {
        serialize_session_state(&serialized_data[i * sizeof(session_state_t)], states[i]);
    }

    // Write the serialized data to a file
    FILE *file = fopen("sessions.bin", "wb");
    if (!file) {
        perror("File open failed");
        exit(1);
    }
    fwrite(serialized_data, sizeof(unsigned char), num_states * sizeof(session_state_t), file);
    fclose(file);
}

// Deserializes an array of custom data structures from a binary format for persistent storage
void deserialize(session_state_t **states) {
    // Read the serialized data from a file
    FILE *file = fopen("sessions.bin", "rb");
    if (!file) {
        perror("File open failed");
        exit(1);
