    // Deserialize each session state from the serialized data
    for (int i = 0; i < num_sessions; i++) {
        deserialize_session_state(&serialized_data[i * sizeof(session_state_t)], states[i]);
    }
}

// Serializes a single session state into a binary format
void serialize_session_state(unsigned char *buf, session_state_t *state) {
    // Serialize the session ID
    buf[0] = (state->session_id >> 24) & 0xFF;
    buf[1] = (state->session_id >> 16) & 0xFF;
    buf[2] = (state->session_id >> 8) & 0xFF;
    buf[3] = state->session_id & 0xFF;

    // Serialize the UE identifier
    strcpy((char *)&buf[4], state->ue_identifier);

    // Serialize the number of events
    buf[sizeof(int) + 4] = (state->num_events >> 24) & 0xFF;
    buf[sizeof(int) + 5] = (state->num_events >> 16) & 0xFF;
    buf[sizeof(int) + 6] = (state->num_events >> 8) & 0xFF;
    buf[sizeof(int) + 7] = state->num_events & 0xFF;

    // Serialize the timestamp for each event
    for (int i = 0; i < state->num_events; i++) {
        buf[sizeof(int) * (i + 2) + 8] = (state->timestamp[i] >> 24) & 0xFF;
        buf[sizeof(int) * (i + 2) + 9] = (state->timestamp[i] >> 16) & 0xFF;
        buf[sizeof(int) * (i + 2) + 10] = (state->timestamp[i] >> 8) & 0xFF;
        buf[sizeof(int) * (i + 2) + 11] = state->timestamp[i] & 0xFF;
    }
}

// Deserializes a single session state from a binary format
void deserialize_session_state(unsigned char *buf, session_state_t *state) {
    // Deserialize the session ID
    state->session_id = (buf[0] << 24) | (buf[1] << 16) | (buf[2] << 8) | buf[3];

    // Deserialize the UE identifier
    strcpy(state->ue_identifier, (char *)&buf[4]);

    // Deserialize the number of events
    state->num_events = (buf[sizeof(int) + 4] << 24) | (buf[sizeof(int) + 5] << 16) | (buf[sizeof(int) + 6] << 8) | buf[sizeof(int) + 7];

    // Deserialize the timestamp for each event
    for (int i = 0; i < state->num_events; i++) {
        state->timestamp[i] = (buf[sizeof(int) * (i + 2) + 8] << 24) | (buf[sizeof(int) * (i + 2) + 9] << 16) | (buf[sizeof(int) * (i + 2) + 10] << 8) | buf[sizeof(int) * (i + 2) + 11];
    }
}

// Frees the memory allocated for an array of custom data structures
void free_states(session_state_t **states) {
    // Free the memory allocated for each session state
    for (int i = 0; i < num_sessions; i++) {
        free(states[i]);
    }

    // Free the memory allocated for the array of session states
    free(states);
}

// Updates a single session state by adding a new event with the given timestamp
void update_session_state(session_state_t *state, int timestamp) {
    // Add the new event to the list of events
    state->num_events++;

    // Update the timestamp for the new event
    state->timestamp[state->num_events - 1] = timestamp;
}

// Prints a single session state to the console
void print_session_state(session_state_t *state) {
    printf("Session ID: %d\n", state->session_id);
    printf("UE identifier: %s\n", state->ue_identifier);
    printf("Number of events: %d\n", state->num_events);

    // Print the timestamp for each event
    for (int i = 0; i < state->num_events; i++) {
        printf("Event %d: Timestamp %d\n", i + 1, state->timestamp[i]);
    }
}

// Prints an array of custom data structures to the console
void print_states(session_state_t **states) {
    for (int i = 0; i < num_sessions; i++) {
        printf("Session %d:\n", i + 1);
        print_session_state(states[i]);
    }
}
