void add_new_message(int user_id, int session_id, char *message) {
    // Check if the user and session IDs are valid
    if (user_id < 0 || session_id < 0) {
        return;
    }

    // Lock the list of UserSessions to prevent race conditions
    pthread_mutex_lock(&sessions_mutex);

    // Check if the user has an existing session
    bool user_has_session = false;
    for (int i = 0; i < num_users && !user_has_session; i++) {
        UserSession *session = sessions[i];
        if (session->user_id == user_id) {
            // Add the new message to the existing session
            session->message_id++;
            char *new_message = malloc(strlen(message) + 1);
            strcpy(new_message, message);
            session->messages[session->message_id] = new_message;
            user_has_session = true;
        }
    }

    // If the user does not have an existing session, create a new one
    if (!user_has_session) {
        UserSession *new_session = malloc(sizeof(UserSession));
        new_session->user_id = user_id;
        new_session->message_id = 0;
        char *new_message = malloc(strlen(message) + 1);
        strcpy(new_message, message);
        new_session->messages[0] = new_message;
