                // Retry the API call with backoff and jitter
                int backoff = rand() % 1000 + 1; // Random delay between 1-1000ms
                sleep(backoff);
                session->api_failed = false;
            }
        } else {
            service_available = true;
        }
    }

    // Unlock the list of UserSessions to allow other threads to access it
    pthread_mutex_unlock(&sessions_mutex);

    if (!service_available) {
