// Define function to process log file and compute average
void processLogFile(char* filename) {
    // Open log file for reading
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    // Initialize list to store processed entries
    NFAPI_CRC_INDICATION_PDU_T* entries = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (entries == NULL) {
        perror("Error allocating memory for log file entries");
        return;
    }

    // Read each line of the log file and extract RNTI and CRC_INDICATION_REL8_TAG
    int i = 0;
    while (fgets(fp) != NULL) {
        NFAPI_CRC_INDICATION_PDU_T entry;
        sscanf(line, "%d %d", &entry.RX_UE_INFORMATION_TAG, &entry.RNTI);
        entry.CRC_INDICATION_REL8_TAG = rand() % 2 ? 1 : 0;
        entries[i++] = entry;
    }

    // Compute average of RNTIs and append to each entry
    int numEntries = i - 1;
    for (int i = 0; i < numEntries; i++) {
        NFAPI_CRC_INDICATION_PDU_T* currEntry = &entries[i];
        float avgRNTI = currEntry->RNTI / numEntries;
        currEntry->RNTI = avgRNTI;
    }

    // Print largest integer in list
