// Define function to parse PNG file and add it to theme cache
void parsePNGFile(char* filename) {
    // Open PNG file for reading
    FILE* fp = fopen(filename, "rb");
    if (fp == NULL) {
        perror("Error opening PNG file");
        return;
    }

    // Read contents of PNG file into memory
    fseek(fp, 0, SEEK_END);
    long fileSize = ftell(fp);
    rewind(fp);
    unsigned char* buffer = malloc(fileSize);
    if (buffer == NULL) {
        perror("Error allocating memory for PNG file");
        return;
    }
    fread(buffer, 1, fileSize, fp);

    // Close PNG file
    fclose(fp);

    // Add parsed PNG to theme cache
    addToThemeCache(filename, buffer, fileSize);
}

// Define function to add parsed PNG to theme cache
void addToThemeCache(char* filename, unsigned char* buffer, long fileSize) {
    // Check if cache root directory is set
    if (cacheRoot == NULL) {
        printf("Default theme directory not set. Cannot add PNG to cache.\n");
        return;
    }

    // Create new entry for parsed PNG in theme cache
    ThemeCacheEntry* newEntry = malloc(sizeof(ThemeCacheEntry));
    if (newEntry == NULL) {
        perror("Error allocating memory for theme cache entry");
        return;
    }
    strcpy(newEntry->filename, filename);
    newEntry->buffer = buffer;
    newEntry->fileSize = fileSize;

    // Add new entry to front of theme cache list
    ThemeCacheEntry* head = NULL;
    if (cacheRoot != NULL) {
        head = cacheRoot;
    }
    newEntry->next = head;
    cacheRoot = newEntry;
}

// Define function to clear expired cache entries
void clearExpiredEntries() {
    // Check for existing cached PNG files
    if (cacheRoot == NULL) {
        return;
    }

    // Iterate through cache list and clear expired entries
    ThemeCacheEntry* curr = cacheRoot;
    while (curr != NULL) {
        if (curr->buffer != NULL && curr->fileSize > 0) {
            // Clear cached PNG file
            free(curr->buffer);
            curr->buffer = NULL;
            curr->fileSize = 0;
        }
        ThemeCacheEntry* temp = curr;
        curr = curr->next;
        free(temp);
    }
}

// Define function to check for existing cached PNG files
void checkForCachedPNGs() {
    // Check if cache root directory is set
    if (cacheRoot == NULL) {
        return;
    }

    // Iterate through cache list and check for cached PNG files
    ThemeCacheEntry* curr = cacheRoot;
    while (curr != NULL) {
        // Check if PNG file is still in cache
        if (curr->buffer == NULL || curr->fileSize <= 0) {
            // Parse PNG file and add it to cache
            parsePNGFile(curr->filename);
        }
        ThemeCacheEntry* temp = curr;
        curr = curr->next;
        free(temp);
    }
}
