    int attempts = 0;
    while (attempts < MAX_RETRY_ATTEMPTS) {
        if (checkForUpdates()) {
            return true;
        } else {
            sleep(RETRY_DELAY_MIN + (rand() % RETRY_DELAY_MAX)); // Random delay between retries
            attempts++;
        }
