    } else if (networkLoad < 0.2) {
        newSize /= 0.7;
    }

    // Ensure the new size is within the acceptable range
    return min(max(newSize, MIN_NEIGHBOR_CELL_LIST_SIZE), MAX_NEIGHBOR_CELL_LIST_SIZE);
}

void adjustNeighborCellListSize(NetworkInterfaceConfig* config) {
