#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>
#include <stdint.h>

// Define the data structure to hold the list of NFAPI_CRC_INDICATION_PDU_T structures
struct NFAPIDynamicList {
    struct NFAPI_CRC_INDICATION_PDU_T* entries; // Array of pointers to the list entries
    size_t count; // Number of elements in the list
    pthread_mutex_t mutex; // Mutex for synchronizing access to the list
};

// Define the function to add a new entry to the list, taking into account the frequency threshold and grace period.
// The function returns 0 on success or a negative value on failure.
int nfapi_crc_indication_list_add(struct NFAPIDynamicList* list, uint16_t rnti, uint8_t crcflag) {
    // Check if the entry already exists in the list
    for (size_t i = 0; i < list->count; i++) {
        if (list->entries[i].rnti == rnti) {
            return -1; // Entry already exists, cannot add it again
        }
    }

    // Check if the frequency threshold is exceeded for this RNTI
    uint32_t current_count = 0;
    for (size_t i = 0; i < list->count; i++) {
        if (list->entries[i].rnti == rnti) {
            current_count++;
        }
    }
    if (current_count >= FREQUENCY_THRESHOLD) {
        return -2; // Frequency threshold exceeded, cannot add new entry
    }

    // Add the new entry to the list
    struct NFAPI_CRC_INDICATION_PDU_T* new_entry = malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
    if (!new_entry) {
        return -3; // Memory allocation failed, cannot add entry
    }
    new_entry->rnti = rnti;
    new_entry->crcflag = crcflag;
    list->entries = realloc(list->entries, (list->count + 1) * sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
    if (!list->entries) {
        free(new_entry);
        return -3; // Memory allocation failed, cannot add entry
    }
    list->entries[list->count++] = new_entry;

    // Clean up inactive entries periodically according to the grace period
    if (list->count > INACTIVE_ENTRY_GRACE_PERIOD) {
        for (size_t i = 0; i < list->count - INACTIVE_ENTRY_GRACE_PERIOD; i++) {
            if (list->entries[i].crcflag == CRCFLAG_INACTIVE) {
                free(list->entries[i]);
                memmove(&list->entries[i], &list->entries[i + 1], (list->count - i - 1) * sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
                list->count--;
            }
        }
    }

    return 0; // Successfully added new entry
}

// Define the function to remove an existing entry from the list
// The function returns 0 on success or a negative value on failure.
int nfapi_crc_indication_list_remove(struct NFAPIDynamicList* list, uint16_t rnti) {
    // Find the index of the entry to remove
    size_t index = 0;
    for (size_t i = 0; i < list->count; i++) {
        if (list->entries[i].rnti == rnti) {
            index = i;
            break;
        }
    }
    if (index >= list->count) {
        return -1; // Entry not found, cannot remove it
    }

    // Remove the entry from the list and free its memory
    struct NFAPI_CRC_INDICATION_PDU_T* removed_entry = list->entries[index];
    memmove(&list->entries[index], &list->entries[index + 1], (list->count - index - 1) * sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
    list->count--;
    free(removed_entry);

    // Clean up inactive entries periodically according to the grace period
    if (list->count > INACTIVE_ENTRY_GRACE_PERIOD) {
        for (size_t i = 0; i < list->count - INACTIVE_ENTRY_GRACE_PERIOD; i++) {
            if (list->entries[i].crcflag == CRCFLAG_INACTIVE) {
                free(list->entries[i]);
                memmove(&list->entries[i], &list->entries[i + 1], (list->count - i - 1) * sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
                list->count--;
            }
        }
    }

    return 0; // Successfully removed entry
}

// Define the function to update CRCFLAG for all entries in the list that match a certain RNTI and set them to a specific value
// The function returns the number of updated entries on success or a negative value on failure.
int nfapi_crc_indication_list_update(struct NFAPIDynamicList* list, uint16_t rnti, CRCFLAG crcflag) {
    // Find all indices of the matching RNTIs
    size_t index_start = 0;
    while (index_start < list->count && list->entries[index_start].rnti != rnti) {
        index_start++;
    }
    if (index_start >= list->count) {
        return -1; // No matching RNTIs found, cannot update CRCFLAG
    }
    size_t index_end = index_start + 1;
    while (index_end < list->count && list->entries[index_end].rnti == rnti) {
        index_end++;
    }
    if (index_end >= list->count) {
        return -2; // No matching RNTIs found, cannot update CRCFLAG
    }

    // Update CRCFLAG for all matching entries and free their memory
    size_t updated_entries = 0;
    for (size_t i = index_start; i < index_end; i++) {
        list->entries[i].crcflag = crcflag;
        updated_entries++;
        if (list->entries[i].crcflag == CRCFLAG_INACTIVE) {
            free(list->entries[i]);
            memmove(&list->entries[i], &list->entries[i + 1], (list->count - i - 1) * sizeof(struct NFAPI_CRC_INDICATION_PDU));
            list->count--;
        }
    }

    return updated_entries; // Successfully updated CRCFLAG for all matching entries
}

// Define the function to iterate over the entries in the list and perform a specific action on each entry
// The function returns 0 on success or a negative value on failure.
int nfapi_crc_indication_list_iterate(struct NFAPIDynamicList* list, void (*action)(struct NFAPI_CRC_INDICATION_PDU*)) {
    for (size_t i = 0; i < list->count; i++) {
        action(&list->entries[i]);
    }
    return 0; // Successfully iterated over all entries
}

// Define the function to free the memory of the list and its elements
void nfapi_crc_indication_list_free(struct NFAPIDynamicList* list) {
    for (size_t i = 0; i < list->count; i++) {
        free(list->entries[i]);
    }
    free(list->entries);
    free(list);
}

int main() {
    struct NFAPIDynamicList* list = malloc(sizeof(struct NFAPIDynamicList));
    if (!list) {
        return -1; // Memory allocation failed, cannot create list
    }
    list->entries = NULL;
    list->count = 0;

    // Create some entries in the list
    nfapi_crc_indication_list_add(list, 100, CRCFLAG_ACTIVE);
    nfapi_crc_indication_list_add(list, 200, CRCFLAG_INACTIVE);
    nfapi_crc_indication_list_add(list, 300, CRCFLAG_ACTIVE);
    nfapi_crc_indication_list_add(list, 400, CRCFLAG_INACTIVE);
    nfapi_crc_indication_list_add(list, 500, CRCFLAG_ACTIVE);
    nfapi_crc_indication_list_add(list, 600, CRCFLAG_INACTIVE);

