// Structure definitions
typedef struct NeighborCellInfo {
    int neighborId;
    // Other properties...
} NeighborCellInfo;

typedef struct NetworkInterfaceConfig {
    int interfaceId;
    size_t numNeighbors;
    NeighborCellInfo *neighbors;
    // SRS parameters...
} NetworkInterfaceConfig;

// Dynamic array implementation
typedef struct DynamicArray {
    size_t capacity;
    size_t count;
    NetworkInterfaceConfig **elements;
} DynamicArray;

// Function definitions

static void initNetworkInterfaceConfig(NetworkInterfaceConfig *config) {
    config->interfaceId = 0;
    config->numNeighbors = 0;
    config->neighbors = NULL;
    // Initialize SRS parameters...
}

// Create a new dynamic array with the specified capacity
static DynamicArray* createDynamicArray(size_t capacity) {
    DynamicArray *array = malloc(sizeof(DynamicArray));
    if (array == NULL) {
        return NULL;
    }
    array->capacity = capacity;
    array->count = 0;
    array->elements = calloc(capacity, sizeof(NetworkInterfaceConfig*));
    if (array->elements == NULL) {
        free(array);
        return NULL;
    }
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

// Add a new element to the dynamic array
static void addElementToDynamicArray(DynamicArray *array, NetworkInterfaceConfig *element) {
    pthread_mutex_lock(&array->mutex);
    if (array->count == array->capacity) {
        // Resize the array if necessary
        size_t newCapacity = array->capacity * 2;
        NetworkInterfaceConfig **newElements = realloc(array->elements, newCapacity * sizeof(NetworkInterfaceConfig*));
        if (newElements == NULL) {
            free(array->elements);
            pthread_mutex_unlock(&array->mutex);
            return;
        }
        array->elements = newElements;
        array->capacity = newCapacity;
    }
    // Add the element to the array
    array->elements[array->count++] = element;
    pthread_mutex_unlock(&array->mutex);
}

// Remove an element from the dynamic array
static void removeElementFromDynamicArray(DynamicArray *array, size_t index) {
    pthread_mutex_lock(&array->mutex);
    if (index >= array->count || index < 0) {
        pthread_mutex_unlock(&array->mutex);
        return;
    }
    // Move the last element to the removed position
    size_t lastIndex = array->count - 1;
    NetworkInterfaceConfig *lastElement = array->elements[lastIndex];
    array->elements[index] = lastElement;
    if (lastIndex != index) {
        array->elements[lastIndex] = NULL;
    }
    array->count--;
    pthread_mutex_unlock(&array->mutex);
}

// Find an element in the dynamic array
static NetworkInterfaceConfig* findElementInDynamicArray(DynamicArray *array, int interfaceId) {
    for (size_t i = 0; i < array->count; i++) {
        if (array->elements[i]->interfaceId == interfaceId) {
            return array->elements[i];
        }
    }
    return NULL;
}

// Initialize a dynamic array of NetworkInterfaceConfig structures
static void initNetworkInterfaceConfigs(size_t numEntries, size_t numNeighborsPerEntry, int srsTemplate[]) {
    DynamicArray *array = createDynamicArray(numEntries);
    if (array == NULL) {
        return;
    }
    for (size_t i = 0; i < numEntries; i++) {
        NetworkInterfaceConfig *config = malloc(sizeof(NetworkInterfaceConfig));
        if (config == NULL) {
            freeDynamicArray(array);
            return;
        }
        initNetworkInterfaceConfig(config);
        config->numNeighbors = numNeighborsPerEntry;
        config->neighbors = malloc(numNeighborsPerEntry * sizeof(NeighborCellInfo));
        if (config->neighbors == NULL) {
            free(config);
            removeElementFromDynamicArray(array, i);
            continue;
        }
        for (size_t j = 0; j < numNeighborsPerEntry; j++) {
            config->neighbors[j].neighborId = srsTemplate[2 * j];
            // Initialize other neighbor properties...
        }
        addElementToDynamicArray(array, config);
    }
}

// Function to track the number of active configurations and limit the total number of active configurations to 50 across all instances of the function being called simultaneously.
static int getNumActiveConfigurations() {
    return numActiveConfigurations;
}

// Function to query the current number of active configurations without affecting the internal state.
static size_t getNumEntriesInDynamicArray(DynamicArray *array) {
    return array->count;
}
```
This implementation uses a dynamic array to store the `NetworkInterfaceConfig` structures, which can grow or shrink in size as needed. The function `initNetworkInterfaceConfigs` takes the number of entries and the number of neighbors per entry as input parameters and initializes the dynamic array with the specified number of elements. It then populates each element with a unique interface ID, a list of neighbor cells, and SRS parameters based on the predefined template.

