#define RESOURCE_POOL_SIZE 1024
#define CONFIGURATION_LIST_SIZE 64
#define RESOURCE_PRIORITY_TREE_SIZE 64
#define HASH_TABLE_SIZE 512

typedef struct configuration {
    int id;
    char *name;
    void (*callback)();
} configuration;

typedef struct resource_priority {
    int priority;
    void *resource;
} resource_priority;

typedef struct hash_table_entry {
    int key;
    void *value;
} hash_table_entry;

struct resource_pool {
    configuration **configurations;
    resource_priority **resource_priorities;
    hash_table_entry **hash_table;
};

int create_configuration(int id, char *name, void (*callback)()) {
    // Check if the configuration exists already
    for (int i = 0; i < CONFIGURATION_LIST_SIZE; i++) {
        if (configurations[i].id == id) {
            return -1; // Configuration already exists
        }
    }

    // Allocate memory for the new configuration
    configuration *new_configuration = malloc(sizeof(configuration));
    new_configuration->id = id;
    new_configuration->name = strdup(name);
    new_configuration->callback = callback;

    // Add the new configuration to the list of configurations
    configurations[configurations_count] = new_configuration;
    configurations_count++;

    return 0;
}

int create_resource(void *data, int configuration_id) {
    // Check if the resource exists already
    for (int i = 0; i < RESOURCE_POOL_SIZE; i++) {
        if (resources[i].data == data) {
            return -1; // Resource already exists
        }
    }

    // Allocate memory for the new resource
    resource *new_resource = malloc(sizeof(resource));
    new_resource->data = data;
    new_resource->configuration_id = configuration_id;

    // Add the new resource to the pool
    resources[resources_count] = new_resource;
    resources_count++;

    return 0;
}

void *get_resource(int id) {
    for (int i = 0; i < RESOURCE_POOL_SIZE; i++) {
        if (resources[i].id == id) {
            return resources[i].data;
        }
    }

    return NULL;
}

