    for (int i = 0; i < CONFIGURATION_LIST_SIZE; i++) {
        if (configurations[i].configuration_id == configuration_id) {
            return configurations[i];
        }
    }

    return NULL;
}

void update_resource_priorities() {
    // Update the resource priorities based on the current state of the resources
    for (int i = 0; i < RESOURCE_POOL_SIZE; i++) {
        if (resources[i].data) {
            resource_priority *resource_priority = malloc(sizeof(resource_priority));
            resource_priority->priority = calculate_priority(resources[i]);
            resource_priority->resource = resources[i];

            // Add the new resource priority to the tree
            resource_priorities[resource_priorities_count] = resource_priority;
            resource_priorities_count++;
        }
    }
}

int calculate_priority(void *resource) {
    // Calculate the priority of a given resource based on its current state and other factors
    int priority = 0;

    for (int i = 0; i < RESOURCE_POOL_SIZE; i++) {
        if (resources[i].data == resource) {
            priority = resources[i].priority;
        }
    }

    return priority;
}

void *get_resource_by_priority(int priority) {
    // Return the resource with the highest priority that matches the given priority
    for (int i = 0; i < RESOURCE_POOL_SIZE; i++) {
        if (resources[i].data && resources[i].priority == priority) {
            return resources[i];
        }
    }

    return NULL;
}

void *get_resource_by_id(int id) {
    // Return the resource with the given ID
    for (int i = 0; i < RESOURCE_POOL_SIZE; i++) {
        if (resources[i].data && resources[i].id == id) {
            return resources[i];
        }
    }

    return NULL;
}

