    for (int i = 0; i < CONFIGURATION_LIST_SIZE; i++) {
        if (configurations[i].id == id) {
            return configurations[i];
        }
    }

    return NULL;
}

void delete_resource(void *resource) {
    // Free the memory of a given resource
    for (int i = 0; i < RESOURCE_POOL_SIZE; i++) {
        if (resources[i].data == resource) {
            free(resources[i]);
            resources[i] = NULL;
        }
    }
}

