    printf("Error: Invalid number of UE instances.\n");
    return NULL;
  }

  // Allocate memory for the array of structures
  NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);
  if (!array) {
    printf("Error: Memory allocation failed.\n");
    return NULL;
  }

  // Initialize the array with random CRCFLAG values
  for (int i = 0; i < N; i++) {
    array[i].RNTI = i + 1; // Assign unique RNTI identifier for each UE instance
    array[i].CRCFLAG = rand() % 256; // Generate random CRCFLAG value for each UE instance
  }

  return array;
}

// Define the function to process incoming radio signal data and verify CRC indications using a predefined checksum function
int process_data(NFAPI_CRC_INDICATION_PDU_T* array, int N) {
  // Check if N is valid and positive
  if (N <= 0 || N > 10000) {
    printf("Error: Invalid number of UE instances.\n");
    return -1;
  }

  // Initialize the checksum value to zero
  uint32_t checksum = 0;

  // Process each UE instance in the array and verify CRC indications
  for (int i = 0; i < N; i++) {
    if (array[i].CRCFLAG == 0) {
      printf("Error: CRC flag is zero.\n");
      return -2;
    }
    checksum += array[i].CRCFLAG; // Calculate the checksum value for each UE instance
  }

  // Verify the integrity of the CRC indications using the predefined checksum function
  if (checksum != (uint32_t)(-1)) {
    printf("Error: Checksum error.\n");
    return -3;
  }

  return 0;
}

// Define the function to free memory allocated for an array of NFAPI_CRC_INDICATION_PDU_T structures
void free_array(NFAPI_CRC_INDICATION_PDU_T* array, int N) {
  // Check if N is valid and positive
  if (N <= 0 || N > 10000) {
    printf("Error: Invalid number of UE instances.\n");
    return;
  }

  // Free the memory allocated for the array of structures
  free(array);
}
