#include <stdlib.h>
#include <string.h>
#include <stdio.h>

typedef struct MAC_RX_FRAME_T {
    PHY_RX_STATS *stats;
    RX_QOS_PARAMETERS *qos;
    float value;
} MAC_RX_FRAME_T;

void process_stream(int sock) {
    size_t capacity = 16; // initial capacity of the linked list (power of 2)
    size_t length = 0;
    MAC_RX_FRAME_T *frames = malloc(sizeof(MAC_RX_FRAME_T) * capacity);
    if (!frames) {
        fprintf(stderr, "Failed to allocate memory for frames\n");
        return;
    }

    // read floating-point numbers from the socket and store them in the linked list
    while (1) {
        float value;
        size_t n = recv(sock, &value, sizeof(float), 0);
        if (n < 0) {
            fprintf(stderr, "Failed to read from socket\n");
            break;
        } else if (n == 0) {
            // end of stream reached
            break;
        }

        // check if the linked list needs to be reallocated
        if (length >= capacity - 1) {
            capacity *= 2;
            frames = realloc(frames, sizeof(MAC_RX_FRAME_T) * capacity);
            if (!frames) {
                fprintf(stderr, "Failed to allocate memory for frames\n");
                break;
            }
        }

        // store the received value and adjust the stats accordingly
        frames[length].value = value;
        frames[length].stats->BER_ESTIMATE += value / 10.0;
        frames[length].stats->SNR_ESTIMATES += value / 20.0;
        length++;
    }

    // free the memory allocated for the linked list when it is no longer needed
    free(frames);
}
```
In this code, `process_stream` is a function that reads floating-point numbers from a network socket and stores them in a dynamically allocated linked list of `MAC_RX_FRAME_T` structures. The linked list starts with an initial capacity of 16 (a power of 2) and is doubled each time it needs to be reallocated.

The function reads floating-point numbers from the socket using `recv` and stores them in the linked list along with a valid `PHY_RX_STATS` and `RX_QOS_PARAMETERS` structure for each node. The `BER_ESTIMATE` and `SNR_ESTIMATES` fields within the `PHY_RX_STATS` structures are updated based on the stored values.

If an error occurs while reading from the socket or reallocating memory, the function exits with a message printed to stderr. Otherwise, it continues reading and storing floating-point numbers until the end of the stream is reached or an error occurs.

When the linked list is no longer needed, its memory is freed using `free`.']

