// Struct to represent sensor reading data
typedef struct {
    int temperature;
    float humidity;
    char* identifier;
} sensor_reading;

// Function to generate unique sensor identifiers based on a provided base string and numeric offset
void generate_identifier(char* base, int offset) {
    // Create a buffer for the generated identifier
    char identifier[10];
    // Copy the base string into the buffer
    strcpy(identifier, base);
    // Append the numeric offset to the end of the buffer
    sprintf(identifier + strlen(base), "%d", offset);
    // Return the generated identifier
    return identifier;
}

// Function to initialize a collection of sensor readings in parallel using multiple threads
void init_sensor_readings(int num_threads, int num_sensors, char* base) {
    // Create an array of thread handles
    pthread_t* threads = (pthread_t*)malloc(num_threads * sizeof(pthread_t));
    // Allocate memory for the sensor readings
    sensor_reading** sensor_readings = (sensor_reading**)calloc(num_sensors, sizeof(sensor_reading*));
    // Initialize each thread with a pointer to its respective sensor reading
    for (int i = 0; i < num_threads; i++) {
        int offset = i * num_sensors / num_threads;
        threads[i] = pthread_create(&sensor_readings[offset], NULL, init_sensor_reading, (void*)generate_identifier(base, offset));
    }
    // Join each thread and free its resources
    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
        free(sensor_readings[i]);
    }
    // Free the thread handles
    free(threads);
}

// Function to initialize a single sensor reading
void* init_sensor_reading(void* args) {
    // Extract the identifier from the arguments
    char* identifier = (char*)args;
    // Allocate memory for the sensor reading
    sensor_reading* reading = (sensor_reading*)malloc(sizeof(sensor_reading));
    // Initialize the temperature and humidity values
    reading->temperature = 20;
    reading->humidity = 40.0f;
    // Allocate memory for the sensor identifier
    reading->identifier = (char*)malloc(strlen(identifier) + 1);
    strcpy(reading->identifier, identifier);
    return reading;
}
