// Define the data structure to hold the linked list of NFAPI_CRC_INDICATION_PDU_T structures
typedef struct NFAPIData {
  struct NFAPIData *next;
  RX_UE_INFORMATION_TAG rx_ue_information_tag;
  RNTI rnti;
  CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPIData;

// Define the linked list head pointer and size variable
NFAPIData *head = NULL;
size_t size = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; // Mutex for synchronizing access to the linked list

// Function to insert a new NFAPIData structure into the linked list
bool insertData(NFAPIData *data) {
  bool ret = true;

  // Acquire lock on the mutex before modifying the linked list
  pthread_mutex_lock(&lock);

  // Allocate memory for the new NFAPIData structure
  data = malloc(sizeof(NFAPIData));
  if (data == NULL) {
    LOG("Memory allocation failed!");
    ret = false;
  } else {
    // Initialize the fields of the new NFAPIData structure
    data->rx_ue_information_tag = RX_UE_INFORMATION_TAG_INIT;
    data->rnti = RNTI_INIT;
    data->crc_indication_rel8_tag = CRC_INDICATION_REL8_TAG_INIT;
    // Set the CRCFLAG to a randomly generated value
    data->crc_indication_rel8_tag.CRCFlag = rand();

    // Insert the new NFAPIData structure into the linked list
    if (head == NULL) {
      head = data;
    } else {
      head->next = data;
    }
    size++;
  }

  // Release lock on the mutex after modifying the linked list
  pthread_mutex_unlock(&lock);

  return ret;
}

// Function to remove an NFAPIData structure from the linked list
void removeData(NFAPIData *data) {
  // Acquire lock on the mutex before modifying the linked list
  pthread_mutex_lock(&lock);

  // Find the specified NFAPIData structure in the linked list and remove it
  if (head == data) {
    head = head->next;
  } else {
    for (NFAPIData *curr = head; curr != NULL && curr->next != data; curr = curr->next);
    if (curr != NULL) {
      curr->next = data->next;
    }
  }

  // Release lock on the mutex after modifying the linked list
  pthread_mutex_unlock(&lock);
}

// Function to clear the linked list and free all memory allocated for the NFAPIData structures
void clearData() {
  // Acquire lock on the mutex before modifying the linked list
  pthread_mutex_lock(&lock);

  // Free all memory allocated for the NFAPIData structures in the linked list
  while (head != NULL) {
    NFAPIData *curr = head;
    head = head->next;
    free(curr);
  }
  size = 0;

  // Release lock on the mutex after modifying the linked list
  pthread_mutex_unlock(&lock);
}

// Function to monitor the growth and usage of the linked list
void monitorData() {
  // Acquire lock on the mutex before accessing the linked list
  pthread_mutex_lock(&lock);

  // Print the size of the linked list and its contents
  LOG("Linked list size: %d", size);
  for (NFAPIData *curr = head; curr != NULL; curr = curr->next) {
    LOG("NFAPI data structure: RX_UE_INFORMATION_TAG=%u, RNTI=%u, CRCFLAG=%u", curr->rx_ue_information_tag, curr->rnti, curr->crc_indication_rel8_tag.CRCFlag);
  }

  // Release lock on the mutex after accessing the linked list
  pthread_mutex_unlock(&lock);
}
