Here is an example implementation of a C-based network configuration manager that dynamically handles a list of network interface configurations across multiple devices:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <errno.h>

#define MAX_INTERFACES 10
#define MAX_CONFIG_LEN 256

struct network_interface {
    char name[IFNAMSIZ];
    struct in_addr addr;
    struct in_addr netmask;
    struct in_addr gateway;
    unsigned int mtu;
};

struct network_config {
    struct network_interface *interfaces;
    size_t num_interfaces;
};

struct device_status {
    char name[IFNAMSIZ];
    unsigned int ip_address;
    unsigned short port;
};

struct network_status {
    struct device_status *devices;
    size_t num_devices;
    struct timeval timestamp;
};

void add_interface(struct network_config *cfg, const char *name) {
    // Check if interface already exists
    for (size_t i = 0; i < cfg->num_interfaces; i++) {
        if (strcmp(cfg->interfaces[i].name, name) == 0) {
            return;
        }
    }

    // Add new interface to the configuration
    struct network_interface *new_iface = malloc(sizeof(struct network_interface));
    strcpy(new_iface->name, name);
    cfg->interfaces = realloc(cfg->interfaces, (cfg->num_interfaces + 1) * sizeof(struct network_interface));
    cfg->interfaces[cfg->num_interfaces++] = new_iface;
}

void remove_interface(struct network_config *cfg, const char *name) {
    // Find the interface to remove
    size_t i = 0;
    for (; i < cfg->num_interfaces; i++) {
        if (strcmp(cfg->interfaces[i].name, name) == 0) {
            break;
        }
    }

    // Remove the interface from the configuration
    struct network_interface *removed_iface = cfg->interfaces[i];
    for (size_t j = i + 1; j < cfg->num_interfaces; j++) {
        cfg->interfaces[j - 1] = cfg->interfaces[j];
    }
    free(removed_iface);
    cfg->num_interfaces--;
}

void update_interface(struct network_config *cfg, const char *name, struct in_addr addr, struct in_addr netmask, struct in_addr gateway) {
    // Find the interface to update
    size_t i = 0;
    for (; i < cfg->num_interfaces; i++) {
        if (strcmp(cfg->interfaces[i].name, name) == 0) {
            break;
        }
    }

    // Update the interface's configuration
    struct network_interface *updated_iface = cfg->interfaces[i];
    updated_iface->addr = addr;
    updated_iface->netmask = netmask;
    updated_iface->gateway = gateway;
}

struct network_config *get_network_config(const char *interface) {
    // Create a new configuration struct
    struct network_config *cfg = malloc(sizeof(struct network_config));
    cfg->num_interfaces = 0;

    // Add all interfaces to the configuration
    for (size_t i = 0; i < MAX_INTERFACES; i++) {
        struct ifreq req;
        strcpy(req.ifr_name, interface);
        int fd = socket(AF_INET, SOCK_DGRAM, 0);
        ioctl(fd, SIOCGIFFLAGS, &req);
        if (req.ifr_flags & IFF_UP) {
            add_interface(cfg, req.ifr_name);
        }
    }

    return cfg;
}

struct network_status *get_network_status(const char *interface) {
    // Create a new status struct
    struct network_status *status = malloc(sizeof(struct network_status));
    status->num_devices = 0;

    // Get the current device status
    struct ifreq req;
    strcpy(req.ifr_name, interface);
    int fd = socket(AF_INET, SOCK_DGRAM, 0);
    ioctl(fd, SIOCGIFADDR, &req);
    unsigned int ip_address = inet_addr(req.ifr_addr);
    close(fd);

    // Add the current device status to the status struct
    struct device_status *new_device = malloc(sizeof(struct device_status));
    strcpy(new_device->name, interface);
    new_device->ip_address = ip_address;
    new_device->port = 0;
    status->devices = realloc(status->devices, (status->num_devices + 1) * sizeof(struct device_status));
    status->devices[status->num_devices++] = new_device;

    return status;
}

void update_network_config(const char *interface, struct network_config *cfg) {
    // Update the interface's configuration in the configuration struct
    for (size_t i = 0; i < cfg->num_interfaces; i++) {
        if (strcmp(cfg->interfaces[i].name, interface) == 0) {
            update_interface(cfg, interface, cfg->interfaces[i].addr, cfg->interfaces[i].netmask, cfg->interfaces[i].gateway);
        }
    }
}

void apply_network_config(struct network_config *cfg) {
    // Apply the configuration to all interfaces
    for (size_t i = 0; i < cfg->num_interfaces; i++) {
        struct ifreq req;
        strcpy(req.ifr_name, cfg->interfaces[i].name);
        int fd = socket(AF_INET, SOCK_DGRAM, 0);
        ioctl(fd, SIOCSIFADDR, &req);
        close(fd);
    }
}

void update_network_status(struct network_config *cfg) {
    // Update the status of all interfaces
    for (size_t i = 0; i < cfg->num_interfaces; i++) {
        struct ifreq req;
        strcpy(req.ifr_name, cfg->interfaces[i].name);
        int fd = socket(AF_INET, SOCK_DGRAM, 0);
        ioctl(fd, SIOCGIFFLAGS, &req);
        if (req.ifr_flags & IFF_UP) {
            struct network_status *status = get_network_status(cfg->interfaces[i].name);
            update_device_status(status, req.ifr_addr);
            free(status);
        }
    }
}

void update_device_status(struct network_status *status, struct in_addr addr) {
    // Update the status of a device
    for (size_t i = 0; i < status->num_devices; i++) {
        if (strcmp(status->devices[i].name, addr.ifr_name) == 0) {
            status->devices[i].port = 0;
            break;
        }
    }
}

void apply_network_status(struct network_status *status) {
    // Apply the status of all interfaces
    for (size_t i = 0; i < status->num_devices; i++) {
        struct ifreq req;
        strcpy(req.ifr_name, status->devices[i].name);
        int fd = socket(AF_INET, SOCK_DGRAM, 0);
        ioctl(fd, SIOCSIFADDR, &req);
        close(fd);
    }
}

void free_network_config(struct network_config *cfg) {
    // Free the memory of a configuration struct
    for (size_t i = 0; i < cfg->num_interfaces; i++) {
        free(cfg->interfaces[i].name);
        free(cfg->interfaces[i].addr);
        free(cfg->interfaces[i].netmask);
        free(cfg->interfaces[i].gateway);
    }
    free(cfg->interfaces);
    free(cfg);
}

void free_network_status(struct network_status *status) {
    // Free the memory of a status struct
    for (size_t i = 0; i < status->num_devices; i++) {
        free(status->devices[i].name);
        free(status->devices[i].ip_address);
        free(status->devices[i].port);
    }
    free(status->devices);
    free(status);
}"]

