// Function to initialize log messages with a specific format
void init_log(int range, const char *format) {
    // Allocate memory for the offset array
    long *offsets = (long *)malloc(range * sizeof(long));
    if (!offsets) {
        printf("Error: Failed to allocate memory for offsets\n");
        return;
    }

    // Initialize the offset array with random values
    for (int i = 0; i < range; i++) {
        offsets[i] = rand() % (range + 1);
    }

    // Allocate memory for the key array and initialize it with random values
    int *keys = (int *)malloc(range * sizeof(int));
    if (!keys) {
        printf("Error: Failed to allocate memory for keys\n");
        free(offsets);
        return;
    }

    for (int i = 0; i < range; i++) {
        keys[i] = rand() % (range + 1);
    }

    // Allocate memory for the record structures and initialize them with the random values
    Record *records = (Record *)malloc(range * sizeof(Record));
    if (!records) {
        printf("Error: Failed to allocate memory for records\n");
        free(keys);
        free(offsets);
        return;
    }

    for (int i = 0; i < range; i++) {
        records[i].key = keys[i];
        records[i].message = malloc(16 * sizeof(char));
        if (!records[i].message) {
            printf("Error: Failed to allocate memory for message\n");
            free(records);
            free(keys);
            free(offsets);
            return;
        }
        sprintf(records[i].message, format, records[i].key);
    }

    // Integrate with an external logging library to write log messages to a file
    FILE *log_file = fopen("log.txt", "w");
    if (!log_file) {
        printf("Error: Failed to open log file\n");
        free(records);
        free(keys);
        free(offsets);
        return;
    }

    // Implement thread-safe initialization of log messages to avoid race conditions in a multi-threaded environment
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    for (int i = 0; i < range; i++) {
        pthread_mutex_lock(&lock);
        fprintf(log_file, "%s\n", records[i].message);
        pthread_mutex_unlock(&lock);
    }

    // Handle memory allocation failures gracefully and provide a fallback mechanism to prevent application crashes
    if (!offsets || !keys || !records) {
        printf("Error: Memory allocation failed\n");
        free(records);
        free(keys);
        free(offsets);
        fclose(log_file);
        return;
    }

    // Provide a mechanism to deallocate all allocated memory when the function is called again to prevent memory leaks and ensure resource management best practices are followed
    free(records);
    free(keys);
    free(offsets);
    fclose(log_file);
}
