#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <stdbool.h>
#include <time.h>
#include <math.h>

// Define the NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    long offset;
    int key;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the metadata structure for each hash entry
typedef struct {
    int value;
    bool allocated;
} METADATA_T;

// Define the extended metadata structure for each hash entry
typedef struct {
    int extended_value;
    bool allocated;
} EXTENDED_METADATA_T;

// Define the doubly linked list node for free memory blocks
typedef struct {
    void* data;
    size_t size;
    struct Node* next;
    struct Node* prev;
} NODE_T;

// Define the hash table structure
typedef struct {
    int capacity; // Total number of entries in the hash table
    int size; // Current number of occupied entries in the hash table
    double load_factor; // Load factor of the hash table (0.75 by default)
    METADATA_T* metadata; // Array of metadata pointers for each hash entry
    EXTENDED_METADATA_T* extended_metadata; // Array of extended metadata pointers for each hash entry
    NODE_T* free_list; // Doubly linked list for free memory blocks
} HASH_TABLE_T;

// Define the custom hash function
unsigned long hash(int key) {
    return key % 10007 + 12345;
}

// Initialize and manage a dynamic collection of NFAPI_CRC_INDICATION_PDU_T structures
void initialize_nfapi_crc_indication(HASH_TABLE_T* table) {
    // Allocate memory for the hash tables and doubly linked list
    table->metadata = (METADATA_T*)calloc(table->capacity, sizeof(METADATA_T));
    table->extended_metadata = (EXTENDED_METADATA_T*)calloc(table->capacity, sizeof(EXTENDED_METADATA_T));
    table->free_list = NULL;

    // Initialize the load factor to 0.75 and the hash tables with empty metadata and extended metadata pointers
    table->load_factor = 0.75;
    for (int i = 0; i < table->capacity; ++i) {
        table->metadata[i].allocated = false;
        table->extended_metadata[i].allocated = false;
    }
}

// Insert a new record into the hash table
void insert(HASH_TABLE_T* table, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Generate a random int key for the record
    int key = rand() % 10000 + 1;

    // Check if the hash table is full and needs to be resized
    if (table->size >= table->capacity * table->load_factor) {
        resize(table, table->capacity * 2);
    }

    // Find the index of the empty slot in the hash table where the record will be inserted
    int index = find_empty_slot(table, key);

    // Insert the record into the hash table and set its metadata and extended metadata pointers to NULL
    table->metadata[index].value = key;
    table->extended_metadata[index].value = 0;
    table->metadata[index].allocated = true;
    table->extended_metadata[index].allocated = false;

    // Set the offset, RNTI, and CRC_INDICATION_REL8_TAG fields of the record
    pdu->offset = 0;
    pdu->rnti = 1;
    pdu->crc_indication_rel8_tag = {true};
}

// Find the index of the empty slot in the hash table where the record will be inserted
int find_empty_slot(HASH_TABLE_T* table, int key) {
    // Iterate through the hash table until an empty slot is found
    for (int i = 0; i < table->capacity; ++i) {
        if (!table->metadata[i].allocated) {
            return i;
        }
    }

    // If no empty slots are found, resize the hash table and try again
    resize(table, table->capacity * 2);
    return find_empty_slot(table, key);
}

// Resize the hash table to a new capacity
void resize(HASH_TABLE_T* table, int new_capacity) {
    // Allocate memory for the new metadata and extended metadata arrays
    METADATA_T* new_metadata = (METADATA_T*)calloc(new_capacity, sizeof(METADATA_T));
    EXTENDED_METADATA_T* new_extended_metadata = (EXTENDED_METADATA_T*)calloc(new_capacity, sizeof(EXTENDED_METADATA_T));

    // Copy the contents of the old metadata and extended metadata arrays to the new arrays
    for (int i = 0; i < table->capacity; ++i) {
        if (table->metadata[i].allocated) {
            new_metadata[i] = table->metadata[i];
            new_extended_metadata[i] = table->extended_metadata[i];
        }
    }

    // Free the old metadata and extended metadata arrays and set the new arrays as the hash tables' arrays
    free(table->metadata);
    free(table->extended_metadata);
    table->metadata = new_metadata;
    table->extended_metadata = new_extended_metadata;

    // Update the capacity of the hash table and resize the load factor to 0.75
    table->capacity = new_capacity;
    table->load_factor = 0.75;
}

// Search for a record in the hash table by its key
NFAPI_CRC_INDICATION_PDU_T* search(HASH_TABLE_T* table, int key) {
    // Find the index of the record with the specified key
    int index = find_index(table, key);

    // If no such record exists, return NULL
    if (index == -1) {
        return NULL;
    }

    // Return a pointer to the found record
    return &table->metadata[index].value;
}

// Find the index of the record with the specified key in the hash table
int find_index(HASH_TABLE_T* table, int key) {
    // Iterate through the hash table until the record with the specified key is found or all slots have been searched
    for (int i = 0; i < table->capacity; ++i) {
        if (table->metadata[i].allocated && table->metadata[i].value == key) {
            return i;
        }
    }

    // If no such record exists, return -1
    return -1;
}

// Remove a record from the hash table by its key
void remove(HASH_TABLE_T* table, int key) {
    // Find the index of the record with the specified key
    int index = find_index(table, key);

    // If no such record exists, do nothing
    if (index == -1) {
        return;
    }

    // Free the metadata and extended metadata pointers of the removed record
    table->metadata[index].allocated = false;
    table->extended_metadata[index].allocated = false;

    // Update the size of the hash table and resize it if necessary
    --table->size;
    if (table->size < table->capacity * 0.5 && table->capacity > 1) {
        resize(table, table->capacity / 2);
    }
}

// Update the offset, RNTI, and CRC_INDICATION_REL8_TAG fields of a record in the hash table by its key
void update(HASH_TABLE_T* table, int key) {
    // Find the index of the record with the specified key
    int index = find_index(table, key);

    // If no such record exists, do nothing
    if (index == -1) {
        return;
    }

    // Update the fields of the found record
    table->metadata[index].value = 0;
    table->extended_metadata[index].value = 0;
}

// Print the contents of the hash table
void print(HASH_TABLE_T* table) {
    // Iterate through the hash table and print each record
    for (int i = 0; i < table->capacity; ++i) {
        if (table->metadata[i].allocated) {
            printf("Record %d: ", i);
            printf("Offset = %d, RNTI = %d, CRC_INDICATION_REL8_TAG = %d\n", table->metadata[i].value.offset, table->metadata[i].value.rnti, table->metadata[i].value.crc_indication_rel8_tag);
        }
    }
}

int main() {
    // Create a new hash table with an initial capacity of 10
    HASH_TABLE_T* table = create(10);

    // Insert some records into the hash table
    insert(table, 5, 1);
    insert(table, 10, 2);
    insert(table, 15, 3);

    // Search for a record in the hash table by its key
    NFAPI_CRC_INDICATION_PDU* pdu = search(table, 5);

    // Update the offset and CRC_INDICATION_REL8_TAG fields of a record in the hash table by its key
    update(table, 10);

    // Remove a record from the hash table by its key
    remove(table, 15);

    // Print the contents of the hash table
    print(table);

    // Free the memory allocated for the hash table
    destroy(table);

    return 0;
}']

