#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <limits.h>
#include <assert.h>

// Define constants for the CRC seed and range of valid integers
#define CRC_SEED 0xDEADBEEF
#define MIN_INT -1000000000
#define MAX_INT 1000000000

// Define structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    uint32_t rx_ue_information_tag;
    uint32_t rnti;
    uint8_t crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define function to validate input integers and store in array
int validate_input(const int* inputs, size_t num_inputs) {
    // Allocate memory for the validated integer array
    int* valid_inputs = (int*)malloc(sizeof(int) * num_inputs);
    if (!valid_inputs) {
        printf("Error: unable to allocate memory for validated input integers\n");
        return -1;
    }

    // Validate each input integer and store in array
    size_t valid_count = 0;
    for (size_t i = 0; i < num_inputs; ++i) {
        if (inputs[i] >= MIN_INT && inputs[i] <= MAX_INT) {
            valid_inputs[valid_count++] = inputs[i];
        } else {
            printf("Error: input integer %d is out of range\n", inputs[i]);
        }
    }

    // Allocate memory for the NFAPI_CRC_INDICATION_PDU_T structures
    size_t num_structs = valid_count;
    NFAPI_CRC_INDICATION_PDU_T* crc_indications = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_structs);
    if (!crc_indications) {
        printf("Error: unable to allocate memory for CRC indication structures\n");
        free(valid_inputs);
        return -1;
    }

    // Populate the NFAPI_CRC_INDICATION_PDU_T structures with validated inputs
    for (size_t i = 0; i < num_structs; ++i) {
        crc_indications[i].rx_ue_information_tag = i + 1;
        crc_indications[i].rnti = valid_inputs[i];
        crc_indications[i].crc_indication_rel8_tag = generate_crc(valid_inputs[i]);
    }

    // Free memory for the validated input array and return the CRC indication structures
    free(valid_inputs);
    return crc_indications;
}

// Define function to generate CRC value based on seed and input integer
uint8_t generate_crc(int input) {
    uint32_t crc = CRC_SEED ^ (uint32_t)input;
    for (size_t i = 0; i < 16; ++i) {
        if (crc & 1) {
            crc = (crc >> 1) ^ 0x8C416D99;
        } else {
            crc = (crc >> 1);
        }
    }
    return (uint8_t)(crc & 0xFF);
}

// Define function to find and print the largest integer in an array
int find_largest(const int* inputs, size_t num_inputs) {
    // Check for invalid input conditions
    if (!inputs || num_inputs == 0) {
        printf("Error: invalid input\n");
        return -1;
    }

    // Initialize variables to track largest integer and its index
    int largest = INT_MIN;
    size_t largest_index = 0;

    // Iterate through the input array and find the largest integer
    for (size_t i = 0; i < num_inputs; ++i) {
        if (inputs[i] > largest) {
            largest = inputs[i];
            largest_index = i;
        }
    }

    // Print the largest integer and its index
    printf("Largest integer: %d\n", largest);
    printf("Index of largest integer: %zu\n", largest_index);

    return 0;
}

