    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} NFAPI_CRC_INDICATION_LIST_T;

// Define the function to add a new CRC indication to the list
bool nfapi_crc_indication_add(NFAPI_CRC_INDICATION_LIST_T *list, RX_UE_INFORMATION_TAG rx_ue_information, RNTI rnti, CRC_INDICATION_REL8_TAG crc_indication_rel8) {
    // Check if the list is full
    if (list->count == list->capacity) {
        return false;
    }

    // Allocate memory for the new CRC indication
    NFAPI_CRC_INDICATION_PDU_T *new_crc_indication = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_crc_indication) {
        return false;
    }

    // Initialize the new CRC indication
    new_crc_indication->rx_ue_information = rx_ue_information;
    new_crc_indication->rnti = rnti;
    new_crc_indication->crc_indication_rel8 = crc_indication_rel8;

    // Add the new CRC indication to the list
    pthread_mutex_lock(&list->lock);
    list->data[list->count++] = new_crc_indication;
    pthread_mutex_unlock(&list->lock);

    return true;
}

// Define the function to update an existing CRC indication in the list
bool nfapi_crc_indication_update(NFAPI_CRC_INDICATION_LIST_T *list, RX_UE_INFORMATION_TAG rx_ue_information, RNTI rnti, CRC_INDICATION_REL8_TAG crc_indication_rel8) {
    // Find the existing CRC indication in the list
    size_t i;
    for (i = 0; i < list->count; ++i) {
        if (list->data[i]->rnti == rnti && list->data[i]->crc_indication_rel8.crc_flag == crc_indication_rel8.crc_flag) {
            break;
        }
    }

    // Check if the CRC indication was found in the list
    if (i == list->count) {
        return false;
    }

    // Update the existing CRC indication in the list
    pthread_mutex_lock(&list->lock);
    list->data[i]->rx_ue_information = rx_ue_information;
    list->data[i]->crc_indication_rel8 = crc_indication_rel8;
    pthread_mutex_unlock(&list->lock);

    return true;
}

// Define the function to remove a CRC indication from the list
bool nfapi_crc_indication_remove(NFAPI_CRC_INDICATION_LIST_T *list, RNTI rnti) {
    // Find the existing CRC indication in the list
    size_t i;
    for (i = 0; i < list->count; ++i) {
        if (list->data[i]->rnti == rnti) {
            break;
        }
    }

    // Check if the CRC indication was found in the list
    if (i == list->count) {
        return false;
    }

    // Remove the existing CRC indication from the list
    pthread_mutex_lock(&list->lock);
    memmove(list->data + i, list->data + i + 1, sizeof(*list->data));
    --list->count;
    pthread_mutex_unlock(&list->lock);

    return true;
}

// Define the function to filter the CRC indications in the list based on RNTI
NFAPI_CRC_INDICATION_PDU_T *nfapi_crc_indication_filter_rnti(NFAPI_CRC_INDICATION_LIST_T *list, RNTI rnti) {
    // Find the existing CRC indication in the list
    size_t i;
    for (i = 0; i < list->count; ++i) {
        if (list->data[i]->rnti == rnti) {
            break;
        }
    }

    // Check if the CRC indication was found in the list
    if (i == list->count) {
        return NULL;
    }

    // Return a subset of matching elements
    NFAPI_CRC_INDICATION_PDU_T *subset = malloc(sizeof(*subset));
    memcpy(subset, list->data + i, sizeof(*subset));
    return subset;
}

// Define the function to shuffle the CRC indications in the list randomly
void nfapi_crc_indication_shuffle(NFAPI_CRC_INDICATION_LIST_T *list) {
    // Allocate memory for the new CRC indication array
    NFAPI_CRC_INDICATION_PDU_T **new_data = malloc(sizeof(*new_data));
    if (!new_data) {
        return;
    }

    // Copy the contents of the old CRC indication array to the new one
    for (size_t i = 0; i < list->count; ++i) {
        new_data[i] = malloc(sizeof(*new_data));
        if (!new_data[i]) {
            free(new_data);
            return;
        }
        memcpy(new_data[i], list->data + i, sizeof(*new_data));
    }

    // Shuffle the new CRC indication array randomly
    srand(time(NULL));
    for (size_t i = 0; i < list->count; ++i) {
        size_t j = rand() % (list->count - i) + i;
        memcpy(list->data + i, new_data[j], sizeof(*new_data));
    }

    // Free the memory allocated for the new CRC indication array
    free(new_data);
}

