    bool enabled; // Whether SRS is enabled or not
    int srsBandwidth; // SRS bandwidth in Hz
    int srsSubcarrierSpacing; // SRS subcarrier spacing in Hz
} SRSConfig;

// Global variable to keep track of the number of network interfaces
int numInterfaces = 0;

// Function to initialize a dynamic array of NetworkInterfaceConfig structures
void initNetworkInterfaceConfigs(int capacity, int initialCapacity) {
    // Allocate memory for the dynamic array
    NetworkInterfaceConfig *configArray = (NetworkInterfaceConfig *)malloc(sizeof(NetworkInterfaceConfig) * capacity);
    if (!configArray) {
        fprintf(stderr, "Error: Failed to allocate memory for network interface configurations\n");
        exit(1);
    }

    // Initialize the dynamic array with default values
    for (int i = 0; i < capacity; i++) {
        configArray[i].interfaceId = -1;
        configArray[i].neighborCellInfoList = NULL;
        configArray[i].srsConfig.enabled = false;
        configArray[i].srsConfig.srsBandwidth = 0;
        configArray[i].srsConfig.srsSubcarrierSpacing = 0;
    }

    // If the initial capacity is exceeded, dynamically resize the list to accommodate more neighbors
    if (initialCapacity > capacity) {
        int newCapacity = initialCapacity * 2;
        NetworkInterfaceConfig *newArray = (NetworkInterfaceConfig *)realloc(configArray, sizeof(NetworkInterfaceConfig) * newCapacity);
        if (!newArray) {
            fprintf(stderr, "Error: Failed to resize network interface configuration array\n");
            exit(1);
        }
        configArray = newArray;
    }

    // Set the initial capacity of the dynamic array
    numInterfaces = initialCapacity;
}

// Function to add a network interface configuration
void addNetworkInterfaceConfig(int interfaceId, int cellId, float rssi, float rsrp) {
    NetworkInterfaceConfig *config = NULL;
    bool found = false;

    // Find an unused entry in the dynamic array
    for (int i = 0; i < numInterfaces; i++) {
        if (configArray[i].interfaceId == -1) {
            config = &configArray[i];
            found = true;
            break;
        }
    }

    // If no unused entry is found, resize the dynamic array to accommodate more neighbors
    if (!found) {
        numInterfaces++;
        NetworkInterfaceConfig *newArray = (NetworkInterfaceConfig *)realloc(configArray, sizeof(NetworkInterfaceConfig) * (numInterfaces + 1));
        if (!newArray) {
            fprintf(stderr, "Error: Failed to resize network interface configuration array\n");
            exit(1);
        }
        configArray = newArray;
        config = &configArray[numInterfaces - 1];
    }

    // Initialize the configuration with the provided values
    config->interfaceId = interfaceId;
    NeighborCellInfo *cellInfo = (NeighborCellInfo *)malloc(sizeof(NeighborCellInfo));
    cellInfo->cellId = cellId;
    cellInfo->rssi = rssi;
    cellInfo->rsrp = rsrp;
    config->neighborCellInfoList = cellInfo;
}

// Function to remove a network interface configuration
void removeNetworkInterfaceConfig(int interfaceId) {
    NetworkInterfaceConfig *config = NULL;

    // Find the entry in the dynamic array corresponding to the given interface ID
    for (int i = 0; i < numInterfaces; i++) {
        if (configArray[i].interfaceId == interfaceId) {
            config = &configArray[i];
            break;
        }
    }

    // If the entry is found, remove it from the dynamic array and free its memory
    if (config) {
        NetworkInterfaceConfig *newArray = (NetworkInterfaceConfig *)realloc(configArray, sizeof(NetworkInterfaceConfig) * (numInterfaces - 1));
        if (!newArray) {
            fprintf(stderr, "Error: Failed to resize network interface configuration array\n");
            exit(1);
        }
        configArray = newArray;
        numInterfaces--;
    }
}

// Function to update a network interface configuration with the provided values
void updateNetworkInterfaceConfig(int interfaceId, int cellId, float rssi, float rsrp) {
    NetworkInterfaceConfig *config = NULL;

    // Find the entry in the dynamic array corresponding to the given interface ID
    for (int i = 0; i < numInterfaces; i++) {
        if (configArray[i].interfaceId == interfaceId) {
            config = &configArray[i];
            break;
        }
    }

    // If the entry is found, update its values with the provided ones
    if (config) {
        NeighborCellInfo *cellInfo = (NeighborCellInfo *)malloc(sizeof(NeighborCellInfo));
        cellInfo->cellId = cellId;
        cellInfo->rssi = rssi;
        cellInfo->rsrp = rsrp;
        config->neighborCellInfoList = cellInfo;
    }
}

// Function to query the configuration for a specific network interface
void queryNetworkInterfaceConfig(int interfaceId, NetworkInterfaceConfig *config) {
    // Find the entry in the dynamic array corresponding to the given interface ID
    for (int i = 0; i < numInterfaces; i++) {
        if (configArray[i].interfaceId == interfaceId) {
            *config = configArray[i];
            break;
        }
    }
}
