    // Modify the SRS parameters based on a predefined template
    srsParams.srsSubcarrierSpacing = rand() % 10;
    srsParams.srsBandwidth = rand() % 500;
    srsParams.srsModOrder = rand() % 8;

    return srsParams;
}

// Function to generate a unique cell ID for the neighbor cell list
int generateUniqueCellId() {
    // Generate a random number between 1 and 2^32-1
    int cellId = rand() % (pow(2, 32) - 1);

    // Check if the generated cell ID is already in use
    while (isCellIdInUse(cellId)) {
        // If the cell ID is in use, generate a new one
        cellId = rand() % (pow(2, 32) - 1);
    }

    return cellId;
}

// Function to check if a given cell ID is already in use in the neighbor cell list
int isCellIdInUse(int cellId) {
    for (int i = 0; i < MAX_NEIGHBOR_CELLS; i++) {
        if (neighborCells[i].cellId == cellId) {
            return 1;
        }
    }

    return 0;
}
