    for (int i = 0; i < num_ints; ++i) {
        variance += pow(arr[i] - mean, 2);
    }
    variance /= num_ints - 1;
    double stddev = sqrt(variance);

    // Print the statistics
    printf("Number of disjoint pairs: %d\n", num_disjoint_pairs);
    printf("Average: %.2f\n", mean);
    printf("Standard deviation: %.2f\n", stddev);

    return 0;  // Return success code
}

int read_int_array(char *input, int *arr, int size) {
    // Read the integers from standard input and store them in an array
    int num_ints = 0;
    while (num_ints < size && scanf("%d", &arr[num_ints]) == 1) {
        ++num_ints;
    }
    if (num_ints > size) {
        // Return error code if there are too many integers in the input
        return -1;
    } else if (num_ints < size && num_ints != 0) {
        // Return error code if there are not enough integers in the input
        return -1;
    }
    return num_ints;
}

bool is_same_set(int a, int b) {
    // Check whether two elements are in the same set using the union-find data structure
    while (a != parent[a]) {
        a = parent[a];
    }
    while (b != parent[b]) {
        b = parent[b];
    }
    return a == b;
}

void union_sets(int a, int b) {
    // Merge the sets containing two elements using the union-find data structure
    if (rank[a] > rank[b]) {
        parent[b] = a;
    } else {
        parent[a] = b;
    }
}
