// Custom C function to handle duplicate neighbor IDs in the dynamic array of NetworkInterfaceConfig structures
void removeDuplicateNeighbors(vector<NetworkInterfaceConfig>& interfaces) {
    unordered_map<int, bool> seenIds;

    for (int i = 0; i < interfaces.size(); i++) {
        NetworkInterfaceConfig& interface = interfaces[i];
        vector<NeighborCellInfo>& neighbors = interface.neighbors;

        for (int j = 0; j < neighbors.size();) {
            NeighborCellInfo& neighbor = neighbors[j];

            if (seenIds.find(neighbor.neighborId) != seenIds.end()) {
                // Remove duplicate neighbor ID and update the index of remaining neighbors
                neighbors.erase(neighbors.begin() + j);

                for (int k = j; k < neighbors.size(); k++) {
                    neighbors[k].neighborId--;
                }
            } else {
