// Define the structs for storing offset and record information
struct offset {
    long offset;
    int *key;
};

struct record {
    int value;
};

// Define the command line options
static const char* short_options = "vro:h";
static const struct option long_options[] = {
    {"help", no_argument, 0, 'h'},
    {"verbose", no_argument, 0, 'v'},
    {"report", no_argument, 0, 'r'},
    {"output-file", required_argument, 0, 'o'},
    {0, 0, 0, 0}
};

// Define the functions for processing command line arguments and handling errors
void print_usage(char* progname) {
    printf("Usage: %s [-v] [-r] [-o output-file] input-file\n", progname);
}

void handle_error(const char* message, int errcode) {
    fprintf(stderr, "%s: %s\n", message, strerror(errcode));
    exit(1);
}

// Define the main function
int main(int argc, char** argv) {
    // Declare variables for command line arguments and options
    int c;
    char* output_file = NULL;
    int verbose = 0;
    int report = 0;

    // Parse the command line arguments and options
    while ((c = getopt_long(argc, argv, short_options, long_options, NULL)) != -1) {
        switch (c) {
            case 'h':
                print_usage(argv[0]);
                exit(0);
                break;
            case 'v':
                verbose = 1;
                break;
            case 'r':
                report = 1;
                break;
            case 'o':
                output_file = optarg;
                break;
            default:
                print_usage(argv[0]);
                exit(1);
        }
    }

    // Check if the input file is specified
    if (optind >= argc) {
        handle_error("Input file not specified", 0);
    }

    // Open the input file and check for errors
    FILE* input_file = fopen(argv[optind], "r");
    if (input_file == NULL) {
        handle_error("Error opening input file", errno);
    }

    // Define variables for storing offset information
    int num_offsets;
    struct offset* offsets = NULL;

    // Read the number of offsets from the input file
    if (fscanf(input_file, "%d", &num_offsets) != 1) {
        handle_error("Error reading number of offsets", errno);
    }

    // Allocate memory for the array of offset structures
    offsets = malloc(sizeof(struct offset) * num_offsets);
    if (offsets == NULL) {
        handle_error("Error allocating memory for offsets", errno);
    }

    // Initialize the offset information from the input file
    for (int i = 0; i < num_offsets; i++) {
        fscanf(input_file, "%ld %d", &offsets[i].offset, &offsets[i].key);
    }

    // Define variables for storing record information
    int num_records;
    struct record* records = NULL;

    // Read the number of records from the input file
    if (fscanf(input_file, "%d", &num_records) != 1) {
        handle_error("Error reading number of records", errno);
    }

    // Allocate memory for the array of record structures
    records = malloc(sizeof(struct record) * num_records);
    if (records == NULL) {
        handle_error("Error allocating memory for records", errno);
    }

    // Initialize the record information from the input file
    for (int i = 0; i < num_records; i++) {
        fscanf(input_file, "%d", &records[i].value);
    }

    // Close the input file and check for errors
    if (fclose(input_file) != 0) {
        handle_error("Error closing input file", errno);
    }

    // Process the records using the offset information
    for (int i = 0; i < num_records; i++) {
        int index = records[i].value - offsets[i].offset;
        if (index >= 0 && index < num_offsets) {
            printf("%d %s\n", offsets[i].key, "found");
        } else {
            printf("%d %s\n", offsets[i].key, "not found");
        }
    }

    // Free the memory for the offset and record structures
    free(offsets);
    free(records);

    // Exit the program with a success status code
    return 0;
}']

