// Define cache management functions
void initCache(CACHE *cache) {
    cache->numEntries = 0;
    cache->entries = NULL;
}

void freeCache(CACHE *cache) {
    if (cache->entries != NULL) {
        free(cache->entries);
    }
}

void addEntryToCache(CACHE *cache, LOG_ENTRY *entry) {
    cache->numEntries++;
    cache->entries = realloc(cache->entries, cache->numEntries * sizeof(LOG_ENTRY));
    memcpy(&cache->entries[cache->numEntries - 1], entry, sizeof(LOG_ENTRY));
}

void removeEntryFromCache(CACHE *cache, int index) {
    if (index >= cache->numEntries || index < 0) {
        return;
    }
    memmove(&cache->entries[index], &cache->entries[index + 1], (cache->numEntries - index - 1) * sizeof(LOG_ENTRY));
    cache->numEntries--;
}

void processLogEntry(CACHE *cache, LOG_ENTRY *entry) {
    // Parse log entry and extract numerical values from last two fields
    uint32_t field1 = atoi(entry->field1);
    uint32_t field2 = atoi(entry->field2);

    // Compute average of numerical values
    double avg = (double)(field1 + field2) / 2.0;

    // Add processed entry to cache
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = entry->timestamp;
    pdu.RNTI = avg;
    pdu.CRCFLAG = 1; // Set CRCFLAG to random value for testing purposes
    addEntryToCache(cache, &pdu);
}

// Main function to process log file
