    FILE *file = fopen(filePath, "r");
    if (file == NULL) {
        printf("Error: unable to open file %s\n", filePath);
        return;
    }

    // Initialize cache management structures
    CACHE cache;
    initCache(&cache);

    char *line = NULL;
    size_t len = 0;
    ssize_t read;

    while ((read = getline(&line, &len, file)) != -1) {
        // Parse log entry from line
        LOG_ENTRY entry;
        entry.timestamp = atoi(strtok(line, ","));
        entry.field1 = atoi(strtok(NULL, ","));
        entry.field2 = atoi(strtok(NULL, "\n"));

        // Process log entry and add to cache
        processLogEntry(&cache, &entry);
    }

    // Free memory allocated by getline
    free(line);

    // Print processed entries
    printf("Processed %d entries:\n", cache.numEntries);
    for (int i = 0; i < cache.numEntries; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &cache.entries[i];
        printf("%u, %u, %d\n", pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->CRCFLAG);
    }

    // Free cache management structures
    freeCache(&cache);

    fclose(file);
}
