        // Increment the size of the collection
        collection->size++;
    }

    // Add the PDU to the end of the collection
    collection->pdu[collection->size] = pdu;

    // Release the mutex
    if (sem_post(mutex) == -1) {
        perror("sem_post");
        return -1;
    }

    // Return success
    return 0;
}

// Function to remove a PDU from the collection
int remove_ltephy_proc_pdu(struct ltephy_proc_pdu_collection *collection, struct ltephy_proc_pdu *pdu) {
    // Acquire the mutex
    if (sem_wait(mutex) == -1) {
        perror("sem_wait");
        return -1;
    }

    // Find the PDU in the collection
