    for (index = 0; index < collection->size; index++) {
        if (collection->pdu[index] == pdu) {
            break;
        }
    }

    // Check if the PDU was found
    if (index >= collection->size) {
        perror("PDU not found in collection");
        return -1;
    }

    // Remove the PDU from the collection
    for (int i = index + 1; i < collection->size; i++) {
        collection->pdu[i - 1] = collection->pdu[i];
    }
    collection->size--;

    // Release the mutex
    if (sem_post(mutex) == -1) {
        perror("sem_post");
        return -1;
    }

