struct processed_output process_packet(struct tcp_header *tcp_header, struct ip_address *src_addr, struct ip_address *dst_addr, long timestamp) {
    // Initialize output structure
    struct processed_output output = {0};

    // Extract the payload size and compute the average payload size per second
    double payload_size = tcp_header->tcp_flags;
    if (payload_size > 0) {
        output.payload_size = payload_size;
    } else {
        output.payload_size = -1;
    }
    output.timestamp = timestamp;

    // Copy the IP addresses and TCP flags
    memcpy(&output.src_addr, src_addr, sizeof(struct ip_address));
    memcpy(&output.dst_addr, dst_addr, sizeof(struct ip_address));
    output.tcp_flags = tcp_header->tcp_flags;

    return output;
}

// Function to process a list of packets and extract the relevant information
void process_packet_list(struct tcp_header *headers, int num_headers, struct ip_address *src_addrs, struct ip_address *dst_addrs, long timestamp) {
    // Initialize output structure
    struct processed_output *outputs = allocate_processed_output_list(num_headers);

    // Loop through each packet and extract the relevant information
    for (int i = 0; i < num_headers; i++) {
