// Define the record structure
typedef struct {
    long offset;
    int key;
    NFAPI_CRC_INDICATION_PDU_T crc_indication;
} record;

// Define a linked list node for storing records
typedef struct Node {
    record* data;
    struct Node* next;
} node;

// Define the function to manage the dynamic collection of records
void manage_records(node** head) {
    // Initialize the random number generator
    srand(time(NULL));

    // Loop until there are no more records in the linked list
    while (*head != NULL) {
        // Get the current node
        node* curr = *head;

        // Check if the record's offset needs to be updated
        if (curr->data->offset < 0) {
            // Generate a new random number for the offset
            curr->data->offset = rand() % INT_MAX;
        }

        // Check if the record's key needs to be updated
        if (curr->data->key < 0) {
            // Generate a new random number for the key
            curr->data->key = rand() % INT_MAX;
        }

        // Update the CRC indication structure
        curr->data->crc_indication.RX_UE_INFORMATION_TAG = (rand() % 2) ? TRUE : FALSE;
        curr->data->crc_indication.RNTI = rand() % INT_MAX;
        curr->data->crc_indication.CRC_INDICATION_REL8_TAG = (rand() % 2) ? TRUE : FALSE;
        curr->data->crc_indication.CRCFLAG = (rand() % 2) ? TRUE : FALSE;

        // Advance the linked list to the next record
        *head = (*head)->next;
    }
}

// Define a function to dynamically allocate memory for a new record
record* create_record(long offset, int key) {
    // Allocate memory for the record structure
    record* rec = malloc(sizeof(record));

    // Check if the allocation was successful
    if (rec == NULL) {
        printf("Error: insufficient memory\n");
        return NULL;
    }

    // Initialize the record structure
    rec->offset = offset;
    rec->key = key;

    // Create a new CRC indication structure
    NFAPI_CRC_INDICATION_PDU_T crc_indication;
    crc_indication.RX_UE_INFORMATION_TAG = (rand() % 2) ? TRUE : FALSE;
    crc_indication.RNTI = rand() % INT_MAX;
    crc_indication.CRC_INDICATION_REL8_TAG = (rand() % 2) ? TRUE : FALSE;
    crc_indication.CRCFLAG = (rand() % 2) ? TRUE : FALSE;

    // Set the CRC indication structure in the record
    rec->crc_indication = crc_indication;

    return rec;
}

// Define a function to add a new record to the linked list
void add_record(node** head, long offset, int key) {
    // Create a new record structure
    record* new_rec = create_record(offset, key);

    // Check if the allocation was successful
    if (new_rec == NULL) {
        printf("Error: insufficient memory\n");
        return;
    }

    // Create a new node for the record
    node* new_node = malloc(sizeof(node));

    // Check if the allocation was successful
    if (new_node == NULL) {
        printf("Error: insufficient memory\n");
        return;
    }

    // Set the data field in the new node to the new record structure
    new_node->data = new_rec;

    // Check if there are no records in the linked list
    if (*head == NULL) {
        // Set the head of the linked list to the new node
        *head = new_node;
        return;
    }

    // Loop through the linked list until the end is reached
    while ((*head)->next != NULL) {
        // Advance to the next node in the linked list
        *head = (*head)->next;
    }

    // Add the new node to the end of the linked list
    (*head)->next = new_node;
}

// Define a function to remove a record from the linked list
void remove_record(node** head, int key) {
    // Check if there are no records in the linked list
    if (*head == NULL) {
        return;
    }

    // Loop through the linked list until the end is reached
    while ((*head)->next != NULL) {
        // Get the current node
        node* curr = *head;

        // Check if the record's key matches the given key
        if (curr->data->key == key) {
            // Remove the node from the linked list
            *head = (*head)->next;

            // Free the memory for the record structure
            free(curr->data);

            // Free the memory for the node
            free(curr);

            return;
        }
    }
}

// Define a function to reset the random number generator before populating the offset fields
void reset_random() {
    srand(time(NULL));
}

int main() {
    // Initialize the linked list head to NULL
    node* head = NULL;

    // Add some records to the linked list
    add_record(&head, 0, 1);
    add_record(&head, 1, 2);
    add_record(&head, 2, 3);
    add_record(&head, 3, 4);

    // Update the records in the linked list
    manage_records(&head);

    // Print out the records in the linked list
    node* curr = head;
    while (curr != NULL) {
        printf("Record: offset=%ld, key=%d\n", curr->data->offset, curr->data->key);
        curr = curr->next;
