    size_t capacity; // Capacity of the vector (number of elements it can hold)
    size_t count; // Current number of elements in the vector
} connection_vector_t;

// Define a thread-safe mutex to protect concurrent access to the vector
pthread_mutex_t vector_lock = PTHREAD_MUTEX_INITIALIZER;

void init_connection_vector(connection_vector_t* vector) {
    // Initialize the vector with an empty vector and a capacity of 100 connections
    vector->connections = malloc(sizeof(connection_t) * 100);
    vector->capacity = 100;
    vector->count = 0;
}

void add_connection(connection_vector_t* vector, connection_t* new_connection) {
    // Lock the mutex to prevent concurrent access to the vector
    pthread_mutex_lock(&vector_lock);

    // Check if the vector has enough capacity to store the new connection
    if (vector->count == vector->capacity) {
        // Increase the capacity of the vector by 50%
        size_t new_capacity = vector->capacity * 1.5;
        connection_t* new_connections = realloc(vector->connections, sizeof(connection_t) * new_capacity);
        if (new_connections == NULL) {
            printf("Error: Failed to allocate memory for the vector\n");
            exit(1);
        }
        vector->connections = new_connections;
        vector->capacity = new_capacity;
    }

    // Add the new connection to the vector
    vector->connections[vector->count] = *new_connection;
    vector->count++;

    // Unlock the mutex to allow other threads to access the vector
    pthread_mutex_unlock(&vector_lock);
}

void remove_connection(connection_vector_t* vector, int socket) {
    // Lock the mutex to prevent concurrent access to the vector
    pthread_mutex_lock(&vector_lock);

    // Find the connection with the specified socket file descriptor and remove it from the vector
    for (size_t i = 0; i < vector->count; i++) {
        if (vector->connections[i].socket == socket) {
            free(vector->connections[i].host);
            free(vector->connections[i].port);
            memmove(&vector->connections[i], &vector->connections[i + 1], sizeof(connection_t) * (vector->count - i - 1));
            vector->count--;
            break;
        }
    }

    // Reallocate the memory for the vector if its capacity is more than half empty
    if (vector->count < vector->capacity / 2) {
        size_t new_capacity = vector->count * 1.5;
        connection_t* new_connections = realloc(vector->connections, sizeof(connection_t) * new_capacity);
        if (new_connections == NULL) {
            printf("Error: Failed to allocate memory for the vector\n");
            exit(1);
        }
        vector->connections = new_connections;
        vector->capacity = new_capacity;
    }

    // Unlock the mutex to allow other threads to access the vector
    pthread_mutex_unlock(&vector_lock);
}

void update_connection(connection_vector_t* vector, int socket, unsigned long long sequence_number) {
    // Lock the mutex to prevent concurrent access to the vector
    pthread_mutex_lock(&vector_lock);

    // Find the connection with the specified socket file descriptor and update its sequence number
    for (size_t i = 0; i < vector->count; i++) {
        if (vector->connections[i].socket == socket) {
            vector->connections[i].sequence_number = sequence_number;
            break;
        }
    }

    // Unlock the mutex to allow other threads to access the vector
    pthread_mutex_unlock(&vector_lock);
}

void monitor_connection(connection_t* connection) {
    // Monitor the connection for packet loss and adjust the sending rate accordingly
    while (true) {
        // Check if there is a gap in the sequence number of received packets
        int sequence_gap = 0;
        for (size_t i = 1; i < connection->count; i++) {
            if (connection->sequence_numbers[i] - connection->sequence_numbers[i - 1] > 1) {
                sequence_gap++;
            }
        }

        // If there is a gap in the sequence number, adjust the sending rate to avoid packet loss
        if (sequence_gap > 0) {
            connection->packet_size += sequence_gap / 10;
        } else {
            connection->packet_size -= sequence_gap / 10;
        }
    }
}
