    if (userSessionsJSON != null) {
        for (String userId : userSessionsJSON.keys()) {
            UserSession userSession = new UserSession(userId, ApplicationState.valueOf(userSessionsJSON.get(userId)), []);
            userSessionMap.put(userId, userSession);
