                            userSession = new UserSession(userId, ApplicationState.valueOf(requestJSON.get("applicationState")), []);
                            userSessionMap.put(userId, userSession);
                        }
                        // Update the UserSession structure with latest information
                        updateUserSession(userSession, requestJSON.get("applicationState"));
                    }

                    // Release lock for updating UserSession structures concurrently
                    pthread_mutex_unlock(&userSessionMutex);
                } catch (Exception e) {
                    // Handle unexpected errors and exceptions
                    logError(e);
                }
            }
        }
    });

    // Start the thread to handle incoming requests for accessing UserSessions concurrently
    requestHandlerThread.start();
}

// Fetch existing UserSession structures from external authentication service
