// Structure to represent a record
typedef struct {
    int key;
    char* buffer;
} Record;

// Function to initialize the arrays and records
int init(int max_offset, int max_key, int max_buffer_size) {
    // Validate input parameters
    if (max_offset <= 0 || max_key <= 0 || max_buffer_size <= 0) {
        return -1;
    }

    // Allocate memory for the offset and key arrays
    long* offsets = malloc(sizeof(long) * max_offset);
    int* keys = malloc(sizeof(int) * max_key);

    // Initialize the arrays with random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < max_offset; i++) {
        offsets[i] = rand() % (max_offset - 1) + 1;
    }
    for (int i = 0; i < max_key; i++) {
        keys[i] = rand() % (max_key - 1) + 1;
    }

    // Allocate memory for the record array
    Record* records = malloc(sizeof(Record) * max_key);

    // Initialize each record's int field to a random value within the specified range
    for (int i = 0; i < max_key; i++) {
        records[i].key = rand() % (max_key - 1) + 1;
        records[i].buffer = malloc(sizeof(char) * max_buffer_size);
        strcpy(records[i].buffer, "Initialized");
    }

    // Check for memory allocation failures and gracefully handle them
    if (offsets == NULL || keys == NULL || records == NULL) {
        free(offsets);
        free(keys);
        free(records);
        return -1;
    }

    // Set the record array pointers to point to the allocated memory
    for (int i = 0; i < max_key; i++) {
        records[i].buffer = malloc(sizeof(char) * max_buffer_size);
        if (records[i].buffer == NULL) {
            free(offsets);
            free(keys);
            free(records);
            return -1;
        }
    }

    // Return the initialized arrays and records
    return 0;
}
