NFAPI_CRC_INDICATION_PDU* crc_indication_pdu_list = NULL;
size_t num_structures = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

bool add_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU pdu) {
    bool ret = false;

    // Acquire lock to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Check if maximum number of structures has been reached
    if (num_structures < MAX_NUM_STRUCTURES) {
        crc_indication_pdu_list = realloc(crc_indication_pdu_list, sizeof(NFAPI_CRC_INDICATION_PDU) * (num_structures + 1));
        if (crc_indication_pdu_list != NULL) {
            crc_indication_pdu_list[num_structures] = pdu;
            num_structures++;
            ret = true;
        } else {
            // Log error message if realloc failed
            log_error("Failed to allocate memory for CRC indication PDU");
        }
    } else {
        // Log warning message if maximum number of structures has been reached
        log_warning("Maximum number of CRC indication PDUs reached, cannot add new structure");
    }

    // Release lock to allow other threads to access the list
    pthread_mutex_unlock(&mutex);

    return ret;
}

NFAPI_CRC_INDICATION_PDU* get_crc_indication_pdu(int32_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    NFAPI_CRC_INDICATION_PDU* ret = NULL;

    // Acquire lock to prevent concurrent access
    pthread_mutex_lock(&mutex);

    for (size_t i = 0; i < num_structures; i++) {
        if (crc_indication_pdu_list[i].RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG && crc_indication_pdu_list[i].RNTI == RNTI) {
            ret = &crc_indication_pdu_list[i];
            break;
        }
    }

    // Release lock to allow other threads to access the list
    pthread_mutex_unlock(&mutex);

    return ret;
}

void delete_crc_indication_pdu(int32_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    // Acquire lock to prevent concurrent access
    pthread_mutex_lock(&mutex);

    for (size_t i = 0; i < num_structures; i++) {
        if (crc_indication_pdu_list[i].RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG && crc_indication_pdu_list[i].RNTI == RNTI) {
            // Shift remaining elements to fill the gap
            for (size_t j = i; j < num_structures - 1; j++) {
                crc_indication_pdu_list[j] = crc_indication_pdu_list[j + 1];
            }

            // Decrement the number of structures and free memory for the deleted element
            num_structures--;
            if (num_structures > 0) {
                crc_indication_pdu_list = realloc(crc_indication_pdu_list, sizeof(NFAPI_CRC_INDICATION_PDU) * num_structures);
            } else {
                free(crc_indication_pdu_list);
                crc_indication_pdu_list = NULL;
            }
            break;
        }
    }

    // Release lock to allow other threads to access the list
    pthread_mutex_unlock(&mutex);
}

size_t get_num_crc_indication_pdus() {
    size_t ret = 0;

    // Acquire lock to prevent concurrent access
    pthread_mutex_lock(&mutex);

    ret = num_structures;

    // Release lock to allow other threads to access the list
    pthread_mutex_unlock(&mutex);

    return ret;
}

void log_error(const char* message) {
    FILE* fp = fopen(LOGGING_FILE, "a");
    if (fp != NULL) {
        time_t rawtime;
        struct tm * timeinfo;
        char buffer[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(fp, "[%s] ERROR: %s\n", buffer, message);
        fclose(fp);
    } else {
        // Log error message if failed to open log file for writing
        printf("ERROR: Failed to open log file for writing");
    }
}

void log_warning(const char* message) {
    FILE* fp = fopen(LOGGING_FILE, "a");
    if (fp != NULL) {
        time_t rawtime;
        struct tm * timeinfo;
        char buffer[80];

