// Define the function to manage and initialize the pools of resources
void init_pools(int num_double_points, int num_string_points, int num_data_point_structs) {
  // Allocate memory for the double-precision floating-point numbers
  double *double_pool = (double *)malloc(num_double_points * sizeof(double));
  if (!double_pool) {
    fprintf(stderr, "Error: failed to allocate memory for double pool\n");
    exit(1);
  }

  // Initialize the double-precision floating-point numbers
  for (int i = 0; i < num_double_points; i++) {
    double_pool[i] = rand() % 100;
  }

  // Allocate memory for the char strings
  string_hash_table *string_pool = (string_hash_table *)malloc(num_string_points * sizeof(string_hash_table));
  if (!string_pool) {
    fprintf(stderr, "Error: failed to allocate memory for string pool\n");
    exit(1);
  }

  // Initialize the char strings
  for (int i = 0; i < num_string_points; i++) {
    string_pool[i].str = (char *)malloc(128 * sizeof(char));
    if (!string_pool[i].str) {
      fprintf(stderr, "Error: failed to allocate memory for string %d\n", i);
      exit(1);
    }
    string_pool[i].len = 128;
  }

  // Allocate memory for the struct data points
  struct data_point *data_point_structs = (struct data_point *)malloc(num_data_point_structs * sizeof(struct data_point));
  if (!data_point_structs) {
    fprintf(stderr, "Error: failed to allocate memory for data point structs\n");
    exit(1);
  }

  // Initialize the struct data points
