    int heartbeat_interval = 1000; // milliseconds
    int retry_count = 3;

    // Initialize the synchronization mechanisms for concurrent access
    pthread_mutex_t offset_arr_lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_t keys_arr_lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_t record_lock = PTHREAD_MUTEX_INITIALIZER;

    // Initialize the logging mechanisms
    FILE* log_file = fopen("log.txt", "a");
    char* log_level = getenv("LOG_LEVEL");

    while (1) {
        // Send a heartbeat message and monitor for a response
        send(conn_fd, "HEARTBEAT", 8, MSG_NOSIGNAL);
        char buf[1024];
        recv(conn_fd, buf, 1024, MSG_WAITALL);
        if (strcmp("PONG", buf) == 0) {
            // Connection is healthy, continue processing data
            break;
        } else if (strcmp("RETRY", buf) == 0) {
            // Connection is lost, attempt re-establishment
            usleep(heartbeat_interval * 1000);
            send(conn_fd, "HEARTBEAT", 8, MSG_NOSIGNAL);
            recv(conn_fd, buf, 1024, MSG_WAITALL);
            if (strcmp("PONG", buf) == 0) {
                // Connection is healthy, continue processing data
                break;
            } else {
                // Retry count has been exceeded, close the connection and exit
                printf("Retry limit reached, closing connection\n");
                fclose(log_file);
                free(offset_arr);
                for (int i = 0; i < ARRAY_INITIAL_SIZE; i++) {
                    free(keys_arr[i]);
                }
                free(keys_arr);
                for (int i = 0; i < RECORD_INITIAL_SIZE; i++) {
                    free(records[i]);
                }
                free(records);
                pthread_exit(NULL);
            }
        } else {
            // Unexpected response from server, log the error and exit
            printf("Unexpected response from server: %s\n", buf);
            fprintf(log_file, "ERROR: %d, %s\n", conn_fd, buf);
            fclose(log_file);
            free(offset_arr);
            for (int i = 0; i < ARRAY_INITIAL_SIZE; i++) {
                free(keys_arr[i]);
            }
            free(keys_arr);
            for (int i = 0; i < RECORD_INITIAL_SIZE; i++) {
                free(records[i]);
            }
            free(records);
            pthread_exit(NULL);
        }
    }

    // Process the data from the server
    while (1) {
        // Receive a message from the server
        recv(conn_fd, buf, 1024, MSG_WAITALL);
        if (strcmp("DONE", buf) == 0) {
            // No more data to process, close the connection and exit
            printf("No more data to process, closing connection\n");
            fclose(log_file);
            free(offset_arr);
            for (int i = 0; i < ARRAY_INITIAL_SIZE; i++) {
                free(keys_arr[i]);
            }
            free(keys_arr);
            for (int i = 0; i < RECORD_INITIAL_SIZE; i++) {
                free(records[i]);
            }
            free(records);
            pthread_exit(NULL);
        } else if (strcmp("DATA", buf) == 0) {
            // Receive the data from the server and process it
            char* key = malloc(sizeof(char) * 16);
            int offset = -1;
            while ((offset = get_next_offset(offset_arr, offset)) != -1) {
                recv(conn_fd, key, 16, MSG_WAITALL);
                if (strcmp(key, "DONE") == 0) {
                    // No more data to process, close the connection and exit
                    printf("No more data to process, closing connection\n");
                    fclose(log_file);
                    free(offset_arr);
                    for (int i = 0; i < ARRAY_INITIAL_SIZE; i++) {
                        free(keys_arr[i]);
                    }
                    free(keys_arr);
                    for (int i = 0; i < RECORD_INITIAL_SIZE; i++) {
                        free(records[i]);
                    }
                    free(records);
                    pthread_exit(NULL);
                } else {
                    // Process the data and update the offset array
                    process_data(key, offset_arr, keys_arr, records, offset, &offset_size, &key_size, &record_size);
                }
            }
        }
    }

    return NULL;
}

// Thread-safe function to get the next offset in the offset array
int get_next_offset(int* offset_arr, int prev_offset) {
    pthread_mutex_lock(&offset_arr_lock);
    int curr_offset = offset_arr[prev_offset + 1];
    pthread_mutex_unlock(&offset_arr_lock);
    return curr_offset;
}

