    pthread_mutex_lock(&offset_arr_lock);
    if (keys_arr[offset] == NULL) {
        // This is the first time we are seeing this key, allocate memory for it
        keys_arr[offset] = malloc(sizeof(long) * RECORD_INITIAL_SIZE);
