        // This is the first time we are seeing this record, allocate memory for it
        records[keys[key_size]] = malloc(sizeof(struct record));
    }
    pthread_mutex_unlock(&record_lock);
    struct record* record = records[keys[key_size]];

    // Process the data and update the offset array
    process_data_internal(key, offset_arr, keys, records, offset, offset_size, key_size, record_size);
