// Structure to store TCP connection stats
typedef struct tcp_connection_stats {
    int session_id;
    size_t bytes_sent;
    size_t bytes_received;
    time_t last_active_time;
} tcp_connection_stats_t;

// Structure to store all active sessions and their stats
typedef struct session_manager {
    int num_sessions;
    tcp_connection_stats_t *stats;
} session_manager_t;

// Function to manage TCP connection stats for active sessions
void manage_tcp_connections(session_manager_t *manager, int session_id, size_t bytes_sent, size_t bytes_received) {
    // Find the corresponding session index in the manager's array
    int index = 0;
    for (; index < manager->num_sessions; ++index) {
        if (manager->stats[index].session_id == session_id) {
            break;
        }
    }

    // If the session is not found, allocate memory and create a new entry
    if (index >= manager->num_sessions) {
        // Ensure thread safety by acquiring a lock on the manager structure
        pthread_mutex_lock(&manager->mutex);

        // Check again in case another thread allocated memory while waiting for the lock
        if (index >= manager->num_sessions) {
            manager->stats = realloc(manager->stats, (manager->num_sessions + 1) * sizeof(tcp_connection_stats_t));
            if (!manager->stats) {
                // Handle memory allocation failure gracefully by printing an error message and returning
                fprintf(stderr, "Failed to allocate memory for TCP connection stats\n");
                return;
            }
            manager->num_sessions++;
        }

        // Initialize the new session entry
        tcp_connection_stats_t *new_entry = &manager->stats[index];
        new_entry->session_id = session_id;
        new_entry->bytes_sent = bytes_sent;
        new_entry->bytes_received = bytes_received;
        new_entry->last_active_time = time(NULL);

        // Release the lock and return
        pthread_mutex_unlock(&manager->mutex);
        return;
    }

    // Update the existing session entry with the new statistics
    tcp_connection_stats_t *entry = &manager->stats[index];
    entry->bytes_sent += bytes_sent;
    entry->bytes_received += bytes_received;
    entry->last_active_time = time(NULL);
}
