void populateCrcIndicationList(NFAPI_CRC_INDICATION_PDU_T *pdu_list, int num_elements) {
    // Create a mutex for thread safety
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    // Initialize the list of CRC indication PDUs
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    memset(pdu, 0, num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Populate the list with random RX information
    for (int i = 0; i < num_elements; i++) {
        pdu[i].rx_ue_information_tag = rand();
        pdu[i].rnti = rand() % MAX_RNTI;
        pdu[i].crc_indication_rel8_tag = rand();
        pdu[i].crcFlag = rand() & 0x1;
    }

    // Create a pool of memory for the list to use
    const int POOL_SIZE = 1024 * 1024;
    char *pool = (char *)malloc(POOL_SIZE);
    memset(pool, 0, POOL_SIZE);

    // Allocate memory for the list using a custom allocator
    NFAPI_CRC_INDICATION_PDU_T **pdu_alloc = (NFAPI_CRC_INDICATION_PDU_T **)malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    for (int i = 0; i < num_elements; i++) {
        pdu_alloc[i] = (NFAPI_CRC_INDICATION_PDU_T *)pool_alloc(sizeof(NFAPI_CRC_INDICATION_PDU_T), pool);
    }

    // Free memory for the list when it is no longer needed
    void free_pdu_list() {
        pthread_mutex_lock(&lock);
        for (int i = 0; i < num_elements; i++) {
            if (pdu[i].crcFlag) {
                pool_free(sizeof(NFAPI_CRC_INDICATION_PDU_T), pool, pdu_alloc[i]);
            }
        }
        free(pool);
        free(pdu_alloc);
        free(pdu);
        pthread_mutex_unlock(&lock);
    }

    // Add an element to the list
    void add_element(NFAPI_CRC_INDICATION_PDU_T *new_element) {
        pthread_mutex_lock(&lock);
        if (num_elements < MAX_NUM_ELEMENTS) {
            memcpy(pdu + num_elements, new_element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            num_elements++;
        } else {
            // handle overflow
        }
        pthread_mutex_unlock(&lock);
    }

    // Remove an element from the list
    void remove_element(int index) {
        pthread_mutex_lock(&lock);
        if (index < num_elements) {
            memcpy(pdu + index, pdu + (num_elements - 1), sizeof(NFAPI_CRC_INDICATION_PDU_T));
            num_elements--;
        } else {
            // handle underflow
        }
        pthread_mutex_unlock(&lock);
    }

    // Sort the list by RX information tag
    void sort_by_rx_information_tag() {
        pthread_mutex_lock(&lock);
        qsort(pdu, num_elements, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare_rx_information_tag);
        pthread_mutex_unlock(&lock);
    }

    // Compare two elements by their RX information tag
    int compare_rx_information_tag(const void *a, const void *b) {
        NFAPI_CRC_INDICATION_PDU_T *pdu1 = (NFAPI_CRC_INDICATION_PDU_T *)a;
        NFAPI_CRC_INDICATION_PDU_T *pdu2 = (NFAPI_CRC_INDICATION_PDU_T *)b;
        if (pdu1->rx_ue_information_tag > pdu2->rx_ue_information_tag) {
            return 1;
        } else if (pdu1->rx_ue_information_tag < pdu2->rx_ue_information_tag) {
            return -1;
        } else {
            return 0;
        }
    }

    // Search for an element with a specific RX information tag
    NFAPI_CRC_INDICATION_PDU_T *search_by_rx_information_tag(uint32_t rx_ue_information_tag) {
        pthread_mutex_lock(&lock);
        for (int i = 0; i < num_elements; i++) {
            if (pdu[i].rx_ue_information_tag == rx_ue_information_tag) {
                return &(pdu[i]);
            }
        }
        pthread_mutex_unlock(&lock);
        return NULL;
    }
