#include <netdb.h>
#include <pthread.h>
#include <stdbool.h>

#define MAX_CONNECTIONS 1024
#define PORT "8080"
#define IP_ADDRESS "127.0.0.1"
#define LISTENQ 5
#define RESILIENT_TIMEOUT 30 // seconds
#define CONNECTION_RETRY_INTERVAL 10 // seconds
#define NFAPI_CRC_INDICATION_PDU_T struct { int RX_UE_INFORMATION_TAG; int RNTI; int CRCFLAG; }

// Function to establish a resilient connection to a remote server using an asynchronous communication channel
int resilient_connect(char* hostname, char* port) {
    struct addrinfo hints, *servinfo, *p;
    int sockfd = 0;
    int rv = 0;
    bool isConnected = false;
    long offsetArray[MAX_CONNECTIONS] = {0};
    int keyArray[MAX_CONNECTIONS] = {0};
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Get the list of available services
    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;
    if ((rv = getaddrinfo(hostname, port, &hints, &servinfo)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(rv));
        return -1;
    }

    // Loop through the list of services and find a suitable one
    for (p = servinfo; p != NULL; p = p->ai_next) {
        if ((sockfd = socket(p->ai_family, p->ai_socktype, p->ai_protocol)) == -1) {
            perror("socket");
            continue;
        }

        // Connect to the service
        if (connect(sockfd, p->ai_addr, p->ai_addrlen) == -1) {
            close(sockfd);
            perror("connect");
            continue;
        }

        // Setup heartbeat mechanism
        struct timeval tv;
        tv.tv_sec = RESILIENT_TIMEOUT;
        setsockopt(sockfd, SOL_SOCKET, SO_RCVTIMEO, (char *)&tv, sizeof(struct timeval));

        // Setup dynamic arrays for offset and keys
        long* offsetArrayPtr = offsetArray;
        int* keyArrayPtr = keyArray;
        while (isConnected == false) {
            if (offsetArrayPtr - offsetArray >= MAX_CONNECTIONS) {
                pthread_mutex_lock(&mutex);
                resizeDynamicArray(offsetArray, MAX_CONNECTIONS * 2);
                resizeDynamicArray(keyArray, MAX_CONNECTIONS * 2);
                pthread_mutex_unlock(&mutex);
            }
            offsetArrayPtr = realloc(offsetArray, sizeof(long) * (offsetArrayPtr - offsetArray + 1));
            keyArrayPtr = realloc(keyArray, sizeof(int) * (keyArrayPtr - keyArray + 1));

            // Check for new connections
            fd_set rfds;
            FD_ZERO(&rfds);
            FD_SET(sockfd, &rfds);

            struct timeval timeout = {CONNECTION_RETRY_INTERVAL, 0};
            int retval = select(sockfd + 1, &rfds, NULL, NULL, &timeout);

            if (retval == 0) {
                // No new connections for the specified interval, try again
                continue;
            } else if (FD_ISSET(sockfd, &rfds)) {
                // New connection detected, check if it's a valid one
                struct sockaddr_storage remoteAddr;
                int remoteSockLen = sizeof(struct sockaddr);
                getpeername(sockfd, (struct sockaddr*)&remoteAddr, &remoteSockLen);

                // Check if the IP address matches the one we're expecting
                char* remoteIp = inet_ntoa(((struct sockaddr_in*)&remoteAddr)->sin_addr);
                if (strcmp(IP_ADDRESS, remoteIp) == 0) {
                    // Valid connection detected, break out of the loop
                    isConnected = true;
                    break;
                } else {
                    // Not a valid connection, try again
                    continue;
                }
            } else {
                perror("select");
            }
        }

        // Connection established successfully, break out of the loop
        break;
    }

    // Cleanup and return the socket file descriptor
    freeaddrinfo(servinfo);
    if (isConnected) {
        *offsetArrayPtr = sockfd;
        *keyArrayPtr = sockfd;
        pthread_mutex_unlock(&mutex);
        return sockfd;
    } else {
        close(sockfd);
        perror("connect");
        return -1;
    }
}

// Function to resize a dynamic array and update its pointers
void resizeDynamicArray(long* offsetArray, int newSize) {
    long* tempOffsetArray = realloc(offsetArray, sizeof(long) * newSize);
    if (tempOffsetArray == NULL) {
        perror("realloc");
        exit(EXIT_FAILURE);
    } else {
        offsetArray = tempOffsetArray;
    }
}
```

In this example, we define a function `resizeDynamicArray` that resizes the dynamic arrays for offsets and keys. We use `realloc` to resize the arrays, but check for errors using `perror`. If an error occurs, we exit the program with an error message.

We also define a variable `isConnected` to keep track of whether we have successfully established a connection. We loop through the list of services until we find one that matches our expectations and has a valid IP address. Once we have found a suitable service, we break out of the loop and return the socket file descriptor. If no suitable service is found, we close the socket and print an error message using `perror`.

Note that in this example, we use `getaddrinfo` to get a list of services for the hostname and port we are interested in, and then loop through the list until we find one that matches our expectations. We also use `realloc` to resize the dynamic arrays for offsets and keys when necessary.

Also note that this example uses `pthread_mutex_lock` and `pthread_mutex_unlock` to protect access to the dynamic arrays for offsets and keys, as we are modifying them in multiple threads.']

