['```c
#include <stdlib.h>
#include <string.h>

typedef struct record {
    long offset;
    int key;
    double value;
    size_t refcount;
} record_t;

typedef struct list {
    record_t** records;
    size_t capacity;
    size_t count;
} list_t;

// Initializes a new list with the given capacity.
list_t* list_new(size_t capacity) {
    list_t* list = malloc(sizeof(list_t));
    if (!list) return NULL;
    list->records = calloc(capacity, sizeof(record_t*));
    if (!list->records) {
        free(list);
        return NULL;
    }
    list->count = 0;
    list->capacity = capacity;
    return list;
}

// Adds a new record to the list.
int list_add(list_t* list, long offset, int key, double value) {
    if (list->count >= list->capacity) {
        // Check for memory allocation failure.
        free(list);
        return -1;
    }
    record_t* new_record = malloc(sizeof(record_t));
    if (!new_record) {
        free(list);
        return -1;
    }
    new_record->offset = offset;
    new_record->key = key;
    new_record->value = value;
    new_record->refcount = 0;
    list->records[list->count++] = new_record;
    return 0;
}

// Removes a record from the list.
int list_remove(list_t* list, long offset) {
    size_t i;
    for (i = 0; i < list->count; i++) {
        if (list->records[i]->offset == offset) {
            break;
        }
    }
    if (i >= list->count) {
        return -1;
    }
    record_t* removed = list->records[i];
    size_t j;
    for (j = i; j < list->count - 1; j++) {
        list->records[j] = list->records[j + 1];
    }
    free(removed);
    list->count--;
    return 0;
}

// Retrieves a record from the list by its offset.
record_t* list_get(list_t* list, long offset) {
    size_t i;
    for (i = 0; i < list->count; i++) {
        if (list->records[i]->offset == offset) {
            break;
        }
    }
    if (i >= list->count) {
        return NULL;
    }
    record_t* found = list->records[i];
    found->refcount++;
    return found;
}

// Safely frees a record by decrementing its reference count.
void list_free(record_t* record) {
    if (--record->refcount == 0) {
        free(record);
    }
}

// Deep copies a record structure.
record_t* list_copy(record_t* record) {
    record_t* copy = malloc(sizeof(record_t));
    if (!copy) return NULL;
    copy->offset = record->offset;
    copy->key = record->key;
    copy->value = record->value;
    copy->refcount = 1;
    return copy;
}
```
Documentation:

* `list_new(size_t capacity)`: Initializes a new list with the given capacity. Returns NULL if memory allocation fails.
* `list_add(list_t* list, long offset, int key, double value)`: Adds a new record to the list. Returns -1 on memory allocation failure or when the list is full.
* `list_remove(list_t* list, long offset)`: Removes a record from the list by its offset. Returns -1 if the record does not exist.
* `list_get(list_t* list, long offset)`: Retrieves a record from the list by its offset. Returns NULL if the record does not exist.
* `list_free(record_t* record)`: Safely frees a record by decrementing its reference count.
* `list_copy(record_t* record)`: Deep copies a record structure. Returns NULL on memory allocation failure.

Unit tests:
```c
#include <assert.h>

int main() {
    size_t capacity = 10;
    list_t* list = list_new(capacity);
    assert(list != NULL);

    // Add a record.
    long offset = 5;
    int key = 20;
    double value = 3.14;
    assert(list_add(list, offset, key, value) == 0);
    assert(list->count == 1);
    assert(list->records[0]->offset == offset);
    assert(list->records[0]->key == key);
    assert(list->records[0]->value == value);
    assert(list->records[0]->refcount == 1);

    // Add another record.
    long offset2 = 10;
    int key2 = 42;
    double value2 = -1.23;
    assert(list_add(list, offset2, key2, value2) == 0);
    assert(list->count == 2);
    assert(list->records[1]->offset == offset2);
    assert(list->records[1]->key == key2);
    assert(list->records[1]->value == value2);
    assert(list->records[1]->refcount == 1);

    // Get a record.
    record_t* found = list_get(list, offset);
    assert(found != NULL);
    assert(found->offset == offset);
    assert(found->key == key);
    assert(found->value == value);
    assert(found->refcount == 2);

    // Remove a record.
    list_remove(list, offset);
    assert(list->count == 1);
    found = list_get(list, offset);
    assert(found == NULL);

    // Free the record.
    list_free(found);

    // Deep copy a record.
    record_t* copy = list_copy(found);
    assert(copy != NULL);
    assert(copy->offset == found->offset);
    assert(copy->key == found->key);
    assert(copy->value == found->value);
    assert(copy->refcount == 1);

    // Free the list.
    free(list);

    return 0;
}
