// define a dynamic array to store the UDP socket connections
static UdpSocketConnection *connections = NULL;
static size_t num_connections = 0;

// function to add a new connection
int add_connection(const char *hostname, const unsigned short port) {
    // perform DNS resolution for the given hostname using the standard library functions
    struct hostent *host = gethostbyname(hostname);
    if (host == NULL) {
        fprintf(stderr, "DNS resolution failed: %s\n", strerror(errno));
        return -1;
    }

    // create a new UdpSocketConnection structure and store the IP address and port number
    UdpSocketConnection *connection = malloc(sizeof(UdpSocketConnection));
    if (connection == NULL) {
        fprintf(stderr, "Failed to allocate memory for UdpSocketConnection\n");
        return -1;
    }
    connection->identifier = num_connections++;
    memcpy(connection->ip_addr, host->h_addr, 16);
    connection->port = port;

    // add the new connection to the dynamic array
    connections = realloc(connections, (num_connections + 1) * sizeof(UdpSocketConnection));
    if (connections == NULL) {
        fprintf(stderr, "Failed to reallocate memory for UdpSocketConnections\n");
        return -1;
    }
    connections[num_connections - 1] = connection;

    // return the identifier of the new connection
    return connection->identifier;
}

// function to remove a connection by its identifier
int remove_connection(int id) {
    // check if the connection with the given identifier exists
    UdpSocketConnection *connection = NULL;
    for (size_t i = 0; i < num_connections; i++) {
        if (connections[i]->identifier == id) {
            connection = connections[i];
            break;
        }
    }
    if (connection == NULL) {
        fprintf(stderr, "Connection with identifier %d not found\n", id);
        return -1;
    }

    // remove the connection from the dynamic array
    for (size_t i = 0; i < num_connections - 1; i++) {
        if (connections[i] == connection) {
            connections[i] = connections[i + 1];
        }
    }
    num_connections--;

    // free the memory allocated for the connection
    free(connection);

    return 0;
}

// function to update a connection's details efficiently
int update_connection_details(int id, const char *hostname, const unsigned short port) {
    // check if the connection with the given identifier exists
    UdpSocketConnection *connection = NULL;
    for (size_t i = 0; i < num_connections; i++) {
        if (connections[i]->identifier == id) {
            connection = connections[i];
            break;
        }
    }
    if (connection == NULL) {
        fprintf(stderr, "Connection with identifier %d not found\n", id);
        return -1;
    }

    // perform DNS resolution for the given hostname using the standard library functions
    struct hostent *host = gethostbyname(hostname);
    if (host == NULL) {
        fprintf(stderr, "DNS resolution failed: %s\n", strerror(errno));
        return -1;
    }

    // update the connection's IP address and port number
    memcpy(connection->ip_addr, host->h_addr, 16);
    connection->port = port;

    return 0;
}

// function to periodically check for inactive connections and close them if they have been idle for more than a specified time period
void check_inactive_connections() {
    // iterate over the connections and close those that have been idle for longer than the specified time period
    for (size_t i = 0; i < num_connections; i++) {
        UdpSocketConnection *connection = connections[i];
        if (time(NULL) - connection->last_used > IDLE_TIMEOUT) {
            remove_connection(connection->identifier);
        }
    }
}
