// C function to manage a dynamic array of UdpSocketConnection structures
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

typedef struct UdpSocketConnection {
    int socket_id;
    char* ip_address;
    unsigned short port;
} UdpSocketConnection;

// Function to add a new connection to the array
void add_connection(UdpSocketConnection* conn) {
    // Check if the maximum number of connections has been reached
    if (num_connections >= MAX_CONNECTIONS) {
        // Gracefully disconnect the oldest active connection
        UdpSocketConnection* oldest = &connections[0];
        int oldest_socket_id = oldest->socket_id;
        close(oldest_socket_id);
        for (int i = 1; i < num_connections; i++) {
            connections[i - 1] = connections[i];
        }
        num_connections--;
    }

    // Add the new connection to the end of the array
    connections[num_connections++] = *conn;
}

// Function to remove a connection from the array by its identifier
void remove_connection(int socket_id) {
    for (int i = 0; i < num_connections; i++) {
        if (connections[i].socket_id == socket_id) {
            UdpSocketConnection* conn = &connections[i];
            close(conn->socket_id);
            for (int j = i; j < num_connections - 1; j++) {
                connections[j] = connections[j + 1];
            }
            num_connections--;
            break;
        }
    }
}

// Function to update a connection's details in the array
void update_connection(UdpSocketConnection* conn) {
    for (int i = 0; i < num_connections; i++) {
        if (connections[i].socket_id == conn->socket_id) {
            connections[i] = *conn;
            break;
        }
    }
}

// Function to periodically check for inactive connections and close them
void close_inactive_connections() {
    struct timeval current_time;
    gettimeofday(&current_time, NULL);
    long current_timestamp = current_time.tv_sec * 1000 + current_time.tv_usec / 1000;

    for (int i = 0; i < num_connections; i++) {
        UdpSocketConnection* conn = &connections[i];
        if (conn->last_active_timestamp != 0 && current_timestamp - conn->last_active_timestamp > INACTIVITY_TIMEOUT) {
            close(conn->socket_id);
            for (int j = i; j < num_connections - 1; j++) {
                connections[j] = connections[j + 1];
            }
            num_connections--;
        }
    }
}

// Function to automatically reconnect closed connections
void auto_reconnect(int socket_id) {
    UdpSocketConnection* conn = get_connection(socket_id);
    if (conn == NULL || !conn->is_failed) {
        return;
    }

    // Check if the connection is still in the process of being reconnected
    for (int i = 0; i < MAX_RECONNECTIONS; i++) {
        if (connections[i].socket_id == socket_id && connections[i].is_reconnecting) {
            return;
        }
    }

    // Attempt to reconnect the connection up to three times before marking it as failed
    for (int i = 0; i < MAX_RECONNECTIONS; i++) {
        UdpSocketConnection* new_conn = create_new_connection(conn->ip_address, conn->port);
        if (new_conn != NULL) {
            // Update the connection details and mark it as reconnecting
            update_connection(new_conn);
            connections[i].is_reconnecting = true;

            return;
        } else {
            printf("Reconnection attempt %d failed for socket ID %d\n", i + 1, socket_id);
        }
    }

    // If the connection has been successfully reconnected or marked as failed, update the connection details and reset the reconnect counter
    UdpSocketConnection* new_conn = create_new_connection(conn->ip_address, conn->port);
    if (new_conn != NULL) {
        update_connection(new_conn);
    } else {
        printf("Reconnection attempt %d failed for socket ID %d\n", MAX_RECONNECTIONS, socket_id);
        remove_connection(socket_id);
    }
}

// Function to limit the maximum number of active connections
void limit_active_connections() {
    if (num_connections >= MAX_CONNECTIONS) {
        UdpSocketConnection* oldest = &connections[0];
        int oldest_socket_id = oldest->socket_id;
        close(oldest_socket_id);
        for (int i = 1; i < num_connections; i++) {
            connections[i - 1] = connections[i];
        }
        num_connections--;
    }
}

// Function to manage the distributed tracing system
