void optimize_performance() {
    struct sched_param param;
    int policy = SCHED_RR;

    // Set the thread scheduling policy to Round Robin (SCHED_RR)
    if (sched_setscheduler(0, policy, &param)) {
        printf("Failed to set thread scheduling policy\n");
