void insertTail(List *list, NFAPI_CRC_INDICATION_PDU_T *data) {
  pthread_mutex_lock(&list->mutex);
  Node *node = malloc(sizeof(Node));
  node->data = data;
  node->prev = list->tail;
  if (list->tail != NULL) {
