    return NULL;
  }
  Node *node = list->head;
  NFAPI_CRC_INDICATION_PDU_T *data = node->data;
  list->head = node->next;
  if (list->head != NULL) {
    list->head->prev = NULL;
  } else {
    list->tail = NULL;
  }
  free(node);
  list->size--;
  pthread_mutex_unlock(&list->mutex);
  return data;
