  pthread_mutex_lock(&list->mutex);
  Node *node = list->head;
  while (node != NULL) {
    if (node->data->rnti == rnti) {
      NFAPI_CRC_INDICATION_PDU_T *data = node->data;
      if (node->prev != NULL) {
        node->prev->next = node->next;
      } else {
        list->head = node->next;
      }
      if (node->next != NULL) {
        node->next->prev = node->prev;
      } else {
        list->tail = node->prev;
      }
      free(node);
      list->size--;
      pthread_mutex_unlock(&list->mutex);
      return data;
