    while (nextNode != NULL) {
      if (node->data->rnti > nextNode->data->rnti) {
        NFAPI_CRC_INDICATION_PDU_T *temp = node->data;
        node->data = nextNode->data;
        nextNode->data = temp;
      }
      nextNode = nextNode->next;
    }
    node = node->next;
  }
  pthread_mutex_unlock(&list->mutex);
}

