// Initialize a new transaction object with a random amount and timestamp
void init_transaction(transaction_t *txn, char currency[3]) {
    txn->timestamp = (long long)(time(NULL)) * 1000; // Microseconds
    txn->amount = (double)rand() / RAND_MAX; // Random amount between 0 and 1
    strncpy(txn->currency, currency, 3); // Set the currency code
