// Add a new transaction to the collection
void add_transaction(transactions_t *transactions, char currency[3]) {
    // Check if we have reached the capacity of the array
    if (transactions->size == transactions->capacity) {
        // If so, double the size of the array and update the capacity
        int old_capacity = transactions->capacity;
        transactions->capacity *= 2;
        transactions->transactions = realloc(transactions->transactions, sizeof(transaction_t) * transactions->capacity);
