    // Check if the index is valid
    if (index < 0 || index >= transactions->size) {
        printf("Error: Invalid transaction index\n");
        return;
    }
    // Shift all elements after the specified index to fill the gap
    for (int i = index + 1; i < transactions->size; i++) {
        transactions->transactions[i - 1] = transactions->transactions[i];
    }
    transactions->size--;
}

// Update a transaction in the collection
void update_transaction(transactions_t *transactions, int index, char currency[3]) {
    // Check if the index is valid
    if (index < 0 || index >= transactions->size) {
        printf("Error: Invalid transaction index\n");
        return;
    }
    // Update the currency code for the specified transaction
    strncpy(transactions->transactions[index].currency, currency, 3);
}

