        int new_capacity = array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_pdu_array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
        memcpy(new_pdu_array, array->pdu_array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * array->size);
        free(array->pdu_array);
        array->pdu_array = new_pdu_array;
        array->capacity = new_capacity;
    }
    memcpy(&array->pdu_array[array->size++], pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

void nfapi_crc_indication_array_update(NFAPI_CRC_INDICATION_ARRAY* array, int index, NFAPI_CRC_INDICATION_PDU_T* pdu) {
