// Function to manage memory allocation and manipulation for an array of records
int manageRecords(Record **records, size_t *numRecords, size_t growthCriteria) {
    int status = 0;

    // Check if the input parameters are valid
    if (!records || !numRecords || growthCriteria <= 0) {
        return -1;
    }

    // Dynamically resize the array based on user-defined growth criteria
    size_t newSize = *numRecords + growthCriteria;
    Record *newRecords = realloc(*records, sizeof(Record) * newSize);
    if (!newRecords) {
        status = -2; // Memory allocation failed
        goto end;
    }
    *records = newRecords;
    *numRecords = newSize;

    // Initialize the new records with random data and cache them
    srand(time(NULL)); // Seed the RNG using the current time
    for (size_t i = *numRecords - growthCriteria; i < *numRecords; i++) {
        // Generate a random alphanumeric string of length 20
        char str[20];
        for (int j = 0; j < 20; j++) {
            str[j] = rand() % 10 + 'A';
        }
        str[19] = '\0';

        // Initialize the record fields
        (*records)[i].offset = rand() % 1000000;
        (*records)[i].key = rand() % 100;
        (*records)[i].data = (float)rand() / RAND_MAX;
        strcpy((*records)[i].buffer, str);
    }

end:
    return status;
}

// Function to handle error logging and memory deallocation upon function exit
void freeRecords(Record **records) {
    if (*records) {
        free(*records);
        *records = NULL;
    }
}
