void add_record(NetworkEventRecord *record) {
    // Check if the record is valid
    if (record == NULL || record->timestamp < 0 || record->event_id < 0 || !record->status_flag) {
        return;
    }

    // Add the new record to the list
    NetworkEventRecord *new_record = malloc(sizeof(NetworkEventRecord));
    memcpy(new_record, record, sizeof(NetworkEventRecord));
    new_record->next = NULL;

    // Update the tail pointer if necessary
    if (tail == NULL) {
        head = tail = new_record;
    } else {
        tail->next = new_record;
        tail = new_record;
    }
}

// Function to update an existing record in the list
