    Record new_record = { string, record_id };
    array->records[array->length] = malloc(sizeof(Record));
    memcpy(array->records[array->length], &new_record, sizeof(Record));
    array->length++;
}

void clear_dynamic_array(struct DynamicArray *array) {
    for (size_t i = 0; i < array->length; i++) {
        free(array->messages[i]);
        free(array->records[i]);
    }
    array->length = 0;
}

void destroy_dynamic_array(struct DynamicArray *array) {
    clear_dynamic_array(array);
    free(array->messages);
    free(array->records);
}

int get_next_available_record_id() {
    // cache the last accessed record ID to minimize string access overhead
    static int last_accessed_record_id = -1;
    if (last_accessed_record_id == -1) {
        return 0;
    } else {
        return last_accessed_record_id + 1;
    }
}

void cache_string(const char *string) {
    // cache the string in a shared pool to minimize overhead from frequent string access
    static char **shared_pool = NULL;
    if (shared_pool == NULL) {
        size_t capacity = 10000;
        shared_pool = malloc(sizeof(char *) * capacity);
    } else if (shared_pool[strlen(string)] == NULL) {
        // if the string is not in the pool, add it and return the index
        size_t new_capacity = 2 * strlen(string);
        shared_pool = realloc(shared_pool, sizeof(char *) * new_capacity);
        shared_pool[strlen(string)] = malloc(sizeof(char) * (new_capacity - strlen(string)));
        memcpy(shared_pool[strlen(string)], string, sizeof(char) * (new_capacity - strlen(string)));
    }
}
