typedef enum {
    NETWORK_STATUS_UP,
    NETWORK_STATUS_DOWN
} NetworkStatus;

typedef struct {
    int EventId;
    time_t Timestamp;
    NetworkStatus Status;
} NetworkEvent;

NetworkEvent* populateNetworkEvents(int numEvents, unsigned seed) {
    // allocate memory for the array of NetworkEvents
    NetworkEvent* events = malloc(numEvents * sizeof(NetworkEvent));
    if (!events) {
        return NULL;
    }

    // initialize the hash table to keep track of unique EventIds
    unsigned* eventIds = malloc(numEvents * sizeof(unsigned));
    memset(eventIds, 0, numEvents * sizeof(unsigned));

    for (int i = 0; i < numEvents; i++) {
        // generate a random NetworkStatus value using the specified seed
        int status = rand_r(&seed) % 2;

        // calculate the current system time in seconds since epoch
        time_t timestamp = time(NULL);

        // create a new NetworkEvent structure and populate it with the generated values
        events[i] = (NetworkEvent) {
            .EventId = i,
            .Timestamp = timestamp,
            .Status = status ? NETWORK_STATUS_UP : NETWORK_STATUS_DOWN
        };

        // add the EventId to the hash table for efficient look-up
        eventIds[i] = events[i].EventId;
    }

    // check if any of the EventIds are duplicate and handle errors accordingly
    for (int i = 0; i < numEvents; i++) {
        for (int j = i + 1; j < numEvents; j++) {
            if (eventIds[i] == eventIds[j]) {
                printf("Duplicate EventId found: %d\n", eventIds[i]);
                free(events);
                free(eventIds);
                return NULL;
            }
        }
    }

    // free the hash table and return the populated array of NetworkEvents
    free(eventIds);
    return events;
}
```
