// Define the structure for a user session log
typedef struct {
    int session_id;
    char *ip_address;
    time_t login_timestamp;
    time_t logout_timestamp;
} UserSessionLog;

// Define a dynamic array to store the user session logs
UserSessionLog **logs = NULL;
int num_logs = 0;
pthread_mutex_t *log_lock = NULL;

// Initialize the function
void initialize() {
    // Allocate memory for the dynamic array of logs
    logs = malloc(sizeof(UserSessionLog *) * 1000);
    if (logs == NULL) {
        printf("Error: failed to allocate memory for logs\n");
        exit(1);
    }

    // Initialize the mutex lock for concurrent access to the log data
    log_lock = malloc(sizeof(pthread_mutex_t));
    if (log_lock == NULL) {
        printf("Error: failed to allocate memory for log lock\n");
        exit(1);
    }

    // Initialize the number of logs to 0
    num_logs = 0;
}

// Add a new session log to the dynamic array
void add_session_log(int session_id, char *ip_address) {
    pthread_mutex_lock(&log_lock);

    // Create a new user session log structure
    UserSessionLog *new_log = malloc(sizeof(UserSessionLog));
    if (new_log == NULL) {
        printf("Error: failed to allocate memory for new log\n");
        exit(1);
    }

    // Set the fields of the new log structure
    new_log->session_id = session_id;
    new_log->ip_address = strdup(ip_address);
    new_log->login_timestamp = time(NULL);
    new_log->logout_timestamp = 0;

    // Add the new log to the dynamic array of logs
    logs[num_logs++] = new_log;

    pthread_mutex_unlock(&log_lock);
}

// Update the logout timestamp for a session with the given ID
void update_session_logout_timestamp(int session_id) {
    pthread_mutex_lock(&log_lock);

    // Find the log with the given session ID
    int i;
    for (i = 0; i < num_logs; i++) {
        if (logs[i]->session_id == session_id) {
            logs[i]->logout_timestamp = time(NULL);
            break;
        }
    }

    pthread_mutex_unlock(&log_lock);
}

// Retrieve the details of a session with the given IP address or time range
void retrieve_session_details(char *ip_address, time_t start_time, time_t end_time) {
    pthread_mutex_lock(&log_lock);

    // Find the log with the given IP address and time range
    int i;
    for (i = 0; i < num_logs; i++) {
        UserSessionLog *log = logs[i];
        if (strcmp(log->ip_address, ip_address) == 0 && log->login_timestamp >= start_time && log->logout_timestamp <= end_time) {
            // Print the details of the session
            printf("Session ID: %d\nIP Address: %s\nLogin Timestamp: %s\nLogout Timestamp: %s\n", log->session_id, log->ip_address, ctime(&log->login_timestamp), ctime(&log->logout_timestamp));
        }
    }

    pthread_mutex_unlock(&log_lock);
}

// Free the memory allocated for the dynamic array of logs
void cleanup() {
    free(logs);
    free(log_lock);
}
