#include <stdlib.h>
#include <stdio.h>
#include <string.h>

#define MAX_NFAPI_CRC_INDICATIONS 1024
#define MIN_MEMORY_THRESHOLD (10 * 1024 * 1024) // 10 MB

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

int init_crc_indications(NFAPI_CRC_INDICATION_PDU_T* crc_indications, int num_indications) {
    // Check input parameters
    if (num_indications > MAX_NFAPI_CRC_INDICATIONS || num_indications <= 0) {
        return -1;
    }

    // Calculate the required memory for the CRC indications
    size_t mem_size = sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_indications;

    // Check if there is enough memory available to allocate the CRC indications
    if (mem_size > MIN_MEMORY_THRESHOLD) {
        return -2;
    }

    // Allocate the memory for the CRC indications
    NFAPI_CRC_INDICATION_PDU_T* mem = malloc(mem_size);

    // Check if memory allocation failed
    if (mem == NULL) {
        return -3;
    }

    // Initialize the CRC indications
    for (int i = 0; i < num_indications; i++) {
        crc_indications[i].RX_UE_INFORMATION_TAG = i + 1;
        crc_indications[i].RNTI = i + 2;
        crc_indications[i].CRC_INDICATION_REL8_TAG = i + 3;
        crc_indications[i].CRCFLAG = (rand() % 2) == 0;
    }

    // Free the memory allocated for the CRC indications
    free(mem);

    return num_indications;
}
