        if ((*records)[i] == NULL) {
            printf("Error: could not allocate memory for record %zu\n", i);
            return;
        }
        (*records)[i]->offset = 0; // initialize the offset field to zero
        (*records)[i]->key = -1;   // initialize the key field to -1
    }
}

// Function to populate an array of records with unique keys from an array of integers
void populate_records(size_t num_keys, int* keys, record** records) {
    // Initialize a hash table for quick lookups and insertions
    size_t i;
    hash_table table;
    table.num_buckets = 1024;
    table.max_size = 1024 * 1024;
    table.mutex = PTHREAD_MUTEX_INITIALIZER;
    table.buckets = (record**)malloc(sizeof(record*) * table.num_buckets);
    if (table.buckets == NULL) {
        printf("Error: could not allocate memory for hash table buckets\n");
        return;
    }

    // Populate the hash table with keys and corresponding records
    for (i = 0; i < num_keys; i++) {
        int key = keys[i];
        pthread_mutex_lock(&table.mutex);
        if (table.buckets[key % table.num_buckets] == NULL) {
            // Insert the record into the hash table
            record* new_record = (record*)malloc(sizeof(record));
            if (new_record == NULL) {
                printf("Error: could not allocate memory for new record\n");
                return;
            }
            new_record->offset = 0; // initialize the offset field to zero
            new_record->key = key;  // set the key field to the current key
            table.buckets[key % table.num_buckets] = new_record;
        } else {
            // Check if there is already a record with the same key
            record* existing_record = table.buckets[key % table.num_buckets];
            while (existing_record->next != NULL) {
                existing_record = existing_record->next;
                if (existing_record->key == key) {
                    // Found a duplicate record, skip the current iteration
                    continue;
                }
            }
            // Insert the record into the linked list of records with the same key
            record* new_record = (record*)malloc(sizeof(record));
            if (new_record == NULL) {
                printf("Error: could not allocate memory for new record\n");
                return;
            }
            new_record->offset = 0; // initialize the offset field to zero
            new_record->key = key;  // set the key field to the current key
            existing_record->next = new_record;
        }
        pthread_mutex_unlock(&table.mutex);
    }
}

// Function to allocate memory for an array of integers
void alloc_ints(size_t num_ints, int*** ints) {
    // Allocate memory for the array of pointers to integers
    *ints = (int**)malloc(sizeof(int*) * num_ints);
    if (*ints == NULL) {
        printf("Error: could not allocate memory for integers\n");
        return;
    }

    // Allocate memory for each integer and initialize it to zero
    size_t i;
    for (i = 0; i < num_ints; i++) {
        (*ints)[i] = (int*)malloc(sizeof(int));
        if ((*ints)[i] == NULL) {
            printf("Error: could not allocate memory for integer %zu\n", i);
            return;
        }
        (*ints)[i][0] = 0; // initialize the integer to zero
    }
}

// Function to generate random numbers within a specified range
void generate_random(long min, long max, int** rand_nums) {
    size_t i;
    for (i = 0; i < (*rand_nums)[0]; i++) {
        (*rand_nums)[i] = ((double)rand() / RAND_MAX) * (max - min + 1) + min;
    }
}

// Function to set the 'offset' field of each record structure randomly within a specified range
void set_offsets(size_t num_records, record** records, long min, long max) {
    size_t i;
    for (i = 0; i < num_records; i++) {
        records[i]->offset = ((double)rand() / RAND_MAX) * (max - min + 1) + min;
    }
}

// Main function
int main(void) {
    // Allocate memory for an array of integers and populate it with random numbers
    int* rand_ints = NULL;
    alloc_ints(10, &rand_ints);
    generate_random(0, 1000, &rand_ints);

    // Allocate memory for an array of record structures and populate it with unique keys from the integer array
    record* records = NULL;
    alloc_records(10, rand_ints, &records);
    populate_records(10, rand_ints, &records);

    // Set the 'offset' field of each record structure randomly within a specified range
    set_offsets(10, records, 0, 1000);

    return 0;
}
