} rx_frame_header_t;

// Structur for holding UE information
typedef struct {
    NFAPI_RX_UE_INFORMATION_TAG tag; // Tag for identifying the UE
    uint16_t rnti; // RNTI of the UE
} rx_ue_information_t;

// Structur for holding a linked list node
typedef struct {
    rx_frame_header_t header; // Header information for the frame
    rx_ue_information_t ue_info; // UE information for the frame
    float value; // Stored floating-point value for determining frame type
    struct node *next; // Pointer to the next node in the linked list
} node_t;

// Function for processing a list of floating-point numbers from standard input
void process_floating_point_numbers(float *input, int size) {
    // Initialize the linked list with an initial capacity of 2^10 nodes
    node_t *head = malloc(sizeof(node_t) * 1024);
    node_t *cur = head;

    for (int i = 0; i < size; i++) {
        // Reallocate the linked list if the current capacity is exceeded
        if (cur == head + 1023) {
            head = realloc(head, sizeof(node_t) * 2 * 1024);
            cur = head + 1023;
        }

        // Store the floating-point number and update the frame type based on the stored value
        float val = input[i];
        if (val >= 0) {
            cur->header.frame_type = 0;
        } else if (val < -1000) {
            cur->header.frame_type = 2;
        } else if (val > 1000) {
            cur->header.frame_type = 3;
        } else {
            cur->header.frame_type = 4;
        }
        cur->value = val;

        // Increment the current node pointer to point to the next available slot
        cur++;
    }

    // Free all dynamically allocated memory
    free(head);
}
