class SocialMediaApplication {
private:
    map<int, UserProfile> userProfiles;
    mutex mtx;
    condition_variable cv;
    int maxNumberOfUsers = 1000;
    int currentNumberOfUsers = 0;
    int cacheSize = 500;
    vector<UserProfile> cache;
    bool isCacheFull() { return currentNumberOfUsers >= cacheSize; }
    void insertIntoCache(UserProfile profile) {
        if (!isCacheFull()) {
            cache.push_back(profile);
            ++currentNumberOfUsers;
        } else {
            // Replace the least recently used item in the cache with the new item
            int lruIndex = 0;
            for (int i = 1; i < cacheSize; ++i) {
                if (cache[lruIndex].lastAccessedAt < cache[i].lastAccessedAt) {
                    lruIndex = i;
                }
            }
            cache[lruIndex] = profile;
        }
    }
    void removeFromCache(int userId) {
        for (auto it = cache.begin(); it != cache.end(); ++it) {
            if ((*it).userId == userId) {
                cache.erase(it);
                --currentNumberOfUsers;
                break;
            }
        }
    }
    UserProfile retrieveFromCache(int userId) {
        for (auto it = cache.begin(); it != cache.end(); ++it) {
            if ((*it).userId == userId) {
                (*it).lastAccessedAt = chrono::high_resolution_clock::now().time_since_epoch().count();
                return *it;
            }
        }
        return UserProfile{};
    }
public:
    void insertUser(int userId, string username, string profilePictureUrl) {
        unique_lock<mutex> lock(mtx);
        if (currentNumberOfUsers < maxNumberOfUsers) {
            UserProfile newUser = {userId, username, profilePictureUrl};
            userProfiles[userId] = newUser;
            insertIntoCache(newUser);
            ++currentNumberOfUsers;
        } else {
            // Evict the least recently used item in the cache
            int lruIndex = 0;
            for (int i = 1; i < cacheSize; ++i) {
                if (cache[lruIndex].lastAccessedAt < cache[i].lastAccessedAt) {
                    lruIndex = i;
                }
            }
            userProfiles.erase(cache[lruIndex].userId);
            removeFromCache(cache[lruIndex].userId);
        }
        lock.unlock();
    }
    void deleteUser(int userId) {
        unique_lock<mutex> lock(mtx);
        userProfiles.erase(userId);
        removeFromCache(userId);
        --currentNumberOfUsers;
        lock.unlock();
    }
    UserProfile retrieveUser(int userId) {
        unique_lock<mutex> lock(mtx);
        UserProfile profile = retrieveFromCache(userId);
        if (profile.isEmpty()) {
            profile = userProfiles[userId];
            insertIntoCache(profile);
        } else {
            profile.lastAccessedAt = chrono::high_resolution_clock::now().time_since_epoch().count();
        }
        lock.unlock();
        return profile;
    }
};

