void remove_ue_context(size_t index, struct ue_context_list *list) {
    // Validate input arguments
    if (!list || (index >= list->size)) {
        return;
    }

    // Shift all subsequent elements to the left by one position
    for (int i = index + 1; i < list->size; ++i) {
        memcpy(&list->list[i - 1], &list->list[i], sizeof(lte_ue_context));
    }

    // Decrement the size of the list by one
    --list->size;
}

