    // Check if the requested number of records is within the limits of the pool
    if (N > pool->total_size / sizeof(struct MAC_LOG_RECORD)) {
        printf("Error: Requested log count (%zu) exceeds maximum allowed by memory pool (%zu).\n", N, pool->total_size / sizeof(struct MAC_LOG_RECORD));
        return NULL;
