    hashtable->capacity = 10000;
    hashtable->elements = (NFAPI_CRC_INDICATION_PDU_T*)malloc(hashtable->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    assert(hashtable->elements != NULL);
}

// Insert a new CRC indication data into the hash table
static void insert_crcindication_data(HashTable* hashtable, NFAPI_CRC_INDICATION_PDU_T* crc_indication) {
    // Check if the hash table is full
    if (hashtable->num_elements == hashtable->capacity) {
        // If so, double the capacity of the hash table
        size_t new_capacity = hashtable->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_elements = (NFAPI_CRC_INDICATION_PDU_T*)malloc(new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        assert(new_elements != NULL);
        // Copy the existing elements to the new array
        memcpy(new_elements, hashtable->elements, hashtable->num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        // Free the old elements
        free(hashtable->elements);
        // Update the hash table with the new array and capacity
        hashtable->elements = new_elements;
        hashtable->capacity = new_capacity;
    }
    // Insert the new CRC indication data into the hash table
    hashtable->elements[hashtable->num_elements++] = *crc_indication;
}

// Remove a CRC indication data from the hash table by RNTI
static void remove_crcindication_data(HashTable* hashtable, uint32_t rnti) {
    // Find the index of the element to be removed in the hash table
    size_t i;
    for (i = 0; i < hashtable->num_elements; ++i) {
        if (hashtable->elements[i].RNTI == rnti) {
            break;
        }
    }
    // If the element is found, remove it from the hash table
    if (i != hashtable->num_elements) {
        // Shift all elements after the removed element to fill the gap
        for (size_t j = i + 1; j < hashtable->num_elements; ++j) {
            hashtable->elements[j - 1] = hashtable->elements[j];
        }
        // Decrease the number of elements in the hash table by one
        --hashtable->num_elements;
    }
}

// Serialize the hash table to a file
static void serialize_hashtable(HashTable* hashtable, FILE* fp) {
    // Write the total number of elements in the hash table to the file
    size_t num_elements = hashtable->num_elements;
    fwrite(&num_elements, sizeof(size_t), 1, fp);
