    }
}

// Deserialize the hash table from a file
static void deserialize_hashtable(HashTable* hashtable, FILE* fp) {
    // Read the total number of elements in the hash table from the file
    size_t num_elements;
    fread(&num_elements, sizeof(size_t), 1, fp);
