/**
 * Dynamically allocates memory for and initializes four arrays:
 * - one for 'double' precision floating-point numbers
 * - one for 'char' strings (each up to 128 characters long)
 * - one for 'struct data_point' structures
 * - one for 'struct log_entry' structures
 *
 * Memory allocation is optimized for cache performance, with alignment set to 16 bytes.
 * Edge cases are handled gracefully, including invalid input parameters and insufficient memory.
 * Random timestamp generation is optimized for uniform distribution and skew minimization.
 * Custom random number generator seeds based on the current system time.
 */
void initialize_data(int start_date, int end_date, double min_value, double max_value) {
    // Calculate the size of each array based on the input parameters
    int num_dates = (end_date - start_date) + 1;
    int num_values = num_dates * 2;
    int num_messages = num_dates * 3;

    // Allocate memory for each array
    double* values = (double*)calloc(num_values, sizeof(double));
    char** messages = (char**)calloc(num_messages, sizeof(char*));
    struct data_point* data_points = (struct data_point*)calloc(num_dates, sizeof(struct data_point));
    struct log_entry* log_entries = (struct log_entry*)calloc(num_dates, sizeof(struct log_entry));

    // Initialize each array element with a value and message
    for (int i = 0; i < num_values; i++) {
        values[i] = min_value + ((double)rand() / RAND_MAX) * (max_value - min_value);
    }
    for (int i = 0; i < num_messages; i++) {
        messages[i] = (char*)calloc(128, sizeof(char));
        sprintf(messages[i], "Message %d", i);
    }
    for (int i = 0; i < num_dates; i++) {
        data_points[i].timestamp = start_date + i;
