    uint8_t payload[MAX_PAYLOAD_SIZE];
    struct timespec timestamp;
  } mac_frame;

  // Define a linked list structure for managing the dynamically allocated MAC frames
  typedef struct {
    mac_frame *mac_frames;
    int size;
    pthread_mutex_t lock;
  } mac_frame_list;

  // Function to initialize the configuration structure for a network interface
  void init_config(network_interface *iface) {
    iface->mac_frames = malloc(sizeof(mac_frame));
    iface->size = 0;
    pthread_mutex_init(&iface->lock, NULL);
  }

  // Function to add a new MAC frame to the list
  void add_mac_frame(network_interface *iface, uint8_t header[MAC_HEADER_SIZE], uint8_t payload[MAX_PAYLOAD_SIZE]) {
    pthread_mutex_lock(&iface->lock);

    // Allocate a new MAC frame structure and copy the header and payload data
    mac_frame *new_frame = malloc(sizeof(mac_frame));
    memcpy(new_frame->header, header, MAC_HEADER_SIZE);
    memcpy(new_frame->payload, payload, MAX_PAYLOAD_SIZE);

    // Update the timestamp for the new frame
    clock_gettime(CLOCK_MONOTONIC, &new_frame->timestamp);

    // Add the new frame to the list of MAC frames
    iface->mac_frames[iface->size++] = new_frame;

    pthread_mutex_unlock(&iface->lock);
  }

  // Function to retrieve a specific MAC frame from the list
  mac_frame* get_mac_frame(network_interface *iface, int index) {
    if (index >= 0 && index < iface->size) {
      return iface->mac_frames[index];
    } else {
      return NULL;
    }
  }

  // Function to retrieve the last MAC frame from the list
  mac_frame* get_last_mac_frame(network_interface *iface) {
    if (iface->size > 0) {
      return iface->mac_frames[iface->size - 1];
    } else {
      return NULL;
    }
  }

  // Function to remove a specific MAC frame from the list
  void remove_mac_frame(network_interface *iface, int index) {
    pthread_mutex_lock(&iface->lock);

    if (index >= 0 && index < iface->size) {
      // Free the memory for the MAC frame structure
      free(iface->mac_frames[index]);

      // Shift all subsequent frames to fill the gap
      int i;
      for (i = index; i < iface->size - 1; i++) {
        iface->mac_frames[i] = iface->mac_frames[i + 1];
      }

      // Decrement the size of the list
      iface->size--;
    }

    pthread_mutex_unlock(&iface->lock);
  }

  // Function to clear all MAC frames from the list
  void clear_mac_frames(network_interface *iface) {
    pthread_mutex_lock(&iface->lock);

    int i;
    for (i = 0; i < iface->size; i++) {
      // Free the memory for each MAC frame structure
      free(iface->mac_frames[i]);
    }

    // Reset the size of the list to zero
    iface->size = 0;

    pthread_mutex_unlock(&iface->lock);
  }

  // Function to destroy the configuration structure for a network interface
  void destroy_config(network_interface *iface) {
    clear_mac_frames(iface);
    free(iface->mac_frames);
    pthread_mutex_destroy(&iface->lock);
  }']

