int populateNFAPCRCIndications(struct NFAPI_CRC_INDICATION_PDU_T *pdu, size_t num_pdus) {
  // Tracking timing and memory usage
  struct timespec start_time, end_time;
  struct rusage usage_before, usage_after;
  getrusage(RUSAGE_SELF, &usage_before);

  for (size_t i = 0; i < num_pdus; i++) {
    // Generate a random CRCFLAG value using standard library functions
    pdu[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

    // Manage dependencies on external data sources
    // Handle potential delays gracefully by introducing backoff strategies or retry logic
    int retries = 0;
    while (retries < 3) {
      if (get_rx_ue_information(&pdu[i].RX_UE_INFORMATION_TAG, &pdu[i].RNTI)) {
        break;
      } else {
        retries++;
        backoff(retries);
      }
    }
  }

  getrusage(RUSAGE_SELF, &usage_after);
  double duration = (double)(usage_after.ru_utime.tv_sec - usage_before.ru_utime.tv_sec) + (double)(usage_after.ru_stime.tv_sec - usage_before.ru_stime.tv_sec);
  printf("Function took %f seconds to execute.\n", duration);
  printf("Resident set size before: %lu bytes\n", usage_before.ru_maxrss);
  printf("Resident set size after: %lu bytes\n", usage_after.ru_maxrss);

  // Return the number of successfully populated structures
  return num_pdus - retries;
}
