    } else {
        // The memory pool is full, so resize it
        uint32_t oldCapacity = config->interfacePools[0].capacity;
        config->interfacePools[0].capacity *= 2;
        NetworkInterfaceConfig* newElements = malloc(sizeof(NetworkInterfaceConfig) * config->interfacePools[0].capacity);

        // Copy the existing elements of the memory pool to the new memory pool
