// Define the function to create and populate the list of NFAPI_CRC_INDICATION_PDU_T structures
void createAndPopulateList(int N, bool enableLogging) {
    // Initialize a list of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* pduList = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);
    if (!pduList) {
        printf("Failed to allocate memory for the list of NFAPI_CRC_INDICATION_PDU_T structures.\n");
        return;
    }

    // Initialize a set to keep track of unique RNTIs
    uint16_t* rntiSet = (uint16_t*) malloc(sizeof(uint16_t) * N);
    if (!rntiSet) {
        printf("Failed to allocate memory for the set of unique RNTIs.\n");
        free(pduList);
        return;
    }
    memset(rntiSet, 0, sizeof(uint16_t) * N);

    // Populate the list of NFAPI_CRC_INDICATION_PDU_T structures
    for (int i = 0; i < N; i++) {
        pduList[i].rx_ue_information_tag = 0x1234;
        pduList[i].rnti = generateRandomRNTI();
