// Function to allocate memory for the arrays and initialize them
void initArrays(int offsetSize, int keySize, int recordStructuresSize) {
    // Check if the input sizes are valid
    if (offsetSize < 0 || keySize < 0 || recordStructuresSize < 0) {
        printf("Invalid input size!\n");
        return;
    }

    // Allocate memory for the offset array
    long* offsets = malloc(OFFSET_ARRAY_SIZE * sizeof(long));
    if (offsets == NULL) {
        printf("Failed to allocate memory for the offset array!\n");
        return;
    }

    // Allocate memory for the key array
    int* keys = malloc(KEY_ARRAY_SIZE * sizeof(int));
    if (keys == NULL) {
        printf("Failed to allocate memory for the key array!\n");
        free(offsets);
        return;
    }

    // Allocate memory for the record structures
