    if (records == NULL) {
        printf("Failed to allocate memory for the record structures!\n");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize the offset array with random values
    srand(time(NULL));
    for (int i = 0; i < OFFSET_ARRAY_SIZE; i++) {
        offsets[i] = rand() % (MAX_MEMORY_USAGE / 2) + MIN_INT_POINTER;
    }

    // Initialize the key array with random values
    for (int i = 0; i < KEY_ARRAY_SIZE; i++) {
        keys[i] = rand() % (MAX_MEMORY_USAGE / 2) + MIN_INT_POINTER;
    }

    // Initialize the record structures with random pointers to integers
    for (int i = 0; i < RECORD_STRUCTURES_SIZE; i++) {
        records[i].pointer = malloc(sizeof(int));
        if (records[i].pointer == NULL) {
            printf("Failed to allocate memory for the integer pointer in record %d!\n", i);
            free(offsets);
            free(keys);
            return;
        }
        *(records[i].pointer) = rand() % (MAX_INT_POINTER - MIN_INT_POINTER + 1) + MIN_INT_POINTER;
    }

    // Shuffle the order of the record structures using a user-defined seed
    srand(time(NULL));
    for (int i = 0; i < RECORD_STRUCTURES_SIZE; i++) {
        int j = rand() % (RECORD_STRUCTURES_SIZE - i) + i;
        Record temp = records[i];
        records[i] = records[j];
        records[j] = temp;
    }

    // Log memory allocation statistics and errors
    printf("Memory usage: %ld bytes\n", OFFSET_ARRAY_SIZE * sizeof(long) + KEY_ARRAY_SIZE * sizeof(int) + RECORD_STRUCTURES_SIZE * sizeof(Record));
    if (malloc_trim() == NULL) {
        printf("Failed to trim memory\n");
    }

    // Free the allocated memory upon function exit to prevent resource leaks
    free(offsets);
    free(keys);
    for (int i = 0; i < RECORD_STRUCTURES_SIZE; i++) {
        free(records[i].pointer);
    }
}
