        RX_UE_INFORMATION_TAG rxUETag;
        int32_t crcFlag;
    };

    struct NFAPI_CRC_INDICATION_PDU_T {
        RNTI rnti;
        CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
    };

    list<NFAPI_CRC_INDICATION_PDU_T> nrilList;

    NRIL() {
        // Initialize the linked list with a valid RNTI and CRC_INDICATION_REL8_TAG
        nrilList.push_back(NFAPI_CRC_INDICATION_PDU_T{
            .rnti = 10,
            .crcIndicationRel8Tag = {.rxUETag = 256, .crcFlag = rand() % 2}
        });
    }

    void addCRCIndication(RNTI rnti, RX_UE_INFORMATION_TAG rxUETag, int32_t crcFlag) {
        // Ensure efficient memory management to prevent buffer overflows
        nrilList.push_back(NFAPI_CRC_INDICATION_PDU_T{
            .rnti = rnti,
            .crcIndicationRel8Tag = {.rxUETag = rxUETag, .crcFlag = crcFlag}
        });
    }

    void removeCRCIndication(RNTI rnti) {
        // Remove the first occurrence of the given RNTI from the linked list
        nrilList.remove_if([&](const NFAPI_CRC_INDICATION_PDU_T &crcIndication) {
            return crcIndication.rnti == rnti;
        });
    }

    void printCRCIndications() {
        // Print all the CRIC indications in the linked list
        for (const auto &crcIndication : nrilList) {
