int manage_memory(size_t max_records, size_t max_long_value, size_t memory_budget) {
    // Check if the budget is sufficient for the given number of records and long value range
    if (max_records * sizeof(record_t) > memory_budget) {
        printf("Memory budget exceeded! Reducing the number of records.\n");
        max_records = memory_budget / sizeof(record_t);
    }

    // Allocate memory for the collection
    record_t* records = malloc(max_records * sizeof(record_t));
    if (records == NULL) {
        printf("Memory allocation failed! Exiting.\n");
        return -1;
    }

    // Initialize each record with a random long value and a pointer to an int from the keys array
    for (size_t i = 0; i < max_records; i++) {
        records[i].value = rand() % max_long_value;
        records[i].keys = malloc(sizeof(int));
        if (records[i].keys == NULL) {
            printf("Memory allocation failed! Reducing the number of records.\n");
            max_records--;
        }
    }

    // Check for any remaining memory allocation failures and clean up partially allocated memory
    for (size_t i = 0; i < max_records; i++) {
        if (records[i].keys == NULL) {
            free(records);
