        q->capacity = q->capacity ? q->capacity * 2 : 1;
        size_t new_size = q->capacity * sizeof(*q->data);
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(q->data, new_size);
        if (new_data == NULL) {
