    memcpy(&q->data[q->capacity - 1], pdu, sizeof(*pdu));
    q->capacity--;
    return 0;
}

int cqueue_pop(CRC_INDICATION_PDU_QUEUE *q, NFAPI_CRC_INDICATION_PDU_T *pdu) {
