#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

// Define semaphore as an integer
sem_t *sem;

// Define record list as a dynamically allocated array of integers
int *records = NULL;

// Define maximum size of the record list
size_t maxSize;

// Function to initialize and process records
void initializeAndProcessRecords(size_t initialSize) {
    // Validate input size
    if (initialSize <= 0) {
        fprintf(stderr, "Invalid initial size\n");
        return;
    }

    // Allocate memory for the record list
    records = malloc(sizeof(int) * initialSize);
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    // Initialize semaphore with initial value 1
    sem = sem_open("recordSem", O_CREAT, 0644, 1);
    if (sem == SEM_FAILED) {
        fprintf(stderr, "Semaphore creation failed\n");
        return;
    }

    // Initialize all record values to random integers within a specified range
    for (size_t i = 0; i < initialSize; ++i) {
        records[i] = rand() % 100;
    }

    // Print the maximum integer in the list
    printf("Maximum integer in the list is: %d\n", getMaxInt());

    // Clean up semaphore and record list memory
    sem_close(sem);
    free(records);
}

// Helper function to print maximum integer in the list
int getMaxInt() {
    int max = INT_MIN;
    for (size_t i = 0; i < maxSize; ++i) {
        if (records[i] > max) {
            max = records[i];
        }
    }
    return max;
}

// Function to read integers into the list from an external data source
void readIntegersFromDataSource() {
    // Lock semaphore to ensure thread-safe access to the list
    if (sem_wait(sem) == -1) {
        fprintf(stderr, "Semaphore wait failed\n");
        return;
    }

    // Read integers from external data source and store in record list
    for (size_t i = 0; i < initialSize; ++i) {
        records[i] = readIntegerFromDataSource();
    }

    // Unlock semaphore after reading integers
    if (sem_post(sem) == -1) {
        fprintf(stderr, "Semaphore post failed\n");
        return;
    }
}

// Function to dynamically resize the record list if necessary
void resizeRecordList() {
    // Lock semaphore to ensure thread-safe access to the list
    if (sem_wait(sem) == -1) {
        fprintf(stderr, "Semaphore wait failed\n");
        return;
    }

    // Reallocate memory for the record list with a new size
    records = realloc(records, sizeof(int) * (maxSize + 1));
    if (!records) {
        fprintf(stderr, "Memory reallocation failed\n");
        return;
    }

    // Initialize the new record value to a random integer within a specified range
    records[maxSize] = rand() % 100;

    // Update the maximum size of the record list
    maxSize++;

    // Unlock semaphore after resizing list
    if (sem_post(sem) == -1) {
        fprintf(stderr, "Semaphore post failed\n");
        return;
    }
}

// Function to delete the record list and release semaphore memory
void cleanUp() {
    // Lock semaphore to ensure thread-safe access to the list
    if (sem_wait(sem) == -1) {
        fprintf(stderr, "Semaphore wait failed\n");
        return;
    }

    // Free memory for the record list and close semaphore
    free(records);
    sem_close(sem);

    // Unlock semaphore after cleaning up
    if (sem_post(sem) == -1) {
        fprintf(stderr, "Semaphore post failed\n");
        return;
    }
}']

