// Function to dynamically allocate and process states in an FSA
int processFSAStates(int *states, int numStates, struct FSA *fsa, int lastState) {
    // Check for sufficient memory to allocate linked list nodes
    if (!enoughMemoryAvailable()) {
        printf("Not enough memory available. Exiting...\n");
        return NULL;
    }

    // Initialize linked list of states with first state
    struct StateNode *head = (struct StateNode*)malloc(sizeof(struct StateNode));
    head->state = states[0];
    head->next = NULL;

    int largestState = head->state;
    int totalStatesProcessed = 1;

    // Iterate over remaining states and add to linked list
    for (int i = 1; i < numStates; i++) {
        struct StateNode *newNode = (struct StateNode*)malloc(sizeof(struct StateNode));
        newNode->state = states[i];
        newNode->next = NULL;

        // Add new node to end of linked list
        struct StateNode *curr = head;
        while (curr->next != NULL) {
            curr = curr->next;
        }
        curr->next = newNode;

        // Update largest state and total states processed
        if (newNode->state > largestState) {
            largestState = newNode->state;
        }
        totalStatesProcessed++;
    }

    // Print largest state and total states processed
    printf("Largest state: %d\n", largestState);
    printf("Total states processed: %d\n", totalStatesProcessed);

    return head;
}
