// Structure to represent a dynamic array of NFAPI_RX_FRAME_PDU_T structures
typedef struct {
    size_t capacity; // Capacity of the array
    size_t count; // Number of frames currently in the array
    NFAPI_RX_FRAME_PDU_T *frames; // Pointer to the first element of the array
} NFAPI_RX_FRAME_DYNAMIC_ARRAY;

// Function to initialize and manage a dynamic array of NFAPI_RX_FRAME_PDU_T structures
NFAPI_RX_FRAME_DYNAMIC_ARRAY *nfapi_rx_frame_dynamic_array_init(size_t capacity) {
    // Allocate memory for the dynamic array structure and its frames
    NFAPI_RX_FRAME_DYNAMIC_ARRAY *array = (NFAPI_RX_FRAME_DYNAMIC_ARRAY *)malloc(sizeof(NFAPI_RX_FRAME_DYNAMIC_ARRAY) + capacity * sizeof(NFAPI_RX_FRAME_PDU_T));
    if (!array) {
        fprintf(stderr, "Failed to allocate memory for the dynamic array\n");
        return NULL;
    }

    // Initialize the count and capacity of the dynamic array
    array->count = 0;
    array->capacity = capacity;
    array->frames = (NFAPI_RX_FRAME_PDU_T *)((char *)array + sizeof(NFAPI_RX_FRAME_DYNAMIC_ARRAY));

    return array;
}

// Function to add a frame to the dynamic array
void nfapi_rx_frame_dynamic_array_add(NFAPI_RX_FRAME_DYNAMIC_ARRAY *array, unsigned long sequence_number, unsigned int timestamp, char *data, size_t length) {
    // Check if the array is full and needs to be reallocated
    if (array->count >= array->capacity) {
        // Reallocate memory for the dynamic array structure and its frames in chunks of 1000
        size_t new_capacity = array->capacity + 1000;
        NFAPI_RX_FRAME_DYNAMIC_ARRAY *new_array = (NFAPI_RX_FRAME_DYNAMIC_ARRAY *)realloc(array, sizeof(NFAPI_RX_FRAME_DYNAMIC_ARRAY) + new_capacity * sizeof(NFAPI_RX_FRAME_PDU_T));
        if (!new_array) {
            fprintf(stderr, "Failed to reallocate memory for the dynamic array\n");
            return;
        }

        // Update the count and capacity of the dynamic array
        new_array->count = array->count;
        new_array->capacity = new_capacity;
        new_array->frames = (NFAPI_RX_FRAME_PDU_T *)((char *)new_array + sizeof(NFAPI_RX_FRAME_DYNAMIC_ARRAY));

        // Update the pointer to the dynamic array structure and its frames
        array = new_array;
    }

    // Initialize the next frame in the dynamic array
    NFAPI_RX_FRAME_PDU_T *frame = &array->frames[array->count];
    frame->header.sequence_number = sequence_number;
    frame->header.timestamp = timestamp;
    frame->contents.data = data;
    frame->contents.length = length;
    frame->error_indication.sequence_number = sequence_number;
    frame->error_indication.error_flag = 0; // No error by default

    // Increment the count of frames in the dynamic array
    array->count++;
}

// Function to validate that no two frames have the same sequence number and timestamp combination
void nfapi_rx_frame_dynamic_array_validate(NFAPI_RX_FRAME_DYNAMIC_ARRAY *array) {
    // Loop over all frames in the dynamic array
    for (size_t i = 0; i < array->count - 1; i++) {
        NFAPI_RX_FRAME_PDU_T *frame = &array->frames[i];
        unsigned long sequence_number = frame->header.sequence_number;
        unsigned int timestamp = frame->header.timestamp;

        // Loop over all subsequent frames in the dynamic array
        for (size_t j = i + 1; j < array->count; j++) {
            NFAPI_RX_FRAME_PDU_T *next_frame = &array->frames[j];
            unsigned long next_sequence_number = next_frame->header.sequence_number;
            unsigned int next_timestamp = next_frame->header.timestamp;

            // Check if the current frame and the subsequent frame have the same sequence number and timestamp combination
            if (next_sequence_number == sequence_number && next_timestamp == timestamp) {
                fprintf(stderr, "Duplicate sequence number and timestamp combination found in the dynamic array\n");
                return;
            }
        }
    }
}

// Function to handle potential integer overflow issues during reallocation
void nfapi_rx_frame_dynamic_array_handle_overflow(NFAPI_RX_FRAME_DYNAMIC_ARRAY *array) {
    // Check if the dynamic array needs to be reallocated due to integer overflow
    if (array->count == ULONG_MAX) {
        // Reallocate memory for the dynamic array structure and its frames in chunks of 1000
        size_t new_capacity = array->capacity + 1000;
        NFAPI_RX_FRAME_DYNAMIC_ARRAY *new_array = (NFAPI_RX_FRAME_DYNAMIC_ARRAY *)realloc(array, sizeof(NFAPI_RX_FRAME_DYNAMIC_ARRAY) + new_capacity * sizeof(NFAPI_RX_FRAME_PDU_T));
        if (!new_array) {
            fprintf(stderr, "Failed to reallocate memory for the dynamic array\n");
            return;
        }

        // Update the count and capacity of the dynamic array
        new_array->count = array->count;
        new_array->capacity = new_capacity;
        new_array->frames = (NFAPI_RX_FRAME_PDU_T *)((char *)new_array + sizeof(NFAPI_RX_FRAME_DYNAMIC_ARRAY));

        // Update the pointer to the dynamic array structure and its frames
        array = new_array;
    }
}

// Function to remove a frame from the dynamic array
void nfapi_rx_frame_dynamic_array_remove(NFAPI_RX_FRAME_DYNAMIC_ARRAY *array, unsigned long sequence_number) {
    // Loop over all frames in the dynamic array
    for (size_t i = 0; i < array->count; i++) {
        NFAPI_RX_FRAME_PDU_T *frame = &array->frames[i];
        unsigned long current_sequence_number = frame->header.sequence_number;

        // Check if the frame with the specified sequence number exists in the dynamic array
        if (current_sequence_number == sequence_number) {
            // Remove the frame from the dynamic array
            for (size_t j = i; j < array->count - 1; j++) {
                array->frames[j] = array->frames[j + 1];
            }

            // Decrement the count of frames in the dynamic array
            array->count--;

            return;
        }
    }
}

// Function to retrieve a frame from the dynamic array by sequence number
NFAPI_RX_FRAME_PDU_T *nfapi_rx_frame_dynamic_array_get(NFAPI_RX_FRAME_DYNAMIC_ARRAY *array, unsigned long sequence_number) {
    // Loop over all frames in the dynamic array
    for (size_t i = 0; i < array->count; i++) {
        NFAPI_RX_FRAME_PDU_T *frame = &array->frames[i];
        unsigned long current_sequence_number = frame->header.sequence_number;

        // Check if the frame with the specified sequence number exists in the dynamic array
        if (current_sequence_number == sequence_number) {
            return frame;
        }
    }

    return NULL;
}

// Function to clear all frames from the dynamic array
void nfapi_rx_frame_dynamic_array_clear(NFAPI_RX_FRAME_DYNAMIC_ARRAY *array) {
