}

// Function to destroy the dynamic array
void nfapi_rx_frame_dynamic_array_destroy(NFAPI_RX_FRAME_DYNAMIC_ARRAY *array) {
    // Free the memory allocated for the dynamic array structure and its frames
    free(array);
