```python
import os
import logging
import subprocess

def update_config(parameters):
    # Open the configuration file for writing
    with open("config.txt", "w") as f:
        # Iterate over the parameters dictionary and replace placeholders with values
        for key, value in parameters.items():
            f.write(f"{key} = {value}\n")

        # Generate a new random numerical ID using a shell script for encryption
        try:
            output = subprocess.check_output(["/path/to/encrypt.sh", "--generate-id"])
            f.write(f"random_id = {int(output)}")
        except subprocess.CalledProcessError as e:
            logging.error(f"Encryption failed with output: {e.output}")

    # Close the configuration file
    f.close()
