using namespace std;

class Octree {
    public:
        // Constructor to initialize the octree with given feature size, number of leaf nodes, and data capacity
        Octree(int featureSize, int numLeafNodes, int dataCapacity) {
            this->featureSize = featureSize;
            this->numLeafNodes = numLeafNodes;
            this->dataCapacity = dataCapacity;

            // Dynamically allocate memory for the octree structure
            this->nodes = new Node*[this->dataCapacity];

            // Initialize all nodes to nullptr
            for (int i = 0; i < this->dataCapacity; i++) {
                this->nodes[i] = nullptr;
            }
        }

        // Destructor to free the memory allocated by the octree structure
        ~Octree() {
            for (int i = 0; i < this->dataCapacity; i++) {
                if (this->nodes[i] != nullptr) {
                    delete[] this->nodes[i];
                }
            }
            delete[] this->nodes;
        }

        // Function to insert data into the octree
        void insert(const vector<double>& data) {
            if (this->numLeafNodes == 0 || data.size() != this->featureSize) {
                return;
            }

            // Find the appropriate node for the given data point and insert it
            Node* currentNode = this->nodes[data[0]];
            for (int i = 1; i < this->featureSize - 1; i++) {
                if (currentNode == nullptr) {
                    break;
                }
                currentNode = currentNode->children[data[i]];
            }

            // If the node is already full, prune less significant branches to make room for new data
            if (currentNode->isFull()) {
                this->pruneLessSignificantBranches(currentNode);
            }

            currentNode->insert(data);
        }

        // Function to query the octree for the k nearest neighbors to a given data point
        vector<vector<double>> knnQuery(const vector<double>& data, int k) {
            if (this->numLeafNodes == 0 || data.size() != this->featureSize) {
                return {};
            }

            // Find the appropriate node for the given data point and perform a k-nearest neighbors query on it
            Node* currentNode = this->nodes[data[0]];
            for (int i = 1; i < this->featureSize - 1; i++) {
                if (currentNode == nullptr) {
                    break;
                }
                currentNode = currentNode->children[data[i]];
            }

            // If the node is not found, return an empty result
            if (currentNode == nullptr) {
                return {};
            }

            return currentNode->knnQuery(data, k);
        }

    private:
        // Node structure for the octree
        struct Node {
            bool isLeaf;
            vector<double> data;
            map<int, Node*> children;
            int numEntries;

            // Constructor to initialize a node with given feature size and number of leaf nodes
            Node(int featureSize, int numLeafNodes) {
                this->isLeaf = false;
                this->data = vector<double>(featureSize);
                this->numEntries = 0;

                if (numLeafNodes > 0) {
                    for (int i = 0; i < numLeafNodes; i++) {
                        this->children[i] = new Node(featureSize, numLeafNodes - 1);
                    }
                }
            }

            // Destructor to free the memory allocated by the node and its children
            ~Node() {
                for (auto& child : this->children) {
                    delete child.second;
                }
            }

            // Function to insert data into a node
            void insert(const vector<double>& data) {
                if (this->isLeaf) {
                    this->data = data;
                    this->numEntries++;
                } else {
                    int index = data[0];
                    for (int i = 1; i < this->featureSize - 1; i++) {
                        index += data[i] * pow(2, i);
                    }
                    if (this->children.find(index) == this->children.end()) {
                        this->children[index] = new Node(this->featureSize, this->numLeafNodes - 1);
                    }
                    this->children[index]->insert(data);
                }
            }

            // Function to perform a k-nearest neighbors query on a node
            vector<vector<double>> knnQuery(const vector<double>& data, int k) {
                if (this->isLeaf) {
                    return this->data;
                } else {
                    int index = data[0];
                    for (int i = 1; i < this->featureSize - 1; i++) {
                        index += data[i] * pow(2, i);
                    }
                    if (this->children.find(index) == this->children.end()) {
                        return {};
                    } else {
                        return this->children[index]->knnQuery(data, k);
                    }
                }
            }

            // Function to check if a node is full
            bool isFull() {
                return this->numEntries == this->children.size();
            }

            // Function to prune less significant branches in the octree
            void pruneLessSignificantBranches(Node* currentNode) {
                if (currentNode->isLeaf || !currentNode->isFull()) {
                    return;
                }

                int minIndex = -1;
                double minValue = std::numeric_limits<double>::max();
                for (auto& child : currentNode->children) {
                    if (child.second->numEntries < minValue) {
                        minValue = child.second->numEntries;
                        minIndex = child.first;
                    }
                }

                // Remove the least significant branch from the node
                currentNode->children.erase(minIndex);

                for (auto& child : currentNode->children) {
                    this->pruneLessSignificantBranches(child.second);
                }
            }
        };

        // Vector to store the nodes of the octree
        Node** nodes;

        // Feature size, number of leaf nodes, and data capacity for the octree
        int featureSize;
        int numLeafNodes;
        int dataCapacity;

        // Function to initialize the octree with given parameters
        void init(int featureSize, int numLeafNodes, int dataCapacity) {
            this->featureSize = featureSize;
            this->numLeafNodes = numLeafNodes;
            this->dataCapacity = dataCapacity;
            this->nodes = new Node*[dataCapacity];
        }
};
