#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <sys/time.h>
#include <pthread.h>
#include <assert.h>

// Macro for logging
#define LOG(format, ...) \
    printf("[%d] " format "\n", __LINE__, ##__VA_ARGS__);

// Structure to store configuration data for the network interface
struct config {
    int buffer_size;  // Size of the buffer for storing MAC frames
    int num_threads;  // Number of threads to use for concurrent access
    int thread_id;    // Thread ID for current thread
};

// Structure to store data for a single MAC frame
struct mac_frame {
    struct timeval timestamp;   // Timestamp for the frame
    unsigned char *data;       // Payload of the frame
    size_t len;               // Length of the payload
};

// Structure to store metadata for a single MAC frame
struct mac_metadata {
    int seq_num;          // Sequence number of the frame
    unsigned char type;   // Type of the frame (e.g., control, data)
};

// Function to initialize the configuration structure with default values
