// Define a list data structure to hold the dynamically resizable list of nfapi_message_t structures
typedef struct nfapi_list {
    size_t count;
    size_t capacity;
    nfapi_message_t *messages;
} nfapi_list_t;

// Define a mutex to protect the list from concurrent access
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

void nfapi_list_init(nfapi_list_t *list) {
    // Initialize the list with a capacity of 0 and no messages
    list->count = 0;
    list->capacity = 0;
    list->messages = NULL;
}

void nfapi_list_add(nfapi_list_t *list, NFAPI_L1_DLSYNCH_IND_T *dl_synch) {
    // Acquire the mutex to protect the list from concurrent access
    pthread_mutex_lock(&list_mutex);

    // Increase the capacity of the list if necessary
    if (list->count == list->capacity) {
        list->capacity *= 2;
        list->messages = realloc(list->messages, sizeof(nfapi_message_t) * list->capacity);
    }

    // Add the new message to the end of the list
    nfapi_message_t *new_message = &list->messages[list->count];
    new_message->dl_synch = dl_synch;
    list->count++;

    // Release the mutex to allow other threads to access the list
    pthread_mutex_unlock(&list_mutex);
}

void nfapi_list_remove(nfapi_list_t *list, size_t index) {
    // Acquire the mutex to protect the list from concurrent access
    pthread_mutex_lock(&list_mutex);

    // Swap the removed message with the last message in the list and decrease the count
    nfapi_message_t *removed_message = &list->messages[index];
    nfapi_message_t *last_message = &list->messages[list->count - 1];
    removed_message->dl_synch = last_message->dl_synch;
    list->count--;

    // Release the mutex to allow other threads to access the list
    pthread_mutex_unlock(&list_mutex);
}

void nfapi_list_free(nfapi_list_t *list) {
    // Acquire the mutex to protect the list from concurrent access
    pthread_mutex_lock(&list_mutex);

    // Free the memory used by the list
    free(list->messages);
    list->messages = NULL;
    list->count = 0;
    list->capacity = 0;

    // Release the mutex to allow other threads to access the list
    pthread_mutex_unlock(&list_mutex);
}

// Define a function to update the parameters of an existing message in the list
void nfapi_list_update(nfapi_list_t *list, size_t index, NFAPI_L1_DLSYNCH_IND_T *dl_synch) {
    // Acquire the mutex to protect the list from concurrent access
    pthread_mutex_lock(&list_mutex);

    // Update the parameters of the message at the given index
    nfapi_message_t *message = &list->messages[index];
    message->dl_synch = dl_synch;

    // Release the mutex to allow other threads to access the list
    pthread_mutex_unlock(&list_mutex);
}
