// Define the structure for a record in the array
typedef struct {
    int key;
    double value;
} Record;

// Define the statistics structure to track multiple metrics
typedef struct {
    // Average, maximum, minimum, and sum values of all records
    double avg;
    double max;
    double min;
    double sum;
} Statistics;

// Function to insert a new record into the array
int insertRecord(Record* arr, int size, Record record) {
    // Check if the array is full
    if (size == 0) {
        return -1;
    }

    // Insert the record at the end of the array
    arr[size] = record;

    // Update the statistics structure with the new record's value
    Statistics* stats = getStatistics(arr, size);
    stats->sum += record.value;
    stats->avg = stats->sum / (double)size;
    if (record.value > stats->max) {
        stats->max = record.value;
    } else if (record.value < stats->min || size == 1) {
        stats->min = record.value;
    }

    // Return the new size of the array
    return size + 1;
}

// Function to retrieve the current statistics from the array
Statistics getStatistics(Record* arr, int size) {
    Statistics stats;
    stats.sum = 0;
    stats.avg = 0;
    stats.max = -DBL_MAX;
    stats.min = DBL_MAX;

    // Iterate over the array and calculate the sum, average, maximum, and minimum values
    for (int i = 0; i < size; i++) {
        stats.sum += arr[i].value;
        if (arr[i].value > stats.max) {
            stats.max = arr[i].value;
        } else if (arr[i].value < stats.min || i == 0) {
            stats.min = arr[i].value;
        }
    }

    // Return the statistics structure
    return stats;
}

// Function to update the statistics structure when a record is removed from the array
void removeRecord(Record* arr, int size, Record record) {
    Statistics* stats = getStatistics(arr, size);

    // Update the sum and average values
    stats->sum -= record.value;
    if (size > 1) {
        stats->avg = stats->sum / (double)(size - 1);
    } else {
        stats->avg = 0;
    }

    // Update the maximum and minimum values
    if (stats->max == record.value) {
        for (int i = 0; i < size; i++) {
            if (arr[i].value > stats->max) {
                stats->max = arr[i].value;
                break;
            }
        }
    } else if (stats->min == record.value) {
        for (int i = 0; i < size; i++) {
            if (arr[i].value < stats->min || i == 0) {
                stats->min = arr[i].value;
                break;
            }
        }
    }
}

// Function to handle concurrent updates from multiple threads without data corruption
void* insertRecordConcurrent(Record* arr, int size, Record record) {
    // Create a copy of the array and statistics structure
    Record* arrCopy = malloc(size * sizeof(Record));
    Statistics stats;
    for (int i = 0; i < size; i++) {
        arrCopy[i] = arr[i];
    }

    // Calculate the new size of the array and update the statistics structure
    int newSize = insertRecord(arrCopy, size, record);
    stats = getStatistics(arrCopy, newSize);

    // Free the old array and replace it with the new one
    free(arr);
    arr = malloc(newSize * sizeof(Record));
    for (int i = 0; i < newSize; i++) {
        arr[i] = arrCopy[i];
    }

    // Update the statistics structure in the main thread
    Statistics* statsMain = getStatistics(arr, size);
    *statsMain = stats;

    // Free the copy of the array and return
    free(arrCopy);
    return NULL;
}

// Function to handle concurrent updates from multiple threads without data corruption
void* removeRecordConcurrent(Record* arr, int size, Record record) {
    // Create a copy of the array and statistics structure
    Record* arrCopy = malloc(size * sizeof(Record));
    Statistics stats;
    for (int i = 0; i < size; i++) {
        arrCopy[i] = arr[i];
    }

    // Remove the record from the copy of the array and update the statistics structure
    removeRecord(arrCopy, size, record);
    stats = getStatistics(arrCopy, size - 1);

    // Free the old array and replace it with the new one
    free(arr);
    arr = malloc((size - 1) * sizeof(Record));
    for (int i = 0; i < size - 1; i++) {
        arr[i] = arrCopy[i];
    }

    // Update the statistics structure in the main thread
    Statistics* statsMain = getStatistics(arr, size);
    *statsMain = stats;

    // Free the copy of the array and return
    free(arrCopy);
    return NULL;
}
