// Define a concurrent HTTP client for interacting with a remote API service
void init_concurrent_http_client(HTTP_CLIENT *client) {
  // Initialize the HTTP client structure
  memset(client, 0, sizeof(HTTP_CLIENT));

  // Set the maximum number of concurrent requests to handle
  client->max_requests = MAX_REQUESTS;

  // Initialize the request queue semaphore with a count of zero
  client->request_queue_sem = sem_open("request_queue", O_CREAT, S_IRUSR | S_IWUSR, 0);

  // Initialize the response queue semaphore with a count of zero
  client->response_queue_sem = sem_open("response_queue", O_CREAT, S_IRUSR | S_IWUSR, 0);

  // Create a thread pool for handling concurrent requests
  pthread_t request_handler_thread;
  int err = pthread_create(&request_handler_thread, NULL, handle_requests, client);
  if (err != 0) {
    printf("Error creating request handler thread: %s\n", strerror(err));
  }
}

// Helper function for handling concurrent requests in the HTTP client
void *handle_requests(void *arg) {
  // Cast the argument to an HTTP client structure
  HTTP_CLIENT *client = (HTTP_CLIENT *)arg;

  // Loop until all requests have been handled or the thread is terminated
  while (1) {
    // Wait for a request to become available in the request queue semaphore
    sem_wait(client->request_queue_sem);

    // Check if there are any more requests to handle
    if (client->current_requests < client->max_requests) {
      // Handle the next request and update the current request count
      handle_next_request(client);
    } else {
      // If there are no more requests to handle, exit the thread
      break;
    }
  }
}

// Helper function for handling a single request in the HTTP client
void handle_next_request(HTTP_CLIENT *client) {
  // Increment the current request count
  client->current_requests++;

  // Send the request to the remote API service using cURL
  CURL *curl = curl_easy_init();
  if (curl) {
    // Set the URL, HTTP method, and custom headers for the request
    char *url = "https://api.example.com/crc_indication";
    char *method = "POST";
    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    headers = curl_slist_append(headers, "Authorization: Bearer <API_KEY>");
    headers = curl_slist_append(headers, "X-HTTP-Method-Override: POST");

    // Set the cURL options for the request
    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_CUSTOMREQUEST, method);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

    // Set the data to be sent in the request body
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pdu->rx_ue_information_tag = RX_UE_INFORMATION_TAG(client->current_requests);
    pdu->rnti = rand() % 65535 + 1;
    pdu->crc_indication_rel8_tag = CRC_INDICATION_REL8_TAG(client->current_requests);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, pdu);

    // Perform the request and check for any errors
    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
      printf("cURL error: %s\n", curl_easy_strerror(res));
    }

    // Free the memory used for the request data structure
    free(pdu);
  }

  // Decrement the current request count and signal the response queue semaphore
  client->current_requests--;
  sem_post(client->response_queue_sem);
}

int main() {
  // Create an HTTP client structure for handling concurrent requests
  HTTP_CLIENT *client = (HTTP_CLIENT *)malloc(sizeof(HTTP_CLIENT));

  // Initialize the HTTP client structure and create a thread pool for handling concurrent requests
  init_http_client(client);
  pthread_t request_handler_thread;
  int err = pthread_create(&request_handler_thread, NULL, handle_requests, client);
  if (err != 0) {
    printf("Error creating request handler thread: %s\n", strerror(err));
  }

  // Loop until all requests have been handled or the program is terminated
  while (1) {
    // Check if there are any more requests to handle
    if (client->current_requests < MAX_REQUESTS) {
      // Handle the next request and update the current request count
      handle_next_request(client);
    } else {
      // If there are no more requests to handle, exit the program
      break;
    }
  }
