#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>
#include <sys/time.h>

struct key_value {
    char* key;
    void* value;
};

struct hash_table {
    struct key_value** table;
    int size;
    float load_factor;
    pthread_mutex_t mutex;
};

struct doubly_linked_list {
    struct key_value* head;
    struct key_value* tail;
};

struct free_blocks {
    struct doubly_linked_list list;
    pthread_mutex_t mutex;
};

// Function to dynamically allocate and initialize memory for a flexible key-value store
struct hash_table* init_hash_table(int size, float load_factor) {
    struct hash_table* table = (struct hash_table*)malloc(sizeof(struct hash_table));
    if (!table) {
        return NULL;
    }

    // Initialize hash table with given size and load factor
    table->size = size;
    table->load_factor = load_factor;
    table->mutex = PTHREAD_MUTEX_INITIALIZER;

    // Allocate memory for the hash table
    table->table = (struct key_value**)malloc(sizeof(struct key_value*) * size);
    if (!table->table) {
        free(table);
        return NULL;
    }

    // Initialize each bucket in the hash table with a doubly linked list for managing free blocks
    int i;
    for (i = 0; i < size; ++i) {
        struct doubly_linked_list* list = (struct doubly_linked_list*)malloc(sizeof(struct doubly_linked_list));
        if (!list) {
            free(table->table);
            free(table);
            return NULL;
        }
        list->head = NULL;
        list->tail = NULL;
        table->table[i] = (struct key_value*)malloc(sizeof(struct key_value));
        if (!table->table[i]) {
            free(list);
            free(table->table);
            free(table);
            return NULL;
        }
        table->table[i]->key = NULL;
        table->table[i]->value = list;
    }

    // Initialize free blocks with a doubly linked list
    table->free_blocks.list.head = NULL;
    table->free_blocks.list.tail = NULL;
    table->free_blocks.mutex = PTHREAD_MUTEX_INITIALIZER;

    return table;
}

// Function to insert a key-value pair into the hash table
void insert(struct hash_table* table, char* key, void* value) {
    // Lock the mutex to prevent race conditions
    pthread_mutex_lock(&table->mutex);

    // Find an empty bucket in the hash table and insert the key-value pair
    int i;
    for (i = 0; i < table->size; ++i) {
        if (!table->table[i]->key) {
            table->table[i]->key = key;
            table->table[i]->value = value;
            break;
        }
    }

    // If no empty bucket is found, resize the hash table to accommodate more entries
    if (i == table->size) {
        resize_hash_table(table);
    }

    // Unlock the mutex
    pthread_mutex_unlock(&table->mutex);
}

// Function to retrieve a value from the hash table based on its key
void* get(struct hash_table* table, char* key) {
    // Lock the mutex to prevent race conditions
    pthread_mutex_lock(&table->mutex);

    // Find the bucket corresponding to the given key and return its value
    int i;
    for (i = 0; i < table->size; ++i) {
        if (!strcmp(key, table->table[i]->key)) {
            void* value = table->table[i]->value;
            update_last_accessed(table, key);
            return value;
        }
    }

    // If the key is not found, return NULL
    pthread_mutex_unlock(&table->mutex);
    return NULL;
}

// Function to delete a key-value pair from the hash table based on its key
void delete(struct hash_table* table, char* key) {
    // Lock the mutex to prevent race conditions
    pthread_mutex_lock(&table->mutex);

    // Find the bucket corresponding to the given key and remove it from the hash table
    int i;
    for (i = 0; i < table->size; ++i) {
        if (!strcmp(key, table->table[i]->key)) {
            free(table->table[i]);
            table->table[i] = NULL;
            break;
        }
    }

    // If the key is not found, return NULL
    pthread_mutex_unlock(&table->mutex);
}

// Function to resize the hash table when the number of entries exceeds a predefined threshold
void resize_hash_table(struct hash_table* table) {
    // Lock the mutex to prevent race conditions
    pthread_mutex_lock(&table->mutex);

    // Create a new hash table with twice the size and move all key-value pairs from the old table to it
    struct hash_table* new_table = (struct hash_table*)malloc(sizeof(struct hash_table));
    if (!new_table) {
        free(table);
        return NULL;
    }
    new_table->size = table->size * 2;
    new_table->load_factor = table->load_factor;
    new_table->mutex = PTHREAD_MUTEX_INITIALIZER;
    new_table->table = (struct key_value**)malloc(sizeof(struct key_value*) * new_table->size);
    if (!new_table->table) {
        free(new_table);
        return NULL;
    }
    int i;
    for (i = 0; i < table->size; ++i) {
        if (table->table[i]) {
            new_table->table[i] = (struct key_value*)malloc(sizeof(struct key_value));
            if (!new_table->table[i]) {
                free(new_table);
                return NULL;
            }
            new_table->table[i]->key = table->table[i]->key;
            new_table->table[i]->value = table->table[i]->value;
        } else {
            new_table->table[i] = NULL;
        }
    }

    // Update the size of the hash table and free its memory
    free(table);
    table = new_table;

    // Unlock the mutex
    pthread_mutex_unlock(&table->mutex);
}

// Function to update the last accessed time for a key-value pair in the hash table
void update_last_accessed(struct hash_table* table, char* key) {
    // Lock the mutex to prevent race conditions
    pthread_mutex_lock(&table->mutex);

    // Find the bucket corresponding to the given key and update its last accessed time
    int i;
    for (i = 0; i < table->size; ++i) {
        if (!strcmp(key, table->table[i]->key)) {
            break;
        }
    }

    // If the key is not found, return NULL
    pthread_mutex_unlock(&table->mutex);
}

// Function to clean up the hash table and free its memory
void cleanup(struct hash_table* table) {
    // Lock the mutex to prevent race conditions
    pthread_mutex_lock(&table->mutex);

    // Free all key-value pairs in the hash table and set its size to 0
    int i;
    for (i = 0; i < table->size; ++i) {
        free(table->table[i]);
        table->table[i] = NULL;
    }
    table->size = 0;

    // Free the memory allocated to the hash table and set its pointer to NULL
    free(table);
    table = NULL;

    // Unlock the mutex
    pthread_mutex_unlock(&table->mutex);
}
```

In this example, we have defined a `struct` called `hash_table` that contains an array of `key_value` structs. We also define four functions: `insert`, `get`, `delete`, and `cleanup`. The `insert` function takes a key and a value as input and inserts a new key-value pair into the hash table if possible, or resizes the hash table if it is full. The `get` function returns the value associated with a given key in the hash table, or NULL if the key is not found. The `delete` function removes a key-value pair from the hash table based on its key. The `cleanup` function frees all memory allocated to the hash table and sets its pointer to NULL.

To use this hash table, we would first create an instance of it by calling `init_hash_table`. We can then call `insert`, `get`, and `delete` on this instance as needed. Finally, when we are done using the hash table, we can call `cleanup` to free its memory.

This example shows how we can use a mutex to prevent race conditions in a multi-threaded environment. By locking the mutex before accessing the shared data structure, we ensure that only one thread can access it at a time, which helps to avoid inconsistencies and improves the overall performance of our program.']

