        struct Node *newNode = malloc(sizeof(struct Node));

        // Set the RX_UE_INFORMATION_TAG and CRCFLAG for the current node
        newNode->data.RX_UE_INFORMATION_TAG = rxUeInformationTag;
        newNode->data.CRCFLAG = crcFlag;

        // Generate a random RNTI value for the current node
        newNode->data.RNTI = rand() % 65535 + 1;

        // Check if the current RNTI already exists in the list
        struct Node *currNode = head;
        while (currNode != NULL) {
            if (newNode->data.RNTI == currNode->data.RNTI) {
                // If the RNTI already exists, regenerate a new value
                newNode->data.RNTI = rand() % 65535 + 1;
                break;
            }
            currNode = currNode->next;
        }

        // Add the new node to the list
        if (head == NULL) {
            head = newNode;
        } else {
            struct Node *currNode = head;
            while (currNode->next != NULL) {
                currNode = currNode->next;
            }
            currNode->next = newNode;
        }
    }
}

