// Structure to hold configuration parameters for a network interface
struct NetworkInterfaceConfig {
    int interfaceId;
    struct NeighborCellInfo *neighborCellList;
    struct SRSParameters srsParams;
};

// Structure to hold information about neighbor cells
struct NeighborCellInfo {
    int cellId;
    char *cellName;
