#define HASH_TABLE_SIZE 1024
int *hash_table = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to dynamically allocate memory for the data structures
void init_data_structures(int num_products, int num_customers) {
    products = (product_t *)malloc(num_products * sizeof(product_t));
    product_ids = (short *)malloc(num_products * sizeof(short));
    customers = (customer_t *)malloc(num_customers * sizeof(customer_t));
