        strcat(p->name, itoa(i));
        p->quantity = rand() % 50;
    }
    for (j = 0; j < num_customers; ++j) {
        customer_t *c = customers + j;
        c->membership_level = rand() % 10;
        strcpy(c->email, "customer");
        strcat(c->email, itoa(j));
    }
}

// Function to add a new product to the inventory and customer database
void add_product(int id, double price, char *name, int quantity) {
    pthread_mutex_lock(&mutex);
    // Check if the product already exists in the system
    for (int i = 0; i < num_products; ++i) {
        if (product_ids[i] == id) {
            printf("Product with ID %d already exists\n", id);
            pthread_mutex_unlock(&mutex);
            return;
        }
    }
    // Add the new product to the inventory and customer database
    product_ids[num_products] = id;
    products[num_products].price = price;
    strcpy(products[num_products].name, name);
    products[num_products].quantity = quantity;
    ++num_products;
    pthread_mutex_unlock(&mutex);
}

// Function to add a new customer to the inventory and customer database
void add_customer(char *email, int membership_level) {
    pthread_mutex_lock(&mutex);
    // Check if the customer already exists in the system
    for (int i = 0; i < num_customers; ++i) {
        if (!strcmp(customers[i].email, email)) {
            printf("Customer with email %s already exists\n", email);
            pthread_mutex_unlock(&mutex);
            return;
        }
    }
    // Add the new customer to the inventory and customer database
    strcpy(customers[num_customers].email, email);
    customers[num_customers].membership_level = membership_level;
    ++num_customers;
    pthread_mutex_unlock(&mutex);
}

// Function to retrieve the product with a given ID from the inventory
product_t *get_product(int id) {
    pthread_mutex_lock(&mutex);
    // Search for the product in the inventory
    for (int i = 0; i < num_products; ++i) {
        if (product_ids[i] == id) {
            return products + i;
        }
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

// Function to retrieve the customer with a given email from the inventory and customer database
customer_t *get_customer(char *email) {
    pthread_mutex_lock(&mutex);
    // Search for the customer in the inventory and customer database
    for (int i = 0; i < num_customers; ++i) {
        if (!strcmp(customers[i].email, email)) {
            return customers + i;
        }
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

// Function to update the quantity of a product in the inventory
void update_product(int id, int new_quantity) {
    pthread_mutex_lock(&mutex);
    // Search for the product in the inventory
    for (int i = 0; i < num_products; ++i) {
        if (product_ids[i] == id) {
            products[i].quantity = new_quantity;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

// Function to update the membership level of a customer in the inventory and customer database
void update_customer(char *email, int new_membership_level) {
    pthread_mutex_lock(&mutex);
    // Search for the customer in the inventory and customer database
    for (int i = 0; i < num_customers; ++i) {
        if (!strcmp(customers[i].email, email)) {
            customers[i].membership_level = new_membership_level;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

// Function to print the inventory and customer database
void print_inventory() {
    printf("Inventory:\n");
    for (int i = 0; i < num_products; ++i) {
        printf("%d: %s (%d)\n", product_ids[i], products[i].name, products[i].quantity);
    }
    printf("Customer Database:\n");
    for (int i = 0; i < num_customers; ++i) {
        printf("%s: %d\n", customers[i].email, customers[i].membership_level);
    }
}

// Function to handle a new order from the customer
void handle_order(char *email, int id, int quantity) {
    pthread_mutex_lock(&mutex);
    // Search for the product in the inventory
    product_t *product = get_product(id);
    if (product == NULL) {
        printf("Product with ID %d does not exist\n", id);
        pthread_mutex_unlock(&mutex);
        return;
    }
    // Check if the product is available in the requested quantity
    if (product->quantity < quantity) {
        printf("Insufficient inventory for product with ID %d\n", id);
        pthread_mutex_unlock(&mutex);
        return;
    }
    // Update the inventory and customer database
    update_product(id, product->quantity - quantity);
    update_customer(email, get_customer(email)->membership_level + 1);
    pthread_mutex_unlock(&mutex);
}

int main() {
    // Initialize the inventory and customer database
    initialize();

    // Add a new product to the inventory and customer database
    add_product(1, 20.99, "Product 1", 5);

    // Add a new customer to the inventory and customer database
    add_customer("customer@email.com", 1);

    // Print the inventory and customer database
    print_inventory();

    // Handle a new order from a customer
    handle_order("customer@email.com", 1, 2);

    return 0;
}
