// Function to initialize and populate the pool of NFAPI_CRC_INDICATION_PDU_T structures
void init_pool() {
    if (pool == NULL) {
        // Allocate memory for the pool
        pool = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * pool_capacity);
        if (pool == NULL) {
            fprintf(stderr, "Failed to allocate memory for the NFAPI CRC indication PDU pool\n");
            exit(1);
        }
    }
}

// Function to retrieve an unused structure from the pool
NFAPI_CRC_INDICATION_PDU_T *get_unused_structure() {
    pthread_mutex_lock(&pool_mutex);
    for (size_t i = 0; i < pool_capacity; i++) {
        if (!pool[i].rx_ue_information.valid) {
            // Structure is unused, return it
            pool[i].rx_ue_information.valid = true;
            pthread_mutex_unlock(&pool_mutex);
            return &pool[i];
        }
    }
    pthread_mutex_unlock(&pool_mutex);
    // No unused structures found, expand the pool if necessary
    if (pool_size < pool_capacity) {
        NFAPI_CRC_INDICATION_PDU_T *new_struct = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_struct == NULL) {
            fprintf(stderr, "Failed to allocate memory for a new NFAPI CRC indication PDU structure\n");
            exit(1);
        }
        pool[pool_size++] = *new_struct;
    } else {
        // No more space in the pool, return NULL
        return NULL;
    }
}

// Function to release a structure back to the pool
void release_structure(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&pool_mutex);
    for (size_t i = 0; i < pool_capacity; i++) {
        if (&pool[i] == pdu) {
            // Structure found, mark it as unused
            pool[i].rx_ue_information.valid = false;
            pthread_mutex_unlock(&pool_mutex);
            return;
        }
    }
    pthread_mutex_unlock(&pool_mutex);
}

// Function to log debug information to a file
