// Define the structure for LTE_NAS_Message
typedef struct {
    NAS_PDU *nas_pdu;
    int nas_transaction_id;
} LTE_NAS_Message;

// Define the function to initialize and configure the dynamic collection of LTE_NAS_Message structures
int init_and_configure_lte_nas_message(LTE_NAS_Message **messages, size_t num_messages) {
    // Allocate memory for the array of LTE_NAS_Message structures
    *messages = (LTE_NAS_Message *)malloc(num_messages * sizeof(LTE_NAS_Message));
    if (*messages == NULL) {
        perror("Failed to allocate memory for LTE_NAS_Message array");
        return -1;
    }

    // Initialize each LTE_NAS_Message structure with a valid NAS_PDU and corresponding NAS_Transaction_ID
    for (size_t i = 0; i < num_messages; i++) {
        (*messages)[i].nas_pdu = NULL;
        (*messages)[i].nas_transaction_id = -1;
    }

    // Initialize the semaphore to manage access to the LTE_NAS_Message array
    sem_t *sem = (sem_t *)malloc(sizeof(sem_t));
    if (sem == NULL) {
        perror("Failed to allocate memory for semaphore");
        return -1;
    }
    int ret = sem_init(sem, 0, num_messages);
    if (ret != 0) {
        perror("Failed to initialize semaphore");
        return -1;
    }

    // Initialize the mutex to manage access to the LTE_NAS_Message array in a multi-threaded environment
    pthread_mutex_t *mutex = (pthread_mutex_t *)malloc(sizeof(pthread_mutex_t));
    if (mutex == NULL) {
        perror("Failed to allocate memory for mutex");
        return -1;
    }
    ret = pthread_mutex_init(mutex, NULL);
    if (ret != 0) {
        perror("Failed to initialize mutex");
        return -1;
    }

    // Initialize the condition variable to manage synchronization between threads
    pthread_cond_t *cond = (pthread_cond_t *)malloc(sizeof(pthread_cond_t));
    if (cond == NULL) {
        perror("Failed to allocate memory for condition variable");
        return -1;
    }
    ret = pthread_cond_init(cond, NULL);
    if (ret != 0) {
        perror("Failed to initialize condition variable");
        return -1;
    }

    // Return the initialized LTE_NAS_Message array and other synchronization primitives
    *sem = sem;
    *mutex = mutex;
    *cond = cond;
    return 0;
}

// Define the function to add a new LTE_NAS_Message structure to the dynamic collection
int add_lte_nas_message(LTE_NAS_Message **messages, size_t num_messages, NAS_PDU *nas_pdu, int nas_transaction_id) {
    // Acquire a lock on the semaphore to ensure exclusive access to the LTE_NAS_Message array
    if (sem_wait((*sem)) != 0) {
        perror("Failed to acquire semaphore");
        return -1;
    }

    // Ensure that there is enough memory allocated for the new structure
    if (num_messages >= (*messages)->size) {
        LTE_NAS_Message *new_messages = (LTE_NAS_Message *)realloc((*messages), 2 * num_messages * sizeof(LTE_NAS_Message));
        if (new_messages == NULL) {
            perror("Failed to reallocate memory for LTE_NAS_Message array");
            return -1;
        }
        (*messages) = new_messages;
    }

    // Add the new structure to the end of the array
    (*messages)[num_messages].nas_pdu = nas_pdu;
    (*messages)[num_messages].nas_transaction_id = nas_transaction_id;
    num_messages++;

    // Release the lock on the semaphore and return the updated number of messages
    if (sem_post((*sem)) != 0) {
        perror("Failed to release semaphore");
        return -1;
    }
    return num_messages;
}

// Define the function to remove a LTE_NAS_Message structure from the dynamic collection
int remove_lte_nas_message(LTE_NAS_Message **messages, size_t *num_messages, int nas_transaction_id) {
    // Acquire a lock on the semaphore to ensure exclusive access to the LTE_NAS_Message array
    if (sem_wait((*sem)) != 0) {
        perror("Failed to acquire semaphore");
        return -1;
    }

    // Find the structure with the corresponding NAS_Transaction_ID and remove it from the array
    for (size_t i = 0; i < *num_messages; i++) {
        if ((*messages)[i].nas_transaction_id == nas_transaction_id) {
            (*messages)[i] = (*messages)[(*num_messages) - 1];
            (*num_messages)--;
            break;
        }
    }

    // Release the lock on the semaphore and return the updated number of messages
    if (sem_post((*sem)) != 0) {
        perror("Failed to release semaphore");
        return -1;
    }
    return *num_messages;
}

// Define the function to process a batch of LTE_NAS_Message structures in a non-blocking manner
int process_lte_nas_message_batch(LTE_NAS_Message **messages, size_t num_messages, int max_messages) {
    // Acquire a lock on the mutex to ensure exclusive access to the LTE_NAS_Message array in a multi-threaded environment
    if (pthread_mutex_lock((*mutex)) != 0) {
        perror("Failed to acquire mutex");
        return -1;
    }

    // Process up to max_messages messages from the beginning of the array, removing them from the array as they are processed
    for (size_t i = 0; i < max_messages && (*num_messages) > 0; i++) {
        // Process the current message and remove it from the array
        process_lte_nas_message(&(*messages)[i]);
        (*messages)[i] = (*messages)[(*num_messages) - 1];
        (*num_messages)--;
    }

    // Release the lock on the mutex and return the updated number of messages
    if (pthread_mutex_unlock((*mutex)) != 0) {
        perror("Failed to release mutex");
        return -1;
    }
    return *num_messages;
}

// Define the function to process a single LTE_NAS_Message structure in a blocking manner
int process_lte_nas_message(LTE_NAS_Message **messages, size_t num_messages) {
    // Acquire a lock on the mutex to ensure exclusive access to the LTE_NAS_Message array in a multi-threaded environment
    if (pthread_mutex_lock((*mutex)) != 0) {
        perror("Failed to acquire mutex");
        return -1;
    }

    // Process the current message and remove it from the array
    process_lte_nas_message(&(*messages)[num_messages]);
    (*messages)[num_messages] = (*messages)[(*num_messages) - 1];
    (*num_messages)--;

    // Release the lock on the mutex and return the updated number of messages
    if (pthread_mutex_unlock((*mutex)) != 0) {
        perror("Failed to release mutex");
        return -1;
    }
    return *num_messages;
}
