            fprintf(stderr, "Sending message...\n");
            current_tail++;
            queue_full = false;
        }

        // Check if we need to update the buffer policy
        switch (constraints->buffer_policy) {
            case BUFFER_POLICY_FIFO:
                fprintf(stderr, "Updating buffer policy to FIFO...\n");
                break;
            case BUFFER_POLICY_LIFO:
