typedef struct record {
    long offset;
    int key;
    char descriptor[256];
} Record;

Record* manageRecords(int numRecords, int maxOffsetValue, int minKeyValue, int maxKeyValue, const char* descriptors) {
    // Validate input parameters
    if (numRecords <= 0 || maxOffsetValue < 1 || minKeyValue > maxKeyValue || !descriptors) {
        return NULL;
    }

    // Initialize random number generator
    srand(time(NULL));

    // Allocate memory for records and arrays
    Record* records = (Record*)malloc(numRecords * sizeof(Record));
    long* offsets = (long*)malloc(numRecords * sizeof(long));
    int* keys = (int*)malloc(numRecords * sizeof(int));
    char* descriptors_ = (char*)malloc(numRecords * 256);

    // Check for allocation failures
    if (!records || !offsets || !keys || !descriptors_) {
        free(records);
        free(offsets);
        free(keys);
        free(descriptors_);
        return NULL;
    }

    // Initialize records and arrays
    for (int i = 0; i < numRecords; ++i) {
        records[i].offset = rand() % maxOffsetValue + 1;
        records[i].key = rand() % (maxKeyValue - minKeyValue + 1) + minKeyValue;
        memcpy(records[i].descriptor, descriptors, 256);

        offsets[i] = records[i].offset;
        keys[i] = records[i].key;
    }

    // Create a mapping from records to their corresponding arrays elements
    int* recordToIndex = (int*)malloc(numRecords * sizeof(int));
    for (int i = 0; i < numRecords; ++i) {
        recordToIndex[i] = i;
    }

    // Create a mapping from arrays elements to their corresponding records
    int* indexToRecord = (int*)malloc(numRecords * sizeof(int));
    for (int i = 0; i < numRecords; ++i) {
        indexToRecord[i] = recordToIndex[i];
    }

    // Initialize the function's return value to the first record
    Record* retVal = records;

    // Free memory when done
    free(records);
    free(offsets);
    free(keys);
    free(descriptors_);
    free(recordToIndex);
    free(indexToRecord);

    return retVal;
}
```
