            if (record[i].value == SUCCESS) {
                num_successful_connections++;
            } else {
                num_failed_connections++;
            }
        }
        offset_sum += num_successful_connections * MAX_OFFSET;
        key_count += num_successful_connections * MAX_KEY;

        // Check and reset global statistics counter if necessary
        if (key_count > MAX_STATISTICS_COUNT) {
            key_count = 0;
            offset_sum = 0;
            record_list = NULL;
        }
    }
}

// Function to get current statistics from global counter
struct record *get_statistics() {
    struct record *record = (struct record *)malloc(sizeof(struct record));
    if (record_list == NULL) {
        // Initialize record list with random values within specified range
        for (int i = 0; i < num_servers; i++) {
            record[i].value = rand() % MAX_RECORD;
        }
        record_list = record;
    } else {
        // Update record list with new values from global counter
        for (int i = 0; i < num_servers; i++) {
            record[i].value = offset_sum / key_count;
        }
    }
    return record;
}
```
