    struct list_head active_rb; // List of active radio bearers
    timestamp_t last_attempt; // Timestamp for the last successful connection attempt
};

// Define structure to represent a radio bearer record
struct rb_record {
    uint32_t id; // Unique identifier for the radio bearer
    struct ue_connection_record *ue; // Pointer to the UE connection record
};

// Define a dynamic list of UE connection records, with thread-safe operations and memory management
struct ue_connection_list {
    pthread_mutex_t lock; // Mutex for synchronizing access to the list
    struct list_head head; // Head node of the list
    size_t capacity; // Current capacity of the list (in number of UE connection records)
};

// Define a function to initialize the UE connection list with a specified initial capacity
void init_ue_connection_list(struct ue_connection_list *list, size_t capacity) {
    pthread_mutex_init(&list->lock, NULL);
    INIT_LIST_HEAD(&list->head);
    list->capacity = capacity;
}

// Define a function to add a new UE connection record to the list
void add_ue_connection(struct ue_connection_list *list, struct ue_connection_record *rec) {
    pthread_mutex_lock(&list->lock);
    // Check if there is enough capacity in the list for the new UE connection record
    if (list->capacity > 0 && list->size >= list->capacity) {
        // Resize the list by doubling its capacity
        size_t new_cap = list->capacity * 2;
        struct ue_connection_record *new_rec = realloc(NULL, sizeof(*new_rec));
        if (!new_rec) {
            pthread_mutex_unlock(&list->lock);
            return; // Failed to resize the list
        }
        new_rec->id = rec->id;
        INIT_LIST_HEAD(&new_rec->active_rb);
        new_rec->last_attempt = rec->last_attempt;
        // Add the new UE connection record to the end of the list
        list->size++;
        __list_add(&new_rec->node, &list->head.prev, &list->head);
        // Free the memory for the old records that were evicted from the list
        struct ue_connection_record *old_rec = NULL;
        while (!IS_LIST_EMPTY(&list->head)) {
            old_rec = LIST_ENTRY(struct ue_connection_record, &list->head);
            __list_del(&old_rec->node);
            free(old_rec);
        }
        list->capacity = new_cap;
    } else {
        // Add the new UE connection record to the end of the list
        list->size++;
        __list_add(&rec->node, &list->head.prev, &list->head);
    }
    pthread_mutex_unlock(&list->lock);
}

// Define a function to remove an UE connection record from the list
void remove_ue_connection(struct ue_connection_list *list, uint32_t id) {
    pthread_mutex_lock(&list->lock);
    struct ue_connection_record *rec = NULL;
    list_for_each_entry(rec, &list->head, node) {
        if (rec->id == id) {
            __list_del(&rec->node);
            free(rec);
            break;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

// Define a function to get an UE connection record from the list by its unique identifier
struct ue_connection_record *get_ue_connection(struct ue_connection_list *list, uint32_t id) {
    pthread_mutex_lock(&list->lock);
    struct ue_connection_record *rec = NULL;
    list_for_each_entry(rec, &list->head, node) {
        if (rec->id == id) {
            break;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return rec;
}

// Define a function to get the active radio bearer record for an UE connection by its unique identifier
struct rb_record *get_active_rb(struct ue_connection_list *list, uint32_t id) {
    struct ue_connection_record *rec = get_ue_connection(list, id);
    if (!rec) {
        return NULL;
    }
    struct rb_record *rb = NULL;
    list_for_each_entry(rb, &rec->active_rb, node) {
        break;
    }
    return rb;
}

// Define a function to update the timestamp for an UE connection record based on its unique identifier
void update_ue_connection(struct ue_connection_list *list, uint32_t id) {
    struct ue_connection_record *rec = get_ue_connection(list, id);
    if (!rec) {
        return;
    }
    rec->last_attempt = get_timestamp(); // Get the current timestamp
}

// Define a function to update the active radio bearer record for an UE connection based on its unique identifier
void update_active_rb(struct ue_connection_list *list, uint32_t id) {
    struct rb_record *rb = get_active_rb(list, id);
    if (!rb) {
        return;
    }
    // Update the timestamp for the active radio bearer record
    update_ue_connection(list, id);
}

// Define a function to check if an UE connection is present in the list based on its unique identifier
bool has_ue_connection(struct ue_connection_list *list, uint32_t id) {
    pthread_mutex_lock(&list->lock);
    struct ue_connection_record *rec = NULL;
    list_for_each_entry(rec, &list->head, node) {
        if (rec->id == id) {
            break;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return !!rec;
}

// Define a function to check if an active radio bearer is present in the list based on its unique identifier
bool has_active_rb(struct ue_connection_list *list, uint32_t id) {
    struct rb_record *rb = get_active_rb(list, id);
    return !!rb;
}
