#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>
#include <math.h>
#include <mutex>

// Structure for storing the list of integers
struct Node {
  int data;
  struct Node* next;
  struct Node* prev;
};

// Function to create a new node in the doubly linked list
struct Node* createNode(int data) {
  struct Node* new_node = (struct Node*)malloc(sizeof(struct Node));
  new_node->data = data;
  new_node->next = NULL;
  new_node->prev = NULL;
  return new_node;
}

// Function to insert a node in the doubly linked list
void insertNode(struct Node** head_ref, int data) {
  struct Node* new_node = createNode(data);
  if (*head_ref == NULL) {
    *head_ref = new_node;
  } else {
    // Insert the node at the end of the list
    struct Node* last = *head_ref;
    while (last->next != NULL) {
      last = last->next;
    }
    last->next = new_node;
    new_node->prev = last;
  }
}

// Function to delete a node from the doubly linked list
void deleteNode(struct Node** head_ref, int data) {
  if (*head_ref == NULL) {
    return;
  }
  struct Node* current = *head_ref;
  // If the first node is to be deleted
  if (current->data == data) {
    *head_ref = current->next;
    free(current);
    return;
  }
  while (current->next != NULL) {
    if (current->next->data == data) {
      struct Node* temp = current->next;
      current->next = temp->next;
      free(temp);
      break;
    }
    current = current->next;
  }
}

// Function to traverse the doubly linked list and find the largest integer
int findLargest(struct Node* head) {
  int largest = INT_MIN;
  struct Node* current = head;
  while (current != NULL) {
    if (current->data > largest) {
      largest = current->data;
    }
    current = current->next;
  }
  return largest;
}

// Function to handle duplicate integers and ensure each integer is unique within the list
void handleDuplicates(struct Node** head_ref, int data) {
  struct Node* current = *head_ref;
  while (current != NULL && current->data != data) {
    if (current->next == NULL) {
      break;
    } else if (current->next->data == data) {
      deleteNode(head_ref, data);
      break;
    } else {
      current = current->next;
    }
  }
  insertNode(head_ref, data);
}

// Function to read integers from standard input and store them in the doubly linked list
void readInput(struct Node** head_ref) {
  int data;
  while (scanf("%d", &data) == 1) {
    handleDuplicates(head_ref, data);
  }
}

// Function to print the largest integer in the doubly linked list
void printLargest(struct Node* head) {
  int largest = findLargest(head);
  printf("%d\n", largest);
}

int main() {
  struct Node* head = NULL;
  readInput(&head);
  printLargest(head);
  return 0;
}
```
