// Function to execute a specified command in the background using fork and wait system calls
int execute_command(const char *command) {
  // Fork a new process to execute the specified command
  pid_t pid = fork();
  if (pid < 0) {
    printf("Failed to fork a new process\n");
    return -1;
  } else if (pid == 0) {
    // Execute the specified command in the child process
    execl("/bin/bash", "bash", "-c", command, (char *)NULL);
    printf("Failed to execute the specified command\n");
    return -1;
  } else {
    // Wait for the child process to complete execution and retrieve its exit status
    int status;
    waitpid(pid, &status, 0);
    if (WIFEXITED(status)) {
      return WEXITSTATUS(status);
    } else {
      printf("The specified command encountered an error\n");
      return -1;
    }
  }
}
