    if (!extracted_states) {
        printf("Error: Out of memory!\n");
        return;
    }

    // Extract the contiguous sequence of states from the FSA
    for (int i = start_state; i <= end_state; i++) {
        extracted_states[i - start_state] = fsa->transitions[i].to;
    }

    // Update all pointers within the FSA to prevent dangling references
    for (int i = 0; i < num_states; i++) {
        int *next_state = &fsa->transitions[start_state + i].to;
        *next_state = extracted_states[i];
    }

    // Free the extracted state sequence memory
    free(extracted_states);
