    }
    record->string = rand_string;
    record->value = (double)rand() / RAND_MAX * 1000;
    record->validity = 1;
    record->usage_status = 0;
    record->creation_timestamp = time(NULL);
    record->last_update_timestamp = time(NULL);
}

void create_record(struct RecordStorage* storage, size_t id) {
    // Create a new record with the specified ID
    struct Record* record = malloc(sizeof(struct Record));
    init_record(record, id);
    pthread_mutex_lock(&storage->mutex);
    if (storage->records == NULL) {
        storage->records = malloc(sizeof(struct Record*) * 1000000);
        storage->record_count = 0;
    }
    storage->records[id] = record;
    storage->record_count++;
    pthread_mutex_unlock(&storage->mutex);
}

void read_record(struct RecordStorage* storage, size_t id) {
    // Read the specified record from the storage system
    struct Record* record = NULL;
    pthread_mutex_lock(&storage->mutex);
    if (id < storage->record_count && storage->records[id] != NULL) {
        record = storage->records[id];
    }
    pthread_mutex_unlock(&storage->mutex);
}

void update_record(struct RecordStorage* storage, size_t id) {
    // Update the specified record in the storage system
    struct Record* record = NULL;
    pthread_mutex_lock(&storage->mutex);
    if (id < storage->record_count && storage->records[id] != NULL) {
        record = storage->records[id];
        record->last_update_timestamp = time(NULL);
        record->usage_status++;
    }
    pthread_mutex_unlock(&storage->mutex);
}

void delete_record(struct RecordStorage* storage, size_t id) {
    // Delete the specified record from the storage system
    struct Record* record = NULL;
    pthread_mutex_lock(&storage->mutex);
    if (id < storage->record_count && storage->records[id] != NULL) {
        record = storage->records[id];
        free(record->string);
        free(record);
        storage->records[id] = NULL;
        storage->record_count--;
    }
    pthread_mutex_unlock(&storage->mutex);
}

void garbage_collect(struct RecordStorage* storage) {
    // Periodically clean up unused records to free up resources
    pthread_mutex_lock(&storage->mutex);
    for (size_t i = 0; i < storage->record_count; i++) {
        if (storage->records[i] == NULL) {
            delete_record(storage, i);
        }
    }
    pthread_mutex_unlock(&storage->mutex);
}

int main() {
    // Initialize the record storage system
    struct RecordStorage* storage = malloc(sizeof(struct RecordStorage));
    storage->records = NULL;
    storage->record_count = 0;
    pthread_mutex_init(&storage->mutex, NULL);

    // Create a new record with ID 12345
    create_record(storage, 12345);

    // Read the specified record from the storage system
    read_record(storage, 12345);

    // Update the specified record in the storage system
    update_record(storage, 12345);

    // Delete the specified record from the storage system
    delete_record(storage, 12345);

    // Periodically clean up unused records to free up resources
    garbage_collect(storage);

    // Clean up the record storage system
    pthread_mutex_destroy(&storage->mutex);
    free(storage);

    return 0;
}
