    while (i < MAX_NUM_NEIGHBORS) {
        neighborCells[i].cellId = i + 1;
        neighborCells[i].signalStrength = 5.0f;
        neighborCells[i].numSamples = 10;
        srsParams->srsFrequency = 2.4e9f;
        srsParams->srsBandwidth = 1.8e6f;
        srsParams->srsDuration = 1000;
