  // Allocate memory for the Union-Find tree
  int *uf = (int *)malloc(size * sizeof(int));
  if (!uf) {
    printf("Error: Unable to allocate memory. Exiting.\n");
    exit(1);
  }

  // Initialize the Union-Find tree with each element pointing to itself
  for (int i = 0; i < size; i++) {
    uf[i] = i;
  }

  // Iterate over the array and perform union operations on disjoint sets
  int num_disjoint_sets = 1;
  for (int i = 1; i < size; i++) {
    if (uf[arr[i]] != uf[arr[i - 1]]) {
      num_disjoint_sets++;
      uf[arr[i]] = arr[i - 1]; // Union the current element with its predecessor
    }
  }

