#include "nfapi_message.h"

typedef struct {
    uint32_t UE_ID;
    TPC_COMMAND tpcCommand;
    QoS_PRIORITY qosPriority;
} NFAPI_MESSAGE_T;

NFAPI_MESSAGE_T* messages = NULL;
size_t numMessages = 0;

void addMessage(uint32_t UE_ID, TPC_COMMAND tpcCommand, QoS_PRIORITY qosPriority) {
    if (UE_ID == 0 || tpcCommand == 0 || qosPriority == 0) {
        printf("Invalid parameters\n");
        return;
    }
    // Validate the message type against a predefined list of supported commands before adding it to the collection.
    if (!validateMessageType(tpcCommand)) {
        printf("Unsupported TPC command: %d\n", tpcCommand);
        return;
    }
    // Check for overflow and reallocate memory as needed.
    if (numMessages >= SIZE_MAX / sizeof(NFAPI_MESSAGE_T)) {
        printf("Memory allocation failure\n");
        return;
    }
    if (!messages) {
        messages = (NFAPI_MESSAGE_T*)malloc(sizeof(NFAPI_MESSAGE_T));
        if (!messages) {
            printf("Memory allocation failure\n");
            return;
        }
        numMessages++;
    } else {
        NFAPI_MESSAGE_T* newMessages = (NFAPI_MESSAGE_T*)realloc(messages, (numMessages + 1) * sizeof(NFAPI_MESSAGE_T));
        if (!newMessages) {
            printf("Memory allocation failure\n");
            return;
        }
        messages = newMessages;
        numMessages++;
    }
    // Initialize the new message with the provided UE_ID, tpcCommand, and qosPriority.
    messages[numMessages - 1].UE_ID = UE_ID;
    messages[numMessages - 1].tpcCommand = tpcCommand;
    messages[numMessages - 1].qosPriority = qosPriority;
}

void removeMessage(uint32_t UE_ID) {
    for (size_t i = 0; i < numMessages; i++) {
        if (messages[i].UE_ID == UE_ID) {
            // Remove the message from the collection.
            memmove(&messages[i], &messages[i + 1], (numMessages - i - 1) * sizeof(NFAPI_MESSAGE_T));
            numMessages--;
            return;
        }
    }
}

void updateMessage(uint32_t UE_ID, TPC_COMMAND tpcCommand, QoS_PRIORITY qosPriority) {
    for (size_t i = 0; i < numMessages; i++) {
        if (messages[i].UE_ID == UE_ID) {
