    for (int i = startState; i <= endState; i++) {
        if (fsa->states[i]) {
            numExtractedStates++;
        }
    }

    // Allocate memory for the extracted state sequence
    int *extractedStates = malloc(numExtractedStates * sizeof(int));
    if (!extractedStates) {
        fprintf(stderr, "Error: Failed to allocate memory for extracted states\n");
        exit(1);
    }

    // Extract the states from the FSA and update their references in other structures
    int currentState = 0;
    for (int i = startState; i <= endState; i++) {
        if (fsa->states[i]) {
            extractedStates[currentState++] = i;
            // Update the transitions and actions associated with this state
            for (int j = 0; j < fsa->numTransitions; j++) {
                Transition *transition = &fsa->transitions[j];
                if (transition->fromState == i) {
                    transition->toState = currentState - 1; // Update the reference to the new state
                }
            }
            for (int j = 0; j < fsa->numActions; j++) {
                Action *action = &fsa->actions[j];
                if (action->state == i) {
                    action->state = currentState - 1; // Update the reference to the new state
                }
            }
        }
    }

    // Copy the extracted states to the output array and free the temporary memory
    memcpy(states, extractedStates, numExtractedStates * sizeof(int));
    free(extractedStates);
}

