struct priorityQueueNode {
  int weight;
  struct session* session;
  struct priorityQueueNode* next;
};

// Global memory pool for records
struct recordPool {
  int size;
  struct record* records[N];
};

// Memory management functions
void initRecord(struct record* r, int value) {
  r->value = value;
}

void initSession(struct session* s, int id) {
  s->id = id;
  for (int i = 0; i < N; ++i) {
    s->records[i] = NULL;
  }
}

void allocRecord(struct recordPool* pool, struct record** r) {
  if (pool->size == 0) {
    // Memory allocation failed
    return;
  }
  *r = pool->records[--pool->size];
}

void freeRecord(struct recordPool* pool, struct record* r) {
  pool->records[pool->size++] = r;
}

// Priority queue management functions
void initPriorityQueue(struct priorityQueue* q) {
  q->size = 0;
  q->head = NULL;
}

void enqueue(struct priorityQueue* q, struct session* s) {
  if (q->size == 0) {
    q->head = malloc(sizeof(struct priorityQueueNode));
    q->head->weight = s->id;
    q->head->session = s;
    q->head->next = NULL;
  } else {
    struct priorityQueueNode* newNode = malloc(sizeof(struct priorityQueueNode));
    newNode->weight = s->id;
    newNode->session = s;
    newNode->next = q->head;
    q->head = newNode;
  }
  ++q->size;
}

void dequeue(struct priorityQueue* q) {
  if (q->size == 0) {
    // Priority queue is empty
    return;
  }
  struct priorityQueueNode* current = q->head;
  q->head = current->next;
  free(current);
  --q->size;
}

// Memory management for session records
void initRecordPool(struct recordPool* pool) {
  for (int i = 0; i < N; ++i) {
    pool->records[i] = malloc(sizeof(struct record));
  }
  pool->size = N;
}

void allocRecordsForSession(struct session* s, struct recordPool* pool) {
