typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct DynamicList {
    NFAPI_CRC_INDICATION_PDU_T* elements;
    size_t numElements;
    pthread_mutex_t mutex;
} DynamicList;

void initializeDynamicList(DynamicList* list) {
    list->elements = NULL;
    list->numElements = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

bool addElementToDynamicList(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&list->mutex);
    size_t newNumElements = list->numElements + 1;
    NFAPI_CRC_INDICATION_PDU_T* newElements = realloc(list->elements, newNumElements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (newElements == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return false;
    }
    list->elements = newElements;
    list->elements[newNumElements - 1] = element;
    list->numElements = newNumElements;
    pthread_mutex_unlock(&list->mutex);
    return true;
}

bool removeElementFromDynamicList(DynamicList* list, size_t index) {
    pthread_mutex_lock(&list->mutex);
    if (index >= list->numElements) {
        pthread_mutex_unlock(&list->mutex);
        return false;
    }
    NFAPI_CRC_INDICATION_PDU_T* newElements = realloc(list->elements, (list->numElements - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (newElements == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return false;
    }
    size_t numMovedElements = list->numElements - index - 1;
    memmove(&list->elements[index], &list->elements[index + 1], numMovedElements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->numElements--;
    pthread_mutex_unlock(&list->mutex);
    return true;
}

bool retrieveElementFromDynamicList(DynamicList* list, size_t index, NFAPI_CRC_INDICATION_PDU_T* element) {
    pthread_mutex_lock(&list->mutex);
    if (index >= list->numElements) {
        pthread_mutex_unlock(&list->mutex);
        return false;
    }
    *element = list->elements[index];
    pthread_mutex_unlock(&list->mutex);
    return true;
}

void destroyDynamicList(DynamicList* list) {
    pthread_mutex_destroy(&list->mutex);
    free(list->elements);
}

