Here is an example implementation of a C function to manage a dynamic array of `NetworkEntityStatus` structures, using a linked list for memory allocation and access patterns:
```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include "NetworkEntityStatus.h" // assume this is the definition of NetworkEntityStatus structure

// Global variables
static pthread_mutex_t mutex; // mutex for protecting concurrent access to the list
static struct NetworkEntityStatus* head = NULL; // head of the linked list
static int numEntries = 0; // number of entries in the list

// Function to add a new entry to the list
void addEntry(struct NetworkEntityStatus* newEntry) {
    pthread_mutex_lock(&mutex);
    struct NetworkEntityStatus* current = head;
    while (current->next != NULL) {
        current = current->next;
    }
    current->next = newEntry;
    newEntry->prev = current;
    numEntries++;
    pthread_mutex_unlock(&mutex);
}

// Function to update an existing entry in the list
void updateEntry(struct NetworkEntityStatus* entry, struct NetworkEntityStatus* updated) {
    pthread_mutex_lock(&mutex);
    struct NetworkEntityStatus* current = head;
    while (current != NULL && current->next != entry) {
        current = current->next;
    }
    if (current == NULL || current->next == NULL) {
        pthread_mutex_unlock(&mutex);
        return; // entry not found in list, ignore update
    }
    *entry = *updated;
    pthread_mutex_unlock(&mutex);
}

// Function to remove an entry from the list
void removeEntry(struct NetworkEntityStatus* entry) {
    pthread_mutex_lock(&mutex);
    struct NetworkEntityStatus* current = head;
    while (current != NULL && current->next != entry) {
        current = current->next;
    }
    if (current == NULL || current->next == NULL) {
        pthread_mutex_unlock(&mutex);
        return; // entry not found in list, ignore removal
    }
    struct NetworkEntityStatus* toRemove = current->next;
    current->next = toRemove->next;
    if (toRemove->next != NULL) {
        toRemove->next->prev = current;
    }
    free(toRemove);
    numEntries--;
    pthread_mutex_unlock(&mutex);
}

// Function to iterate over the list and call a callback function for each entry
void iterateOverList(int (*callback)(struct NetworkEntityStatus*)) {
    pthread_mutex_lock(&mutex);
    struct NetworkEntityStatus* current = head;
    while (current != NULL) {
        callback(current);
        current = current->next;
    }
    pthread_mutex_unlock(&mutex);
}
```
