typedef struct record {
    int data;
} Record;

void *allocate_memory(size_t num_records) {
    size_t record_size = sizeof(Record);
    size_t long_array_size = num_records * sizeof(long);
    size_t int_array_size = num_records * sizeof(int);
    size_t total_size = long_array_size + int_array_size + record_size;
    void *memory = malloc(total_size);

    if (memory == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory\n");
        return NULL;
    }

    // Initialize the offsets array
    long *offsets = (long *)memory;
    size_t offset_index = 0;
    for (size_t i = 0; i < num_records; i++) {
        offsets[i] = offset_index;
        offset_index += record_size;
    }

    // Initialize the unique keys array
    int *keys = (int *)(memory + long_array_size);
    for (size_t i = 0; i < num_records; i++) {
        keys[i] = rand() % 1000;
    }

    // Initialize the records array
    Record *records = (Record *)(memory + long_array_size + int_array_size);
    for (size_t i = 0; i < num_records; i++) {
        records[i].data = rand() % 1000;
    }

    return memory;
}

void free_memory(void *memory) {
    if (memory != NULL) {
        free(memory);
    }
}

int main() {
    size_t num_records = 100000;
    void *memory = allocate_memory(num_records);

    // Perform some operations on the allocated memory
    long *offsets = (long *)memory;
    int *keys = (int *)(memory + sizeof(long) * num_records);
    Record *records = (Record *)(memory + sizeof(long) * num_records + sizeof(int) * num_records);

    for (size_t i = 0; i < num_records; i++) {
        printf("Offset %zu: %lu\n", i, offsets[i]);
        printf("Key %zu: %d\n", i, keys[i]);
        printf("Record %zu: {%d}\n", i, records[i].data);
    }

    free_memory(memory);

    return 0;
}
