#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdbool.h>

struct record {
    int value;
    char* user_id;
};

struct set {
    long* offsets;
    int* keys;
    struct record* records;
    size_t num_records;
    pthread_mutex_t lock;
};

void initialize_set(struct set* set, size_t num_records, long min_range, long max_range) {
    // Initialize the offsets array with random integers within the given range
    for (size_t i = 0; i < num_records; ++i) {
        set->offsets[i] = (long)(rand() % (max_range - min_range + 1)) + min_range;
    }

    // Initialize the keys array with unique integers
    for (size_t i = 0; i < num_records; ++i) {
        set->keys[i] = i + 1;
    }

    // Initialize the records array with empty string pointers
    for (size_t i = 0; i < num_records; ++i) {
        set->records[i].user_id = malloc(32 * sizeof(char));
        set->records[i].user_id[0] = '\0';
    }

    // Initialize the lock for thread safety
    pthread_mutex_init(&set->lock, NULL);
}

void add_record(struct set* set, int key, char* user_id) {
    pthread_mutex_lock(&set->lock);

    // Find the first empty slot in the records array
    size_t i;
    for (i = 0; i < set->num_records; ++i) {
        if (set->records[i].user_id[0] == '\0') {
            break;
        }
    }

    // If all slots are occupied, resize the records array and retry
    if (i == set->num_records) {
        size_t new_size = set->num_records * 2;
        struct record* new_records = realloc(set->records, new_size * sizeof(struct record));
        if (new_records == NULL) {
            pthread_mutex_unlock(&set->lock);
            return;
        }
        set->records = new_records;
        set->num_records = new_size;

        i = 0;
        while (i < set->num_records && set->records[i].user_id[0] != '\0') {
            ++i;
        }
    }

    // Add the record to the slot found
    size_t user_id_length = strlen(user_id);
    if (user_id_length > 32) {
        user_id_length = 32;
    }
    set->records[i].value = key;
    memcpy(set->records[i].user_id, user_id, user_id_length);
    pthread_mutex_unlock(&set->lock);
}

void remove_record(struct set* set, int key) {
    pthread_mutex_lock(&set->lock);

    // Find the slot for the given key and remove it from the records array
    size_t i;
    for (i = 0; i < set->num_records; ++i) {
        if (set->records[i].value == key) {
            break;
        }
    }

    // If the slot was not found, return
    if (i == set->num_records) {
        pthread_mutex_unlock(&set->lock);
        return;
    }

    // Remove the record from the slot and free the memory
    free(set->records[i].user_id);
    memmove(&set->records[i], &set->records[i + 1], (set->num_records - i - 1) * sizeof(struct record));
    --set->num_records;

    pthread_mutex_unlock(&set->lock);
}

void destroy_set(struct set* set) {
    // Free all memory allocated for the records array and destroy the lock
    free(set->offsets);
    free(set->keys);
    free(set->records);
    pthread_mutex_destroy(&set->lock);
}
```
This code defines a function `initialize_set` that initializes a set of records with the given number of records, minimum and maximum ranges for random integer values, and a maximum total memory usage constraint. The function also creates an array of pointers to strings representing user IDs and locks for thread safety.

The function `add_record` adds a new record to the set by finding the first empty slot in the records array and initializing it with the given key and user ID. If all slots are occupied, the function resizes the records array and reties the operation. The function also ensures that the memory usage constraint is not exceeded.

The function `remove_record` removes a record from the set by finding the slot for the given key and removing it from the records array. If the slot was not found, the function returns without taking any action. The function also frees the memory allocated for the removed record and ensures that the lock is released before returning.

The function `destroy_set` destroys a set of records by freeing all memory allocated for the arrays and destroying the lock."]

