    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void read_integers(int *array, int size) {
    // Validate input parameters
    if (size <= 0) {
        fprintf(stderr, "Invalid input: empty or non-positive array\n");
        return;
    }

    // Allocate memory for the array of structures
    NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        fprintf(stderr, "Failed to allocate memory for array\n");
        return;
    }

    // Read the integers from standard input and store them in the array
    int i = 0;
    while (i < size && scanf("%d", &array[i]) == 1) {
        pdu[i].RX_UE_INFORMATION_TAG = 0xAB;
        pdu[i].RNTI = array[i];
        pdu[i].CRC_INDICATION_REL8_TAG = (array[i] % 3 == 2) ? 1 : 0;
        i++;
    }

    // Print the largest integer in the array
    int max = -1;
    for (int j = 0; j < size; j++) {
        if (max < array[j]) {
            max = array[j];
        }
    }
    printf("Largest integer: %d\n", max);

    // Free the dynamically allocated memory
    free(pdu);
