    Record* bucket = table.buckets[bucket_index];

    // Traverse the linked list of records in the bucket
    while (bucket) {
        if (bucket->key == key) {
            return bucket;
        }
        bucket = bucket->next;
    }

    // If no record was found, return NULL
    return NULL;
}

