    strcpy(new_session->user_id, user_id);
    new_session->events = NULL;
    new_session->status = 0;
    new_session->last_activity = time(NULL);

    // Add the new session to the array
    (*sessions)->sessions[(*sessions)->num_sessions++] = new_session;
}

// Function to remove a session from the array by ID
void remove_session(session_array_t **sessions, char *session_id) {
    // Find the index of the session in the array
    int i = 0;
    while (i < (*sessions)->num_sessions && strcmp((*sessions)->sessions[i]->session_id, session_id) != 0) {
        i++;
    }

    // Check if the session was found in the array
    if (i >= (*sessions)->num_sessions) {
        return;
    }

    // Remove the session from the array and free its memory
    free((*sessions)->sessions[i]);
    memmove(&(*sessions)->sessions[i], &(*sessions)->sessions[i + 1], (*sessions)->num_sessions - i);
    (*sessions)->num_sessions--;
}

// Function to update a session in the array by ID
void update_session(session_array_t **sessions, char *session_id) {
    // Find the index of the session in the array
    int i = 0;
    while (i < (*sessions)->num_sessions && strcmp((*sessions)->sessions[i]->session_id, session_id) != 0) {
        i++;
    }

    // Check if the session was found in the array
    if (i >= (*sessions)->num_sessions) {
        return;
    }

    // Update the session's status and last activity timestamp
    (*sessions)->sessions[i]->status = 1;
    (*sessions)->sessions[i]->last_activity = time(NULL);
}

// Function to serialize a session array into a binary format for persistence
void serialize_session_array(session_array_t *sessions, char **serialized_data) {
    // Check if there is enough memory for the serialized data
    int num_bytes = 0;
    for (int i = 0; i < sessions->num_sessions; i++) {
        num_bytes += sizeof(session_t);
    }

    *serialized_data = malloc(num_bytes);
    char *ptr = *serialized_data;

    // Serialize each session in the array
    for (int i = 0; i < sessions->num_sessions; i++) {
        memcpy(ptr, sessions->sessions[i], sizeof(session_t));
        ptr += sizeof(session_t);
    }
}

// Function to deserialize a session array from a binary format for persistence
void deserialize_session_array(char *serialized_data, int num_bytes, session_array_t **sessions) {
    // Check if there is enough memory for the deserialized data
    *sessions = malloc(num_bytes);
    char *ptr = serialized_data;

    // Deserialize each session in the array
    for (int i = 0; i < num_bytes / sizeof(session_t); i++) {
        memcpy((*sessions)->sessions[i], ptr, sizeof(session_t));
        ptr += sizeof(session_t);
    }

    // Set the number of sessions in the array
    (*sessions)->num_sessions = num_bytes / sizeof(session_t);
}
