static LinkedList *head = NULL;
static pthread_mutex_t lock;

// Function to initialize linked list with initial size
void initLinkedList(int size) {
    head = malloc(sizeof(LinkedList));
    head->data = malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    capacity = size;
}

// Function to insert a new node at the end of linked list
void insertNode(NFAPI_CRC_INDICATION_PDU_T *data) {
    pthread_mutex_lock(&lock);
    LinkedList *node = malloc(sizeof(LinkedList));
    node->data = data;
    node->next = NULL;
    if (head == NULL) {
        head = node;
    } else {
        LinkedList *current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = node;
    }
    pthread_mutex_unlock(&lock);
}

// Function to delete a node from linked list
void deleteNode(NFAPI_CRC_INDICATION_PDU_T *data) {
    pthread_mutex_lock(&lock);
    LinkedList *current = head;
    while (current != NULL && current->next != NULL) {
        if (current->next->data == data) {
            LinkedList *temp = current->next;
            current->next = temp->next;
            free(temp);
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&lock);
}

// Function to dynamically allocate memory for linked list
void reallocateMemory() {
    capacity *= 2;
    head->data = realloc(head->data, capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

// Helper function to find the largest integer in an array
int findLargestInteger(int arr[], int size) {
    int largest = INT_MIN;
    for (int i = 0; i < size; i++) {
        if (arr[i] > largest) {
            largest = arr[i];
        }
    }
    return largest;
}

// Function to read integers from standard input and populate linked list
void populateLinkedList() {
    int *arr = malloc(sizeof(int));
    scanf("%d", &arr);
    for (int i = 0; i < arr[0]; i++) {
        int n;
        scanf("%d", &n);
        NFAPI_CRC_INDICATION_PDU_T *data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
