        data->Rnti = n;
        data->CrcIndicationRel8Tag.CRCFlag = rand();
        insertNode(data);
    }
}

// Function to serialize linked list to binary file
void serializeLinkedListToFile(FILE *fp) {
    LinkedList *current = head;
    while (current != NULL) {
        fwrite(&current->data->RxUeInformationTag, sizeof(RX_UE_INFORMATION_TAG), 1, fp);
        fwrite(&current->data->Rnti, sizeof(RNTI), 1, fp);
        fwrite(&current->data->CrcIndicationRel8Tag.CRCFlag, sizeof(CRC_INDICATION_REL8_TAG), 1, fp);
        current = current->next;
    }
}

// Function to deserialize linked list from binary file
void deserializeLinkedListFromFile(FILE *fp) {
    int readSize = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    while (fread(&readSize, 1, 1, fp)) {
        NFAPI_CRC_INDICATION_PDU_T *data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        data->RxUeInformationTag = RX_UE_INFORMATION_TAG;
        data->Rnti = rand();
        data->CrcIndicationRel8Tag.CRCFlag = rand();
        insertNode(data);
    }
}

// Function to monitor number of successfully processed CRC indications and provide detailed logs for initialization failures
void logInitializationFailures() {
