// Function to add a new CRC indication structure to the array
void AddCrcIndication(NFAPI_CRC_INDICATION_PDU_T *crcIndication) {
    // Check if the array needs to be resized
    if (crcIndicationsUsed == crcIndicationsSize) {
        ResizeCrcIndications();
    }

    // Add the new CRC indication structure to the array
    crcIndications[crcIndicationsUsed++] = *crcIndication;
}

// Function to resize the CRC indication array
void ResizeCrcIndications() {
    // Calculate the new size of the array based on the current usage and a growth factor
    uint32_t newSize = crcIndicationsUsed + (crcIndicationsUsed / 4);

    // Reallocate the memory for the array
    NFAPI_CRC_INDICATION_PDU_T *newArray = realloc(crcIndications, newSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (newArray == NULL) {
        // Handle memory allocation failure
        printf("Error: Failed to resize CRC indication array\n");
        exit(-1);
    }

    // Update the global variables for the new array
    crcIndications = newArray;
    crcIndicationsSize = newSize;
}

// Function to remove a CRC indication structure from the array
void RemoveCrcIndication(uint32_t index) {
    // Check if the index is valid
    if (index >= crcIndicationsUsed) {
        printf("Error: Invalid index for removing CRC indication\n");
        return;
    }

    // Move all elements after the specified index one position earlier
    for (uint32_t i = index + 1; i < crcIndicationsUsed; i++) {
        crcIndications[i - 1] = crcIndications[i];
    }

    // Decrement the usage count of the array
    crcIndicationsUsed--;
}

// Function to update the CRCFLAG value for a CRC indication structure
void UpdateCrcFlag(uint32_t index, uint8_t newValue) {
    // Check if the index is valid
    if (index >= crcIndicationsUsed) {
        printf("Error: Invalid index for updating CRCFLAG\n");
        return;
    }

    // Update the CRCFLAG value for the specified structure
    crcIndications[index].CRCFLAG = newValue;
}

// Function to check if a CRC indication structure already exists in the array
bool DoesCrcIndicationExist(uint32_t RNTI) {
    // Iterate through the array and check for a matching RNTI value
    for (uint32_t i = 0; i < crcIndicationsUsed; i++) {
        if (crcIndications[i].RNTI == RNTI) {
            return true;
        }
    }

    // If no match is found, return false
    return false;
}

// Function to generate a random value for the CRCFLAG based on the seed value
uint8_t GenerateRandomCrcFlag() {
    // Use the seed value as a starting point and increment it by 1 each time a new value is generated
    uint8_t newValue = seedValue;

    // Generate a random number between 0 and 255 using the Mersenne twister algorithm
    for (uint32_t i = 0; i < 255; i++) {
        int kk = (196507 * newValue + 1) % 255;
        if (kk == 0 || kk == 1) {
            kk = 254;
        }

        // Update the new value and seed value for the next iteration
        newValue = kk;
        seedValue++;
    }

    return newValue;
}

// Function to handle incoming CRC indications from the NFAPI interface
void HandleCrcIndication(NFAPI_CRC_INDICATION_PDU_T *crcIndication) {
    // Check if a CRC indication structure for the specified RNTI already exists in the array
    if (DoesCrcIndicationExist(crcIndication->RNTI)) {
        // If a matching structure is found, update its CRCFLAG value and return
        UpdateCrcFlag(GetCrcIndicationIndex(crcIndication->RNTI), GenerateRandomCrcFlag());
    } else {
        // If no matching structure is found, add a new one to the array with a random CRCFLAG value
        AddCrcIndication(crcIndication);
    }
}

// Function to get the index of a CRC indication structure in the array based on its RNTI value
uint32_t GetCrcIndicationIndex(uint32_t RNTI) {
    // Iterate through the array and check for a matching RNTI value
    for (uint32_t i = 0; i < crcIndicationsUsed; i++) {
        if (crcIndications[i].RNTI == RNTI) {
            return i;
        }
    }

    // If no match is found, return the maximum index + 1
    return crcIndicationsUsed;
}

