void init_lte_ue_context(struct lte_ue_context **ue_contexts, int num_ues, struct lte_cell_id *cell_ids, struct lte_rnti *rntis, struct srb1_status *srb1_statuses) {
    // Check if input parameters are valid
    if (ue_contexts == NULL || num_ues <= 0 || cell_ids == NULL || rntis == NULL || srb1_statuses == NULL) {
        return;
    }

    // Initialize the list of UE context structures
    for (int i = 0; i < num_ues; i++) {
        ue_contexts[i] = malloc(sizeof(struct lte_ue_context));
        if (ue_contexts[i] == NULL) {
            // Memory allocation failed, log error and return
            fprintf(stderr, "Memory allocation failed for UE context %d\n", i);
            return;
        }
        ue_contexts[i]->cell_id = cell_ids[i];
        ue_contexts[i]->rnti = rntis[i];
        ue_contexts[i]->srb1_status = srb1_statuses[i];
    }

    // Allocate buffer for storing uplink TPC commands
    size_t buf_size = num_ues * MAX_TPC_COMMAND_LENGTH;
    u8 *buf = malloc(buf_size);
    if (buf == NULL) {
        fprintf(stderr, "Memory allocation failed for TPC command buffer\n");
        return;
    }

    // Initialize the buffer with empty commands
    for (int i = 0; i < num_ues; i++) {
        ue_contexts[i]->tpc_command = buf + i * MAX_TPC_COMMAND_LENGTH;
    }

    // Determine predefined threshold for dynamic buffer resizing
    int resize_threshold = 0.75 * num_ues * MAX_TPC_COMMAND_LENGTH;

    // Integrate with existing network management system for UE context updates
    pthread_mutex_lock(&ue_contexts_lock);
    for (int i = 0; i < num_ues; i++) {
        update_ue_context(ue_contexts[i]);
    }
    pthread_mutex_unlock(&ue_contexts_lock);

    // Implement retries with exponential backoff strategies for failed TPC commands
    int retry_count = 0;
    while (retry_count < MAX_RETRY_COUNT) {
        bool success = true;
        for (int i = 0; i < num_ues; i++) {
            if (!send_tpc_command(ue_contexts[i]->cell_id, ue_contexts[i]->rnti, ue_contexts[i]->tpc_command)) {
                success = false;
                break;
            }
        }
        if (success) {
            // Successfully sent TPC commands to all UEs, exit retry loop
            break;
        } else {
            // Failed to send TPC command to one or more UEs, backoff and retry
            retry_count++;
            int backoff = pow(2, retry_count) * 1000;
            fprintf(stderr, "TPC command sending failed, backing off for %d ms\n", backoff);
            sleep(backoff);
        }
    }

    // Log detailed information about each context configuration attempt
    for (int i = 0; i < num_ues; i++) {
        bool success = send_tpc_command(ue_contexts[i]->cell_id, ue_contexts[i]->rnti, ue_contexts[i]->tpc_command);
        fprintf(stderr, "UE context %d: TPC command sending %ssuccessful\n", i, success ? "" : "un");
    }

    // Release allocated resources upon completion or failure of the operation
    if (buf != NULL) {
        free(buf);
    }
    for (int i = 0; i < num_ues; i++) {
        if (ue_contexts[i] != NULL) {
            free(ue_contexts[i]);
        }
    }
