// Function to dynamically manage memory for records
int create_records(int num_records, int range) {
    // Declare arrays for storing 'long' offsets and 'int' keys
    long *offset_array = malloc(sizeof(long) * num_records);
    int *key_array = malloc(sizeof(int) * num_records);
    struct record *record_array = malloc(sizeof(struct record) * num_records);

    // Initialize arrays with random values within the specified range
    for (int i = 0; i < num_records; i++) {
        offset_array[i] = rand() % range;
        key_array[i] = rand() % range;
        record_array[i].key = key_array[i];
        record_array[i].offset = offset_array[i];
    }

    // Declare a lock for thread safety
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Declare an atomic variable to store the total number of records created
    __atomic_int_t num_records_created = 0;

    // Thread function to generate random values and insert them into the record array
    void *generate_random(void *args) {
        int thread_id = (int) args;
        for (int i = 0; i < num_records / 10; i++) {
            pthread_mutex_lock(&lock);
            int key = rand() % range;
            long offset = rand() % range;
            record_array[i].key = key;
            record_array[i].offset = offset;
            num_records_created++;
            pthread_mutex_unlock(&lock);
        }
    }

    // Create 10 threads to generate random values and insert them into the record array
    pthread_t thread[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&thread[i], NULL, generate_random, (void *) i);
    }

    // Join all threads to ensure they have completed their work
    for (int i = 0; i < 10; i++) {
        pthread_join(thread[i], NULL);
    }

    // Return the total number of records created
    return num_records_created;
}
