// Define a function to populate the records array using a weighted distribution
void* populate_records(const char* text, size_t max_threshold) {
    // Initialize variables
    size_t num_keys = 0;
    int *keys = malloc(sizeof(int) * 5000);
    if (keys == NULL) {
        return NULL;
    }
    int *weights = malloc(sizeof(int) * 5000);
    if (weights == NULL) {
        free(keys);
        return NULL;
    }
    size_t num_records = 0;
    record_array_t *record_array = malloc(sizeof(record_array_t));
    if (record_array == NULL) {
        free(weights);
        free(keys);
        return NULL;
    }

    // Count the number of keys in the text and populate the keys array
    while (*text != '\0') {
        if (isalnum(*text)) {
            num_keys++;
            keys[num_keys - 1] = *text;
        }
        text++;
    }

    // Calculate the weights for each key based on its frequency in the text
    for (size_t i = 0; i < num_keys; i++) {
        size_t count = 0;
        char current_key = keys[i];
        while (*text != '\0') {
            if (*text == current_key) {
                count++;
            }
            text++;
        }
        weights[i] = (int)(count * 1.0 / num_keys);
    }

    // Populate the records array using a weighted distribution
    while (num_records < record_array->num_elements) {
        size_t random_index = rand() % num_keys;
        int current_key = keys[random_index];
        for (size_t i = 0; i < num_keys; i++) {
            if (current_key == keys[i]) {
                record_array->elements[num_records++] = weights[i];
                break;
            }
        }
    }

    // Free the memory allocated for the keys and weights arrays
    free(weights);
    free(keys);

    return record_array;
}

// Define a function to generate a random integer between two given integers
int getRandomInteger(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Define a function to generate a random record using the records array
void* generate_random_record(record_array_t *record_array) {
    // Initialize variables
    size_t num_records = record_array->num_elements;
    int current_record = getRandomInteger(0, num_records - 1);

    return record_array->elements[current_record];
}

// Define a function to generate a random integer between two given integers using the records array
int getRandomIntegerUsingRecords(const char* text, size_t max_threshold) {
    // Initialize variables
    size_t num_records = 0;
    record_array_t *record_array = populate_records(text, max_threshold);
    if (record_array == NULL) {
        return -1;
    }

    while (num_records < record_array->num_elements) {
        size_t random_index = rand() % num_records;
        int current_record = record_array->elements[random_index];
        if (current_record > max_threshold) {
            continue;
        } else {
            free(record_array);
            return current_record;
        }
    }

    // Free the memory allocated for the records array
    free(record_array);

    return -1;
}
