// Structure to store connection information
typedef struct {
    int sock;
    char* hostname;
    int port;
    int timeout;
} ConnectionInfo;

// Function to establish an HTTPS client capable of handling secure connections with mutual TLS authentication, supporting client certificates and CA bundles.
int https_client_init(const char* hostname, const char* port, const char* ca_bundle) {
    // Initialize SSL context
    SSL_CTX* ctx = SSL_CTX_new(TLS_client_method());
    if (!ctx) {
        perror("Error initializing SSL context");
        return -1;
    }

    // Load CA bundle
    if (SSL_CTX_load_verify_locations(ctx, ca_bundle)) {
        perror("Error loading CA bundle");
        SSL_CTX_free(ctx);
        return -1;
    }

    // Set verify mode to VERIFY_PEER
    SSL_CTX_set_verify(ctx, SSL_VERIFY_PEER, NULL);

    // Create a new SSL object
    SSL* ssl = SSL_new(ctx);
    if (!ssl) {
        perror("Error creating SSL object");
        SSL_CTX_free(ctx);
        return -1;
    }

    // Connect to server using hostname and port
    int sock = connect_to_server(hostname, port);
    if (sock < 0) {
        perror("Error connecting to server");
        SSL_free(ssl);
        SSL_CTX_free(ctx);
        return -1;
    }

    // Set the socket for the SSL object
    SSL_set_fd(ssl, sock);

    // Perform handshake
    if (SSL_connect(ssl) <= 0) {
        perror("Error performing SSL handshake");
        close(sock);
        SSL_free(ssl);
        SSL_CTX_free(ctx);
        return -1;
    }

    // Free the SSL context and return the socket descriptor
    SSL_CTX_free(ctx);
    SSL_free(ssl);
    return sock;
}

// Function to send a simple probe message and receive a response. If a connection fails to respond within a specified time frame, initiate a graceful shutdown and attempt to establish a new connection with the server.
int check_connection(ConnectionInfo* conn) {
    // Send a simple probe message
    char* probe = "PING";
    if (send(conn->sock, probe, strlen(probe), 0) < 0) {
        perror("Error sending probe message");
        return -1;
    }

    // Receive the response
    char* resp = malloc(sizeof(char) * 256);
    if (recv(conn->sock, resp, 256, 0) < 0) {
        perror("Error receiving response");
        return -1;
    }

    // Check the response
    if (strcmp(resp, "PONG") != 0) {
        // Connection failed to respond within a specified time frame
        printf("Connection %s:%d timed out\n", conn->hostname, conn->port);
        close(conn->sock);
        return -1;
    }

    // Free the response buffer
    free(resp);
    return 0;
}

// Function to periodically check the health status of each connection by sending a simple probe message and receiving a response. If a connection fails to respond within a specified time frame, initiate a graceful shutdown and attempt to establish a new connection with the server.
void manage_connections(ConnectionInfo* connections, int num_connections) {
    // Initialize variables for looping through connections
    int i;
    int ret = 0;
    char* errstr = NULL;

    // Loop through each connection and check its health status
    for (i = 0; i < num_connections; i++) {
        ConnectionInfo* conn = &(connections[i]);
        ret = check_connection(conn);
        if (ret == -1) {
            // Connection failed, initiate a graceful shutdown and attempt to establish a new connection with the server
            printf("Connection %s:%d failed\n", conn->hostname, conn->port);
            SSL_free(conn->ssl);
            close(conn->sock);
            ret = https_client_init(conn->hostname, conn->port, conn->ca_bundle);
            if (ret < 0) {
                perror("Error reconnecting to server");
                return -1;
            } else {
                printf("Connection %s:%d reestablished\n", conn->hostname, conn->port);
            }
        }
    }
}

// Function to manage memory efficiently, ensuring that all allocated resources are freed upon completion of the function.
void cleanup_connections(ConnectionInfo* connections, int num_connections) {
    // Loop through each connection and free its resources
    for (int i = 0; i < num_connections; i++) {
        ConnectionInfo* conn = &(connections[i]);
        SSL_free(conn->ssl);
        close(conn->sock);
        free(conn->hostname);
        free(conn->ca_bundle);
    }
}

// Function to integrate logging capabilities to record detailed information about the connection health checks and the connection management process, including any errors encountered during these operations.
void log_connections(ConnectionInfo* connections, int num_connections) {
    // Initialize variables for looping through connections
    int i;
    char* errstr = NULL;

    // Loop through each connection and log its health status
    for (i = 0; i < num_connections; i++) {
        ConnectionInfo* conn = &(connections[i]);
        if (conn->ssl != NULL) {
            printf("Connection %s:%d established\n", conn->hostname, conn->port);
        } else {
            printf("Connection %s:%d failed\n", conn->hostname, conn->port);
        }
    }
}

int main() {
    // Initialize variables for looping through connections
    int i;
    ConnectionInfo* connections = NULL;
    int num_connections = 0;

    // Loop through each connection and initialize its resources
    for (i = 0; i < 5; i++) {
        ConnectionInfo* conn = malloc(sizeof(ConnectionInfo));
        if (conn == NULL) {
            perror("Error allocating memory for connections");
            return -1;
        } else {
            conn->hostname = malloc(sizeof(char) * 256);
            conn->port = i + 1;
            sprintf(conn->hostname, "www.example%d.com", conn->port);
            connections[num_connections] = conn;
            num_connections++;
        }
    }

    // Periodically check the health status of each connection and initiate a graceful shutdown if necessary
    manage_connections(connections, num_connections);

    // Log the health status of each connection
    log_connections(connections, num_connections);

    // Clean up memory for all connections
    cleanup_connections(connections, num_connections);

    return 0;
}
```

This program will periodically check the health status of each connection and initiate a graceful shutdown if necessary. It will also log the health status of each connection to standard output.']

