// Define the logging context structure
typedef struct LoggingContext {
    // Thread-safe queue for log messages
    Queue *queue;
    // Log buffer for storing logs before they are sent to the destination
    char **log_buffer;
    // Configuration settings for log levels, output formats, and destinations
    ConfigSettings config_settings;
    // Metrics on log throughput, latency, and error rates
    MetricStats metrics;
} LoggingContext;

// Define the queue structure for storing log messages
typedef struct Queue {
    // Array of log messages
    char **log_messages;
    // Size of the array
    size_t capacity;
    // Number of elements in the queue
    size_t size;
} Queue;

// Define the configuration settings structure for log levels, output formats, and destinations
typedef struct ConfigSettings {
    // Log level (e.g., debug, info, warn, error)
    int log_level;
    // Output format (e.g., text, json)
    char *output_format;
    // Destination (e.g., console, file, network)
    char *destination;
} ConfigSettings;

// Define the metric statistics structure for logging metrics
typedef struct MetricStats {
    // Throughput of log messages in bytes per second
    double throughput;
    // Latency of log messages in milliseconds
    double latency;
    // Error rate of log messages (e.g., percentage of failed logs)
    double error_rate;
} MetricStats;

// Configure the logging framework
LoggingContext *configure_logging_framework(const char *config_file) {
    // Validate the configuration file for syntactical accuracy and limits
    if (!validate_config_file(config_file)) {
        return NULL;
    }

    // Allocate memory for the logging context structure
    LoggingContext *logging_ctx = malloc(sizeof(LoggingContext));
    if (logging_ctx == NULL) {
        printf("Error: Failed to allocate memory for logging context\n");
        return NULL;
    }

    // Initialize the thread-safe queue and log buffer
    logging_ctx->queue = initialize_queue();
    if (logging_ctx->queue == NULL) {
        printf("Error: Failed to initialize thread-safe queue\n");
        free(logging_ctx);
        return NULL;
    }
    logging_ctx->log_buffer = malloc(sizeof(char *) * MAX_LOG_BUFFER_SIZE);
    if (logging_ctx->log_buffer == NULL) {
        printf("Error: Failed to allocate memory for log buffer\n");
        free(logging_ctx->queue);
        free(logging_ctx);
        return NULL;
    }

    // Parse the configuration file and store the settings in the logging context structure
    if (!parse_config_file(config_file, logging_ctx)) {
        printf("Error: Failed to parse configuration file\n");
        free(logging_ctx->queue);
        free(logging_ctx->log_buffer);
        free(logging_ctx);
        return NULL;
    }

    // Initialize the metrics collection system
    logging_ctx->metrics = initialize_metric_stats();
    if (logging_ctx->metrics == NULL) {
        printf("Error: Failed to initialize metrics collection system\n");
        free(logging_ctx->queue);
        free(logging_ctx->log_buffer);
        free(logging_ctx);
        return NULL;
    }

    // Return the logging context structure
    return logging_ctx;
}

// Validate the configuration file for syntactical accuracy and limits
bool validate_config_file(const char *config_file) {
    // Open the configuration file and check for errors
    FILE *config_fp = fopen(config_file, "r");
    if (config_fp == NULL) {
        printf("Error: Failed to open configuration file\n");
        return false;
    }

    // Read the contents of the configuration file and check for syntax errors
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, config_fp)) != -1) {
        // Check for empty lines or comments
        if (strcmp(line, "") == 0 || line[0] == '#') {
            continue;
        }

        // Split the line into key-value pairs and validate each setting
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");
        if (key == NULL || value == NULL) {
            printf("Error: Malformed configuration file\n");
            fclose(config_fp);
            return false;
        }
        // Check for valid log levels (e.g., debug, info, warn, error)
        if (strcmp(key, "log_level") == 0) {
            int log_level = atoi(value);
            if (log_level < MIN_LOG_LEVEL || log_level > MAX_LOG_LEVEL) {
                printf("Error: Invalid log level\n");
                fclose(config_fp);
                return false;
            }
        }
        // Check for valid output formats (e.g., text, json)
        else if (strcmp(key, "output_format") == 0) {
            if (!validate_output_format(value)) {
                printf("Error: Invalid output format\n");
                fclose(config_fp);
                return false;
            }
        }
        // Check for valid destinations (e.g., console, file, network)
        else if (strcmp(key, "destination") == 0) {
            if (!validate_destination(value)) {
                printf("Error: Invalid destination\n");
                fclose(config_fp);
                return false;
            }
        }
    }

    // Close the configuration file and return success
    fclose(config_fp);
    return true;
}

// Validate the output format (e.g., text, json)
bool validate_output_format(const char *value) {
    if (strcmp(value, "text") == 0 || strcmp(value, "json") == 0) {
        return true;
    } else {
        return false;
    }
}

// Validate the destination (e.g., console, file, network)
bool validate_destination(const char *value) {
    if (strcmp(value, "console") == 0 || strcmp(value, "file") == 0 || strcmp(value, "network") == 0) {
        return true;
    } else {
        return false;
    }
}

// Initialize the thread-safe queue for logging messages
Queue *initialize_queue() {
    // Allocate memory for the queue structure and initialize it
    Queue *queue = malloc(sizeof(Queue));
    if (queue == NULL) {
        printf("Error: Failed to allocate memory for queue\n");
        return NULL;
    }
    queue->head = NULL;
    queue->tail = NULL;
    queue->size = 0;

    // Initialize the mutex and condition variable for synchronizing access to the queue
    pthread_mutexattr_t attr;
    if (pthread_mutexattr_init(&attr) != 0) {
        printf("Error: Failed to initialize mutex attribute\n");
        free(queue);
        return NULL;
    }
    if (pthread_mutex_init(&queue->mutex, &attr) != 0) {
        printf("Error: Failed to initialize mutex\n");
        pthread_mutexattr_destroy(&attr);
        free(queue);
        return NULL;
    }
    if (pthread_cond_init(&queue->cond, NULL) != 0) {
        printf("Error: Failed to initialize condition variable\n");
        pthread_mutex_destroy(&queue->mutex);
        pthread_mutexattr_destroy(&attr);
        free(queue);
        return NULL;
    }
    if (pthread_condattr_setclock(&queue->cond, CLOCK_MONOTONIC) != 0) {
        printf("Error: Failed to set condition variable clock\n");
        pthread_cond_destroy(&queue->cond);
        pthread_mutex_destroy(&queue->mutex);
        free(queue);
        return NULL;
    }

    // Return the initialized queue structure
    return queue;
}

// Parse the configuration file and store the settings in the logging context structure
bool parse_config_file(const char *config_file, LoggingContext *logging_ctx) {
    // Open the configuration file and check for errors
    FILE *config_fp = fopen(config_file, "r");
    if (config_fp == NULL) {
        printf("Error: Failed to open configuration file\n");
        return false;
    }

    // Read the contents of the configuration file and store the settings in the logging context structure
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, config_fp)) != -1) {
        // Check for empty lines or comments
        if (strcmp(line, "") == 0 || line[0] == '#') {
            continue;
        }

        // Split the line into key-value pairs and store each setting in the logging context structure
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");
        if (key == NULL || value == NULL) {
            printf("Error: Malformed configuration file\n");
            fclose(config_fp);
            return false;
        }
        // Store the log level setting in the logging context structure
        if (strcmp(key, "log_level") == 0) {
            int log_level = atoi(value);
            logging_ctx->log_level = log_level;
        }
        // Store the output format setting in the logging context structure
        else if (strcmp(key, "output_format") == 0) {
            logging_ctx->output_format = value;
        }
        // Store the destination setting in the logging context structure
        else if (strcmp(key, "destination") == 0) {
            logging_ctx->destination = value;
        }
    }

    // Close the configuration file and return success
    fclose(config_fp);
    return true;
}

// Print a message to the console
void print_message(const char *format, ...) {
    va_list args;
    va_start(args, format);
    vprintf(format, args);
    va_end(args);
}

// Log a message to the console and file
void log_message(LoggingContext *logging_ctx, const char *message) {
    // Print the message to the console
    print_message("%s\n", message);

    // Write the message to the log file
    FILE *log_file = fopen(logging_ctx->destination, "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}']

