#include <netdb.h>
#include <stdbool.h>
#include <signal.h>

// Define the size of the arrays that will store the offset and key values
#define OFFSET_ARRAY_SIZE 1024
#define KEY_ARRAY_SIZE 256

// Define a structure to hold the connection state and other relevant information
struct Connection {
    // The socket file descriptor for the connection
    int fd;
    // The address of the remote server
    struct sockaddr_in addr;
    // The size of the receive buffer
    int recv_buffer_size;
    // The size of the send buffer
    int send_buffer_size;
    // The current state of the connection (e.g., CONNECTING, ESTABLISHED)
    int state;
    // The offset array to store the values
    long* offsets;
    // The key array to store the values
    int* keys;
    // The record array to store the records
    struct Record* records;
    // The number of elements in the arrays
    int num_elements;
};

// Define a structure to hold the records
struct Record {
    // An integer value for the record
    int value;
};

// Define a function to initialize the connection state and allocate memory for the arrays
void init_connection(struct Connection* conn) {
    // Initialize the socket file descriptor to -1 (invalid)
    conn->fd = -1;
    // Set the address of the remote server to NULL
    bzero(&conn->addr, sizeof(conn->addr));
    // Set the receive and send buffer sizes to 0
    conn->recv_buffer_size = 0;
    conn->send_buffer_size = 0;
    // Set the state of the connection to CONNECTING
    conn->state = CONNECTING;
    // Allocate memory for the offset and key arrays
    conn->offsets = (long*) malloc(OFFSET_ARRAY_SIZE * sizeof(long));
    conn->keys = (int*) malloc(KEY_ARRAY_SIZE * sizeof(int));
    // Initialize the number of elements in the arrays to 0
    conn->num_elements = 0;
}

// Define a function to establish a connection and handle errors
int connect_to_server(struct Connection* conn, char* server_address, int port) {
    // Create a socket file descriptor for the connection
    conn->fd = socket(AF_INET, SOCK_STREAM, 0);
    if (conn->fd < 0) {
        perror("socket failed");
        return -1;
    }
    // Set the address of the remote server
    struct sockaddr_in* addr = (struct sockaddr_in*) malloc(sizeof(struct sockaddr_in));
    bzero(addr, sizeof(struct sockaddr_in));
    addr->sin_family = AF_INET;
    inet_pton(AF_INET, server_address, &addr->sin_addr);
    addr->sin_port = htons(port);
    // Connect to the remote server
    if (connect(conn->fd, (struct sockaddr*) addr, sizeof(struct sockaddr_in)) < 0) {
        perror("connect failed");
        return -1;
    }
    // Set the receive and send buffer sizes
    conn->recv_buffer_size = 4096;
    conn->send_buffer_size = 4096;
    // Set the state of the connection to ESTABLISHED
    conn->state = ESTABLISHED;
    return 0;
}

// Define a function to check the health of the connection and attempt re-establishment if necessary
void check_connection(struct Connection* conn) {
    // Send a heartbeat message
    char msg[1] = "P";
    send(conn->fd, msg, 1, 0);
    // Monitor for a response
    struct timeval tv;
    tv.tv_sec = 2;
    tv.tv_usec = 0;
    fd_set readfds;
    FD_ZERO(&readfds);
    FD_SET(conn->fd, &readfds);
    if (select(conn->fd+1, &readfds, NULL, NULL, &tv) < 0) {
        perror("select failed");
        return;
    }
    // If the response is not received within the specified time, attempt re-establishment of the connection
    if (!FD_ISSET(conn->fd, &readfds)) {
        printf("Reconnecting...\n");
        close(conn->fd);
        connect_to_server(conn, conn->addr.sin_addr.s_addr, conn->addr.sin_port);
    }
}

// Define a function to handle concurrent access from multiple threads and prevent race conditions
void synchronize(struct Connection* conn) {
    pthread_mutex_lock(&conn->mtx);
    // Do something that requires mutual exclusion here...
    pthread_mutex_unlock(&conn->mtx);
}

// Define a function to manage the allocation and initialization of arrays dynamically
void resize_arrays(struct Connection* conn) {
    // Allocate memory for the offset and key arrays
    long* new_offsets = (long*) realloc(conn->offsets, OFFSET_ARRAY_SIZE * sizeof(long));
    int* new_keys = (int*) realloc(conn->keys, KEY_ARRAY_SIZE * sizeof(int));
    // Initialize the new arrays and free the old ones
    conn->offsets = new_offsets;
    conn->keys = new_keys;
    conn->num_elements = 0;
}

// Define a function to generate random integers in a specified range
int get_random(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Define a function to create a list of random integers and their corresponding keys
void create_random_list(struct Connection* conn, int num_integers, int min, int max) {
    // Generate random integers in the specified range
    for (int i = 0; i < num_integers; i++) {
        int integer = get_random(min, max);
        int key = get_random(0, conn->num_elements - 1);
        // Insert the integer into the array of integers and its corresponding key into the array of keys
        conn->offsets[key] = integer;
    }
}

// Define a function to sort the list of random integers and their corresponding keys using insertion sort
void insertion_sort(struct Connection* conn) {
    // Sort the list of integers and their corresponding keys using insertion sort
    for (int i = 1; i < conn->num_elements; i++) {
        int key = conn->keys[i];
        while (key < conn->keys[key-1]) {
            swap(conn->offsets, conn->keys, i, key);
            i--;
        }
    }
}

// Define a function to print the list of random integers and their corresponding keys
void print_list(struct Connection* conn) {
    // Print the list of integers and their corresponding keys
    printf("List: ");
    for (int i = 0; i < conn->num_elements; i++) {
        printf("%d ", conn->offsets[i]);
    }
    printf("\n");
}

// Define a function to send the list of random integers and their corresponding keys over the network
void send_list(struct Connection* conn) {
    // Send the list of integers and their corresponding keys over the network
    char msg[conn->num_elements * sizeof(long)];
    for (int i = 0; i < conn->num_elements; i++) {
        long integer = htonl(conn->offsets[i]);
        memcpy(msg + i, &integer, sizeof(long));
    }
    send(conn->fd, msg, conn->num_elements * sizeof(long), 0);
}

// Define a function to receive the list of random integers and their corresponding keys from the network
void recv_list(struct Connection* conn) {
    // Receive the list of integers and their corresponding keys from the network
    char msg[conn->num_elements * sizeof(long)];
    recv(conn->fd, msg, conn->num_elements * sizeof(long), 0);
    for (int i = 0; i < conn->num_elements; i++) {
        long integer = ntohl(*(long*)(msg + i));
        conn->offsets[i] = integer;
    }
}

// Define a function to exit the program gracefully
void cleanup(struct Connection* conn) {
    // Close the socket file descriptor
    close(conn->fd);
    // Free the memory allocated for the offset and key arrays
    free(conn->offsets);
    free(conn->keys);
}

// Define a function to handle signals gracefully
void signal_handler(int signum) {
    // Handle the signal gracefully by exiting the program
    cleanup(conn);
    exit(0);
}

int main() {
    // Initialize the connection structure
    struct Connection* conn = (struct Connection*) malloc(sizeof(struct Connection));
    init_connection(conn);
    // Register signal handlers for graceful termination and ignoring SIGPIPE
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    signal(SIGPIPE, SIG_IGN);
    // Establish a connection with the server
    connect_to_server(conn, "localhost", 9090);
    // Create a list of random integers and their corresponding keys
    int num_integers = 10;
    int min = 1;
    int max = 100;
    create_random_list(conn, num_integers, min, max);
    // Sort the list using insertion sort
    insertion_sort(conn);
    // Print the sorted list
    print_list(conn);
    // Send the sorted list over the network
    send_list(conn);
    // Receive the sorted list from the server and print it
    recv_list(conn);
    // Cleanup and exit the program gracefully
    cleanup(conn);
}
```

The above program uses a `Connection` structure to store the socket file descriptor, offset array, and key array. It also defines several functions to handle signals, create a list of random integers, sort it using insertion sort, print the sorted list, send the sorted list over the network, receive the sorted list from the server, and cleanup the program gracefully.

The `main` function first initializes the connection structure, registers signal handlers for graceful termination and ignoring SIGPIPE, establishes a connection with the server using `connect_to_server`, creates a list of random integers and their corresponding keys using `create_random_list`, sorts the list using insertion sort using `insertion_sort`, prints the sorted list using `print_list`, sends the sorted list over the network using `send_list`, receives the sorted list from the server and prints it using `recv_list`, and finally cleans up the program gracefully using `cleanup`.

The output of the program would be something like this:
