#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_CONNECTIONS 10
#define RX_UE_INFORMATION_TAG 0x30
#define RNTI 0x40
#define CRC_INDICATION_REL8_TAG 0x50

// Structure to hold the connection state and data
typedef struct {
    int socket;
    int offset;
    int key;
} ConnectionState;

// Function to establish a resilient connection to a remote server
ConnectionState* establish_connection(char* hostname, char* port) {
    // Create an array for the offsets, keys, and record structures
    long* offset_array = (long*)malloc(sizeof(long) * MAX_CONNECTIONS);
    int* key_array = (int*)malloc(sizeof(int) * MAX_CONNECTIONS);
    Record** record_array = (Record**)malloc(sizeof(Record*) * MAX_CONNECTIONS);

    // Initialize the arrays with random values within a specified range
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        offset_array[i] = rand() % 100;
        key_array[i] = rand() % 100;
        record_array[i] = (Record*)malloc(sizeof(Record));
        record_array[i]->value = rand() % 100;
    }

    // Create a socket and connect to the remote server
    int socket = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in server_address;
    server_address.sin_family = AF_INET;
    inet_pton(AF_INET, hostname, &server_address.sin_addr);
    server_address.sin_port = htons(atoi(port));
    connect(socket, (struct sockaddr*)&server_address, sizeof(server_address));

    // Create a semaphore for thread synchronization
    sem_t* semaphore = sem_open("connection_semaphore", O_CREAT, 0644, 1);

    // Start a thread to manage the connection state and data
    pthread_create(&thread, NULL, connection_manager, (void*)&socket);

    return &ConnectionState{ socket, offset_array, key_array, record_array };
}

// Function to manage the connection state and data in a separate thread
void* connection_manager(void* arg) {
    int socket = *(int*)arg;
    ConnectionState* state = (ConnectionState*)malloc(sizeof(ConnectionState));
    state->socket = socket;

    // Periodically check the health of the connection and attempt re-establishment if lost
    while (1) {
        // Send a heartbeat message and monitor for a response
        send(state->socket, "HEARTBEAT", 8, 0);
        char buffer[256];
        recv(state->socket, buffer, 256, 0);

        // Check if the connection is lost and attempt re-establishment if necessary
        if (strcmp(buffer, "HEARTBEAT") != 0) {
            close(state->socket);
            sem_wait(semaphore);
            state->socket = socket;
            sem_post(semaphore);
        }
    }
}

// Function to populate a list of NFAPI_CRC_INDICATION_PDU_T structures
void populate_list(List* list) {
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pdu->tag = RX_UE_INFORMATION_TAG;
        pdu->rnti = rand() % 100;
        pdu->crc_indication.crcflag = rand() % 2 ? CRC_INDICATION_REL8_TAG : 0;
        list_add(list, pdu);
    }
}

// Function to shut down the connection gracefully and release resources
void close_connection(ConnectionState* state) {
    // Close the socket and destroy the semaphore
    close(state->socket);
    sem_close(semaphore);

    // Release memory for the offset, key, and record arrays
    free(state->offset_array);
    free(state->key_array);
    free(state->record_array);
}
