// Function to efficiently manage memory for multiple arrays and structures
void allocate_memory(size_t offset_size, size_t key_size, size_t record_size, const char* valid_dates[], size_t date_count) {
    // Allocate memory for the offset array
    long *offset_array = malloc(sizeof(long) * offset_size);
    if (!offset_array) {
        printf("Memory allocation failed for the offset array\n");
        return;
    }

    // Allocate memory for the key array
    int *key_array = malloc(sizeof(int) * key_size);
    if (!key_array) {
        printf("Memory allocation failed for the key array\n");
        free(offset_array);
        return;
    }

    // Allocate memory for the record structure array
    Record *record_array = malloc(sizeof(Record) * record_size);
    if (!record_array) {
        printf("Memory allocation failed for the record array\n");
        free(offset_array);
        free(key_array);
        return;
    }

    // Populate the offset array with the valid dates
    size_t i = 0;
    for (i = 0; i < date_count; ++i) {
        strncpy(record_array[i].date, valid_dates[i], 10);
        record_array[i].value = i + 1;
        offset_array[i] = i * sizeof(Record);
    }

    // Free the memory allocated for the offset array and the key array
    free(offset_array);
    free(key_array);

    // Return the record structure array and its size
    return record_array;
}
