    struct LinkedListNode* next;
} LinkedListNode;

// Function to initialize and populate the linked list of LTEPHY_TDL_FDD_RX_FRAME_STATS structures
LTEPHY_TDL_FDD_RX_FRAME_STATS* initAndPopulateLinkedList() {
    // Allocate memory for the head node of the linked list
    LinkedListNode* head = (LinkedListNode*)malloc(sizeof(LinkedListNode));
    if (!head) {
        fprintf(stderr, "Failed to allocate memory for head node\n");
        return NULL;
    }

    // Initialize the head node with a valid frame number and SQI
    head->stats.frameNumber = 100;
    head->stats.SQI = 80;

    // Allocate memory for the tail node of the linked list
    LinkedListNode* tail = (LinkedListNode*)malloc(sizeof(LinkedListNode));
    if (!tail) {
        fprintf(stderr, "Failed to allocate memory for tail node\n");
        return NULL;
    }

    // Initialize the tail node with a valid frame number and SQI
    tail->stats.frameNumber = 100;
    tail->stats.SQI = 80;

    // Set the head node's next pointer to point to the tail node
    head->next = tail;

    // Allocate memory for a temporary node to store the current frame number and SQI
    LinkedListNode* tempNode = (LinkedListNode*)malloc(sizeof(LinkedListNode));
    if (!tempNode) {
        fprintf(stderr, "Failed to allocate memory for temporary node\n");
        return NULL;
    }

    // Loop until the dynamic data acquisition fails or returns incomplete data
    while (1) {
        // Get the current frame number and SQI from the external signal source
        int currentFrameNumber = getCurrentFrameNumber();
        unsigned char currentSQI = getCurrentSQI();

        // If the data acquisition fails, retry after a delay
        if (currentFrameNumber == -1 || currentSQI == -1) {
            fprintf(stderr, "Failed to acquire data from external signal source\n");
            sleep(1);
            continue;
        }

        // Add the current frame number and SQI to the linked list
        tempNode->stats.frameNumber = currentFrameNumber;
        tempNode->stats.SQI = currentSQI;

        // If the head node is empty, set it to point to the new node
        if (!head) {
            head = tempNode;
        } else {
            // Otherwise, add the new node to the end of the linked list
            LinkedListNode* currentNode = head;
            while (currentNode->next != NULL) {
                currentNode = currentNode->next;
            }
            currentNode->next = tempNode;
        }
    }

    // Return a pointer to the head node of the linked list
    return &head->stats;
}
