    net_connection *connections[NET_CONNECTIONS_HASH_SIZE];
} net_connections;

// Define a function to parse network configuration settings from a file
void parse_network_config(char *file) {
    // Open the configuration file for reading
    FILE *fp = fopen(file, "r");
    if (!fp) {
        printf("Error: unable to open network configuration file\n");
        exit(1);
    }

    // Read each line of the file and parse the IP address ranges and port specifications
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, fp)) != -1) {
        // Check for malformed lines and log warnings
        if (strlen(line) > 256) {
            printf("Warning: ignoring malformed network configuration line\n");
            continue;
        }

        // Parse the IP address ranges and port specifications from the line
        char *ip_range = strtok(line, "-");
        if (!ip_range) {
            printf("Error: unable to parse IP address range\n");
            exit(1);
        }
        short src_port = atoi(strtok(NULL, ":"));
        short dst_port = atoi(strtok(NULL, ":"));
        if (src_port < 0 || dst_port < 0) {
            printf("Error: invalid port number\n");
            exit(1);
        }

        // Allocate memory for the new network connection and add it to the hash table
        net_connection *conn = malloc(sizeof(net_connection));
        if (!conn) {
            printf("Error: unable to allocate memory for new network connection\n");
            exit(1);
        }
        conn->id = 0; // Initialize the ID to 0 for now, will be updated later
        conn->src_ip = ip_range;
        conn->dst_ip = ip_range;
        conn->src_port = src_port;
        conn->dst_port = dst_port;
        net_connections *conn_list = get_net_connections();
        add_net_connection(conn, conn_list);
    }

    // Close the configuration file
    fclose(fp);
}

// Define a function to load and cache network configuration data
void load_network_config() {
    char *file = "/path/to/network_config.txt";
    parse_network_config(file);
}

// Define a function to add a new network connection to the hash table
void add_net_connection(net_connection *conn, net_connections *conn_list) {
    // Calculate the hash value for the new connection's ID
    int id = conn->id;
    int hash_val = id % NET_CONNECTIONS_HASH_SIZE;

    // Check if there is already an existing connection with the same ID, and update it if necessary
    net_connection *existing_conn = NULL;
    while (1) {
        existing_conn = conn_list->connections[hash_val];
        if (!existing_conn || existing_conn->id == id) {
            break;
        }
        hash_val++;
        hash_val %= NET_CONNECTIONS_HASH_SIZE;
    }
    if (existing_conn && existing_conn->id == id) {
        // The new connection has the same ID as an existing connection, so update it
        free(existing_conn);
        conn_list->connections[hash_val] = conn;
    } else {
        // No existing connection with the same ID was found, so add the new connection to the hash table
        conn_list->connections[hash_val] = conn;
    }
}

// Define a function to find a network connection by its ID
net_connection *find_net_connection(int id) {
    net_connections *conn_list = get_net_connections();
    int hash_val = id % NET_CONNECTIONS_HASH_SIZE;
    while (1) {
        net_connection *conn = conn_list->connections[hash_val];
        if (!conn || conn->id == id) {
            break;
        }
        hash_val++;
        hash_val %= NET_CONNECTIONS_HASH_SIZE;
    }
    return conn_list->connections[hash_val];
}

// Define a function to update the ID of a network connection
void update_net_connection_id(int old_id, int new_id) {
    net_connection *conn = find_net_connection(old_id);
    if (!conn) {
        printf("Error: unable to find network connection with ID %d\n", old_id);
        exit(1);
    }
    conn->id = new_id;
}

// Define a function to remove a network connection from the hash table
void remove_net_connection(int id) {
    net_connections *conn_list = get_net_connections();
    int hash_val = id % NET_CONNECTIONS_HASH_SIZE;
    while (1) {
        net_connection *conn = conn_list->connections[hash_val];
        if (!conn || conn->id == id) {
            break;
        }
        hash_val++;
        hash_val %= NET_CONNECTIONS_HASH_SIZE;
    }
    free(conn_list->connections[hash_val]);
    conn_list->connections[hash_val] = NULL;
}

// Define a function to initialize the network connection manager
void init_net_connection_manager() {
    net_connections *conn_list = get_net_connections();
    int i;
    for (i=0; i<NET_CONNECTIONS_HASH_SIZE; i++) {
        conn_list->connections[i] = NULL;
    }
}

// Define a function to handle incoming connections
void handle_incoming_connection(int sockfd) {
    // Read the client's request and parse it
    char req[4096];
    read(sockfd, req, 4096);
    printf("Received request: %s\n", req);

    // Extract the ID from the request
    int id = 0;
    sscanf(req, "%d", &id);

    // Find the network connection with the matching ID
    net_connection *conn = find_net_connection(id);
    if (!conn) {
        printf("Error: unable to find network connection with ID %d\n", id);
        exit(1);
    }

    // Update the ID of the network connection and write the response back to the client
    int new_id = conn->id + 1;
    update_net_connection_id(conn->id, new_id);
    char resp[4096];
    sprintf(resp, "%d", new_id);
    write(sockfd, resp, strlen(resp));
}

