    for (int i = 0; i < num_elements; i++) {
        node *new_node = malloc(sizeof(node));
        new_node->data.RX_UE_INFORMATION_TAG = rand() % 256;
        new_node->data.RNTI = rand() % 256;
        new_node->data.CRC_INDICATION_REL8_TAG = rand() % 256;
        new_node->data.CRCFLAG = crcfla[i];
        new_node->next = head;
        if (head != NULL) {
            head->prev = new_node;
        }
        head = new_node;
    }
}

