    while (current != NULL) {
        printf("RX_UE_INFORMATION_TAG: %d\n", current->data.RX_UE_INFORMATION_TAG);
        printf("RNTI: %d\n", current->data.RNTI);
        printf("CRC_INDICATION_REL8_TAG: %d\n", current->data.CRC_INDICATION_REL8_TAG);
        printf("CRCFLAG: %d\n", current->data.CRCFLAG);
        current = current->next;
    }
