#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>

// Struct definitions
typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// List definitions
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pduList;
    size_t listSize;
} NFAPI_CRC_INDICATION_LIST_T;

// Function declarations
NFAPI_CRC_INDICATION_LIST_T *initList();
void freeList(NFAPI_CRC_INDICATION_LIST_T *list);
void addPduToList(NFAPI_CRC_INDICATION_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T pdu);
void removePduFromList(NFAPI_CRC_INDICATION_LIST_T *list, int index);
NFAPI_CRC_INDICATION_PDU_T getPduFromList(NFAPI_CRC_INDICATION_LIST_T *list, int index);
void setPduInList(NFAPI_CRC_INDICATION_LIST_T *list, int index, NFAPI_CRC_INDICATION_PDU_T pdu);
size_t getListSize(NFAPI_CRC_INDICATION_LIST_T *list);
void printList(NFAPI_CRC_INDICATION_LIST_T *list);

// Function definitions
NFAPI_CRC_INDICATION_LIST_T *initList() {
    NFAPI_CRC_INDICATION_LIST_T *list = malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    list->pduList = NULL;
    list->listSize = 0;
    return list;
}

void freeList(NFAPI_CRC_INDICATION_LIST_T *list) {
    if (list == NULL) {
        return;
    }

    // Free the memory for each PDU in the list
    for (size_t i = 0; i < list->listSize; i++) {
        free(list->pduList[i].RX_UE_INFORMATION_TAG);
        free(list->pduList[i].RNTI);
        free(list->pduList[i].CRC_INDICATION_REL8_TAG);
    }

    // Free the memory for the list itself
    free(list->pduList);
    free(list);
}

void addPduToList(NFAPI_CRC_INDICATION_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    // Check if the list is empty and allocate memory for the first PDU
    if (list->pduList == NULL) {
        list->pduList = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        list->listSize = 1;
    } else {
        // Allocate memory for the new PDU and copy the contents of the old one
        NFAPI_CRC_INDICATION_PDU_T *newList = realloc(list->pduList, (list->listSize + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (newList == NULL) {
            printf("Error: Failed to allocate memory for new PDU in list\n");
            return;
        }
        list->pduList = newList;
        memcpy(&list->pduList[list->listSize], &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        list->listSize++;
    }
}

void removePduFromList(NFAPI_CRC_INDICATION_LIST_T *list, int index) {
    if (index < 0 || index >= list->listSize) {
        printf("Error: Invalid index for PDU removal\n");
        return;
    }

    // Remove the PDU at the specified index by shifting all subsequent PDUs one position to the left
    for (size_t i = index + 1; i < list->listSize; i++) {
        memcpy(&list->pduList[i - 1], &list->pduList[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    // Decrement the list size and free the memory for the last PDU
    list->listSize--;
    free(&list->pduList[list->listSize]);
}

NFAPI_CRC_INDICATION_PDU_T getPduFromList(NFAPI_CRC_INDICATION_LIST_T *list, int index) {
    if (index < 0 || index >= list->listSize) {
        printf("Error: Invalid index for PDU retrieval\n");
        return NULL;
    }

    return list->pduList[index];
}

void setPduInList(NFAPI_CRC_INDICATION_LIST_T *list, int index, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (index < 0 || index >= list->listSize) {
        printf("Error: Invalid index for PDU update\n");
        return;
    }

    memcpy(&list->pduList[index], &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

size_t getListSize(NFAPI_CRC_INDICATION_LIST_T *list) {
    return list->listSize;
}

void printList(NFAPI_CRC_INDICATION_LIST_T *list) {
    if (list == NULL) {
        printf("Error: List is NULL\n");
        return;
    }

    // Print each PDU in the list
    for (size_t i = 0; i < list->listSize; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu = list->pduList[i];
        printf("PDU %d: RX_UE_INFORMATION_TAG=%u, RNTI=%u, CRCFLAG=%u\n", i, pdu.RX_UE_INFORMATION_TAG, pdu.RNTI, pdu.CRCFLAG);
    }
}
