void init_tcp_connections(int m) {
    // Allocate memory for the dynamic array
    tcp_connection_states = (struct TCPConnectionState*) malloc(m * sizeof(struct TCPConnectionState));
    if (!tcp_connection_states) {
        fprintf(stderr, "Failed to allocate memory for TCP connection states\n");
        exit(1);
    }

    // Initialize the structs in the array
    for (int i = 0; i < m; ++i) {
        tcp_connection_states[i].connection_id = i;
        tcp_connection_states[i].last_active_timestamp = time(NULL);
        tcp_connection_states[i].current_data_rate = 0.0f;
        tcp_connection_states[i].error_count = 0;
    }
}

// Function to update the state of each connection based on simulated network conditions
void update_tcp_connections() {
    // Simulate network conditions for each connection
    for (int i = 0; i < tcp_connection_states->size; ++i) {
        struct TCPConnectionState* connection = &tcp_connection_states[i];
        time_t current_time = time(NULL);
        float data_rate = simulate_data_rate(current_time - connection->last_active_timestamp);
        if (data_rate > 0) {
            // Update the current data rate and error count for the connection
            connection->current_data_rate += data_rate;
            ++connection->error_count;
        } else {
            // If there is no data rate, assume the connection is in an error state
            connection->current_data_rate = 0.0f;
            connection->error_count = 0;
        }
    }
}

