#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>

// Define the structure to store data packets
struct DataPacket {
    int id;
    long timestamp;
    size_t payloadSize;
    void* payload;
};

// Function to initialize and populate a dynamic array of DataPackets
int initDataPackets(int numPackets, struct DataPacket** packets) {
    // Check if the number of packets is valid
    if (numPackets <= 0) {
        return -1;
    }

    // Allocate memory for the array of pointers to DataPacket structures
    *packets = malloc(sizeof(struct DataPacket*) * numPackets);
    if (*packets == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for data packets\n");
        return -2;
    }

    // Allocate memory for each DataPacket structure and populate it with the given values
    int i;
    for (i = 0; i < numPackets; ++i) {
        (*packets)[i] = malloc(sizeof(struct DataPacket));
        if ((*packets)[i] == NULL) {
            fprintf(stderr, "Error: failed to allocate memory for data packet %d\n", i);
            return -3;
        }
    }

    // Initialize the values of each DataPacket structure
    for (i = 0; i < numPackets; ++i) {
        (*packets)[i]->id = i + 1;
        (*packets)[i]->timestamp = time(NULL);
        (*packets)[i]->payloadSize = rand() % 1024;
        (*packets)[i]->payload = malloc((*packets)[i]->payloadSize);
        if ((*packets)[i]->payload == NULL) {
            fprintf(stderr, "Error: failed to allocate memory for payload of data packet %d\n", i);
            return -4;
        }
    }

    // Return the number of packets initialized successfully
    return numPackets;
}

// Function to serialize and store DataPacket structures in binary format for persistent storage
int persistDataPackets(struct DataPacket** packets, int numPackets) {
    // Check if the number of packets is valid
    if (numPackets <= 0) {
        return -1;
    }

    // Open a file descriptor to write to
    int fd = open("data.bin", O_WRONLY | O_CREAT, S_IRUSR | S_IWUSR);
    if (fd == -1) {
        fprintf(stderr, "Error: failed to open file for writing\n");
        return -2;
    }

    // Write the number of packets to the file header
    int headerSize = sizeof(int);
    if (write(fd, &numPackets, headerSize) != headerSize) {
        fprintf(stderr, "Error: failed to write file header\n");
        return -3;
    }

    // Serialize each DataPacket structure and write it to the file
    int i;
    for (i = 0; i < numPackets; ++i) {
        size_t packetSize = sizeof(struct DataPacket);
        if (write(fd, packets[i], packetSize) != packetSize) {
            fprintf(stderr, "Error: failed to write data packet %d\n", i);
            return -4;
        }
    }

    // Close the file descriptor
    close(fd);

    // Return success
    return 0;
}

// Function to deserialize and load DataPacket structures from binary format for persistent storage
int loadDataPackets(struct DataPacket*** packets, int* numPackets) {
    // Open the file descriptor to read from
    int fd = open("data.bin", O_RDONLY);
    if (fd == -1) {
        fprintf(stderr, "Error: failed to open file for reading\n");
        return -2;
    }

    // Read the number of packets from the file header
    int headerSize = sizeof(int);
    read(fd, numPackets, headerSize);

    // Allocate memory for an array of pointers to DataPacket structures
    *packets = malloc(*numPackets * sizeof(struct DataPacket*));
    if (*packets == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for data packets\n");
        return -3;
    }

    // Deserialize each DataPacket structure from the file and populate the array of pointers
    int i;
    for (i = 0; i < *numPackets; ++i) {
        (*packets)[i] = malloc(sizeof(struct DataPacket));
        if ((*packets)[i] == NULL) {
            fprintf(stderr, "Error: failed to allocate memory for data packet %d\n", i);
            return -4;
        }
    }
    size_t packetSize = sizeof(struct DataPacket);
    for (i = 0; i < *numPackets; ++i) {
        if (read(fd, (*packets)[i], packetSize) != packetSize) {
            fprintf(stderr, "Error: failed to read data packet %d\n", i);
            return -5;
        }
    }

    // Close the file descriptor and return success
    close(fd);
    return 0;
}
