// Function to initialize a dynamic array of NetworkInterfaceConfig structures
void initNetworkInterfaces(vector<NetworkInterfaceConfig>& networkInterfaces, const string& filename) {
    // Load the configurations from file
    ifstream infile(filename);
    if (!infile.is_open()) {
        cerr << "Failed to open input file" << endl;
        return;
    }

    int numInterfaces;
    infile >> numInterfaces;

    networkInterfaces.resize(numInterfaces);

    for (int i = 0; i < numInterfaces; ++i) {
        // Read the interface ID and neighbor cell info
        int interfaceId;
        infile >> interfaceId;
        vector<NeighborCellInfo> neighborCells;
        int numNeighbors;
        infile >> numNeighbors;
        for (int j = 0; j < numNeighbors; ++j) {
            NeighborCellInfo neighborCell;
            infile >> neighborCell.cellId;
            infile >> neighborCell.cellName;
            neighborCells.push_back(neighborCell);
        }

        // Read the SRS parameters
        int srsBandwidth, srsPeriodicity;
        infile >> srsBandwidth;
        infile >> srsPeriodicity;

        networkInterfaces[i] = NetworkInterfaceConfig{interfaceId, neighborCells, SRSParams{srsBandwidth, srsPeriodicity}};
    }
}

// Function to validate the integrity of the NetworkInterfaceConfig structures
bool validateNetworkInterfaces(const vector<NetworkInterfaceConfig>& networkInterfaces) {
    // Check that all NeighborCellInfo keys are unique within each structure
    for (const auto& config : networkInterfaces) {
        unordered_map<int, int> neighborIds;
        for (const auto& neighbor : config.neighborCells) {
            if (neighborIds.find(neighbor.cellId) != neighborIds.end()) {
                // Duplicate neighbor ID found
                return false;
            }
            neighborIds[neighbor.cellId]++;
        }
    }

    return true;
}

// Function to dynamically resize the NetworkInterfaceConfig arrays without losing existing data
void resizeNetworkInterfaces(vector<NetworkInterfaceConfig>& networkInterfaces, int newSize) {
    // Save the current size and data
    int oldSize = networkInterfaces.size();
    vector<NetworkInterfaceConfig> oldData = move(networkInterfaces);

    // Resize the array to the new size
    networkInterfaces.resize(newSize);

    // Copy the existing data to the new array
    for (int i = 0; i < oldSize; ++i) {
        networkInterfaces[i] = move(oldData[i]);
    }
}

