void insertContent(char *contentId, char *title, char *description, char *authorId, char *tags) {
    pthread_mutex_lock(&lock);

    // Check if content already exists
    for (int i = 0; i < numContents; i++) {
        if (strcmp(contentArray[i].contentId, contentId) == 0) {
            printf("Content with ID %s already exists\n", contentId);
            pthread_mutex_unlock(&lock);
