    strcpy(newContent->description, description);
    strcpy(newContent->authorId, authorId);
    strcpy(newContent->tags, tags);

    contentArray = (Content *) realloc(contentArray, (numContents + 1) * sizeof(Content));
    contentArray[numContents++] = newContent;

    pthread_mutex_unlock(&lock);
}

// Thread-safe deletion function
void deleteContent(char *contentId) {
    pthread_mutex_lock(&lock);

    // Check if content exists
    for (int i = 0; i < numContents; i++) {
        if (strcmp(contentArray[i].contentId, contentId) == 0) {
            // Delete the version of the content from the version array
            for (int j = 0; j < numVersions; j++) {
                if (strcmp(versionArray[j]->contentId, contentId) == 0) {
                    free(versionArray[j]);
                    memmove(&versionArray[j], &versionArray[j+1], sizeof(Version*) * (numVersions - j));
                    numVersions--;
                    break;
                }
            }

            // Delete the content from the content array
            free(contentArray[i]);
            memmove(&contentArray[i], &contentArray[i+1], sizeof(Content) * (numContents - i));
            numContents--;

            pthread_mutex_unlock(&lock);
            return;
        }
    }

    printf("Content with ID %s does not exist\n", contentId);
    pthread_mutex_unlock(&lock);
}

