    for (int i = 0; i < numContents; i++) {
        if (strcmp(contentArray[i].contentId, contentId) == 0) {
            if (versionNumber <= versionArray[i]->versionNumber) {
                printf("Version %ld of Content ID: %s\n", versionNumber, contentArray[i].contentId);
                printf("Title: %s\n", contentArray[i].title);
                printf("Description: %s\n", contentArray[i].description);
                printf("Author ID: %s\n", contentArray[i].authorId);
                printf("Tags: %s\n", contentArray[i].tags);
            } else {
                printf("Version %ld of Content ID: %s does not exist\n", versionNumber, contentId);
            }
            pthread_mutex_unlock(&lock);
            return;
        }
    }

    printf("Content with ID %s does not exist\n", contentId);
    pthread_mutex_unlock(&lock);
}
