        (*reports)[i].timestamp.tv_nsec = 0;
    }
}

// Function to add a MeasurementReport to a NetworkDeviceStatusReport
void add_measurement_report(struct NetworkDeviceStatusReport *report, struct MeasurementReport measurement) {
    // Check if the report has enough space for another measurement
    if (report->num_measurements >= 50) {
        fprintf(stderr, "Maximum number of measurements reached for device %d\n", report->device_id);
        return;
    }

    // Check if the signal strength is within a valid range
    if (measurement.signal_strength < 0 || measurement.signal_strength > 100) {
        fprintf(stderr, "Invalid signal strength for device %d: %f\n", report->device_id, measurement.signal_strength);
        return;
    }

    // Add the new measurement to the report
    report->measurement_reports[report->num_measurements] = measurement;
    report->num_measurements++;
}

