uint32_t md5hash(char *str) {
    uint32_t hash = 0; // initialize the hash value

    // Iterate over each character in the string and calculate its corresponding MD5 hash
    while (*str != '\0') {
        hash ^= (uint32_t)*str++; // XOR the current character with the previous hash value
