// Define the structure to represent a transaction
typedef struct {
    double amount;
    char currency[5];
} Transaction;

// Define an array of transactions
Transaction* transactions = NULL;

// Define the size of the array
size_t num_transactions = 0;

// Function to allocate memory for a new transaction
void allocate_transaction(double amount, char* currency) {
    // Check if there is enough memory available
    if (num_transactions == SIZE_MAX / sizeof(Transaction)) {
        printf("Memory allocation failure\n");
        return;
    }

    // Allocate memory for the new transaction
    Transaction* new_transaction = malloc(sizeof(Transaction));
    if (new_transaction == NULL) {
        printf("Memory allocation failure\n");
        return;
    }

    // Set the amount and currency of the new transaction
    new_transaction->amount = amount;
    strncpy(new_transaction->currency, currency, 4);

    // Add the new transaction to the array
    transactions[num_transactions++] = new_transaction;
}

// Function to retrieve a transaction by index
Transaction* get_transaction(size_t index) {
    if (index >= num_transactions) {
        return NULL;
    }

    return transactions[index];
}

// Function to free all allocated memory when the function exits
void cleanup() {
    // Free all memory allocated for the transactions
    for (size_t i = 0; i < num_transactions; i++) {
        free(transactions[i]);
    }

    // Reset the number of transactions to zero
    num_transactions = 0;
}
