    new_node->pdu = pdu;
    new_node->next = NULL;

    if (list->head == NULL) {
        // List is empty, set head and tail to new node
        list->head = new_node;
        list->tail = new_node;
    } else {
        // Add new node to end of the list
        list->tail->next = new_node;
        list->tail = new_node;
    }

    // Increment size and check for capacity increase
    list->size++;
    if (list->size > list->capacity) {
        list->capacity *= 2;
    }

    pthread_mutex_unlock(&list->mutex);
