import java.util.Arrays;
import java.util.List;
import java.util.Random;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.atomic.AtomicInteger;

public class ConnectionPool {
  private static final Random RANDOM = new Random();
  private static final AtomicInteger CONNECTION_ID = new AtomicInteger(0);

  // Configuration parameters
  private int maxConnections;
  private int minLoad;
  private int maxLoad;
  private int connectionTimeout;

  // Internal state
  private List<Connection> connections;
  private int activeConnections;

  public ConnectionPool(int maxConnections, int minLoad, int maxLoad, int connectionTimeout) {
    this.maxConnections = maxConnections;
    this.minLoad = minLoad;
    this.maxLoad = maxLoad;
    this.connectionTimeout = connectionTimeout;

    // Initialize connections list and metrics counters
    this.connections = new CopyOnWriteArrayList<>();
    this.activeConnections = 0;
  }

  public void addConnection(String serverAddress) {
    // Check if there are available slots for a new connection
    int activeConnections = getActiveConnections();
    if (activeConnections < maxConnections) {
      // Initialize the connection and add it to the list of connections
      Connection connection = new Connection(CONNECTION_ID.getAndIncrement(), serverAddress);
      connections.add(connection);
      activeConnections++;

      // Log metrics
      logMetrics(activeConnections, connections.size());
    } else {
      // The pool is full, cannot add more connections
      logMetrics(activeConnections, connections.size(), "Pool is full");
    }
  }

  public void removeConnection(String serverAddress) {
    // Find the connection to be removed and remove it from the list of connections
    Connection connection = findConnection(serverAddress);
    if (connection != null) {
      connections.remove(connection);
      activeConnections--;

      // Log metrics
      logMetrics(activeConnections, connections.size());
    } else {
      // Cannot find the connection to be removed
      logMetrics(activeConnections, connections.size(), "Cannot find connection to remove");
    }
  }

  public void updateConnection(String serverAddress) {
    // Find the connection and update its state
    Connection connection = findConnection(serverAddress);
    if (connection != null) {
      // Update the connection state and log metrics
      connection.updateState();
      logMetrics(activeConnections, connections.size());
    } else {
      // Cannot find the connection to be updated
      logMetrics(activeConnections, connections.size(), "Cannot find connection to update");
    }
  }

  public void gracefulReconnection(String serverAddress) {
    // Find the connection and attempt a graceful reconnection
    Connection connection = findConnection(serverAddress);
    if (connection != null) {
      // Attempt to reconnect the connection and update its state
      boolean isSuccessful = connection.attemptReconnection();
      if (!isSuccessful) {
        logMetrics(activeConnections, connections.size(), "Failed to gracefully reconnect");
      } else {
        // Update the connection state and log metrics
        connection.updateState();
        logMetrics(activeConnections, connections.size());
      }
    } else {
      // Cannot find the connection to be reconnected
      logMetrics(activeConnections, connections.size(), "Cannot find connection to reconnect");
    }
  }

  public int getActiveConnections() {
    return activeConnections;
  }

  private Connection findConnection(String serverAddress) {
    // Iterate over the list of connections and find the one with the specified server address
    for (Connection connection : connections) {
      if (connection.getServerAddress().equals(serverAddress)) {
        return connection;
      }
    }
    return null;
  }

  private void logMetrics(int activeConnections, int totalConnections) {
    // Log metrics using a logging framework or a metrics collector
    LOGGER.info("Active connections: " + activeConnections);
    LOGGER.info("Total connections: " + totalConnections);
  }

  private void logMetrics(int activeConnections, int totalConnections, String message) {
    // Log metrics using a logging framework or a metrics collector
    LOGGER.warn("Active connections: " + activeConnections);
    LOGGER.warn("Total connections: " + totalConnections);
    LOGGER.warn(message);
  }
}
```
