void init_frames(const uint16_t initial_preamble, const uint8_t initial_demux_tag) {
    // Initialize frames array with the given initial parameters
    frames = (LTE_PHY_RX_FRAME *)malloc(DEFAULT_MAX_FRAMES * sizeof(LTE_PHY_RX_FRAME));
    if (!frames) {
