        frames[i].preamble = initial_preamble;
        frames[i].demux_tag = initial_demux_tag;
    }
}

void add_frame(const uint16_t preamble, const uint8_t demux_tag) {
    // Add a new frame to the array, growing the array if necessary
    if (num_frames == max_frames) {
        max_frames *= 2;
        LTE_PHY_RX_FRAME *new_frames = (LTE_PHY_RX_FRAME *)realloc(frames, max_frames * sizeof(LTE_PHY_RX_FRAME));
        if (!new_frames) {
            perror("Error reallocating memory for frames");
            exit(1);
        }
        frames = new_frames;
    }
    frames[next_frame_idx].preamble = preamble;
    frames[next_frame_idx].demux_tag = demux_tag;
    next_frame_idx = (next_frame_idx + 1) % max_frames;
    num_frames++;
}

