    for (size_t i = 0; i < num_frames; ++i) {
        if (frames[i].demux_tag == demux_tag) {
            frames[i] = frames[next_frame_idx];
            next_frame_idx = (next_frame_idx + 1) % max_frames;
            num_frames--;
            return;
        }
    }
}

void update_preamble(const uint16_t preamble, const uint8_t demux_tag) {
    // Update the preamble for the frame with the given demux tag if it exists
    for (size_t i = 0; i < num_frames; ++i) {
        if (frames[i].demux_tag == demux_tag) {
            frames[i].preamble = preamble;
            return;
        }
    }
}

void update_demux_tag(const uint8_t demux_tag, const uint16_t preamble) {
    // Update the demux tag for the frame with the given preamble if it exists
    for (size_t i = 0; i < num_frames; ++i) {
        if (frames[i].preamble == preamble) {
            frames[i].demux_tag = demux_tag;
            return;
        }
    }
}
