```c
#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

// Define the structure for storing a record
typedef struct {
    char key[20];
    double value;
} record_t;

// Define the structure for storing the list of records
typedef struct {
    int size; // The number of elements in the list
    int capacity; // The maximum number of elements that can be stored in the list
    long* offsets; // An array of long integers to store offsets into the record array
    int* keys; // An array of int integers to serve as keys for the records
    record_t** records; // An array of custom record structures, each containing a char array and a double value
} list_t;

// Define the structure for storing the statistics of the list
typedef struct {
    int num_successful_allocations;
    int num_failed_allocations;
} stats_t;

// Define the function that manages the list of records
void manage_records(list_t* list, int size) {
    // Check if the input size is valid
    if (size < 0 || size > 10000) {
        return;
    }

    // Acquire a lock to prevent race conditions and concurrent access from multiple threads
    pthread_mutex_lock(&list->mutex);

    // If the list is empty, initialize it with the given size
    if (list->size == 0) {
        list->capacity = size;
        list->offsets = malloc(sizeof(long) * size);
        list->keys = malloc(sizeof(int) * size);
        list->records = malloc(sizeof(record_t*) * size);
    }

    // If the list is not empty, resize it if necessary
    else {
        if (list->size == list->capacity) {
            list->capacity += 100;
            list->offsets = realloc(list->offsets, sizeof(long) * list->capacity);
            list->keys = realloc(list->keys, sizeof(int) * list->capacity);
            list->records = realloc(list->records, sizeof(record_t*) * list->capacity);
        }
    }

    // Initialize the record structures with random keys and values
    for (int i = 0; i < size; i++) {
        list->offsets[i] = -1;
        list->keys[i] = rand() % 100 + 1;
        list->records[i] = malloc(sizeof(record_t));
        list->records[i]->key[0] = '\0';
        strcpy(list->records[i]->key, "random string");
        list->records[i]->value = rand() % 100 + 1;
    }

    // Update the size of the list and release the lock
    list->size += size;
    pthread_mutex_unlock(&list->mutex);
}

// Define the function that retrieves a record from the list
record_t* get_record(list_t* list, int index) {
    // Check if the input index is valid
    if (index < 0 || index >= list->size) {
        return NULL;
    }

    // Acquire a lock to prevent race conditions and concurrent access from multiple threads
    pthread_mutex_lock(&list->mutex);

    // Return the record at the given index if it exists
    if (list->offsets[index] != -1) {
        record_t* record = list->records[list->offsets[index]];
        pthread_mutex_unlock(&list->mutex);
        return record;
    }

    // If the record does not exist, return NULL and release the lock
    else {
        pthread_mutex_unlock(&list->mutex);
        return NULL;
    }
}

// Define the function that deletes a record from the list
void delete_record(list_t* list, int index) {
    // Check if the input index is valid
    if (index < 0 || index >= list->size) {
        return;
    }

    // Acquire a lock to prevent race conditions and concurrent access from multiple threads
    pthread_mutex_lock(&list->mutex);

    // If the record exists, delete it and update the size of the list
    if (list->offsets[index] != -1) {
        free(list->records[list->offsets[index]]);
        list->size--;
    }

    // Update the offsets array to reflect the deleted record
    for (int i = index + 1; i < list->size; i++) {
        if (list->offsets[i] != -1) {
            list->offsets[i - 1] = list->offsets[i];
        }
    }

    // Release the lock and return
    pthread_mutex_unlock(&list->mutex);
}

// Define the function that updates the statistics of the list
void update_stats(list_t* list) {
    // Acquire a lock to prevent race conditions and concurrent access from multiple threads
    pthread_mutex_lock(&list->mutex);

    // Update the statistics of the list
    stats_t* stats = malloc(sizeof(stats_t));
    stats->num_successful_allocations = 0;
    stats->num_failed_allocations = 0;
    for (int i = 0; i < list->size; i++) {
        if (list->offsets[i] != -1) {
            stats->num_successful_allocations++;
        }
        else {
            stats->num_failed_allocations++;
        }
    }

    // Release the lock and return
    pthread_mutex_unlock(&list->mutex);
}
