    // Loop to set the int value of each record to a random value within a given range
    for (int i = 0; i < num_records; i++) {
        records[i].int_field = rand() % 10 + 5;
    }

    // Efficiently filter transactions based on a set of criteria, including the transaction's age, the number of transactions in the past 3 seconds, and the transaction's weighted sum
    for (int i = 0; i < num_records; i++) {
