    char* dest_ip;
    int protocol_type;
    // Additional user-defined fields can be added dynamically
} packet_header_t;

// Function to initialize and configure a list of custom data structures representing network packet headers
void init_packet_headers(packet_header_t** headers, size_t num_headers) {
    // Allocate memory for the array of packet header pointers
    *headers = malloc(num_headers * sizeof(packet_header_t*));
    if (*headers == NULL) {
        perror("malloc");
        return;
    }

    // Initialize each packet header structure with default values
    for (size_t i = 0; i < num_headers; i++) {
        (*headers)[i] = malloc(sizeof(packet_header_t));
        if ((*headers)[i] == NULL) {
            perror("malloc");
            return;
        }
        (*headers)[i]->length = 0;
        (*headers)[i]->timestamp = 0;
        (*headers)[i]->source_ip = NULL;
        (*headers)[i]->dest_ip = NULL;
        (*headers)[i]->protocol_type = -1;
    }
}

// Function to add a new user-defined field to the packet header structure
void add_user_field(packet_header_t* header, char* name, void* value) {
    // Check if the header is null or if there is already a user field with the same name
    if (header == NULL || strcmp(name, header->name) == 0) {
        return;
    }

    // Allocate memory for the new user field and copy its value
    size_t name_len = strlen(name);
    header->name = malloc(sizeof(char) * (name_len + 1));
    if (header->name == NULL) {
        perror("malloc");
        return;
    }
    memcpy(header->name, name, name_len + 1);

    // Allocate memory for the new user field value and copy its value
    size_t value_size = sizeof(void*);
    header->value = malloc(sizeof(void*) * value_size);
    if (header->value == NULL) {
        perror("malloc");
        return;
    }
    memcpy(header->value, value, value_size);
}

// Function to free the memory allocated for a list of custom data structures representing network packet headers
void free_packet_headers(packet_header_t** headers, size_t num_headers) {
    // Free each packet header structure and its user-defined fields
    for (size_t i = 0; i < num_headers; i++) {
        if ((*headers)[i] != NULL) {
            free((*headers)[i]->name);
            free((*headers)[i]->value);
            free(*headers[i]);
        }
    }

    // Free the memory allocated for the array of packet header pointers
    free(*headers);
}
