        inputData[i].timestamp = timestamp;
        inputData[i].value = value;
    }
    for (int i = 0; i < neighborCellListSize; i++) {
        char* id = (char*)malloc(sizeof(char) * 128);
        if (id == NULL) {
            break;
        }
        strcpy(id, "cell-");
        int randInt = rand() % 10000; // Random integer between 0 and 9999
        sprintf(id + 5, "%d", randInt);
        neighborCellIds[i] = id;
    }

    // Initialize SRS parameters based on predefined template
    SoundingReferenceSignal srs = {.numBits = srsTemplate.numBits, .crcFlag = srsTemplate.crcFlag, .dataLength = srsTemplate.dataLength};

    // Initialize network interfaces with neighbor cell list and SRS parameters
    for (int i = 0; i < 10; i++) {
        NetworkInterfaceConfig interfaceConfig;
        interfaceConfig.interfaceId = "interface-";
        int randInt = rand() % 10000; // Random integer between 0 and 9999
        sprintf(interfaceConfig.interfaceId + 9, "%d", randInt);
        interfaceConfig.neighborCellList = (NeighborCellInfo*)malloc(sizeof(NeighborCellInfo) * neighborCellListSize);
        if (interfaceConfig.neighborCellList == NULL) {
            continue;
        }
        for (int j = 0; j < neighborCellListSize; j++) {
            interfaceConfig.neighborCellList[j].id = neighborCellIds[j];
            double latitude = ((double)rand() / RAND_MAX) * 180 - 90; // Random latitude between -90 and 90 degrees
            double longitude = ((double)rand() / RAND_MAX) * 360 - 180; // Random longitude between -180 and 180 degrees
            interfaceConfig.neighborCellList[j].latitude = latitude;
            interfaceConfig.neighborCellList[j].longitude = longitude;
        }
        interfaceConfig.srs = srs;
        networkInterfaces[i] = interfaceConfig;
    }

    // Periodically update neighbor cell list size based on CRC indication feedback
    NFAPI_CRC_INDICATION_PDU_T crcIndications[MAX_NFAPI_CRC_INDICATION_PDU_T];
    for (int i = 0; i < MAX_NFAPI_CRC_INDICATION_PDU_T; i++) {
        crcIndications[i].numBits = srsTemplate.numBits;
        crcIndications[i].crcFlag = rand() % 2 ? 1 : 0; // Random boolean value for CRC flag
        crcIndications[i].dataLength = srsTemplate.dataLength;
    }
    int neighborCellListSizeUpdateFrequency = 3600; // Update every hour
    while (true) {
        sleep(neighborCellListSizeUpdateFrequency);
        for (int i = 0; i < MAX_NFAPI_CRC_INDICATION_PDU_T; i++) {
            if (crcIndications[i].crcFlag == 1) { // CRC error detected, update neighbor cell list size
                int newNeighborCellListSize = rand() % 10 + 5; // Random integer between 5 and 14
                free(networkInterfaces[i].neighborCellList);
                networkInterfaces[i].neighborCellList = (NeighborCellInfo*)malloc(sizeof(NeighborCellInfo) * newNeighborCellListSize);
                if (networkInterfaces[i].neighborCellList == NULL) {
                    continue;
                }
                for (int j = 0; j < newNeighborCellListSize; j++) {
                    char* id = (char*)malloc(sizeof(char) * 128);
                    if (id == NULL) {
                        break;
                    }
                    strcpy(id, "cell-");
                    int randInt = rand() % 10000; // Random integer between 0 and 9999
                    sprintf(id + 5, "%d", randInt);
                    networkInterfaces[i].neighborCellList[j].id = id;
                }
            }
        }
    }

    // Handle freeing memory for all allocated resources
    for (int i = 0; i < dataPoints; i++) {
        free(inputData[i]);
    }
    for (int i = 0; i < neighborCellListSize; i++) {
        free(neighborCellIds[i]);
    }
    for (int i = 0; i < 10; i++) {
        free(networkInterfaces[i].neighborCellList);
    }
    free(inputData);
    free(neighborCellIds);
    free(networkInterfaces);
}']

