  list->tail = NULL;
}

// Define a function to add an element to the linked list
bool addElementToLinkedList(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T* elem) {
  // Check if the list is empty and set the head pointer if necessary
  if (list->head == NULL) {
    list->head = elem;
  }

  // Set the tail pointer to the current element
  list->tail = elem;

  // Set the next pointer of the previous element to point to the new element
  NFAPI_CRC_INDICATION_PDU_T* prevElem = list->head;
  while (prevElem->next != NULL) {
    prevElem = prevElem->next;
