    // Check if there is enough capacity in the array
    if (mac_contexts_len >= mac_contexts_capacity) {
        // Dynamically resize the array by 25%
        mac_contexts_capacity += (mac_contexts_capacity / 4) + 1;
        mac_contexts = realloc(mac_contexts, sizeof(MAC_CONTEXT_T) * mac_contexts_capacity);
