    list<UserProfile*> profile_list; // List of UserProfile pointers in LRU order
    int size; // Current size of the cache
} Cache;

// Define the thread-safe linked list for storing NFAPI_CRC_INDICATION_PDU_T objects
typedef struct NFAPIData {
    pthread_mutex_t mutex;
    list<NFAPIData*> nfapi_data_list;
} NFAPIData;

// Function to manage a dynamic collection of user profiles within a social media application
int ManageUserProfiles(Cache* cache, int user_id, char* username, char* profile_picture_url) {
    UserProfile* profile = NULL;
    pthread_mutex_lock(&cache->mutex);
    // Check if the user ID already exists in the cache
    if (cache->profile_map.find(user_id) != cache->profile_map.end()) {
        // Update the existing profile
        profile = cache->profile_map[user_id];
        free(profile->username);
        profile->username = strdup(username);
        free(profile->profile_picture_url);
        profile->profile_picture_url = strdup(profile_picture_url);
    } else {
        // Create a new profile
        profile = (UserProfile*) malloc(sizeof(UserProfile));
        profile->user_id = user_id;
        profile->username = strdup(username);
        profile->profile_picture_url = strdup(profile_picture_url);
    }
    // Insert the profile into the cache and LRU list
    cache->profile_map[user_id] = profile;
    cache->profile_list.push_front(profile);
    if (cache->size > cache->max_size) {
        UserProfile* to_remove = cache->profile_list.back();
        free(to_remove->username);
        free(to_remove->profile_picture_url);
        delete to_remove;
        cache->profile_list.pop_back();
    }
    pthread_mutex_unlock(&cache->mutex);
    return 0;
}

// Function to retrieve a user profile from the cache
UserProfile* GetUserProfile(Cache* cache, int user_id) {
    UserProfile* profile = NULL;
    pthread_mutex_lock(&cache->mutex);
    // Check if the user ID exists in the cache
    auto it = cache->profile_map.find(user_id);
    if (it != cache->profile_map.end()) {
        profile = it->second;
        cache->profile_list.remove(profile);
        cache->profile_list.push_front(profile);
    }
    pthread_mutex_unlock(&cache->mutex);
    return profile;
}

// Function to delete a user profile from the cache
void DeleteUserProfile(Cache* cache, int user_id) {
    UserProfile* profile = NULL;
    pthread_mutex_lock(&cache->mutex);
    // Check if the user ID exists in the cache
    auto it = cache->profile_map.find(user_id);
    if (it != cache->profile_map.end()) {
        profile = it->second;
        free(profile->username);
        free(profile->profile_picture_url);
        delete profile;
        cache->profile_map.erase(it);
        cache->profile_list.remove(profile);
    }
    pthread_mutex_unlock(&cache->mutex);
}

