void mangeMemory(size_t longOffsetSize, size_t intKeySize, size_t recordSize) {
    // Allocate memory dynamically for the arrays based on user-provided sizes
    long *longOffsets = malloc(longOffsetSize * sizeof(long));
    int *intKeys = malloc(intKeySize * sizeof(int));
    Record *records = malloc(recordSize * sizeof(Record));

    // Initialize the 'record' structures with timestamps and 'int' values within a specified range
    for (size_t i = 0; i < recordSize; i++) {
        records[i].timestamp = (uint64_t)time(NULL);
        records[i].value = rand() % 100;
    }

    // Populate 'record' structures with unique 'key' values from the 'int' array, avoiding duplicates through retries up to five times
    for (size_t i = 0; i < recordSize; i++) {
        records[i].key = intKeys[rand() % intKeySize];
        if (records[i].key == -1) {
            // If the key is not found, try again up to five times
            for (size_t j = 0; j < 5; j++) {
                records[i].key = intKeys[rand() % intKeySize];
                if (records[i].key != -1) {
                    break;
                }
            }
        }
    }

    // Set the 'offset' field to a random value within a specified range, avoiding zero to prevent indexing errors
    for (size_t i = 0; i < recordSize; i++) {
        records[i].offset = rand() % 1000;
    }

    // Evaluate and choose between a linked list and a hash table for the secondary data structure based on cache locality, memory usage, and concurrent access patterns
    struct LinkedListNode *linkedListHead = NULL;
    int hashTableSize = 1024;
    struct HashTableNode *hashTable = malloc(sizeof(struct HashTableNode) * hashTableSize);
