        // Add the record to the appropriate data structure
        if (records[i].offset % 2 == 0) {
            linkedListHead = addRecordToLinkedList(linkedListHead, &records[i]);
        } else {
            int hashTableIndex = records[i].key % hashTableSize;
            struct HashTableNode *newNode = malloc(sizeof(struct HashTableNode));
            newNode->next = hashTable[hashTableIndex];
            hashTable[hashTableIndex] = newNode;
        }
    }

    // Implement a fallback mechanism for seeding if the process ID and counter do not yield sufficient uniqueness
    srand(getpid() * time(NULL));

    // Set thread safety with lock-free algorithms to support concurrent access, considering the impact of synchronization on overall throughput
    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    // Handle edge cases like negative inputs and large integer limits, ensuring robust performance under all conditions
    if (longOffsetSize < 0 || intKeySize < 0 || recordSize < 0) {
        fprintf(stderr, "Invalid input: longOffsetSize = %zu, intKeySize = %zu, recordSize = %zu\n", longOffsetSize, intKeySize, recordSize);
        return;
    }

    // Log memory allocation events and evaluate performance implications, prioritizing log granularity to avoid unnecessary system overhead
