    bool crc_flag;
};

struct record {
    struct data_point *data_points[MAX_DATA_POINTS];
    struct NFAPI_CRC_INDICATION_PDU_T *NFAPI_CRC_INDICATION_PDUS[MAX_NFAPI_CRC_INDICATION_PDUS];
};

struct record_list {
    struct record *records;
    int count;
};

int generate_random_value(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

void initialize_record_list(struct record_list *list) {
    list->records = NULL;
    list->count = 0;
}

void free_record_list(struct record_list *list) {
    for (int i = 0; i < list->count; i++) {
        struct record *record = &list->records[i];
        for (int j = 0; j < MAX_DATA_POINTS; j++) {
            if (record->data_points[j] != NULL) {
                free(record->data_points[j]);
            }
        }
    }
    free(list->records);
}

struct record *allocate_record() {
    struct record *record = malloc(sizeof(struct record));
    if (record == NULL) {
        return NULL;
    }
    for (int i = 0; i < MAX_DATA_POINTS; i++) {
        record->data_points[i] = NULL;
    }
    for (int i = 0; i < MAX_NFAPI_CRC_INDICATION_PDUS; i++) {
        record->NFAPI_CRC_INDICATION_PDUS[i] = NULL;
    }
    return record;
}

struct data_point *allocate_data_point() {
    struct data_point *data_point = malloc(sizeof(struct data_point));
    if (data_point == NULL) {
        return NULL;
    }
    return data_point;
}

struct NFAPI_CRC_INDICATION_PDU_T *allocate_NFAPI_CRC_INDICATION_PDU() {
    struct NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
    if (pdu == NULL) {
        return NULL;
    }
    pdu->tag = NULL;
    pdu->rnti = 0;
    pdu->crc_flag = false;
    return pdu;
}

void insert_record(struct record_list *list, struct record *record) {
    if (list->count == 0) {
        list->records = malloc(sizeof(struct record));
        if (list->records == NULL) {
            return;
        }
    } else {
        list->records = realloc(list->records, sizeof(struct record) * (list->count + 1));
        if (list->records == NULL) {
            return;
        }
    }
    memcpy(&list->records[list->count], record, sizeof(struct record));
    list->count++;
}

void remove_record(struct record_list *list, int index) {
    if (index >= list->count || index < 0) {
        return;
    }
    for (int i = index + 1; i < list->count; i++) {
        memcpy(&list->records[i - 1], &list->records[i], sizeof(struct record));
    }
    list->count--;
}

void insert_data_point(struct record *record, struct data_point *data_point) {
    for (int i = 0; i < MAX_DATA_POINTS; i++) {
        if (record->data_points[i] == NULL) {
            memcpy(&record->data_points[i], data_point, sizeof(struct data_point));
            return;
        }
    }
}

void remove_data_point(struct record *record, int index) {
    if (index >= MAX_DATA_POINTS || index < 0) {
        return;
    }
    for (int i = index + 1; i < MAX_DATA_POINTS; i++) {
        memcpy(&record->data_points[i - 1], &record->data_points[i], sizeof(struct data_point));
    }
}

void insert_NFAPI_CRC_INDICATION_PDU(struct record *record, struct NFAPI_CRC_INDICATION_PDU_T *pdu) {
    for (int i = 0; i < MAX_NFAPI_CRC_INDICATION_PDUS; i++) {
        if (record->NFAPI_CRC_INDICATION_PDUS[i] == NULL) {
            memcpy(&record->NFAPI_CRC_INDICATION_PDUS[i], pdu, sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
            return;
        }
    }
}

void remove_NFAPI_CRC_INDICATION_PDU(struct record *record, int index) {
    if (index >= MAX_NFAPI_CRC_INDICATION_PDUS || index < 0) {
        return;
    }
    for (int i = index + 1; i < MAX_NFAPI_CRC_INDICATION_PDUS; i++) {
        memcpy(&record->NFAPI_CRC_INDICATION_PDUS[i - 1], &record->NFAPI_CRC_INDICATION_PDUS[i], sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
    }
}

int main() {
    srand(time(NULL));

    struct record_list list;
    initialize_record_list(&list);

    for (int i = 0; i < MAX_RECORDS; i++) {
        struct record *record = allocate_record();
        if (record == NULL) {
            break;
        }
        insert_record(&list, record);
    }

    while (true) {
        char command[1024];
        scanf("%s", command);
        if (strcmp(command, "insert") == 0) {
