            struct record *record = list.records[record_index];
            insert_data_point(record, data_point);
        } else if (strcmp(command, "remove") == 0) {
            int record_index, data_point_index;
            scanf("%d %d", &record_index, &data_point_index);
            struct record *record = list.records[record_index];
            remove_data_point(record, data_point_index);
        } else if (strcmp(command, "insert_NFAPI") == 0) {
            struct NFAPI_CRC_INDICATION_PDU *pdu = allocate_NFAPI_CRC_INDICATION_PDU();
            if (pdu == NULL) {
