RXInfo *rx_info_array = NULL;
size_t rx_info_count = 0;

// Function to add a new RX information structure to the array
void add_rx_info(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Check if the array is full
    if (rx_info_count == SIZE_MAX) {
        printf("ERROR: RX info array is full\n");
        return;
    }

    // Allocate memory for a new structure
    RXInfo *new_info = malloc(sizeof(RXInfo));
    if (!new_info) {
        printf("ERROR: Failed to allocate memory for RX info\n");
        return;
    }

    // Set the pointer and increment the count
    new_info->pdu = pdu;
    rx_info_count++;

    // Reallocate the array if necessary
    if (rx_info_array == NULL) {
        rx_info_array = malloc(sizeof(RXInfo) * rx_info_count);
        if (!rx_info_array) {
            printf("ERROR: Failed to allocate memory for RX info array\n");
            free(new_info);
            return;
        }
    } else {
        rx_info_array = realloc(rx_info_array, sizeof(RXInfo) * rx_info_count);
        if (!rx_info_array) {
            printf("ERROR: Failed to reallocate memory for RX info array\n");
            free(new_info);
            return;
        }
    }

    // Set the new structure in the array
    rx_info_array[rx_info_count - 1] = *new_info;
}

// Function to remove an RX information structure from the array
void remove_rx_info(size_t index) {
    if (index >= rx_info_count) {
        printf("ERROR: Invalid index for RX info\n");
        return;
    }

    // Free the memory associated with the structure
    free(rx_info_array[index].pdu);

    // Shift all structures after the removed one
    for (size_t i = index + 1; i < rx_info_count - 1; i++) {
        rx_info_array[i - 1] = rx_info_array[i];
    }

    // Decrement the count and reallocate the array if necessary
    rx_info_count--;
    if (rx_info_count == 0) {
        free(rx_info_array);
        rx_info_array = NULL;
    } else {
        rx_info_array = realloc(rx_info_array, sizeof(RXInfo) * rx_info_count);
        if (!rx_info_array) {
            printf("ERROR: Failed to reallocate memory for RX info array\n");
        }
    }
}

// Function to serialize the entire array into a binary format
void serialize_rx_info(char *buffer, size_t buffer_size) {
    // Check if the buffer is large enough
    if (buffer_size < sizeof(RXInfo)) {
        printf("ERROR: Serialization buffer is too small\n");
        return;
    }

    // Serialize each structure in the array
    for (size_t i = 0; i < rx_info_count; i++) {
        memcpy(buffer, &rx_info_array[i], sizeof(RXInfo));
        buffer += sizeof(RXInfo);
    }
}

// Function to deserialize the serialized array into its original structures
void deserialize_rx_info(char *buffer, size_t buffer_size) {
    // Check if the buffer is large enough
    if (buffer_size < sizeof(RXInfo)) {
        printf("ERROR: Deserialization buffer is too small\n");
        return;
    }

    // Create a new array for the deserialized structures
    RXInfo *deserialized_array = malloc(sizeof(RXInfo) * (buffer_size / sizeof(RXInfo)));
    if (!deserialized_array) {
        printf("ERROR: Failed to allocate memory for deserialized array\n");
        return;
    }

    // Deserialize each structure in the buffer
    size_t i = 0;
    while (i < buffer_size / sizeof(RXInfo)) {
        memcpy(&deserialized_array[i], buffer, sizeof(RXInfo));
        buffer += sizeof(RXInfo);
        i++;
    }

    // Replace the old array with the deserialized one
    if (rx_info_count > 0) {
        free(rx_info_array);
    }
    rx_info_array = deserialized_array;
    rx_info_count = i;
}
