```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the maximum number of frames that can be stored in the list
#define MAX_FRAMES 10000

// Define the structure to hold information about each frame
typedef struct LTE_PHY_RX_FRAME {
    PDCP_PDU_T *pdcp;
    float snr;
    float sinr;
    uint64_t timestamp;
} LTE_PHY_RX_FRAME;

// Define the list of frames
LTE_PHY_RX_FRAME *frames = NULL;
size_t num_frames = 0;
pthread_mutex_t frame_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize the list of frames
void init_frames(int max_frames) {
    // Check if the input parameter exceeds the maximum allowed value
    if (max_frames > MAX_FRAMES) {
        fprintf(stderr, "Error: Maximum number of frames exceeded\n");
        return;
    }

    // Allocate memory for the list of frames
    frames = malloc(sizeof(LTE_PHY_RX_FRAME) * max_frames);
    if (frames == NULL) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        return;
    }
}

// Function to add a new frame to the list
void add_frame(PDCP_PDU_T *pdcp, float snr, float sinr, uint64_t timestamp) {
    // Acquire the lock for the frame list
    pthread_mutex_lock(&frame_lock);

    // Check if the list of frames is full
    if (num_frames >= MAX_FRAMES) {
        fprintf(stderr, "Warning: Frame list is full\n");
        return;
    }

    // Add the new frame to the list
    frames[num_frames].pdcp = pdcp;
    frames[num_frames].snr = snr;
    frames[num_frames].sinr = sinr;
    frames[num_frames].timestamp = timestamp;
    num_frames++;

    // Release the lock for the frame list
    pthread_mutex_unlock(&frame_lock);
}

// Function to periodically purge old frames from the list
void purge_old_frames() {
    // Acquire the lock for the frame list
    pthread_mutex_lock(&frame_lock);

    // Check if there are any frames in the list
    if (num_frames == 0) {
        fprintf(stderr, "Warning: No frames to purge\n");
        return;
    }

    // Purge old frames from the list
    for (int i = num_frames - 1; i >= 0; i--) {
        if (frames[i].timestamp < get_current_time()) {
            memmove(frames + i, frames + i + 1, sizeof(LTE_PHY_RX_FRAME) * (num_frames - i));
            num_frames--;
        } else {
            break;
        }
    }

    // Release the lock for the frame list
    pthread_mutex_unlock(&frame_lock);
}

// Function to get the current time in nanoseconds
uint64_t get_current_time() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return (uint64_t)(ts.tv_sec * 1000000000 + ts.tv_nsec);
}
```
