void* CustomAllocator(size_t size) {
  // Allocate memory from the heap using malloc() with additional sanity checks
  void *ptr = malloc(size);
  assert(ptr != NULL && "Failed to allocate memory");
  return ptr;
}

// Define a mutex for thread-safe access to the dynamic array
pthread_mutex_t lock;

// Define a function to initialize the dynamic array and its associated variables
void InitDynamicArray() {
  // Initialize the dynamic array with a default size of 10 elements
  LTE_PHY_TEST_CONFIG_PDU_T *arr = (LTE_PHY_TEST_CONFIG_PDU_T*)CustomAllocator(sizeof(LTE_PHY_TEST_CONFIG_PDU_T) * 10);

  // Initialize the current size of the array to 0
  int currSize = 0;

  // Set the mutex for thread-safe access
  pthread_mutex_init(&lock, NULL);
}

// Define a function to add an element to the dynamic array
void AddElement(int TEST_MODE, int PHY_LAYER_VERSION, int CHANNEL_TYPE) {
  // Lock the mutex for thread-safe access
  pthread_mutex_lock(&lock);

  // Check if the current size of the array is greater than or equal to its capacity
  if (currSize >= arr->size) {
    // Double the size of the array if it's full
    LTE_PHY_TEST_CONFIG_PDU_T *newArr = (LTE_PHY_TEST_CONFIG_PDU_T*)CustomAllocator(sizeof(LTE_PHY_TEST_CONFIG_PDU_T) * arr->size * 2);
    memcpy(newArr, arr, sizeof(LTE_PHY_TEST_CONFIG_PDU_T) * currSize);
    free(arr);
    arr = newArr;
  }

  // Add the new element to the end of the array
  arr[currSize].TEST_MODE = TEST_MODE;
  arr[currSize].PHY_LAYER_VERSION = PHY_LAYER_VERSION;
  arr[currSize].CHANNEL_TYPE = CHANNEL_TYPE;
  currSize++;

  // Unlock the mutex
  pthread_mutex_unlock(&lock);
}

// Define a function to get an element from the dynamic array by its index
LTE_PHY_TEST_CONFIG_PDU_T GetElement(int idx) {
  assert(idx >= 0 && idx < currSize && "Index out of bounds");
  return arr[idx];
}

// Define a function to delete an element from the dynamic array by its index
void DeleteElement(int idx) {
  assert(idx >= 0 && idx < currSize && "Index out of bounds");

  // Lock the mutex for thread-safe access
  pthread_mutex_lock(&lock);

  // Shift all elements after the deleted element to the left
  for (int i = idx; i < currSize - 1; i++) {
    arr[i] = arr[i + 1];
  }

  // Decrease the current size of the array
  currSize--;

  // Unlock the mutex
  pthread_mutex_unlock(&lock);
}

// Define a function to clear the dynamic array and release its memory
void ClearDynamicArray() {
  // Lock the mutex for thread-safe access
  pthread_mutex_lock(&lock);

  // Release the memory allocated for the dynamic array
  free(arr);

  // Reset the current size of the array to 0
  currSize = 0;

  // Unlock the mutex
  pthread_mutex_unlock(&lock);
}
