// Define struct for MAC-CE message
typedef struct {
    unsigned short id; // Unique ID for each MAC-CE message
    bool uci_flags[4]; // Uplink control information flags (BCH, BCCH, MCS)
} mac_ce_msg;

// Define list data structure for holding MAC-CE messages
typedef struct {
    int size; // Current size of the list
    int max_size; // Maximum allowed size of the list
    mac_ce_msg* msgs[]; // Array of MAC-CE messages
} mac_ce_list;

// Function to initialize and configure a list of MAC-CE messages
void init_mac_ce_list(mac_ce_list* list) {
    list->size = 0;
    list->max_size = 1024; // Set maximum allowed size for the list
}

// Function to add a new MAC-CE message to the list
void add_mac_ce_msg(mac_ce_list* list, unsigned short id, bool uci_flags[4]) {
    if (list->size < list->max_size) { // Check if list size is within limits
        mac_ce_msg new_msg;
        new_msg.id = id;
        memcpy(new_msg.uci_flags, uci_flags, 4);
        list->msgs[list->size++] = new_msg; // Add new message to the end of the list
    } else { // If list size is at maximum, resize it by half
        int new_size = list->max_size / 2;
        mac_ce_msg* new_msgs = malloc(sizeof(mac_ce_msg) * new_size);
        memcpy(new_msgs, list->msgs, sizeof(mac_ce_msg) * list->max_size);
        free(list->msgs);
        list->msgs = new_msgs;
        list->max_size = new_size;
    }
}

// Function to remove a MAC-CE message from the list
void remove_mac_ce_msg(mac_ce_list* list, unsigned short id) {
    int i;
    for (i = 0; i < list->size; i++) { // Search for the specified ID in the list
        if (list->msgs[i].id == id) {
            break;
        }
    }
    if (i < list->size - 1) { // If the ID is found, shift the remaining messages to fill the gap
        memmove(&list->msgs[i], &list->msgs[i + 1], sizeof(mac_ce_msg) * (list->size - i));
    }
    list->size--; // Decrement the list size
}

// Function to retrieve a MAC-CE message from the list by ID
bool get_mac_ce_msg(mac_ce_list* list, unsigned short id, mac_ce_msg** msg) {
    int i;
    for (i = 0; i < list->size; i++) { // Search for the specified ID in the list
        if (list->msgs[i].id == id) {
            break;
        }
    }
    if (i < list->size) { // If the ID is found, return a pointer to the message
        *msg = &list->msgs[i];
        return true;
    } else {
        return false;
    }
}

// Function to update UCI flags for a MAC-CE message
void update_uci(mac_ce_list* list, unsigned short id, bool uci_flags[4]) {
    mac_ce_msg* msg = get_mac_ce_msg(list, id); // Get the message by ID
    if (msg != NULL) { // If the message is found, update its UCI flags
        memcpy(msg->uci_flags, uci_flags, 4);
    }
}

// Function to print a MAC-CE list
void print_mac_ce_list(mac_ce_list* list) {
    int i;
    for (i = 0; i < list->size; i++) { // Iterate over the list of messages
        printf("MAC-CE message %d: ID=%hu, UCI flags=[%d, %d, %d, %d]\n", i + 1, list->msgs[i].id, list->msgs[i].uci_flags[0], list->msgs[i].uci_flags[1], list->msgs[i].uci_flags[2], list->msgs[i].uci_flags[3]);
    }
}

int main() {
    // Test the functions by adding and removing MAC-CE messages
    mac_ce_list* list = malloc(sizeof(mac_ce_list));
    init_mac_ce_list(list);
    add_mac_ce_msg(list, 1, [true, false, true, false]); // Add message with ID=1 and UCI flags
    remove_mac_ce_msg(list, 1); // Remove the added message
    free(list);
    return 0;
}']

