    struct RX_UE_INFORMATION_NODE* next;
} RX_UE_INFORMATION_NODE;

// Define a function to allocate and initialize a new node in the linked list
RX_UE_INFORMATION_NODE* createNewNode(int rnti, bool crcFlag) {
    // Allocate memory for the new node
    RX_UE_INFORMATION_NODE* newNode = malloc(sizeof(RX_UE_INFORMATION_NODE));
    if (newNode == NULL) {
        printf("Error: Failed to allocate memory for new node\n");
        return NULL;
    }

    // Initialize the data for the new node
    newNode->rxUeInformation.rnti = rnti;
    newNode->crcIndicationRel8.crcFlag = crcFlag;
    newNode->next = NULL;

    return newNode;
}

// Define a function to add an element to the end of the linked list
void appendElement(RX_UE_INFORMATION_NODE** headRef, int rnti, bool crcFlag) {
    // Check if the linked list is empty
    if (*headRef == NULL) {
        *headRef = createNewNode(rnti, crcFlag);
        return;
    }

    // Traverse to the end of the linked list
    RX_UE_INFORMATION_NODE* current = *headRef;
    while (current->next != NULL) {
        current = current->next;
    }

    // Add a new element to the end of the linked list
    current->next = createNewNode(rnti, crcFlag);
}

// Define a function to free the memory allocated for the linked list
void freeList(RX_UE_INFORMATION_NODE** headRef) {
    // Check if the linked list is empty
    if (*headRef == NULL) {
        return;
    }

    // Traverse through the linked list and free the memory for each node
    RX_UE_INFORMATION_NODE* current = *headRef;
    while (current != NULL) {
        RX_UE_INFORMATION_NODE* temp = current;
        current = current->next;
        free(temp);
    }
}

// Define a function to iterate over the linked list without copying its contents
void iterateList(RX_UE_INFORMATION_NODE** headRef) {
    // Check if the linked list is empty
    if (*headRef == NULL) {
        return;
    }

    // Traverse through the linked list and print the data for each node
    RX_UE_INFORMATION_NODE* current = *headRef;
    while (current != NULL) {
        printf("RNTI: %d, CRC Flag: %s\n", current->rxUeInformation.rnti, current->crcIndicationRel8.crcFlag ? "true" : "false");
        current = current->next;
    }
}

// Define a function to read the input from standard input and add each integer to the linked list
void processInput(RX_UE_INFORMATION_NODE** headRef) {
    // Read the input from standard input
    int rnti;
    bool crcFlag;
    while (scanf("%d %d", &rnti, &crcFlag) == 2) {
        appendElement(headRef, rnti, crcFlag);
    }
}

// Define a function to resize the linked list if necessary
void resizeList(RX_UE_INFORMATION_NODE** headRef) {
    // Check if the linked list is empty
    if (*headRef == NULL) {
        return;
    }

    // Traverse through the linked list and check if it needs to be resized
    RX_UE_INFORMATION_NODE* current = *headRef;
    while (current != NULL) {
        if (current->next == NULL) {
            break;
        }
        current = current->next;
    }

    // Resize the linked list if necessary
    if (current == NULL) {
        RX_UE_INFORMATION_NODE* newNode = createNewNode(0, false);
        current->next = newNode;
    }
}

// Define a function to print the contents of the linked list
void printList(RX_UE_INFORMATION_NODE** headRef) {
    // Check if the linked list is empty
    if (*headRef == NULL) {
        printf("Linked List is Empty\n");
        return;
    }

    // Traverse through the linked list and print the data for each node
    RX_UE_INFORMATION_NODE* current = *headRef;
    while (current != NULL) {
        printf("RNTI: %d, CRC Flag: %s\n", current->rxUeInformation.rnti, current->crcIndicationRel8.crcFlag ? "true" : "false");
        current = current->next;
    }
}

// Define a function to free the memory allocated for the linked list and log any errors that may have occurred
void cleanup(RX_UE_INFORMATION_NODE** headRef) {
    // Free the memory allocated for the linked list
    freeList(headRef);

    // Log any errors that may have occurred
    if (errno != 0) {
        printf("Error: %s\n", strerror(errno));
    }
}

