typedef struct {
    uint32_t interfaceId;
    NeighborCellInfo *neighborCells;
    SRSParams srsParams;
} NetworkInterfaceConfig;

static const int MAX_NUM_INTERFACES = 100; // configurable upper limit on number of interfaces
static pthread_mutex_t interfaceLock = PTHREAD_MUTEX_INITIALIZER; // lock for synchronizing access to the network interface list
static NetworkInterfaceConfig *interfaceList = NULL; // list of all network interfaces
static int numInterfaces = 0; // number of interfaces in the list
static bool resourceManagerInitialized = false; // flag indicating whether the resource manager has been initialized

void initializeResourceManager() {
    if (!resourceManagerInitialized) {
        pthread_mutexattr_t mutexAttr;
        pthread_mutexattr_init(&mutexAttr);
        pthread_mutexattr_settype(&mutexAttr, PTHREAD_MUTEX_ERRORCHECK);
        pthread_mutex_init(&interfaceLock, &mutexAttr);
        resourceManagerInitialized = true;
    }
}

int createNetworkInterface(uint32_t interfaceId) {
    if (!resourceManagerInitialized) {
        initializeResourceManager();
    }
    pthread_mutex_lock(&interfaceLock);
    // check if the requested interface ID is already in use
    for (int i = 0; i < numInterfaces; i++) {
        if (interfaceList[i].interfaceId == interfaceId) {
            pthread_mutex_unlock(&interfaceLock);
            return -1; // error: requested interface ID is already in use
        }
    }
    // allocate memory for the new network interface
    NetworkInterfaceConfig *newInterface = (NetworkInterfaceConfig *)malloc(sizeof(NetworkInterfaceConfig));
    if (!newInterface) {
        pthread_mutex_unlock(&interfaceLock);
        return -1; // error: out of memory
    }
    // initialize the new network interface
    newInterface->interfaceId = interfaceId;
    newInterface->neighborCells = NULL;
    newInterface->srsParams.numNeighbors = 0;
    memset(&newInterface->srsParams, 0, sizeof(SRSParams));
    // add the new network interface to the list of interfaces
    interfaceList[numInterfaces++] = *newInterface;
    pthread_mutex_unlock(&interfaceLock);
    return 0; // success
}

int deleteNetworkInterface(uint32_t interfaceId) {
    if (!resourceManagerInitialized) {
        initializeResourceManager();
    }
    pthread_mutex_lock(&interfaceLock);
    // find the network interface with the requested ID in the list of interfaces
    for (int i = 0; i < numInterfaces; i++) {
        if (interfaceList[i].interfaceId == interfaceId) {
            // remove the network interface from the list of interfaces
            NetworkInterfaceConfig *removedInterface = &interfaceList[i];
            memset(removedInterface, 0, sizeof(NetworkInterfaceConfig));
            for (int j = i + 1; j < numInterfaces; j++) {
                interfaceList[j - 1] = interfaceList[j];
            }
            numInterfaces--;
            // free the memory allocated to the network interface
            free(removedInterface);
            break;
        }
    }
    pthread_mutex_unlock(&interfaceLock);
    return 0; // success
}

int populateNeighborCellList(uint32_t interfaceId, int numEntries) {
    if (!resourceManagerInitialized) {
        initializeResourceManager();
    }
    pthread_mutex_lock(&interfaceLock);
    // find the network interface with the requested ID in the list of interfaces
    for (int i = 0; i < numInterfaces; i++) {
        if (interfaceList[i].interfaceId == interfaceId) {
            NetworkInterfaceConfig *interface = &interfaceList[i];
            // allocate memory for the neighbor cell list
            NeighborCellInfo *neighborCells = (NeighborCellInfo *)malloc(numEntries * sizeof(NeighborCellInfo));
            if (!neighborCells) {
                pthread_mutex_unlock(&interfaceLock);
                return -1; // error: out of memory
            }
            // populate the neighbor cell list with unique IDs and no duplicates
            for (int j = 0; j < numEntries; j++) {
                neighborCells[j].cellId = j + 1;
                bool duplicateFound = false;
                for (int k = 0; k < j; k++) {
                    if (neighborCells[k].cellId == neighborCells[j].cellId) {
                        duplicateFound = true;
                        break;
                    }
                }
                if (duplicateFound) {
                    free(neighborCells);
                    pthread_mutex_unlock(&interfaceLock);
                    return -1; // error: neighbor cell list contains duplicates
                }
            }
            interface->neighborCells = neighborCells;
            interface->srsParams.numNeighbors = numEntries;
            pthread_mutex_unlock(&interfaceLock);
            return 0; // success
        }
    }
    pthread_mutex_unlock(&interfaceLock);
    return -1; // error: requested interface ID not found
}

