// A function to read and process the CSV file, handling potential memory allocation failures and partial reads/errors
int read_csv_file(const char *filename) {
    // Open the CSV file for reading
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error: Failed to open %s\n", filename);
        return -1;
    }

    // Create a buffer for storing the contents of the CSV file
    char *buffer = malloc(BUFSIZ);
    if (buffer == NULL) {
        printf("Error: Memory allocation failure\n");
        fclose(fp);
        return -1;
    }

    // Create a linked list to store the filtered and validated TxPathInfo structures
    LTEPHY_TxPathInfo *list = NULL;

    // Read the contents of the CSV file line by line, filtering and validating each line as it is read
    while (fgets(buffer, BUFSIZ, fp) != NULL) {
        // Parse the current line into a temporary TxPathInfo structure
        LTEPHY_TxPathInfo temp;
        sscanf(buffer, "%u,%u,%d", &temp.phy_tx_stream_id, &temp.tx_antenna_index, &temp.phy_tx_power_dbm);

        // Ignore any duplicate or corrupted power level values
        if (temp.phy_tx_power_dbm < 0 || temp.phy_tx_power_dbm > 63) {
            printf("Warning: Ignoring invalid power level value %d for TxPathInfo with PHY_TX_STREAM_ID %u and TX_ANTENNA_INDEX %u\n", temp.phy_tx_power_dbm, temp.phy_tx_stream_id, temp.tx_antenna_index);
            continue;
        }

        // Add the validated TxPathInfo structure to the linked list
        LTEPHY_TxPathInfo *new_node = malloc(sizeof(LTEPHY_TxPathInfo));
        if (new_node == NULL) {
            printf("Error: Memory allocation failure\n");
            fclose(fp);
            free(buffer);
            return -1;
        }
        memcpy(new_node, &temp, sizeof(LTEPHY_TxPathInfo));
        new_node->next = list;
        list = new_node;
    }

    // Close the CSV file and release the buffer
    fclose(fp);
    free(buffer);

    return 0;
}

// A function to iterate over the filtered and validated TxPathInfo structures in the linked list
void iterate_txpathinfo(LTEPHY_TxPathInfo *list) {
    LTEPHY_TxPathInfo *current = list;
    while (current != NULL) {
        printf("PHY_TX_STREAM_ID: %u\n", current->phy_tx_stream_id);
        printf("TX_ANTENNA_INDEX: %u\n", current->tx_antenna_index);
        printf("PHY_TX_POWER_DBM: %d\n", current->phy_tx_power_dbm);
        current = current->next;
    }
}

// A function to release the resources allocated by the read_csv_file() function
void free_txpathinfo(LTEPHY_TxPathInfo *list) {
    LTEPHY_TxPathInfo *current = list;
    while (current != NULL) {
        LTEPHY_TxPathInfo *next = current->next;
        free(current);
        current = next;
    }
}
