// Define the record structure
typedef struct {
    int value;
    char* string;
} Record;

void manage_resources(size_t size) {
    // Allocate memory for the arrays in a single block to minimize fragmentation and optimize cache performance
    void* array_mem = malloc(sizeof(long) * size + sizeof(int) * size + sizeof(Record) * size);
    long* offset_array = (long*)array_mem;
    int* key_array = (int*)(offset_array + size);
    Record* record_array = (Record*)(key_array + size);

    // Initialize the arrays with random values
    for (size_t i = 0; i < size; i++) {
        offset_array[i] = (long)rand() % 1000;
        key_array[i] = (int)offset_array[i];
        record_array[i].value = (int)offset_array[i];
        // Allocate memory for the string field in each record
        size_t str_len = rand() % 10 + 5; // Random length between 5 and 15 characters
        char* str = malloc(str_len);
        sprintf(str, "%d", (int)offset_array[i]);
        record_array[i].string = str;
    }

    // Free the memory in reverse order of allocation to avoid memory leaks and minimize impact on other system processes
    for (size_t i = size - 1; i >= 0; i--) {
        free(record_array[i].string);
        record_array[i].string = NULL;
    }
    free(array_mem);
