// Function to serialize each MAC_CONTEXT instance to a file
void serialize_mac_context(const char* filename, const MAC_CONTEXT* mac_context) {
    FILE* fp = fopen(filename, "wb");
    if (!fp) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }
    size_t bytes_written = fwrite(&mac_context->mac_instance_id, sizeof(uint16_t), 1, fp);
    if (bytes_written != 1) {
        fprintf(stderr, "Failed to write MAC instance ID\n");
        fclose(fp);
        return;
    }
    bytes_written = fwrite(&mac_context->flags, sizeof(uint8_t), 1, fp);
    if (bytes_written != 1) {
        fprintf(stderr, "Failed to write MAC flags\n");
        fclose(fp);
        return;
    }
    bytes_written = fwrite(mac_context->buffer, mac_context->capacity, 1, fp);
    if (bytes_written != 1) {
        fprintf(stderr, "Failed to write MAC trace buffer\n");
        fclose(fp);
        return;
    }
    fclose(fp);
}

// Function to deserialize each MAC_CONTEXT instance from a file
