    FILE* fp = fopen(filename, "rb");
    if (!fp) {
        fprintf(stderr, "Failed to open file for reading\n");
        return;
    }
    size_t bytes_read = fread(&mac_context->mac_instance_id, sizeof(uint16_t), 1, fp);
    if (bytes_read != 1) {
        fprintf(stderr, "Failed to read MAC instance ID\n");
