    if (bytes_read != 1) {
        fprintf(stderr, "Failed to read MAC flags\n");
        fclose(fp);
        return;
    }
    bytes_read = fread(mac_context->buffer, mac_context->capacity, 1, fp);
    if (bytes_read != 1) {
        fprintf(stderr, "Failed to read MAC trace buffer\n");
        fclose(fp);
        return;
    }
    fclose(fp);
}

// Function to deallocate memory for a dynamic array of MAC_CONTEXT structures
void free_mac_contexts(MAC_CONTEXT** mac_contexts, uint16_t num_instances) {
    for (int i = 0; i < num_instances; ++i) {
        if ((*mac_contexts)[i].buffer) {
