pthread_mutex_t txPathInfoMutex = PTHREAD_MUTEX_INITIALIZER;

// Initialize the dynamic array with a default capacity of 64 elements
void initTxPathInfoArray(size_t size) {
    // Allocate memory for the dynamic array
    txPathInfoSize = size;
    txPathInfoArray = (LTEPHY_TxPathInfo*)malloc(txPathInfoSize * sizeof(LTEPHY_TxPathInfo));
}

// Resize the dynamic array to a new capacity
void resizeTxPathInfoArray(size_t size) {
    // Lock the mutex before modifying the array
    pthread_mutex_lock(&txPathInfoMutex);

    // Reallocate memory for the dynamic array with the new size
    txPathInfoSize = size;
    txPathInfoArray = (LTEPHY_TxPathInfo*)realloc(txPathInfoArray, txPathInfoSize * sizeof(LTEPHY_TxPathInfo));

