    pthread_mutex_lock(&txPathInfoMutex);

    // Check if the dynamic array needs to be resized
    if (txPathInfoSize == 0 || txPathInfoSize >= MAX_CAPACITY) {
        resizeTxPathInfoArray(MAX_CAPACITY);
    }

    // Add the new LTE PHY Tx Path Info to the end of the dynamic array
    txPathInfoArray[txPathInfoSize] = info;
    ++txPathInfoSize;

    // Unlock the mutex after modifying the array
    pthread_mutex_unlock(&txPathInfoMutex);
}

// Read LTE PHY Tx Path Info from a CSV file and add it to the dynamic array
void readTxPathInfoFromCSV(const char* csvFile) {
    // Open the CSV file for reading
    FILE* fp = fopen(csvFile, "r");

    // Check if the file was opened successfully
    if (fp == NULL) {
        printf("Error: Unable to open CSV file %s\n", csvFile);
        return;
    }

    // Define a buffer for reading lines from the file
    char line[1024];

    // Initialize the dynamic array with a default capacity of 64 elements
    initTxPathInfoArray(64);

    // Read each line from the CSV file and add it to the dynamic array
    while (fgets(line, sizeof(line), fp) != NULL) {
        char* token;
        int PHY_TX_STREAM_ID = -1;
        int TX_ANTENNA_INDEX = -1;
        int PHY_TX_POWER_DBM = -100;

        // Tokenize the line and extract the LTE PHY Tx Path Info
        token = strtok(line, ",");
        while (token != NULL) {
            if (strcmp(token, "PHY_TX_STREAM_ID") == 0) {
                PHY_TX_STREAM_ID = atoi(strtok(NULL, ","));
            } else if (strcmp(token, "TX_ANTENNA_INDEX") == 0) {
                TX_ANTENNA_INDEX = atoi(strtok(NULL, ","));
            } else if (strcmp(token, "PHY_TX_POWER_DBM") == 0) {
                PHY_TX_POWER_DBM = atoi(strtok(NULL, ","));
            }
            token = strtok(NULL, ",");
        }

        // Add the LTE PHY Tx Path Info to the dynamic array if it is valid
        if (PHY_TX_STREAM_ID != -1 && TX_ANTENNA_INDEX != -1 && PHY_TX_POWER_DBM != -100) {
            addTxPathInfo({PHY_TX_STREAM_ID, TX_ANTENNA_INDEX, PHY_TX_POWER_DBM});
        }
    }

    // Close the CSV file
    fclose(fp);
