// Filter and validate LTE PHY Tx Path Info in the dynamic array
void filterAndValidateTxPathInfo() {
    // Lock the mutex before modifying the array
    pthread_mutex_lock(&txPathInfoMutex);

    // Iterate through the LTE PHY Tx Path Info and filter out duplicates and corrupted power levels
    for (size_t i = 0; i < txPathInfoSize; ++i) {
        bool isDuplicate = false;
        int duplicateIndex = -1;

        // Check if the current LTE PHY Tx Path Info is a duplicate of another entry in the array
        for (size_t j = 0; j < i; ++j) {
            if (txPathInfoArray[i].PHY_TX_STREAM_ID == txPathInfoArray[j].PHY_TX_STREAM_ID &&
                txPathInfoArray[i].TX_ANTENNA_INDEX == txPathInfoArray[j].TX_ANTENNA_INDEX) {
                isDuplicate = true;
                duplicateIndex = j;
                break;
            }
        }

        // If the current LTE PHY Tx Path Info is a duplicate, remove it from the array
        if (isDuplicate) {
            txPathInfoArray[duplicateIndex] = txPathInfoArray[--txPathInfoSize];
        }
    }

    // Unlock the mutex after modifying the array
    pthread_mutex_unlock(&txPathInfoMutex);
}

// Write LTE PHY Tx Path Info to a CSV file
void writeTxPathInfoToCSV(const char* csvFile) {
    // Open the CSV file for writing
    FILE* fp = fopen(csvFile, "w");

    // Check if the file was opened successfully
    if (fp == NULL) {
        printf("Error: Unable to open CSV file %s\n", csvFile);
        return;
    }

    // Define a buffer for writing lines to the file
    char line[1024];

    // Iterate through the LTE PHY Tx Path Info and write it to the CSV file
    for (size_t i = 0; i < txPathInfoSize; ++i) {
        snprintf(line, sizeof(line), "%d,%d,%d\n", txPathInfoArray[i].PHY_TX_STREAM_ID,
                 txPathInfoArray[i].TX_ANTENNA_INDEX, txPathInfoArray[i].PHY_TX_POWER_DBM);
        fputs(line, fp);
    }

    // Close the CSV file
    fclose(fp);
}

int main() {
    readTxPathInfoFromCSV("tx_path_info.csv");
    filterAndValidateTxPathInfo();
    writeTxPathInfoToCSV("filtered_tx_path_info.csv");
    return 0;
}
