// Session data structure
typedef struct {
    int session_id;
    int user_id;
    char *events;
    int status;
    struct {
        unsigned long last_activity_timestamp;
        int rx_ue_information_tag;
        int rnti;
        int crc_indication_rel8_tag;
        int crcflag;
    } metadata;
} session_t;

// Session management functions

// Initialize a new session with default values
session_t *initialize_session(int session_id, int user_id) {
    session_t *new_session = (session_t *)malloc(sizeof(session_t));
    new_session->session_id = session_id;
    new_session->user_id = user_id;
    new_session->events = NULL;
    new_session->status = 0;
    new_session->metadata.last_activity_timestamp = 0;
    new_session->metadata.rx_ue_information_tag = -1;
    new_session->metadata.rnti = -1;
    new_session->metadata.crc_indication_rel8_tag = -1;
    new_session->metadata.crcflag = 0;
    return new_session;
}

// Add a new event to the session events list
void add_event(session_t *session, char *event) {
    // Check if the session has already been initialized
    if (session == NULL || session->events == NULL) {
        return;
    }

    // Allocate memory for the new event
    char *new_event = (char *)malloc(sizeof(char) * strlen(event));
    strcpy(new_event, event);

    // Append the new event to the session events list
    session->events = (char **)realloc(session->events, sizeof(char *) * (session->status + 1));
    session->events[session->status] = new_event;
    session->status++;
}

// Set the last activity timestamp of a session
void set_last_activity_timestamp(session_t *session, unsigned long timestamp) {
    // Check if the session has already been initialized
    if (session == NULL || session->events == NULL) {
        return;
    }

    // Set the last activity timestamp of the session
    session->metadata.last_activity_timestamp = timestamp;
}

// Set the RX UE information tag of a session
void set_rx_ue_information_tag(session_t *session, int rx_ue_information_tag) {
    // Check if the session has already been initialized
    if (session == NULL || session->events == NULL) {
        return;
    }

    // Set the RX UE information tag of the session
    session->metadata.rx_ue_information_tag = rx_ue_information_tag;
}

// Set the RNTI of a session
void set_rnti(session_t *session, int rnti) {
    // Check if the session has already been initialized
    if (session == NULL || session->events == NULL) {
        return;
    }

    // Set the RNTI of the session
    session->metadata.rnti = rnti;
}

// Set the CRC flag of a session
void set_crcflag(session_t *session, int crcflag) {
    // Check if the session has already been initialized
    if (session == NULL || session->events == NULL) {
        return;
    }

    // Set the CRC flag of the session
    session->metadata.crcflag = crcflag;
}

// Serialize a session to a binary format for persistence
void serialize_session(session_t *session, char **serialized_data) {
    // Check if the session has already been initialized
    if (session == NULL || session->events == NULL) {
        return;
    }

    // Calculate the size of the serialized data
    int size = sizeof(int) + sizeof(int) + sizeof(char *) + sizeof(int) + sizeof(int) + sizeof(int);
    for (int i = 0; i < session->status; i++) {
        size += strlen(session->events[i]) + 1; // Add the size of each event string
    }

    // Allocate memory for the serialized data
    *serialized_data = (char *)malloc(size);

    // Serialize the session data into the binary format
    char *ptr = *serialized_data;
    memcpy(ptr, &session->session_id, sizeof(int));
    ptr += sizeof(int);
    memcpy(ptr, &session->user_id, sizeof(int));
    ptr += sizeof(int);
    memcpy(ptr, &session->events, sizeof(char *));
    ptr += sizeof(char *);
    memcpy(ptr, &session->status, sizeof(int));
    ptr += sizeof(int);
    for (int i = 0; i < session->status; i++) {
        strcpy(ptr, session->events[i]);
        ptr += strlen(session->events[i]) + 1;
    }
}

// Deserialize a session from a binary format for persistence
void deserialize_session(char *serialized_data, int size, session_t **session) {
    // Allocate memory for the new session
    *session = (session_t *)malloc(sizeof(session_t));

    // Deserialize the session data from the binary format
    char *ptr = serialized_data;
