    session_t *session2 = NULL;
    add_session(manager, session1);
    add_session(manager, session2);

    // Serialize all sessions in the list to a binary format for persistence
    char *serialized_data = NULL;
    serialize_sessions(manager, &serialized_data);

    // Deserialize all sessions from a binary format for persistence
    session_manager_t *new_manager = NULL;
    deserialize_sessions(serialized_data, strlen(serialized_data), &new_manager);

    return 0;
}']

