    pthread_mutex_t* mutex = malloc(sizeof(pthread_mutex_t));
    pthread_mutex_init(mutex, NULL);

    NetworkInterfaceConfig* configs = malloc(numInterfaces * sizeof(NetworkInterfaceConfig));
    for (int i = 0; i < numInterfaces; i++) {
        configs[i].interfaceId = i;
        configs[i].neighborCells = malloc(numNeighbors * sizeof(NeighborCellInfo));
        for (int j = 0; j < numNeighbors; j++) {
            configs[i].neighborCells[j].cellId = i + 1;
            configs[i].neighborCells[j].rssi = 0.0f;
            configs[i].neighborCells[j].rsrp = 0.0f;
            configs[i].neighborCells[j].rsrq = 0.0f;
        }

        // Initialize the SRS parameters
        configs[i].srsParams.srsSetUpPeriodicity = numSRS;
        configs[i].srsParams.srsOccupancy = 0;
        configs[i].srsParams.srsBandwidth = 12;
        configs[i].srsParams.srsAntennaPorts = 3;
    }

    // Ensure thread safety when accessing shared resources
    pthread_mutex_lock(mutex);

    // Populate the neighbor cell list with a specified number of entries, ensuring no duplicate neighbor IDs
    for (int i = 0; i < numInterfaces; i++) {
        for (int j = 0; j < numNeighbors; j++) {
            int neighborId = rand() % (numInterfaces - 1) + 1;
            while (configs[neighborId].neighborCells[j].cellId == configs[i].interfaceId) {
                neighborId = rand() % (numInterfaces - 1) + 1;
            }
            configs[i].neighborCells[j].cellId = neighborId;
        }
    }

    // Correctly configure the SRS parameters based on a predefined template
    for (int i = 0; i < numInterfaces; i++) {
        int srsPeriodicity = rand() % (numSRS - 1) + 1;
        while (srsPeriodicity == configs[i].srsParams.srsSetUpPeriodicity) {
            srsPeriodicity = rand() % (numSRS - 1) + 1;
        }
        configs[i].srsParams.srsSetUpPeriodicity = srsPeriodicity;
