    time_t timestamp;
    float temperature;
    int isAboveThreshold;
};

// hash map to track frequency of temperature readings above the threshold within each hour
struct HashMap {
    struct HashEntry *table;
    size_t capacity;
    size_t size;
};

struct HashEntry {
    float key;
    int value;
};

void processSensorDataAndAnalyzeTrends(char* directoryPath) {
    // dynamically load data from specified directory
    DIR *dir = opendir(directoryPath);
    if (dir == NULL) {
        perror("Error opening directory");
        exit(EXIT_FAILURE);
    }

    struct dirent *file;
    char filePath[1024];

    // array to store temperature readings for each hour
    float* temperatureReadings = (float*)calloc(8760, sizeof(float));
    if (temperatureReadings == NULL) {
        perror("Error allocating memory");
        exit(EXIT_FAILURE);
    }

    // array to store temperature readings for each hour that are above the threshold
    struct TemperatureReading* temperatureReadingsAboveThreshold = (struct TemperatureReading*)calloc(8760, sizeof(struct TemperatureReading));
    if (temperatureReadingsAboveThreshold == NULL) {
        perror("Error allocating memory");
        exit(EXIT_FAILURE);
    }

    // hash map to track frequency of temperature readings above the threshold within each hour
    struct HashMap *hashMap = (struct HashMap*)calloc(8760, sizeof(struct HashMap));
    if (hashMap == NULL) {
        perror("Error allocating memory");
        exit(EXIT_FAILURE);
    }

    // populate hash map with initial values
    for (int i = 0; i < 8760; i++) {
        struct HashEntry *hashEntry = (struct HashEntry*)calloc(1, sizeof(struct HashEntry));
        if (hashEntry == NULL) {
            perror("Error allocating memory");
            exit(EXIT_FAILURE);
        }
        hashEntry->key = i;
        hashEntry->value = 0;
        hashMap[i].table = hashEntry;
        hashMap[i].capacity = 1;
        hashMap[i].size = 1;
    }

    // iterate over files in the directory
    while ((file = readdir(dir)) != NULL) {
        if (strcmp(file->d_name, ".") == 0 || strcmp(file->d_name, "..") == 0) continue;

        // open file and parse JSON data
        char *filePath = malloc(1024);
        snprintf(filePath, 1024, "%s/%s", directoryPath, file->d_name);
        FILE *fp = fopen(filePath, "r");
        if (fp == NULL) {
            perror("Error opening file");
            exit(EXIT_FAILURE);
        }

        char buffer[1024];
        while (fgets(buffer, 1024, fp) != NULL) {
            // parse JSON data and extract timestamp and temperature readings
            json_object *json = json_tokener_parse(buffer);
            if (json == NULL) {
                perror("Error parsing JSON");
                exit(EXIT_FAILURE);
            }

            time_t timestamp;
            float temperature;
            int isAboveThreshold;

            // extract timestamp and temperature readings from JSON object
            json_object *timestampObj = json_object_object_get(json, "timestamp");
            if (timestampObj == NULL) {
                perror("Error extracting timestamp from JSON");
                exit(EXIT_FAILURE);
            }
            sscanf(json_object_get_string(timestampObj), "%lu", &timestamp);

            json_object *temperatureObj = json_object_object_get(json, "temperature");
            if (temperatureObj == NULL) {
                perror("Error extracting temperature from JSON");
                exit(EXIT_FAILURE);
            }
            sscanf(json_object_get_string(temperatureObj), "%f", &temperature);

            // store temperature reading in arrays
            int hour = (int)timestamp / 3600;
            temperatureReadings[hour] += temperature;
            if (temperature > THRESHOLD) {
                isAboveThreshold = 1;
            } else {
                isAboveThreshold = 0;
            }
            struct TemperatureReading *reading = &temperatureReadingsAboveThreshold[hour];
            reading->timestamp = timestamp;
            reading->temperature = temperature;
            reading->isAboveThreshold = isAboveThreshold;

            // increment hash map counter for temperature readings above the threshold in this hour
            if (hashMap[hour].size == 0) {
                struct HashEntry *hashEntry = (struct HashEntry*)calloc(1, sizeof(struct HashEntry));
                if (hashEntry == NULL) {
                    perror("Error allocating memory");
                    exit(EXIT_FAILURE);
                }
                hashEntry->key = hour;
                hashEntry->value = 0;
                hashMap[hour].table = hashEntry;
                hashMap[hour].capacity = 1;
                hashMap[hour].size = 1;
            }
            hashMap[hour].table->value++;
        }
    }

    // compute averages and populate structures
    float averageTemperature = 0;
    for (int i = 0; i < 8760; i++) {
        if (temperatureReadings[i] > 0) {
            averageTemperature += temperatureReadings[i];
        }
    }
    averageTemperature /= 8760;

    struct TemperatureReading *maxTemp = &temperatureReadingsAboveThreshold[0];
    for (int i = 1; i < 8760; i++) {
        if (temperatureReadingsAboveThreshold[i].temperature > maxTemp->temperature) {
            maxTemp = &temperatureReadingsAboveThreshold[i];
        }
    }

    struct TemperatureReading *minTemp = &temperatureReadingsAboveThreshold[0];
    for (int i = 1; i < 8760; i++) {
        if (temperatureReadingsAboveThreshold[i].temperature < minTemp->temperature) {
            minTemp = &temperatureReadingsAboveThreshold[i];
        }
    }

    // print results
    printf("Maximum temperature in this period was %.2f degrees Celsius at %lu:%lu\n", maxTemp->temperature, maxTemp->timestamp / 3600, (maxTemp->timestamp / 60) % 60);
    printf("Minimum temperature in this period was %.2f degrees Celsius at %lu:%lu\n", minTemp->temperature, minTemp->timestamp / 3600, (minTemp->timestamp / 60) % 60);
    printf("Average temperature in this period was %.2f degrees Celsius.\n", averageTemperature);
    printf("There were a total of %d temperature readings above the threshold.\n", hashMap[8759].table->value);
}

