struct ApplicationServiceConfig {
    int serviceId;
    int priority;
    List<Endpoint> endpoints;
};

// Define a thread-safe tree data structure for managing the set of ApplicationServiceConfig objects
class ThreadSafeTree {
public:
    // Insert an ApplicationServiceConfig object into the tree while preventing duplicate serviceId entries and prioritizing based on priority level.
    void insert(ApplicationServiceConfig config) {
        if (!contains(config)) {
            tree.insert(config);
        } else {
            // Update the existing entry with the new priority level if it exists.
            tree.update(config, [](auto &entry) {
                entry->priority = config->priority;
                return true;
            });
        }
    }

    // Get an ApplicationServiceConfig object from the tree by serviceId.
    ApplicationServiceConfig getByServiceId(int serviceId) {
        auto it = tree.find(serviceId);
        if (it != tree.end()) {
            return *it;
        } else {
            return nullptr;
        }
    }

    // Check if a given ApplicationServiceConfig object is already present in the tree by serviceId.
    bool contains(ApplicationServiceConfig config) {
        return tree.contains(config->serviceId);
    }

private:
    // A thread-safe implementation of a binary search tree to store the set of ApplicationServiceConfig objects.
    Tree<ApplicationServiceConfig> tree;
};
```
