    // check if input is valid
    if (sessions == NULL || num_sessions <= 0) {
        return false;
    }

    // allocate memory for each session and populate with default values
    for (int i = 0; i < num_sessions; i++) {
        sessions[i].session_id = i + 1;
        strcpy(sessions[i].ue_identifier, "UE-");
        for (int j = 0; j < MAX_EVENTS; j++) {
            sessions[i].events[j] = malloc(sizeof(Event));
            if (sessions[i].events[j] == NULL) {
                printf("Memory allocation error!\n");
                return false;
            }
        }
    }

    // initialize each session's event list and populate with default values
    for (int i = 0; i < num_sessions; i++) {
        for (int j = 0; j < MAX_EVENTS; j++) {
            sessions[i].events[j]->timestamp = time(NULL);
            sessions[i].events[j]->event_id = j + 1;
        }
    }

    return true;
}

// function to de-initialize and free memory for an array of sessions
void destroy_sessions(Session *sessions, int num_sessions) {
    // check if input is valid
    if (sessions == NULL || num_sessions <= 0) {
        return;
    }

    // free each session's event list and memory for the session structure
    for (int i = 0; i < num_sessions; i++) {
        for (int j = 0; j < MAX_EVENTS; j++) {
            free(sessions[i].events[j]);
        }
        free(sessions[i].session_id);
    }
}

// function to handle concurrent access from multiple threads
bool init_session_concurrent(Session *sessions, int num_sessions) {
    // check if input is valid
    if (sessions == NULL || num_sessions <= 0) {
        return false;
    }

    // use a semaphore to limit the maximum number of concurrent sessions being initialized at once
    sem_t *sem = sem_open("session_init", O_CREAT, S_IRUSR | S_IWUSR);
    if (sem == SEM_FAILED) {
        printf("Semaphore creation error!\n");
        return false;
    }

    // initialize each session and populate with default values in a separate thread
    for (int i = 0; i < num_sessions; i++) {
        pthread_t thread;
        if (pthread_create(&thread, NULL, init_session_thread, &sessions[i]) != 0) {
            printf("Thread creation error!\n");
            return false;
        }
    }

    // wait for all threads to finish and destroy the semaphore
    for (int i = 0; i < num_sessions; i++) {
        pthread_join(thread, NULL);
    }
    sem_close(sem);
    sem_unlink("session_init");

    return true;
}

// function to handle memory allocation and deallocation for each session in a separate thread
bool init_session_thread(Session *session) {
    // allocate memory for the session structure
    session->session_id = malloc(sizeof(uint32_t));
    if (session->session_id == NULL) {
        printf("Memory allocation error!\n");
        return false;
    }

    // allocate memory for each event in the session and populate with default values
    for (int i = 0; i < MAX_EVENTS; i++) {
        session->events[i] = malloc(sizeof(Event));
        if (session->events[i] == NULL) {
            printf("Memory allocation error!\n");
            return false;
        }
    }

    // populate each event with default values and add it to the session's event list
