void initList(struct List *list) {
  list->size = 0;
  list->capacity = 1024;
  list->head = NULL;
}

void addToList(struct List *list, NFAPI_CRC_INDICATION_PDU_T *data) {
  struct Node *node = malloc(sizeof(struct Node));
  node->data = data;
  node->next = list->head;
  list->head = node;
  list->size++;
}

void removeFromList(struct List *list, NFAPI_CRC_INDICATION_PDU_T *data) {
  struct Node *node = list->head;
  while (node != NULL && node->next != data) {
    node = node->next;
  }
  if (node == NULL) return;
  node->next = node->next->next;
  list->size--;
}

NFAPI_CRC_INDICATION_PDU_T *getFromList(struct List *list, int index) {
  struct Node *node = list->head;
  for (int i = 0; i < index && node != NULL; i++) {
    node = node->next;
  }
  return node ? node->data : NULL;
}

void freeList(struct List *list) {
  struct Node *node = list->head;
  while (node != NULL) {
    struct Node *next = node->next;
    free(node);
    node = next;
  }
  list->size = 0;
  list->capacity = 0;
}

