    NFAPI_CRC_INDICATION_PDU_T *newArray = (NFAPI_CRC_INDICATION_PDU_T *)malloc(BATCH_MAX_PDU_COUNT * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    CHECK_NULL(newArray)

    // Initialize the new PDUs and add them to the array
    for (int i = 0; i < BATCH_MAX_PDU_COUNT; i++) {
        newArray[i].rxUeInformationTag = rand() % 10;
        newArray[i].rnti = rand();
        newArray[i].crcIndicationRel8Tag.crcFlag = rand() % 2;
    }

    // Add the new batch to the array
    for (int i = 0; i < BATCH_MAX_PDU_COUNT; i++) {
        array[*count + i] = newArray[i];
    }

    *count += BATCH_MAX_PDU_COUNT;

    // Free the memory allocated for the new batch
    free(newArray);

    return 0;
}

// Function to remove a PDU from the array based on RNTI or index
int removePdu(NFAPI_CRC_INDICATION_PDU_T **array, int *count, int rntiOrIndex) {
    // Check if the input is valid
    if (rntiOrIndex < 0 || rntiOrIndex >= *count) {
        return 1;
    }

    // Find the index of the PDU to be removed
    int index = -1;
    for (int i = 0; i < *count; i++) {
        if (rntiOrIndex == array[i]->rnti) {
            index = i;
            break;
        }
    }

    // Check if the PDU was found
    if (index == -1) {
        return 1;
    }

    // Remove the PDU from the array
    for (int i = index; i < *count - 1; i++) {
        array[i] = array[i + 1];
    }

    (*count)--;

    return 0;
}

// Function to verify the integrity of the CRC flags
int verifyCrcFlags(NFAPI_CRC_INDICATION_PDU_T **array, int count) {
    // Check if there are any PDUs in the array
    if (count == 0) {
        return 1;
