    long offset;
    int value;
} record;

// Function to initialize and manage records
void manage_records(int num_records, int sum_threshold, int max_value) {
    // Allocate memory for the arrays
    long *offset_array = (long *) malloc(num_records * sizeof(long));
    int *key_array = (int *) malloc(num_records * sizeof(int));
    record *record_array = (record *) malloc(num_records * sizeof(record));

    // Populate the arrays with unique random values
    srand((unsigned) time(NULL));
    for (int i = 0; i < num_records; ++i) {
        offset_array[i] = rand() % max_value;
        key_array[i] = rand() % max_value;
        record_array[i].key = key_array[i];
        record_array[i].offset = offset_array[i];
        record_array[i].value = rand() % max_value;
    }

    // Enforce the sum threshold
    int total_sum = 0;
    for (int i = 0; i < num_records; ++i) {
        total_sum += record_array[i].value;
        if (total_sum > sum_threshold) {
            // Adjust the value to comply with the threshold without exceeding it
            int diff = total_sum - sum_threshold;
            record_array[i].value -= diff;
            total_sum -= diff;
        }
    }

    // Handle memory allocation failures
    if (offset_array == NULL || key_array == NULL || record_array == NULL) {
        printf("Error: Memory allocation failed\n");
        return;
    }

    // Free the allocated resources on error or when resetting the function
    void free_resources() {
        free(offset_array);
        free(key_array);
        free(record_array);
    }

    // Thread-safe access and modifications to the arrays
    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);
    pthread_mutex_lock(&mutex);

    // Clear the allocated resources and reset the function state
    void reset() {
        free_resources();
        offset_array = (long *) malloc(num_records * sizeof(long));
        key_array = (int *) malloc(num_records * sizeof(int));
        record_array = (record *) malloc(num_records * sizeof(record));
        pthread_mutex_unlock(&mutex);
    }

    // Logging and monitoring features
    void log_metrics() {
        printf("Number of records: %d\n", num_records);
        printf("Sum threshold: %d\n", sum_threshold);
        printf("Maximum value: %d\n", max_value);
        printf("Total sum: %d\n", total_sum);
    }

    // Document the function and its assumptions
    printf("manage_records: Initializes and manages a dynamic record storage system subject to operational constraints and performance requirements.\n");
    printf("Assumptions:\n");
    printf("\t- The input parameters num_records, sum_threshold, and max_value are valid.\n");
    printf("\t- The function is called in a thread-safe manner.\n");
    printf("\t- The function does not modify the input arguments.\n");
}
