// Structure definitions
struct NeighborCellInfo {
    int neighborId;
    char* ssid;
    unsigned short channel;
};

struct NetworkInterfaceConfig {
    int interfaceId;
    struct NeighborCellInfo** neighborCells;
    int numNeighbors;
    int maxNeighbors;
    char* srsTemplateName;
    struct SRSParameters srsParams;
};

struct SRSParameters {
    int referenceSignalPower;
    int usedRepetitionFactor;
    int usedPrecodedGI;
    int usedSoundingInterval;
};

// Global variables
static const char* kDefaultSRSTemplateName = "default";
static const int kDefaultMaxNeighbors = 10;
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
void logError(const char* message);
bool isDuplicateNeighbor(struct NetworkInterfaceConfig* config, int neighborId);
bool loadSRSParameters(struct NetworkInterfaceConfig* config);

/**
 * Initializes a dynamic array of `NetworkInterfaceConfig` structures.
 * Each structure should contain a unique `interfaceId`, a list of `NeighborCellInfo` structures, and a configuration for `Sounding Reference Signal` (SRS) parameters.
 * The function should dynamically allocate memory for the neighbor cell list, ensuring no duplicate `neighborId` entries, and correctly configure the SRS parameters based on user-specified templates.
 *
 * @param configs An array of `NetworkInterfaceConfig` structures to initialize.
 * @param numConfigs The number of configurations in the `configs` array.
 * @return 0 if successful, a negative value otherwise.
 */
int initNetworkInterfaces(struct NetworkInterfaceConfig** configs, int numConfigs) {
    assert(configs != NULL);
    assert(numConfigs > 0);

    // Iterate over the configurations and initialize each one
    for (int i = 0; i < numConfigs; ++i) {
        struct NetworkInterfaceConfig* config = configs[i];

        // Initialize the neighbor cell list
        if (!initNeighborCells(config)) {
            logError("Failed to initialize neighbor cells for interface %d", config->interfaceId);
            return -1;
        }

        // Load SRS parameters from template or default values
        if (!loadSRSParameters(config)) {
            logError("Failed to load SRS parameters for interface %d", config->interfaceId);
            return -2;
        }
    }

    return 0;
}

/**
 * Initializes the neighbor cell list for a `NetworkInterfaceConfig` structure.
 * The function should dynamically allocate memory for the neighbor cell list, ensuring no duplicate `neighborId` entries, and correctly configure the SRS parameters based on user-specified templates.
 *
 * @param config A `NetworkInterfaceConfig` structure to initialize.
 * @return True if successful, false otherwise.
 */
bool initNeighborCells(struct NetworkInterfaceConfig* config) {
    assert(config != NULL);

    // Lock the mutex before accessing the neighbor cell list
    pthread_mutex_lock(&lock);

    // Dynamically allocate memory for the neighbor cell list
    config->neighborCells = (struct NeighborCellInfo**) malloc(sizeof(struct NeighborCellInfo*) * config->maxNeighbors);
    if (config->neighborCells == NULL) {
        logError("Failed to allocate memory for neighbor cell list for interface %d", config->interfaceId);
        pthread_mutex_unlock(&lock);
        return false;
    }

    // Initialize the number of neighbors to 0
    config->numNeighbors = 0;

    // Iterate over the neighbor cell list and add each entry to the configuration
    for (int i = 0; i < config->maxNeighbors; ++i) {
        struct NeighborCellInfo* neighbor = (struct NeighborCellInfo*) malloc(sizeof(struct NeighborCellInfo));
        if (neighbor == NULL) {
            logError("Failed to allocate memory for neighbor cell %d for interface %d", i, config->interfaceId);
            pthread_mutex_unlock(&lock);
            return false;
        }

        // Set the default values for the neighbor cell
        neighbor->neighborId = -1;
        neighbor->ssid = NULL;
        neighbor->channel = 0;

        config->neighborCells[i] = neighbor;
    }

    pthread_mutex_unlock(&lock);

    return true;
}

/**
 * Loads SRS parameters from a template or default values for a `NetworkInterfaceConfig` structure.
 * The function should correctly configure the SRS parameters based on user-specified templates.
 *
 * @param config A `NetworkInterfaceConfig` structure to initialize.
 * @return True if successful, false otherwise.
 */
bool loadSRSParameters(struct NetworkInterfaceConfig* config) {
    assert(config != NULL);

    // Lock the mutex before accessing the SRS parameters
    pthread_mutex_lock(&lock);

    // Load SRS parameters from template or default values
    config->srsTemplateName = kDefaultSRSTemplateName;
    config->srsParams.referenceSignalPower = 50;
    config->srsParams.usedRepetitionFactor = 16;
    config->srsParams.usedBandwidth = 0;

    pthread_mutex_unlock(&lock);

    return true;
}

/**
