 * The function should correctly free all memory allocated for the neighbor cell list and SRS parameters.
 *
 * @param config A `NetworkInterfaceConfig` structure to clean up.
 */
void freeNetworkInterfaces(struct NetworkInterfaceConfig* config) {
    assert(config != NULL);

    // Lock the mutex before accessing the neighbor cell list
    pthread_mutex_lock(&lock);

    // Free the memory allocated for the neighbor cell list
    if (config->neighborCells != NULL) {
        free(config->neighborCells);
    }

    // Free the memory allocated for the SRS parameters
    if (config->srsParams.referenceSignalPower != NULL) {
        free(config->srsParams.referenceSignalPower);
    }

    pthread_mutex_unlock(&lock);
}
