// Thread-safe linked list node structure for storing CRC indications
typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_information;
    RNTI rnti;
    CRCFLAG crcflag;
    time_t timestamp;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

// Global linked list head pointer for storing CRC indications
static pthread_mutex_t crc_indication_list_lock = PTHREAD_MUTEX_INITIALIZER;
static NFAPI_CRC_INDICATION_PDU_T *crc_indication_list_head = NULL;

// Function to insert a new node in the linked list
void insert_crc_indication(NFAPI_CRC_INDICATION_PDU_T *new_node) {
    pthread_mutex_lock(&crc_indication_list_lock);
    NFAPI_CRC_INDICATION_PDU_T *current = crc_indication_list_head;
    while (current != NULL && current->timestamp < new_node->timestamp) {
        current = current->next;
    }
    new_node->next = current;
    if (crc_indication_list_head == NULL) {
        crc_indication_list_head = new_node;
    } else {
        crc_indication_list_head->prev = new_node;
    }
    pthread_mutex_unlock(&crc_indication_list_lock);
}

// Function to remove a node from the linked list
void remove_crc_indication(NFAPI_CRC_INDICATION_PDU_T *node) {
    pthread_mutex_lock(&crc_indication_list_lock);
    NFAPI_CRC_INDICATION_PDU_T *current = crc_indication_list_head;
    while (current != NULL && current->next != node) {
        current = current->next;
    }
    if (current == NULL) {
        pthread_mutex_unlock(&crc_indication_list_lock);
        return;
    }
    NFAPI_CRC_INDICATION_PDU_T *previous = current->prev;
    if (previous == NULL) {
        crc_indication_list_head = node->next;
    } else {
        previous->next = node->next;
    }
    if (node->next != NULL) {
        node->next->prev = previous;
    }
    pthread_mutex_unlock(&crc_indication_list_lock);
}

// Function to retrieve the most recent CRC indication from the linked list
NFAPI_CRC_INDICATION_PDU_T *get_latest_crc_indication() {
    pthread_mutex_lock(&crc_indication_list_lock);
    NFAPI_CRC_INDICATION_PDU_T *current = crc_indication_list_head;
    while (current != NULL) {
        if (current->timestamp == current->next->timestamp) {
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&crc_indication_list_lock);
    return current;
}

// Function to retrieve the oldest CRC indication from the linked list
NFAPI_CRC_INDICATION_PDU_T *get_oldest_crc_indication() {
    pthread_mutex_lock(&crc_indication_list_lock);
    NFAPI_CRC_INDICATION_PDU_T *current = crc_indication_list_head;
    while (current != NULL) {
        if (current->timestamp == current->next->timestamp) {
            break;
        }
        current = current->prev;
    }
    pthread_mutex_unlock(&crc_indication_list_lock);
    return current;
}

// Function to retrieve a specific CRC indication from the linked list based on RX UE information and RNTI
NFAPI_CRC_INDICATION_PDU_T *get_crc_indication(RX_UE_INFORMATION_TAG rx_ue_information, RNTI rnti) {
    pthread_mutex_lock(&crc_indication_list_lock);
    NFAPI_CRC_INDICATION_PDU_T *current = crc_indication_list_head;
    while (current != NULL) {
        if (current->rx_ue_information == rx_ue_information && current->rnti == rnti) {
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&crc_indication_list_lock);
    return current;
}

// Function to update the CRC flag of a specific CRC indication in the linked list based on RX UE information and RNTI
void update_crc_flag(RX_UE_INFORMATION_TAG rx_ue_information, RNTI rnti, bool crc_ok) {
    pthread_mutex_lock(&crc_indication_list_lock);
    NFAPI_CRC_INDICATION_PDU_T *current = crc_indication_list_head;
    while (current != NULL) {
        if (current->rx_ue_information == rx_ue_information && current->rnti == rnti) {
            current->crc_ok = crc_ok;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&crc_indication_list_lock);
}
```

This is a simple example of how you can use a linked list to store and retrieve CRC indications. In this case, we are using a `NFAPI_CRC_INDICATION_PDU` struct to represent each node in the linked list. The nodes in the linked list are connected by pointers, allowing for efficient insertion, deletion, and retrieval of nodes.

Note that this implementation assumes that the CRC indications are being received in chronological order based on the `timestamp` field. If the CRC indications are not received in chronological order, you may need to adjust the logic of the `insert_crc_indication()` and `remove_crc_indication()` functions accordingly.

Also note that this implementation does not handle the case where multiple CRC indications have the same `timestamp` field. In such a case, the linked list will become corrupted, and you may need to implement additional logic to ensure the integrity of the linked list.']

