// Data structure for storing unique integers
typedef struct {
    int value;
    pthread_mutex_t mutex; // Mutex for thread-safe insertion and retrieval
} IntegerSet;

// Function to initialize the integer set
void initIntegerSet(IntegerSet* iset) {
    // Initialize the mutex
    pthread_mutex_init(&iset->mutex, NULL);
}

// Function to add an integer to the set
void addInteger(IntegerSet* iset, int value) {
    // Lock the mutex
    pthread_mutex_lock(&iset->mutex);

    // Check if the integer already exists in the set
    for (int i = 0; i < iset->size; i++) {
        if (iset->data[i] == value) {
            pthread_mutex_unlock(&iset->mutex);
            return; // Integer already exists, do nothing
        }
    }

    // If the integer does not exist, add it to the set
    iset->data[iset->size++] = value;

    // Unlock the mutex
    pthread_mutex_unlock(&iset->mutex);
}

// Function to remove an integer from the set
void removeInteger(IntegerSet* iset, int value) {
    // Lock the mutex
    pthread_mutex_lock(&iset->mutex);

    // Find the index of the integer in the set
    int index = -1;
    for (int i = 0; i < iset->size; i++) {
        if (iset->data[i] == value) {
            index = i;
            break;
        }
    }

    // If the integer exists, remove it from the set
    if (index != -1) {
        for (int i = index; i < iset->size - 1; i++) {
            iset->data[i] = iset->data[i + 1];
        }
        iset->size--;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&iset->mutex);
}

// Function to check if an integer exists in the set
int containsInteger(IntegerSet* iset, int value) {
    // Lock the mutex
    pthread_mutex_lock(&iset->mutex);

    // Find the index of the integer in the set
    int index = -1;
    for (int i = 0; i < iset->size; i++) {
        if (iset->data[i] == value) {
            index = i;
            break;
        }
    }

    // Unlock the mutex
    pthread_mutex_unlock(&iset->mutex);

    // Return true if the integer exists in the set, false otherwise
    return index != -1;
}

// Function to get the largest integer in the set
int getLargestInteger(IntegerSet* iset) {
    // Lock the mutex
    pthread_mutex_lock(&iset->mutex);

    // Find the largest integer in the set
    int largest = -1;
    for (int i = 0; i < iset->size; i++) {
        if (largest == -1 || iset->data[i] > largest) {
            largest = iset->data[i];
        }
    }

    // Unlock the mutex
    pthread_mutex_unlock(&iset->mutex);

    // Return the largest integer in the set
    return largest;
}

// Function to export the integer set to a file
void exportIntegerSet(IntegerSet* iset, const char* filename) {
    // Open the output file for writing
    FILE* outfile = fopen(filename, "w");
    if (outfile == NULL) {
        perror("Error opening output file");
        return;
    }

    // Lock the mutex
    pthread_mutex_lock(&iset->mutex);

    // Write the integers to the output file
    for (int i = 0; i < iset->size; i++) {
        fprintf(outfile, "%d\n", iset->data[i]);
    }

    // Unlock the mutex
    pthread_mutex_unlock(&iset->mutex);

    // Close the output file
    fclose(outfile);
}

// Function to clear the integer set for re-use
void clearIntegerSet(IntegerSet* iset) {
    // Lock the mutex
    pthread_mutex_lock(&iset->mutex);

    // Reset the size of the set to 0
    iset->size = 0;

    // Unlock the mutex
    pthread_mutex_unlock(&iset->mutex);
}
