    }
    manager->pdu_list = NULL;
    manager->pdu_count = 0;
    sem_init(&manager->mutex, 0, 1);
    return manager;
}

// Function to destroy a PDU_LIST_MANAGER structure
void destroy_pdu_list_manager(PDU_LIST_MANAGER *manager) {
    if (manager) {
        sem_destroy(&manager->mutex);
        free(manager->pdu_list);
        free(manager);
    }
}

// Function to add a new PDU to the list of managed PDUs
void add_pdu(PDU_LIST_MANAGER *manager, NFAPI_RLC_PDU_T pdu) {
    sem_wait(&manager->mutex);
    manager->pdu_list = (PDU_INFO*)realloc(manager->pdu_list, (manager->pdu_count + 1) * sizeof(PDU_INFO));
    if (!manager->pdu_list) {
        fprintf(stderr, "Error: Failed to allocate memory for PDU list\n");
        sem_post(&manager->mutex);
        return;
    }
    manager->pdu_list[manager->pdu_count].pdu = pdu;
    manager->pdu_list[manager->pdu_count].status = 0;
    manager->pdu_count++;
    sem_post(&manager->mutex);
}

// Function to remove a PDU from the list of managed PDUs
void remove_pdu(PDU_LIST_MANAGER *manager, int index) {
    if (index < 0 || index >= manager->pdu_count) {
        return;
    }
    sem_wait(&manager->mutex);
    for (int i = index + 1; i < manager->pdu_count; i++) {
        manager->pdu_list[i - 1] = manager->pdu_list[i];
    }
    manager->pdu_count--;
    sem_post(&manager->mutex);
}

// Function to update the status of a PDU in the list of managed PDUs
void update_status(PDU_LIST_MANAGER *manager, int index, int status) {
    if (index < 0 || index >= manager->pdu_count) {
        return;
    }
    sem_wait(&manager->mutex);
    manager->pdu_list[index].status = status;
    sem_post(&manager->mutex);
}

// Function to retrieve the next PDU in the list of managed PDUs
NFAPI_RLC_PDU_T get_next_pdu(PDU_LIST_MANAGER *manager) {
