        return NULL;
    }
    sem_wait(&manager->mutex);
    NFAPI_RLC_PDU_T pdu = manager->pdu_list[0].pdu;
    remove_pdu(manager, 0);
    sem_post(&manager->mutex);
    return pdu;
}
