// Structure to hold MAC transmission PDU information
typedef struct {
    uint8_t pduType; // valid MAC PDU type
    uint16_t payloadSize; // size of the payload in bytes
    uint8_t *payloadData; // pointer to the payload data buffer
} MAC_Transmission_PDU;

// Function to initialize and populate an array of MAC transmission PDUs
int initMACPDUS(MAC_Transmission_PDU *pduArray, int numPDUS, uint16_t maxPayloadSize) {
    // Check input parameters
    if (!pduArray || numPDUS <= 0 || maxPayloadSize == 0) {
        return -1; // error: invalid input parameters
    }

    // Initialize PDU array elements with default values
    for (int i = 0; i < numPDUS; i++) {
        pduArray[i].pduType = 0; // valid MAC PDU type is set to 0
        pduArray[i].payloadSize = 0; // payload size is set to 0
        pduArray[i].payloadData = NULL; // pointer to the payload data buffer is set to NULL
    }

    // Dynamically adjust payload sizes based on available system memory, network bandwidth, and hardware constraints
    uint16_t totalPayloadSize = 0; // total allocated memory for all PDUs in bytes
    int numPDUSPopulated = 0; // number of populated PDUs
    for (int i = 0; i < numPDUS; i++) {
        // Calculate the maximum allowed payload size based on available system memory and network bandwidth
        uint16_t maxAllowedPayloadSize = getMaxAllowedPayloadSize(totalPayloadSize, maxPayloadSize);
        if (maxAllowedPayloadSize == 0) { // error: no more memory available or insufficient network bandwidth
            break;
        }

        // Allocate memory for the payload data buffer
        pduArray[i].payloadData = malloc(maxAllowedPayloadSize);
        if (!pduArray[i].payloadData) { // error: failed to allocate memory
            break;
        }

        // Set the PDU type and payload size
        pduArray[i].pduType = 1; // valid MAC PDU type is set to 1
        pduArray[i].payloadSize = maxAllowedPayloadSize; // payload size is set to the maximum allowed payload size

        totalPayloadSize += maxAllowedPayloadSize; // update total allocated memory for all PDUs
        numPDUSPopulated++; // increment number of populated PDUs
    }

    return numPDUSPopulated; // return the number of populated PDUs
}

// Function to get the maximum allowed payload size based on available system memory and network bandwidth
uint16_t getMaxAllowedPayloadSize(uint16_t totalPayloadSize, uint16_t maxPayloadSize) {
    // Calculate the available system memory in bytes
    uint16_t availableSystemMemory = getAvailableSystemMemory();

    // Calculate the maximum allowed payload size based on the available system memory and network bandwidth
    uint16_t maxAllowedPayloadSize = 0;
    if (totalPayloadSize + maxPayloadSize > availableSystemMemory) {
        maxAllowedPayloadSize = availableSystemMemory - totalPayloadSize; // maximum allowed payload size is the available system memory minus the total allocated memory for all PDUs
    } else {
        maxAllowedPayloadSize = maxPayloadSize; // maximum allowed payload size is the requested maximum payload size
    }

    return maxAllowedPayloadSize; // return the maximum allowed payload size
}

// Function to get the available system memory in bytes
uint16_t getAvailableSystemMemory() {
    // Calculate the total memory available for allocation in bytes
    uint64_t totalMemory = 0;
#ifdef __linux__
    struct sysinfo info;
    if (sysinfo(&info) == 0) {
        totalMemory = info.totalram * info.mem_unit;
    } else {
        perror("getAvailableSystemMemory(): Failed to get total memory");
        return 0; // error: failed to get total memory available for allocation
    }
#elif __WIN32__
    MEMORYSTATUSEX status;
    if (GlobalMemoryStatusEx(&status) == 0) {
        totalMemory = status.ullTotalPhys;
    } else {
        perror("getAvailableSystemMemory(): Failed to get total memory");
        return 0; // error: failed to get total memory available for allocation
    }
#else
    #error "Unsupported platform"
#endif

    // Calculate the available system memory in bytes
    uint16_t availableSystemMemory = (uint16_t)(totalMemory - (totalMemory * 0.2)); // available system memory is calculated based on the total memory available for allocation, with a 20% safety margin to prevent excessive memory usage

    return availableSystemMemory; // return the available system memory in bytes
}
```
