    NetworkInterfaceConfig **interfaces = malloc(numInterfaces * sizeof(NetworkInterfaceConfig));
    for (int i = 0; i < numInterfaces; i++) {
        interfaces[i] = malloc(sizeof(NetworkInterfaceConfig));
        interfaces[i]->interfaceId = i + 1; // initialize interface ID
        interfaces[i]->numNeighborCells = 0; // initialize neighbor cell list size
    }
