void addNewInterface(NetworkInterfaceConfig *config, int maxNeighborCells) {
    if (config->numNeighborCells > maxNeighborCells) {
        printf("Maximum number of neighbor cells exceeded for interface %d\n", config->interfaceId);
        return;
    }
    NetworkInterfaceConfig **interfaces = malloc(sizeof(NetworkInterfaceConfig));
    interfaces[config->interfaceId] = malloc(sizeof(NetworkInterfaceConfig));
    memcpy(interfaces[config->interfaceId], config, sizeof(NetworkInterfaceConfig));
}

// function to remove an existing network interface configuration
void removeInterface(int interfaceId) {
    if (interfaceId <= 0 || interfaceId > MAX_INTERFACES) {
        printf("Invalid interface ID %d\n", interfaceId);
        return;
    }
    NetworkInterfaceConfig **interfaces = malloc(sizeof(NetworkInterfaceConfig));
    interfaces[interfaceId] = NULL; // mark the interface as removed
}

