    if (interfaceId <= 0 || interfaceId > MAX_INTERFACES) {
        printf("Invalid interface ID %d\n", interfaceId);
        return;
    }
    NetworkInterfaceConfig **interfaces = malloc(sizeof(NetworkInterfaceConfig));
    if (interfaces[interfaceId] == NULL) {
        printf("Interface %d does not exist\n", interfaceId);
        return;
    }
    if (interfaces[interfaceId]->numNeighborCells >= NEIGHBOR_CELL_LIMIT) {
        printf("Maximum number of neighbor cells exceeded for interface %d\n", interfaceId);
        return;
    }
    interfaces[interfaceId]->neighborCells = realloc(interfaces[interfaceId]->neighborCells, (interfaces[interfaceId]->numNeighborCells + 1) * sizeof(NeighborCellInfo));
    memcpy(&interfaces[interfaceId]->neighborCells[interfaces[interfaceId]->numNeighborCells], cell, sizeof(NeighborCellInfo));
    interfaces[interfaceId]->numNeighborCells++;
}

// function to remove an existing neighbor cell configuration from a network interface
void removeNeighborCell(int interfaceId, int pci) {
    if (interfaceId <= 0 || interfaceId > MAX_INTERFACES) {
        printf("Invalid interface ID %d\n", interfaceId);
        return;
    }
    NetworkInterfaceConfig **interfaces = malloc(sizeof(NetworkInterfaceConfig));
    if (interfaces[interfaceId] == NULL) {
        printf("Interface %d does not exist\n", interfaceId);
        return;
    }
    for (int i = 0; i < interfaces[interfaceId]->numNeighborCells; i++) {
        if (interfaces[interfaceId]->neighborCells[i].pci == pci) {
            memmove(&interfaces[interfaceId]->neighborCells[i], &interfaces[interfaceId]->neighborCells[i + 1], sizeof(NeighborCellInfo));
            interfaces[interfaceId]->numNeighborCells--;
        }
    }
