        printf("Interface %d does not exist\n", interfaceId);
        return;
    }
    for (int i = 0; i < interfaces[interfaceId]->numNeighborCells; i++) {
        if (interfaces[interfaceId]->neighborCells[i].pci == pci) {
            memcpy(cell, &interfaces[interfaceId]->neighborCells[i], sizeof(NeighborCellInfo));
            return;
