    array[size - 1].RNTI = RNTI;
    array[size - 1].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    array[size - 1].PHY_RXUEINFO_TAG = PHY_RXUEINFO_TAG;
    pthread_mutex_unlock(&mutex); // Unlock mutex after adding new structure
}

// Function to remove an existing structure from the array by RNTI
void remove_structure(int RNTI) {
