    for (i = 0; i < size; i++) {
        if (array[i].RNTI == RNTI) { // If RNTI matches, replace it with the last element of the array and shrink the array by one
            memcpy(&array[i], &array[size - 1], sizeof(LTE_PHY_RX_API_RXUEINFO_T));
            size--;
            break;
        }
    }
}

// Function to update signal quality data for an existing structure in the array by RNTI
void update_signal_quality(int RNTI, int PHY_STATE) {
