    for (i = 0; i < size; i++) {
        if (array[i].RNTI == RNTI) { // If RNTI matches, update the signal quality data
            array[i].PHY_STATE = PHY_STATE;
            break;
        }
    }
}

// Function to free memory when no longer needed
void free_memory() {
    if (array != NULL) { // If array is not empty, free its memory
        pthread_mutex_lock(&mutex); // Lock mutex for thread safety
        free(array);
        size = 0;
