#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Custom data structure for a user profile
typedef struct {
    long id;
    char* username;
    int num_posts;
    record** posts;
} user_profile;

// Record structure for storing post information
typedef struct {
    long offset;
    int key;
} record;

// Global variables for tracking memory usage and locks
long memory_usage = 0;
pthread_mutex_t* lock_array = NULL;

// Function to initialize the user profile data structure
void init_user_profile(user_profile** pp) {
    // Allocate memory for the new user profile
    *pp = (user_profile*)malloc(sizeof(user_profile));

    // Initialize the user ID, username, and number of posts to 0
    (*pp)->id = 0;
    (*pp)->username = NULL;
    (*pp)->num_posts = 0;

    // Allocate memory for the post list and initialize it to NULL
    (*pp)->posts = (record**)malloc(sizeof(record*) * MAX_POSTS);
    for (int i = 0; i < MAX_POSTS; i++) {
        (*pp)->posts[i] = NULL;
    }
}

// Function to free the user profile data structure
void free_user_profile(user_profile** pp) {
    // Free the username string
    if ((*pp)->username != NULL) {
        free((*pp)->username);
    }

    // Free the post list memory
    for (int i = 0; i < MAX_POSTS; i++) {
        if ((*pp)->posts[i] != NULL) {
            free((*pp)->posts[i]);
        }
    }

    // Free the user profile structure itself
    free(*pp);
}

// Function to add a new post to a user's profile
void add_post(user_profile** pp, char* username, long offset) {
    // Acquire a lock for the user ID
    pthread_mutex_lock(&lock_array[(*pp)->id]);

    // Increment the number of posts and allocate memory for the new post
    (*pp)->num_posts++;
    record* new_post = (record*)malloc(sizeof(record));
    new_post->offset = offset;
    new_post->key = 0;

    // Add the new post to the end of the post list
    int i = 0;
    while ((*pp)->posts[i] != NULL) {
        i++;
    }
    (*pp)->posts[i] = new_post;

    // Release the lock for the user ID
    pthread_mutex_unlock(&lock_array[(*pp)->id]);
}

// Function to remove a post from a user's profile
void remove_post(user_profile** pp, int index) {
    // Acquire a lock for the user ID
    pthread_mutex_lock(&lock_array[(*pp)->id]);

    // Decrement the number of posts and free the memory for the removed post
    (*pp)->num_posts--;
    record* removed_post = (*pp)->posts[index];
    free(removed_post);

    // Shift all subsequent posts down to fill the gap
    int i = index + 1;
    while ((*pp)->posts[i] != NULL) {
        (*pp)->posts[i - 1] = (*pp)->posts[i];
        i++;
    }

    // Release the lock for the user ID
    pthread_mutex_unlock(&lock_array[(*pp)->id]);
}

// Function to populate the offset field of each record structure with a random value within a specified range
void populate_offsets(user_profile** pp, int min_offset, int max_offset) {
    // Acquire a lock for the user ID
    pthread_mutex_lock(&lock_array[(*pp)->id]);

    // Randomly generate offset values within the specified range and populate them in each post
    srand(time(NULL));
    int random_offset = 0;
    for (int i = 0; i < (*pp)->num_posts; i++) {
        while (random_offset == 0) {
            random_offset = min_offset + rand() % (max_offset - min_offset);
        }
        (*pp)->posts[i]->offset = random_offset;
    }

    // Release the lock for the user ID
    pthread_mutex_unlock(&lock_array[(*pp)->id]);
}

// Function to serialize the user profile data structure into a JSON format for persistent storage
void serialize(user_profile** pp, FILE* fp) {
    // Acquire a lock for the user ID
    pthread_mutex_lock(&lock_array[(*pp)->id]);

    // Write the user ID and username to the file
    fprintf(fp, "{\"id\": %ld, \"username\": \"%s\", \"num_posts\": %d", (*pp)->id, (*pp)->username, (*pp)->num_posts);

    // Write each post in the list to the file
    for (int i = 0; i < (*pp)->num_posts; i++) {
        fprintf(fp, ",\"post\": %ld}", (*pp)->posts[i]->offset);
    }

    // Release the lock for the user ID
    pthread_mutex_unlock(&lock_array[(*pp)->id]);
}

// Function to deserialize a JSON-formatted string into a user profile data structure
void deserialize(user_profile** pp, char* json) {
    // Acquire a lock for the user ID
    pthread_mutex_lock(&lock_array[(*pp)->id]);

    // Parse the JSON string and extract the user ID and username
    long id = 0;
    char username[128] = "";
    int num_posts = 0;
    for (int i = 0; json[i] != '\0'; i++) {
        if (json[i] == '\"') {
            if (json[i + 1] == 'i' && json[i + 2] == 'd' && json[i + 3] == '\"') {
                sscanf(json + i + 4, "%ld", &id);
            } else if (json[i + 1] == 'u' && json[i + 2] == 's' && json[i + 3] == 'e' && json[i + 4] == 'r' && json[i + 5] == 'n' && json[i + 6] == 'a' && json[i + 7] == 'm' && json[i + 8] == 'e' && json[i + 9] == '\"') {
                sscanf(json + i + 10, "\"%s\"", username);
            } else if (json[i + 1] == 'o' && json[i + 2] == 'b' && json[i + 3] == 'j' && json[i + 4] == 'e' && json[i + 5] == 'c' && json[i + 6] == 't' && json[i + 7] == '\":') {
                sscanf(json + i + 8, "%d", &num_posts);
            }
        }
    }

    // Create a new user profile structure and initialize it with the extracted data
    *pp = (user_profile*)malloc(sizeof(user_profile));
    (*pp)->id = id;
    (*pp)->username = malloc((strlen(username) + 1) * sizeof(char));
    strcpy((*pp)->username, username);
    (*pp)->num_posts = num_posts;
    (*pp)->posts = (record**)malloc(sizeof(record*) * num_posts);

    // Acquire locks for each user ID in the JSON string and populate their post lists
    char temp[1024] = "";
    int i = 0;
    while (sscanf(json + i, "\"post\": %ld}", &temp[0]) != EOF) {
        long offset = 0;
        sscanf(temp, "%ld", &offset);
        pthread_mutex_lock(&lock_array[id]);
        record* new_post = (record*)malloc(sizeof(record));
        new_post->offset = offset;
        new_post->key = 0;
        (*pp)->posts[(*pp)->num_posts - 1] = new_post;
        pthread_mutex_unlock(&lock_array[id]);
        i++;
    }

    // Release the lock for the user ID
    pthread_mutex_unlock(&lock_array[(*pp)->id]);
}
```

In this code, we have implemented the functions `add_post`, `remove_post`, and `populate_offsets` to add or remove a post from a user's profile and populate each record structure with a random offset value within a specified range. We have also implemented the functions `serialize` and `deserialize` to serialize and deserialize a user profile data structure into JSON format for persistent storage.

