// Custom hash table implementation for efficient lookups and insertions
typedef struct {
    int key; // connection ID
    char *value; // pointer to the corresponding TCP_CONNECTION_STATE_T structure
} ConnectionTableEntry;

struct ConnectionTable {
    ConnectionTableEntry **entries; // array of pointers to the entries in the table
    int size; // number of entries in the table
    int capacity; // maximum number of entries the table can hold
};

void connectionTableInit(ConnectionTable *table) {
    table->size = 0;
    table->capacity = 16;
    table->entries = (ConnectionTableEntry **)malloc(sizeof(ConnectionTableEntry *) * table->capacity);
}

int connectionTableInsert(ConnectionTable *table, int key, char *value) {
    if (table->size >= table->capacity) {
        // resize the table when it's full
        table->entries = (ConnectionTableEntry **)realloc(table->entries, sizeof(ConnectionTableEntry *) * table->capacity * 2);
        table->capacity *= 2;
    }

    int index = key % table->capacity;
    while (table->entries[index] != NULL && table->entries[index]->key != key) {
        // linear probing
        index = (index + 1) % table->capacity;
    }

    if (table->entries[index] == NULL) {
        // insert a new entry
        ConnectionTableEntry *entry = (ConnectionTableEntry *)malloc(sizeof(ConnectionTableEntry));
        entry->key = key;
        entry->value = value;
        table->entries[index] = entry;
        table->size++;
    } else {
        // update the existing entry
        ConnectionTableEntry *entry = table->entries[index];
        free(entry->value);
        entry->value = value;
    }
}

char *connectionTableSearch(ConnectionTable *table, int key) {
    int index = key % table->capacity;
    while (table->entries[index] != NULL && table->entries[index]->key != key) {
        // linear probing
        index = (index + 1) % table->capacity;
    }

    if (table->entries[index] == NULL) {
        return NULL;
    } else {
        return table->entries[index]->value;
    }
}

void connectionTableDestroy(ConnectionTable *table) {
    for (int i = 0; i < table->capacity; i++) {
        if (table->entries[i] != NULL) {
            free(table->entries[i]);
        }
    }
    free(table->entries);
}

