// Memory pool for efficient reuse and reduced fragmentation
typedef struct {
    void **freeList; // list of free memory blocks
    int size; // number of free memory blocks in the pool
} MemoryPool;

void memoryPoolInit(MemoryPool *pool) {
    pool->size = 0;
}

void *memoryPoolAllocate(MemoryPool *pool, int size) {
    if (pool->size == 0) {
        return malloc(size);
    } else {
        void **freeList = pool->freeList;
        void *block = freeList[--pool->size];
        return block;
    }
}

void memoryPoolDeallocate(MemoryPool *pool, void *block) {
    if (pool->size < 1024) { // maximum number of free blocks to keep in the pool
        void **freeList = pool->freeList;
        freeList[pool->size++] = block;
    } else {
        free(block);
    }
}

