  void addEntry(struct CustomMessage* message) {
    // Check if the total number of entries exceeds the maximum size limit
    if (numMessages >= MAX_ENTRIES) {
      return;
    }

    // Ensure that no entry is added if it would violate the session frequency threshold
    int numActiveSessions = 0;
    for (int i = 0; i < numMessages; i++) {
      if (messages[i].deliveryStatus == DELIVERED) {
        numActiveSessions++;
      }
    }

    if (numActiveSessions >= MAX_ACTIVE_SESSIONS) {
      return;
    }

    // Add the new entry to the list
    messages[numMessages++] = *message;
