// Define a function to handle potential overflows and ensure that no memory leaks occur
void handle_overflow(LTE_PHY_RX_FRAME_T** frame_array, int* frame_count) {
    // Check if the dynamic array has exceeded its maximum capacity
    if (*frame_count > MAX_FRAMES) {
        // Free the oldest frame structure in the dynamic array
        free(frame_array[0]);

        // Shift all remaining frames one index to the left
        for (int i = 1; i < *frame_count - 1; i++) {
            frame_array[i - 1] = frame_array[i];
