// Define a function to verify the integrity of CRC indications using a predefined checksum function
bool verifyCrcIndication(CrcIndicationPdu *array, int size) {
    unsigned char checksum = 0;
    for (int i = 0; i < size; i++) {
        checksum += array[i].CRCFlag;
    }
    return checksum == 0;
}

// Define a function to process an array of NFAPI_CRC_INDICATION_PDU_T structures concurrently
void processArray(CrcIndicationPdu *array, int size) {
    pthread_t threads[size];
    for (int i = 0; i < size; i++) {
        pthread_create(&threads[i], NULL, (void *(*)(void *))processCrcIndication, array + i);
    }
    for (int i = 0; i < size; i++) {
        pthread_join(threads[i], NULL);
    }
}

// Define a function to handle CRC failures and memory leaks
void handleError(CrcIndicationPdu *array, int size) {
    printf("An error occurred during processing\n");
    for (int i = 0; i < size; i++) {
        if (array[i].CRCFlag != verifyCrcIndication(array + i)) {
            printf("Error: CRC failed on UE %d\n", i);
        } else {
            printf("UE %d processed successfully\n", i);
        }
    }
}

