void *processCrcIndication(void *args) {
    CrcIndicationPdu *crcIndication = (CrcIndicationPdu *) args;
    if (!verifyCrcIndication(crcIndication)) {
        handleError(crcIndication);
    } else {
        printf("UE %d processed successfully\n", crcIndication->CRCFlag);
    }
}

