// Function to dynamically create and populate an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* createAndPopulateArray(uint16_t n, uint16_t validRNTIRangeMin, uint16_t validRNTIRangeMax) {
