    if (n > MAX_ARRAY_SIZE || validRNTIRangeMin > validRNTIRangeMax) {
        return NULL;
    }

    // Allocate memory for the array of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* arr = (NFAPI_CRC_INDICATION_PDU_T*) malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (arr == NULL) {
        return NULL;
    }

    // Populate the array with random RNTIs and CRCFLAGs within valid ranges
    for (uint16_t i = 0; i < n; i++) {
        // Generate a random RNTI value within the valid range
