            config->interfaceId = interfaceId;
            config->interfaceName = interfaceName;
            config->neighborCells = neighborCells;
            config->srsParams = srsParams;
            // Add the new configuration to the pool
            configPool[config->interfaceId] = config;
        }
    }
    pthread_mutex_unlock(&poolLock);
    return result;
}

// Function to remove a network interface configuration from the pool
int removeConfig(int interfaceId) {
    int result = 0;
    pthread_mutex_lock(&poolLock);
    // Check if the interface exists in the pool
    if (configPool[interfaceId] == NULL) {
        fprintf(stderr, "Network interface %d does not exist in the configuration pool\n", interfaceId);
        result = -1;
    } else {
        // Free the memory associated with the configuration
        free(configPool[interfaceId]);
        configPool[interfaceId] = NULL;
    }
    pthread_mutex_unlock(&poolLock);
    return result;
}

// Function to periodically clean up unused or expired network interface configurations from the pool
void cleanupConfigs(void) {
    int i;
    pthread_mutex_lock(&poolLock);
    for (i = 0; i < MAX_INTERFACES; i++) {
        if (configPool[i] == NULL) {
            continue;
        }
        // Check if the configuration has expired or is no longer in use
        if (configPool[i]->expirationTime <= time(NULL)) {
            // Remove the configuration from the pool
            removeConfig(i);
        }
    }
    pthread_mutex_unlock(&poolLock);
}
