// Function to add a new device status update to the hash table
void add_device_status_update(char* device_id, long timestamp, int bandwidth_usage) {
    // Check if the hash table is initialized
    if (device_status_updates == NULL) {
        // Allocate memory for the hash table
        device_status_updates = malloc(sizeof(DeviceStatusUpdate));
    }

    // Check if there is already an entry for the given device ID
    DeviceStatusUpdate* update = device_status_updates;
    while (update != NULL) {
        if (strcmp(update->device_id, device_id) == 0) {
            // Update the existing entry with the new values
            update->timestamp = timestamp;
            update->bandwidth_usage = bandwidth_usage;
            return;
        }
        update = update->next;
    }

    // Add a new entry for the device ID
    DeviceStatusUpdate* new_update = malloc(sizeof(DeviceStatusUpdate));
    strcpy(new_update->device_id, device_id);
    new_update->timestamp = timestamp;
    new_update->bandwidth_usage = bandwidth_usage;
    new_update->next = device_status_updates;
    device_status_updates = new_update;
