#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdbool.h>
#include <stdint.h>
#include <pthread.h>
#include <unistd.h>

// Data structure for LTE MAC entities
typedef struct {
    uint32_t id; // Unique identifier for each entity
    pthread_mutex_t lock; // Mutex to protect concurrent access to the entity
    bool active; // Flag indicating whether the entity is currently valid or not
    struct PduSessions {
        uint16_t qosParams[4]; // QoS parameters for each session
        int32_t priority; // Priority of each session (higher value = higher priority)
        bool active; // Flag indicating whether the session is currently valid or not
    } sessions[MAX_SESSIONS]; // Array of PDU sessions associated with the entity
} MacEntity;

// Data structure for QoS parameters
typedef struct {
    uint32_t dlCqi; // DL CQI value (0-15)
    uint32_t ulCqi; // UL CQI value (0-15)
    uint8_t rssi; // RSSI value (0-7)
} QosParameters;

// Global variables
MacEntity* macEntities[MAX_ENTITIES]; // Array of LTE MAC entities
pthread_mutex_t macListLock; // Mutex to protect concurrent access to the list of entities
int32_t numEntities = 0; // Number of active LTE MAC entities in the system
const int32_t MAX_ENTITIES = 1000; // Maximum number of LTE MAC entities that can be stored in the system
const int32_t MAX_SESSIONS = 5; // Maximum number of PDU sessions that can be associated with each LTE MAC entity
const uint32_t REVALIDATION_INTERVAL = 10000; // Interval at which entities should be revalidated (in milliseconds)
const uint8_t MAX_PDU_SESSIONS = 5; // Maximum number of PDU sessions that can be associated with each LTE MAC entity

// Function to create a new LTE MAC entity
void createMacEntity(uint32_t id, int32_t numSessions) {
    if (numEntities >= MAX_ENTITIES) {
        printf("Error: Cannot create more than %d LTE MAC entities\n", MAX_ENTITIES);
        return;
    }

    MacEntity* entity = malloc(sizeof(MacEntity));
    memset(entity, 0, sizeof(MacEntity));
    entity->id = id;
    pthread_mutex_init(&entity->lock, NULL);
    entity->active = true;

    for (int32_t i = 0; i < numSessions; ++i) {
        PduSession* session = &entity->sessions[i];
        memset(session, 0, sizeof(PduSession));
        session->active = true;
    }

    macEntities[numEntities] = entity;
    numEntities++;
}

// Function to delete a LTE MAC entity
void deleteMacEntity(uint32_t id) {
    MacEntity* entity = getMacEntityById(id);
    if (entity == NULL) {
        printf("Error: Cannot find LTE MAC entity with ID %d\n", id);
        return;
    }

    // Acquire lock on the entity before deleting it
    pthread_mutex_lock(&entity->lock);

    // Mark the entity as inactive and free its memory
    entity->active = false;
    pthread_mutex_unlock(&entity->lock);
    free(entity);
}

// Function to get a LTE MAC entity by ID
MacEntity* getMacEntityById(uint32_t id) {
    for (int32_t i = 0; i < numEntities; ++i) {
        MacEntity* entity = macEntities[i];
        if (entity->id == id) {
            return entity;
        }
    }
    return NULL;
}

// Function to get a PDU session by ID and MAC entity ID
PduSession* getPduSessionById(uint32_t id, uint32_t macId) {
    MacEntity* entity = getMacEntityById(macId);
    if (entity == NULL) {
        return NULL;
    }

    for (int32_t i = 0; i < MAX_SESSIONS; ++i) {
        PduSession* session = &entity->sessions[i];
        if (session->id == id) {
            return session;
        }
    }
    return NULL;
}

// Function to update QoS parameters for a PDU session
void updateQosParams(uint32_t macId, uint16_t pduSessionId, const QosParameters* params) {
    MacEntity* entity = getMacEntityById(macId);
    if (entity == NULL) {
        printf("Error: Cannot find LTE MAC entity with ID %d\n", macId);
        return;
    }

    PduSession* session = getPduSessionById(pduSessionId, macId);
    if (session == NULL) {
        printf("Error: Cannot find PDU session with ID %d for MAC entity %d\n", pduSessionId, macId);
        return;
    }

    memcpy(&session->qosParams, params, sizeof(QosParameters));
}

// Function to revalidate entities based on QoS parameters
void revalidateEntities() {
    // Acquire lock on the list of entities before iterating over it
    pthread_mutex_lock(&macListLock);

    for (int32_t i = 0; i < numEntities; ++i) {
        MacEntity* entity = macEntities[i];
        if (!entity->active) continue; // Skip inactive entities

        bool revalidate = false;
        for (int32_t j = 0; j < MAX_SESSIONS; ++j) {
            PduSession* session = &entity->sessions[j];
            if (!session->active) continue; // Skip inactive sessions

            // Check if QoS parameters have changed since last revalidation
            if (memcmp(&session->qosParams, &lastRevalidatedQosParams[i][j], sizeof(QosParameters)) != 0) {
                revalidate = true;
                break;
            }
        }

        // Revalidate entity if QoS parameters have changed since last revalidation
        if (revalidate) {
            entity->active = false;
            pthread_mutex_unlock(&entity->lock);
            free(entity);
            i--; // Decrement counter to avoid skipping the next entity
            numEntities--;
        }
    }

    // Mark current QoS parameters as last revalidated
    for (int32_t i = 0; i < numEntities; ++i) {
        MacEntity* entity = macEntities[i];
        if (!entity->active) continue; // Skip inactive entities

        for (int32_t j = 0; j < MAX_SESSIONS; ++j) {
            PduSession* session = &entity->sessions[j];
            if (!session->active) continue; // Skip inactive sessions

            memcpy(&lastRevalidatedQosParams[i][j], &session->qosParams, sizeof(QosParameters));
        }
    }

    pthread_mutex_unlock(&macListLock);
}

// Function to update QoS parameters for all PDU sessions
void updateAllQosParams() {
    // Acquire lock on the list of entities before iterating over it
    pthread_mutex_lock(&macListLock);

    for (int32_t i = 0; i < numEntities; ++i) {
        MacEntity* entity = macEntities[i];
        if (!entity->active) continue; // Skip inactive entities

        for (int32_t j = 0; j < MAX_SESSIONS; ++j) {
            PduSession* session = &entity->sessions[j];
            if (!session->active) continue; // Skip inactive sessions

            updateQosParams(entity->id, session->id, &lastRevalidatedQosParams[i][j]);
        }
    }

    pthread_mutex_unlock(&macListLock);
}
