     * Returns the pointer to the created or retrieved DeviceConnection.
     */
    DeviceConnection* addDeviceConnection(uint64_t deviceId);

    /*
     * Removes a DeviceConnection from the manager, if it exists.
     * Returns true if the connection was removed successfully, false otherwise.
     */
    bool removeDeviceConnection(uint64_t deviceId);

    /*
     * Retrieves the DeviceConnection with the given device ID, creating it if necessary.
     * Returns a pointer to the retrieved or created DeviceConnection.
     */
    DeviceConnection* getDeviceConnection(uint64_t deviceId);

    /*
     * Updates the NetworkState of the DeviceConnection associated with the given device ID.
     * Returns true if the update was successful, false otherwise.
     */
    bool updateNetworkState(uint64_t deviceId, const NetworkState& newState);

    /*
     * Retrieves the NetworkState of the DeviceConnection associated with the given device ID.
     * Returns a reference to the retrieved NetworkState object.
     */
    const NetworkState& getNetworkState(uint64_t deviceId) const;

    /*
     * Populates an IPacketData structure with a valid SOURCE_IP, DESTINATION_PORT, and SEQUENCE_NUMBER for the given device ID.
     * Returns true if the packet data was successfully populated, false otherwise.
     */
    bool populatePacketData(uint64_t deviceId, IPacketData& packetData) const;

private:
    /*
     * The map of DeviceConnections, keyed by device ID.
     */
    std::map<uint64_t, std::unique_ptr<DeviceConnection>> connections_;

    /*
     * The monitoring service client for fetching real-time connection metrics asynchronously.
     */
    std::unique_ptr<MonitoringServiceClient> monitoringServiceClient_;

    /*
     * The mutex for synchronizing access to the DeviceConnections map.
     */
    mutable std::mutex connectionsMutex_;

    /*
     * The condition variable for notifying when new network state data is available.
     */
    std::condition_variable newNetworkStateDataCV_;

    /*
     * The last known network state data, keyed by device ID.
     */
    std::map<uint64_t, NetworkState> lastKnownNetworkStateData_;

    /*
     * The cache for storing previously fetched network state data.
     */
    std::map<uint64_t, NetworkState> networkStateCache_;

    /*
     * The mutex for synchronizing access to the network state cache.
     */
    mutable std::mutex networkStateCacheMutex_;

    /*
     * The retry mechanism for failed network operations with exponential backoff.
     */
    RetryMechanism<NetworkState> networkRetryMechanism_;

    /*
     * The logging level for critical events.
     */
    LoggingLevel loggingLevel_ = LoggingLevel::INFO;

    /*
     * The mutex for synchronizing access to the logging level.
     */
    mutable std::mutex loggingMutex_;

    /*
     * The file handler for the log file.
     */
    std::fstream logFileHandler_;

    /*
     * The current size of the log file.
     */
    uint64_t logFileSize_ = 0;

    /*
     * The maximum allowed size of the log file, in bytes.
     */
    uint64_t maxLogFileSize_ = 1024 * 1024; // 1 MB

    /*
     * The frequency at which to archive old logs.
     */
    uint32_t logArchiveFrequency_ = 5; // in minutes

    /*
     * The current CPU usage of the system.
     */
    double cpuUsage_ = 0;

    /*
     * The maximum allowed CPU usage, as a percentage.
     */
    double maxCpuUsage_ = 0.85;

    /*
     * The current memory usage of the system.
