     */
    double networkIoOpsPerSec_ = 0;

    /*
     * The maximum allowed network I/O operations per second.
     */
    double maxNetworkIoOpsPerSec_ = 100; // in ops/sec

    /*
     * The retry mechanism for failed self-healing operations with exponential backoff.
     */
    RetryMechanism<SelfHealingResult> selfHealingRetryMechanism_;

    /*
