static pthread_mutex_t g_crc_indication_list_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to dynamically manage the linked list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T *crc_indication_list_get(uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
