    NFAPI_CRC_INDICATION_PDU_T *element = g_crc_indication_list.head;
    while (element != NULL) {
        if ((element->RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) && (element->RNTI == RNTI)) {
            break;
        }
        element = element->next;
    }

    pthread_mutex_unlock(&g_crc_indication_list_lock);
    return element;
}

// Function to dynamically manage the linked list of NFAPI_CRC_INDICATION_PDU_T structures
void crc_indication_list_insert(NFAPI_CRC_INDICATION_PDU_T *element) {
    pthread_mutex_lock(&g_crc_indication_list_lock);

    if (g_crc_indication_list.size == 0) {
        g_crc_indication_list.head = element;
        g_crc_indication_list.tail = element;
    } else {
        g_crc_indication_list.tail->next = element;
        g_crc_indication_list.tail = element;
    }

    g_crc_indication_list.size++;

    pthread_mutex_unlock(&g_crc_indication_list_lock);
}

// Function to dynamically manage the linked list of NFAPI_CRC_INDICATION_PDU_T structures
void crc_indication_list_delete(NFAPI_CRC_INDICATION_PDU_T *element) {
    pthread_mutex_lock(&g_crc_indication_list_lock);

    if (g_crc_indication_list.head == element) {
        g_crc_indication_list.head = element->next;
    } else {
        NFAPI_CRC_INDICATION_PDU_T *prev = g_crc_indication_list.head;
        while (prev->next != element) {
            prev = prev->next;
        }
        prev->next = element->next;
    }

    if (g_crc_indication_list.tail == element) {
        g_crc_indication_list.tail = prev;
    }

    g_crc_indication_list.size--;

    pthread_mutex_unlock(&g_crc_indication_list_lock);
}

// Function to dynamically manage the linked list of NFAPI_CRC_INDICATION_PDU_T structures
void crc_indication_list_update(NFAPI_CRC_INDICATION_PDU_T *element) {
    pthread_mutex_lock(&g_crc_indication_list_lock);

    if (g_crc_indication_list.head == element) {
        g_crc_indication_list.head = element->next;
    } else {
        NFAPI_CRC_INDICATION_PDU_T *prev = g_crc_indication_list.head;
        while (prev->next != element) {
