// Define global variables for neighbor cell pool and buffer
static struct NeighborCellInfo *neighborCellsPool = NULL;
static size_t neighborCellsPoolSize = 0;
static struct NeighborCellInfo *tempBuffer = NULL;
static size_t tempBufferCapacity = 0;

// Define function to initialize network interface configuration
void initNetworkInterfaceConfig(struct NetworkInterfaceConfig *config, int numNeighborCells, float srsBandwidthThreshold) {
    // Allocate memory for neighbor cell pool and buffer
    size_t numNeighborCellsSize = sizeof(struct NeighborCellInfo) * numNeighborCells;
    if (neighborCellsPool == NULL) {
        neighborCellsPool = malloc(numNeighborCellsSize);
        memset(neighborCellsPool, 0, numNeighborCellsSize);
        neighborCellsPoolSize = numNeighborCells;
    } else if (numNeighborCells > neighborCellsPoolSize) {
        // Reallocate memory for neighbor cell pool to accommodate new number of cells
        struct NeighborCellInfo *tempPool = realloc(neighborCellsPool, sizeof(struct NeighborCellInfo) * numNeighborCells);
        if (tempPool == NULL) {
            // Handle error condition when memory allocation fails
        } else {
            neighborCellsPool = tempPool;
            neighborCellsPoolSize = numNeighborCells;
        }
    }

    // Allocate memory for temporary buffer
    size_t tempBufferCapacity = sizeof(struct NeighborCellInfo) * 16;
    tempBuffer = malloc(tempBufferCapacity);

    // Initialize configuration structure
    config->interfaceId = 0;
    config->neighborCells = neighborCellsPool;
    config->srsParams.bandwidth = srsBandwidthThreshold;
}

// Define function to populate neighbor cell list with unique neighbor cells
void populateNeighborCellList(struct NetworkInterfaceConfig *config) {
    // Lock access to shared resources
    pthread_mutex_lock(&neighborCellsPoolLock);

    // Iterate over all available neighbor cells and add new ones to the list
    for (int i = 0; i < config->numNeighborCells; i++) {
        struct NeighborCellInfo *cell = &config->neighborCells[i];
        if (cell->timestamp > time(NULL) - 600) { // Check if cell is recent enough to be included in the list
            bool duplicate = false;
            for (int j = i + 1; j < config->numNeighborCells; j++) {
                struct NeighborCellInfo *otherCell = &config->neighborCells[j];
                if (cell->neighborId == otherCell->neighborId) {
                    duplicate = true;
                    break;
                }
            }
            if (!duplicate) {
                cell->timestamp = time(NULL); // Update timestamp for this cell
                config->numNeighborCells++; // Increment number of neighbor cells in the list
            }
        }
    }

    // Unlock access to shared resources
    pthread_mutex_unlock(&neighborCellsPoolLock);
}

// Define function to configure SRS parameters based on predefined template
void configureSRSParams(struct NetworkInterfaceConfig *config) {
    // Lock access to shared resources
    pthread_mutex_lock(&tempBufferLock);

    // Iterate over all available neighbor cells and determine if they meet the signal quality threshold
    for (int i = 0; i < config->numNeighborCells; i++) {
        struct NeighborCellInfo *cell = &config->neighborCells[i];
        float signalQuality = getSignalQuality(cell); // Compute signal quality using proprietary algorithm
        if (signalQuality >= srsBandwidthThreshold) {
            config->srsParams.bandwidth = calculateSRSParams(signalQuality); // Calculate SRS parameters based on signal quality
            break; // Exit function early if a cell meets the threshold
        }
    }

    // Unlock access to shared resources
    pthread_mutex_unlock(&tempBufferLock);
}
