typedef struct {
    int frameNumber;
    // Other fields...
} NFAPI_RX_FRAME_INFO;

struct FrameListNode {
    NFAPI_RX_FRAME_INFO* data;
    struct FrameListNode* next;
};

typedef struct {
    int capacity;
    int size;
    struct FrameListNode* head;
    struct FrameListNode* tail;
} FrameList;

void initFrameList(FrameList* list) {
    assert(list != NULL);

    list->capacity = 10000; // Initial capacity of the list
    list->size = 0;
    list->head = NULL;
    list->tail = NULL;
}

void addFrameToList(FrameList* list, NFAPI_RX_FRAME_INFO* frame) {
    assert(list != NULL && frame != NULL);

    // Check if the list needs to be resized
    if (list->size == list->capacity) {
        // Resize the list by 50%
        int newCapacity = list->capacity * 3 / 2;
        struct FrameListNode* newHead = (struct FrameListNode*)malloc(sizeof(struct FrameListNode));
        if (newHead == NULL) {
            printf("Error: Failed to allocate memory for the new head node\n");
            return;
        }
        list->head = newHead;
        list->tail->next = newHead;
        list->capacity = newCapacity;
    }

    // Insert the frame at the end of the list
    struct FrameListNode* newNode = (struct FrameListNode*)malloc(sizeof(struct FrameListNode));
    if (newNode == NULL) {
        printf("Error: Failed to allocate memory for the new node\n");
        return;
    }
    newNode->data = frame;
    list->tail->next = newNode;
    list->tail = newNode;
    list->size++;
}

void freeFrameList(FrameList* list) {
    assert(list != NULL);

    struct FrameListNode* current = list->head;
    while (current != NULL) {
        struct FrameListNode* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
}
