    offsets[i] = rand() % limit;
    keys[i] = rand() % 100 + 1;
  }

  // Allocate memory for the record structures
  if (!(records = (record*)malloc(num_records * sizeof(record)))) {
    printf("Error: Failed to allocate memory for record structures.\n");
    free(offsets);
    free(keys);
    return NULL;
