// Union-Find data structure for managing disjoint pairs of elements
typedef struct {
    uint16_t *parent;
    uint16_t *size;
} UF_DS;

// Function for initializing the Union-Find data structure
void uf_init(UF_DS *uf) {
    uf->parent = (uint16_t *)malloc(sizeof(uint16_t) * 1024); // arbitrary size for now
    uf->size = (uint16_t *)malloc(sizeof(uint16_t) * 1024);
    memset(uf->parent, -1, sizeof(uint16_t) * 1024);
    memset(uf->size, 0, sizeof(uint16_t) * 1024);
}

// Function for finding the root of an element in the Union-Find data structure
uint16_t uf_find(UF_DS *uf, uint16_t x) {
    if (uf->parent[x] == -1) return x; // base case: element is a root
    else return uf_find(uf, uf->parent[x]); // recursive case: follow parent pointers until we find the root
}

// Function for merging two elements in the Union-Find data structure
void uf_union(UF_DS *uf, uint16_t x, uint16_t y) {
    uint16_t root_x = uf_find(uf, x); // find the roots of both elements
    uint16_t root_y = uf_find(uf, y);
    if (root_x == root_y) return; // don't merge two elements that are already in the same set

    // merge the smaller set into the larger set
    if (uf->size[root_x] < uf->size[root_y]) {
        uf->parent[root_x] = root_y;
        uf->size[root_y] += uf->size[root_x];
    } else {
        uf->parent[root_y] = root_x;
        uf->size[root_x] += uf->size[root_y];
    }
}

// Function for counting the number of disjoint pairs of elements in a list
uint32_t count_disjoint_pairs(UF_DS *uf, NFAPI_CRC_INDICATION_PDU_T *list, uint32_t len) {
    uint32_t num_pairs = 0;

    // initialize the Union-Find data structure
    uf_init(uf);

    // iterate through the list and merge elements based on their RNTIs
    for (uint32_t i = 0; i < len; i++) {
        uint16_t x = list[i].rnti;
        uint16_t y = list[i].crcflag ? list[i].rnti : -list[i].rnti; // if the CRC flag is set, use the RNTI as is. Otherwise, negate it

        uf_union(uf, x, y);
    }

    // iterate through the Union-Find data structure and count the number of disjoint sets
    for (uint32_t i = 0; i < len; i++) {
        uint16_t x = list[i].rnti;

        if (uf->parent[x] == -1) num_pairs++; // base case: element is a root, so it's in its own set and there's one disjoint pair
    }

    return num_pairs;
}

// Function for managing the list of NFAPI_CRC_INDICATION_PDU_T structures
void manage_list(NFAPI_CRC_INDICATION_PDU_T *list, uint32_t len) {
    UF_DS uf;

    // update the Union-Find data structure with new elements from the list
    for (uint32_t i = 0; i < len; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu = list[i];

        uint16_t x = pdu.rnti;
        uint16_t y = pdu.crcflag ? pdu.rnti : -pdu.rnti; // if the CRC flag is set, use the RNTI as is. Otherwise, negate it

        uf_union(&uf, x, y);
    }

    // remove elements from the list that are not in any disjoint set
    for (uint32_t i = 0; i < len;) {
        uint16_t rnti = list[i].rnti;

        if (uf.parent[rnti] == -1) { // element is not in any set, so remove it from the list
            memmove(&list[i], &list[i+1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (len-i));
            len--;
        } else {
            i++;
        }
    }
}

