#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <assert.h>
#include <pthread.h>
#include "nfapi_rx_frame.h"
#include "ltephy_tx_path_info.h"

struct UE_IDENTIFIER {
    int ue_id;
};

struct RF_PATH {
    char *rf_path;
};

struct NFAPI_RX_CHANNEL_T {
    struct NFAPI_RX_CHANNEL_T *next;
    int channel;
    int band;
    int freq;
};

struct LTEPHY_TxPathInfo {
    struct LTEPHY_TxPathInfo *next;
    int phy_tx_stream_id;
    int tx_antenna_index;
    int phy_tx_power_dbm;
};

struct UE_RX_FRAME_INFO {
    struct UE_IDENTIFIER *ue_identifier;
    struct RF_PATH *rf_path;
    struct NFAPI_RX_CHANNEL_T *rx_channel;
    struct LTEPHY_TxPathInfo *tx_path_info;
};

struct UE_RX_FRAME_DATA {
    int num_frames;
    struct UE_RX_FRAME_INFO **frames;
};

struct LOGGING_DATA {
    struct UE_RX_FRAME_DATA *rx_frame_data;
    pthread_mutex_t mutex;
};

void init_logging_data(struct LOGGING_DATA *log_data) {
    log_data->rx_frame_data = malloc(sizeof(struct UE_RX_FRAME_DATA));
    memset(log_data->rx_frame_data, 0, sizeof(struct UE_RX_FRAME_DATA));
}

void free_logging_data(struct LOGGING_DATA *log_data) {
    for (int i = 0; i < log_data->rx_frame_data->num_frames; i++) {
        free(log_data->rx_frame_data->frames[i]);
    }
    free(log_data->rx_frame_data);
}

void add_ue_identifier(struct UE_RX_FRAME_INFO *frame, struct UE_IDENTIFIER *ue_id) {
    frame->ue_identifier = malloc(sizeof(struct UE_IDENTIFIER));
    memcpy(frame->ue_identifier, ue_id, sizeof(struct UE_IDENTIFIER));
}

void add_rf_path(struct UE_RX_FRAME_INFO *frame, struct RF_PATH *rf_path) {
    frame->rf_path = malloc(sizeof(struct RF_PATH));
    memcpy(frame->rf_path, rf_path, sizeof(struct RF_PATH));
}

void add_rx_channel(struct UE_RX_FRAME_INFO *frame, struct NFAPI_RX_CHANNEL_T *channel) {
    frame->rx_channel = malloc(sizeof(struct NFAPI_RX_CHANNEL_T));
    memcpy(frame->rx_channel, channel, sizeof(struct NFAPI_RX_CHANNEL_T));
}

void add_tx_path_info(struct UE_RX_FRAME_INFO *frame, struct LTEPHY_TxPathInfo *tx_path_info) {
    frame->tx_path_info = malloc(sizeof(struct LTEPHY_TxPathInfo));
    memcpy(frame->tx_path_info, tx_path_info, sizeof(struct LTEPHY_TxPathInfo));
}

void parse_configuration_file(char *filename, struct LOGGING_DATA *log_data) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        char *token = strtok(line, " ");
        if (!token) {
            continue;
        }

        int num_frames = atoi(token);
        log_data->rx_frame_data->num_frames = num_frames;
        log_data->rx_frame_data->frames = malloc(sizeof(struct UE_RX_FRAME_INFO) * num_frames);
        memset(log_data->rx_frame_data->frames, 0, sizeof(struct UE_RX_FRAME_INFO) * num_frames);

        for (int i = 0; i < num_frames; i++) {
            struct UE_RX_FRAME_INFO *frame = log_data->rx_frame_data->frames[i];
            token = strtok(NULL, " ");
            if (!token) {
                break;
            }
            int ue_id = atoi(token);
            add_ue_identifier(frame, &(struct UE_IDENTIFIER){.ue_id = ue_id});

            token = strtok(NULL, " ");
            if (!token) {
                break;
            }
            int rf_path_index = atoi(token);
            struct RF_PATH *rf_path = &(struct RF_PATH){.rf_path = "RF_PATH_INDEX"};
            add_rf_path(frame, rf_path);

            token = strtok(NULL, " ");
            if (!token) {
                break;
            }
            int channel_index = atoi(token);
            struct NFAPI_RX_CHANNEL_T *channel = &(struct NFAPI_RX_CHANNEL_T){.channel = channel_index, .band = 0, .freq = 1};
            add_rx_channel(frame, channel);

            token = strtok(NULL, " ");
            if (!token) {
                break;
            }
            int tx_path_info_index = atoi(token);
            struct LTEPHY_TxPathInfo *tx_path_info = &(struct LTEPHY_TxPathInfo){.tx_path_info = tx_path_info_index};
            add_tx_path_info(frame, tx_path_info);
        }
    }

    fclose(file);
}

int main() {
    struct LOGGING_DATA log_data;
    parse_configuration_file("configuration.txt", &log_data);

    return 0;
}
```

This code will read the configuration file line by line, and for each line it will create a new `UE_RX_FRAME` struct and fill it with the appropriate data. The `add_ue_identifier`, `add_rf_path`, `add_rx_channel`, and `add_tx_path_info` functions are used to add the data to the structs.

The `parse_configuration_file` function is passed a filename, and it will read the file line by line, tokenizing each line using the space character as a delimiter. It will then iterate over the tokens, checking if they represent a valid UE identifier, RF path index, channel index, or TX path info index, and adding the corresponding data to the `UE_RX_FRAME` struct.

The code also contains some error handling, in case the file cannot be opened or there is an issue with the parsing of the tokens.

Note that this code assumes that the configuration file has the following format:
```
<number of frames> <UE identifier> <RF path index> <channel index> <TX path info index>
```
