// Structures for TCP connections and streams
typedef struct {
    char *server_address;
    int port;
    int num_streams;
    int *streams;
} TCP_CONNECTION_T;

typedef struct {
    int stream_id;
    int status;
    int metric1;
    int metric2;
} TCP_STREAM_T;

// Function to parse configuration file and create connections and streams
int parseConfig(const char *config_file, TCP_CONNECTION_T **connections) {
    FILE *fp = fopen(config_file, "r");
    if (fp == NULL) {
        perror("fopen");
        return -1;
    }

    int num_connections = 0;
    while (fscanf(fp, "%d", &num_connections) != EOF) {}
    *connections = malloc(sizeof(TCP_CONNECTION_T) * num_connections);

    for (int i = 0; i < num_connections; i++) {
