public class NetworkStats {
    public static List<NetworkStatsDTO> generateNetworkStatsReport(int N) {
        // Generate random network IDs and timestamps
        Random r = new Random();
        List<Integer> networkIds = new ArrayList<>();
        for (int i = 0; i < N; i++) {
            networkIds.add(r.nextInt(1000));
        }
        List<Long> timestamps = new ArrayList<>();
        for (int i = 0; i < N; i++) {
            timestamps.add(System.currentTimeMillis());
        }

        // Calculate bandwidth usage as a percentage of total capacity
        int totalCapacity = 1000;
        List<NetworkStatsDTO> networkStats = new ArrayList<>();
        for (int i = 0; i < N; i++) {
            int usage = r.nextInt(totalCapacity);
            NetworkStatsDTO dto = new NetworkStatsDTO();
            dto.setNetworkId(networkIds.get(i));
            dto.setTimestamp(timestamps.get(i));
            dto.setBandwidthUsage(usage);
            networkStats.add(dto);
        }

        return networkStats;
    }

    public static void updateRouterConfigurations(RouterConfig config) {
        // Calculate current network load based on bandwidth usage
        int totalBandwidth = 1000;
        int currentLoad = 0;
        for (NetworkStatsDTO dto : generateNetworkStatsReport(5)) {
            currentLoad += dto.getBandwidthUsage();
        }

        // Update router configurations based on load
        if (currentLoad > totalBandwidth * 0.8) {
            config.setBufferSize(totalBandwidth / 2);
            config.setQueueSize(totalBandwidth / 4);
        } else if (currentLoad > totalBandwidth * 0.6) {
            config.setBufferSize(totalBandwidth / 3);
            config.setQueueSize(totalBandwidth / 6);
        } else {
            config.setBufferSize(totalBandwidth / 4);
            config.setQueueSize(totalBandwidth / 8);
        }

        // Log configuration changes
        System.out.println("Updated router configurations: " + config.toString());
    }
}

