    public List<TransactionDTO> processFinancialTransactions(int batchSize, Configuration configuration, ConnectionManager connectionManager) {
        ExecutorService executor = Executors.newFixedThreadPool(MAX_THREADS);
        CompletionService<TransactionDTO> completionService = new ExecutorCompletionService<>(executor);

        List<Future<TransactionDTO>> futures = new ArrayList<>();
        for (int i = 0; i < batchSize; i++) {
            int transactionId = i + 1; // start from 1, not 0
            futures.add(completionService.submit(() -> processTransaction(transactionId, configuration, connectionManager)));
        }

        List<TransactionDTO> processedTransactions = new ArrayList<>();
        try {
            for (int i = 0; i < batchSize; i++) {
                Future<TransactionDTO> future = futures.get(i);
                TransactionDTO transactionDTO = future.get(TIMEOUT, TimeUnit.MILLISECONDS);
                processedTransactions.add(transactionDTO);
            }
        } catch (InterruptedException | ExecutionException | TimeoutException e) {
            // handle exceptions
            executor.shutdownNow();
        } finally {
            executor.shutdown();
        }

        return processedTransactions;
    }

