char* generateSensorId(const char *baseString, int offset) {
    char *sensorId = malloc(sizeof(char) * (strlen(baseString) + 10));
    sprintf(sensorId, "%s%d", baseString, offset);
    return sensorId;
}

NetworkInterfaceConfig* initNetworkInterfaceConfig(int interfaceId, int numNeighbors, SoundingReferenceSignalParameters *srsParams) {
    NetworkInterfaceConfig *config = malloc(sizeof(NetworkInterfaceConfig));
    config->interfaceId = interfaceId;
    config->frequencyBand = 0.0f; // Set default frequency band to 0
    config->transmissionPower = 0; // Set default transmission power to 0
    config->interfaceName = "unknown"; // Set default interface name to unknown

    int numSensors = numNeighbors * 2 + 1; // Calculate the number of sensors needed based on the number of neighbors
    sensor_reading **sensorReadings = malloc(sizeof(sensor_reading) * numSensors);

    for (int i = 0; i < numNeighbors; ++i) {
        NeighborCellInfo neighborCell = {
            .cellId = i + 1,
            .signalStrength = 0.0f,
            .isSrsEnabled = false
        };

        // Generate a unique sensor identifier for each neighbor cell using the provided base string and offset
        char *sensorId = generateSensorId("neighbor", i);
        sensor_reading *sensorReading = malloc(sizeof(sensor_reading));
        sensorReading->temperatureReading = 0; // Set default temperature reading to 0
        sensorReading->humidityLevel = 0.0f; // Set default humidity level to 0
        sensorReading->sensorId = sensorId;

        neighborCell.sensorReading = sensorReading;
        config->neighborCells[i] = neighborCell;
    }

    // Configure SRS parameters based on the predefined template
    if (srsParams != NULL) {
        config->srsFreq = srsParams->srsFreq;
        config->srsBandwidth = srsParams->srsBandwidth;
        config->srsDuration = srsParams->srsDuration;
    } else {
        // Set default SRS parameters if no predefined template is provided
        config->srsFreq = 0.0f;
        config->srsBandwidth = 0;
        config->srsDuration = 0;
    }

    return config;
}

void freeNetworkInterfaceConfig(NetworkInterfaceConfig *config) {
    free(config->interfaceName);
    for (int i = 0; i < config->numNeighbors; ++i) {
        free(config->neighborCells[i].sensorReading->sensorId);
        free(config->neighborCells[i].sensorReading);
    }
    free(config->neighborCells);
    free(config);
}
