// Function to dynamically manage a thread-safe list of UserSession structures
struct UserSession {
    int messageID;
    NFAPI_CRC_INDICATION_PDU_T rx_indication_pdu;
};

struct SessionList {
    pthread_mutex_t mutex; // Mutex for protecting the list
    struct UserSession *head; // Head of the linked list
};

// Function to allocate a new session and add it to the list
void add_session(struct SessionList *list, int messageID, NFAPI_CRC_INDICATION_PDU_T rx_indication_pdu) {
    struct UserSession *new_session = malloc(sizeof(struct UserSession));
    new_session->messageID = messageID;
    new_session->rx_indication_pdu = rx_indication_pdu;

    pthread_mutex_lock(&list->mutex);
    new_session->next = list->head;
    list->head = new_session;
    pthread_mutex_unlock(&list->mutex);
}

// Function to remove a session from the list and free its memory
void remove_session(struct SessionList *list, int messageID) {
    struct UserSession *current = NULL;
    struct UserSession *previous = NULL;

    pthread_mutex_lock(&list->mutex);
    current = list->head;
    while (current != NULL && current->messageID != messageID) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    if (previous == NULL) {
        list->head = current->next;
    } else {
        previous->next = current->next;
    }
    free(current);

    pthread_mutex_unlock(&list->mutex);
}

// Function to retrieve a session from the list by messageID
struct UserSession *get_session(struct SessionList *list, int messageID) {
    struct UserSession *current = NULL;

    pthread_mutex_lock(&list->mutex);
    current = list->head;
    while (current != NULL && current->messageID != messageID) {
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);

    return current;
}

// Function to serialize a session list into a binary format for storage or transmission
void serialize_session_list(struct SessionList *list, char **serialized) {
    struct UserSession *current = NULL;
    int size = 0;

    pthread_mutex_lock(&list->mutex);
    current = list->head;
    while (current != NULL) {
        size += sizeof(int) + sizeof(NFAPI_CRC_INDICATION_PDU_T);
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);

    *serialized = malloc(size);
    char *ptr = *serialized;

    pthread_mutex_lock(&list->mutex);
    current = list->head;
    while (current != NULL) {
        memcpy(ptr, &current->messageID, sizeof(int));
        ptr += sizeof(int);
        memcpy(ptr, &current->rx_indication_pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        ptr += sizeof(NFAPI_CRC_INDICATION_PDU_T);
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
}

// Function to deserialize a session list from a binary format for storage or transmission
void deserialize_session_list(struct SessionList *list, char *serialized) {
    struct UserSession *current = NULL;
    int size = 0;

    pthread_mutex_lock(&list->mutex);
    current = list->head;
    while (current != NULL) {
        size += sizeof(int) + sizeof(NFAPI_CRC_INDICATION_PDU_T);
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);

    char *ptr = serialized;

    while (size > 0) {
        int messageID = *(int *)ptr;
        ptr += sizeof(int);

        NFAPI_CRC_INDICATION_PDU_T rx_indication_pdu;
        memcpy(&rx_indication_pdu, ptr, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        ptr += sizeof(NFAPI_CRC_INDICATION_PDU_T);

        add_session(list, messageID, rx_indication_pdu);
        size -= sizeof(int) + sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }
}

// Function to validate an RX_UE_INFORMATION_TAG association with an RNTI
bool is_associated(struct SessionList *list, int messageID) {
    struct UserSession *session = get_session(list, messageID);
    if (session == NULL) {
        return false;
    }

    return true;
}

// Function to validate an RX_UE_INFORMATION_TAG association with an RNTI
bool is_associated(struct SessionList *list, int messageID) {
    struct UserSession *session = get_session(list, messageID);
    if (session == NULL) {
        return false;
    }

    return true;
}

// Function to handle a new RX_UE_INFORMATION_TAG association
void handle_association(struct SessionList *list, int messageID, NFAPI_CRC_INDICATION_PDU_T rx_indication_pdu) {
    if (is_associated(list, messageID)) {
        // Already associated, do nothing
        return;
    }

    add_session(list, messageID, rx_indication_pdu);
}

// Function to handle a lost RX_UE_INFORMATION_TAG association
void handle_disassociation(struct SessionList *list, int messageID) {
    if (!is_associated(list, messageID)) {
        // Already disassociated, do nothing
        return;
    }

    remove_session(list, messageID);
}

// Function to handle a received RX_UE_INFORMATION_TAG
void handle_rx_ue_information_tag(struct SessionList *list, int messageID, NFAPI_CRC_INDICATION_PDU_T rx_indication_pdu) {
    if (!is_associated(list, messageID)) {
        // Not associated, handle as a new association
        add_session(list, messageID, rx_indication_pdu);
        return;
    }

    struct UserSession *session = get_session(list, messageID);
    if (memcmp(&session->rx_indication_pdu, &rx_indication_pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T)) != 0) {
        // RX_UE_INFORMATION_TAG has changed, handle as a new association
        remove_session(list, messageID);
        add_session(list, messageID, rx_indication_pdu);
        return;
    }
}
```

This code uses a `struct UserSession` to store the information associated with each user session. The `struct SessionList` contains a linked list of all active user sessions, and provides methods for adding, removing, and retrieving sessions from the list.

The `serialize_session_list()` function serializes the session list into a binary format that can be stored or transmitted, while the `deserialize_session_list()` function deserializes the binary format back into an active session list.

The `is_associated()` function checks whether a given message ID is associated with an RNTI in the session list. The `handle_association()` and `handle_disassociation()` functions handle new and lost associations, respectively.

The `handle_rx_ue_information_tag()` function handles received RX_UE_INFORMATION_TAG messages by updating the stored RNTI for the given message ID if necessary, and handling the new association if not already present in the session list.']

