// Structure for a MAC frame
typedef struct {
    unsigned long long timestamp;
    bool control_info;
    size_t payload_size;
} MAC_FRAME_T;

// Circular buffer implementation
struct circular_buffer {
    // Pointer to the start of the buffer
    MAC_FRAME_T *buffer;
    // Size of the buffer
    size_t size;
    // Number of elements in the buffer
    size_t count;
    // Index of the next element to enqueue
    size_t enqueue_index;
    // Index of the next element to dequeue
    size_t dequeue_index;
};

// Function for initializing a circular buffer
void init_circular_buffer(struct circular_buffer *buffer, size_t size) {
    buffer->buffer = malloc(sizeof(MAC_FRAME_T) * size);
    buffer->size = size;
    buffer->count = 0;
    buffer->enqueue_index = 0;
    buffer->dequeue_index = 0;
}

// Function for enqueuing a MAC frame in the circular buffer
bool enqueue_frame(struct circular_buffer *buffer, MAC_FRAME_T frame) {
    // Check if the buffer is full
    if (buffer->count == buffer->size) {
        return false;
    }
    // Enqueue the frame
    buffer->buffer[buffer->enqueue_index] = frame;
    buffer->enqueue_index++;
    if (buffer->enqueue_index == buffer->size) {
        buffer->enqueue_index = 0;
    }
    buffer->count++;
    return true;
}

// Function for dequeuing a MAC frame from the circular buffer
MAC_FRAME_T dequeue_frame(struct circular_buffer *buffer) {
    // Check if the buffer is empty
    if (buffer->count == 0) {
        return NULL;
    }
    // Dequeue the first frame
    MAC_FRAME_T frame = buffer->buffer[buffer->dequeue_index];
    buffer->dequeue_index++;
    if (buffer->dequeue_index == buffer->size) {
        buffer->dequeue_index = 0;
    }
    buffer->count--;
    return frame;
}

