// Global variables for the connection state and arrays
static bool isConnected = false;
static int offsetArraySize = MAX_OFFSET_ARRAY_SIZE;
static int keyArraySize = MAX_KEY_ARRAY_SIZE;
static int recordCount = 0;
static long *offsets = NULL;
static int *keys = NULL;
static Record *records = NULL;

// Function to establish a resilient connection to a remote server using an asynchronous communication channel
int connectToServer(const char* hostname, const char* port) {
    // Create a socket and connect to the remote server
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        printf("Error creating socket: %s\n", strerror(errno));
        return -1;
    }

    struct sockaddr_in serverAddr;
    memset(&serverAddr, 0, sizeof(serverAddr));
    serverAddr.sin_family = AF_INET;
    serverAddr.sin_port = htons(atoi(port));
    if (inet_pton(AF_INET, hostname, &serverAddr.sin_addr) <= 0) {
        printf("Error parsing IP address: %s\n", strerror(errno));
        return -1;
    }

    if (connect(sockfd, (struct sockaddr*)&serverAddr, sizeof(serverAddr)) < 0) {
        printf("Error connecting to server: %s\n", strerror(errno));
        return -1;
    }

    // Initialize the connection state and arrays
    isConnected = true;
    offsets = (long*)calloc(offsetArraySize, sizeof(long));
    keys = (int*)calloc(keyArraySize, sizeof(int));
    records = (Record*)calloc(recordCount, sizeof(Record));

    return sockfd;
}

// Function to periodically assess the connection's health by sending a heartbeat message and waiting for a response
void sendHeartbeat(int sockfd) {
    // Send a heartbeat message to the server
    char buffer[1024];
    sprintf(buffer, "HEARTBEAT");
    if (send(sockfd, buffer, strlen(buffer), 0) < 0) {
        printf("Error sending heartbeat: %s\n", strerror(errno));
    }

    // Wait for a response from the server
    char response[1024];
    if (recv(sockfd, response, sizeof(response), 0) < 0) {
        printf("Error receiving heartbeat response: %s\n", strerror(errno));
    }

    // Check the response and update the connection state accordingly
    if (strcmp(response, "OK") == 0) {
        isConnected = true;
    } else {
        isConnected = false;
    }
}

// Function to handle concurrent access from multiple threads by using appropriate synchronization mechanisms
void* processRecords(void* arg) {
    // Initialize the record count and offset values for this thread
    int threadId = (int)arg;
    int startIndex = threadId * MAX_RECORD_COUNT / numThreads;
    int endIndex = (threadId + 1) * MAX_RECORD_COUNT / numThreads;
    int recordCount = endIndex - startIndex;

    // Lock the connection state and array size variables to prevent race conditions
    pthread_mutex_lock(&connectionMutex);
    if (recordCount > recordMax) {
        recordMax = recordCount;
    }
    pthread_mutex_unlock(&connectionMutex);

    // Lock the record array to prevent concurrent access
    pthread_mutex_lock(&recordsMutex);

    // Generate random integer keys and long offset values for each record
    int key;
    long offset;
    for (int i = startIndex; i < endIndex; i++) {
        key = generateRandomKey();
        offset = generateRandomOffset(key);
        records[i].key = key;
        records[i].offset = offset;
    }

    // Unlock the record array and connection state variables
    pthread_mutex_unlock(&recordsMutex);
    pthread_mutex_unlock(&connectionMutex);

    return NULL;
}

// Function to generate random integer keys within a specified range
int generateRandomKey() {
    // Use a pseudo-random number generator to generate the key
    int key = rand();
    while (key < MIN_KEY || key > MAX_KEY) {
        key = rand();
    }

    return key;
}

// Function to generate random long offset values within a specified range
long generateRandomOffset(int key) {
    // Use a pseudo-random number generator to generate the offset
    long offset = rand() % MAX_OFFSET + MIN_OFFSET;
    while (offset < MIN_OFFSET || offset > MAX_OFFSET) {
        offset = rand() % MAX_OFFSET + MIN_OFFSET;
    }

    return offset;
}

// Function to update the array size variables when a new record is added
void updateArraySize(int threadId, int startIndex, int endIndex) {
    pthread_mutex_lock(&connectionMutex);
    if (endIndex > recordMax) {
        recordMax = endIndex;
    }
    pthread_mutex_unlock(&connectionMutex);
}

// Function to close the connection and release resources
void disconnect() {
    // Close the socket and free memory
    shutdown(sockfd, SHUT_RDWR);
    free(offsets);
    free(keys);
    free(records);

    isConnected = false;
}

int main() {
    // Initialize the connection state and arrays
    connect();

    // Spawn multiple threads to process records concurrently
    pthread_t* threads = (pthread_t*)calloc(numThreads, sizeof(pthread_t));
    for (int i = 0; i < numThreads; i++) {
        int threadId = i;
        pthread_create(&threads[i], NULL, processRecords, (void*)threadId);
    }

    // Join the threads and wait for them to complete
    void* status;
    for (int i = 0; i < numThreads; i++) {
        pthread_join(threads[i], &status);
    }

    // Close the connection and release resources
    disconnect();

    return 0;
}']

