            free(pool->pool);
            free(pool);
            pthread_mutex_unlock(&mutex);
            return;
        }
    }
    InitializedInterface *interface = malloc(sizeof(InitializedInterface));
    if (!interface) {
        printf("Failed to allocate memory for initialized interface\n");
        free(pool->pool);
        free(pool);
        pthread_mutex_unlock(&mutex);
        return;
    }
    interface->interfaceId = interfaceId;
    interface->config = config;
    interface->next = NULL;
    if (initializedInterfaces == NULL) {
        initializedInterfaces = interface;
    } else {
        InitializedInterface *curr = initializedInterfaces;
        while (curr->next != NULL) {
            curr = curr->next;
        }
        curr->next = interface;
    }
    pthread_mutex_unlock(&mutex);
}

// Define function to populate neighbor cell list with unique entries
void populateNeighborCellList(NeighborCellInfo **neighborCells, uint16_t numEntries) {
