    if (!table->table) {
        printf("Failed to allocate memory for neighbor cell list\n");
        free(table);
        return;
    }

    // Iterate through the neighbor cell list and add unique entries
    NeighborCellInfo *curr = *neighborCells;
    while (curr != NULL) {
        bool duplicateFound = false;
        for (uint16_t i = 0; i < table->size; i++) {
            if (table->table[i] != NULL && table->table[i]->id == curr->id) {
                // Duplicate found, add to neighbor cell list
                duplicateFound = true;
                break;
            }
        }
        if (!duplicateFound) {
            NeighborCellInfo *entry = malloc(sizeof(NeighborCellInfo));
            if (!entry) {
