                free(table->table);
                free(table);
                return;
            }
            memcpy(entry, curr, sizeof(NeighborCellInfo));
            table->table[hashFunc(curr->id)] = entry;
        }
        curr = curr->next;
    }

    // Set the neighbor cell list to the hash table
    *neighborCells = (NeighborCellInfo *)table->table;
}

// Define function to check for duplicate entries in a list
bool containsDuplicates(NeighborCellInfo **list, uint16_t numEntries) {
    // Create a hash table for storing the neighbor cells
    HashTable *table = malloc(sizeof(HashTable));
    if (!table) {
        printf("Failed to allocate memory for neighbor cell list\n");
        return true;
    }
    table->size = numEntries;
    table->table = calloc(numEntries, sizeof(NeighborCellInfo *));
    if (!table->table) {
        printf("Failed to allocate memory for neighbor cell list\n");
        free(table);
        return true;
    }

    // Iterate through the list and check for duplicates
    NeighborCellInfo *curr = *list;
    while (curr != NULL) {
        bool duplicateFound = false;
        for (uint16_t i = 0; i < table->size; i++) {
            if (table->table[i] != NULL && table->table[i]->id == curr->id) {
                // Duplicate found, return true
                duplicateFound = true;
                break;
            }
        }
        if (duplicateFound) {
            free(table->table);
            free(table);
            return true;
        }
        table->table[hashFunc(curr->id)] = curr;
        curr = curr->next;
    }

    // No duplicates found, return false
    free(table->table);
    free(table);
    return false;
}
