// Custom hash table implementation for key uniqueness checks
struct HashTable {
    int *keys;
    size_t capacity;
    size_t used;
};

void hashTableInit(struct HashTable *ht, size_t capacity) {
    ht->capacity = capacity;
    ht->used = 0;
    ht->keys = malloc(sizeof(int) * capacity);
}

bool hashTableInsert(struct HashTable *ht, int key) {
    if (ht->used == ht->capacity) {
        // Rehash the table if it's full
        size_t new_capacity = ht->capacity * 2;
        int *new_keys = malloc(sizeof(int) * new_capacity);
        memcpy(new_keys, ht->keys, sizeof(int) * ht->used);
        free(ht->keys);
        ht->keys = new_keys;
        ht->capacity = new_capacity;
    }
    ht->keys[ht->used++] = key;
}

bool hashTableContains(struct HashTable *ht, int key) {
    for (size_t i = 0; i < ht->used; i++) {
        if (ht->keys[i] == key) {
            return true;
        }
    }
    return false;
}

// Custom logging mechanism for error reporting
void logError(const char *msg) {
    printf("ERROR: %s\n", msg);
}

