    while (i < config->initial_capacity) {
        int value = rand() % (config->max_value - config->min_value + 1) + config->min_value;
        if (!hashTableContains(ht, value)) {
            hashTableInsert(ht, value);
            records[i++]->value = value;
        }
    }
}

// Dynamic resizing strategy for the array of 'record' structures
void resizeRecords(struct Config *config, struct Record **records) {
    // Rehash the table if it's full and create a new hash table with twice the capacity
    size_t new_capacity = ht->capacity * 2;
    int *new_keys = malloc(sizeof(int) * new_capacity);
    memcpy(new_keys, ht->keys, sizeof(int) * ht->used);
    free(ht->keys);
    ht->keys = new_keys;
    ht->capacity = new_capacity;

    // Resize the array of 'record' structures to match the new capacity
    size_t i = 0;
    while (i < config->initial_capacity) {
        records[i++]->value = rand() % (config->max_value - config->min_value + 1) + config->min_value;
    }
}

// Thread-safe implementation of the function to ensure data corruption or race conditions under concurrent access
void manageRecords(struct Config *config, struct Record **records) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    while (true) {
        // Acquire the lock before accessing the records
        pthread_mutex_lock(&mutex);
        if (ht->used == ht->capacity) {
            resizeRecords(config, records);
        }
        int value = rand() % (config->max_value - config->min_value + 1) + config->min_value;
        if (!hashTableContains(ht, value)) {
            hashTableInsert(ht, value);
            records[i++]->value = value;
        }
        // Release the lock to allow other threads to access the records
        pthread_mutex_unlock(&mutex);
    }
}

int main() {
    struct Config config = {
        .min_value = 1,
        .max_value = 100,
        .initial_capacity = 16
    };
    struct Record **records = malloc(sizeof(struct Record *) * config.initial_capacity);
    for (size_t i = 0; i < config.initial_capacity; i++) {
        records[i] = malloc(sizeof(struct Record));
        records[i]->value = 0;
    }
    struct HashTable ht;
    hashTableInit(&ht, config.initial_capacity);
    manageRecords(&config, records);
}
