void connectToServer(char *server_ip, int port) {
    // create socket and set up socket options
    struct sockaddr_in serv_addr = {0};
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(port);
    inet_pton(AF_INET, server_ip, &serv_addr.sin_addr);

    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        printf("Socket creation failed!\n");
        return;
    }

    int optval = 1;
    setsockopt(sockfd, SOL_SOCKET, SO_KEEPALIVE, &optval, sizeof(optval));
    setsockopt(sockfd, SOL_SOCKET, SO_REUSEADDR, &optval, sizeof(optval));

    // establish connection to remote server
    if (connect(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        printf("Connection failed!\n");
        close(sockfd);
        return;
    }

    // handle various connection states and manage retries for transient failures
    bool connected = false;
    while (!connected) {
        int status = connect(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr));
        if (status < 0 && errno == ECONNREFUSED) {
            // connection refused, retry after a short delay
            sleep(1);
        } else if (status < 0) {
            printf("Connection failed!\n");
            close(sockfd);
            return;
        } else {
            connected = true;
        }
    }

    // log successful connection and handle any connection-related errors gracefully
    printf("Connected to remote server!\n");
}

