#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <stdint.h>

typedef struct {
    uint8_t tag;
    void* data;
} NFAPI_RRC_MESSAGE_T;

typedef enum {
    RRC_MESSAGE_TYPE_TAG,
    BSR_REQUEST_TAG,
    UPLINK_CQI_TAG,
    NUMBER_OF_TAGS
} MessageTag;

void initializeAndPopulateMessageArray(NFAPI_RRC_MESSAGE_T** messageArray, size_t n) {
    // Allocate memory for the array of messages
    *messageArray = (NFAPI_RRC_MESSAGE_T*) malloc(n * sizeof(NFAPI_RRC_MESSAGE_T));

    if (*messageArray == NULL) {
        printf("Failed to allocate memory for message array\n");
        return;
    }

    // Initialize the tags in each message structure
    for (size_t i = 0; i < n; i++) {
        (*messageArray)[i].tag = RRC_MESSAGE_TYPE_TAG;
        (*messageArray)[i].data = NULL;
    }

    // Populate the array of messages with data from external sources
    for (size_t i = 0; i < n; i++) {
        NFAPI_RRC_MESSAGE_T* message = &(*messageArray)[i];

        // Acquire RRC message type tag from external source
        message->tag = acquireRrcMessageTypeTag();

        if (message->tag == RRC_MESSAGE_TYPE_TAG) {
            // Acquire BSR request data from external source
            size_t bsrRequestSize = acquireBsrRequestSize();

            if (bsrRequestSize > 0) {
                message->data = malloc(bsrRequestSize * sizeof(uint8_t));

                if (message->data == NULL) {
                    printf("Failed to allocate memory for BSR request\n");
                    return;
                }

                // Acquire BSR request data from external source and copy it into the message structure
                acquireBsrRequest(message->data, bsrRequestSize);
            }
        } else if (message->tag == BSR_REQUEST_TAG) {
            // Acquire UPLINK CQI data from external source
            size_t uplinkCqiSize = acquireUplinkCqiSize();

            if (uplinkCqiSize > 0) {
                message->data = malloc(uplinkCqiSize * sizeof(uint8_t));

                if (message->data == NULL) {
                    printf("Failed to allocate memory for UPLINK CQI\n");
                    return;
                }

                // Acquire UPLINK CQI data from external source and copy it into the message structure
                acquireUplinkCqi(message->data, uplinkCqiSize);
            }
        }
    }
}

void freeMessageArray(NFAPI_RRC_MESSAGE_T** messageArray) {
    if (*messageArray == NULL) {
        return;
    }

    for (size_t i = 0; i < n; i++) {
        NFAPI_RRC_MESSAGE_T* message = &(*messageArray)[i];

        // Free the memory allocated for the data field of each message structure
        if (message->data != NULL) {
            free(message->data);
            message->data = NULL;
        }
    }

    // Free the memory allocated for the array of messages
    free(*messageArray);
    *messageArray = NULL;
}

int main() {
    size_t n = 10;

    NFAPI_RRC_MESSAGE_T** messageArray = (NFAPI_RRC_MESSAGE_T**) malloc(n * sizeof(NFAPI_RRC_MESSAGE_T*));

    if (messageArray == NULL) {
        printf("Failed to allocate memory for message array\n");
        return 1;
    }

