// Custom memory pool for high-throughput environments
struct MemPool {
    size_t capacity;
    size_t used;
    struct Node *head;
};

// Node structure for the custom memory pool
struct Node {
    void *data;
    struct Node *next;
};

// Structure to store NFAPI_CRC_INDICATION_PDU_T data
struct CrcIndicationData {
    uint32_t rx_ue_information_tag;
    uint16_t rnti;
    bool crc_flag;
};

// Function to insert a new element into the list
void insertElement(struct MemPool *pool, struct CrcIndicationData data) {
    // Check if the pool has reached its capacity
    if (pool->used == pool->capacity) {
        // Reallocate the pool with double the capacity
        size_t newCapacity = pool->capacity * 2;
        struct Node *newHead = realloc(pool->head, newCapacity * sizeof(struct Node));
        if (!newHead) {
            fprintf(stderr, "Failed to allocate memory for the pool\n");
            exit(1);
        }
        // Update the pool's capacity and head pointer
        pool->capacity = newCapacity;
        pool->head = newHead;
    }

    // Allocate memory for the new element
    struct Node *newNode = malloc(sizeof(struct Node));
    if (!newNode) {
        fprintf(stderr, "Failed to allocate memory for the new node\n");
        exit(1);
    }

    // Initialize the new element with the given data
    newNode->data = data;
    newNode->next = pool->head;
    pool->head = newNode;

    // Increment the used count of the pool
    ++pool->used;
}

// Function to delete an element from the list
void deleteElement(struct MemPool *pool, uint16_t rnti) {
    struct Node *nodeToDelete = NULL;
    struct Node *currentNode = pool->head;

    // Find the node with the given RNTI value
    while (currentNode && currentNode->data.rnti != rnti) {
        currentNode = currentNode->next;
    }

    // If the node is found, delete it and update the pool's used count
    if (currentNode) {
        nodeToDelete = currentNode;
        pool->head = currentNode->next;
        --pool->used;

        // Free the memory of the deleted node
        free(nodeToDelete);
    }
}

// Function to clear the list and reset the pool
void clearPool(struct MemPool *pool) {
    struct Node *currentNode = pool->head;

    // While there are still nodes in the list, delete them one by one
    while (currentNode) {
        struct Node *nextNode = currentNode->next;
        free(currentNode);
        currentNode = nextNode;
    }

    // Reset the pool's used count and head pointer
    pool->used = 0;
    pool->head = NULL;
}

// Function to get a random value for the CRC_INDICATION_REL8_TAG
uint32_t getRandomCrcIndicationRel8Tag() {
    // Generate a random number between 0 and 1
    double randomValue = (double)rand() / RAND_MAX;

    // Calculate the integer representation of the random value
    uint32_t crcIndicationRel8Tag = (uint32_t)(randomValue * UINT32_MAX);

    return crcIndicationRel8Tag;
}

// Function to initialize a new CrcIndicationData structure
void initCrcIndicationData(struct CrcIndicationData *data, uint16_t rnti) {
    data->rx_ue_information_tag = getRandomCrcIndicationRel8Tag();
    data->rnti = rnti;
    data->crc_flag = false;
}

