void generateWebFooterFromInput(int input[]) {
  int num_inputs = sizeof(input) / sizeof(input[0]); // Get the number of inputs
  NFAPI_CRC_INDICATION_PDU_T *crc_indication_pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_inputs * sizeof(NFAPI_CRC_INDICATION_PDU_T)); // Allocate memory for the structures
