    script_tags[i] = tag; // Add the script tag to the list
  }

  // Concatenate the script tags into an HTML string
  char html[1024]; // Allocate memory for the HTML string
  strcpy(html, "<!DOCTYPE html><html><body>"); // Start the HTML body
  for (i = 0; i < num_inputs; i++) {
    strcat(html, script_tags[i]); // Concatenate the current script tag
  }
  strcpy(html + strlen(html), "</body></html>"); // End the HTML body

  // Output the HTML string to standard output
  printf("%s", html);

  // Free memory for the structures and script tags
  free(crc_indication_pdu);
  for (i = 0; i < num_inputs; i++) {
    free(script_tags[i]);
  }
  free(script_tags);
}
