#include <unistd.h>
#include <pthread.h>

#define MIN_RECORD_SIZE 1024
#define MAX_RECORD_SIZE 8192
#define INITIAL_POOL_SIZE (1 << 20) // 1MB
#define POOL_GROWTH_FACTOR 2

typedef struct Record {
    long offset;
    int key;
    void* metadata;
} Record;

typedef struct Pool {
    size_t size;
    size_t used;
    void* data;
    pthread_mutex_t lock;
} Pool;

Pool* create_pool(size_t initial_size) {
    Pool* pool = malloc(sizeof(Pool));
    if (!pool) {
        return NULL;
    }
    pool->size = initial_size;
    pool->used = 0;
    pool->data = malloc(initial_size);
    if (!pool->data) {
        free(pool);
        return NULL;
    }
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

bool expand_pool(Pool* pool) {
    size_t new_size = pool->size * POOL_GROWTH_FACTOR;
    void* new_data = realloc(pool->data, new_size);
    if (!new_data) {
        return false;
    }
    pool->data = new_data;
    pool->size = new_size;
    return true;
}

bool allocate_record(Pool* pool, Record** record) {
    pthread_mutex_lock(&pool->lock);
    if (pool->used == pool->size) {
        bool success = expand_pool(pool);
        if (!success) {
            return false;
        }
    }
    *record = (Record*)pool->data + pool->used++;
    pthread_mutex_unlock(&pool->lock);
    return true;
}

void free_pool(Pool* pool) {
    if (!pool) {
        return;
    }
    pthread_mutex_destroy(&pool->lock);
    free(pool->data);
    free(pool);
}

Record** allocate_records(size_t count, size_t* out_count) {
    *out_count = 0;
    Record** records = NULL;
    Pool* pool = create_pool(INITIAL_POOL_SIZE);
    if (!pool) {
        return NULL;
    }
    while (*out_count < count) {
        size_t current_size = *out_count;
        Record** new_records = realloc(records, sizeof(Record*) * (current_size + 1));
        if (!new_records) {
            free_pool(pool);
            return NULL;
        }
        records = new_records;
        records[*out_count] = NULL;
        for (size_t i = current_size; i < *out_count + 1; ++i) {
            if (!allocate_record(pool, &records[i])) {
                free_pool(pool);
                records = realloc(records, sizeof(Record*) * current_size);
                return NULL;
            }
        }
        (*out_count)++;
    }
    free_pool(pool);
    return records;
}

void populate_records(Record** records, size_t count, int* keys, void* metadata) {
    for (size_t i = 0; i < count; ++i) {
        Record* record = records[i];
        record->key = keys[i];
        record->metadata = metadata;
        // Set offset to a random value within the specified range
        srand(time(NULL));
        record->offset = (long)(rand() % (MAX_RECORD_SIZE - MIN_RECORD_SIZE) + MIN_RECORD_SIZE);
    }
}

void free_records(Record** records, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        Record* record = records[i];
        if (record) {
            free(record->metadata);
            free(record);
        }
    }
    free(records);
}

// Implement a custom hash table to manage unique keys efficiently
typedef struct HashTable {
    size_t capacity;
    size_t size;
    Record** records;
} HashTable;

HashTable* create_hash_table(size_t initial_capacity) {
    HashTable* hash_table = malloc(sizeof(HashTable));
    if (!hash_table) {
        return NULL;
    }
    hash_table->capacity = initial_capacity;
    hash_table->size = 0;
    hash_table->records = calloc(initial_capacity, sizeof(Record*));
    if (!hash_table->records) {
        free(hash_table);
        return NULL;
    }
    return hash_table;
}

bool insert_record(HashTable* hash_table, Record* record) {
    size_t index = hash_value(record->key);
    if (index >= hash_table->capacity) {
        return false;
    }
    while (hash_table->records[index]) {
        if (hash_table->records[index]->key == record->key) {
            return false;
        }
        index++;
        if (index >= hash_table->capacity) {
            index = 0;
        }
    }
    hash_table->records[index] = record;
    hash_table->size++;
    return true;
}

bool delete_record(HashTable* hash_table, int key) {
    size_t index = hash_value(key);
    if (index >= hash_table->capacity) {
        return false;
    }
    Record** record = &hash_table->records[index];
    while (*record && (*record)->key != key) {
        record++;
        if (record == hash_table->records + hash_table->capacity) {
            record = hash_table->records;
        }
    }
    if (!*record) {
        return false;
    }
    *record = NULL;
    hash_table->size--;
    return true;
}

bool search_record(HashTable* hash_table, int key) {
    size_t index = hash_value(key);
    if (index >= hash_table->capacity) {
        return false;
    }
    Record** record = &hash_table->records[index];
    while (*record && (*record)->key != key) {
        record++;
        if (record == hash_table->records + hash_table->capacity) {
            record = hash_table->records;
        }
    }
    return *record != NULL;
}

void free_hash_table(HashTable* hash_table) {
    if (!hash_table) {
        return;
    }
    for (size_t i = 0; i < hash_table->capacity; ++i) {
        Record* record = hash_table->records[i];
        if (record) {
            free(record->metadata);
            free(record);
        }
    }
    free(hash_table->records);
    free(hash_table);
}

void example() {
    size_t count = 0;
    Record** records = allocate_records(10, &count);
    if (!records) {
        return;
    }
    int keys[5] = {1, 2, 3, 4, 5};
    void* metadata = malloc(sizeof(char) * 10);
    populate_records(records, count, keys, metadata);
    // Implement a hash table to manage the unique keys efficiently
    HashTable* hash_table = create_hash_table(count);
    for (size_t i = 0; i < count; ++i) {
        Record* record = records[i];
        insert_record(hash_table, record);
    }
    // Search for a specific key and delete it if found
    int key_to_delete = 2;
    bool success = delete_record(hash_table, key_to_delete);
    if (success) {
        printf("Key %d deleted successfully\n", key_to_delete);
    } else {
        printf("Key %d not found or already deleted\n", key_to_delete);
    }
    free_hash_table(hash_table);
    // Free the records and the metadata
    free_records(records, count);
}
