// Define the function to send an HTTP request with retries and exponential backoff
bool sendHTTPRequestWithRetry(HTTPClient *client, const char *url, const char *apiKey) {
  if (!client || !url || !apiKey) {
    return false;
  }
  CURLcode res;
  int retryCount = client->retryCount;
  bool success = false;
  while (retryCount > 0 && !success) {
    curl_easy_setopt(client->curl, CURLOPT_URL, url);
    curl_easy_setopt(client->curl, CURLOPT_USERPWD, apiKey);
    res = curl_easy_perform(client->curl);
    if (res != CURLE_OK) {
      retryCount--;
      sleep((1 << (retryCount - 1)) * 1000); // Exponential backoff with initial delay of 1 second
      continue;
    } else {
      success = true;
    }
  }
  if (!success) {
    curl_easy_cleanup(client->curl);
    free(client);
  }
  return success;
}

