// Define the structure for a single message
typedef struct {
    time_t timestamp; // Timestamp of the message
    int messageID; // Unique ID of the message
    char* dataPacket; // Payload of the message
} ModemMessage;

// Define the array to store the messages
ModemMessage messages[MAX_MESSAGES];

// Function to add a new message to the array
void addMessage(time_t timestamp, int messageID, char* dataPacket) {
    // Check if the array is full and need to purge expired messages
    if (numMessages >= MAX_MESSAGES) {
        purgeExpiredMessages();
    }

    // Add the new message to the end of the array
    int index = numMessages++;
    messages[index].timestamp = timestamp;
    messages[index].messageID = messageID;
    messages[index].dataPacket = dataPacket;
}

// Function to update an existing message in the array based on MessageID
void updateMessage(int messageID, char* dataPacket) {
    // Find the index of the message with the given ID
    int index = findIndexByMessageID(messageID);

    // Update the payload of the message if found
    if (index != -1) {
        messages[index].dataPacket = dataPacket;
    } else {
        printf("Message with ID %d not found\n", messageID);
    }
}

// Function to retrieve a message from the array based on Timestamp
ModemMessage* getMessageByTimestamp(time_t timestamp) {
    // Find the index of the message with the given timestamp
    int index = findIndexByTimestamp(timestamp);

    if (index != -1) {
        return &messages[index];
    } else {
        return NULL;
    }
}

// Function to purge expired messages from the array based on a configurable time threshold
void purgeExpiredMessages() {
    // Define the time threshold for purging expired messages
    int threshold = 10 * 60 * 1000; // 10 minutes in milliseconds

    // Iterate over the array and remove any messages that are older than the threshold
    int index = 0;
    while (index < numMessages) {
        if (messages[index].timestamp + threshold <= time(NULL)) {
            numMessages--;
            for (int i = index; i < numMessages; i++) {
                messages[i] = messages[i + 1];
            }
        } else {
            index++;
        }
    }
}

// Function to find the index of a message in the array based on its MessageID
int findIndexByMessageID(int messageID) {
    for (int i = 0; i < numMessages; i++) {
        if (messages[i].messageID == messageID) {
            return i;
        }
    }
    return -1;
}

// Function to find the index of a message in the array based on its Timestamp
int findIndexByTimestamp(time_t timestamp) {
    for (int i = 0; i < numMessages; i++) {
        if (messages[i].timestamp == timestamp) {
            return i;
        }
    }
    return -1;
}
