void initNetworkInterfaceConfig(NetworkInterfaceConfig* config) {
    pthread_mutex_lock(&mutex);
    // Initialize the configuration structure with default values
    config->interfaceId = 0;
    config->neighborCellList.clear();
    config->srsParams.reset();
    time(&config->lastUpdateTimestamp);
    pthread_mutex_unlock(&mutex);
}

void addNeighborCell(NetworkInterfaceConfig* config, int neighborId) {
