    // Add the new neighbor cell to the list
    NeighborCellInfo* newCell = new NeighborCellInfo();
    newCell->neighborId = neighborId;
    config->neighborCellList.push(newCell);
    pthread_mutex_unlock(&mutex);
}

void updateSoundingReferenceSignal(NetworkInterfaceConfig* config, SoundingReferenceSignal params) {
    pthread_mutex_lock(&mutex);
    // Update the SRS parameters
    config->srsParams = params;
    time(&config->lastUpdateTimestamp);
    pthread_mutex_unlock(&mutex);
}

void saveNetworkInterfaceConfig(NetworkInterfaceConfig* config) {
    pthread_mutex_lock(&mutex);
    // Serialize the configuration to disk
    if (fd < 0) {
        fd = open("network_interface_config.dat", O_WRONLY | O_CREAT, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    }
    if (fd >= 0) {
        write(fd, config, sizeof(*config));
    } else {
        perror("Failed to open file for writing");
    }
    pthread_mutex_unlock(&mutex);
}

void loadNetworkInterfaceConfig() {
    pthread_mutex_lock(&mutex);
    // Deserialize the configuration from disk
    if (fd < 0) {
        fd = open("network_interface_config.dat", O_RDONLY, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    }
    if (fd >= 0) {
        NetworkInterfaceConfig* config = read(fd, sizeof(*config));
        if (config != NULL) {
            // Update the configuration structure with deserialized values
            pthread_mutex_unlock(&mutex);
            return config;
        } else {
            perror("Failed to read from file");
        }
    } else {
        perror("Failed to open file for reading");
    }
    pthread_mutex_unlock(&mutex);
}

void deinitNetworkInterfaceConfig() {
    pthread_mutex_lock(&mutex);
    // Clean up the configuration structure and close the file descriptor
    if (fd >= 0) {
        close(fd);
        fd = -1;
    }
    delete config;
    pthread_mutex_unlock(&mutex);
}
