};

void init_packet(struct packet *pkt, size_t num) {
    // Initialize Ethernet header
    pkt->eth_hdr.ether_type = htons(ETH_P_IP);

    // Initialize IP header
    pkt->ip_hdr.version = 4;
    pkt->ip_hdr.ihl = 5;
    pkt->ip_hdr.tos = 0;
    pkt->ip_hdr.tot_len = sizeof(struct packet);
    pkt->ip_hdr.id = htons(getpid());
    pkt->ip_hdr.frag_off = htons(IP_DF);
    pkt->ip_hdr.ttl = 64;
    pkt->ip_hdr.protocol = IPPROTO_TCP;

    // Initialize TCP header
    pkt->tcp_hdr.source = rand();
    pkt->tcp_hdr.dest = rand();
    pkt->tcp_hdr.doff = sizeof(struct tcphdr) / 4;
    pkt->tcp_hdr.syn = 1;
    pkt->tcp_hdr.window = htons(8192);
}

int send_packet(struct packet *pkt, size_t num) {
    struct sockaddr_in dest;
    int sockfd, ret;

    // Create a socket for sending packets
    sockfd = socket(AF_INET, SOCK_RAW, IPPROTO_TCP);
    if (sockfd < 0) {
        perror("socket");
        return -1;
    }

    // Set the destination address and port number
    dest.sin_family = AF_INET;
    dest.sin_port = htons(80);
    inet_aton("192.168.0.1", &dest.sin_addr);

    // Send each packet asynchronously using sendto()
    for (size_t i = 0; i < num; i++) {
        ret = sendto(sockfd, pkt + i, sizeof(struct packet), MSG_DONTWAIT,
                     (struct sockaddr *)&dest, sizeof(dest));
        if (ret < 0) {
            perror("sendto");
            return -1;
        }
    }

    // Close the socket after sending all packets
    close(sockfd);

    return 0;
}
