    char *description;
    struct point location;
};

// Function to dynamically allocate and initialize an array of transactions
struct transaction* read_transactions(int n) {
    // Allocate memory for the array of transactions
    struct transaction *transactions = malloc(n * sizeof(struct transaction));

    // Initialize random seed for generating random values within range
    srand(time(NULL));

    // Read transactions from CSV file and parse data
    FILE *fp = fopen("transactions.csv", "r");
    if (fp == NULL) {
        perror("Error opening file");
        return NULL;
    }

    char line[1024];
    int i = 0;
    while (fgets(line, sizeof(line), fp) != NULL && i < n) {
        // Parse transaction data from CSV line
        double value;
        char *description;
        struct point location;
        sscanf(line, "%lf,%[^,]%*c%d,%d", &value, description, &location.x, &location.y);

        // Initialize transaction structure with parsed data
        transactions[i].value = value;
        transactions[i].description = strdup(description);
        transactions[i].location = location;

        // Generate random value within range for transaction
        transactions[i].value *= (rand() % 100) + 1.0;

        i++;
    }

    fclose(fp);

    return transactions;
}
