const asyncReduce = (arr, callback) => {
  return new Promise((resolve, reject) => {
    const reduceFn = (accumulator, currentValue, currentIndex, arr) => {
      // Callback to handle the aggregation operation
      return callback(accumulator, currentValue, currentIndex, arr);
    };

    // Process the array of numbers asynchronously using a custom thread pool
    const threadPool = [];
    for (let i = 0; i < arr.length; i++) {
      threadPool.push(reduceFn(arr[i], i));
    }

    Promise.all(threadPool).then((results) => {
      // Resolve the promise with the aggregated result
      resolve(results);
    }).catch((err) => {
      // Reject the promise with an error message
      reject(new Error(`asyncReduce failed: ${err}`));
    });
  });
};
