// Initialize and populate an array of custom data structures for session states.
void init_session_states(session_state_t **session_states, int num_sessions) {
    *session_states = (session_state_t *)malloc(num_sessions * sizeof(session_state_t));
    if (*session_states == NULL) {
        fprintf(stderr, "Failed to allocate memory for session states: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Initialize each session state with default values.
    for (int i = 0; i < num_sessions; i++) {
        (*session_states)[i].session_id = -1;
        (*session_states)[i].ue_identifier = NULL;
        (*session_states)[i].num_events = 0;
    }
}

// Add a new session state to the array.
void add_session_state(session_state_t **session_states, int num_sessions, const char *ue_identifier) {
    // Check if there is enough memory for the new session state.
    if (num_sessions >= MAX_SESSIONS) {
        fprintf(stderr, "Maximum number of sessions exceeded: %d\n", num_sessions);
        exit(EXIT_FAILURE);
    }

    // Allocate memory for the new session state.
    session_state_t *new_session = (session_state_t *)malloc(sizeof(session_state_t));
    if (new_session == NULL) {
        fprintf(stderr, "Failed to allocate memory for new session state: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Initialize the new session state with default values.
    new_session->session_id = -1;
    new_session->ue_identifier = ue_identifier;
    new_session->num_events = 0;

    // Add the new session state to the array.
    (*session_states)[num_sessions] = new_session;
}

// Remove an existing session state from the array.
void remove_session_state(session_state_t **session_states, int num_sessions, const char *ue_identifier) {
    // Find the index of the session state to be removed.
    int i = 0;
    while (i < num_sessions && strcmp((*session_states)[i].ue_identifier, ue_identifier) != 0) {
        i++;
    }

    // Check if the session state was found.
    if (i == num_sessions) {
        fprintf(stderr, "Session state with UE identifier %s not found\n", ue_identifier);
        exit(EXIT_FAILURE);
    }

    // Remove the session state from the array by shifting all subsequent states left.
    for (int j = i; j < num_sessions - 1; j++) {
        (*session_states)[j] = (*session_states)[j + 1];
    }
    num_sessions--;
}

// Update an existing session state in the array.
void update_session_state(session_state_t **session_states, int num_sessions, const char *ue_identifier) {
    // Find the index of the session state to be updated.
    int i = 0;
    while (i < num_sessions && strcmp((*session_states)[i].ue_identifier, ue_identifier) != 0) {
        i++;
    }

    // Check if the session state was found.
    if (i == num_sessions) {
        fprintf(stderr, "Session state with UE identifier %s not found\n", ue_identifier);
        exit(EXIT_FAILURE);
    }

    // Update the session state in the array.
    (*session_states)[i].num_events++;
}

// Serialize an array of custom data structures into a binary format for persistent storage.
void serialize_session_states(const session_state_t *session_states, int num_sessions, FILE *out) {
    // Write the number of sessions to the file.
    fwrite(&num_sessions, sizeof(int), 1, out);

    // Serialize each session state.
    for (int i = 0; i < num_sessions; i++) {
        // Write the session ID and UE identifier to the file.
        int session_id = (*session_states)[i].session_id;
        fwrite(&session_id, sizeof(int), 1, out);
        char *ue_identifier = (*session_states)[i].ue_identifier;
        fwrite(ue_identifier, strlen(ue_identifier) + 1, 1, out);

        // Write the number of associated network events to the file.
        int num_events = (*session_states)[i].num_events;
        fwrite(&num_events, sizeof(int), 1, out);

        // Serialize each network event.
        for (int j = 0; j < num_events; j++) {
            int type = (*session_states)[i].events[j].type;
            fwrite(&type, sizeof(int), 1, out);
            int timestamp = (*session_states)[i].events[j].timestamp;
            fwrite(&timestamp, sizeof(int), 1, out);
        }

        // Write the QoS parameters to the file.
        qos_params_t qos_params = (*session_states)[i].qos_params;
        fwrite(&qos_params.max_bandwidth, sizeof(int), 1, out);
        fwrite(&qos_params.min_latency, sizeof(int), 1, out);
    }
}

// Deserialize an array of custom data structures from a binary format for persistent storage.
void deserialize_session_states(session_state_t **session_states, FILE *in) {
    // Read the number of sessions from the file.
    int num_sessions;
    fread(&num_sessions, sizeof(int), 1, in);

    // Initialize an array for storing the deserialized session states.
    (*session_states) = malloc(sizeof(session_state_t) * num_sessions);

    // Deserialize each session state.
    for (int i = 0; i < num_sessions; i++) {
        // Read the session ID and UE identifier from the file.
        int session_id;
        fread(&session_id, sizeof(int), 1, in);
        char ue_identifier[1024];
        fread(ue_identifier, strlen(ue_identifier) + 1, 1, in);

        // Read the number of associated network events from the file.
        int num_events;
        fread(&num_events, sizeof(int), 1, in);

        // Initialize an array for storing the deserialized network events.
        (*session_states)[i].events = malloc(sizeof(event_t) * num_events);

        // Deserialize each network event.
        for (int j = 0; j < num_events; j++) {
            int type;
            fread(&type, sizeof(int), 1, in);
            int timestamp;
            fread(&timestamp, sizeof(int), 1, in);
            (*session_states)[i].events[j].type = type;
            (*session_states)[i].events[j].timestamp = timestamp;
        }

        // Read the QoS parameters from the file.
        qos_params_t qos_params;
        fread(&qos_params.max_bandwidth, sizeof(int), 1, in);
        fread(&qos_params.min_latency, sizeof(int), 1, in);

        // Set the session ID and UE identifier for the deserialized session state.
        (*session_states)[i].session_id = session_id;
        strcpy((*session_states)[i].ue_identifier, ue_identifier);
    }
}

// Print an array of custom data structures to the console.
void print_session_states(const session_state_t *session_states, int num_sessions) {
    for (int i = 0; i < num_sessions; i++) {
        printf("Session state with UE identifier %s\n", (*session_states)[i].ue_identifier);
        printf("\tSession ID: %d\n", (*session_states)[i].session_id);
        printf("\tNumber of associated network events: %d\n", (*session_states)[i].num_events);
        for (int j = 0; j < (*session_states)[i].num_events; j++) {
            printf("\tNetwork event %d:\n", j + 1);
            printf("\t\ttype: %d\n", (*session_states)[i].events[j].type);
            printf("\t\ttimestamp: %d\n", (*session_states)[i].events[j].timestamp);
        }
        printf("\tQoS parameters:\n");
        printf("\t\tMaximum bandwidth: %d\n", (*session_states)[i].qos_params.max_bandwidth);
        printf("\t\tMinimum latency: %d\n", (*session_states)[i].qos_params.min_latency);
    }
}

int main() {
    // Initialize an array for storing the session states.
    session_state_t *session_states = NULL;
    int num_sessions = 0;

    // Add a new session state to the array.
    add_session_state(session_states, &num_sessions, "UE1");
    printf("Session states:\n");
    print_session_states(session_states, num_sessions);

    // Update an existing session state in the array.
    update_session_state(session_states, num_sessions, "UE1");
    printf("\nUpdated session states:\n");
    print_session_states(session_states, num_sessions);

    // Remove an existing session state from the array.
    remove_session_state(session_states, num_sessions, "UE1");
    printf("\nSession states after removing UE1:\n");
    print_session_states(session_states, num_sessions);

    // Add a new session state to the array.
    add_session_state(session_states, &num_sessions, "UE2");
    printf("\nSession states after adding UE2:\n");
    print_session_states(session_states, num_sessions);

    // Serialize and deserialize the session states.
    serialize_session_states(session_states, num_sessions, "serialized_session_states.txt");
    deserialize_session_states(&session_states, &num_sessions, "serialized_session_states.txt");
    printf("\nDeserialized session states:\n");
    print_session_states(session_states, num_sessions);

    // Clean up the memory.
    free(session_states);

    return 0;
}
