// Function to initialize a dynamic array of NetworkInterfaceConfig structures
void initNetworkInterfaces(NetworkInterfaceConfig* interfaces, int numInterfaces) {
    // Initialize the neighbor cell list with the specified number of entries
    for (int i = 0; i < numInterfaces; i++) {
        interfaces[i].interfaceId = i;
        interfaces[i].neighborCellList = malloc(sizeof(NeighborCellInfo) * MAX_NEIGHBOR_CELLS);
        for (int j = 0; j < MAX_NEIGHBOR_CELLS; j++) {
            interfaces[i].neighborCellList[j].neighborId = i + 1; // unique neighbor ID
            interfaces[i].neighborCellList[j].rssi = generateRssiValue(); // random RSSI value between -90 and -120 dBm
        }
    }
}

// Function to add multiple NetworkInterfaceConfig instances into a global data structure
void addNetworkInterfaces(NetworkInterfaceConfig* interfaces, int numInterfaces) {
    pthread_mutex_lock(&interfaceLock); // acquire interface lock for thread-safe access
    for (int i = 0; i < numInterfaces; i++) {
        // Check if the interface configuration already exists in the global structure
        bool found = false;
        for (int j = 0; j < MAX_INTERFACES && !found; j++) {
            if (interfaces[i].interfaceId == interfaces[j].interfaceId) {
                found = true;
            }
        }
        // Add the interface configuration to the global structure if it does not exist
        if (!found) {
            memcpy(&interfaceList[interfaceCount], &interfaces[i], sizeof(NetworkInterfaceConfig));
            interfaceCount++;
        }
    }
    pthread_mutex_unlock(&interfaceLock); // release interface lock
}

// Function to generate a random RSSI value between -90 and -120 dBm
int generateRssiValue() {
    return rand() % 30 - 90; // random number between -90 and -120 dBm
}

// Global structure to store the network interface configurations
struct NetworkInterfaceConfig {
    int interfaceId; // unique interface ID
    NeighborCellInfo* neighborCellList; // list of neighboring cell information
    SRSParameters srsParams; // configuration for SRS parameters
};

// Structure to store neighboring cell information
struct NeighborCellInfo {
    int neighborId; // unique neighbor ID
    int rssi; // received signal strength indicator (RSSI) value
};

// Structure to store SRS parameters configuration
struct SRSParameters {
    int srsBandwidth; // bandwidth for SRS transmission
    int srsSubcarrierSpacing; // subcarrier spacing for SRS transmission
};

// Global data structure to store the network interface configurations
NetworkInterfaceConfig* interfaceList = malloc(sizeof(NetworkInterfaceConfig) * MAX_INTERFACES);
int interfaceCount = 0;
pthread_mutex_t interfaceLock; // mutex lock for thread-safe access to the interface list

// Function to release all allocated memory when the dynamic array is deallocated
void freeNetworkInterfaces(NetworkInterfaceConfig* interfaces) {
    pthread_mutex_lock(&interfaceLock); // acquire interface lock for thread-safe access
    for (int i = 0; i < interfaceCount; i++) {
        free(interfaces[i].neighborCellList);
    }
    pthread_mutex_unlock(&interfaceLock); // release interface lock
}

// Function to validate the input parameters for the function
void validateInputParameters(NetworkInterfaceConfig* interfaces, int numInterfaces) {
    if (numInterfaces < 0 || numInterfaces > MAX_INTERFACES) {
        fprintf(stderr, "Error: Invalid number of network interface configurations\n");
        return;
    }
    for (int i = 0; i < numInterfaces; i++) {
        if (interfaces[i].interfaceId < 0 || interfaces[i].interfaceId >= MAX_INTERFACES) {
            fprintf(stderr, "Error: Invalid interface ID\n");
            return;
        }
    }
}

// Function to optimize the memory allocation strategy for the neighbor cell list
void optimizeNeighborCellAllocation(NetworkInterfaceConfig* interfaces, int numInterfaces) {
    for (int i = 0; i < numInterfaces; i++) {
        // Check if the neighbor cell list needs to be optimized
        if (interfaces[i].neighborCellList == NULL) {
            continue;
        }
        // Optimize the memory allocation strategy for the neighbor cell list
        int newSize = interfaces[i].neighborCellCount * 2;
        NeighborCellInfo* newNeighborCellList = realloc(interfaces[i].neighborCellList, sizeof(NeighborCellInfo) * newSize);
        if (newNeighborCellList != NULL) {
            interfaces[i].neighborCellList = newNeighborCellList;
            interfaces[i].neighborCellCount = newSize;
        } else {
            fprintf(stderr, "Error: Failed to allocate memory for neighbor cell list\n");
        }
    }
}

