        // Check if the SRS parameters configuration needs to be optimized
        if (interfaces[i].srsParams == NULL) {
            continue;
        }
        // Optimize the memory allocation strategy for the SRS parameters configuration
        int newSize = interfaces[i].neighborCellCount * 2;
        SRSParameters* newSRSParamsList = realloc(interfaces[i].srsParams, sizeof(SRSParameters) * newSize);
        if (newSRSParamsList != NULL) {
            interfaces[i].srsParams = newSRSParamsList;
            interfaces[i].neighborCellCount = newSize;
        } else {
            fprintf(stderr, "Error: Failed to allocate memory for SRS parameters configuration\n");
        }
    }
