Python function:
```python
import requests
import json

# Define a dictionary to store the network configurations
network_configs = {}

def fetch_updates():
    # Fetch the latest network configuration updates from a remote server
    response = requests.get('https://example.com/network_configs')
    if response.status_code == 200:
        # Parse the JSON response and add the configurations to the dictionary
        configs = json.loads(response.text)
        for config in configs:
            network_configs[config['id']] = config
    else:
        print('Error fetching network configuration updates')

def add_update(id, ip_addr, subnet_mask):
    # Add a new configuration update to the dictionary
    network_configs[id] = { 'ip_addr': ip_addr, 'subnet_mask': subnet_mask }

def update_update(id, ip_addr, subnet_mask):
    # Update an existing configuration update in the dictionary
    if id in network_configs:
        network_configs[id]['ip_addr'] = ip_addr
        network_configs[id]['subnet_mask'] = subnet_mask
    else:
        print('Error: Configuration with ID %d not found' % id)

def delete_update(id):
    # Delete a configuration update from the dictionary
    if id in network_configs:
        del network_configs[id]
    else:
        print('Error: Configuration with ID %d not found' % id)
