// Function to dynamically create and populate a linked list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* createAndPopulateLinkedList(int N, int RX_UE_INFORMATION_TAG, int CRC_INDICATION_REL8_TAG) {
    // Allocate memory for the linked list structure
    LinkedListNode *list = malloc(sizeof(LinkedListNode));

    // Initialize the head node of the linked list to NULL
    list->next = NULL;

    // Iterate through the input parameters and create a new node in the linked list for each set of data
    for (int i = 0; i < N; i++) {
        // Allocate memory for the current node
        LinkedListNode *current = malloc(sizeof(LinkedListNode));

        // Set the RX_UE_INFORMATION_TAG and CRC_INDICATION_REL8_TAG of the current node to the input parameters
        current->data.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        current->data.CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;

        // Generate a random RNTI value for the current node
        current->data.RNTI = rand() % 10000;

        // Check if the current node's RNTI value is already present in the linked list
