#define MAX_ARRAY_SIZE 100000
#define MIN_RX_UE_INFO_TAG 1
#define MAX_RX_UE_INFO_TAG 100000
#define MIN_RNTI 1
#define MAX_RNTI 65535
#define MIN_CRC_INDICATION_REL8_TAG 1
#define MAX_CRC_INDICATION_REL8_TAG 255
#define RESIZE_FACTOR 1.5
#define DEFAULT_ARRAY_SIZE 1000
#define CONNECTION_TIMEOUT 30
#define NETWORK_LATENCY 50

// Structure to store information about a single UE's RX information
typedef struct {
    int rx_ue_info_tag;
    int rnti;
    char crc_indication_rel8_tag;
} rx_ue_information_t;

// Structure to store a list of UE RX information
typedef struct {
    int num_uplink_info;
    rx_ue_information_t *rx_ue_info_array;
} uplink_information_list_t;

// Structure to store information about the connection health
typedef struct {
    time_t last_update;
    int num_failed_attempts;
} connection_health_t;

// Function to establish and maintain a robust asynchronous connection to a remote server
void establish_connection(uplink_information_list_t *uplink_info_list, connection_health_t *conn_health) {
    int num_threads = 2; // Number of threads for concurrent access to the connection
    pthread_mutex_t conn_lock; // Lock for synchronizing access to the connection
    pthread_cond_t conn_cond; // Condition variable for notifying when the connection is established or fails
    int *conn_established = malloc(sizeof(int)); // Flag indicating whether the connection has been established
    *conn_established = 0; // Initialize the flag to false

    // Initialize the list of UE RX information
    uplink_info_list->num_uplink_info = DEFAULT_ARRAY_SIZE;
    uplink_info_list->rx_ue_info_array = malloc(sizeof(rx_ue_information_t) * uplink_info_list->num_uplink_info);

    // Initialize the connection health information
    conn_health->last_update = time(NULL);
    conn_health->num_failed_attempts = 0;

    // Create a new thread to establish the connection
    pthread_t connect_thread;
    if (pthread_create(&connect_thread, NULL, connect_to_server, uplink_info_list) != 0) {
        fprintf(stderr, "Failed to create connect thread\n");
        exit(1);
    }

    // Create a new thread to monitor the connection health
    pthread_t health_monitor_thread;
    if (pthread_create(&health_monitor_thread, NULL, monitor_connection_health, conn_health) != 0) {
        fprintf(stderr, "Failed to create health monitor thread\n");
        exit(1);
    }

    // Wait for the connection to be established or failed
    pthread_mutex_lock(&conn_lock);
    while (!*conn_established) {
        pthread_cond_wait(&conn_cond, &conn_lock);
    }
    pthread_mutex_unlock(&conn_lock);

    // Destroy the connect and health monitor threads
    if (pthread_join(connect_thread, NULL) != 0) {
        fprintf(stderr, "Failed to join connect thread\n");
        exit(1);
    }
    if (pthread_join(health_monitor_thread, NULL) != 0) {
        fprintf(stderr, "Failed to join health monitor thread\n");
        exit(1);
    }
}

// Function to establish a connection with the remote server
void *connect_to_server(void *args) {
    uplink_information_list_t *uplink_info_list = (uplink_information_list_t *) args;

    // Establish a connection with the remote server
    int socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd == -1) {
        fprintf(stderr, "Failed to create socket\n");
        return NULL;
    }

    // Set up the connection to the remote server
    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(12345);
    if (connect(socket_fd, (struct sockaddr *) &server_addr, sizeof(server_addr)) == -1) {
        fprintf(stderr, "Failed to connect to server\n");
        close(socket_fd);
        return NULL;
    }

    // Set up the connection health information
    time_t current_time = time(NULL);
    connection_health_t conn_health;
    conn_health.last_update = current_time;
    conn_health.num_failed_attempts = 0;

    // Initialize the lock and condition variable for synchronizing access to the connection
    pthread_mutex_t conn_lock;
    pthread_cond_t conn_cond;
    if (pthread_mutex_init(&conn_lock, NULL) != 0) {
        fprintf(stderr, "Failed to initialize connection lock\n");
        close(socket_fd);
        return NULL;
    }
    if (pthread_cond_init(&conn_cond, NULL) != 0) {
        fprintf(stderr, "Failed to initialize connection condition variable\n");
        pthread_mutex_destroy(&conn_lock);
        close(socket_fd);
        return NULL;
    }

    // Set up the connection timeout
    struct timeval conn_timeout;
    conn_timeout.tv_sec = CONNECTION_TIMEOUT;
    conn_timeout.tv_usec = 0;
    setsockopt(socket_fd, SOL_SOCKET, SO_RCVTIMEO, &conn_timeout, sizeof(conn_timeout));

    // Loop until the connection is closed or fails
    int *conn_established = malloc(sizeof(int));
    *conn_established = 1;
    while (*conn_established) {
        // Check for any incoming messages from the remote server
        struct timeval rcv_timeout;
        rcv_timeout.tv_sec = RCV_TIMEOUT;
        rcv_timeout.tv_usec = 0;
        setsockopt(socket_fd, SOL_SOCKET, SO_RCVTIMEO, &rcv_timeout, sizeof(rcv_timeout));
        char buffer[256];
        if (recv(socket_fd, buffer, sizeof(buffer), 0) > 0) {
            // Update the connection health information
            current_time = time(NULL);
            conn_health.last_update = current_time;
            conn_health.num_failed_attempts = 0;
        } else if (recv(socket_fd, buffer, sizeof(buffer), 0) == -1 && errno != EAGAIN) {
            // Close the connection if an error occurs
            *conn_established = 0;
            close(socket_fd);
        } else if (current_time - conn_health.last_update > CONNECTION_TIMEOUT) {
            // Check for a timeout in the connection
            fprintf(stderr, "Connection timed out\n");
            *conn_established = 0;
            close(socket_fd);
        } else if (current_time - conn_health.last_update > RCV_TIMEOUT) {
            // Check for a timeout in receiving data from the remote server
            fprintf(stderr, "Timed out waiting for data from server\n");
            *conn_established = 0;
            close(socket_fd);
        }
    }

    // Destroy the lock and condition variable for synchronizing access to the connection
    pthread_mutex_destroy(&conn_lock);
    pthread_cond_destroy(&conn_cond);

    // Close the socket
    close(socket_fd);

    return NULL;
}

// Function to monitor the connection health
void *monitor_connection_health(void *args) {
    connection_health_t *conn_health = (connection_health_t *) args;

    // Loop until the connection is closed or fails
    while (*conn_established) {
        // Check for a timeout in the connection
        if (current_time - conn_health->last_update > CONNECTION_TIMEOUT) {
            fprintf(stderr, "Connection timed out\n");
            *conn_established = 0;
            close(socket_fd);
        }
    }

    return NULL;
}
```

