            destroy_set(rnti_set);
            return false;
        } else {
            add_element_to_set(list[i].rnti, rnti_set);
        }
    }

    // If no duplicates are found, return true and free the set
    destroy_set(rnti_set);
    return true;
}

// Function to create a set data structure for storing RNTIs
struct set *create_set() {
    struct set *s = malloc(sizeof(*s));
    s->size = 0;
    s->capacity = 16;
    s->elements = malloc(s->capacity * sizeof(*(s->elements)));
    return s;
}

// Function to add an element to a set
void add_element_to_set(uint16_t element, struct set *s) {
    if (s->size == s->capacity) {
        // If the set is full, double its capacity and reallocate memory for the elements array
        s->capacity *= 2;
        s->elements = realloc(s->elements, s->capacity * sizeof(*(s->elements)));
    }
    s->elements[s->size++] = element;
}

// Function to check if an element is in a set
bool is_element_in_set(uint16_t element, struct set *s) {
    for (int i = 0; i < s->size; i++) {
        if (s->elements[i] == element) {
            return true;
        }
    }
    return false;
}

// Function to destroy a set data structure
void destroy_set(struct set *s) {
    free(s->elements);
    free(s);
}

