    uint32_t num_ues;
    nas_message_t *nas_messages;
    rach_information_t **rach_infos;
    crc_indication_t **crc_inds;
} nas_collection_t;

// Define functions for adding, updating, and querying NAS messages
void add_ue(nas_collection_t *col, uint32_t ue_id) {
    // Check if UE ID is already in the collection
    bool found = false;
    for (int i = 0; i < col->num_ues; i++) {
        if (col->nas_messages[i].ue_id == ue_id) {
            found = true;
            break;
        }
    }

    // If UE ID is not in the collection, add a new NAS message and RACH information structure
    if (!found) {
        col->num_ues++;
        col->nas_messages = realloc(col->nas_messages, col->num_ues * sizeof(nas_message_t));
        col->nas_messages[col->num_ues - 1].ue_id = ue_id;
        col->nas_messages[col->num_ues - 1].nas_message_type = -1; // Initialize NAS message type to unknown
        col->rach_infos = realloc(col->rach_infos, col->num_ues * sizeof(rach_information_t*));
        col->rach_infos[col->num_ues - 1] = malloc(sizeof(rach_information_t));
        col->crc_inds = realloc(col->crc_inds, col->num_ues * sizeof(crc_indication_t*));
        col->crc_inds[col->num_ues - 1] = malloc(sizeof(crc_indication_t));
    }
}

void update_ue(nas_collection_t *col, uint32_t ue_id) {
    // Check if UE ID is in the collection
    bool found = false;
    for (int i = 0; i < col->num_ues; i++) {
        if (col->nas_messages[i].ue_id == ue_id) {
            found = true;
            break;
        }
    }

    // If UE ID is in the collection, update the NAS message type
    if (found) {
        col->nas_messages[i].nas_message_type++;
    }
}

uint16_t query_rach(nas_collection_t *col, uint32_t ue_id) {
    // Check if UE ID is in the collection
    bool found = false;
    for (int i = 0; i < col->num_ues; i++) {
        if (col->nas_messages[i].ue_id == ue_id) {
            found = true;
            break;
        }
    }

    // If UE ID is in the collection, return the latest RACH sequence
    uint16_t rach_sequence = 0;
    if (found) {
        for (int i = 0; i < col->num_ues; i++) {
            if (col->nas_messages[i].ue_id == ue_id) {
                rach_sequence = col->rach_infos[i]->sequence;
            }
        }
    }
    return rach_sequence;
}

// Define a function for handling CRC errors and updating the RACH information structure
void handle_crc_error(nas_collection_t *col, uint32_t ue_id) {
    // Check if UE ID is in the collection
    bool found = false;
    for (int i = 0; i < col->num_ues; i++) {
        if (col->nas_messages[i].ue_id == ue_id) {
            found = true;
            break;
        }
    }

    // If UE ID is in the collection, update the CRC indication structure
    if (found) {
        col->crc_inds[i]->error_checking_flag = true;
    }
}

// Define a function for cleaning up and freeing memory when the NAS message collection is no longer needed
void nas_collection_free(nas_collection_t *col) {
    // Free dynamically allocated memory for NAS messages, RACH information structures, and CRC indications
    for (int i = 0; i < col->num_ues; i++) {
        free(col->rach_infos[i]);
        free(col->crc_inds[i]);
    }
    free(col->nas_messages);
    free(col->rach_infos);
    free(col->crc_inds);
}
