// Structure to store file information
typedef struct {
    char *path;
    char *name;
    time_t mtime;
    size_t size;
} file_info_t;

// Function to compress and archive a directory
int compress_archive(char *input_dir, char *output_dir) {
    // Check if input and output directories are valid
    if (input_dir == NULL || output_dir == NULL) {
        return -1;
    }

    // Initialize list of file information structures
    file_info_t *files = NULL;

    // Open the directory specified by the input argument
    DIR *dir = opendir(input_dir);
    if (dir == NULL) {
        return -1;
    }

    // Read the directory entries and store file information in a list
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        char *file_path = entry->d_name;
        if (strcmp(file_path, ".") == 0 || strcmp(file_path, "..") == 0) {
            continue;
        }

        // Stat the file to get its metadata
        struct stat file_stats;
        if (stat(file_path, &file_stats) != 0) {
            closedir(dir);
            return -1;
        }

        // Check if the file is a regular file or directory and skip it if necessary
        if (!S_ISREG(file_stats.st_mode)) {
            continue;
        }

        // Allocate memory for the file information structure
        file_info_t *new_file = malloc(sizeof(file_info_t));
        if (new_file == NULL) {
            closedir(dir);
            return -1;
        }

        // Populate the file information structure with the file's metadata and path
        new_file->path = strdup(input_dir);
        new_file->name = strdup(file_path);
        new_file->mtime = file_stats.st_mtim.tv_sec;
        new_file->size = file_stats.st_size;

        // Add the structure to the list of files
        files = realloc(files, (num_files + 1) * sizeof(file_info_t));
        if (files == NULL) {
            free(new_file->path);
            free(new_file->name);
            free(new_file);
            closedir(dir);
            return -1;
        }

        files[num_files] = new_file;
        num_files++;
    }

    // Close the directory stream
    closedir(dir);

    // Compress and archive each file in the list using zlib library
    char *compressed_data = NULL;
    size_t compressed_size = 0;
    for (int i = 0; i < num_files; i++) {
        FILE *file = fopen(files[i]->path, "rb");
        if (file == NULL) {
            continue;
        }

        // Read the file contents into a buffer
        char *file_buffer = malloc(files[i]->size);
        size_t num_read = fread(file_buffer, 1, files[i]->size, file);
        if (num_read != files[i]->size) {
            free(file_buffer);
            continue;
        }

        // Compress the file contents using zlib library
        unsigned long compressed_len = compressBound(files[i]->size);
        compressed_data = malloc(compressed_len);
        if (compressed_data == NULL) {
            free(file_buffer);
            continue;
        }

        int status = compress(compressed_data, &compressed_len, file_buffer, files[i]->size);
        if (status != Z_OK) {
            free(compressed_data);
            free(file_buffer);
            continue;
        }

        // Archive the compressed data using tar format
        char archive_name[256];
        snprintf(archive_name, sizeof(archive_name), "%s/%s.tar", output_dir, files[i]->name);

        FILE *archive = fopen(archive_name, "wb");
        if (archive == NULL) {
            free(compressed_data);
            free(file_buffer);
            continue;
        }

        // Write the compressed data to the archive file
        size_t num_written = fwrite(compressed_data, 1, compressed_len, archive);
        if (num_written != compressed_len) {
            free(compressed_data);
            free(file_buffer);
            continue;
        }

        // Close the file stream and free memory
        fclose(archive);
        free(compressed_data);
