void initSessionManager(struct SessionManager *manager) {
    manager->numSessions = 0;
    manager->lastActiveTimestamp = 0;
}

int addSession(struct SessionManager *manager, int sessionID, char* UEIdentifier) {
    if (manager->numSessions == MAX_SESSIONS) {
        return -1; // maximum number of sessions reached
    }

    Session *newSession = malloc(sizeof(Session));
    newSession->sessionID = sessionID;
    newSession->UEIdentifier = UEIdentifier;
    newSession->lastActiveTimestamp = 0;
    newSession->events = NULL;

    manager->sessions[manager->numSessions++] = newSession;
    return 0;
}

void removeSession(struct SessionManager *manager, int sessionID) {
    for (int i = 0; i < manager->numSessions; i++) {
        if (manager->sessions[i]->sessionID == sessionID) {
            free(manager->sessions[i]);
            manager->numSessions--;
            return;
        }
    }
}

void updateSessionActivity(struct SessionManager *manager, int sessionID) {
    for (int i = 0; i < manager->numSessions; i++) {
        if (manager->sessions[i]->sessionID == sessionID) {
            manager->sessions[i]->lastActiveTimestamp = time(NULL);
            return;
        }
    }
}

void addEventToSession(struct SessionManager *manager, int sessionID, int eventType, char* eventData) {
    for (int i = 0; i < manager->numSessions; i++) {
        if (manager->sessions[i]->sessionID == sessionID) {
            Event *newEvent = malloc(sizeof(Event));
            newEvent->eventType = eventType;
            newEvent->eventData = eventData;
            newEvent->next = manager->sessions[i]->events;
            manager->sessions[i]->events = newEvent;
            return;
        }
    }
}

void serializeSessions(struct SessionManager *manager, char* buffer) {
    for (int i = 0; i < manager->numSessions; i++) {
        Session *session = manager->sessions[i];
        int offset = 0;

        // session ID
