        offset += sizeof(unsigned long);

        // event list length
        int eventsLength = 0;
        Event *events = session->events;
        while (events != NULL) {
            eventsLength++;
            events = events->next;
        }
        memcpy(buffer + offset, &eventsLength, sizeof(int));
        offset += sizeof(int);

        // event list
