        while (events != NULL) {
            memcpy(buffer + offset, &events->eventType, sizeof(int));
            offset += sizeof(int);

            int eventDataLength = strlen(events->eventData) + 1;
            memcpy(buffer + offset, &eventDataLength, sizeof(int));
            offset += sizeof(int);

            memcpy(buffer + offset, events->eventData, eventDataLength);
            offset += eventDataLength;

            events = events->next;
        }
    }
}

