    nfapi_crc_indication_pdu_t *data = head->data;
    free(head);

    // Unlock the mutex after modifying the list
    pthread_mutex_unlock(&lock);

    return data;
}

// Function to retrieve an element from the linked list by index
nfapi_crc_indication_pdu_t *nfapi_crc_indication_get(nfapi_crc_indication_list_t *list, int index) {
    // Lock the mutex before modifying the list
    pthread_mutex_lock(&lock);

    // If the list is empty or the index is out of bounds, return NULL
    if (list->head == NULL || index < 0 || index >= nfapi_crc_indication_list_length(list)) {
        nfapi_crc_indication_pdu_t *data = NULL;
        pthread_mutex_unlock(&lock);
        return data;
    }

    // Otherwise, iterate through the list to find the node at the specified index
    int current_index = 0;
    nfapi_crc_indication_list_node_t *current_node = list->head;
    while (current_index < index) {
        current_node = current_node->next;
        current_index++;
    }

    // Return the data from the node at the specified index
    nfapi_crc_indication_pdu_t *data = current_node->data;

    // Unlock the mutex after modifying the list
    pthread_mutex_unlock(&lock);

    return data;
