// Function to retrieve the length of the linked list
int nfapi_crc_indication_list_length(nfapi_crc_indication_list_t *list) {
    // Lock the mutex before modifying the list
    pthread_mutex_lock(&lock);

    // If the list is empty, return 0
    if (list->head == NULL) {
        int length = 0;
        pthread_mutex_unlock(&lock);
        return length;
    }

    // Otherwise, iterate through the list to find the last node and return its index + 1
    nfapi_crc_indication_list_node_t *last_node = list->tail;
    int length = 0;
    while (last_node != NULL) {
        length++;
        last_node = last_node->next;
    }

