    nfapi_crc_indication_list_node_t *current_node = list->head;
    while (current_node != NULL) {
        nfapi_crc_indication_list_node_t *next_node = current_node->next;
        free(current_node->data);
        free(current_node);
        current_node = next_node;
    }

