// C-based communication module that manages a dynamically sized buffer of NFAPI_CRC_INDICATION_PDU_T structures
#include <stdbool.h>
#include <pthread.h>
#include <semaphore.h>

#define BUFFER_SIZE 10000 // maximum size of the buffer (in number of elements)
#define PRIORITY_LEVELS 3 // number of priority levels (from highest to lowest)

// struct for storing received packets in the buffer
typedef struct {
    uint8_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// struct for storing packet prioritization rules
typedef struct {
    uint8_t priority_level; // priority level (from highest to lowest)
    uint16_t RNTI; // RNTI value associated with the priority level
} PRIORITY_RULE_T;

// buffer of received packets
NFAPI_CRC_INDICATION_PDU_T *buffer = NULL;

// mutex for synchronizing access to the buffer
pthread_mutex_t mutex;

// semaphore for signaling available slots in the buffer
sem_t sem;

// priority rules for determining packet priority
PRIORITY_RULE_T *priority_rules = NULL;

// number of priority levels (from highest to lowest)
uint8_t num_priority_levels = 0;

// current size of the buffer (in number of elements)
uint16_t buffer_size = BUFFER_SIZE;

// number of elements in the buffer
uint16_t num_elements = 0;

// function for inserting a new packet into the buffer
void insert(NFAPI_CRC_INDICATION_PDU_T *packet) {
    // lock the mutex
    pthread_mutex_lock(&mutex);

    // check if the buffer is full
    while (num_elements == buffer_size) {
        // wait for a slot to become available in the buffer
        sem_wait(&sem);
    }

    // insert the packet into the buffer
    buffer[num_elements++] = *packet;

    // unlock the mutex
    pthread_mutex_unlock(&mutex);
}

// function for removing a packet from the buffer
void remove(NFAPI_CRC_INDICATION_PDU_T *packet) {
    // lock the mutex
    pthread_mutex_lock(&mutex);

    // check if the buffer is empty
    if (num_elements == 0) {
        // unlock the mutex and return
        pthread_mutex_unlock(&mutex);
        return;
    }

    // remove the head of the buffer
    *packet = buffer[0];

    // shift all remaining packets in the buffer up by one position
    for (uint16_t i = 0; i < num_elements - 1; i++) {
        buffer[i] = buffer[i + 1];
    }

    // decrement the number of elements in the buffer
    num_elements--;

    // signal that a slot has become available in the buffer
    sem_post(&sem);

    // unlock the mutex
    pthread_mutex_unlock(&mutex);
}

// function for iterating over all packets in the buffer
void iterate(packet_callback callback) {
    // lock the mutex
    pthread_mutex_lock(&mutex);

    // check if the buffer is empty
    if (num_elements == 0) {
        // unlock the mutex and return
        pthread_mutex_unlock(&mutex);
        return;
    }

    // iterate over all packets in the buffer
    for (uint16_t i = 0; i < num_elements; i++) {
        callback(&buffer[i]);
    }

    // unlock the mutex
    pthread_mutex_unlock(&mutex);
}

// function for updating packet prioritization rules
void update_priority_rules(PRIORITY_RULE_T *new_rules, uint8_t num_rules) {
    // lock the mutex
    pthread_mutex_lock(&mutex);

    // check if the new priority rules are valid
    for (uint8_t i = 0; i < num_rules; i++) {
        if (new_rules[i].priority_level >= PRIORITY_LEVELS) {
            // unlock the mutex and return an error
            pthread_mutex_unlock(&mutex);
            return;
        }
    }

    // update the priority rules
    num_priority_levels = num_rules;
    for (uint8_t i = 0; i < num_rules; i++) {
        priority_rules[i] = new_rules[i];
    }

    // unlock the mutex
    pthread_mutex_unlock(&mutex);
}

// function for getting the current size of the buffer (in number of elements)
uint16_t get_size() {
    // lock the mutex
    pthread_mutex_lock(&mutex);

    // get the current size of the buffer
    uint16_t size = num_elements;

    // unlock the mutex
    pthread_mutex_unlock(&mutex);

    return size;
}

// function for getting the current number of priority levels
uint8_t get_num_priority_levels() {
    // lock the mutex
    pthread_mutex_lock(&mutex);

    // get the current number of priority levels
    uint8_t num = num_priority_levels;

    // unlock the mutex
    pthread_mutex_unlock(&mutex);

    return num;
}

// function for getting the current priority rules
void get_priority_rules(PRIORITY_RULE_T *rules) {
    // lock the mutex
    pthread_mutex_lock(&mutex);

    // check if the buffer is empty
    if (num_elements == 0) {
        // unlock the mutex and return an error
        pthread_mutex_unlock(&mutex);
        return;
    }

    // get the current priority rules
    for (uint8_t i = 0; i < num_priority_levels; i++) {
        rules[i] = priority_rules[i];
    }

    // unlock the mutex
    pthread_mutex_unlock(&mutex);
}

// function for getting a specific packet from the buffer
void get_packet(uint16_t index, NFAPI_PACKET *packet) {
    // lock the mutex
    pthread_mutex_lock(&mutex);

    // check if the buffer is empty
    if (num_elements == 0) {
        // unlock the mutex and return an error
        pthread_mutex_unlock(&mutex);
        return;
    }

    // get the specific packet from the buffer
    *packet = buffer[index];

    // unlock the mutex
    pthread_mutex_unlock(&mutex);
}

// function for updating a specific packet in the buffer
void update_packet(uint16_t index, NFAPI_PACKET *new_packet) {
    // lock the mutex
    pthread_mutex_lock(&mutex);

    // check if the buffer is empty
    if (num_elements == 0) {
        // unlock the mutex and return an error
        pthread_mutex_unlock(&mutex);
        return;
    }

    // update the specific packet in the buffer
    buffer[index] = *new_packet;

    // unlock the mutex
    pthread_mutex_unlock(&mutex);
}']

