    void* TAG_NSA_DEACTIVATION_INDICATION_REL15_TAG;
} NFAPI_RX_PDU_T;

// Define list for storing NFAPI_RX_PDU_T structures
typedef struct {
    NFAPI_RX_PDU_T* data;
    size_t size;
} NFAPI_RX_PDU_LIST;

// Initialize and populate a list of NFAPI_RX_PDU_T structures
void init_nfapi_rx_pdu_list(NFAPI_RX_PDU_LIST* list, size_t capacity) {
    list->data = (NFAPI_RX_PDU_T*) malloc(capacity * sizeof(NFAPI_RX_PDU_T));
    list->size = 0;
}

// Add a new NFAPI_RX_PDU_T structure to the list
void add_nfapi_rx_pdu(NFAPI_RX_PDU_LIST* list, void* UE_CONTEXT, void* RRC_CONNECTION_RECONFIGURATION_TAG, void* TAG_NSA_DEACTIVATION_INDICATION_REL15_TAG) {
    // Check if the list is full
    if (list->size == capacity) {
        // Reallocate memory for the list to make room for a new structure
        NFAPI_RX_PDU_T* temp = (NFAPI_RX_PDU_T*) realloc(list->data, (capacity + 1) * sizeof(NFAPI_RX_PDU_T));
        // If reallocation fails, free the existing memory and return
        if (!temp) {
            free(list->data);
            list->size = 0;
            return;
        }
        list->data = temp;
    }

    // Store the new structure in the next available position in the list
    NFAPI_RX_PDU_T* data = &(list->data[list->size]);
    data->UE_CONTEXT = UE_CONTEXT;
    data->RRC_CONNECTION_RECONFIGURATION_TAG = RRC_CONNECTION_RECONFIGURATION_TAG;
    data->TAG_NSA_DEACTIVATION_INDICATION_REL15_TAG = TAG_NSA_DEACTIVATION_INDICATION_REL15_TAG;
    list->size++;
}

// Remove outdated structures from the list to prevent excessive memory consumption
void purge_outdated_nfapi_rx_pdu(NFAPI_RX_PDU_LIST* list, uint64_t threshold) {
    // Check if there are any outdated structures in the list
    if (list->size > 0 && list->data[0].timestamp < threshold) {
        // Reallocate memory for the list to remove outdated structures
        NFAPI_RX_PDU_T* temp = (NFAPI_RX_PDU_T*) realloc(list->data, list->size * sizeof(NFAPI_RX_PDU_T));
        // If reallocation fails, free the existing memory and return
        if (!temp) {
            free(list->data);
            list->size = 0;
            return;
        }
        list->data = temp;
    }
}

// Retrieve the most recent NFAPI_RX_PDU_T structure from the list based on the timestamp
NFAPI_RX_PDU_T* get_most_recent_nfapi_rx_pdu(NFAPI_RX_PDU_LIST* list) {
    // Check if there are any structures in the list
    if (list->size == 0) {
        return NULL;
    }

    // Retrieve the most recent structure based on the timestamp
    NFAPI_RX_PDU_T* data = &(list->data[list->size - 1]);
    return data;
}
