    size_t count;
    LTE_ENB_CONFIG* elements;
};

// Function to manage a dynamic array of LTE_ENB_CONFIG structures
void mange_dynamic_array(struct dynamic_array* arr, int num_elements) {
    // Check if the input number of elements is valid
    if (num_elements <= 0) {
        return;
    }

    // Calculate the new capacity for the array
    size_t new_capacity = arr->count + num_elements;

    // Allocate memory for the new array
    LTE_ENB_CONFIG* new_arr = (LTE_ENB_CONFIG*)realloc(arr->elements, new_capacity * sizeof(LTE_ENB_CONFIG));
    if (!new_arr) {
        return;
    }

    // Update the capacity and element count of the array
    arr->capacity = new_capacity;
    arr->count += num_elements;

