int initializeSystemConfig(const char *configString, const int maxNumDataPoints, const char *networkConfigTemplatePath, const int maxNumThreads, const int n) {
  // Check input parameters for validity
  if (configString == NULL || maxNumDataPoints <= 0 || networkConfigTemplatePath == NULL || maxNumThreads < 1 || n <= 0) {
    return -1;
  }

  // Allocate memory for NFAPI_CRC_INDICATION_PDU_T structures
  NFAPI_CRC_INDICATION_PDU_T *crcIndicationPduList = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * n);
  if (crcIndicationPduList == NULL) {
    // Handle memory allocation failure gracefully
    return -2;
  }

  // Initialize NFAPI_CRC_INDICATION_PDU_T structures with valid data
  for (int i = 0; i < n; ++i) {
    crcIndicationPduList[i].rx_ue_information_tag = rand() % INT32_MAX;
    crcIndicationPduList[i].rnti = rand() % UINT16_MAX;
    crcIndicationPduList[i].crc_indication_rel8_tag = rand() % UINT8_MAX;
    crcIndicationPduList[i].crcflag = rand() % 2;
  }

  // Allocate memory for dynamic arrays of DataPoint and NetworkInterfaceConfig structures
  DataPoint *dataPointList = malloc(sizeof(DataPoint) * maxNumDataPoints);
  if (dataPointList == NULL) {
    free(crcIndicationPduList);
    return -3;
  }
  NetworkInterfaceConfig *networkInterfaceConfigList = malloc(sizeof(NetworkInterfaceConfig) * maxNumThreads);
  if (networkInterfaceConfigList == NULL) {
    free(dataPointList);
    free(crcIndicationPduList);
    return -4;
  }

  // Initialize dynamic arrays of DataPoint and NetworkInterfaceConfig structures with valid data
  for (int i = 0; i < maxNumDataPoints; ++i) {
    dataPointList[i].timestamp = time(NULL);
    dataPointList[i].value = rand() % 100.0;
  }
  for (int i = 0; i < maxNumThreads; ++i) {
    networkInterfaceConfigList[i].interfaceId = i + 1;
    char *neighborCellInfoList[128];
    // Initialize neighbor cell info list with default values from template
    for (int j = 0; j < 128; ++j) {
      neighborCellInfoList[j] = malloc(sizeof(char) * 16);
      snprintf(neighborCellInfoList[j], 16, "Default Neighbor Cell %d", i + 1);
    }
    networkInterfaceConfigList[i].neighborCellInfoList = neighborCellInfoList;
    // Initialize SRS parameters with default values from template
    networkInterfaceConfigList[i].srsParams.referenceSignalConfigurationIndex = 0;
    networkInterfaceConfigList[i].srsParams.referenceSignalPeriodicity = 5;
    networkInterfaceConfigList[i].srsParams.referenceSignalOffset = 1;
  }

  // Load template file and override default values with user-defined overrides if provided
  FILE *fp = fopen(networkConfigTemplatePath, "r");
  if (fp == NULL) {
    return -5;
  }
  char *line = NULL;
  size_t len = 0;
  ssize_t read;
  while ((read = getline(&line, &len, fp)) != -1) {
    // Override default values with user-defined overrides if provided
    if (strncmp(line, "interfaceId", 11) == 0) {
      char *interfaceIdStr = strtok(line, " ");
      interfaceIdStr = strtok(NULL, "=");
      int interfaceId = atoi(interfaceIdStr);
      if (interfaceId > maxNumThreads) {
        continue;
      }
      networkInterfaceConfigList[interfaceId - 1].interfaceId = interfaceId;
    } else if (strncmp(line, "neighborCellInfo", 15) == 0) {
      char *neighborCellInfoStr = strtok(line, " ");
      neighborCellInfoStr = strtok(NULL, "=");
      int neighborCellIdx = atoi(neighborCellInfoStr);
      if (neighborCellIdx > 128) {
        continue;
      }
      char *neighborCellName = strtok(NULL, ",");
      networkInterfaceConfigList[interfaceId - 1].neighborCellInfoList[neighborCellIdx] = malloc(sizeof(char) * 16);
      snprintf(networkInterfaceConfigList[interfaceId - 1].neighborCellInfoList[neighborCellIdx], 16, "%s", neighborCellName);
    } else if (strncmp(line, "referenceSignalConfigurationIndex", 30) == 0) {
      char *referenceSignalConfigurationIndexStr = strtok(line, " ");
      referenceSignalConfigurationIndexStr = strtok(NULL, "=");
      int referenceSignalConfigurationIndex = atoi(referenceSignalConfigurationIndexStr);
      networkInterfaceConfigList[interfaceId - 1].srsParams.referenceSignalConfigurationIndex = referenceSignalConfigurationIndex;
    } else if (strncmp(line, "referenceSignalPeriodicity", 28) == 0) {
      char *referenceSignalPeriodicityStr = strtok(line, " ");
      referenceSignalPeriodicityStr = strtok(NULL, "=");
      int referenceSignalPeriodicity = atoi(referenceSignalPeriodicityStr);
      networkInterfaceConfigList[interfaceId - 1].srsParams.referenceSignalPeriodicity = referenceSignalPeriodicity;
    } else if (strncmp(line, "referenceSignalOffset", 23) == 0) {
      char *referenceSignalOffsetStr = strtok(line, " ");
      referenceSignalOffsetStr = strtok(NULL, "=");
      int referenceSignalOffset = atoi(referenceSignalOffsetStr);
      networkInterfaceConfigList[interfaceId - 1].srsParams.referenceSignalOffset = referenceSignalOffset;
    } else {
      continue;
    }
  }

  // Free memory allocated for template file reading
  if (line) {
    free(line);
  }
  fclose(fp);

  return 0;
}

int main() {
  int ret = init();
  if (ret != 0) {
    // Handle error gracefully
  }
  return 0;
}
