            if (tag) {
                // Process the sample and update the session information
                process_sample(feature, sample, tag);
            }
        }
    }
}

void process_sample(double feature, media_sample* sample, media_tag* tag) {
    // Validate input parameters and handle edge cases
    if (sample == NULL || tag == NULL) return;

    // Process the sample concurrently
    while (1) {
        // Analyze a feature from the media sample
        double new_feature = analyze_feature(sample);
        if (new_feature < feature - 0.5 || new_feature > feature + 0.5) break;

        // Update the session information for each session
        for (int i = 0; i < SESSION_COUNT; i++) {
            sessions[i].active = 1;
            media_pdu* pdu = allocate_media_pdu(sessions[i].media_pdus);
            if (pdu) {
                // Process the new feature and update the session information
                process_new_feature(new_feature, pdu);
            }
        }
    }
}

void process_new_feature(double new_feature, media_pdu* pdu) {
    // Validate input parameters and handle edge cases
