struct HashTable {
    struct Entry** entries;
    int size;
    int count;
    pthread_mutex_t lock;
};

void hashTableInit(struct HashTable* ht, int size) {
    ht->size = size;
    ht->count = 0;
    ht->entries = (struct Entry**)malloc(sizeof(struct Entry*) * size);
    for (int i = 0; i < size; i++) {
        ht->entries[i] = NULL;
    }
    pthread_mutex_init(&ht->lock, NULL);
}

void hashTableInsert(struct HashTable* ht, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    int index = pdu->RNTI % ht->size;
    struct Entry* entry = (struct Entry*)malloc(sizeof(struct Entry));
    entry->pdu = *pdu;
    entry->expirationTime = time(NULL) + 30; // set expiration time to 30 seconds
    pthread_mutex_lock(&ht->lock);
    ht->entries[index] = entry;
    ht->count++;
    pthread_mutex_unlock(&ht->lock);
}

void hashTableGet(struct HashTable* ht, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    int index = pdu->RNTI % ht->size;
    pthread_mutex_lock(&ht->lock);
    struct Entry* entry = ht->entries[index];
    if (entry != NULL && entry->expirationTime > time(NULL)) {
        *pdu = entry->pdu;
    } else {
        *pdu = (NFAPI_CRC_INDICATION_PDU_T){0};
    }
    pthread_mutex_unlock(&ht->lock);
}

void hashTableDelete(struct HashTable* ht, int RNTI) {
    int index = RNTI % ht->size;
    pthread_mutex_lock(&ht->lock);
    struct Entry* entry = ht->entries[index];
    if (entry != NULL && entry->pdu.RNTI == RNTI) {
        free(entry);
        ht->entries[index] = NULL;
        ht->count--;
    }
    pthread_mutex_unlock(&ht->lock);
}

void hashTableCleanup(struct HashTable* ht) {
    for (int i = 0; i < ht->size; i++) {
        struct Entry* entry = ht->entries[i];
        if (entry != NULL && entry->expirationTime <= time(NULL)) {
            free(entry);
            ht->entries[i] = NULL;
            ht->count--;
        }
    }
}

void hashTableDestroy(struct HashTable* ht) {
    pthread_mutex_destroy(&ht->lock);
    for (int i = 0; i < ht->size; i++) {
        struct Entry* entry = ht->entries[i];
        if (entry != NULL) {
            free(entry);
        }
    }
    free(ht->entries);
}
