    quickSort(list);
}

// Define the quicksort algorithm for sorting the list of CRC indication PDUs
void quickSort(NFAPI_CRC_INDICATION_LIST_T *list) {
    // Check if the list is empty
    if (list->count == 0) {
        return;
    }

    // Define the partition function for selecting a pivot element
    size_t partition(NFAPI_CRC_INDICATION_LIST_T *list, size_t left, size_t right) {
        // Select a random pivot element from the list
        NFAPI_CRC_INDICATION_PDU_T pivot = list->entries[rand() % (right - left + 1) + left];

        // Partition the list around the pivot
        size_t i = left;
        for (size_t j = left; j < right; j++) {
            if (list->entries[j].rx_ue_information_tag < pivot.rx_ue_information_tag) {
                swap(list->entries[i], list->entries[j]);
                i++;
            }
        }
        swap(list->entries[i], list->entries[right]);
        return i;
    }

    // Define the swap function for swapping two elements in the list
    void swap(NFAPI_CRC_INDICATION_PDU_T *a, NFAPI_CRC_INDICATION_PDU_T *b) {
        NFAPI_CRC_INDICATION_PDU_T temp = *a;
        *a = *b;
        *b = temp;
    }

    // Sort the list recursively using the quicksort algorithm
    size_t left = 0, right = list->count - 1;
    while (left <= right) {
        size_t pivotIndex = partition(list, left, right);
        if (pivotIndex > 1) {
            quickSort(list, left, pivotIndex - 1);
        }
        left = pivotIndex + 1;
    }
}
