// Structure to store UDP connection statistics
typedef struct {
    char *remote_ip; // Remote IP address in string format
    int remote_port; // Remote port number
    char *local_ip; // Local IP address in string format
    int local_port; // Local port number
    time_t timestamp; // Timestamp of the last connection attempt
} UdpConnectionStats;

// Function to initialize and populate a dynamic array of UdpConnectionStats structures
int init_udp_connection_stats(UdpConnectionStats **stats, int max_connections) {
    // Check for invalid input parameters
    if (!stats || max_connections <= 0) {
        return -1;
    }

    // Allocate memory for the dynamic array of UdpConnectionStats structures
    *stats = malloc(sizeof(UdpConnectionStats) * max_connections);
    if (!*stats) {
        fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
        return -1;
    }

    // Initialize the dynamic array of UdpConnectionStats structures to zeroes
    memset(*stats, 0, sizeof(UdpConnectionStats) * max_connections);

    // Return success
    return 0;
}

// Function to add a new entry to the dynamic array of UdpConnectionStats structures
int add_udp_connection_stats(UdpConnectionStats **stats, int max_connections, char *remote_ip, int remote_port, char *local_ip, int local_port) {
    // Check for invalid input parameters
    if (!stats || !*stats || max_connections <= 0 || !remote_ip || !local_ip) {
        return -1;
    }

    // Allocate memory for the new entry in the dynamic array of UdpConnectionStats structures
    UdpConnectionStats *new_entry = malloc(sizeof(UdpConnectionStats));
    if (!new_entry) {
        fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
        return -1;
    }

    // Set the new entry's remote IP address and port number
    new_entry->remote_ip = strdup(remote_ip);
    if (!new_entry->remote_ip) {
        fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
        free(new_entry);
        return -1;
    }
    new_entry->remote_port = remote_port;

    // Set the new entry's local IP address and port number
    new_entry->local_ip = strdup(local_ip);
    if (!new_entry->local_ip) {
        fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
        free(new_entry->remote_ip);
        free(new_entry);
        return -1;
    }
    new_entry->local_port = local_port;

    // Set the new entry's timestamp to the current time
    new_entry->timestamp = time(NULL);

    // Add the new entry to the dynamic array of UdpConnectionStats structures
    if (max_connections <= (*stats)->count) {
        fprintf(stderr, "Maximum number of connections exceeded: %d\n", max_connections);
        free(new_entry->remote_ip);
        free(new_entry->local_ip);
        free(new_entry);
        return -1;
    } else {
        (*stats)[(*stats)->count] = *new_entry;
        (*stats)->count++;
        return 0;
    }
}

// Function to update an existing entry in the dynamic array of UdpConnectionStats structures
int update_udp_connection_stats(UdpConnectionStats **stats, int max_connections, char *remote_ip, int remote_port, char *local_ip, int local_port) {
    // Check for invalid input parameters
    if (!stats || !*stats || max_connections <= 0 || !remote_ip || !local_ip) {
        return -1;
    }

    // Find the entry in the dynamic array of UdpConnectionStats structures with the specified remote IP address and port number
    int i = 0;
    for (i = 0; i < (*stats)->count; i++) {
        if ((*stats)[i].remote_ip && !strcmp((*stats)[i].remote_ip, remote_ip) && (*stats)[i].remote_port == remote_port) {
            break;
        }
    }
    if (i >= max_connections) {
        fprintf(stderr, "Entry not found: %s:%d\n", remote_ip, remote_port);
        return -1;
    }

    // Update the entry's local IP address and port number
    free((*stats)[i].local_ip);
    (*stats)[i].local_ip = strdup(local_ip);
    if (!(*stats)[i].local_ip) {
        fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
        return -1;
    }
    (*stats)[i].local_port = local_port;

    // Update the entry's timestamp to the current time
    (*stats)[i].timestamp = time(NULL);

    // Return success
    return 0;
}

// Function to remove an existing entry from the dynamic array of UdpConnectionStats structures
int remove_udp_connection_stats(UdpConnectionStats **stats, int max_connections, char *remote_ip, int remote_port) {
    // Check for invalid input parameters
    if (!stats || !*stats || max_connections <= 0 || !remote_ip) {
        return -1;
    }

    // Find the entry in the dynamic array of UdpConnectionStats structures with the specified remote IP address and port number
    int i = 0;
    for (i = 0; i < (*stats)->count; i++) {
        if ((*stats)[i].remote_ip && !strcmp((*stats)[i].remote_ip, remote_ip) && (*stats)[i].remote_port == remote_port) {
            break;
        }
    }
    if (i >= max_connections) {
        fprintf(stderr, "Entry not found: %s:%d\n", remote_ip, remote_port);
        return -1;
    }

    // Remove the entry from the dynamic array of UdpConnectionStats structures
    free((*stats)[i].remote_ip);
    (*stats)[i].remote_ip = NULL;
    free((*stats)[i].local_ip);
    (*stats)[i].local_ip = NULL;
    (*stats)->count--;

    // Shift the remaining entries in the dynamic array of UdpConnectionStats structures down by one index
    for (int j = i; j < (*stats)->count; j++) {
        (*stats)[j] = (*stats)[j + 1];
    }

    // Return success
    return 0;
}

// Function to free the memory allocated for the dynamic array of UdpConnectionStats structures
void free_udp_connection_stats(UdpConnectionStats **stats) {
    // Check for invalid input parameters
    if (!stats || !*stats) {
        return;
    }

    // Free the memory allocated for each entry in the dynamic array of UdpConnectionStats structures
    for (int i = 0; i < (*stats)->count; i++) {
        free((*stats)[i].remote_ip);
        free((*stats)[i].local_ip);
    }

    // Free the memory allocated for the dynamic array of UdpConnectionStats structures
    free(*stats);
}

// Function to display the contents of a UdpConnectionStats structure
void print_udp_connection_stats(UdpConnectionStats *stats) {
    // Check for invalid input parameters
    if (!stats) {
        return;
    }

    // Print each entry in the dynamic array of UdpConnectionStats structures
    for (int i = 0; i < stats->count; i++) {
        printf("Remote IP: %s, Remote Port: %d, Local IP: %s, Local Port: %d, Timestamp: %ld\n", stats[i].remote_ip, stats[i].remote_port, stats[i].local_ip, stats[i].local_port, stats[i].timestamp);
    }
}
