int add_message(NAS_MESSAGE_TYPE type, uint8_t *message_id, void *message_content, size_t message_len) {
    // Lock the mutex for synchronizing access to the message array
    pthread_mutex_lock(&message_lock);

    // Check if the message array is full
    if (num_messages >= 10) {
        // The message array is full, so reallocate memory with a larger capacity
        messages = (LTE_NAS_Message *)realloc(messages, 2 * num_messages * sizeof(LTE_NAS_Message));
        if (!messages) {
            pthread_mutex_unlock(&message_lock);
            return -1;
        }
    }

    // Create a new message structure and add it to the array
    LTE_NAS_Message *new_message = (LTE_NAS_Message *)malloc(sizeof(LTE_NAS_Message));
    if (!new_message) {
        pthread_mutex_unlock(&message_lock);
        return -1;
    }

    new_message->type = type;
    new_message->message_id = message_id;
    new_message->message_content = message_content;
    new_message->message_len = message_len;
    messages[num_messages++] = *new_message;

    // Unlock the mutex for synchronizing access to the message array
    pthread_mutex_unlock(&message_lock);

    return 0;
}

// Function to retrieve a message from the dynamic array by its ID
int get_message(uint8_t *message_id, LTE_NAS_Message **message) {
    // Lock the mutex for synchronizing access to the message array
    pthread_mutex_lock(&message_lock);

    // Iterate through the message array and find the message with the given ID
    for (size_t i = 0; i < num_messages; i++) {
        if (strcmp(messages[i].message_id, message_id) == 0) {
            *message = &messages[i];
            break;
        }
    }

    // Unlock the mutex for synchronizing access to the message array
    pthread_mutex_unlock(&message_lock);

    return 0;
}

// Function to delete a message from the dynamic array by its ID
int delete_message(uint8_t *message_id) {
    // Lock the mutex for synchronizing access to the message array
    pthread_mutex_lock(&message_lock);

    // Iterate through the message array and find the message with the given ID
    size_t i;
    for (i = 0; i < num_messages; i++) {
        if (strcmp(messages[i].message_id, message_id) == 0) {
            break;
        }
    }

    // If the message was found, remove it from the array and free its resources
    if (i < num_messages) {
        LTE_NAS_Message *temp = &messages[i];
        messages[i] = messages[--num_messages];
        free(temp);
    }

    // Unlock the mutex for synchronizing access to the message array
    pthread_mutex_unlock(&message_lock);

    return 0;
}

// Function to iterate over all messages in the dynamic array
int iterate_messages(void (*callback)(LTE_NAS_Message *)) {
    // Lock the mutex for synchronizing access to the message array
    pthread_mutex_lock(&message_lock);

    // Iterate through the message array and call the callback function for each message
    for (size_t i = 0; i < num_messages; i++) {
        callback(&messages[i]);
    }

    // Unlock the mutex for synchronizing access to the message array
    pthread_mutex_unlock(&message_lock);

    return 0;
}
```
This code implements a function `init_messages()` that initializes and manages a dynamic array of `LTE_NAS_Message` structures, ensuring efficient resource utilization and reliable operation under varying loads. The function allocates memory for the message array with a capacity for 10 messages, and it sets the number of messages to 0. It also initializes a lock for synchronizing access to the message array.

The `add_message()` function adds a new message to the dynamic array by creating a new structure that contains the message type, ID, and content. The function checks if the message array is full before reallocating memory with a larger capacity. It then creates a new message structure and adds it to the end of the array.

