use std::sync::{Arc, Mutex};
use std::env;
use std::fs;
use std::path::PathBuf;
use std::io;

struct LTE_NAS_Message {
    nas_message_type: NAS_MESSAGE_TYPE,
    nas_message_id: NAS_MESSAGE_ID,
    message_content: Vec<u8>,
}

impl LTE_NAS_Message {
    fn new(nas_message_type: NAS_MESSAGE_TYPE, nas_message_id: NAS_MESSAGE_ID, message_content: Vec<u8>) -> Self {
        LTE_NAS_Message {
            nas_message_type,
            nas_message_id,
            message_content,
        }
    }
}

struct MessageArray {
    messages: Arc<Mutex<Vec<LTE_NAS_Message>>>,
}

impl MessageArray {
    fn new() -> Self {
        MessageArray {
            messages: Arc::new(Mutex::new(vec![])),
        }
    }

    fn push(&self, message: LTE_NAS_Message) {
        let mut messages = self.messages.lock().unwrap();
        messages.push(message);
    }

    fn pop(&self) -> Option<LTE_NAS_Message> {
        let mut messages = self.messages.lock().unwrap();
        messages.pop()
    }

    fn len(&self) -> usize {
        let messages = self.messages.lock().unwrap();
        messages.len()
    }
}

fn init_message_array(name: &str) -> MessageArray {
    let mut message_array = MessageArray::new();
    if !env::var("MESSAGES_PATH").is_some() {
        let path = PathBuf::from(format!("{}_messages", name));
        fs::create_dir(&path).unwrap();
        env::set_var("MESSAGES_PATH", &path);
    }
    message_array
}

fn process_message(message: LTE_NAS_Message) {
    let mut messages = init_message_array(name);
    messages.push(message);
    // log message processing event
    log::info!("processed message {:?}", message);
}

fn create_directory(name: &str) -> Result<(), io::Error> {
    if !env::var("MESSAGES_PATH").is_some() {
        let path = PathBuf::from(format!("{}_messages", name));
        fs::create_dir(&path)?;
        env::set_var("MESSAGES_PATH", &path);
    }
    Ok(())
}
```
