// Memory pool for dynamic memory allocation
static void *memory_pool = NULL;

// Size of the memory pool in bytes
static size_t memory_pool_size = 0;

// Mutex for protecting the memory pool
static pthread_mutex_t memory_pool_mutex = PTHREAD_MUTEX_INITIALIZER;

// Semaphore for signaling when a new interface is added/removed
static sem_t *interface_change_sem = NULL;

// List of all interfaces and their associated data structures
typedef struct InterfaceInfo {
  NetworkInterfaceConfig config;
  NeighborCellInfo *neighbors;
  SRSParameters srs_params;
} InterfaceInfo;

static InterfaceInfo *interface_list = NULL;

// Size of the interface list
static size_t interface_list_size = 0;

// Mutex for protecting the interface list
static pthread_mutex_t interface_list_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to allocate memory from the memory pool
void *allocate_memory(size_t size) {
  // Acquire the mutex for the memory pool
  pthread_mutex_lock(&memory_pool_mutex);

  // Check if there is enough memory in the pool
  if (size > memory_pool_size) {
    fprintf(stderr, "Error: Not enough memory in pool\n");
    exit(1);
  }

  // Allocate memory from the pool
  void *memory = malloc(size);

  // Update the size of the memory pool
  memory_pool_size -= size;

  // Release the mutex for the memory pool
  pthread_mutex_unlock(&memory_pool_mutex);

  return memory;
}

// Function to free memory back to the memory pool
void free_memory(void *memory, size_t size) {
  // Acquire the mutex for the memory pool
  pthread_mutex_lock(&memory_pool_mutex);

  // Reallocate the memory back to the pool
  realloc(memory, size);

  // Update the size of the memory pool
  memory_pool_size += size;

  // Release the mutex for the memory pool
  pthread_mutex_unlock(&memory_pool_mutex);
}

// Function to add a new interface to the list
void add_interface(NetworkInterfaceConfig config, NeighborCellInfo *neighbors) {
  // Acquire the mutex for the interface list
  pthread_mutex_lock(&interface_list_mutex);

  // Allocate memory for the new interface
  InterfaceInfo *new_interface = allocate_memory(sizeof(InterfaceInfo));

  // Initialize the new interface structure
  new_interface->config = config;
  new_interface->neighbors = neighbors;
  new_interface->srs_params = SRSParameters();

  // Add the new interface to the list
  interface_list[interface_list_size++] = new_interface;

  // Release the mutex for the interface list
  pthread_mutex_unlock(&interface_list_mutex);
}

// Function to remove an interface from the list
void remove_interface(NetworkInterfaceConfig config) {
  // Acquire the mutex for the interface list
  pthread_mutex_lock(&interface_list_mutex);

  // Find the interface with the matching configuration
  InterfaceInfo *interface = NULL;
  for (size_t i = 0; i < interface_list_size; i++) {
    if (interface_list[i]->config == config) {
      interface = interface_list[i];
      break;
    }
  }

  // Remove the interface from the list
  if (interface != NULL) {
    free_memory(interface, sizeof(InterfaceInfo));
    interface_list_size--;
    for (size_t i = 0; i < interface_list_size - 1; i++) {
      if (interface == interface_list[i]) {
        InterfaceInfo *tmp = interface_list[i];
        interface_list[i] = interface_list[i + 1];
        interface_list[i + 1] = tmp;
        break;
      }
    }
  } else {
    fprintf(stderr, "Error: Interface not found\n");
  }

  // Release the mutex for the interface list
  pthread_mutex_unlock(&interface_list_mutex);
}

// Function to update an interface's SRS parameters
void update_srs_params(NetworkInterfaceConfig config, SRSParameters srs_params) {
  // Acquire the mutex for the interface list
  pthread_mutex_lock(&interface_list_mutex);

  // Find the interface with the matching configuration
  InterfaceInfo *interface = NULL;
  for (size_t i = 0; i < interface_list_size; i++) {
    if (interface_list[i]->config == config) {
      interface = interface_list[i];
      break;
    }
  }

  // Update the SRS parameters of the interface
  if (interface != NULL) {
    interface->srs_params = srs_params;
  } else {
    fprintf(stderr, "Error: Interface not found\n");
  }

  // Release the mutex for the interface list
  pthread_mutex_unlock(&interface_list_mutex);
}

// Function to iterate over all interfaces and their neighbors
void iterate_interfaces(void (*callback)(NetworkInterfaceConfig config, NeighborCellInfo *neighbors)) {
  // Acquire the mutex for the interface list
  pthread_mutex_lock(&interface_list_mutex);

  // Iterate over all interfaces and their neighbors
  for (size_t i = 0; i < interface_list_size; i++) {
    NetworkInterfaceConfig config = interface_list[i]->config;
    NeighborCellInfo *neighbors = interface_list[i]->neighbors;
    callback(config, neighbors);
  }

  // Release the mutex for the interface list
  pthread_mutex_unlock(&interface_list_mutex);
}

// Function to get an interface's SRS parameters
SRSParameters get_srs_params(NetworkInterfaceConfig config) {
  // Acquire the mutex for the interface list
  pthread_mutex_lock(&interface_list_mutex);

  // Find the interface with the matching configuration
  InterfaceInfo *interface = NULL;
  for (size_t i = 0; i < interface_list_size; i++) {
    if (interface_list[i]->config == config) {
      interface = interface_list[i];
      break;
    }
  }

  // Get the SRS parameters of the interface
  SRSParameters srs_params;
  if (interface != NULL) {
    srs_params = interface->srs_params;
  } else {
    fprintf(stderr, "Error: Interface not found\n");
  }

  // Release the mutex for the interface list
  pthread_mutex_unlock(&interface_list_mutex);
}

// Main function
int main() {
  // Initialize the memory pool
  size_t mempool_size = 100;
  void *mempool = allocate_memory(mempool_size);

  // Initialize the interface list and its mutex
  interface_list = (InterfaceInfo **)malloc(sizeof(InterfaceInfo *) * INTERFACE_LIST_SIZE);
  pthread_mutex_init(&interface_list_mutex, NULL);

