// Define a structure to hold the NFAPI_CRC_INDICATION_PDU_T data
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
