// Define a dynamic list of NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    int size;
    int capacity;
    NFAPI_CRC_INDICATION_PDU_T* data;
} DynamicList;

// Function to add a new entry to the list, returning true if successful and false otherwise
bool AddEntry(DynamicList* list, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Check that the list is not full
    if (list->size == list->capacity) {
        return false;
    }

    // Allocate memory for the new entry and copy the data from the given PDU
    NFAPI_CRC_INDICATION_PDU_T* new_entry = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    memcpy(new_entry, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Add the new entry to the list and update the size
    list->data[list->size++] = new_entry;

    return true;
}

// Function to remove an existing entry from the list, returning true if successful and false otherwise
bool RemoveEntry(DynamicList* list, const int RNTI) {
    // Find the index of the entry with the given RNTI
    int i = 0;
    for (i = 0; i < list->size; i++) {
        if (list->data[i]->RNTI == RNTI) {
            break;
        }
    }

    // Check that the entry was found
    if (i >= list->size) {
        return false;
    }

    // Remove the entry and update the size
    free(list->data[i]);
    memmove(&list->data[i], &list->data[i + 1], (list->size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->size--;

    return true;
}

// Function to update the CRCFLAG for all entries with a given RNTI, returning the number of updated entries
int UpdateCRCFlag(DynamicList* list, const int RNTI, const bool new_crcflag) {
    // Find the index of the entry with the given RNTI
    int i = 0;
    for (i = 0; i < list->size; i++) {
        if (list->data[i]->RNTI == RNTI) {
            break;
        }
    }

    // Check that the entry was found
    if (i >= list->size) {
        return 0;
    }

    // Update the CRCFLAG for all entries with the given RNTI
    int num_updated = 0;
    for (int j = i; j < list->size; j++) {
        if (list->data[j]->RNTI == RNTI) {
            list->data[j]->CRCFLAG = new_crcflag;
            num_updated++;
        }
    }

    return num_updated;
}

// Function to iterate over the list and update the CRCFLAG for all entries based on certain conditions, returning the number of updated entries
int UpdateCRCFlagByCondition(DynamicList* list, const bool (*condition)(const NFAPI_CRC_INDICATION_PDU_T*), const bool new_crcflag) {
    // Initialize a counter for the number of updated entries
    int num_updated = 0;

    // Iterate over the list and update the CRCFLAG for all entries that satisfy the condition
    for (int i = 0; i < list->size; i++) {
        if (condition(list->data[i])) {
