// Function to generate and execute a strategy for the game character
void generateAndExecuteStrategy(const std::vector<RX_UE_INFORMATION_TAG>& rxUeInformationList) {
    // Probability distribution for selecting a strategy
    const double strategyProbs[2] = {0.5, 0.5};

    // Cooldown period in seconds
    const uint32_t cooldownPeriod = 9;

    // Current time in seconds
    std::chrono::time_point<std::chrono::system_clock> currentTime;

    // Mutex for protecting access to the strategy and cooldown timer
    static std::mutex strategyMutex;

    // Condition variable for signalling when the cooldown period is over
    static std::condition_variable cooldownCV;

    // Function to check if the cooldown period has expired
    auto isCooldownExpired = [&currentTime, &cooldownPeriod]() {
        return (std::chrono::duration<double>(currentTime - std::chrono::system_clock::now()).count() >= cooldownPeriod);
    };

    // Function to generate a random number within the given range
    auto generateRandom = [](const int& lowerBound, const int& upperBound) {
        return rand() % (upperBound - lowerBound + 1) + lowerBound;
    };

    // Function to select a strategy based on its probability
    auto selectStrategy = [&strategyProbs]() {
        double randomNum = generateRandom(0, 1);
        int selectedStrategy = 0;
        for (int i = 0; i < 2; ++i) {
            if (randomNum <= strategyProbs[i]) {
                selectedStrategy = i;
                break;
            } else {
                randomNum -= strategyProbs[i];
            }
        }
        return selectedStrategy;
    };

    // Function to execute a strategy and print it to the console
    auto executeAndPrintStrategy = [](const int& strategyIndex) {
        std::cout << "Selected strategy: " << strategyIndex << std::endl;
    };

    // Acquire the mutex for protecting access to the strategy and cooldown timer
    strategyMutex.lock();

    // Check if the cooldown period has expired or not
    currentTime = std::chrono::system_clock::now();
    if (isCooldownExpired()) {
        // Update the cooldown timer and execute a new strategy
        cooldownCV.wait(strategyMutex, isCooldownExpired);
        int selectedStrategy = selectStrategy();
        executeAndPrintStrategy(selectedStrategy);
    } else {
        // If the cooldown period has not expired, wait for it to be over
        cooldownCV.wait_for(strategyMutex, std::chrono::seconds{cooldownPeriod});
    }

    // Release the mutex for protecting access to the strategy and cooldown timer
    strategyMutex.unlock();
}

// Main function for demonstrating the functionality of generateAndExecuteStrategy()
