// Function to manage the persistent HTTP client connection pool
void manage_http_pool(struct request* requests, int num_requests) {
    // Initialize the connection pool with 20 active connections
    CURLM *multi_handle = curl_multi_init();
    int max_active_connections = 20;

    // Initialize an array to keep track of the active connections
    struct curl_slist* connections[max_active_connections];

    for (int i = 0; i < num_requests; i++) {
        // Create a new connection for each request
        CURL* easy_handle = curl_easy_init();

        // Set the URL, payload, and timeout value for the current request
        curl_easy_setopt(easy_handle, CURLOPT_URL, requests[i].url);
        curl_easy_setopt(easy_handle, CURLOPT_POSTFIELDS, requests[i].payload);
        curl_easy_setopt(easy_handle, CURLOPT_TIMEOUT_MS, requests[i].timeout_value);

        // Add the current request to the connection pool
        connections[i] = curl_multi_add_handle(multi_handle, easy_handle);
    }

    // Execute the requests concurrently and process their responses
    for (;;) {
        CURLMcode code;
        int still_running;

        // Execute one round of HTTP requests
        do {
            code = curl_multi_perform(multi_handle, &still_running);
        } while (code == CURLM_CALL_MULTI_PERFORM);

        if (!still_running) {
            // Process the responses for each request
            for (int i = 0; i < num_requests; i++) {
                CURL* easy_handle = connections[i];
                long response_code;

                curl_easy_getinfo(easy_handle, CURLINFO_RESPONSE_CODE, &response_code);
                if (response_code >= 400) {
                    // Handle error recovery for failed requests
