                }
            }
        }

        // Check for memory allocation failures and handle unexpected disconnections
        if (curl_multi_info_read(multi_handle, &still_running) == NULL) {
            break;
        }
    }

    // Clean up the connection pool and requests
    curl_multi_cleanup(multi_handle);
    for (int i = 0; i < num_requests; i++) {
        curl_easy_cleanup(connections[i]);
    }
}
