use std::collections::HashMap;
use std::sync::Mutex;
use std::sync::Arc;
use std::sync::atomic::AtomicUsize;

struct Session {
    id: String,
    user_name: String,
    purchase_history: Vec<Purchase>,
    expiration_timestamp: u64,
}

struct Purchase {
    item_id: String,
    amount: f32,
    timestamp: u64,
}

struct SessionManager {
    sessions: HashMap<String, Arc<Mutex<Session>>>,
    last_session_id: AtomicUsize,
}

impl SessionManager {
    fn new() -> Self {
        Self {
            sessions: HashMap::new(),
            last_session_id: AtomicUsize::new(0),
        }
    }

    fn create_session(&self, user_name: String) -> Arc<Mutex<Session>> {
        let session = Session {
            id: self.last_session_id.fetch_add(1, Ordering::SeqCst).to_string(),
            user_name,
            purchase_history: vec![],
            expiration_timestamp: 0,
        };

        Arc::new(Mutex::new(session))
    }

    fn get_session(&self, id: &str) -> Option<Arc<Mutex<Session>>> {
        self.sessions.get(id).cloned()
    }

    fn update_session(&self, session: Arc<Mutex<Session>>) {
        let mut sessions = self.sessions.write();
        sessions.insert(session.lock().unwrap().id.clone(), session);
    }

    fn delete_session(&self, id: &str) -> Option<Arc<Mutex<Session>>> {
        self.sessions.remove(id)
    }
}
