        // Lock the mutex before updating the last active time
        std::lock_guard<std::mutex> lock(mutex_);

        // Check if the session ID is within bounds
        if (sessionID < 0 || sessionID >= sessions_.size()) {
            throw std::out_of_range("Session ID out of range");
        }

        // Update the last active time for the given session ID
        sessions_[sessionID].lastActiveTime = std::chrono::system_clock::now();
    }

    void validateIntegrity(int sessionID) {
        // Lock the mutex before checking the integrity of the sessions
        std::lock_guard<std::mutex> lock(mutex_);

        // Check if the session ID is within bounds
        if (sessionID < 0 || sessionID >= sessions_.size()) {
            throw std::out_of_range("Session ID out of range");
        }

        // Validate the integrity of the given session
        if (sessions_[sessionID].lastActiveTime < minLastActiveTime_) {
            throw std::runtime_error("Invalid last active time");
        }
    }

private:
