void init_arrays(long** offset, int** keys, Record*** records, size_t num_records) {
    // Allocate memory for the offset array
    *offset = (long*)malloc(num_records * sizeof(long));
    if (*offset == NULL) {
        printf("Error: Failed to allocate memory for offset array\n");
        exit(1);
    }

    // Allocate memory for the key array
    *keys = (int*)malloc(num_records * sizeof(int));
    if (*keys == NULL) {
        printf("Error: Failed to allocate memory for key array\n");
        exit(1);
    }

    // Allocate memory for the record array
    *records = (Record**)malloc(num_records * sizeof(Record*));
    if (*records == NULL) {
        printf("Error: Failed to allocate memory for record array\n");
        exit(1);
    }

    // Initialize the offset and key arrays
    for (size_t i = 0; i < num_records; i++) {
        (*offset)[i] = i * sizeof(Record);
        (*keys)[i] = rand() % 100 + 1;
    }

    // Initialize the record array
    for (size_t i = 0; i < num_records; i++) {
        (*records)[i] = malloc(sizeof(Record));
        if ((*records)[i] == NULL) {
            printf("Error: Failed to allocate memory for record %d\n", i);
            exit(1);
        }
    }
}

// Function to validate the integrity of the data structure
void validate_data(long* offset, int* keys, Record** records, size_t num_records) {
    // Validate that no two consecutive records have the same key value
    for (size_t i = 0; i < num_records - 1; i++) {
        if (keys[i] == keys[i + 1]) {
            printf("Error: Record %d and %d have the same key value\n", i, i + 1);
            exit(1);
        }
    }

    // Validate that no record contains an invalid value
    for (size_t i = 0; i < num_records; i++) {
        if (!is_valid_value(records[i]->value)) {
            printf("Error: Record %d has an invalid value\n", i);
            exit(1);
        }
    }
}

// Function to set the value of each record's int field to a random value within a specified range
void set_random_values(long* offset, int* keys, Record** records, size_t num_records) {
    // Set the value of each record's int field to a random value within the specified range
    for (size_t i = 0; i < num_records; i++) {
        records[i]->value = rand() % 100 + 1;
    }
}

// Function to serialize the initialized data structure to a binary file
void save_data(long* offset, int* keys, Record** records, size_t num_records) {
    // Open the output file for writing
    FILE* fp = fopen("output.bin", "wb");
    if (fp == NULL) {
        printf("Error: Failed to open output file\n");
        exit(1);
    }

    // Write the offset array to the file
    fwrite(offset, sizeof(long), num_records, fp);

    // Write the key array to the file
    fwrite(keys, sizeof(int), num_records, fp);

    // Write the record array to the file
    for (size_t i = 0; i < num_records; i++) {
        Record* record = records[i];
        fwrite(&record->value, sizeof(int), 1, fp);
    }

    // Close the output file
    fclose(fp);
}
