    for (int i = 0; i < numInterfaces; i++) {
        pthread_mutex_lock(mutex);
        interfaces[i]->srsParams.srsPeriod = 1;
        interfaces[i]->srsParams.srsOffset = 0;
        pthread_mutex_unlock(mutex);
    }
}

// Define the function to populate the neighbor cell list with a specified number of entries, ensuring no duplicate neighbor IDs and correctly configure the SRS parameters based on a predefined template
void populateNeighborCells(NetworkInterfaceConfig *interface, int numEntries) {
    // Generate random cell IDs for each entry
    int *cellIds = (int *) malloc(numEntries * sizeof(int));
    for (int i = 0; i < numEntries; i++) {
        cellIds[i] = rand() % 1000 + 1;
    }

    // Check for duplicate neighbor IDs and update the SRS parameters accordingly
    pthread_mutex_lock(interface->mutex);
    for (int i = 0; i < numEntries; i++) {
        int duplicateIdx = -1;
        for (int j = 0; j < interface->numNeighborCells; j++) {
            if (cellIds[i] == interface->neighborCells[j].cellId) {
                duplicateIdx = j;
                break;
            }
        }
        if (duplicateIdx != -1) {
            cellIds[i] = rand() % 1000 + 1;
            interface->neighborCells[duplicateIdx].rssi = 0;
            interface->srsParams.srsPeriod = 1;
        } else {
            interface->neighborCells[interface->numNeighborCells].cellId = cellIds[i];
            interface->neighborCells[interface->numNeighborCells].rssi = rand() % 20 - 10;
            interface->srsParams.srsPeriod += 1;
        }
    }
    pthread_mutex_unlock(interface->mutex);
}

// Define the function to handle memory allocation efficiently to avoid leaks and ensure thread-safe access to shared resources when multiple instances are initialized simultaneously
void* allocateMemory(size_t size) {
    void *ptr = malloc(size);
    if (ptr == NULL) {
        printf("Error: Out of memory\n");
        exit(1);
    }
    return ptr;
}

// Define the function to serialize a NetworkInterfaceConfig structure to a binary format for storage or network transmission
void serializeNetworkInterfaceConfig(NetworkInterfaceConfig *config, char **buffer) {
    int size = sizeof(config->interfaceId) + sizeof(config->numNeighborCells) + sizeof(config->srsParams) + config->numNeighborCells * sizeof(NeighborCellInfo);
    char *ptr = (char *) allocateMemory(size);

    // Write the interface ID to the buffer
    memcpy(ptr, &config->interfaceId, sizeof(config->interfaceId));
    ptr += sizeof(config->interfaceId);

    // Write the number of neighbor cells to the buffer
    memcpy(ptr, &config->numNeighborCells, sizeof(config->numNeighborCells));
    ptr += sizeof(config->numNeighborCells);

    // Write the SRS parameters to the buffer
    memcpy(ptr, &config->srsParams, sizeof(config->srsParams));
    ptr += sizeof(config->srsParams);

    // Write the neighbor cell information to the buffer
    for (int i = 0; i < config->numNeighborCells; i++) {
        memcpy(ptr, &config->neighborCells[i], sizeof(NeighborCellInfo));
        ptr += sizeof(NeighborCellInfo);
    }

    *buffer = ptr - size;
}

// Define the function to deserialize a NetworkInterfaceConfig structure from a binary format for storage or network transmission
void deserializeNetworkInterfaceConfig(char **buffer, NetworkInterfaceConfig *config) {
    int size = sizeof(config->interfaceId) + sizeof(config->numNeighborCells) + sizeof(config->srsParams) + config->numNeighborCells * sizeof(NeighborCellInfo);
    memcpy(&config->interfaceId, *buffer, sizeof(config->interfaceId));
    *buffer += sizeof(config->interfaceId);

    memcpy(&config->numNeighborCells, *buffer, sizeof(config->numNeighborCells));
    *buffer += sizeof(config->numNeighborCells);

    memcpy(&config->srsParams, *buffer, sizeof(config->srsParams));
    *buffer += sizeof(config->srsParams);

    for (int i = 0; i < config->numNeighborCells; i++) {
        memcpy(&config->neighborCells[i], *buffer, sizeof(NeighborCellInfo));
        *buffer += sizeof(NeighborCellInfo);
    }
}

// Define the function to allocate a NetworkInterfaceConfig structure with a specified number of neighbor cells and initialize it with random values
NetworkInterfaceConfig* allocAndInitializeNetworkInterfaceConfig(int numEntries) {
    NetworkInterfaceConfig *config = (NetworkInterfaceConfig *) allocateMemory(sizeof(NetworkInterfaceConfig));
    config->interfaceId = rand() % 1000 + 1;
    config->numNeighborCells = numEntries;
    config->neighborCells = (NeighborCellInfo*) malloc(numEntries * sizeof(NeighborCellInfo));
    for (int i = 0; i < numEntries; i++) {
        config->neighborCells[i].cellId = rand() % 1000 + 1;
        config->neighborCells[i].rssi = rand() % 20 - 10;
    }
    return config;
}

// Define the function to free a NetworkInterfaceConfig structure and all of its associated memory
void freeNetworkInterfaceConfig(NetworkInterfaceConfig *config) {
    if (config != NULL) {
        free(config->neighborCells);
        free(config);
    }
}

int main() {
    // Initialize the network interface configuration with a specified number of neighbor cells and populate it with random values
    NetworkInterfaceConfig *interface = allocAndInitializeNetworkInterfaceConfig(10);
    printf("Initial interface configuration:\n");
    serializeNetworkInterfaceConfig(interface, &buffer);
    deserializeNetworkInterfaceConfig(&buffer, interface);
    printf("%d\n", interface->numNeighborCells);
    for (int i = 0; i < interface->numNeighborCells; i++) {
        printf("%d: %d\n", i + 1, interface->neighborCells[i].cellId);
    }

    // Populate the neighbor cell list with a specified number of entries, ensuring no duplicate neighbor IDs and correctly configure the SRS parameters based on a predefined template
    populateNeighborCells(interface, 20);
    printf("Populated interface configuration:\n");
    serializeNetworkInterfaceConfig(interface, &buffer);
    deserializeNetworkInterfaceConfig(&buffer, interface);
    printf("%d\n", interface->numNeighborCells);
    for (int i = 0; i < interface->numNeighborCells; i++) {
        printf("%d: %d\n", i + 1, interface->neighborCells[i].cellId);
    }

    // Free the network interface configuration and all of its associated memory
    freeNetworkInterfaceConfig(interface);
    return 0;
}
```

