// Define a structure to represent a network event
typedef struct NetworkEvent {
    unsigned long timestamp; // Timestamp of the event
    int eventType; // Type of the event (e.g., RX_UE_INFORMATION_TAG, CRC_INDICATION_REL8_TAG)
    void* dataPayload; // Variable-length data payload for the event
} NetworkEvent;

// Define a linked list node to store a network event
typedef struct NetworkEventNode {
    NetworkEvent event;
    struct NetworkEventNode* next;
} NetworkEventNode;

// Function to add a new network event to the linked list
void addNetworkEvent(NetworkEventNode** head, unsigned long timestamp, int eventType, void* dataPayload) {
    // Create a new node for the event
    NetworkEventNode* newNode = malloc(sizeof(NetworkEventNode));
    assert(newNode != NULL);

    // Initialize the node with the given parameters
    newNode->event.timestamp = timestamp;
    newNode->event.eventType = eventType;
    newNode->event.dataPayload = dataPayload;

    // Add the node to the linked list
    if (*head == NULL) {
        *head = newNode;
    } else {
        NetworkEventNode* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }
}

// Function to update an existing network event in the linked list
void updateNetworkEvent(NetworkEventNode** head, unsigned long timestamp, int eventType, void* dataPayload) {
    // Check if the linked list is empty
    if (*head == NULL) {
        return;
    }

    // Find the node corresponding to the given ID
    NetworkEventNode* current = *head;
    while (current != NULL && current->event.timestamp != timestamp) {
        current = current->next;
    }

    // Update the event if it exists, otherwise do nothing
    if (current != NULL) {
        current->event.eventType = eventType;
        current->event.dataPayload = dataPayload;
    }
}

// Function to iterate over all network events in chronological order
void iterateNetworkEvents(NetworkEventNode* head) {
    // Check if the linked list is empty
    if (head == NULL) {
        return;
    }

    // Iterate over all nodes in the linked list
    NetworkEventNode* current = head;
    while (current != NULL) {
        printf("Timestamp: %lu, Event Type: %d, Data Payload: %p\n", current->event.timestamp, current->event.eventType, current->event.dataPayload);
        current = current->next;
    }
}

