// Define a struct to represent a promise
struct promise {
    void (*resolve)(void *value);  // function to resolve the promise with a value
    void *value;                   // value associated with the promise
};

// Define a struct to represent an array of numbers
struct number_array {
    size_t capacity;  // maximum number of elements in the array
    size_t size;      // current number of elements in the array
    int *elements;  // array of integers
};

// Initialize an array of numbers
void initialize(struct number_array *array) {
    array->capacity = 10;
    array->size = 0;
    array->elements = malloc(sizeof(int) * array->capacity);
}

// Add a new element to the array of numbers
void add(struct number_array *array, int value) {
    // Check if the array is full
    if (array->size == array->capacity) {
        // If the array is full, double its capacity and reallocate memory for the elements array
        size_t new_capacity = array->capacity * 2;
        array->elements = realloc(array->elements, sizeof(int) * new_capacity);
        array->capacity = new_capacity;
    }

    // Add a new element to the end of the array
    array->elements[array->size++] = value;
}

// Remove an element from the array of numbers by its index
void remove(struct number_array *array, size_t index) {
    // Check if the given index is valid
    if (index >= array->size) {
        return;
    }

    // Shift all elements after the given index one position to the left
    for (size_t i = index + 1; i < array->size; i++) {
        array->elements[i - 1] = array->elements[i];
    }

    // Decrease the size of the array by one
    array->size--;
}

// Get an element from the array of numbers by its index
int get(struct number_array *array, size_t index) {
    // Check if the given index is valid
    if (index >= array->size) {
        return 0;
    }

    // Return the element at the given index
    return array->elements[index];
}

// Calculate the product of an array of numbers using a cumulative reduction algorithm
void *calculate_product(struct number_array *array) {
    // Check if the array is empty
    if (array->size == 0) {
        return NULL;
    }

    // Initialize a promise to represent the result of the calculation
    struct promise promise;
    promise.resolve = NULL;
    promise.value = NULL;

    // Start a new thread to calculate the product in the background
    pthread_t thread;
    int error = pthread_create(&thread, NULL, (void *(*) (void *)) calculate_product, array);
    if (error != 0) {
        return NULL;
    }

    // Return a promise that will resolve with the result of the calculation when it is available
    return &promise;
}

// Calculate the product of an array of numbers using a cumulative reduction algorithm in the background
void *calculate_product(struct number_array *array) {
    // Initialize a variable to represent the product
    long product = 1;

    // Iterate over all elements in the array and calculate their product recursively
    for (size_t i = 0; i < array->size; i++) {
        if (i == array->size - 1) {
            product *= get(array, i);
        } else {
            product *= get(array, i) * calculate_product(array, i + 1);
        }
    }

    // Return the calculated product
    return (void *) product;
}
