void destroyLinkedList(struct LinkedList *list) {
  pthread_mutex_destroy(&list->mutex);
  free(list);
}

int addEntryToList(struct LinkedList *list, NFAPI_CRC_INDICATION_PDU_T entry) {
  int ret = 0;
  pthread_mutex_lock(&list->mutex);
  if (list->size == MAX_LIST_SIZE) {
    LOG_ERROR("List size limit reached, removing oldest entry\n");
    // Remove oldest entry from the list
    NFAPI_CRC_INDICATION_PDU_T *oldestEntry = list->head;
    list->head = list->head->next;
    free(oldestEntry);
  }
  NFAPI_CRC_INDICATION_PDU_T *newEntry = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
  if (newEntry == NULL) {
    ret = -1; // Out of memory
  } else {
    newEntry->RX_UE_INFORMATION_TAG = entry.RX_UE_INFORMATION_TAG;
    newEntry->RNTI = entry.RNTI;
    newEntry->CRCFLAG = entry.CRCFLAG;
    list->size++;
    if (list->head == NULL) {
      // Empty list, add as head and tail
      list->head = newEntry;
      list->tail = newEntry;
    } else {
      // Add to the end of the list
      list->tail->next = newEntry;
      list->tail = newEntry;
    }
  }
  pthread_mutex_unlock(&list->mutex);
  return ret;
}

void removeEntryFromList(struct LinkedList *list, NFAPI_CRC_INDICATION_PDU_T *entry) {
  pthread_mutex_lock(&list->mutex);
  if (list->head == entry) {
    list->head = entry->next;
  }
  if (list->tail == entry) {
    list->tail = entry->prev;
  }
  entry->prev->next = entry->next;
  entry->next->prev = entry->prev;
  free(entry);
  list->size--;
  pthread_mutex_unlock(&list->mutex);
}

