struct Session {
    int id;
    int authLevel;
    string lastActivity;
    map<string, string> prefs;
};
class SessionsManager {
public:
    SessionsManager();
    ~SessionsManager();
    void addSession(int id, int authLevel, string lastActivity, const map<string, string>& prefs);
    void updateSession(int id, const map<string, string>& newPrefs);
    bool getSession(int id, Session& session);
    void deleteSession(int id);
    int size();
private:
    mutex sessionsMutex;
    atomic_bool stopFlag;
    condition_variable cv;
    queue<pair<int, Session>> sessionsQueue;
    unordered_map<int, Session> sessionsMap;
};
SessionsManager::SessionsManager() {
    stopFlag = false;
}
SessionsManager::~SessionsManager() {
    if (sessionsMutex.try_lock()) {
        cv.notify_all();
        while (!sessionsQueue.empty()) {
            sessionsQueue.pop();
        }
        sessionsMap.clear();
        sessionsMutex.unlock();
    }
}
void SessionsManager::addSession(int id, int authLevel, string lastActivity, const map<string, string>& prefs) {
    if (sessionsMutex.try_lock()) {
        cv.notify_all();
        while (!sessionsQueue.empty()) {
            sessionsQueue.pop();
        }
        Session session = { id, authLevel, lastActivity, prefs };
        sessionsMap[id] = move(session);
        sessionsMutex.unlock();
    } else {
        // handle error
    }
}
void SessionsManager::updateSession(int id, const map<string, string>& newPrefs) {
    if (sessionsMutex.try_lock()) {
        cv.notify_all();
        while (!sessionsQueue.empty()) {
            sessionsQueue.pop();
        }
        Session& session = sessionsMap[id];
        for (auto it = newPrefs.begin(); it != newPrefs.end(); ++it) {
            session.prefs[it->first] = it->second;
        }
        sessionsMutex.unlock();
    } else {
        // handle error
    }
}
bool SessionsManager::getSession(int id, Session& session) {
    if (sessionsMutex.try_lock()) {
        cv.notify_all();
        while (!sessionsQueue.empty()) {
            sessionsQueue.pop();
        }
        auto it = sessionsMap.find(id);
        if (it != sessionsMap.end()) {
            session = move(it->second);
            sessionsMutex.unlock();
            return true;
        } else {
            sessionsMutex.unlock();
            return false;
        }
    } else {
        // handle error
    }
}
void SessionsManager::deleteSession(int id) {
    if (sessionsMutex.try_lock()) {
        cv.notify_all();
        while (!sessionsQueue.empty()) {
            sessionsQueue.pop();
        }
        auto it = sessionsMap.find(id);
        if (it != sessionsMap.end()) {
            sessionsMap.erase(it);
        }
        sessionsMutex.unlock();
    } else {
        // handle error
    }
}
int SessionsManager::size() {
    if (sessionsMutex.try_lock()) {
        cv.notify_all();
        while (!sessionsQueue.empty()) {
            sessionsQueue.pop();
        }
        auto size = sessionsMap.size();
        sessionsMutex.unlock();
        return size;
    } else {
        // handle error
    }
}
int main() {
    SessionsManager manager;
    int id = 0;
    int authLevel = 1;
    string lastActivity = "2022-01-01T00:00:00Z";
    map<string, string> prefs = { {"theme", "dark"}, {"language", "en"} };
    manager.addSession(id, authLevel, lastActivity, prefs);
    id++;
    authLevel++;
    lastActivity = "2022-01-02T00:00:00Z";
    prefs["theme"] = "light";
    manager.updateSession(id, prefs);
    map<string, string> newPrefs;
    newPrefs["language"] = "es";
    manager.updateSession(id, newPrefs);
    Session session;
    manager.getSession(id, session);
    cout << "Session: " << id << endl;
    cout << "Auth level: " << session.authLevel << endl;
    cout << "Last activity: " << session.lastActivity << endl;
    for (auto it = session.prefs.begin(); it != session.prefs.end(); ++it) {
        cout << it->first << ": " << it->second << endl;
    }
