// A structure to represent a session ID and its associated data
typedef struct {
    uint64_t sessionID; // The unique identifier for the session
    char *peerConnections[10]; // An array of pointers to PeerConnectionInfo structures
    int numPeers; // The number of peers in the session
    QoSParameters qosParams; // A structure containing the Quality of Service parameters for the session
} SessionData;

// A function to initialize a dynamic hash table for managing sessions
void initSessionTable(SessionData **table, int size) {
    // Allocate memory for the hash table and its associated data structures
    *table = malloc(size * sizeof(SessionData));
    memset(*table, 0, size * sizeof(SessionData));
}

// A function to add a session to the dynamic hash table
void addSession(SessionData **table, uint64_t sessionID, char *peerConnections[10], int numPeers, QoSParameters qosParams) {
    // Check if the session ID is already in use and error if it is
    for (int i = 0; i < size; i++) {
        if ((*table)[i].sessionID == sessionID) {
            printf("Error: duplicate session ID\n");
            return;
        }
    }

    // Add the new session to the hash table and update its associated data structures
    for (int i = 0; i < size; i++) {
        if ((*table)[i].sessionID == 0) {
            (*table)[i].sessionID = sessionID;
            strcpy((*table)[i].peerConnections, peerConnections);
            (*table)[i].numPeers = numPeers;
            memcpy(&(*table)[i].qosParams, qosParams, sizeof(QoSParameters));
            break;
        }
    }
}

// A function to retrieve a session from the dynamic hash table
SessionData *getSession(SessionData **table, uint64_t sessionID) {
    // Check if the session ID is in use and return its associated data structure if it is
    for (int i = 0; i < size; i++) {
        if ((*table)[i].sessionID == sessionID) {
            return &(*table)[i];
        }
    }
    return NULL;
}

// A function to update a session in the dynamic hash table
void updateSession(SessionData **table, uint64_t sessionID, char *peerConnections[10], int numPeers, QoSParameters qosParams) {
    // Retrieve the session data structure from the hash table and update its associated data structures
    SessionData *session = getSession(table, sessionID);
    if (session == NULL) {
        printf("Error: session not found\n");
        return;
    }
    strcpy(session->peerConnections, peerConnections);
    session->numPeers = numPeers;
    memcpy(&session->qosParams, qosParams, sizeof(QoSParameters));
}

// A function to remove a session from the dynamic hash table
void removeSession(SessionData **table, uint64_t sessionID) {
    // Retrieve the session data structure from the hash table and set its ID to 0
    SessionData *session = getSession(table, sessionID);
    if (session == NULL) {
        printf("Error: session not found\n");
        return;
    }
    memset(&session->sessionID, 0, sizeof(uint64_t));
}
