#define MAX_RAN_INSTANCES 100 // maximum number of RAN instances supported
#define MAX_MAC_EI_LEN 64 // maximum length of a MAC entity identifier (MAC-EI)
#define MAX_IP_ADDR_LEN 256 // maximum length of an IP address string
#define MAX_PORT_NUM 65535 // maximum port number supported

typedef struct ran_instance {
    char mac_ei[MAX_MAC_EI_LEN]; // MAC entity identifier (MAC-EI)
    struct in_addr ip_addr; // IP address
    uint16_t port_num; // port number
} ran_instance_t;

int configure_ran(const char *mac_ei, const char *ip_addr, uint16_t port_num) {
    int ret = 0;
    struct ifaddrs *ifaddr, *ifa;
    void *iname;
    int family;
    ran_instance_t ran[MAX_RAN_INSTANCES];
    size_t num_ran = 0;

    // validate input parameters
    if (!mac_ei || !ip_addr || port_num > MAX_PORT_NUM) {
        return -1;
    }

    // get the list of network interfaces
    ret = getifaddrs(&ifaddr);
    if (ret < 0) {
        perror("getifaddrs failed");
        return ret;
    }

    for (ifa = ifaddr, num_ran = 0; ifa != NULL && num_ran < MAX_RAN_INSTANCES; ifa = ifa->ifa_next) {
        // make sure the interface is up and running
        if (!(ifa->ifa_flags & IFF_UP)) continue;

        // get the interface name
        iname = ifa->ifa_name;

        // ignore non-IP interfaces
        family = ifa->ifa_addr->sa_family;
        if (family != AF_INET && family != AF_INET6) continue;

        // ignore loopback interface
        if (!strcmp(iname, "lo")) continue;

        // ignore virtual interfaces
        if ((ifa->ifa_flags & IFF_LOOPBACK)) continue;

        // configure the RAN instance
        strncpy(ran[num_ran].mac_ei, mac_ei, MAX_MAC_EI_LEN);
        ran[num_ran].ip_addr = *((struct in_addr *) ifa->ifa_addr);
        ran[num_ran].port_num = port_num;
        num_ran++;
    }

    // free memory allocated by getifaddrs
    freeifaddrs(ifaddr);

    // return error code if no interfaces were found
    if (num_ran == 0) {
        fprintf(stderr, "No network interfaces found\n");
        return -1;
    }

    // configure each RAN instance
    for (size_t i = 0; i < num_ran; i++) {
        ran_instance_t *cur_ran = &ran[i];

        // validate the MAC-EI and IP address
        if (!mac_ei_is_valid(cur_ran->mac_ei) || !ip_addr_is_valid(&cur_ran->ip_addr)) {
            fprintf(stderr, "Invalid MAC entity identifier or IP address\n");
            return -1;
        }

        // validate the port number
        if (cur_ran->port_num < 1 || cur_ran->port_num > MAX_PORT_NUM) {
            fprintf(stderr, "Invalid port number\n");
            return -1;
        }

        // configure the interface
        // ...
    }

    // success
    return 0;
}

int mac_ei_is_valid(const char *mac_ei) {
    if (!mac_ei || strlen(mac_ei) > MAX_MAC_EI_LEN) {
        return 0;
    }
    // validate the MAC-EI string
    // ...
    return 1;
}

int ip_addr_is_valid(const struct in_addr *ip_addr) {
    if (!ip_addr || !inet_ntop(AF_INET, ip_addr, buf, sizeof(buf))) {
        return 0;
    }
    // validate the IP address string
    // ...
    return 1;
}
