        printf("Invalid input parameters\n");
        return NULL;
    }

    // Calculate the size of each data structure
    int record_size = sizeof(Record);
    long offset_array_size = (offset_max - offset_min + 1) * sizeof(long);
    int key_array_size = (key_max - key_min + 1) * sizeof(int);

    // Allocate memory for each data structure
    void* offset_array = malloc(offset_array_size);
    void* key_array = malloc(key_array_size);
    void* record_array = malloc(num_records * record_size);

    // Initialize the index variable to keep track of the current position in the records array
    int curr_record = 0;

    // Set the value of each record's int field to a random value within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        Record* record = record_array + curr_record * record_size;
        record->value = rand() % (key_max - key_min + 1) + key_min;
        curr_record++;
    }

    // Return the allocated memory structures and indices
    return (void*)offset_array, (void*)key_array, (void*)record_array;
}
