// Define the structure for a record
typedef struct {
    int value;
} record;

// Define the structure for an NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    unsigned char rx_ue_information_tag;
    unsigned short rnti;
    unsigned char crc_indication_rel8_tag;
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the function to create and initialize the data structures
void create_data_structures(int num_records) {
    // Validate the input value for number of records
    if (num_records <= 0 || num_records > MAX_RECORD) {
        printf("Invalid input: number of records must be a positive integer less than or equal to %d\n", MAX_RECORD);
        return;
    }

    // Dynamically allocate memory for the offset, key, and record arrays
    int *offset = (int *)malloc(num_records * sizeof(int));
    int *key = (int *)malloc(num_records * sizeof(int));
    record *records = (record *)malloc(num_records * sizeof(record));

    // Initialize the index for tracking the current position in the records array
    int index = 0;

    // Set the value of each record's int field to a random value within a specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        offset[i] = rand() % MAX_OFFSET;
        key[i] = rand() % MAX_KEY;
        records[i].value = rand() % INT_MAX;
    }

    // Populate the list of NFAPI_CRC_INDICATION_PDU_T structures
    for (int i = 0; i < num_records; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.rx_ue_information_tag = RX_UE_INFORMATION_TAG;
        pdu.rnti = rand() % MAX_RNTI;
        pdu.crc_indication_rel8_tag = CRCFLAG;
        pdu.crcflag = records[i].value;
    }

    // Free the memory allocated for the offset, key, and record arrays
    free(offset);
    free(key);
    free(records);
}
