struct UserProfile {
    uint64_t user_id;
    time_t creation_timestamp;
    std::list<Activity> recent_activities;
    std::vector<Notification> notification_history;
};

class ProfileManager {
public:
    void addUser(uint64_t user_id, const std::string& username);
    void removeUser(uint64_t user_id);
    bool updateUser(uint64_t user_id, const std::string& username);
    UserProfile* getUserProfile(uint64_t user_id);

private:
    std::unordered_map<uint64_t, UserProfile> profiles;
};

class ProfileSerializer {
public:
    void serialize(const UserProfile& profile, std::string& output) const;
    void deserialize(const std::string& input, UserProfile& profile);
};

void ProfileManager::addUser(uint64_t user_id, const std::string& username) {
    profiles.insert({user_id, {user_id, 0, {}, {}}});
}

void ProfileManager::removeUser(uint64_t user_id) {
    profiles.erase(user_id);
}

bool ProfileManager::updateUser(uint64_t user_id, const std::string& username) {
    auto it = profiles.find(user_id);
    if (it == profiles.end()) return false;
    it->second.username = username;
    return true;
}

UserProfile* ProfileManager::getUserProfile(uint64_t user_id) {
    auto it = profiles.find(user_id);
    if (it == profiles.end()) return nullptr;
    return &it->second;
}

void ProfileSerializer::serialize(const UserProfile& profile, std::string& output) const {
    output += std::to_string(profile.user_id) + ";";
    output += std::to_string(profile.creation_timestamp) + ";";
    for (auto activity : profile.recent_activities) {
        output += std::to_string(activity) + ";";
    }
    for (auto notification : profile.notification_history) {
        output += std::to_string(notification) + ";";
    }
}

void ProfileSerializer::deserialize(const std::string& input, UserProfile& profile) const {
    size_t pos = 0;
    pos = input.find(';', pos);
    if (pos == std::string::npos) return;
    profile.user_id = stoul(input.substr(pos + 1));
    pos = input.find(';', pos);
    if (pos == std::string::npos) return;
    profile.creation_timestamp = stoull(input.substr(pos + 1));
    while ((pos = input.find(';', pos)) != std::string::npos) {
        size_t next_pos = input.find(';', pos + 1);
        if (next_pos == std::string::npos) return;
        profile.recent_activities.push_back(stoul(input.substr(pos + 1, next_pos - pos)));
    }
    while ((pos = input.find(';', pos)) != std::string::npos) {
        size_t next_pos = input.find(';', pos + 1);
        if (next_pos == std::string::npos) return;
        profile.notification_history.push_back(stoul(input.substr(pos + 1, next_pos - pos)));
    }
}
