    // Check if the list is full and needs to be resized
    if (list->size >= list->capacity) {
        size_t newCapacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU** newBuffer = realloc(list->buffer, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU*));
        if (newBuffer == NULL) {
            return false;
        }

        list->capacity = newCapacity;
        list->buffer = newBuffer;
    }

    // Add the new PDU to the end of the list
    list->buffer[list->size++] = pdu;

    return true;
}

void removeNFAPI_CRC_INDICATION_PDU(DynamicList* list, size_t index) {
    if (index >= list->size) {
        return;
    }

    // Shift all elements at indices greater than the specified index to the left by one
    for (size_t i = index + 1; i < list->size; ++i) {
        list->buffer[i - 1] = list->buffer[i];
    }

    // Decrement the size of the list
    --list->size;
}

size_t getListSize(const DynamicList* list) {
    return list->size;
}

NFAPI_CRC_INDICATION_PDU** getListBuffer(const DynamicList* list) {
    return list->buffer;
}

bool isFull(const DynamicList* list) {
    return list->size >= list->capacity;
}

void clear(DynamicList* list) {
    list->size = 0;
