void* my_alloc(size_t size) {
    // Use a fixed-size pool of 2 MB to reduce memory allocation overhead
    static char mem[2097152];
    static int next_free;

    if (next_free + size > 2097152) {
        return NULL;
    }

    void* ptr = &mem[next_free];
    next_free += size;

    return ptr;
}

