static CrcIndicationList list = {NULL, 0, 1000};

// Lock to protect concurrent access to the list
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to insert a new element into the list
void insert(NFAPI_CRC_INDICATION_PDU_T* data) {
    // Lock the mutex before modifying the list
    pthread_mutex_lock(&lock);

    if (list.size == list.capacity) {
        // If the list is full, double its capacity and reallocate memory
        list.data = realloc(list.data, list.capacity * 2 * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        assert(list.data != NULL);
        list.capacity *= 2;
    }

    // Copy the new data into the list at the end of the current data
    memcpy(&list.data[list.size], data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list.size++;

    pthread_mutex_unlock(&lock);
}

// Function to remove an element from the list by its index
void remove(int index) {
    // Lock the mutex before modifying the list
    pthread_mutex_lock(&lock);

    if (index >= list.size) {
        return;
    }

    // Shift all elements after the specified index one position to the left
    for (int i = index; i < list.size - 1; i++) {
        memcpy(&list.data[i], &list.data[i + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T));
