// Function to process a large, heterogeneous network traffic trace file
void process_trace_file(const char *filename) {
    // Open the trace file for reading
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error: Could not open trace file\n");
        return;
    }

    // Allocate memory for a list of TCP_HEADER structures
    struct TCP_HEADER *tcp_headers = malloc(sizeof(struct TCP_HEADER));
    if (tcp_headers == NULL) {
        printf("Error: Could not allocate memory for TCP header structure\n");
