    if (index < 0 || index >= num_elements) {
        printf("Error: Invalid index %d\n", index);
        exit(1);
    }
    pthread_mutex_lock(&lock);
    crc_indication_pdu_list = realloc(crc_indication_pdu_list, (num_elements - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
