    rx_pdu->pdu = malloc(length);
    if (rx_pdu->pdu == NULL) {
        // handle memory allocation failure gracefully
        return;
    }

    size_t i;
    for (i = 0; i < length; i++) {
        rx_pdu->pdu[i] = i % 256;
    }
}

void reset_rx_pdu(NFAPI_RX_PDU_T* rx_pdu) {
    // reallocate memory if necessary to reset the array of PDU structures
    free(rx_pdu->pdu);
    rx_pdu->pdu = malloc(sizeof(RRC_PDU_T));
    if (rx_pdu->pdu == NULL) {
        // handle memory allocation failure gracefully
        return;
    }
}
