// Function to dynamically allocate memory for an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* alloc_array(size_t size, bool use_seed) {
    // Allocate memory for the array and initialize all elements to NULL
    NFAPI_CRC_INDICATION_PDU_T *arr = malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!arr) {
        fprintf(stderr, "Error: Failed to allocate memory for CRC array\n");
        return NULL;
    }

    // Initialize each element with a unique RNTI value and random CRC generation flag
    unsigned int rnti = 1;
    for (size_t i = 0; i < size; i++) {
        arr[i].RX_UE_INFORMATION_TAG.RNTI = rnti++;
        arr[i].CRCFLAG = use_seed ? random() % 2 : true;
    }

    return arr;
}

// Function to free memory allocated by alloc_array
void free_array(NFAPI_CRC_INDICATION_PDU_T *arr, size_t size) {
    // Free all elements in the array and reset the pointer to NULL
    for (size_t i = 0; i < size; i++) {
        free(arr[i].RX_UE_INFORMATION_TAG.RNTI);
    }
    free(arr);
