struct List {
    size_t size;  // Number of elements in the list
    size_t capacity;  // Maximum number of elements that can be stored in the list
    NFAPI_CRC_INDICATION_PDU_T* data;  // Pointer to the array of NFAPI_CRC_INDICATION_PDU_T structures
};

// Function to dynamically resize the list based on current demand
void dynamicResize(struct List* list, size_t newCapacity) {
    if (newCapacity > list->capacity) {  // If the new capacity is greater than the current capacity
        NFAPI_CRC_INDICATION_PDU_T* newData = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * newCapacity);
        memcpy(newData, list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * list->size);
        free(list->data);
        list->data = newData;
        list->capacity = newCapacity;
    }
}

// Function to populate the list with N elements while considering memory constraints and performance implications
void populateList(struct List* list, size_t n) {
    for (size_t i = 0; i < n; ++i) {
