        if (list->size == list->capacity) {  // If the list is full, resize it
            dynamicResize(list, list->capacity * 2);
        }
        list->data[list->size++] = pdu;
    }
}

// Function to ensure proper deallocation of resources and handle concurrent access from multiple threads to prevent data corruption and ensure thread safety
void cleanupList(struct List* list) {
