void manageCrcIndicationPdus(CrcIndicationPdu *pdus, size_t numPdus) {
    // Initialize the list with the default maximum size if no configuration is available
    size_t maxListSize = DEFAULT_LIST_SIZE;
    if (numPdus > 0) {
        // Fetch the maximum list size from the external configuration service
        maxListSize = getExternalConfigValue("max_list_size");
        if (maxListSize <= 0) {
            maxListSize = DEFAULT_LIST_SIZE;
        }
    }

    // Create a lock for thread safety
    pthread_mutex_t listLock;
    pthread_mutex_init(&listLock, NULL);

    // Create the list of CrcIndicationPdu structures and initialize its size
    CrcIndicationPdu *crcPdus = malloc(sizeof(CrcIndicationPdu) * maxListSize);
    size_t crcPdusSize = 0;

    // Iterate over the input pdus and add them to the list, ensuring proper memory management and safe deallocation of resources
    for (size_t i = 0; i < numPdus; i++) {
        pthread_mutex_lock(&listLock);
        if (crcPdusSize >= maxListSize) {
            // Check if the list needs to be resized dynamically based on traffic patterns
            size_t newMaxListSize = maxListSize * 2;
            CrcIndicationPdu *newCrcPdus = realloc(crcPdus, sizeof(CrcIndicationPdu) * newMaxListSize);
            if (newCrcPdus != NULL) {
                maxListSize = newMaxListSize;
                crcPdus = newCrcPdus;
            } else {
                // If the reallocation fails, limit the list size to prevent resource exhaustion
                maxListSize = crcPdusSize;
            }
        }

        // Add the current pdu to the list and increment its size
        crcPdus[crcPdusSize].pdu = pdus[i];
        crcPdusSize++;
        pthread_mutex_unlock(&listLock);
    }

    // Validate that all RNTIs fall within the specified range and handle any out-of-range values
    for (size_t i = 0; i < crcPdusSize; i++) {
        if (crcPdus[i].pdu.rxUeInformationTag.rnti < MIN_RNTI_VALUE || crcPdus[i].pdu.rxUeInformationTag.rnti > MAX_RNTI_VALUE) {
            // Log an error message and cleanly exit the function if an out-of-range RNTI is encountered
            logError("Out-of-range RNTI value encountered in CRC indication PDU");
            pthread_mutex_destroy(&listLock);
            free(crcPdus);
            return;
        }
    }

    // Implement a fallback mechanism that uses default values if the external service is unavailable or if the received values are inconsistent
    size_t defaultMaxListSize = DEFAULT_LIST_SIZE;
    if (maxListSize <= 0) {
        maxListSize = defaultMaxListSize;
    }

    // Implement a mechanism for dynamic resizing of the list to maintain optimal performance under different workloads, balancing memory usage, thread safety, and performance
    size_t currentListSize = crcPdusSize;
    while (currentListSize > maxListSize) {
        pthread_mutex_lock(&listLock);
        CrcIndicationPdu *newCrcPdus = realloc(crcPdus, sizeof(CrcIndicationPdu) * (maxListSize * 2));
        if (newCrcPdus != NULL) {
            maxListSize *= 2;
            currentListSize /= 2;
            crcPdus = newCrcPdus;
        } else {
            // If the reallocation fails, limit the list size to prevent resource exhaustion
            maxListSize = defaultMaxListSize;
            currentListSize = maxListSize;
        }
        pthread_mutex_unlock(&listLock);
    }

    // Implement a mechanism for monitoring the list's growth and shrink it appropriately based on observed traffic patterns, minimizing unnecessary allocations and deallocations
    while (currentListSize < maxListSize) {
        pthread_mutex_lock(&listLock);
        if (crcPdusSize > 0 && crcPdus[crcPdusSize - 1].pdu.rxUeInformationTag.rnti == 0) {
