            } else {
                // If the reallocation fails, limit the list size to prevent resource exhaustion
                currentListSize = maxListSize;
            }
        }
        pthread_mutex_unlock(&listLock);
    }

    // Implement a mechanism for handling thread safety while accessing and modifying the list of CrcIndicationPdu structures
    pthread_mutex_destroy(&listLock);

    // Free the memory used by the list of CrcIndicationPdu structures
