// Define the collection type
typedef struct {
    TX_PACKET_INFO *data;
    size_t capacity;
    size_t count;
} TX_PACKET_INFO_COLLECTION;

// Initialize an empty collection
void tx_packet_info_collection_init(TX_PACKET_INFO_COLLECTION *collection) {
    collection->data = NULL;
    collection->capacity = 0;
    collection->count = 0;
}

// Add a new entry to the collection
void tx_packet_info_collection_add(TX_PACKET_INFO_COLLECTION *collection, TX_PACKET_INFO *entry) {
    // Check if we need to resize the collection
    if (collection->count == collection->capacity) {
        // Resize the collection by a factor of 2
        size_t new_capacity = collection->capacity ? collection->capacity * 2 : 16;
        TX_PACKET_INFO *new_data = realloc(collection->data, new_capacity * sizeof(*entry));
        if (!new_data) {
            // Error: out of memory
            return;
        }
        collection->data = new_data;
        collection->capacity = new_capacity;
    }

    // Add the entry to the collection
    memcpy(&collection->data[collection->count], entry, sizeof(*entry));
    collection->count++;
}

// Update an existing entry in the collection based on UE_ID
bool tx_packet_info_collection_update(TX_PACKET_INFO_COLLECTION *collection, uint32_t UE_ID, TX_PACKET_INFO *entry) {
    // Find the index of the entry with the matching UE_ID
    size_t i;
    for (i = 0; i < collection->count; i++) {
        if (collection->data[i].UE_ID == UE_ID) {
            break;
        }
    }

    // If the entry was not found, return false
    if (i == collection->count) {
        return false;
    }

    // Update the entry with the new values
    memcpy(&collection->data[i], entry, sizeof(*entry));
    return true;
}

// Remove an entry from the collection based on UE_ID
bool tx_packet_info_collection_remove(TX_PACKET_INFO_COLLECTION *collection, uint32_t UE_ID) {
    // Find the index of the entry with the matching UE_ID
    size_t i;
    for (i = 0; i < collection->count; i++) {
        if (collection->data[i].UE_ID == UE_ID) {
            break;
        }
    }

    // If the entry was not found, return false
    if (i == collection->count) {
        return false;
    }

    // Remove the entry by shifting all subsequent entries back one index
    for (size_t j = i; j < collection->count - 1; j++) {
        memcpy(&collection->data[j], &collection->data[j + 1], sizeof(TX_PACKET_INFO));
    }
    collection->count--;

    // If the collection is now half full or less, resize it down by a factor of 2
    if (collection->count < collection->capacity / 2) {
        size_t new_capacity = collection->capacity ? collection->capacity / 2 : 0;
        TX_PACKET_INFO *new_data = realloc(collection->data, new_capacity * sizeof(*entry));
        if (!new_data) {
            // Error: out of memory
            return false;
        }
        collection->data = new_data;
        collection->capacity = new_capacity;
    }

    return true;
}

// Iterate over the entries in the collection
void tx_packet_info_collection_iter(TX_PACKET_INFO_COLLECTION *collection, void (*callback)(TX_PACKET_INFO *)) {
    for (size_t i = 0; i < collection->count; i++) {
        callback(&collection->data[i]);
    }
}

// Free the memory used by the collection
void tx_packet_info_collection_free(TX_PACKET_INFO_COLLECTION *collection) {
    free(collection->data);
    collection->data = NULL;
    collection->capacity = 0;
    collection->count = 0;
}']

