    RRC_PDU_T *rrc_pdu;
} FrameInfo;

// Function to initialize a list of frames
int initFrames(FrameInfo **frames, int num_frames, unsigned char *encryption_key, unsigned char *iv) {
    // Check input parameters
    if (frames == NULL || num_frames < 0) {
        return -1;
    }

    // Allocate memory for the list of frames
    FrameInfo **frame_list = malloc(sizeof(FrameInfo *) * num_frames);
    if (frame_list == NULL) {
        return -2;
    }

    // Initialize each frame with a valid RX_FRAME_INFO_TAG and dynamically allocated RRC_PDU_T
    for (int i = 0; i < num_frames; i++) {
        // Allocate memory for the RRC_PDU_T structure
        RRC_PDU_T *rrc_pdu = malloc(sizeof(RRC_PDU_T));
        if (rrc_pdu == NULL) {
            free(frame_list);
            return -3;
        }

        // Initialize the RX_FRAME_INFO_TAG for this frame
        NFAPI_RX_PDU_T *rx_pdu = malloc(sizeof(NFAPI_RX_PDU_T));
        if (rx_pdu == NULL) {
            free(rrc_pdu);
            free(frame_list);
            return -4;
        }

        // Populate the RRC_PDU_T structure with a sequence of bytes that simulate a valid RRC message
        rrc_pdu->payload = malloc(sizeof(unsigned char) * 1024);
        if (rrc_pdu->payload == NULL) {
            free(rx_pdu);
            free(rrc_pdu);
            free(frame_list);
            return -5;
        }
        for (int j = 0; j < 1024; j++) {
            rrc_pdu->payload[j] = rand() % 256;
        }

        // Encrypt the RRC message using AES-GCM
        if (encryption_key != NULL && iv != NULL) {
            EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
            if (ctx == NULL) {
                free(rrc_pdu->payload);
                free(rx_pdu);
                free(rrc_pdu);
                free(frame_list);
                return -6;
            }
            EVP_EncryptInit(ctx, EVP_aes_128_gcm(), encryption_key, iv);
            if (EVP_EncryptUpdate(ctx, rrc_pdu->payload, 1024) != 1024) {
                free(rrc_pdu->payload);
                free(rx_pdu);
                free(rrc_pdu);
                free(frame_list);
                EVP_CIPHER_CTX_free(ctx);
                return -7;
            }
            if (EVP_EncryptFinal(ctx, rrc_pdu->payload, 1024) != 1024) {
                free(rrc_pdu->payload);
                free(rx_pdu);
                free(rrc_pdu);
                free(frame_list);
                EVP_CIPHER_CTX_free(ctx);
                return -8;
            }
            EVP_CIPHER_CTX_free(ctx);
        }

        // Calculate the HMAC for integrity verification
        unsigned char hmac[32];
        if (encryption_key != NULL && iv != NULL) {
            HMAC(EVP_sha256(), encryption_key, 16, rrc_pdu->payload, 1024, hmac, NULL);
        }

        // Store the initialized frame information in the list
        FrameInfo *frame = malloc(sizeof(FrameInfo));
        if (frame == NULL) {
            free(rrc_pdu->payload);
            free(rx_pdu);
            free(rrc_pdu);
            free(frame_list);
            return -9;
        }
        frame->rx_pdu = rx_pdu;
        frame->rrc_pdu = rrc_pdu;
        frame_list[i] = frame;
    }

    // Return the initialized list of frames
    *frames = frame_list;
    return num_frames;
}

// Function to clean up the allocated memory for a list of frames
void freeFrames(FrameInfo **frames) {
    if (frames == NULL || *frames == NULL) {
        return;
    }

    // Free the RRC_PDU_T structures
    for (int i = 0; i < num_frames; i++) {
        FrameInfo *frame = (*frames)[i];
        if (frame->rrc_pdu != NULL) {
            free(frame->rrc_pdu);
        }
        free(frame);
    }

    // Free the list of frames
    free(*frames);
}
