void populate_list(record* list, int size, char** string_array) {
    // Check if the input size is valid
    assert(size > 0 && size <= MAX_LIST_SIZE);

    // Initialize a hash set to store the unique strings
    HashSet* unique_strings = createHashSet();

    // Populate the hash set with the strings from the array
    for (int i = 0; i < size; ++i) {
        char* string = string_array[i];
        if (!string || strlen(string) == 0) continue;
        if (!hashSetContains(unique_strings, string)) {
            hashSetAdd(unique_strings, string);
