    // Check if the input size is valid
    assert(size > 0 && size <= MAX_LIST_SIZE);

    // Validate each element in the list for uniqueness and consistency
    for (int i = 0; i < size; ++i) {
        record* current = &list[i];
        if (!current->string || strlen(current->string) == 0) continue;
        if (current->shape.type != SHAPE_TYPE_NONE &&
            current->shape.dimensions <= 0.0f) {
