// Function to add a new neighboring cell to the list of neighbors in a NetworkInterfaceConfig structure
void addNeighbor(int interfaceId, int cellId) {
    pthread_mutex_lock(&mutex);
    // Find the NetworkInterfaceConfig structure corresponding to the interface ID
    int i = findInterfaceIndex(interfaceId);
    if (i < 0) {
        fprintf(stderr, "Error: Could not find NetworkInterfaceConfig for interface %d\n", interfaceId);
        pthread_mutex_unlock(&mutex);
        return;
    }
    // Allocate memory for the new NeighborCellInfo structure
    NeighborCellInfo *newNeighbor = (NeighborCellInfo *)malloc(sizeof(NeighborCellInfo));
    if (!newNeighbor) {
        fprintf(stderr, "Error: Could not allocate memory for new neighbor cell\n");
        pthread_mutex_unlock(&mutex);
        return;
    }
    // Initialize the new NeighborCellInfo structure
    newNeighbor->cellId = cellId;
    newNeighbor->distance = 0.0f;
    // Add the new neighbor to the list of neighbors in the NetworkInterfaceConfig structure
    configs[i]->neighbors = (NeighborCellInfo *)realloc(configs[i]->neighbors, sizeof(NeighborCellInfo) * (configs[i]->numNeighbors + 1));
    if (!configs[i]->neighbors) {
        fprintf(stderr, "Error: Could not reallocate memory for neighbor cell list\n");
        pthread_mutex_unlock(&mutex);
        return;
    }
    configs[i]->neighbors[configs[i]->numNeighbors] = newNeighbor;
    configs[i]->numNeighbors++;
    pthread_mutex_unlock(&mutex);
}

// Function to remove a neighboring cell from the list of neighbors in a NetworkInterfaceConfig structure
void removeNeighbor(int interfaceId, int cellId) {
    pthread_mutex_lock(&mutex);
    // Find the NetworkInterfaceConfig structure corresponding to the interface ID
    int i = findInterfaceIndex(interfaceId);
    if (i < 0) {
        fprintf(stderr, "Error: Could not find NetworkInterfaceConfig for interface %d\n", interfaceId);
        pthread_mutex_unlock(&mutex);
        return;
    }
    // Find the index of the neighboring cell to remove in the list of neighbors
    int j = -1;
    for (int k = 0; k < configs[i]->numNeighbors; k++) {
        if (configs[i]->neighbors[k]->cellId == cellId) {
            j = k;
            break;
        }
    }
    if (j < 0) {
        fprintf(stderr, "Error: Could not find neighboring cell %d for interface %d\n", cellId, interfaceId);
        pthread_mutex_unlock(&mutex);
        return;
    }
    // Remove the neighboring cell from the list of neighbors
    configs[i]->numNeighbors--;
    NeighborCellInfo *newNeighbors = (NeighborCellInfo *)malloc(sizeof(NeighborCellInfo) * configs[i]->numNeighbors);
    if (!newNeighbors) {
        fprintf(stderr, "Error: Could not allocate memory for neighbor cell list\n");
        pthread_mutex_unlock(&mutex);
        return;
    }
    memcpy(newNeighbors, configs[i]->neighbors, sizeof(NeighborCellInfo) * j);
    memcpy(newNeighbors + j, configs[i]->neighbors + j + 1, sizeof(NeighborCellInfo) * (configs[i]->numNeighbors - j));
    free(configs[i]->neighbors);
    configs[i]->neighbors = newNeighbors;
    pthread_mutex_unlock(&mutex);
}

// Function to update the configuration for Sounding Reference Signal parameters in a NetworkInterfaceConfig structure
void updateSRSParameters(int interfaceId, int srsBandwidth, int srsPeriodicity) {
    pthread_mutex_lock(&mutex);
    // Find the NetworkInterfaceConfig structure corresponding to the interface ID
    int i = findInterfaceIndex(interfaceId);
    if (i < 0) {
        fprintf(stderr, "Error: Could not find NetworkInterfaceConfig for interface %d\n", interfaceId);
        pthread_mutex_unlock(&mutex);
        return;
    }
    // Update the Sounding Reference Signal parameters in the NetworkInterfaceConfig structure
    configs[i]->srsBandwidth = srsBandwidth;
    configs[i]->srsPeriodicity = srsPeriodicity;
    pthread_mutex_unlock(&mutex);
}

// Function to find the index of a NetworkInterfaceConfig structure corresponding to an interface ID
int findInterfaceIndex(int interfaceId) {
    for (int i = 0; i < numInterfaces; i++) {
        if (interfaceIds[i] == interfaceId) {
            return i;
        }
    }
    return -1;
}
