#define MAX_KEY_VALUE 100
#define RECORD_INITIALIZER {0}
#define NUM_RECORDS 16

// Custom record structure with a single integer value
typedef struct {
    int value;
} record;

// Function to manage memory allocation and initialization for three data structures
void initDataStructures(size_t offsetSize, size_t keySize, size_t numRecords) {
    // Allocate memory dynamically for all arrays and structures based on user-provided sizes
    long* offsets = (long*)malloc(offsetSize * sizeof(long));
    int* keys = (int*)malloc(keySize * sizeof(int));
    record* records = (record*)calloc(numRecords, sizeof(record));

    // Initialize the offset array with sequential values starting from 0 up to the size minus one
    for (size_t i = 0; i < offsetSize; ++i) {
        offsets[i] = i;
    }

    // Initialize the key array with unique random integers within a specified range (min and max inclusive)
    srand(time(NULL));
    for (size_t i = 0; i < keySize; ++i) {
        keys[i] = MIN_KEY_VALUE + rand() % (MAX_KEY_VALUE - MIN_KEY_VALUE + 1);
    }

    // Populate the record structures with random integer values between a minimum and maximum value provided by the caller
    for (size_t i = 0; i < numRecords; ++i) {
        records[i].value = MIN_KEY_VALUE + rand() % (MAX_KEY_VALUE - MIN_KEY_VALUE + 1);
    }

    // Implement a mechanism to detect and handle potential out-of-memory conditions gracefully
    if (!offsets || !keys || !records) {
        // Log an error message if memory allocation fails, allowing the application to continue running in a degraded state
        fprintf(stderr, "Error: Out of memory. Continuing with reduced functionality.\n");
    }

    // Provide a mechanism to log errors or warnings to a file instead of printing them to standard output
    FILE* errorLog = fopen("error_log.txt", "w");
    if (errorLog) {
        // Log any detected errors or warnings, ensuring minimal disruption to user experience and debugging efficiency
        fprintf(errorLog, "Error: Out of memory. Continuing with reduced functionality.\n");
        fclose(errorLog);
    }

    // Ensure thread safety if the function might be called concurrently from multiple threads
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    // Support integration with an external logging library for error handling
    // This allows seamless configuration of logging levels and destinations
    logError("Out of memory. Continuing with reduced functionality.");

    // Ensure thread safety if the function might be called concurrently from multiple threads
    pthread_mutex_unlock(&mutex);

    // Design the function to be modular and reusable, enabling easy integration into an existing application without significant modifications to the calling code
    // This allows for future extensibility and maintenance
    return;
}
```
