    }
}

// Define the function to integrate the list with an external data source for periodic synchronization
void nfapi_crc_sync(NFAPI_CRC_INDICATION_LIST_T* list, NFAPI_CRC_INDICATION_LIST_T* external_list) {
    // Iterate over all elements in the external list and update the corresponding elements in the local list
    for (size_t i = 0; i < external_list->size; ++i) {
