['```c
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <time.h>
#include <pthread.h>

// Structure to represent a network interface config
typedef struct NetworkInterfaceConfig {
    int interfaceId;
    NeighborCellInfo *neighborCellList;
    SRSParams srsParams;
} NetworkInterfaceConfig;

// Structure to represent neighbor cell info
typedef struct NeighborCellInfo {
    int neighborId;
    time_t lastModifiedTime;
} NeighborCellInfo;

// Structure to represent SRS parameters
typedef struct SRSParams {
    int srsBandwidth;
    int srsSubframeConfig;
    int srsPeriodicity;
} SRSParams;

// Global neighbor cell list
NeighborCellInfo *neighborCellList = NULL;

// Number of elements in the neighbor cell list
int numElements = 0;

// Lock for thread-safe access to the global neighbor cell list
pthread_mutex_t neighborCellListLock = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize a dynamic array of NetworkInterfaceConfig structures
void initNetworkInterfaceConfig(int numInterfaces, int minNeighborCellsPerInterface, int maxNeighborCellsPerInterface) {
    // Allocate memory for the network interface configs
    NetworkInterfaceConfig *networkInterfaceConfigs = (NetworkInterfaceConfig *)malloc(numInterfaces * sizeof(NetworkInterfaceConfig));

    // Initialize each network interface config
    for (int i = 0; i < numInterfaces; i++) {
        networkInterfaceConfigs[i].interfaceId = i;
        networkInterfaceConfigs[i].neighborCellList = NULL;
        networkInterfaceConfigs[i].srsParams = SRSParams();
    }

    // Populate the neighbor cell list for each interface
    for (int i = 0; i < numInterfaces; i++) {
        NetworkInterfaceConfig *interfaceConfig = &networkInterfaceConfigs[i];

        // Allocate memory for the neighbor cell list
        int numNeighborCells = minNeighborCellsPerInterface + rand() % (maxNeighborCellsPerInterface - minNeighborCellsPerInterface);
        interfaceConfig->neighborCellList = (NeighborCellInfo *)malloc(numNeighborCells * sizeof(NeighborCellInfo));

        // Initialize each neighbor cell
        for (int j = 0; j < numNeighborCells; j++) {
            NeighborCellInfo *neighborCell = &interfaceConfig->neighborCellList[j];
            neighborCell->neighborId = i + 10000 * j;
            neighborCell->lastModifiedTime = time(NULL);
        }
    }

    // Sort the neighbor cell list based on last modified time
    for (int i = 0; i < numInterfaces; i++) {
        NetworkInterfaceConfig *interfaceConfig = &networkInterfaceConfigs[i];
        qsort(interfaceConfig->neighborCellList, numNeighborCells, sizeof(NeighborCellInfo), compareLastModifiedTime);
    }

    // Log the changes in neighbor cell list size to a file for auditing purposes
    FILE *file = fopen("neighbor_cell_list.log", "a");
    if (file != NULL) {
        for (int i = 0; i < numInterfaces; i++) {
            NetworkInterfaceConfig *interfaceConfig = &networkInterfaceConfigs[i];
            int numNeighborCells = interfaceConfig->neighborCellList.length();
            fprintf(file, "Interface %d: neighbor cell list size changed from %d to %d\n", i, numElements, numNeighborCells);
        }
        fclose(file);
    }
}

// Function to update the neighbor cell list based on new data from the remote database
void updateNeighborCellList() {
    // Lock the neighbor cell list for thread-safe access
    pthread_mutex_lock(&neighborCellListLock);

    // Update the neighbor cell list with new data from the remote database
    for (int i = 0; i < numInterfaces; i++) {
        NetworkInterfaceConfig *interfaceConfig = &networkInterfaceConfigs[i];
        int numNeighborCells = interfaceConfig->neighborCellList.length();

        // Iterate through the neighbor cell list and update each entry with new data from the remote database
        for (int j = 0; j < numNeighborCells; j++) {
            NeighborCellInfo *neighborCell = &interfaceConfig->neighborCellList[j];
            int updatedNeighborId = updateNeighborId(neighborCell->neighborId);
            if (updatedNeighborId != neighborCell->neighborId) {
                neighborCell->neighborId = updatedNeighborId;
                neighborCell->lastModifiedTime = time(NULL);
            }
        }
    }

    // Unlock the neighbor cell list for thread-safe access
    pthread_mutex_unlock(&neighborCellListLock);
}

// Function to adjust the size of the neighbor cell list based on network conditions
void adjustNeighborCellListSize() {
    // Lock the neighbor cell list for thread-safe access
    pthread_mutex_lock(&neighborCellListLock);

    // Iterate through each interface and update the neighbor cell list size based on network conditions
    for (int i = 0; i < numInterfaces; i++) {
        NetworkInterfaceConfig *interfaceConfig = &networkInterfaceConfigs[i];
        int numNeighborCells = interfaceConfig->neighborCellList.length();

        // Determine the desired neighbor cell list size based on network conditions
        int desiredNeighborCellSize = minNeighborCellsPerInterface + rand() % (maxNeighborCellsPerInterface - minNeighborCellsPerInterface);

        // Adjust the neighbor cell list size if necessary
        if (desiredNeighborCellSize != numNeighborCells) {
            // Reallocate memory for the neighbor cell list with the new desired size
            NeighborCellInfo *newNeighborCellList = (NeighborCellInfo *)realloc(interfaceConfig->neighborCellList, desiredNeighborCellSize * sizeof(NeighborCellInfo));
            if (newNeighborCellList != NULL) {
                interfaceConfig->neighborCellList = newNeighborCellList;
            } else {
                // If reallocation fails, fall back to the previous neighbor cell list size
                desiredNeighborCellSize = numNeighborCells;
            }
        }
    }

    // Unlock the neighbor cell list for thread-safe access
    pthread_mutex_unlock(&neighborCellListLock);
}

// Function to compare two neighbor cell entries based on their last modified time
int compareLastModifiedTime(const void *a, const void *b) {
    const NeighborCellInfo *neighborCellA = (const NeighborCellInfo *)a;
    const NeighborCellInfo *neighborCellB = (const NeighborCellInfo *)b;
    return neighborCellA->lastModifiedTime - neighborCellB->lastModifiedTime;
}

// Function to update a neighbor cell entry with new data from the remote database
int updateNeighborId(int neighborId) {
    // Lock the neighbor cell list for thread-safe access
    pthread_mutex_lock(&neighborCellListLock);

    // Iterate through each interface and search for a matching neighbor cell entry
    for (int i = 0; i < numInterfaces; i++) {
        NetworkInterfaceConfig *interfaceConfig = &networkInterfaceConfigs[i];
        int numNeighborCells = interfaceConfig->neighborCellList.length();

        // Iterate through each neighbor cell entry and search for a matching neighbor id
        for (int j = 0; j < numNeighborCells; j++) {
            NeighborCellInfo *neighborCell = &interfaceConfig->neighborCellList[j];
            if (neighborCell->neighborId == neighborId) {
                // If a matching neighbor cell entry is found, update it with new data from the remote database
                int updatedNeighborId = rand() % 10000 + 1;
                neighborCell->neighborId = updatedNeighborId;
                neighborCell->lastModifiedTime = time(NULL);
                return updatedNeighborId;
            }
        }
    }

    // Unlock the neighbor cell list for thread-safe access
    pthread_mutex_unlock(&neighborCellListLock);
}
```

This code uses a vector to store the neighbor cells for each interface, and it sorts the neighbor cell list based on last modified time. The `updateNeighborId()` function is used to update a neighbor cell entry with new data from the remote database, and it returns the updated neighbor id. The `adjustNeighborCellListSize()` function is used to adjust the size of the neighbor cell list based on network conditions, and it reallocates memory for the neighbor cell list with the new desired size if necessary. The `compareLastModifiedTime()` function is used to compare two neighbor cell entries based on their last modified time.

