The use of a mutex to protect the shared data between worker threads is essential in this code, because multiple threads may access the same data simultaneously. By using a mutex, we ensure that only one thread can modify the shared data at a time, which prevents race conditions and ensures the correctness of the data.']

['Here is an example implementation of the C function to manage memory for a variable number of `record` structures:
```c
#include <stdlib.h>
#include <stdio.h>
#include <stdint.h>

// Structure definition for each record
typedef struct {
    int value;
    long offset;
    int key;
} Record;

// Global variables to keep track of memory usage and eviction policy
const int MAX_MEMORY_LIMIT = 100 * 1024 * 1024; // 100 MB
int current_memory_usage = 0;
Record* record_list = NULL;

// Function to allocate memory for a new record
void allocate_record(int value, long offset, int key) {
    if (current_memory_usage + sizeof(Record) > MAX_MEMORY_LIMIT) {
        // Evict least frequently accessed records to maintain performance under high load
        evict_records();
    }
    Record* new_record = malloc(sizeof(Record));
    if (new_record == NULL) {
        fprintf(stderr, "Failed to allocate memory for record\n");
        return;
    }
    current_memory_usage += sizeof(Record);
    new_record->value = value;
    new_record->offset = offset;
    new_record->key = key;
    record_list = realloc(record_list, (current_memory_usage / sizeof(Record)) * sizeof(Record));
    if (record_list == NULL) {
        fprintf(stderr, "Failed to reallocate memory for record list\n");
        return;
    }
    record_list[current_memory_usage / sizeof(Record)] = new_record;
}

// Function to free memory for an existing record
void free_record(int value) {
    Record* record = find_record(value);
    if (record == NULL) {
        fprintf(stderr, "Failed to find record with value %d\n", value);
        return;
    }
    current_memory_usage -= sizeof(Record);
    free(record);
}

// Function to evict least frequently accessed records
void evict_records() {
    // Select the least frequently accessed records to evict based on some heuristic
    // (e.g., LRU, MRU) and free their memory.
}

// Function to find a record in the list by value
Record* find_record(int value) {
    for (int i = 0; i < current_memory_usage / sizeof(Record); ++i) {
        if (record_list[i]->value == value) {
            return record_list[i];
        }
    }
    return NULL;
}

// Function to iterate over all records in the list
void iterate_records(void (*callback)(Record*)) {
    for (int i = 0; i < current_memory_usage / sizeof(Record); ++i) {
        callback(record_list[i]);
    }
