#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <inttypes.h>

// Define a structure to represent the configuration of a transport channel
typedef struct LTE_TRANSPORT_CHANNEL_CONFIG {
    uint8_t tci;
    uint16_t mcs;
} LTE_TRANSPORT_CHANNEL_CONFIG;

// Define a function to read and parse the configuration data from a file
LTE_TRANSPORT_CHANNEL_CONFIG* read_config(const char* filename) {
    // Open the file for reading
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening configuration file");
        return NULL;
    }

    // Allocate memory for an array of LTE_TRANSPORT_CHANNEL_CONFIG structures
    LTE_TRANSPORT_CHANNEL_CONFIG* configs = malloc(sizeof(LTE_TRANSPORT_CHANNEL_CONFIG) * 10);
    if (configs == NULL) {
        perror("Error allocating memory for configuration array");
        fclose(fp);
        return NULL;
    }

    // Read the file line by line and parse each line as a set of integers
    uint8_t index = 0;
    while (fscanf(fp, "%hhu %" PRIu16 "\n", &configs[index].tci, &configs[index].mcs) == 2) {
        // Increment the index and continue reading until the end of the file is reached
        ++index;
    }

    // Close the file and return the array of configuration structures
    fclose(fp);
    return configs;
}

// Define a function to find and print the largest integer in an array of integers
void print_largest_integer(int* arr, int size) {
    if (size == 0) {
        printf("No elements in the array\n");
        return;
    }

    int largest = arr[0];
    for (int i = 1; i < size; ++i) {
        if (arr[i] > largest) {
            largest = arr[i];
        }
    }
    printf("The largest integer in the array is %d\n", largest);
}

