    LTE_TRANSPORT_CHANNEL_CONFIG* configs = read_config(filename);
    if (configs == NULL) {
        return;
    }

    // Allocate memory for a dynamically sized array of NFAPI_CRC_INDICATION_PDU_T structures
    int num_channels = sizeof(configs) / sizeof(LTE_TRANSPORT_CHANNEL_CONFIG);
    NFAPI_CRC_INDICATION_PDU_T* crc_pdu = malloc(num_channels * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (crc_pdu == NULL) {
        perror("Error allocating memory for CRC indication PDU array");
        return;
    }

    // Initialize each structure in the array with the appropriate configuration data
    for (int i = 0; i < num_channels; ++i) {
        crc_pdu[i].tci = configs[i].tci;
        crc_pdu[i].mcs = configs[i].mcs;
    }

    // Free the configuration data array and return the CRC indication PDU array
    free(configs);
    return crc_pdu;
}

int main() {
