    LTE_TRANSPORT_CHANNEL_CONFIG* configs = read_config(filename);
    if (configs == NULL) {
        return 1;
    }

    // Find and print the largest integer in the configuration array
    int num_channels = sizeof(configs) / sizeof(LTE_TRANSPORT_CHANNEL_CONFIG);
    int* arr = malloc(num_channels * sizeof(int));
    for (int i = 0; i < num_channels; ++i) {
